async function loadDevicesFromDB() {
  try {
    const rows = await supabaseGet("devices?enabled=eq.true&order=id.asc&select=*");
    if (Array.isArray(rows) && rows.length > 0) {
      DEVICES = rows.map(r => ({ id: r.device_id, uid: r.uid, name: r.name, type: r.type||"relay", location: r.location||"", sensing_capable: r.sensing_capable||false }));
    } else {
      DEVICES = [
        { id: "device1", uid: "dev:868032061596023", name: "Unit 6023", type:"relay" },
      ];
    }
  } catch(e) {
    console.warn("Could not load devices from Supabase, using defaults:", e);
    DEVICES = [
      { id: "device1", uid: "dev:868032061596023", name: "Unit 6023", type:"relay" },
    ];
  }

  // Re-initialize relay state
  DEVICES.forEach(d => {
    if (!relayState[d.id]) relayState[d.id] = { 1:false, 2:false, 3:false, 4:false, all:false };
  });

  // Load all asset types and inject into DEVICES so they appear in groups at startup
  await loadAllAssetsIntoDevices();
}

async function loadAllAssetsIntoDevices() {
  // Load EV, battery, generator from localStorage + Supabase and inject into DEVICES
  // so they appear in group selectors and target dropdowns without opening their tabs first

  const safeGet = async (q, key, key2) => {
    let db = [], local = [];
    try { const r = await supabaseGet(q); if (Array.isArray(r)) db = r; } catch(e) {}
    try { const s = localStorage.getItem(key); if (s) local = JSON.parse(s); } catch(e) {}
    if (key2) { try { const s2 = localStorage.getItem(key2); if (s2) local = [...local, ...JSON.parse(s2)]; } catch(e) {} }
    const ids = new Set(db.map(r => r.station_id || r.asset_id));
    return [...db, ...local.filter(r => !(ids.has(r.station_id) || ids.has(r.asset_id)))];
  };

  const [evRows, battRows, genRows, thermRows] = await Promise.all([
    safeGet("ev_chargers?enabled=eq.true&order=enrolled_at.asc",       "lcp_ev_chargers_v1", "lcp_ev_dev_assets_v1"),
    safeGet("battery_assets?enabled=eq.true&order=enrolled_at.asc",    "lcp_battery_assets_v1"),
    safeGet("generator_assets?enabled=eq.true&order=enrolled_at.asc",  "lcp_generator_assets_v1"),
    safeGet("thermostat_assets?enabled=eq.true&order=enrolled_at.asc", "lcp_thermostat_assets_v1"),
  ]);

  // Populate global arrays used by existing inject functions
  if (!evChargers.length && evRows.length) {
    evChargers = evRows;
    if (typeof evDevAssets === "undefined") window.evDevAssets = evRows;
    else evDevAssets = evRows;
  }
  if (!batteryAssets.length && battRows.length) batteryAssets = battRows;
  if (!generatorAssets.length && genRows.length) generatorAssets = genRows;
  if (!thermostatAssets.length && thermRows.length) thermostatAssets = thermRows;

  // Inject into DEVICES directly using same pattern as inject functions
  DEVICES = DEVICES.filter(d => d.type === "relay" || !d.type);

  evRows.forEach(a => {
    const uid = `ev_${a.station_id||a.asset_id}`;
    DEVICES.push({ id:uid, uid, name:a.name, type:"ev", evAsset:a });
    if (!relayState[uid]) relayState[uid] = {1:false,2:false,3:false,4:false,all:false};
  });

  battRows.forEach(a => {
    const uid = `batt_${a.asset_id}`;
    const cfg = typeof a.integ_config === "string" ? (() => { try { return JSON.parse(a.integ_config); } catch(e) { return {}; } })() : (a.integ_config||{});
    DEVICES.push({ id:uid, uid, name:a.name, type:"battery", battAsset:{...a, integ_config:cfg} });
    if (!relayState[uid]) relayState[uid] = {1:false,2:false,3:false,4:false,all:false};
  });

  genRows.forEach(a => {
    const uid = `gen_${a.asset_id}`;
    const cfg = typeof a.integ_config === "string" ? (() => { try { return JSON.parse(a.integ_config); } catch(e) { return {}; } })() : (a.integ_config||{});
    DEVICES.push({ id:uid, uid, name:a.name, type:"generator", genAsset:{...a, integ_config:cfg} });
    if (!relayState[uid]) relayState[uid] = {1:false,2:false,3:false,4:false,all:false};
  });

  thermRows.forEach(a => {
    const uid = `therm_${a.asset_id}`;
    const cfg = typeof a.integ_config === "string" ? (() => { try { return JSON.parse(a.integ_config); } catch(e) { return {}; } })() : (a.integ_config||{});
    DEVICES.push({ id:uid, uid, name:a.name, type:"thermostat", thermAsset:{...a, integ_config:cfg} });
    if (!relayState[uid]) relayState[uid] = {1:false,2:false,3:false,4:false,all:false};
  });

  // Inject Pelican sites into DEVICES for group and target selectors
  if (typeof pelicanSites !== "undefined" && pelicanSites.length) {
    pelicanSites.forEach(s => {
      const uid = `pelican_${s.site_name}`;
      if (!DEVICES.find(d => d.id === uid)) {
        DEVICES.push({ id: uid, uid, name: s.display_name || s.site_name, type: "pelican", pelicanSite: s });
        if (!relayState[uid]) relayState[uid] = {1:false,2:false,3:false,4:false,all:false};
      }
    });
  }

  if (typeof refreshGroupSelectors === "function") refreshGroupSelectors();
  if (typeof populateTargetSelector === "function") populateTargetSelector();
}

function injectEVIntoDevices() {
  // Remove any previously injected EV devices to avoid duplicates
  DEVICES = DEVICES.filter(d => d.type !== "ev");
  // Add current EV assets
  if (typeof evDevAssets !== "undefined" && evDevAssets.length) {
    evDevAssets.forEach(a => {
      DEVICES.push({
        id:   `ev_${a.station_id}`,
        uid:  `ev_${a.station_id}`,
        name: a.name,
        type: "ev",
        evAsset: a
      });
      if (!relayState[`ev_${a.station_id}`]) {
        relayState[`ev_${a.station_id}`] = { 1:false, 2:false, 3:false, 4:false, all:false };
      }
    });
  }
}

