// ── Supabase ──────────────────────────────────────────────────────────────────
async function supabaseGet(query) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${query}`, {
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
  });
  return res.json();
}

// Paginated fetch — uses Range headers to bypass PostgREST's server-side
// default row cap (typically 1000). Fetches in pages of pageSize until either
// all rows are returned or the maxRows ceiling is hit.
async function supabaseGetPaged(query, maxRows = 20000, pageSize = 1000) {
  let allRows = [];
  let offset  = 0;
  while (true) {
    const rangeEnd = offset + pageSize - 1;
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${query}`, {
      headers: {
        "apikey":        SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Range":         `${offset}-${rangeEnd}`,
        "Range-Unit":    "items",
        "Prefer":        "count=none"
      }
    });
    // 416 = range not satisfiable (no more rows)
    if (res.status === 416) break;
    const page = await res.json();
    if (!Array.isArray(page) || page.length === 0) break;
    allRows = allRows.concat(page);
    // If we got fewer rows than the page size, we've reached the end
    if (page.length < pageSize) break;
    // If we've hit the caller's max ceiling, stop
    if (allRows.length >= maxRows) { allRows = allRows.slice(0, maxRows); break; }
    offset += pageSize;
  }
  return allRows;
}
async function supabasePost(table, data) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}`, {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify(data)
  });
  if (!res.ok) {
    const err = await res.text();
    console.error(`Supabase POST error (${table}):`, err, "Data:", JSON.stringify(data));
  }
  return res;
}
async function supabaseUpsert(table, data, onConflict) {
  return fetch(`${SUPABASE_URL}/rest/v1/${table}?on_conflict=${onConflict}`, {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "resolution=merge-duplicates,return=minimal" },
    body: JSON.stringify(data)
  });
}
async function supabaseDelete(table, filter) {
  return fetch(`${SUPABASE_URL}/rest/v1/${table}?${filter}`, {
    method: "DELETE",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
  });
}

async function supabasePatch(path, data) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    method: "PATCH",
    headers: {
      "apikey": SUPABASE_KEY,
      "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
      "Content-Type": "application/json",
      "Prefer": "return=minimal"
    },
    body: JSON.stringify(data)
  });
  if (!res.ok) {
    const err = await res.text();
    console.error(`Supabase PATCH error (${path}):`, err);
  }
  return res;
}

