let currentMain = 'summary';
let currentSub  = { events: 'scheduler', devices: 'data', admin: 'admin-users', monitor: 'monitor-triggers' };

function switchMain(main, btn) {
  document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
  currentMain = main;
  document.getElementById("sub-tabs-events").style.display  = main === "events"  ? "flex" : "none";
  document.getElementById("sub-tabs-devices").style.display = main === "devices" ? "flex" : "none";
  document.getElementById("sub-tabs-admin").style.display   = main === "admin"   ? "flex" : "none";
  document.getElementById("sub-tabs-monitor").style.display = main === "monitor" ? "flex" : "none";
  document.getElementById("sub-tabs-ami").style.display     = main === "ami"     ? "flex" : "none";
  if (main === "summary")  { activatePane("summary");          initSummaryTab();    }
  if (main === "programs") { activatePane("summary-programs"); loadSummaryPrograms(); }
  else if (main === "weather") { activatePane("weather"); initWeatherTab(); }
  else if (main === "admin")   { const s = currentSub.admin||"admin-users"; activatePane(s); activateSubBtn("admin",s); }
  else if (main === "events")  { const s = currentSub.events||"scheduler";  activatePane(s); activateSubBtn("events",s); }
  else if (main === "devices") { const s = currentSub.devices||"data"; activatePane(s); activateSubBtn("devices",s); }
  else if (main === "monitor") { const s = currentSub.monitor||"monitor-triggers"; activatePane(s); activateSubBtn("monitor",s); }
  else if (main === "vp")   { activatePane("vp"); initVPTab(); }
  else if (main === "lora") { activatePane("lora"); loraInit(); }
  else if (main === "ami")  { const s = currentSub.ami||"ami-ingest"; activatePane(s); activateSubBtn("ami",s); initAMITab(s); }
}

function switchSub(main, sub, btn) {
  currentSub[main] = sub;
  document.getElementById("sub-tabs-"+main).querySelectorAll(".sub-tab-btn").forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
  activatePane(sub);
}

function activatePane(name) {
  document.querySelectorAll(".tab-pane").forEach(p => p.classList.remove("active"));
  const el = document.getElementById("tab-"+name);
  if (el) el.classList.add("active");
  runTabInit(name);
}

function activateSubBtn(main, sub) {
  const bar = document.getElementById("sub-tabs-"+main);
  if (!bar) return;
  bar.querySelectorAll(".sub-tab-btn").forEach(b => b.classList.remove("active"));
  const btn = document.getElementById("sub-"+sub);
  if (btn) btn.classList.add("active");
}

