// ── Map ───────────────────────────────────────────────────────────────────────
function makeIcon(online) {
  const color = online ? "#1D9E75" : "#888780";
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="28" height="36" viewBox="0 0 28 36"><path d="M14 0C6.27 0 0 6.27 0 14c0 9.33 14 22 14 22s14-12.67 14-22C28 6.27 21.73 0 14 0z" fill="${color}"/><circle cx="14" cy="14" r="6" fill="white"/></svg>`;
  return L.divIcon({ html: svg, className: "", iconSize: [28,36], iconAnchor: [14,36], popupAnchor: [0,-36] });
}
// Online threshold: 4 hours — generous for cellular Notecards on varying bubble-up intervals
const ONLINE_THRESHOLD_MS = 24 * 60 * 60 * 1000; // 24h — matches Notecard periodic reporting

function isOnline(row) {
  if (!row) return false;
  return Date.now() - new Date(row.recorded_at).getTime() < ONLINE_THRESHOLD_MS;
}
async function loadMap() {
  if (!mapInitialized) {
    map = L.map("map").setView([39.5, -98.35], 4);
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", { attribution: '© <a href="https://openstreetmap.org">OpenStreetMap</a>' }).addTo(map);
    mapInitialized = true;
  }
  Object.values(mapMarkers).forEach(m => map.removeLayer(m));
  Object.keys(mapMarkers).forEach(k => delete mapMarkers[k]);
  const pinned = [];
  for (const device of DEVICES) {
    const rows = await supabaseGet(`device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`);
    const row = rows?.[0] ?? null;
    const online = isOnline(row);
    if (row?.lat && row?.lon) {
      const marker = L.marker([row.lat, row.lon], { icon: makeIcon(online) });
      marker.bindPopup(`<div style="font-family:-apple-system,sans-serif;min-width:150px;"><div style="font-weight:600;font-size:13px;margin-bottom:4px;">${device.name}</div><div style="font-size:11px;color:#5f5e5a;margin-bottom:6px;">${row.location ?? ""}</div><div style="display:flex;align-items:center;gap:5px;"><div style="width:7px;height:7px;border-radius:50%;background:${online?"#1D9E75":"#888780"}"></div><span style="font-size:11px;font-weight:500;color:${online?"#0F6E56":"#888780"}">${online?"Online":"No recent data"}</span></div><div style="font-size:10px;color:#888780;margin-top:4px;">Last seen: ${new Date(row.recorded_at).toLocaleString()}</div></div>`);
      marker.addTo(map);
      mapMarkers[device.uid] = marker;
      pinned.push(marker);
    }
  }
  if (pinned.length > 0) map.fitBounds(L.featureGroup(pinned).getBounds().pad(0.3));
  setTimeout(() => map.invalidateSize(), 100);
}

