// ── North American Timezones ──────────────────────────────────────────────────
const NA_TIMEZONES = [
  { label: "Eastern (ET) — UTC-5/4",     tz: "America/New_York" },
  { label: "Central (CT) — UTC-6/5",     tz: "America/Chicago" },
  { label: "Mountain (MT) — UTC-7/6",    tz: "America/Denver" },
  { label: "Mountain No DST (MST)",       tz: "America/Phoenix" },
  { label: "Pacific (PT) — UTC-8/7",     tz: "America/Los_Angeles" },
  { label: "Alaska (AKT) — UTC-9/8",     tz: "America/Anchorage" },
  { label: "Hawaii (HT) — UTC-10",       tz: "Pacific/Honolulu" },
  { label: "Atlantic (AT) — UTC-4/3",    tz: "America/Halifax" },
  { label: "Newfoundland (NT) — UTC-3:30", tz: "America/St_Johns" },
  { label: "Saskatchewan (CST)",          tz: "America/Regina" },
  { label: "Central Mexico (CST)",        tz: "America/Mexico_City" },
];

// Store timezone selections per device { device_id: tz_string }
const deviceTimezones = {};

// Detect timezone from lat/lon using corrected longitude bands
// Boundaries tuned for actual North American timezone regions
function guessTzFromCoords(lat, lon) {
  if (lat == null || lon == null) return "America/Chicago"; // default

  // Hawaii
  if (lon < -140) return "Pacific/Honolulu";

  // Alaska
  if (lon < -125 && lat > 54) return "America/Anchorage";

  // Pacific — west of Sierra Nevada
  if (lon < -114 && lat > 32) return "America/Los_Angeles";

  // Arizona (no DST) — roughly 31-37N, -109 to -114W
  if (lat >= 31 && lat <= 37 && lon >= -114 && lon <= -109) return "America/Phoenix";

  // Mountain — roughly -104 to -114W (excluding AZ)
  if (lon < -104) return "America/Denver";

  // Central — roughly -87 to -104W
  if (lon < -82) return "America/Chicago";

  // Eastern — roughly -67 to -87W
  if (lon < -52) return "America/New_York";

  // Atlantic (eastern Canada)
  if (lon < -42) return "America/Halifax";

  return "America/St_Johns";
}

function getCurrentTime(tz) {
  return new Date().toLocaleTimeString("en-US", { timeZone: tz, hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

function buildTzSelector(deviceId, selectedTz) {
  const opts = NA_TIMEZONES.map(t =>
    `<option value="${t.tz}" ${t.tz === selectedTz ? "selected" : ""}>${t.label}</option>`
  ).join("");
  return `<div class="tz-row">
    <span class="tz-label">TZ:</span>
    <select class="tz-select" id="tz-${deviceId}" onchange="onTzChange('${deviceId}')">
      ${opts}
    </select>
    <span class="tz-time" id="tz-time-${deviceId}">${getCurrentTime(selectedTz)}</span>
  </div>`;
}

function onTzChange(deviceId) {
  const sel = document.getElementById(`tz-${deviceId}`);
  deviceTimezones[deviceId] = sel.value;
  document.getElementById(`tz-time-${deviceId}`).textContent = getCurrentTime(sel.value);
}

// Update all timezone clocks every second
setInterval(() => {
  DEVICES.forEach(d => {
    const el = document.getElementById(`tz-time-${d.id}`);
    if (el && deviceTimezones[d.id]) {
      el.textContent = getCurrentTime(deviceTimezones[d.id]);
    }
  });
}, 1000);

// Auto-detect timezone from latest device location data
async function autoDetectTimezones() {
  for (const device of DEVICES) {
    try {
      const rows = await supabaseGet(`device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1&select=lat,lon`);
      const row = rows?.[0] ?? null;
      const tz = guessTzFromCoords(row?.lat, row?.lon);
      deviceTimezones[device.id] = tz;
      // Update selector if already rendered
      const sel = document.getElementById(`tz-${device.id}`);
      if (sel) sel.value = tz;
      const timeEl = document.getElementById(`tz-time-${device.id}`);
      if (timeEl) timeEl.textContent = getCurrentTime(tz);
    } catch(e) {
      deviceTimezones[device.id] = "America/Chicago";
    }
  }
}


// ── SCHEDULER ─────────────────────────────────────────────────────────────────
const RELAY_ACTION_LABELS = {
  all_on: "All Relays ON", all_off: "All Relays OFF",
  relay1_on: "Relay 1 ON", relay1_off: "Relay 1 OFF",
  relay2_on: "Relay 2 ON", relay2_off: "Relay 2 OFF",
  relay3_on: "Relay 3 ON", relay3_off: "Relay 3 OFF",
  relay4_on: "Relay 4 ON", relay4_off: "Relay 4 OFF",
};
const RELAY_OFF_MAP = {
  all_on: "all_off",
  relay1_on: "relay1_off",
  relay2_on: "relay2_off",
  relay3_on: "relay3_off",
  relay4_on: "relay4_off",
};
const DAY_NAMES = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
let schedulerInitialized = false;
let scheduleCheckInterval = null;

async function initScheduler() {
  if (!schedulerInitialized) {
    schedulerInitialized = true;
    console.log("Initializing scheduler for first time");
    await loadGroupNamesForScheduler();
    populateTzSelector();
    populateTargetSelector();
    updateSchedulerTimezone();
    await loadSchedules();
    await loadDeviceEvents();
    renderHexParser("hex-parser-panel");
    renderLCResponseParser("lcr-parser-panel");
    renderBubbleUpParser("bu-parser-panel");
    setTimeout(async () => { await prefillEventName(); }, 100);
    populateDRProgramSelector(); // populate program dropdown
  } else {
    await loadGroupNamesForScheduler();
    populateTargetSelector();
    updateSchedulerTimezone();
    await loadSchedules();
    await loadDeviceEvents();
    populateDRProgramSelector();
  }
}

async function getNextEventName() {
  try {
    const [schedRows, queueRows] = await Promise.all([
      supabaseGet("schedules?select=name&order=id.desc&limit=200").catch(()=>[]),
      supabaseGet("schedule_queue?select=name&order=id.desc&limit=200").catch(()=>[])
    ]);
    let maxNum = 0;
    [...(Array.isArray(schedRows) ? schedRows : []), ...(Array.isArray(queueRows) ? queueRows : [])].forEach(r => {
      if (!r.name) return;
      const match = r.name.match(/Event\s+(\d+)/i);
      if (match) {
        const num = parseInt(match[1]);
        if (num > maxNum) maxNum = num;
      }
    });
    return "Event " + String(maxNum + 1).padStart(5, "0");
  } catch(e) { return "Event 00001"; }
}

async function prefillEventName() {
  const nextName = await getNextEventName();
  const nameEl = document.getElementById("sf-name");
  if (nameEl) nameEl.value = nextName;
  const dateEl = document.getElementById("sf-date");
  if (dateEl && !dateEl.value) {
    dateEl.value = new Date().toISOString().split("T")[0];
  }
}

async function loadGroupNamesForScheduler() {
  try {
    const names = await supabaseGet("group_names?order=group_number");
    if (Array.isArray(names) && names.length) {
      names.forEach(n => {
        groupNames[n.group_number] = n.group_name;
        if (!groupTags) groupTags = {};
        groupTags[n.group_number]  = n.group_tag || "";
      });
      numGroups = names.length;
    }
    const assignments = await supabaseGet("device_groups?order=group_number");
    groupAssignments = {};
    if (Array.isArray(assignments)) {
      assignments.forEach(a => {
        if (!groupAssignments[a.device_uid]) groupAssignments[a.device_uid] = [];
        groupAssignments[a.device_uid].push(a.group_number);
      });
    }
  } catch(e) { console.error("Error loading groups for scheduler", e); }
}

function getBrowserTz() {
  // Get the browser/computer's current timezone
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone;
  } catch(e) {
    return "America/Chicago";
  }
}

function populateTzSelector() {
  const sel = document.getElementById("sf-timezone");
  if (!sel) return;
  const browserTz = getBrowserTz();
  // Find best match in our NA_TIMEZONES list
  const match = NA_TIMEZONES.find(t => t.tz === browserTz);
  const defaultTz = match ? browserTz : "America/Chicago";
  const defaultLabel = match ? match.label : "Central (CT) — UTC-6/5";

  sel.innerHTML = NA_TIMEZONES.map(t => {
    const isDefault = t.tz === defaultTz;
    return `<option value="${t.tz}" ${isDefault ? "selected" : ""}>${t.label}${isDefault ? " ★ Default" : ""}</option>`;
  }).join("");
}

function populateTargetSelector() {
  const type = document.getElementById("sf-target-type")?.value;
  const sel  = document.getElementById("sf-target");
  if (!type || !sel) return;
  const placeholder = `<option value="" disabled selected>— Choose One —</option>`;

  if (type === "group") {
    // Show group number, name, and tag if set
    sel.innerHTML = placeholder + Object.keys(groupNames).map(Number).sort((a,b)=>a-b).map(n => {
      const name = groupNames[n] || `Group ${n}`;
      const tag  = groupTags?.[n] ? ` — ${groupTags[n]}` : "";
      return `<option value="group_${n}">Group ${n}: ${name}${tag}</option>`;
    }).join("");
  } else {
    // Separate relay devices from EV chargers with optgroups
    const relayDevs = DEVICES.filter(d => d.type !== "ev" && !d.uid.includes("PLACEHOLDER"));
    const evDevs    = DEVICES.filter(d => d.type === "ev");
    let html = placeholder;
    if (relayDevs.length) {
      html += `<optgroup label="Relay Devices">` +
        relayDevs.map(d => `<option value="${d.uid}">${d.name}</option>`).join("") +
        `</optgroup>`;
    }
    if (evDevs.length) {
      html += `<optgroup label="EV Chargers">` +
        evDevs.map(d => `<option value="${d.uid}">⚡ ${d.name}</option>`).join("") +
        `</optgroup>`;
    }
    const battDevs = DEVICES.filter(d => d.type === "battery");
    if (battDevs.length) {
      html += `<optgroup label="Battery Systems">` +
        battDevs.map(d => `<option value="${d.uid}">🔋 ${d.name}</option>`).join("") +
        `</optgroup>`;
    }
    const genDevs = DEVICES.filter(d => d.type === "generator");
    if (genDevs.length) {
      html += `<optgroup label="Generators">` +
        genDevs.map(d => `<option value="${d.uid}">⚡ ${d.name}</option>`).join("") +
        `</optgroup>`;
    }
    const thermDevs = DEVICES.filter(d => d.type === "thermostat");
    if (thermDevs.length) {
      html += `<optgroup label="Thermostats">` +
        thermDevs.map(d => `<option value="${d.uid}">🌡️ ${d.name}</option>`).join("") +
        `</optgroup>`;
    }
    sel.innerHTML = html;
  }
  sel.value = ""; // ensure placeholder is shown
}

// onTargetTypeChange merged below with BAS context support

function getGroupMostCommonTz(groupNum) {
  const members = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(groupNum));
  if (members.length === 0) return "America/Chicago";
  const tzCounts = {};
  members.forEach(d => {
    const tz = deviceTimezones[d.id] || "America/Chicago";
    tzCounts[tz] = (tzCounts[tz] || 0) + 1;
  });
  return Object.entries(tzCounts).sort((a,b) => b[1]-a[1])[0][0];
}

function updateSchedulerTimezone() {
  const type = document.getElementById("sf-target-type").value;
  const targetSel = document.getElementById("sf-target");
  const tzSel = document.getElementById("sf-timezone");
  if (!tzSel || !targetSel || targetSel.options.length === 0) return;
  const targetVal = targetSel.value;
  if (!targetVal) return;
  let tz = getBrowserTz();
  if (type === "device") {
    const device = DEVICES.find(d => d.uid === targetVal);
    if (device && deviceTimezones[device.id]) tz = deviceTimezones[device.id];
  } else {
    const gNum = parseInt(targetVal.replace("group_", ""));
    if (gNum) tz = getGroupMostCommonTz(gNum);
  }
  // Rebuild options with new default marked
  const browserTz = getBrowserTz();
  tzSel.innerHTML = NA_TIMEZONES.map(t => {
    const isSelected = t.tz === tz;
    const isBrowser = t.tz === browserTz;
    let suffix = "";
    if (isSelected && isBrowser) suffix = " ★ Default";
    else if (isSelected) suffix = " ★ Selected";
    else if (isBrowser) suffix = " (your device)";
    return `<option value="${t.tz}" ${isSelected ? "selected" : ""}>${t.label}${suffix}</option>`;
  }).join("");
}



function onStrategyChange() {
  updateRepsDisplay();
  updateSFLCPreview();
}

function updateRepsDisplay() {
  const stratSel = document.getElementById("sf-strategy");
  const durSel   = document.getElementById("sf-duration");
  const repsEl   = document.getElementById("sf-reps-display");
  if (!stratSel || !durSel || !repsEl) return;
  const stratVal = stratSel.value;
  const durVal   = parseFloat(durSel.value);
  if (!stratVal || !durVal) {
    repsEl.value = ""; return;
  }
  const [stratNum, timeout, cycleTime] = stratVal.split("|").map(Number);
  const reps = Math.max(1, Math.round(durVal / cycleTime));
  repsEl.value = `${reps} repetition(s)  (${durVal} min ÷ ${cycleTime} min cycle)`;
}





// ── Schedule Confirmation Modal ──────────────────────────────────────────────

function showSchedConfirm() {
  const getVal = (id) => { const el = document.getElementById(id); return el ? el.value : ""; };
  const name           = getVal("sf-name").trim();
  const hour           = getVal("sf-hour");
  const minute         = getVal("sf-minute");
  const tz             = getVal("sf-timezone");
  const event_date     = getVal("sf-date") || null;
  const duration_minutes = parseFloat(getVal("sf-duration")) || null;
  const eventType      = sfEventType;

  if (!name)             { setStatus("error", "Please enter an event name."); return; }
  if (!eventType)        { setStatus("error", "Please select an event type."); return; }
  if (!event_date)       { setStatus("error", "Please select a date."); return; }
  if (!hour || !minute)  { setStatus("error", "Please select a time."); return; }
  if (!duration_minutes) { setStatus("error", "Please select an event duration."); return; }

  // Type-specific validation & summary info
  let targetName = "—", actionSummary = "—", type = "device", targetVal = "";
  const action = getVal("sf-action") || "all_on";
  const mode   = getVal("sf-mode")   || "dlc";
  let stratVal = getVal("sf-strategy");

  if (eventType === "switch") {
    type      = getVal("sf-target-type");
    targetVal = getVal("sf-target");
    if (!type)      { setStatus("error", "Please select a target type."); return; }
    if (!targetVal) { setStatus("error", "Please select a target."); return; }
    const isHybrid = document.getElementById("sf-switch-mode")?.value === "hybrid";
    if (isHybrid) {
      const { dlcRelays, basRelays } = getHybridConfig();
      if (!dlcRelays.length && !basRelays.length) { setStatus("error", "Select at least one relay to participate."); return; }
      stratVal      = "hybrid"; // sentinel
      actionSummary = `Hybrid — ${dlcRelays.length} DLC, ${basRelays.length} BAS relay${(dlcRelays.length+basRelays.length)!==1?"s":""}`;
    } else {
      if (!stratVal)  { setStatus("error", "Please select a shed level."); return; }
      const shed    = Object.entries(SHED_LEVEL_MAP).find(([,v])=>v.strategy===stratVal||stratVal.startsWith(v.strategy.split("|")[0]));
      actionSummary = shed ? shed[1].label : `Strategy ${stratVal}`;
    }
    targetName    = type === "group"
      ? (groupNames[parseInt(targetVal.replace("group_",""))] || targetVal)
      : unitName(targetVal);

  } else if (eventType === "bas_di") {
    const basType = getVal("sf-bas-target-type");
    targetVal     = getVal("sf-bas-target");
    stratVal      = getVal("sf-bas-strategy") || stratVal;
    type          = basType || "device";
    if (!targetVal) { setStatus("error", "Please select a BAS target."); return; }
    if (!stratVal)  { setStatus("error", "Please select a BAS setpoint."); return; }
    targetName    = targetVal;
    actionSummary = `BAS Mode — Strategy ${stratVal.split("|")[0]}`;

  } else if (eventType === "ev") {
    type          = getVal("sf-ev-target-type");
    targetVal     = getVal("sf-ev-target");
    const evPct   = getVal("sf-ev-shed-pct");
    if (!type)      { setStatus("error", "Please select a target type."); return; }
    if (!targetVal) { setStatus("error", "Please select an EV target."); return; }
    if (evPct === "") { setStatus("error", "Please select a charge rate limit."); return; }
    targetName    = type === "group" ? (groupNames[parseInt(targetVal.replace("group_",""))] || targetVal) : (unitName(targetVal) || targetVal);
    actionSummary = document.querySelector(`#sf-ev-shed-pct option[value="${evPct}"]`)?.text || `${evPct}%`;
    stratVal      = "ev_shed";

  } else if (eventType === "battery") {
    type          = getVal("sf-batt-target-type");
    targetVal     = getVal("sf-batt-target");
    const battAct = getVal("sf-batt-action");
    if (!type)      { setStatus("error", "Please select a target type."); return; }
    if (!targetVal) { setStatus("error", "Please select a battery target."); return; }
    if (!battAct)   { setStatus("error", "Please select a battery action."); return; }
    targetName    = type === "group" ? (groupNames[parseInt(targetVal.replace("group_",""))] || targetVal) : (unitName(targetVal) || targetVal);
    actionSummary = document.querySelector(`#sf-batt-action option[value="${battAct}"]`)?.text || battAct;
    stratVal      = "batt_action";

  } else if (eventType === "generator") {
    type          = getVal("sf-gen-target-type");
    targetVal     = getVal("sf-gen-target");
    const genAct  = getVal("sf-gen-action");
    if (!type)      { setStatus("error", "Please select a target type."); return; }
    if (!targetVal) { setStatus("error", "Please select a generator target."); return; }
    if (!genAct)    { setStatus("error", "Please select a generator action."); return; }
    targetName    = type === "group" ? (groupNames[parseInt(targetVal.replace("group_",""))] || targetVal) : (unitName(targetVal) || targetVal);
    actionSummary = document.querySelector(`#sf-gen-action option[value="${genAct}"]`)?.text || genAct;
    stratVal      = "gen_action";

  } else if (eventType === "thermostat") {
    type          = getVal("sf-therm-target-type");
    targetVal     = getVal("sf-therm-target");
    const thermAct = getVal("sf-therm-action");
    if (!type)       { setStatus("error", "Please select a target type."); return; }
    if (!targetVal)  { setStatus("error", "Please select a thermostat target."); return; }
    if (!thermAct)   { setStatus("error", "Please select a setback level."); return; }
    targetName    = type === "group" ? (groupNames[parseInt(targetVal.replace("group_",""))] || targetVal) : (unitName(targetVal) || targetVal);
    actionSummary = document.querySelector(`#sf-therm-action option[value="${thermAct}"]`)?.text || thermAct;
    stratVal      = "therm_setback";

  } else if (eventType === "openadr") {
    const oadrLevel = getVal("sf-oadr-level");
    actionSummary   = `OpenADR SIMPLE level ${oadrLevel}`;
    targetName      = "VEN (configured)";
    targetVal       = "openadr_ven";
    stratVal        = "oadr_event"; // sentinel
  }

  // Resolve human-readable labels from select option text
  const time = (hour !== "" && minute !== "") ? `${hour}:${minute}` : "";
  const tzLabel = document.querySelector(`#sf-timezone option[value="${tz}"]`)?.text || tz;

  // Format scheduled date/time
  const [yr, mo, dy] = (event_date || "").split("-").map(Number);
  const h = parseInt(hour), m = parseInt(minute);
  const ampm = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 || 12;
  const dateLabel = event_date
    ? `${mo}/${dy}/${yr} at ${h12}:${String(minute).padStart(2,"0")} ${ampm}`
    : "—";

  // Duration label
  const durH = Math.floor(duration_minutes / 60);
  const durM = duration_minutes % 60;
  const durLabel = durH > 0 ? (durM > 0 ? `${durH}h ${durM}m` : `${durH}h`) : `${durM}m`;

  // LC hex (only for switch/relay events)
  let lcHex = "—", repsLabel = "—", schedUnix = null;
  const isLCEvent = eventType === "switch" || eventType === "bas_di";
  if (isLCEvent && stratVal && !["ev_shed","batt_action","gen_action","oadr_event","hybrid"].includes(stratVal)) {
    const [stratNum,, stratCycle] = stratVal.split("|").map(Number);
    const reps = duration_minutes && stratCycle ? Math.max(1, Math.round(duration_minutes / stratCycle)) : 1;
    schedUnix = getScheduleUnixTime(event_date, time, tz);
    lcHex    = buildLCHex(action, mode, stratNum, reps, schedUnix) || "—";
    repsLabel = `${reps} rep${reps!==1?"s":""} (${duration_minutes}m ÷ ${stratCycle}m cycle)`;
  } else {
    schedUnix = getScheduleUnixTime(event_date, time, tz);
  }

  // Populate modal fields
  const setText = (id, val) => { const el=document.getElementById(id); if(el) el.textContent=val; };
  setText("sc-name",        name);
  setText("sc-target",      targetName);
  setText("sc-target-type", eventType.toUpperCase().replace("_"," "));
  setText("sc-datetime",    dateLabel);
  setText("sc-timezone",    tzLabel);
  setText("sc-duration",    durLabel);
  setText("sc-action",      actionSummary);
  setText("sc-mode",        mode);
  setText("sc-strategy",    isLCEvent ? stratVal : "—");
  setText("sc-reps",        repsLabel);
  setText("sc-hex",         lcHex);

  // Warning if event is in the past
  const warnEl = document.getElementById("sc-warning");
  if (schedUnix && schedUnix < Math.floor(Date.now() / 1000)) {
    warnEl.textContent = "⚠️ The scheduled time appears to be in the past. The device may execute this event immediately upon receipt.";
    warnEl.style.display = "block";
  } else {
    warnEl.style.display = "none";
  }

  document.getElementById("sched-confirm-modal").classList.add("active");
}

function closeSchedConfirm(e) {
  if (e && e.target !== document.getElementById("sched-confirm-modal")) return;
  document.getElementById("sched-confirm-modal").classList.remove("active");
}

async function confirmAndSave() {
  const btn = document.getElementById("sc-confirm-btn");
  btn.disabled = true;
  btn.textContent = "Sending…";
  document.getElementById("sched-confirm-modal").classList.remove("active");
  await _executeCreateSchedule();
  btn.disabled = false;
  btn.textContent = "✓ Confirm & Send to Device";
}

async function createSchedule() {
  // Legacy direct call kept for backward compatibility — routes through confirmation
  await showSchedConfirm();
}

async function _executeCreateSchedule() {
  const getVal = (id) => { const el = document.getElementById(id); return el ? el.value : ""; };
  const name     = getVal("sf-name").trim();
  const hour     = getVal("sf-hour");
  const minute   = getVal("sf-minute");
  const time     = (hour !== "" && minute !== "") ? `${hour}:${minute}` : "";
  const tz       = getVal("sf-timezone");
  const event_date = getVal("sf-date") || null;
  const duration_minutes = parseFloat(getVal("sf-duration")) || null;
  const evType   = sfEventType || "switch";

  if (!name)             { setStatus("error", "Please enter an event name."); return; }
  if (!event_date)       { setStatus("error", "Please select a date."); return; }
  if (!hour || !minute)  { setStatus("error", "Please select a time."); return; }
  if (!duration_minutes) { setStatus("error", "Please select an event duration."); return; }

  const schedUnix = getScheduleUnixTime(event_date, time, tz);
  setStatus("sending", "Dispatching event…");

  // ── EV Charger ─────────────────────────────────────────────────────────────
  if (evType === "ev") {
    const evTargetType = getVal("sf-ev-target-type");
    const evTarget     = getVal("sf-ev-target");
    const evPct        = parseFloat(getVal("sf-ev-shed-pct"));
    if (!evTarget)     { setStatus("error", "Please select an EV target."); return; }
    if (isNaN(evPct))  { setStatus("error", "Please select a charge rate limit."); return; }
    const targets = evTargetType === "group"
      ? DEVICES.filter(d => d.type==="ev" && (groupAssignments[d.uid]||[]).includes(parseInt(evTarget.replace("group_",""))))
      : [DEVICES.find(d => d.uid === evTarget)].filter(Boolean);
    for (const d of targets) {
      const sid = d.uid.replace("ev_","");
      if (evPct === 100) await restoreEVSingle(sid);
      else               await dispatchEVDRSingle(sid, evPct/100);
    }
    await supabasePost("schedule_queue", {
      name, fire_at:new Date(schedUnix*1000).toISOString(),
      target_type:evTargetType, target_id:evTarget, target_name:unitName(evTarget)||evTarget,
      relay_action:"ev_shed", duration_minutes, timezone:tz, action_time:time, one_time:true,
      status:"sent", fired_at:new Date().toISOString(), event_type:"ev"
    });
    setStatus("ready", `"${name}" EV event dispatched.`);
    await loadSchedules(); return;
  }

  // ── Battery Backup ──────────────────────────────────────────────────────────
  if (evType === "battery") {
    const battTargetType = getVal("sf-batt-target-type");
    const battTarget     = getVal("sf-batt-target");
    const battAct        = getVal("sf-batt-action");
    if (!battTarget) { setStatus("error", "Please select a battery target."); return; }
    if (!battAct)    { setStatus("error", "Please select a battery action."); return; }
    const targets = battTargetType === "group"
      ? DEVICES.filter(d => d.type==="battery" && (groupAssignments[d.uid]||[]).includes(parseInt(battTarget.replace("group_",""))))
      : [DEVICES.find(d => d.uid === battTarget)].filter(Boolean);
    for (const d of targets) {
      const aid = d.uid.replace("batt_","");
      if (battAct === "restore") await restoreBatterySingle(aid);
      else                       await dispatchBatteryDRSingle(aid, battAct);
    }
    await supabasePost("schedule_queue", {
      name, fire_at:new Date(schedUnix*1000).toISOString(),
      target_type:battTargetType, target_id:battTarget, target_name:unitName(battTarget)||battTarget,
      relay_action:battAct, duration_minutes, timezone:tz, action_time:time, one_time:true,
      status:"sent", fired_at:new Date().toISOString(), event_type:"battery"
    });
    setStatus("ready", `"${name}" battery event dispatched.`);
    await loadSchedules(); return;
  }

  // ── Generator ───────────────────────────────────────────────────────────────
  if (evType === "generator") {
    const genTargetType = getVal("sf-gen-target-type");
    const genTarget     = getVal("sf-gen-target");
    const genAct        = getVal("sf-gen-action");
    if (!genTarget) { setStatus("error", "Please select a generator target."); return; }
    if (!genAct)    { setStatus("error", "Please select a generator action."); return; }
    const targets = genTargetType === "group"
      ? DEVICES.filter(d => d.type==="generator" && (groupAssignments[d.uid]||[]).includes(parseInt(genTarget.replace("group_",""))))
      : [DEVICES.find(d => d.uid === genTarget)].filter(Boolean);
    for (const d of targets) {
      const aid = d.uid.replace("gen_","");
      if (genAct === "stop") await stopGeneratorSingle(aid);
      else                   await startGeneratorSingle(aid, genAct === "test");
    }
    await supabasePost("schedule_queue", {
      name, fire_at:new Date(schedUnix*1000).toISOString(),
      target_type:genTargetType, target_id:genTarget, target_name:unitName(genTarget)||genTarget,
      relay_action:genAct, duration_minutes, timezone:tz, action_time:time, one_time:true,
      status:"sent", fired_at:new Date().toISOString(), event_type:"generator"
    });
    setStatus("ready", `"${name}" generator event dispatched.`);
    await loadSchedules(); return;
  }

  // ── Thermostat ──────────────────────────────────────────────────────────────
  if (evType === "thermostat") {
    const thermTargetType = getVal("sf-therm-target-type");
    const thermTarget     = getVal("sf-therm-target");
    const thermAct        = getVal("sf-therm-action");
    if (!thermTarget) { setStatus("error", "Please select a thermostat target."); return; }
    if (!thermAct)    { setStatus("error", "Please select a setback level."); return; }
    const targets = thermTargetType === "group"
      ? DEVICES.filter(d => d.type==="thermostat" && (groupAssignments[d.uid]||[]).includes(parseInt(thermTarget.replace("group_",""))))
      : [DEVICES.find(d => d.uid === thermTarget)].filter(Boolean);
    for (const d of targets) {
      const aid = d.uid.replace("therm_","");
      if (thermAct === "restore") await restoreThermostatSingle(aid);
      else                        await dispatchThermostatDRSingle(aid, thermAct);
    }
    await supabasePost("schedule_queue", {
      name, fire_at:new Date(schedUnix*1000).toISOString(),
      target_type:thermTargetType, target_id:thermTarget, target_name:unitName(thermTarget)||thermTarget,
      relay_action:thermAct, duration_minutes, timezone:tz, action_time:time, one_time:true,
      status:"sent", fired_at:new Date().toISOString(), event_type:"thermostat"
    });
    setStatus("ready", `"${name}" thermostat event dispatched.`);
    await loadSchedules(); return;
  }

  // ── OpenADR ─────────────────────────────────────────────────────────────────
  if (evType === "openadr") {
    const oadrLevel = parseInt(getVal("sf-oadr-level") || "1");
    const oadrSig   = getVal("sf-oadr-signal-type") || "SIMPLE";
    const evId      = getVal("sf-oadr-event-id") || `EVT-${Date.now()}`;
    try {
      const res = await fetch(PROXY_URL + "openadr/event", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          event_id:evId, signal_type:oadrSig,
          signal_level:oadrLevel, duration_minutes
        })
      });
      const data = await res.json();
      setStatus(data.ok ? "ready" : "error", data.ok ? `"${name}" OpenADR event sent.` : "OpenADR dispatch failed.");
    } catch(e) { setStatus("error", "OpenADR error: " + e.message); }
    await loadSchedules(); return;
  }

  // ── Hybrid Switch ─────────────────────────────────────────────────────────
  if (evType === "switch" && document.getElementById("sf-switch-mode")?.value === "hybrid") {
    const type      = getVal("sf-target-type");
    const targetVal = getVal("sf-target");
    if (!type)      { setStatus("error", "Please select a target type."); return; }
    if (!targetVal) { setStatus("error", "Please select a target."); return; }
    const { dlcRelays, basRelays } = getHybridConfig();
    if (!dlcRelays.length && !basRelays.length) { setStatus("error", "Configure at least one relay."); return; }
    setStatus("sending", "Sending hybrid event…");
    const schedUnix = getScheduleUnixTime(event_date, time, tz);
    // Send DLC commands
    for (const rel of dlcRelays) {
      const [stratNum,,stratCycle] = rel.stratVal.split("|").map(Number);
      const reps = duration_minutes && stratCycle ? Math.max(1, Math.round(duration_minutes/stratCycle)) : 1;
      const hex  = buildLCHex(rel.action, "dlc", stratNum, reps, schedUnix);
      await sendLCToDevice(targetVal, hex);
    }
    // Send BAS commands
    for (const rel of basRelays) {
      const [stratNum,,stratCycle] = rel.stratVal.split("|").map(Number);
      const reps = duration_minutes && stratCycle ? Math.max(1, Math.round(duration_minutes/stratCycle)) : 1;
      const hex  = buildLCHex(rel.action, "di", stratNum, reps, schedUnix);
      await sendLCToDevice(targetVal, hex);
    }
    await supabasePost("schedule_queue", {
      name, fire_at: new Date(schedUnix*1000).toISOString(),
      target_type:type, target_id:targetVal,
      target_name: unitName(targetVal),
      relay_action: "hybrid",
      duration_minutes, timezone:tz, action_time:time,
      one_time:true, status:"sent", fired_at:new Date().toISOString(),
      event_type:"hybrid"
    });
    setStatus("ready", `"${name}" hybrid event dispatched.`);
    await loadSchedules(); return;
  }

  // ── Switch / Relay / BAS Mode ─────────────────────────────────────────────
  const type     = evType === "bas_di" ? getVal("sf-bas-target-type") : getVal("sf-target-type");
  const targetVal= evType === "bas_di" ? getVal("sf-bas-target")      : getVal("sf-target");
  const action   = getVal("sf-action") || "all_on";
  const mode     = getVal("sf-mode")   || (evType === "bas_di" ? "di" : "dlc");
  const stratVal = evType === "bas_di" ? (getVal("sf-bas-strategy")||getVal("sf-strategy")) : getVal("sf-strategy");

  if (!type)      { setStatus("error", "Please select a target type."); return; }
  if (!targetVal) { setStatus("error", "Please select a target."); return; }
  if (!stratVal && evType !== "hybrid")  { setStatus("error", "Please select a shed level."); return; }

  const [stratNum, stratTimeout, stratCycle] = stratVal.split("|").map(Number);
  const reps = duration_minutes && stratCycle
    ? Math.max(1, Math.round(duration_minutes / stratCycle)) : 1;

  let targetName = type === "group"
    ? (groupNames[parseInt(targetVal.replace("group_",""))] || targetVal)
    : unitName(targetVal);

  const schedule = {
    name, enabled: true,
    target_type: type, target_id: targetVal, target_name: targetName,
    frequency: "one_time", days_of_week: null,
    action_time: time, event_date: event_date || null, timezone: tz,
    relay_action: action, duration_minutes, one_time: true,
    lc_mode: mode, lc_strategy: stratNum, lc_timeout: stratTimeout,
    lc_cycle: stratCycle, lc_reps: reps,
    event_type: evType
  };

  const res = await supabasePost("schedules", schedule);
  if (res.ok) {
    const lcHex = buildLCHex(action, mode, stratNum, reps, schedUnix);
    const lastEventId = lcEventId > 1 ? lcEventId - 1 : 254;

    if (type === "group") {
      const gNum = parseInt(targetVal.replace("group_",""));
      const members = DEVICES.filter(d => (groupAssignments[d.uid]||[]).includes(gNum));
      for (const device of members) await sendLCToDevice(device.uid, lcHex);
    } else {
      await sendLCToDevice(targetVal, lcHex);
    }

    await supabasePost("schedule_queue", {
      schedule_id:null, name,
      fire_at: new Date(schedUnix*1000).toISOString(),
      target_type:type, target_id:targetVal, target_name:targetName,
      relay_action:action, duration_minutes, timezone:tz, action_time:time,
      lc_mode:mode, lc_strategy:stratNum, lc_timeout:stratTimeout||null,
      lc_cycle:stratCycle||null, lc_reps:reps, lc_event_id:lastEventId,
      one_time:true, status:"sent", fired_at:new Date().toISOString(),
      event_type:evType
    });

    setStatus("ready", `"${name}" saved & sent to device.`);
    const nextName = await getNextEventName();
    document.getElementById("sf-name").value = nextName;
    await loadSchedules();
    await loadDeviceEvents();
  } else {
    setStatus("error", "Error saving schedule.");
  }
}




async function loadSchedules() {
  const list = document.getElementById("sched-list");
  if (!list) return;
  list.innerHTML = `<div class="sched-empty">Loading...</div>`;
  const range = document.getElementById("sched-range")?.value;

  // Build query against schedule_queue for full event history
  let query = "schedule_queue?order=fire_at.desc&limit=200";
  if (range === "future") {
    // Show events from now forward plus active events — exclude cancelled and ended
    const since = new Date(Date.now() - 24*60*60*1000).toISOString();
    query = `schedule_queue?order=fire_at.asc&limit=200&fire_at=gte.${since}&status=not.in.(cancelled,ended,rejected)`;
  } else if (range) {
    const since = new Date(Date.now() - parseInt(range)*60*60*1000).toISOString();
    query += `&fire_at=gte.${since}`;
  }

  const rows = await supabaseGet(query);
  if (!rows || rows.length === 0) {
    list.innerHTML = `<div class="sched-empty">No events found for selected range.</div>`;
    return;
  }

  const statusColors = {
    sent:"var(--blue-dark)", received:"var(--green-dark)", started:"#166534",
    ended:"var(--text-secondary)", cancelled:"var(--text-hint)", pending:"var(--amber)"
  };

  list.innerHTML = rows.map(s => {
    const fireStr = s.fire_at ? new Date(s.fire_at).toLocaleString() : "—";
    const dur     = s.duration_minutes ? formatDuration(s.duration_minutes) : "—";
    const sc      = statusColors[s.status] || "var(--text-secondary)";
    const isCancellable = ["sent","received","started","pending","fired"].includes(s.status);
    const displayName = s.name || s.target_name || `Queue #${s.id}`;
    const evType  = s.event_type || "switch";

    // Event type badge
    const typeIcons = { switch:"⚡", bas_di:"🏢", ev:"🔌", battery:"🔋", generator:"⚙️", openadr:"📡", hybrid:"🔀" };
    const typeIcon  = typeIcons[evType] || "📋";

    const cancelBtn = isCancellable
      ? `<button class="sched-delete-btn" style="color:var(--red);white-space:nowrap;"
           onclick="event.stopPropagation();cancelScheduledEvent(${s.id})">
           ✕ Cancel &amp; Restore
         </button>`
      : `<span style="font-size:10px;color:var(--text-hint);">${s.status}</span>`;

    const optOutBtn = `<button class="sched-delete-btn" style="color:var(--amber);border-color:var(--amber);white-space:nowrap;"
      onclick="event.stopPropagation();openOptOutForEvent('${(s.name||'').replace(/'/g,"\\'")}','${(s.fire_at||'').replace(/'/g,"\\'")}')">
      🚫 Opt-Out Device
    </button>`;

    const rowData = encodeURIComponent(JSON.stringify({ type:"queue", item:s }));

    return `<div class="sched-item" style="cursor:pointer;" onclick="showEventDetail(JSON.parse(decodeURIComponent('${rowData}')))">
      <div class="sched-info">
        <div class="sched-name">
          <span style="margin-right:5px;">${typeIcon}</span>${displayName}
          <span style="font-size:10px;font-weight:600;padding:2px 6px;border-radius:8px;
            background:${s.status==='sent'?'var(--blue-bg)':s.status==='received'?'var(--green-bg)':s.status==='ended'?'var(--surface2)':'var(--surface2)'};
            color:${sc};margin-left:6px;">${s.status}</span>
        </div>
        <div class="sched-detail">
          ${s.target_name || "—"} &bull; ${RELAY_ACTION_LABELS[s.relay_action] || s.relay_action || "—"}
          &bull; 📅 ${fireStr} &bull; ⏱ ${dur}
          ${s.lc_mode ? "&bull; " + s.lc_mode.toUpperCase() : ""}
        </div>
      </div>
      <div class="sched-actions" style="display:flex;flex-direction:column;gap:4px;align-items:flex-end;">${cancelBtn}${optOutBtn}</div>
    </div>`;
  }).join("");
}

async function queueNow(scheduleId) {
  const rows = await supabaseGet(`schedules?id=eq.${scheduleId}`);
  const s = rows?.[0];
  if (!s) { setStatus("error", "Schedule not found."); return; }

  const fireAt = new Date().toISOString();
  const queueItem = {
    schedule_id: s.id || null,
    name: s.name || null,
    fire_at: fireAt,
    target_type: s.target_type,
    target_id: s.target_id,
    target_name: s.target_name,
    relay_action: s.relay_action,
    duration_minutes: s.duration_minutes || null,
    one_time: s.one_time || false,
    lc_mode: s.lc_mode || "dlc",
    lc_strategy: s.lc_strategy || 1,
    lc_reps: s.lc_reps || 1,
    status: "sent",
    fired_at: fireAt
  };

  // Execute the command first
  setStatus("sending", `Executing ${s.name}...`);
  await executeQueuedCommand(queueItem);

  // Save to queue as already fired
  await supabasePost("schedule_queue", queueItem);

  // Update last_fired_at on schedule
  await fetch(`${SUPABASE_URL}/rest/v1/schedules?id=eq.${scheduleId}`, {
    method: "PATCH",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({ last_fired_at: fireAt })
  });

  setStatus("ready", `${s.name} executed successfully.`);
  await loadQueue();
}

async function toggleSchedule(id, currentEnabled) {
  await fetch(`${SUPABASE_URL}/rest/v1/schedules?id=eq.${id}`, {
    method: "PATCH",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({ enabled: !currentEnabled })
  });
  await loadSchedules();
}

async function deleteSchedule(id) {
  // Cancel any pending queue items for this schedule
  await fetch(`${SUPABASE_URL}/rest/v1/schedule_queue?schedule_id=eq.${id}&status=eq.pending`, {
    method: "PATCH",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({ status: "cancelled" })
  });
  await supabaseDelete("schedules", `id=eq.${id}`);
  setStatus("ready", "Schedule deleted and queue cancelled.");
  await loadSchedules();
  await loadQueue();
}

async function loadDeviceEvents() {
  const list = document.getElementById("device-events-list");
  if (!list) return;
  list.innerHTML = `<div class="sched-empty">Loading...</div>`;
  try {
    const rangeHours = document.getElementById("device-events-range")?.value;
    let query  = `device_events?order=received_at.desc&limit=500`;
    let qQuery = `schedule_queue?order=fired_at.desc&limit=500`;
    if (rangeHours) {
      const since = new Date(Date.now() - parseInt(rangeHours)*60*60*1000).toISOString();
      query  += `&received_at=gte.${since}`;
      qQuery += `&fired_at=gte.${since}`;
    }
    const devRows = await supabaseGet(query);
    const qRows   = await supabaseGet(qQuery);

    // Build schedule_queue lookup by lc_event_id
    const qMap = {};
    if (Array.isArray(qRows)) qRows.forEach(q => { if (q.lc_event_id != null) qMap[q.lc_event_id] = q; });

    // Build rows from device_events — one row per device_event entry
    // but deduplicate by keeping only one row per (name + device) where name is known
    let rows = [];
    if (Array.isArray(devRows) && devRows.length) {
      // First merge all rows with queue data
      const merged = devRows.map(e => {
        const q = qMap[e.event_id] || {};
        return {
          ...e,
          name:             q.name || null,
          target_name:      q.target_name || DEVICES.find(d => d.uid === e.device_uid)?.name || unitName(e.device_uid || ""),
          relay_action:     q.relay_action || "—",
          status:           e.lc_status_label || "—",
          lc_mode:          q.lc_mode || "—",
          lc_strategy:      q.lc_strategy || "—",
          lc_reps:          q.lc_reps || "—",
          fire_at:          q.fire_at || e.event_time,
          duration_minutes: q.duration_minutes || null,
          event_type:       q.event_type || "switch",
          _raw:             e
        };
      });

      // Filter out rows with no event name (these are "Unit xxx" fallback entries)
      const named = merged.filter(r => r.name && r.name !== "—");
      const unnamed = merged.filter(r => !r.name || r.name === "—");

      // For named events: deduplicate by (name + device_uid) keeping most recent per status
      // Show one row per unique (name + device_uid + lc_status) combination
      const namedGrouped = {};
      named.forEach(r => {
        const key = `${r.name}_${r.device_uid}_${r.lc_status}`;
        if (!namedGrouped[key] || new Date(r.received_at) > new Date(namedGrouped[key].received_at)) {
          namedGrouped[key] = r;
        }
      });

      rows = Object.values(namedGrouped);
    }

    // If no device_events with names, fall back to schedule_queue directly
    if (!rows.length && Array.isArray(qRows) && qRows.length) {
      rows = qRows.map(q => ({ ...q, lc_status: null, _raw: q }));
    }

    // Sort by received_at / fire_at descending
    rows.sort((a, b) => new Date(b.received_at || b.fire_at) - new Date(a.received_at || a.fire_at));

    if (!rows.length) {
      list.innerHTML = `<div class="sched-empty">No device events in selected range.</div>`;
      return;
    }

    const statusIcon  = { sent:"📤", received:"📥", started:"▶️", ended:"✅", cancelled:"🚫", rejected:"❌", pending:"🕐" };
    const statusClass = { sent:"sent", received:"received", started:"started", ended:"ended", cancelled:"cancelled", rejected:"rejected" };
    const lcStatusToKey = { 0:"received", 1:"started", 2:"ended", 3:"sent", 4:"rejected", 5:"rejected", 6:"cancelled", 7:"started", 8:"started", 9:"started", 10:"ended" };

    list.innerHTML = `<div style="display:flex;flex-direction:column;gap:6px;">` +
      rows.map(r => {
        const fireAt     = r.fire_at ? new Date(r.fire_at) : null;
        const durationMs = (r.duration_minutes || 0) * 60 * 1000;
        const endAt      = fireAt ? new Date(fireAt.getTime() + durationMs) : null;
        const scKey      = lcStatusToKey[r.lc_status] || "sent";
        const sc         = statusClass[scKey] || "sent";
        const icon       = statusIcon[sc] || "📡";
        const fireStr    = fireAt ? fireAt.toLocaleString() : "—";
        const endStr     = endAt  ? endAt.toLocaleString()  : "—";
        const dur        = r.duration_minutes ? formatDuration(r.duration_minutes) : "—";
        const rData      = encodeURIComponent(JSON.stringify({ type:"queue", item:r._raw || r, queue:r }));
        return `<div class="queue-item ${sc}" style="cursor:pointer;" onclick="showDeviceEventDetail(JSON.parse(decodeURIComponent('${rData}')))">
          <div class="queue-info">
            <div class="queue-name">${r.name || r.target_name || "Unnamed Event"} &bull; ${r.target_name || "—"} &bull; ${RELAY_ACTION_LABELS[r.relay_action] || r.relay_action || "—"}</div>
            <div class="queue-detail">${icon} ${r.lc_status_label || r.status} &bull; 📅 ${fireStr} &bull; ⏱ ${dur} &bull; ends ${endStr}</div>
            <div class="queue-detail" style="color:var(--text-hint);margin-top:1px;">Mode: ${(r.lc_mode||"—").toUpperCase()} &bull; Strategy: ${r.lc_strategy||"—"} &bull; Duration: ${r.duration_minutes ? formatDuration(r.duration_minutes) : "—"} &nbsp;|&nbsp; <span style="color:var(--blue);text-decoration:underline;">Click to view hex &amp; details</span></div>
          </div>
          <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;" onclick="event.stopPropagation()">
            <span class="queue-status ${sc}">${r.lc_status_label || r.status}</span>
            <button onclick="openOptOutForEvent('${(r.name||'').replace(/'/g,"\\'")}','${(r.fire_at||'').replace(/'/g,"\\'")}')"
              style="padding:3px 8px;border-radius:var(--radius-sm);border:0.5px solid var(--amber);background:rgba(245,158,11,0.1);color:var(--amber);font-size:10px;font-weight:600;cursor:pointer;white-space:nowrap;">
              🚫 Opt-Out Device
            </button>
          </div>
        </div>`;
      }).join("") + `</div>`;
  } catch(err) {
    list.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error: ${err.message}</div>`;
    console.error("loadDeviceEvents:", err);
  }
}

function showDeviceEventDetail(data) {
  // Route to showEventDetail since rows now contain merged queue data
  showEventDetail({ type: "queue", item: data.queue || data.item });
}

// Keep loadQueue as alias for backward compat
async function loadQueue() { await loadDeviceEvents(); }

async function fireNow(id) {
  // Fetch the queue item and execute it immediately
  const rows = await supabaseGet(`schedule_queue?id=eq.${id}`);
  const item = rows?.[0];
  if (!item) { setStatus("error", "Queue item not found."); return; }
  await executeQueuedCommand(item);
  // Mark as fired
  await fetch(`${SUPABASE_URL}/rest/v1/schedule_queue?id=eq.${id}`, {
    method: "PATCH",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({ status: "sent", fired_at: new Date().toISOString() })
  });
  await loadQueue();
}

async function cancelQueueItem(id) {
  await fetch(`${SUPABASE_URL}/rest/v1/schedule_queue?id=eq.${id}`, {
    method: "PATCH",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({ status: "cancelled" })
  });
  setStatus("ready", "Queue item cancelled.");
  await loadQueue();
}

// ── Schedule Checker ──────────────────────────────────────────────────────────
async function checkSchedules() {
  const schedules = await supabaseGet("schedules?enabled=eq.true");
  if (!Array.isArray(schedules)) return;
  const now = new Date();

  for (const s of schedules) {
    // Get current time in schedule's timezone
    const nowInTz = new Date(now.toLocaleString("en-US", { timeZone: s.timezone }));
    const currentHHMM = nowInTz.getHours() * 60 + nowInTz.getMinutes();
    const [schedH, schedM] = s.action_time.split(":").map(Number);
    const schedHHMM = schedH * 60 + schedM;

    // Check date matches today
    if (s.event_date) {
      const todayStr = [
        nowInTz.getFullYear(),
        String(nowInTz.getMonth()+1).padStart(2,"0"),
        String(nowInTz.getDate()).padStart(2,"0")
      ].join("-");
      if (todayStr !== s.event_date) continue;
    }

    // Check within 5-minute window (2 min before, 5 min after to catch missed)
    const diffMins = schedHHMM - currentHHMM;
    if (diffMins < -5 || diffMins > 2) continue;

    // Check not already fired
    if (s.last_fired_at) {
      const lastFired = new Date(s.last_fired_at);
      const lastFiredInTz = new Date(lastFired.toLocaleString("en-US", { timeZone: s.timezone }));
      if (lastFiredInTz.toDateString() === nowInTz.toDateString()) continue;
    }

    const fireAt = now.toISOString();
    const queueItem = {
      schedule_id: s.id || null,
      name: s.name || null,
      fire_at: fireAt,
      target_type: s.target_type,
      target_id: s.target_id,
      target_name: s.target_name,
      relay_action: s.relay_action,
      duration_minutes: s.duration_minutes || null,
      one_time: s.one_time || false,
      lc_mode: s.lc_mode || "dlc",
      lc_strategy: s.lc_strategy || 1,
      lc_reps: s.lc_reps || 1,
      status: "sent",
      fired_at: fireAt
    };

    // Execute immediately — no delay
    await executeQueuedCommand(queueItem);

    // Save to queue as fired
    await supabasePost("schedule_queue", queueItem);

    // Update last_fired_at on schedule
    await fetch(`${SUPABASE_URL}/rest/v1/schedules?id=eq.${s.id}`, {
      method: "PATCH",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
      body: JSON.stringify({ last_fired_at: fireAt })
    });

    // Refresh queue if tab is visible
    const schedulerTab = document.getElementById("tab-scheduler");
    if (schedulerTab && schedulerTab.classList.contains("active")) await loadQueue();
  }
}

async function fireReadyQueueItems() {
  const now = new Date();
  const rows = await supabaseGet(`schedule_queue?status=eq.pending&fire_at=lte.${now.toISOString()}`);
  if (!Array.isArray(rows) || rows.length === 0) return;
  for (const item of rows) {
    // Mark fired BEFORE executing to prevent double-fire
    await fetch(`${SUPABASE_URL}/rest/v1/schedule_queue?id=eq.${item.id}`, {
      method: "PATCH",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
      body: JSON.stringify({ status: "sent", fired_at: now.toISOString() })
    });
    await executeQueuedCommand(item);
  }
  // Only refresh queue display if scheduler tab is active
  const schedulerTab = document.getElementById("tab-scheduler");
  if (rows.length > 0 && schedulerTab && schedulerTab.classList.contains("active")) {
    await loadQueue();
  }
}

function getScheduleUnixTime(dateStr, timeStr, timezone) {
  // Reliable method: parse the date/time as if it's in the target timezone
  // by creating an ISO string with the timezone offset applied
  try {
    // Create a date string that looks like it's in UTC
    // then find what UTC time corresponds to that local time in the target tz
    const localStr = `${dateStr}T${timeStr}:00`;
    // Use the trick of formatting a known UTC time in the target timezone
    // to find the offset, then apply it
    const probe = new Date(localStr + "Z"); // treat as UTC temporarily
    const tzStr = probe.toLocaleString("en-US", { timeZone: timezone, hour12: false,
      year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit", second: "2-digit" });
    // Parse what the timezone thinks the time is
    const [datePart, timePart] = tzStr.split(", ");
    const [m, d, y] = datePart.split("/").map(Number);
    const [h, min, s] = timePart.split(":").map(Number);
    const tzAsUtc = new Date(Date.UTC(y, m-1, d, h, min, s));
    // Offset = difference between what we asked for and what TZ returned
    const offset = probe.getTime() - tzAsUtc.getTime();
    // Apply offset to get true UTC for the requested local time
    const result = new Date(localStr + "Z").getTime() + offset;
    return Math.floor(result / 1000);
  } catch(e) {
    console.error("Error calculating schedule Unix time:", e);
    return 0;
  }
}

function formatTimeAMPM(timeStr) {
  // Convert "HH:MM" or "HH:MM:SS" to "h:MM AM/PM"
  if (!timeStr) return "";
  const parts = timeStr.split(":");
  let h = parseInt(parts[0]);
  const m = parts[1] || "00";
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return `${h}:${m} ${ampm}`;
}

function calcEndTime(timeStr, durationMins) {
  if (!timeStr || !durationMins) return "";
  const parts = timeStr.split(":");
  const totalMins = parseInt(parts[0]) * 60 + parseInt(parts[1]) + durationMins;
  const endH = Math.floor(totalMins / 60) % 24;
  const endM = String(totalMins % 60).padStart(2, "0");
  const ampm = endH >= 12 ? "PM" : "AM";
  const h12 = endH % 12 || 12;
  return `${h12}:${endM} ${ampm}`;
}

function formatDurationLabel(mins) {
  if (!mins) return "";
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  if (m === 0) return `${h} hr`;
  return `${h} hr ${m} min`;
}

function formatDuration(mins) {
  if (mins < 60) return mins + " min";
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m > 0 ? `${h} hr ${m} min` : `${h} hr`;
}


// ── LC Hex Generator ──────────────────────────────────────────────────────────
const RELAY_FUNCTION_MAP = {
  all_on:    0x8F,
  relay1_on: 0x81,
  relay2_on: 0x82,
  relay3_on: 0x84,
  relay4_on: 0x88,
};

let lcEventId = 1; // Auto-incrementing event ID (1-254) — loaded from Supabase on init

async function loadLCEventId() {
  try {
    const rows = await supabaseGet("program_settings?setting_key=eq.lc_event_id_counter&select=setting_value");
    const val = parseInt(rows?.[0]?.setting_value);
    if (!isNaN(val) && val >= 1 && val <= 254) lcEventId = val;
  } catch(e) { console.warn("loadLCEventId:", e.message); }
}

async function saveLCEventId(id) {
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/program_settings?on_conflict=setting_key`, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates,return=minimal"
      },
      body: JSON.stringify({ setting_key: "lc_event_id_counter", setting_value: String(id) })
    });
  } catch(e) { console.warn("saveLCEventId:", e.message); }
}

function buildLCHex(relayAction, mode, strategyNum, reps, startUnixTime) {
  const bytes = [];

  // Header
  bytes.push(0xA1);

  // Address spec = 0 (all call) — no address body
  // Message type = 0x00 (Load Control)
  // Strategy byte: bits 7-6 = mode (0=DLC, 1=DI), bits 0-5 = strategy number
  const modeBits = (mode === "di") ? 0x40 : 0x00;
  const stratByte = modeBits | (strategyNum & 0x3F);

  // Function byte: 1000xxxx where xxxx = relay bits
  const funcByte = RELAY_FUNCTION_MAP[relayAction] || 0x8F;

  // Data byte = repetitions (0-255)
  const dataByte = Math.min(255, Math.max(0, reps - 1)); // 0 = 1 rep, 1 = 2 reps etc.

  // Event ID (1-254, wraps) — persisted to Supabase to prevent collisions across devices
  const evId = lcEventId;
  lcEventId = (lcEventId >= 254) ? 1 : lcEventId + 1;
  saveLCEventId(lcEventId); // async, non-blocking

  // Start time as 4 bytes MSB first (Unix timestamp)
  const t = Math.floor(startUnixTime || 0);
  const t3 = (t >>> 24) & 0xFF;
  const t2 = (t >>> 16) & 0xFF;
  const t1 = (t >>> 8)  & 0xFF;
  const t0 =  t         & 0xFF;

  // Build message body (excluding header and length)
  const body = [
    0x00,      // Address spec = all call
    0x00,      // Message type = Load Control
    stratByte, // Strategy
    funcByte,  // Function
    dataByte,  // Data (reps-1)
    evId,      // Event ID
    t3, t2, t1, t0  // Start time MSB→LSB
  ];

  // Length = bytes after length byte including checksum = body.length + 1
  const length = body.length + 1;
  bytes.push(length);
  body.forEach(b => bytes.push(b));

  // Checksum = XOR of all bytes so far (including header and length)
  let checksum = 0;
  bytes.forEach(b => { checksum ^= b; });
  bytes.push(checksum);

  return bytes.map(b => b.toString(16).toUpperCase().padStart(2, "0")).join("");
}

function buildAssignBubbleUpHex(minutes) {
  // Assignment Command 0x1A, Designator 0x04 = Assign Bubble Up Timer
  // Writes directly to device non-volatile memory — persists through reboots
  const msb = (minutes >> 8) & 0xFF;
  const lsb = minutes & 0xFF;
  const bytes = [0xA1, 0x06, 0x00, 0x1A, 0x04, msb, lsb];
  let checksum = 0;
  bytes.forEach(b => { checksum ^= b; });
  bytes.push(checksum);
  return bytes.map(b => b.toString(16).toUpperCase().padStart(2,"0")).join("");
}

function buildCurrentChangeFlagHex(enable) {
  // Assignment Command 0x1A, Designator 0x03 = Assign Bubble Flag register
  //   enable=true  → 0x80 — set   bit 8: current-change bubble-up ON
  //                  result: A1 05 00 1A 03 80 [checksum]
  //   enable=false → 0x02 — clear bit 8, keep flag field present in payload
  //                  result: A1 05 00 1A 03 02 BF
  //   NOTE: 0x00 was incorrect — it caused the device to drop 1 byte from
  //   the bubble-up payload (60 chars instead of 62). 0x02 keeps the field
  //   present while disabling current-change reporting. Confirmed by firmware team.
  const flagByte = enable ? 0x80 : 0x02;
  const bytes = [0xA1, 0x05, 0x00, 0x1A, 0x03, flagByte];
  let checksum = 0;
  bytes.forEach(b => { checksum ^= b; });
  bytes.push(checksum);
  return bytes.map(b => b.toString(16).toUpperCase().padStart(2,"0")).join("");
}

function buildCancelEventHex(relayAction, eventId) {
  // Strategy 61 = restore, with SPECIFIC event ID (not 0xFF which cancels all)
  const bytes = [0xA1];
  const funcByte = RELAY_FUNCTION_MAP[relayAction] || 0x8F;
  const evId = parseInt(eventId) & 0xFF; // specific event ID
  const body = [
    0x00,  // Address spec = all call
    0x00,  // Message type = Load Control
    0x3D,  // Strategy 61 = restore
    funcByte,
    0x00,  // Data = 0 (abrupt restore)
    evId,  // Specific event ID to cancel
    0x00, 0x00, 0x00, 0x00  // immediate
  ];
  const length = body.length + 1;
  bytes.push(length);
  body.forEach(b => bytes.push(b));
  let checksum = 0;
  bytes.forEach(b => { checksum ^= b; });
  bytes.push(checksum);
  return bytes.map(b => b.toString(16).toUpperCase().padStart(2,"0")).join("");
}

function buildRestoreHex(relayAction) {
  // Strategy 61 = restore, DLC, abrupt (data=0)
  const bytes = [0xA1];
  const funcByte = RELAY_FUNCTION_MAP[relayAction] || 0x8F;
  const body = [
    0x00,  // Address spec = all call
    0x00,  // Message type = Load Control
    0x3D,  // Strategy 61 = 0x3D, DLC mode bits 7-6 = 00
    funcByte,
    0x00,  // Data = 0 (abrupt restore)
    0xFF,  // Event ID = 0xFF (cancel all)
    0x00, 0x00, 0x00, 0x00  // Start time = immediate
  ];
  const length = body.length + 1;
  bytes.push(length);
  body.forEach(b => bytes.push(b));
  let checksum = 0;
  bytes.forEach(b => { checksum ^= b; });
  bytes.push(checksum);
  return bytes.map(b => b.toString(16).toUpperCase().padStart(2, "0")).join("");
}

async function sendLCToDevice(uid, lcHex) {
  // Block commands to disabled/removed devices
  if (!DEVICES.find(d => d.uid === uid)) {
    console.warn(`sendLCToDevice: ${uid} not in active DEVICES — command blocked.`);
    return;
  }
  // Deliver to Notehub as data.qi note in exact required format:
  // {"body":{"LC":"..."},"req":"note.add","sync":true}
  const payload = {
    body: { LC: lcHex },
    req: "note.add",
    sync: true
  };
  try {
    const res = await fetch(PROXY_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Device-UID": uid },
      body: JSON.stringify(payload)
    });
    const responseText = await res.text();
    console.log(`LC sent to ${uid}: status=${res.status} body=${responseText}`);
    if (!res.ok) console.error(`LC command failed: ${responseText}`);
  } catch(e) { console.error("LC send error", uid, e); }
}

async function executeQueuedCommand(item) {
  const key = item.relay_action;
  const mode     = item.lc_mode     || "dlc";
  const strategy = item.lc_strategy || 1;
  const reps     = item.lc_reps     || 1;
  // Always use startTime=0 — device executes immediately on receipt
  // Our 1-hour queue delay handles the timing, not the device
  const lcHex = buildLCHex(key, mode, strategy, reps, 0);
  console.log(`LC Hex built: mode=${mode} strategy=${strategy} reps=${reps} hex=${lcHex}`);

  setStatus("sending", `Scheduled: ${item.target_name} — ${RELAY_ACTION_LABELS[key]} (${lcHex.substring(0,8)}...)...`);

  if (item.target_type === "group") {
    const gNum = parseInt(item.target_id.replace("group_", ""));
    const members = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(gNum));
    for (const device of members) {
      await sendLCToDevice(device.uid, lcHex);
    }
  } else {
    await sendLCToDevice(item.target_id, lcHex);
  }

  setStatus("ready", `Fired: ${item.target_name} — ${RELAY_ACTION_LABELS[key]} | LC: ${lcHex}`);



  // If one_time, delete the schedule after firing
  if (item.one_time && item.schedule_id) {
    await supabaseDelete("schedules", `id=eq.${item.schedule_id}`);
    const schedulerTab = document.getElementById("tab-scheduler");
    if (schedulerTab && schedulerTab.classList.contains("active")) await loadSchedules();
  }
}

