// ── LC Response Parser ────────────────────────────────────────────────────────
const LC_STATUS_LABELS = {
  0: "Event Received ✅",
  1: "Event Started 🟢",
  2: "Event Ended 🏁",
  3: "Already In Queue ⚠️",
  4: "Rejected — Queue Full ❌",
  5: "Rejected ❌",
  6: "Event Canceled 🚫",
  7: "Override 🔄",
  8: "Override Canceled 🔄",
  9: "Customer Comfort Override (R4)",
  10: "Customer Comfort Exit (R4)"
};




function runResponseParse(containerId) {
  const input = document.getElementById(`resp-input-${containerId}`);
  const result = document.getElementById(`resp-result-${containerId}`);
  if (!input || !result) return;
  const hex = input.value.trim();
  if (hex.length < 20) {
    result.innerHTML = `<div class="hex-error">Enter 20 hex characters (${hex.length}/20)</div>`;
    return;
  }
  const parsed = parseLCResponseHex(hex);
  if (parsed.error) {
    result.innerHTML = `<div class="hex-error">${parsed.error}</div>`;
    return;
  }
  result.innerHTML = Object.entries(parsed).map(([k, v]) =>
    `<div class="hex-row">
      <span class="hex-label">${k.charAt(0).toUpperCase() + k.slice(1).replace(/([A-Z])/g," $1")}</span>
      <span class="hex-value">${v}</span>
    </div>`
  ).join("");
}

// ── Bubble Up / Data Parser (62-char) ────────────────────────────────────────
function parseBubbleUpHex(hex) {
  hex = hex.trim().toUpperCase().replace(/\s/g, "");
  if (hex.length !== 62) return { error: `Expected 62 hex chars, got ${hex.length}` };

  const b = (pos) => parseInt(hex.slice(pos * 2, pos * 2 + 2), 16);
  const word = (msb, lsb) => (b(msb) << 8) | b(lsb);

  const header         = b(0);
  const length         = b(1);
  const msgType        = b(2);
  const bubbleUpCfg    = word(3, 4);
  const relayR1        = b(5);
  const relayR2        = b(6);
  const relayR3        = b(7);
  const relayR4        = b(8);
  const powerUpFlag    = b(9);
  const custComfort    = b(10) & 0x0F;
  const voltage        = word(11, 12);
  const current        = word(13, 14);
  const powerFactor    = word(15, 16);
  const watts          = word(17, 18);
  const touchPad       = b(19) & 0x03;
  const swValue        = word(20, 21);
  const sqValue        = word(22, 23);
  const overrideTimer  = word(24, 25);
  const serialNum      = (b(26) << 16) | (b(27) << 8) | b(28);
  const deviceId       = b(29);
  const checksum       = b(30);

  // Checksum verify
  let xorBU = 0;
  for (let i = 0; i < 30; i++) xorBU ^= b(i);
  const csOk = xorBU === checksum;

  const relayStatus = (r) => {
    const active = (r >> 3) & 1;
    const load   = r & 1;
    return active ? "ON" : (load ? "OFF (Load present)" : "OFF");
  };

  return {
    header:        `0x${header.toString(16).toUpperCase()} (${header === 0x51 ? "Response ✅" : "Invalid ❌"})`,
    msgType:       `0x${msgType.toString(16).toUpperCase()} (${msgType === 0x10 ? "Bubble Up" : "Other"})`,
    relay1:        relayStatus(relayR1),
    relay2:        relayStatus(relayR2),
    relay3:        relayStatus(relayR3),
    relay4:        relayStatus(relayR4),
    voltage:       `${voltage / 10} V`,
    current:       `${current / 10} A`,
    powerFactor:   `${(powerFactor / 1000).toFixed(3)}`,
    watts:         `${watts} W`,
    custComfort:   custComfort === 0x0A ? "ON" : "OFF",
    swValue:       swValue,
    sqValue:       sqValue,
    overrideTimer: `${overrideTimer} min`,
    serialNumber:  serialNum,
    deviceId:      `0x${deviceId.toString(16).toUpperCase()} (${deviceId})`,
    checksum:      csOk
      ? `0x${checksum.toString(16).toUpperCase()} ✅ Valid`
      : `0x${checksum.toString(16).toUpperCase()} ❌ Invalid`
  };
}

function renderBubbleUpParser(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  el.innerHTML = `
    <input class="hex-input" id="bu-input-${containerId}" type="text"
      placeholder="Paste Bubble Up hex (62 chars)..." maxlength="62"
      oninput="runBubbleUpParse('${containerId}')" />
    <button class="hex-parse-btn" onclick="runBubbleUpParse('${containerId}')">Parse</button>
    <div id="bu-result-${containerId}" class="hex-result"></div>`;
}

function runBubbleUpParse(containerId) {
  const input = document.getElementById(`bu-input-${containerId}`);
  const result = document.getElementById(`bu-result-${containerId}`);
  if (!input || !result) return;
  const hex = input.value.trim();
  if (hex.length < 62) {
    result.innerHTML = `<div class="hex-error">Enter 62 hex characters (${hex.length}/62)</div>`;
    return;
  }
  const parsed = parseBubbleUpHex(hex);
  if (parsed.error) {
    result.innerHTML = `<div class="hex-error">${parsed.error}</div>`;
    return;
  }
  result.innerHTML = Object.entries(parsed).map(([k, v]) =>
    `<div class="hex-row">
      <span class="hex-label">${k.charAt(0).toUpperCase() + k.slice(1).replace(/([A-Z])/g, " $1")}</span>
      <span class="hex-value">${v}</span>
    </div>`
  ).join("");
}

// ── LC Response Parser ───────────────────────────────────────────────────────
// LC_STATUS_LABELS already defined above

function parseLCResponseHex(hex) {
  hex = hex.trim().toUpperCase().replace(/\s/g, "");
  if (hex.length !== 20) return { error: `Expected 20 hex chars, got ${hex.length}` };

  const b = (pos) => parseInt(hex.slice(pos * 2, pos * 2 + 2), 16);

  const header   = b(0);
  const length   = b(1);
  const msgType  = b(2);
  const eventId  = b(3);
  const statusNibble = b(4) & 0x0F;
  const timestamp = (b(5) << 24) | (b(6) << 16) | (b(7) << 8) | b(8);
  const checksum = b(9);

  // Verify header
  if (header !== 0x51) return { error: `Invalid header 0x${header.toString(16).toUpperCase()} — expected 0x51` };

  // Verify checksum
  let xor = 0;
  for (let i = 0; i < 9; i++) xor ^= b(i);
  // Verify checksum — XOR of all bytes before checksum
  let rspXor = 0;
  for (let i = 0; i < 9; i++) rspXor ^= b(i);
  const checksumOk = rspXor === checksum;

  const statusLabel = LC_STATUS_LABELS[statusNibble] || `Unknown (${statusNibble})`;
  const tsDate = timestamp > 0 ? new Date(timestamp * 1000).toLocaleString() : "—";

  return {
    header:    `0x${header.toString(16).toUpperCase()} (Response)`,
    length:    length,
    msgType:   `0x${msgType.toString(16).toUpperCase()} (Load Control)`,
    eventId:   `0x${eventId.toString(16).toUpperCase()} (${eventId} decimal)`,
    status:    `${statusNibble} — ${statusLabel}`,
    timestamp: tsDate,
    checksum:  checksumOk
      ? `0x${checksum.toString(16).toUpperCase()} ✅ Valid`
      : `0x${checksum.toString(16).toUpperCase()} ❌ Invalid`
  };
}

function renderLCResponseParser(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  el.innerHTML = `
    <input class="hex-input" id="lcr-input-${containerId}" type="text"
      placeholder="Paste LC Response hex (20 chars)..." maxlength="20"
      oninput="runLCResponseParse('${containerId}')" />
    <button class="hex-parse-btn" onclick="runLCResponseParse('${containerId}')">Parse</button>
    <div id="lcr-result-${containerId}" class="hex-result"></div>`;
}

function runLCResponseParse(containerId) {
  const input = document.getElementById(`lcr-input-${containerId}`);
  const result = document.getElementById(`lcr-result-${containerId}`);
  if (!input || !result) return;
  const hex = input.value.trim();
  if (hex.length < 20) {
    result.innerHTML = `<div class="hex-error">Enter 20 hex characters (${hex.length}/20)</div>`;
    return;
  }
  const parsed = parseLCResponseHex(hex);
  if (parsed.error) {
    result.innerHTML = `<div class="hex-error">${parsed.error}</div>`;
    return;
  }
  result.innerHTML = Object.entries(parsed).map(([k, v]) =>
    `<div class="hex-row">
      <span class="hex-label">${k.charAt(0).toUpperCase() + k.slice(1).replace(/([A-Z])/g, " $1")}</span>
      <span class="hex-value">${v}</span>
    </div>`
  ).join("");
}

// ── End Event ────────────────────────────────────────────────────────────────

async function endEvent(targetId, targetType, relayAction, queueId) {
  const restoreHex = buildRestoreHex(relayAction);
  setStatus("sending", "Ending event — sending restore command...");
  if (targetType === "group") {
    const gNum = parseInt(targetId.replace("group_", ""));
    const members = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(gNum));
    for (const device of members) await sendLCToDevice(device.uid, restoreHex);
  } else {
    await sendLCToDevice(targetId, restoreHex);
  }
  setStatus("ready", "Event ended — restore command sent.");
  await loadQueue();
}

// ── Cancel All Events ─────────────────────────────────────────────────────────
async function cancelScheduledEvent(queueId) {
  // Load the full row so we have all fields
  const rows = await supabaseGet(`schedule_queue?id=eq.${queueId}`);
  if (!Array.isArray(rows) || !rows.length) { setStatus("error", "Event not found."); return; }
  const s = rows[0];
  const evType     = s.event_type || "switch";
  const displayName = s.name || s.target_name || `Event #${queueId}`;
  const targetId   = s.target_id;
  const targetType = s.target_type || "device";

  if (!confirm(`Cancel "${displayName}" and send a restore command to all assets in this event?`)) return;

  setStatus("sending", `Cancelling "${displayName}"…`);

  // Helper: get relay devices for a target
  const getRelayTargets = () => {
    if (targetType === "group") {
      const gNum = parseInt(targetId.replace("group_",""));
      return DEVICES.filter(d => (groupAssignments[d.uid]||[]).includes(gNum) && (!d.type || d.type === "relay"));
    }
    const d = DEVICES.find(x => x.uid === targetId);
    return d ? [d] : [{ uid: targetId }];
  };

  const getAssetTargets = (assetType) => {
    if (targetType === "group") {
      const gNum = parseInt(targetId.replace("group_",""));
      return DEVICES.filter(d => d.type === assetType && (groupAssignments[d.uid]||[]).includes(gNum));
    }
    const d = DEVICES.find(x => x.uid === targetId);
    return d ? [d] : [];
  };

  try {
    // ── Relay / Switch / BAS / Hybrid — send restore hex ───────────────────
    if (["switch","bas_di","hybrid"].includes(evType)) {
      const restoreHex = buildRestoreHex(s.relay_action || "all_on");
      for (const d of getRelayTargets()) await sendLCToDevice(d.uid, restoreHex);
    }

    // ── EV Charger — restore full charge rate ───────────────────────────────
    if (evType === "ev") {
      for (const d of getAssetTargets("ev")) {
        const sid = d.uid.replace("ev_","");
        if (typeof restoreEVSingle === "function") await restoreEVSingle(sid);
      }
    }

    // ── Battery — restore to autonomous mode ────────────────────────────────
    if (evType === "battery") {
      for (const d of getAssetTargets("battery")) {
        const aid = d.uid.replace("batt_","");
        if (typeof restoreBatterySingle === "function") await restoreBatterySingle(aid);
      }
    }

    // ── Generator — stop ────────────────────────────────────────────────────
    if (evType === "generator") {
      for (const d of getAssetTargets("generator")) {
        const aid = d.uid.replace("gen_","");
        if (typeof stopGeneratorSingle === "function") await stopGeneratorSingle(aid);
      }
    }

    // ── OpenADR — mark cancelled (VTN handles restore) ─────────────────────
    // No action needed — cancellation is handled at the VTN level

    // Mark cancelled in Supabase with operator info
    await supabasePatch(`schedule_queue?id=eq.${queueId}`, {
      status:       "cancelled",
      cancelled_at: new Date().toISOString(),
      cancelled_by: currentUser?.email || "operator"
    });
    setStatus("ready", `"${displayName}" cancelled — restore sent.`);
    await loadSchedules();
    loadEventsBar();

  } catch(e) {
    setStatus("error", `Cancel failed: ${e.message}`);
  }
}

async function cancelSpecificEvent(queueId, targetId, targetType, relayAction, eventName, lcEventId) {
  // Legacy wrapper — delegates to cancelScheduledEvent
  await cancelScheduledEvent(queueId);
}

async function cancelAllEvents() {
  if (!confirm("Send restore command to ALL devices? This will cancel all active load control events.")) return;
  // Build restore hex for all relays (0x8F = all functions)
  const restoreHex = buildRestoreHex("all_on");
  setStatus("sending", "Cancelling all events — sending restore to all devices...");
  // Send to every device on this dashboard
  for (const device of DEVICES) {
    await sendLCToDevice(device.uid, restoreHex);
  }
  // Mark all fired/pending queue items as cancelled in Supabase
  await fetch(`${SUPABASE_URL}/rest/v1/schedule_queue?status=in.(pending,fired)`, {
    method: "PATCH",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({ status: "cancelled" })
  });
  setStatus("ready", `Restore sent to all ${DEVICES.length} devices — all events cancelled.`);
  await loadQueue();
}


// ── History Charts ────────────────────────────────────────────────────────────
let chartInstances = {};

function destroyChart(id) {
  if (chartInstances[id]) { chartInstances[id].destroy(); delete chartInstances[id]; }
}

function buildChart(canvasId, label, labels, data, color) {
  destroyChart(canvasId);
  const ctx = document.getElementById(canvasId);
  if (!ctx) return;
  chartInstances[canvasId] = new Chart(ctx, {
    type: "line",
    data: {
      labels,
      datasets: [{
        label,
        data,
        borderColor: color,
        backgroundColor: color + "22",
        borderWidth: 2,
        pointRadius: 2,
        tension: 0.3,
        fill: true
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: {
        x: {
          ticks: { maxTicksLimit: 8, font: { size: 10 }, color: "#888780" },
          grid: { color: "rgba(0,0,0,0.05)" }
        },
        y: {
          ticks: { font: { size: 10 }, color: "#888780" },
          grid: { color: "rgba(0,0,0,0.05)" }
        }
      }
    }
  });
}

async function loadHistoricEvents() {
  const list = document.getElementById("historic-events-list");
  if (!list) return;
  list.innerHTML = `<div class="sched-empty">Loading...</div>`;
  const rangeHours = document.getElementById("hist-event-range")?.value;
  try {
    let query = `schedule_queue?order=fire_at.desc&limit=200`;
    if (rangeHours) {
      const since = new Date(Date.now() - parseInt(rangeHours)*60*60*1000).toISOString();
      query += `&fire_at=gte.${since}`;
    }
    const rows = await supabaseGet(query);
    if (!rows || rows.length === 0) { list.innerHTML = `<div class="sched-empty">No historic events found.</div>`; return; }
    list.innerHTML = `<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">
      <thead><tr>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Event</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Target</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Action</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Scheduled</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Sent</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Status</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Mode</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Strategy</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Reps</th>
        <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Duration</th>
      </tr></thead>
      <tbody>${rows.map(r => `<tr>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${r.name || "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${r.target_name || "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${RELAY_ACTION_LABELS[r.relay_action] || r.relay_action || "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${r.fire_at ? new Date(r.fire_at).toLocaleString() : "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${r.fired_at ? new Date(r.fired_at).toLocaleString() : "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);"><span class="queue-status ${r.status}">${r.status}</span></td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${(r.lc_mode||"—").toUpperCase()}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${r.lc_strategy || "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${r.lc_reps || "—"}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${r.duration_minutes ? formatDuration(r.duration_minutes) : "—"}</td>
      </tr>`).join("")}</tbody>
    </table></div>`;
  } catch(e) { list.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error loading historic events.</div>`; }
}

async function exportHistoricEvents() {
  const rangeHours = document.getElementById("hist-event-range")?.value;
  setStatus("sending", "Preparing historic events export...");
  try {
    let query = `schedule_queue?order=fire_at.desc&limit=5000`;
    if (rangeHours) {
      const since = new Date(Date.now() - parseInt(rangeHours)*60*60*1000).toISOString();
      query += `&fire_at=gte.${since}`;
    }
    const rows = await supabaseGet(query);
    if (!rows || rows.length === 0) { setStatus("error", "No events to export."); return; }
    const headers = ["Event Name","Target","Action","Mode","Strategy","Reps","Duration","Scheduled","Sent","Status"];
    const csvRows = rows.map(r => [
      r.name || "",
      r.target_name || "",
      RELAY_ACTION_LABELS[r.relay_action] || r.relay_action || "",
      (r.lc_mode || "").toUpperCase(),
      r.lc_strategy || "",
      r.lc_reps || "",
      r.duration_minutes ? formatDuration(r.duration_minutes) : "",
      r.fire_at ? new Date(r.fire_at).toLocaleString() : "",
      r.fired_at ? new Date(r.fired_at).toLocaleString() : "",
      r.status || ""
    ].map(v => `"${v}"`).join(","));
    const csv = [headers.join(","), ...csvRows].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = `historic_events.csv`; a.click();
    URL.revokeObjectURL(url);
    setStatus("ready", `Exported ${rows.length} historic events.`);
  } catch(e) { setStatus("error", "Export failed."); }
}

async function exportHistory() {
  setStatus("sending", "Preparing export — fetching all pages...");
  try {
    // Strip limit from query — supabaseGetPaged handles the ceiling
    const query   = buildHistoryQuery("device_readings", 50000).replace(/&limit=\d+/, "");
    const rows    = await supabaseGetPaged(query, 50000, 1000);
    if (!rows || rows.length === 0) { setStatus("error", "No data to export."); return; }
    const headers = ["Time","Device","Relay1","Relay2","Relay3","Relay4","Voltage (V)","Current (A)","Watts (W)","Power Factor","Comfort"];
    const csvRows = rows.map(r => {
      const devName = DEVICES.find(d => d.uid === r.device_uid)?.name ?? unitName(r.device_uid);
      return [
        new Date(r.recorded_at).toLocaleString(),
        devName,
        r.relay_status_r1 > 0 ? "On" : "Off",
        r.relay_status_r2 > 0 ? "On" : "Off",
        r.relay_status_r3 > 0 ? "On" : "Off",
        r.relay_status_r4 > 0 ? "On" : "Off",
        r.voltage        ? (r.voltage/10).toFixed(1)        : "",
        r.current        ? (r.current/10).toFixed(1)        : "",
        r.watts_consumed ?? "",
        r.power_factor   != null ? (r.power_factor/1000).toFixed(3) : "",
        r.customer_comfort > 0 ? "On" : "Off"
      ].map(v => `"${v}"`).join(",");
    });
    const csv      = [headers.join(","), ...csvRows].join("\n");
    const blob     = new Blob([csv], { type: "text/csv" });
    const url      = URL.createObjectURL(blob);
    const a        = document.createElement("a");
    const rangeVal = document.getElementById("history-range")?.value;
    const rangeLabel = rangeVal === "custom"
      ? `_${document.getElementById("history-from-date")?.value||""}__${document.getElementById("history-to-date")?.value||""}`
      : rangeVal ? `_last${rangeVal}h` : "_all";
    const devFilter = document.getElementById("history-device-select")?.value;
    const devLabel  = devFilter ? `_${unitName(devFilter)||devFilter}` : "_all_devices";
    a.href = url;
    a.download = `device_history${devLabel}${rangeLabel}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    setStatus("ready", `Exported ${rows.length.toLocaleString()} records.`);
  } catch(e) { setStatus("error", "Export failed."); console.error(e); }
}

async function loadCharts() {
  const deviceFilter = document.getElementById("chart-device-select")?.value;
  const hours = parseInt(document.getElementById("chart-range")?.value || "24");
  const since = new Date(Date.now() - hours * 60 * 60 * 1000).toISOString();
  const empty = document.getElementById("charts-empty");

  let query = `device_readings?order=recorded_at.asc&recorded_at=gte.${since}&limit=1000`;
  if (deviceFilter) query += `&device_uid=eq.${encodeURIComponent(deviceFilter)}`;

  const rows = await supabaseGet(query);
  if (!Array.isArray(rows) || rows.length === 0) {
    ["chart-voltage","chart-current","chart-watts"].forEach(id => destroyChart(id));
    if (empty) empty.style.display = "block";
    document.querySelectorAll(".chart-panel").forEach(p => p.style.display = "none");
    return;
  }
  if (empty) empty.style.display = "none";

  const labels = rows.map(r => {
    const d = new Date(r.recorded_at);
    return hours <= 48
      ? d.toLocaleTimeString("en-US", { hour:"2-digit", minute:"2-digit" })
      : d.toLocaleDateString("en-US", { month:"short", day:"numeric" }) + " " +
        d.toLocaleTimeString("en-US", { hour:"2-digit", minute:"2-digit" });
  });

  const activeBtn = document.querySelector(".chart-tab-btn.active");
  const activeChart = activeBtn?.dataset?.chart || "voltage";

  // Show active panel BEFORE building charts so canvas has real dimensions
  document.querySelectorAll(".chart-panel").forEach(p => p.style.display = "none");
  const activePanel = document.getElementById(`chart-panel-${activeChart}`);
  if (activePanel) activePanel.style.display = "block";

  buildChart("chart-voltage", "Voltage (V)",    labels, rows.map(r => r.voltage != null ? r.voltage / 10 : null),        "#378ADD");
  buildChart("chart-current", "Current (A)",    labels, rows.map(r => r.current != null ? r.current / 10 : null),        "#1D9E75");
  buildChart("chart-watts",   "Power (W)",      labels, rows.map(r => r.watts_consumed ?? null), "#BA7517");
  // chart-pf intentionally not built — canvas removed from UI (power factor sensor not yet meaningful)

  // Resize active chart after a frame to ensure proper fit
  requestAnimationFrame(() => {
    const inst = chartInstances[`chart-${activeChart}`];
    if (inst) inst.resize();
  });
}

async function loadEventsBar() {
  const bar = document.getElementById("events-bar");
  if (!bar) return;
  try {
    const now = new Date();

    // Only show queue items that are currently active or in the future
    // Active = fire_at in past but end time (fire_at + duration) is in future
    // Future = fire_at is in the future
    // Exclude ended/cancelled
    // Include all statuses except cancelled — use fire_at window to filter ended events
    // Look back 24hrs to catch active events, and forward for upcoming
    const lookback = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
    const lookahead = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString();
    const qRows = await supabaseGet(
      `schedule_queue?status=not.eq.cancelled&fire_at=gte.${lookback}&fire_at=lte.${lookahead}&order=fire_at.asc&limit=30`
    );

    let pills = [];

    if (Array.isArray(qRows)) {
      qRows.forEach(q => {
        const fireAt     = new Date(q.fire_at);
        // If duration_minutes is null/0, show for 4 hours as safe default
        const durationMs = ((q.duration_minutes || 0) > 0 ? q.duration_minutes : 240) * 60 * 1000;
        const endAt      = new Date(fireAt.getTime() + durationMs);

        // Skip if event has ended (past end time)
        if (endAt < now) return;

        // Determine display status
        const isActive = fireAt <= now && endAt > now;
        const sc = isActive ? "started"
          : q.status === "received" ? "received"
          : "sent";

        const timeStr = formatTimeAMPM(new Date(q.fire_at).toTimeString().slice(0,5));
        const dateStr = fireAt.toLocaleDateString("en-US", { month:"short", day:"numeric" });
        const activeLabel = isActive ? "🟢 Active" : `📅 ${dateStr} ${timeStr}`;

        const qData = encodeURIComponent(JSON.stringify({ type:'queue', item:q }));
        pills.push(`<span class="event-pill ${sc}" onclick="showEventDetail(JSON.parse(decodeURIComponent('${qData}')))">${q.name || q.target_name} &bull; ${activeLabel}</span>`);
      });
    }

    if (pills.length === 0) {
      bar.innerHTML = `<span class="events-bar-label">Events:</span><span class="events-bar-empty">No active or upcoming events</span>`;
    } else {
      bar.innerHTML = `<span class="events-bar-label">Events:</span>${pills.join("")}`;
    }
  } catch(e) {
    bar.innerHTML = `<span class="events-bar-label">Events:</span><span class="events-bar-empty">—</span>`;
  }
}

function switchToScheduler() {
  const mainBtn = document.getElementById("main-events");
  if (mainBtn) switchMain("events", mainBtn);
  const subBtn = document.getElementById("sub-event-history");
  if (subBtn) switchSub("events", "event-history", subBtn);
}

// Refresh events bar every 60 seconds
setInterval(loadEventsBar, 60000);

function closeEventModal(e) {
  if (!e || e.target === document.getElementById("event-modal")) {
    document.getElementById("event-modal").classList.remove("active");
  }
}

function showEventDetail(data) {
  const modal = document.getElementById("event-modal");
  const title = document.getElementById("modal-title");
  const body  = document.getElementById("modal-body");
  const item  = data.item;

  const evType = item.event_type || "switch";
  const typeLabels = { switch:"⚡ Switch / Relay", bas_di:"🏢 BAS Mode", ev:"🔌 EV Charger",
    battery:"🔋 Battery Backup", generator:"⚙️ Generator", openadr:"📡 OpenADR", hybrid:"🔀 Hybrid" };

  title.textContent = item.name || "Event Details";

  const statusColors = {
    sent:"background:var(--blue-bg);color:var(--blue-dark);",
    received:"background:var(--green-bg);color:var(--green-dark);",
    started:"background:#F0FDF4;color:#166534;",
    ended:"background:var(--surface2);color:var(--text-secondary);",
    pending:"background:var(--amber-bg);color:var(--amber);",
    cancelled:"background:var(--surface2);color:var(--text-hint);"
  };
  const statusStyle = statusColors[item.status] || "";
  const fireTime = item.fire_at  ? new Date(item.fire_at).toLocaleString()  : "—";
  const sentTime = item.fired_at ? new Date(item.fired_at).toLocaleString() : "—";
  const endTime  = item.action_time && item.duration_minutes ? calcEndTime(item.action_time, item.duration_minutes) : "—";
  const tzShort  = item.timezone ? item.timezone.split("/").pop().replace("_"," ") : "";

  // Build LC hex section only for relay-type events
  let lcSection = "";
  const isLCEvent = ["switch","bas_di","hybrid"].includes(evType);
  if (isLCEvent && item.relay_action && item.relay_action !== "hybrid") {
    const mode     = item.lc_mode     || "dlc";
    const strategy = item.lc_strategy || 1;
    const reps     = item.lc_reps     || 1;
    const startUnix = item.fire_at ? Math.floor(new Date(item.fire_at).getTime()/1000) : 0;
    const lcHex    = buildLCHex(item.relay_action, mode, strategy, reps, startUnix);
    const strat    = STRATEGY_TABLE[strategy];
    const stratDesc = strat ? `${strategy} — On ${strat.to} min / Off ${strat.ct - strat.to} min (${strat.pct}%)` : `${strategy}`;
    lcSection = `
    <div class="modal-section">
      <div class="modal-section-title">LC Hex Command</div>
      <div class="modal-hex">${lcHex}</div>
      <div class="modal-row" style="margin-top:8px;"><span class="modal-row-label">Strategy</span><span class="modal-row-value">${stratDesc}</span></div>
      <div class="modal-row"><span class="modal-row-label">Repetitions</span><span class="modal-row-value">${reps}</span></div>
      <div class="modal-row"><span class="modal-row-label">Control Mode</span><span class="modal-row-value">${mode.toUpperCase()}</span></div>
    </div>`;
  }

  // Type-specific detail rows
  let typeRows = "";
  if (evType === "ev")        typeRows = `<div class="modal-row"><span class="modal-row-label">Charge Limit</span><span class="modal-row-value">${item.ev_shed_pct !== undefined ? item.ev_shed_pct+"%" : "—"}</span></div>`;
  if (evType === "battery")   typeRows = `<div class="modal-row"><span class="modal-row-label">Battery Action</span><span class="modal-row-value">${item.battery_action || item.relay_action || "—"}</span></div>`;
  if (evType === "generator") typeRows = `<div class="modal-row"><span class="modal-row-label">Generator Action</span><span class="modal-row-value">${item.generator_action || item.relay_action || "—"}</span></div>`;
  if (evType === "hybrid")    typeRows = `<div class="modal-row"><span class="modal-row-label">Relay Config</span><span class="modal-row-value">Hybrid — see hybrid_config</span></div>`;

  body.innerHTML = `
    <div class="modal-section">
      <div class="modal-section-title">Event Parameters</div>
      <div class="modal-row"><span class="modal-row-label">Event Type</span><span class="modal-row-value">${typeLabels[evType] || evType}</span></div>
      <div class="modal-row"><span class="modal-row-label">Target</span><span class="modal-row-value">${item.target_name || "—"}</span></div>
      <div class="modal-row"><span class="modal-row-label">Target Type</span><span class="modal-row-value">${item.target_type || "—"}</span></div>
      ${isLCEvent ? `<div class="modal-row"><span class="modal-row-label">Relay Action</span><span class="modal-row-value">${RELAY_ACTION_LABELS[item.relay_action] || item.relay_action || "—"}</span></div>` : ""}
      ${typeRows}
      <div class="modal-row"><span class="modal-row-label">Duration</span><span class="modal-row-value">${item.duration_minutes ? formatDuration(item.duration_minutes) : "—"}</span></div>
      <div class="modal-row"><span class="modal-row-label">Scheduled</span><span class="modal-row-value">${fireTime}</span></div>
      ${endTime !== "—" ? `<div class="modal-row"><span class="modal-row-label">End Time</span><span class="modal-row-value">${endTime} ${tzShort}</span></div>` : ""}
      ${sentTime !== "—" ? `<div class="modal-row"><span class="modal-row-label">Dispatched</span><span class="modal-row-value">${sentTime}</span></div>` : ""}
      ${item.status ? `<div class="modal-row"><span class="modal-row-label">Status</span><span class="modal-row-value"><span class="modal-status" style="${statusStyle}">${item.status}</span></span></div>` : ""}
    </div>
    ${lcSection}`;

  modal.classList.add("active");
}

function viewDeviceHistory(uid) {
  // Switch to Devices > Device History
  const mainBtn = document.getElementById("main-devices");
  if (mainBtn) switchMain("devices", mainBtn);
  const subBtn = document.getElementById("sub-history");
  if (subBtn) switchSub("devices", "history", subBtn);
  setTimeout(() => {
    const sel = document.getElementById('history-device-select');
    if (sel) sel.value = uid;
    const chartSel = document.getElementById('chart-device-select');
    if (chartSel) chartSel.value = uid;
    loadHistory();
    loadCharts();
  }, 150);
}

// ── Current Device Status Tab ────────────────────────────────────────────────
let deviceStatusRefreshInterval = null;

async function initDeviceStatusTab() {
  await loadDeviceStatusTable();
  if (deviceStatusRefreshInterval) clearInterval(deviceStatusRefreshInterval);
  deviceStatusRefreshInterval = setInterval(async () => {
    const tabActive = document.getElementById("tab-data")?.classList.contains("active");
    if (tabActive) {
      await loadDeviceStatusTable();
      updateRefreshIndicator();
    }
  }, 10000);
}

// loadDeviceStatusTable — same logic as loadProgramSummary's device section
async function loadDeviceStatusTable() {
  const now        = Date.now();
  const oneHourAgo = new Date(now - ONLINE_THRESHOLD_MS).toISOString();
  refreshCountdown = 10;

  const deviceData = {};
  const eventData  = {};

  // Only relay-type DEVICES have Supabase readings — filter others out
  const relayDevices = DEVICES.filter(d => d.type !== "ev" && d.type !== "battery" && d.type !== "generator" && !d.uid.includes("PLACEHOLDER"));

  for (const device of relayDevices) {
    try {
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`
      );
      deviceData[device.uid] = rows?.[0] ?? null;
    } catch(e) { deviceData[device.uid] = null; }
  }
  for (const device of relayDevices) {
    try {
      const rows = await supabaseGet(
        `device_events?device_uid=eq.${encodeURIComponent(device.uid)}&order=received_at.desc&limit=1`
      );
      eventData[device.uid] = rows?.[0] ?? null;
    } catch(e) { eventData[device.uid] = null; }
  }

  let online = 0, offline = 0, noEvent = 0;

  const tbody = document.getElementById("summary-device-tbody");
  if (!tbody) return;

  if (!relayDevices.length) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:2rem;color:var(--text-hint);">No relay devices enrolled.</td></tr>`;
    return;
  }

  tbody.innerHTML = relayDevices.map(device => {
    const reading    = deviceData[device.uid];
    const evData     = eventData[device.uid];
    const lastReport = reading?.recorded_at ? new Date(reading.recorded_at) : null;
    const isOnline   = lastReport && (now - lastReport.getTime()) < ONLINE_THRESHOLD_MS;
    const location   = reading?.location ?? "—";

    const hasEvent    = !!evData;
    const eventStatus = hasEvent
      ? `<span style="color:var(--green-dark);font-weight:500;">${evData.lc_status_label || "Received"}</span><br><span style="font-size:10px;color:var(--text-hint);">${new Date(evData.received_at).toLocaleString()}</span>`
      : `<span style="color:var(--amber);font-weight:500;">No event received</span>`;

    const r1 = reading?.relay_status_r1 > 0;
    const r2 = reading?.relay_status_r2 > 0;
    const r3 = reading?.relay_status_r3 > 0;
    const r4 = reading?.relay_status_r4 > 0;
    const anyOn   = r1 || r2 || r3 || r4;
    const relayStr = reading
      ? [r1?"R1":"", r2?"R2":"", r3?"R3":"", r4?"R4":""].filter(Boolean).join(", ") || "All Off"
      : "—";

    if (isOnline) online++; else offline++;
    if (!hasEvent) noEvent++;

    const statusDot = isOnline
      ? `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);margin-right:5px;"></span>Online`
      : `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--red);margin-right:5px;"></span>Offline`;

    return `<tr style="${!hasEvent ? "background:rgba(186,117,23,0.05);" : ""}">
      <td style="padding:8px;border-bottom:0.5px solid var(--border);font-weight:500;">${device.name}<br><span style="font-size:10px;color:var(--text-hint);font-family:monospace;">${device.uid}</span></td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${statusDot}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${lastReport ? lastReport.toLocaleString() : "Never"}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">${location}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">${eventStatus}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);font-weight:${anyOn?"600":"400"};color:${anyOn?"var(--green-dark)":"var(--text-secondary)"};">${relayStr}</td>
    </tr>`;
  }).join("");

  // Update summary stats (shared with summary tab stat tiles)
  const enrolled = relayDevices.length;
  const statEl = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  statEl("stat-enrolled", enrolled);
  statEl("stat-online",   online);
  statEl("stat-offline",  offline);
  statEl("stat-no-event", noEvent);
}

// ── PROGRAM SUMMARY ──────────────────────────────────────────────────────────
let summaryRefreshInterval = null;

async function initSummaryTab() {
  refreshSummaryFeeds();
  await loadProgramSummary();          // populates stat tiles (enrolled/online/offline/no-event)
  await populateParticipationEventSelect();
  // Auto-refresh stats every 30s while on summary tab
  if (summaryRefreshInterval) clearInterval(summaryRefreshInterval);
  summaryRefreshInterval = setInterval(async () => {
    if (document.getElementById("tab-summary")?.classList.contains("active")) {
      await loadProgramSummary();
    }
  }, 30000);
}

let refreshCountdown = 10;
function updateRefreshIndicator() {
  refreshCountdown = 10;
  const el = document.getElementById("summary-refresh-indicator");
  if (el) el.textContent = "Auto-refresh: 10s";
}

setInterval(() => {
  if (document.getElementById("tab-summary")?.classList.contains("active")) {
    refreshCountdown--;
    const el = document.getElementById("summary-refresh-indicator");
    if (el) el.textContent = `Auto-refresh: ${Math.max(0, refreshCountdown)}s`;
  }
}, 1000);

async function loadProgramSummary() {
  const now = Date.now();
  const oneHourAgo = new Date(now - ONLINE_THRESHOLD_MS).toISOString();
  const oneDayAgo  = new Date(now - 24 * 60 * 60 * 1000).toISOString();
  refreshCountdown = 10;

  // Fetch latest reading per device
  const deviceData = {};
  for (const device of DEVICES) {
    try {
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`
      );
      deviceData[device.uid] = rows?.[0] ?? null;
    } catch(e) { deviceData[device.uid] = null; }
  }

  // Fetch recent device events (LC Responses) per device
  const eventData = {};
  for (const device of DEVICES) {
    try {
      const rows = await supabaseGet(
        `device_events?device_uid=eq.${encodeURIComponent(device.uid)}&order=received_at.desc&limit=1`
      );
      eventData[device.uid] = rows?.[0] ?? null;
    } catch(e) { eventData[device.uid] = null; }
  }

  // Calculate stats from device data fetched above
  let online = 0, offline = 0, noEvent = 0;
  // Count ALL assets — relay devices + EV chargers + batteries + generators
  const relayDevices = DEVICES.filter(d => (!d.type || d.type === "relay") && !d.uid.includes("PLACEHOLDER"));
  const enrolled = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER")).length;

  for (const device of relayDevices) {
    const reading    = deviceData[device.uid];
    const evData     = eventData[device.uid];
    const lastReport = reading?.recorded_at ? new Date(reading.recorded_at) : null;
    const isOnline   = lastReport && (now - lastReport.getTime()) < ONLINE_THRESHOLD_MS;
    if (isOnline) online++; else offline++;
    if (!evData) noEvent++;
  }

  document.getElementById("stat-enrolled").textContent = enrolled;
  document.getElementById("stat-online").textContent   = online;
  document.getElementById("stat-offline").textContent  = offline;
  document.getElementById("stat-no-event").textContent = noEvent;

  // Device status table now lives on Current Device Status tab — not rendered here
  return;

  const tbody = document.getElementById("summary-device-tbody_unused");
  if (!tbody) return;

  tbody.innerHTML = DEVICES.map(device => {
    const reading = deviceData[device.uid];
    const evData  = eventData[device.uid];
    const lastReport = reading?.recorded_at ? new Date(reading.recorded_at) : null;
    const isOnline = lastReport && (now - lastReport.getTime()) < ONLINE_THRESHOLD_MS;
    const location = reading?.location ?? "—";

    // Event received indicator
    const hasEvent = !!evData;
    const eventStatus = hasEvent
      ? `<span style="color:var(--green-dark);font-weight:500;">${evData.lc_status_label || "Received"}</span><br><span style="font-size:10px;color:var(--text-hint);">${new Date(evData.received_at).toLocaleString()}</span>`
      : `<span style="color:var(--amber);font-weight:500;">No event received</span>`;

    // Relay status
    const r1 = reading?.relay_status_r1 > 0;
    const r2 = reading?.relay_status_r2 > 0;
    const r3 = reading?.relay_status_r3 > 0;
    const r4 = reading?.relay_status_r4 > 0;
    const anyOn = r1 || r2 || r3 || r4;
    const relayStr = reading
      ? [r1?"R1":"", r2?"R2":"", r3?"R3":"", r4?"R4":""].filter(Boolean).join(", ") || "All Off"
      : "—";

    // Count stats
    if (isOnline) online++; else offline++;
    if (!hasEvent) noEvent++;

    const statusDot = isOnline
      ? `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);margin-right:5px;"></span>Online`
      : `<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--red);margin-right:5px;"></span>Offline`;

    return `<tr style="${!hasEvent ? 'background:rgba(186,117,23,0.05);' : ''}">
      <td style="padding:8px;border-bottom:0.5px solid var(--border);font-weight:500;">${device.name}<br><span style="font-size:10px;color:var(--text-hint);font-family:monospace;">${device.uid}</span></td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${statusDot}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${lastReport ? lastReport.toLocaleString() : "Never"}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">${location}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">${eventStatus}</td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);font-weight:${anyOn?"600":"400"};color:${anyOn?"var(--green-dark)":"var(--text-secondary)"};">${relayStr}</td>
    </tr>`;
  }).join("");

  // Update stats
  document.getElementById("stat-enrolled").textContent = enrolled;
  document.getElementById("stat-online").textContent   = online;
  document.getElementById("stat-offline").textContent  = offline;
  document.getElementById("stat-no-event").textContent = noEvent;
}

async function populateParticipationEventSelect() {
  await refreshParticipationEvents();
}

async function refreshParticipationEvents() {
  const sel = document.getElementById("participation-event-select");
  if (!sel) return;
  const rangeVal = document.getElementById("participation-date-range")?.value;
  const days = rangeVal !== "" && rangeVal != null ? parseInt(rangeVal) : null;
  const since = days ? new Date(Date.now() - days * 86400000).toISOString() : null;
  let q = "schedule_queue?order=fire_at.desc&limit=200&select=name,fire_at,status,target_type,target_id";
  if (since) q += `&fire_at=gte.${since}`;
  try {
    const rows = await supabaseGet(q);
    const current = sel.value;
    sel.innerHTML = '<option value="">— Select Event —</option>';
    if (Array.isArray(rows)) {
      rows.filter(r => r.name && r.name !== "—").forEach(r => {
        const opt = document.createElement("option");
        opt.value = r.name;
        opt.textContent = `${r.name} (${new Date(r.fire_at).toLocaleDateString()})`;
        if (r.name === current) opt.selected = true;
        sel.appendChild(opt);
      });
    }
  } catch(e) { console.error("refreshParticipationEvents:", e); }
}

async function loadParticipation() {
  const eventName = document.getElementById("participation-event-select")?.value;
  const results   = document.getElementById("participation-results");
  if (!results) return;
  if (!eventName) { results.innerHTML = `<div class="sched-empty">Please select an event.</div>`; return; }
  results.innerHTML = `<div class="sched-empty">Loading participation data...</div>`;

  try {
    const qRows = await supabaseGet(`schedule_queue?name=eq.${encodeURIComponent(eventName)}&order=fire_at.desc&limit=1`);
    const event = qRows?.[0];
    if (!event) { results.innerHTML = `<div class="sched-empty">Event not found.</div>`; return; }

    const fireAt   = new Date(event.fire_at);
    const duration = event.duration_minutes || 60;
    const endAt    = new Date(fireAt.getTime() + duration * 60 * 1000);
    const now      = new Date();

    // Resolve targeted devices (same logic as opt-out panel)
    const targetType = event.target_type || "all";
    const targetId   = event.target_id   || "";
    let targetDevices = [];
    if (targetType === "all") {
      targetDevices = DEVICES.filter(d => !d.uid.startsWith("therm_") && !d.uid.startsWith("batt_") && !d.uid.startsWith("ev_") && !d.uid.startsWith("gen_"));
    } else if (targetType === "group") {
      const groupNum = parseInt((targetId || "").replace("group_", ""));
      targetDevices = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(groupNum));
    } else {
      const d = DEVICES.find(d => d.uid === targetId);
      if (d) targetDevices = [d];
    }

    if (!targetDevices.length) {
      results.innerHTML = `<div class="sched-empty">No devices found for this event's target.</div>`;
      return;
    }

    // Load opt-out records for this event
    let optOutMap = {};
    try {
      const optOutRows = await supabaseGet(`event_opt_outs?event_name=eq.${encodeURIComponent(eventName)}`);
      if (Array.isArray(optOutRows)) optOutRows.forEach(o => { optOutMap[o.device_uid] = o; });
    } catch(e) {}

    let participated = 0, optedOutPre = 0, optedOutDuring = 0, didNotParticipate = 0;
    // Widen the window by 30 min each side to catch timing mismatches
    const windowStart = new Date(fireAt.getTime() - 30 * 60 * 1000);
    const windowEnd   = new Date(endAt.getTime()   + 30 * 60 * 1000);
    const rows = await Promise.all(targetDevices.map(async device => {
      const readings = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&recorded_at=gte.${windowStart.toISOString()}&recorded_at=lte.${windowEnd.toISOString()}&order=recorded_at.asc&limit=100`
      );
      const relayOn = Array.isArray(readings) && readings.some(r =>
        r.relay_status_r1 > 0 || r.relay_status_r2 > 0 ||
        r.relay_status_r3 > 0 || r.relay_status_r4 > 0 ||
        r.relay_active_r1 === true || r.relay_active_r2 === true ||
        r.relay_active_r3 === true || r.relay_active_r4 === true
      );
      const lastReading = Array.isArray(readings) ? readings[readings.length-1] : null;
      const optOut = optOutMap[device.uid] || null;
      if (optOut?.opt_out_type === "pre_event")       optedOutPre++;
      else if (optOut?.opt_out_type === "during_event") optedOutDuring++;
      else if (relayOn) participated++;
      else didNotParticipate++;
      return { device, relayOn, readingCount: Array.isArray(readings) ? readings.length : 0, lastReading, optOut };
    }));

    const totalDevices  = targetDevices.length;
    const pct = totalDevices > 0 ? Math.round((participated / totalDevices) * 100) : 0;
    const targetLabel = targetType === "all" ? "All Devices"
      : targetType === "group" ? `Group ${targetId.replace("group_","")}`
      : targetDevices[0]?.name || targetId;

    // Store data for export
    window._lastParticipationData = { event, eventName, fireAt, endAt, duration, targetLabel, targetDevices, rows, participated, didNotParticipate, optedOutPre, optedOutDuring, pct,
      cancelledAt: event.cancelled_at || null,
      cancelledBy: event.cancelled_by || null,
      endedAt:     event.ended_at     || null,
      wasEarlyCancelled: !!event.cancelled_at
    };

    results.innerHTML = `
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:1rem;">
        <div style="text-align:center;padding:0.75rem;background:var(--green-bg);border-radius:var(--radius-sm);">
          <div style="font-size:20px;font-weight:700;color:var(--green-dark);">${participated}</div>
          <div style="font-size:10px;color:var(--green-dark);">Participated</div>
        </div>
        <div style="text-align:center;padding:0.75rem;background:#FEF2F2;border-radius:var(--radius-sm);">
          <div style="font-size:20px;font-weight:700;color:var(--red);">${didNotParticipate}</div>
          <div style="font-size:10px;color:var(--red);">Did Not Participate</div>
        </div>
        <div style="text-align:center;padding:0.75rem;background:rgba(245,158,11,0.1);border-radius:var(--radius-sm);">
          <div style="font-size:20px;font-weight:700;color:var(--amber);">${optedOutPre}</div>
          <div style="font-size:10px;color:var(--amber);">Opted-Out Pre-Event</div>
        </div>
        <div style="text-align:center;padding:0.75rem;background:rgba(245,158,11,0.1);border-radius:var(--radius-sm);">
          <div style="font-size:20px;font-weight:700;color:var(--amber);">${optedOutDuring}</div>
          <div style="font-size:10px;color:var(--amber);">Opted-Out During</div>
        </div>
        <div style="text-align:center;padding:0.75rem;background:var(--blue-bg);border-radius:var(--radius-sm);">
          <div style="font-size:20px;font-weight:700;color:var(--blue-dark);">${pct}%</div>
          <div style="font-size:10px;color:var(--blue-dark);">Participation Rate</div>
        </div>
      </div>
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px;">
        <div style="font-size:11px;color:var(--text-hint);">
          Event window: ${fireAt.toLocaleString()} — ${endAt.toLocaleString()} &bull;
          Target: <strong>${targetLabel}</strong> &bull;
          ${totalDevices} device${totalDevices !== 1 ? "s" : ""}
        </div>
        <button class="queue-refresh" style="color:var(--green-dark);border-color:var(--green);" onclick="exportParticipationReport()">
          📄 Export Report
        </button>
      </div>
      <div style="overflow-x:auto;">
      <table style="width:100%;border-collapse:collapse;font-size:11px;">
        <thead><tr>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Device</th>
          <th style="text-align:center;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Participated</th>
          <th style="text-align:center;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Opted-Out Pre-Event</th>
          <th style="text-align:center;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Opted-Out During</th>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Opt-Out Time</th>
          <th style="text-align:center;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Readings in Event</th>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Relay Status</th>
        </tr></thead>
        <tbody>${rows.map(r => {
          const relayStr = r.lastReading
            ? [r.lastReading.relay_status_r1>0?"R1":"",r.lastReading.relay_status_r2>0?"R2":"",r.lastReading.relay_status_r3>0?"R3":"",r.lastReading.relay_status_r4>0?"R4":""].filter(Boolean).join(", ")||"All Off"
            : "No data";
          const isPre    = r.optOut?.opt_out_type === "pre_event";
          const isDuring = r.optOut?.opt_out_type === "during_event";
          const optTime  = r.optOut ? new Date(r.optOut.opted_out_at).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}) : "—";
          return `<tr>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);font-weight:500;">${r.device.name}</td>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${r.optOut?"—":r.relayOn?'<span style="color:var(--green-dark);font-weight:600;">✅ Yes</span>':'<span style="color:var(--red);">❌ No</span>'}</td>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${isPre?'<span style="color:var(--amber);font-weight:600;">🚫 Yes</span>':"—"}</td>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${isDuring?'<span style="color:var(--amber);font-weight:600;">🚫 Yes</span>':"—"}</td>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);font-size:10px;color:var(--text-hint);">${optTime}</td>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${r.readingCount}</td>
            <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">${relayStr}</td>
          </tr>`;
        }).join("")}</tbody>
      </table></div>`;
  } catch(e) {
    results.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error: ${e.message}</div>`;
    console.error("loadParticipation:", e);
  }
}

function exportParticipationReport() {
  const d = window._lastParticipationData;
  if (!d) { alert("Please load participation data first."); return; }

  const { eventName, fireAt, endAt, duration, targetLabel, rows,
          participated, didNotParticipate, optedOutPre, optedOutDuring, pct,
          cancelledAt, cancelledBy, endedAt, wasEarlyCancelled } = d;

  const total        = rows.length;
  const reportDate   = new Date().toLocaleString();
  const actualEnd    = cancelledAt ? new Date(cancelledAt) : endedAt ? new Date(endedAt) : endAt;
  const actualDurMins = Math.round((actualEnd - fireAt) / 60000);
  const endReason    = cancelledAt
    ? `Early cancellation by operator (${cancelledBy || "unknown"})`
    : "Completed at scheduled end time";

  const kpiCard = (value, label, color, bg) =>
    `<div style="text-align:center;padding:16px 12px;border-radius:8px;background:${bg};border-left:4px solid ${color};">
      <div style="font-size:28px;font-weight:800;color:${color};line-height:1;">${value}</div>
      <div style="font-size:11px;color:#64748B;margin-top:6px;text-transform:uppercase;letter-spacing:.05em;font-weight:600;">${label}</div>
    </div>`;

  const statusBadge = (val) => {
    if (val === true  || val === 'yes') return `<span style="display:inline-block;padding:2px 10px;border-radius:12px;background:#DCFCE7;color:#166534;font-size:11px;font-weight:700;">✓ Yes</span>`;
    if (val === false || val === 'no')  return `<span style="display:inline-block;padding:2px 10px;border-radius:12px;background:#FEE2E2;color:#991B1B;font-size:11px;font-weight:700;">✗ No</span>`;
    if (val === 'optout') return `<span style="display:inline-block;padding:2px 10px;border-radius:12px;background:#FEF3C7;color:#92400E;font-size:11px;font-weight:700;">🚫 Opted Out</span>`;
    return `<span style="color:#94A3B8;">—</span>`;
  };

  // Build donut chart SVG for participation breakdown
  const total2 = participated + didNotParticipate + optedOutPre + optedOutDuring;
  const pctParticipated  = total2 > 0 ? (participated  / total2 * 100) : 0;
  const pctNoShow        = total2 > 0 ? (didNotParticipate / total2 * 100) : 0;
  const pctOptPre        = total2 > 0 ? (optedOutPre / total2 * 100) : 0;
  const pctOptDuring     = total2 > 0 ? (optedOutDuring / total2 * 100) : 0;

  function donutArc(pct, offset, color) {
    const r = 60, cx = 80, cy = 80;
    const circ = 2 * Math.PI * r;
    const dash = (pct / 100) * circ;
    const dashOffset = circ - (offset / 100) * circ;
    return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="20"
      stroke-dasharray="${dash} ${circ - dash}"
      stroke-dashoffset="${dashOffset}"
      transform="rotate(-90 ${cx} ${cy})" />`;
  }

  let offset = 0;
  const arc1 = donutArc(pctParticipated, offset, '#16A34A'); offset += pctParticipated;
  const arc2 = donutArc(pctNoShow,       offset, '#DC2626'); offset += pctNoShow;
  const arc3 = donutArc(pctOptPre,       offset, '#D97706'); offset += pctOptPre;
  const arc4 = donutArc(pctOptDuring,    offset, '#F59E0B');

  const donutSVG = `<svg width="160" height="160" viewBox="0 0 160 160">
    <circle cx="80" cy="80" r="60" fill="none" stroke="#F1F5F9" stroke-width="20"/>
    ${arc1}${arc2}${arc3}${arc4}
    <text x="80" y="75" text-anchor="middle" font-size="22" font-weight="800" fill="#0F172A">${pct}%</text>
    <text x="80" y="94" text-anchor="middle" font-size="10" fill="#64748B" font-weight="600">PARTICIPATION</text>
  </svg>`;

  const deviceRows = rows.map(r => {
    const isPre    = r.optOut?.opt_out_type === "pre_event";
    const isDuring = r.optOut?.opt_out_type === "during_event";
    const optTime  = r.optOut ? new Date(r.optOut.opted_out_at).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}) : "—";
    const relayStr = r.lastReading
      ? [r.lastReading.relay_status_r1>0?"R1":"",r.lastReading.relay_status_r2>0?"R2":"",
         r.lastReading.relay_status_r3>0?"R3":"",r.lastReading.relay_status_r4>0?"R4":""].filter(Boolean).join(", ")||"All Off"
      : "No data";
    const rowBg = r.optOut ? "#FFFBEB" : r.relayOn ? "#F0FDF4" : "#FFF";
    return `<tr style="background:${rowBg};">
      <td style="padding:10px 14px;font-weight:600;border-bottom:1px solid #F1F5F9;">${r.device.name}</td>
      <td style="padding:10px 14px;border-bottom:1px solid #F1F5F9;text-align:center;">${r.optOut ? statusBadge('optout') : r.relayOn ? statusBadge(true) : statusBadge(false)}</td>
      <td style="padding:10px 14px;border-bottom:1px solid #F1F5F9;text-align:center;">${isPre ? statusBadge('yes') : statusBadge(false)}</td>
      <td style="padding:10px 14px;border-bottom:1px solid #F1F5F9;text-align:center;">${isDuring ? statusBadge('yes') : statusBadge(false)}</td>
      <td style="padding:10px 14px;border-bottom:1px solid #F1F5F9;font-size:12px;color:#64748B;">${optTime}</td>
      <td style="padding:10px 14px;border-bottom:1px solid #F1F5F9;text-align:center;font-weight:600;">${r.readingCount}</td>
      <td style="padding:10px 14px;border-bottom:1px solid #F1F5F9;font-size:12px;">${relayStr}</td>
    </tr>`;
  }).join('');

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>DR Participation Report — ${eventName}</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #F8FAFC; color: #0F172A; font-size: 14px; }
  @media print { body { background: #fff; } .no-print { display: none; } }
</style>
</head>
<body>
<div style="max-width:900px;margin:0 auto;padding:32px 24px;">

  <!-- Header -->
  <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:32px;padding-bottom:24px;border-bottom:2px solid #E2E8F0;">
    <div>
      <div style="font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.1em;margin-bottom:6px;">Demand Response Report</div>
      <div style="font-size:28px;font-weight:800;color:#0F172A;line-height:1.2;">Event Participation Report</div>
      <div style="font-size:15px;color:#64748B;margin-top:6px;">${eventName}</div>
    </div>
    <div style="text-align:right;">
      <div style="font-size:11px;color:#94A3B8;">Generated</div>
      <div style="font-size:13px;font-weight:600;color:#475569;">${reportDate}</div>
      <button class="no-print" onclick="window.print()" style="margin-top:10px;padding:8px 16px;border-radius:6px;border:none;background:#0F172A;color:#fff;font-size:12px;font-weight:600;cursor:pointer;">🖨 Print / Save PDF</button>
    </div>
  </div>

  <!-- Event Summary Card -->
  <div style="background:#fff;border-radius:12px;padding:24px;margin-bottom:24px;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;">
    <div style="font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.08em;margin-bottom:16px;">Event Summary</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Event Name</div><div style="font-weight:700;font-size:15px;">${eventName}</div></div>
      <div><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Target Scope</div><div style="font-weight:700;font-size:15px;">${targetLabel}</div></div>
      <div><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Event Start</div><div style="font-weight:600;">${fireAt.toLocaleString([], {dateStyle:"full",timeStyle:"short"})}</div></div>
      <div><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Event End</div><div style="font-weight:600;">${endAt.toLocaleString([],{timeStyle:"short"})}</div></div>
      <div><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Scheduled Duration</div><div style="font-weight:600;">${duration} minutes</div></div>
      <div><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Actual Duration</div><div style="font-weight:600;">${actualDurMins} minutes</div></div>
      <div style="grid-column:1/-1;"><div style="font-size:11px;color:#94A3B8;margin-bottom:3px;">Conclusion</div>
        <div style="font-weight:600;${cancelledAt?'color:#DC2626;':'color:#16A34A;'}">${endReason}</div></div>
    </div>
  </div>

  <!-- KPI Row + Donut -->
  <div style="display:grid;grid-template-columns:160px 1fr;gap:20px;margin-bottom:24px;align-items:center;">
    <div style="background:#fff;border-radius:12px;padding:16px;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;display:flex;align-items:center;justify-content:center;">
      ${donutSVG}
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      ${kpiCard(participated, 'Participated', '#16A34A', '#F0FDF4')}
      ${kpiCard(didNotParticipate, 'Did Not Participate', '#DC2626', '#FEF2F2')}
      ${kpiCard(optedOutPre, 'Opted-Out Pre-Event', '#D97706', '#FFFBEB')}
      ${kpiCard(optedOutDuring, 'Opted-Out During', '#F59E0B', '#FFFBEB')}
    </div>
  </div>

  <!-- Narrative -->
  <div style="background:#EFF6FF;border-radius:12px;padding:20px 24px;margin-bottom:24px;border-left:4px solid #3B82F6;">
    <div style="font-size:12px;font-weight:700;color:#1D4ED8;text-transform:uppercase;letter-spacing:.08em;margin-bottom:10px;">Summary</div>
    <p style="color:#1E3A5F;line-height:1.7;font-size:13px;">
      This demand response event was dispatched to <strong>${total} device${total!==1?"s":""}</strong> under the target scope <strong>"${targetLabel}"</strong>.
      ${wasEarlyCancelled
        ? `The event was <strong style="color:#DC2626;">cancelled early</strong> by ${cancelledBy||"an operator"} after running for <strong>${actualDurMins} of ${duration}</strong> scheduled minutes.`
        : `The event ran its <strong>full scheduled duration</strong> of <strong>${duration} minutes</strong>.`}
      Of the ${total} devices called, <strong style="color:#16A34A;">${participated} (${pct}%)</strong> successfully participated by activating their relay during the event window.
      ${optedOutPre > 0 ? `<strong>${optedOutPre} device${optedOutPre!==1?"s":""}</strong> were opted out prior to the event.` : ""}
      ${optedOutDuring > 0 ? `<strong>${optedOutDuring} device${optedOutDuring!==1?"s":""}</strong> were opted out during the event and received a restore command.` : ""}
      ${didNotParticipate > 0 ? `<strong style="color:#DC2626;">${didNotParticipate} device${didNotParticipate!==1?"s":""}</strong> did not register relay activation during the event window.` : "All non-opted-out devices confirmed participation."}
    </p>
  </div>

  <!-- Device Detail Table -->
  <div style="background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;margin-bottom:24px;">
    <div style="padding:16px 20px;border-bottom:1px solid #F1F5F9;font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.08em;">Device Detail</div>
    <div style="overflow-x:auto;">
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead>
        <tr style="background:#F8FAFC;">
          <th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Device</th>
          <th style="text-align:center;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Participated</th>
          <th style="text-align:center;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Opted-Out Pre</th>
          <th style="text-align:center;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Opted-Out During</th>
          <th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Opt-Out Time</th>
          <th style="text-align:center;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Readings</th>
          <th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid #E2E8F0;">Relay Status</th>
        </tr>
      </thead>
      <tbody>${deviceRows}</tbody>
    </table>
    </div>
  </div>

  <!-- Footer -->
  <div style="text-align:center;padding-top:24px;border-top:1px solid #E2E8F0;color:#94A3B8;font-size:11px;">
    Load Control Dashboard &nbsp;·&nbsp; ${eventName} &nbsp;·&nbsp; ${reportDate}
  </div>

</div>
</body>
</html>`;

  const blob = new Blob([html], { type: "text/html" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `DR_Participation_Report_${eventName.replace(/\s+/g,"_")}_${fireAt.toISOString().split("T")[0]}.html`;
  a.click();
  URL.revokeObjectURL(a.href);
}


// ── Current Event Viewer ──────────────────────────────────────────────────────

let _currentEventPoller = null;
let _currentEventCountdownTimer = null;

function initCurrentEventViewer() {
  loadCurrentEvent();
  // Start auto-refresh every 30 seconds
  if (_currentEventPoller) clearInterval(_currentEventPoller);
  _currentEventPoller = setInterval(() => {
    const pane = document.getElementById("tab-current-event");
    if (pane?.classList.contains("active")) loadCurrentEvent();
    else { clearInterval(_currentEventPoller); _currentEventPoller = null; }
  }, 30000);
}

async function loadCurrentEvent() {
  const container = document.getElementById("current-event-container");
  const refreshEl = document.getElementById("live-event-last-refresh");
  if (!container) return;
  if (refreshEl) refreshEl.textContent = `Last updated: ${new Date().toLocaleTimeString()}`;

  try {
    // Find active events — fired within last 24 hours with non-terminal status
    const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
    const rows = await supabaseGet(
      `schedule_queue?fire_at=gte.${since}&status=not.in.(cancelled,rejected,ended)&order=fire_at.desc&limit=10`
    );

    const now = new Date();
    // Filter to events that are actually in their active window
    const active = Array.isArray(rows) ? rows.filter(r => {
      const start = new Date(r.fire_at);
      const end   = new Date(start.getTime() + (r.duration_minutes || 60) * 60000);
      return now >= start && now <= end;
    }) : [];

    // Also include events that fired recently (sent/received but may not have started yet)
    const pending = Array.isArray(rows) ? rows.filter(r => {
      const start = new Date(r.fire_at);
      const minsAgo = (now - start) / 60000;
      return minsAgo < 5 && !active.find(a => a.id === r.id);
    }) : [];

    const allEvents = [...active, ...pending];

    if (!allEvents.length) {
      // Check if any event ended very recently (within last 15 min)
      const recentEnd = Array.isArray(rows) ? rows.find(r => {
        const end = new Date(new Date(r.fire_at).getTime() + (r.duration_minutes||60)*60000);
        return (now - end) < 15 * 60000;
      }) : null;

      container.innerHTML = `<div class="sched-card" style="text-align:center;padding:2rem;">
        <div style="font-size:32px;margin-bottom:10px;">📭</div>
        <div style="font-size:15px;font-weight:600;color:var(--text-primary);">No Active Events</div>
        ${recentEnd ? `<div style="font-size:12px;color:var(--amber);margin-top:6px;">⚠️ Event "${recentEnd.name}" ended recently</div>` : ""}
        <div style="font-size:12px;color:var(--text-hint);margin-top:6px;">Live event status will appear here when an event is in progress</div>
      </div>`;
      return;
    }

    // Render each active event
    container.innerHTML = await Promise.all(allEvents.map(ev => renderLiveEventCard(ev))).then(cards => cards.join(""));

    // Start countdown timers
    startEventCountdowns(allEvents);

  } catch(e) {
    container.innerHTML = `<div class="sched-card"><div class="sched-empty" style="color:var(--red);">Error: ${e.message}</div></div>`;
    console.error("loadCurrentEvent:", e);
  }
}

async function renderLiveEventCard(ev) {
  const now      = new Date();
  const fireAt   = new Date(ev.fire_at);
  const duration = ev.duration_minutes || 60;
  const endAt    = new Date(fireAt.getTime() + duration * 60000);
  const elapsed  = Math.max(0, Math.floor((now - fireAt) / 1000));
  const totalSec = duration * 60;
  const remaining = Math.max(0, totalSec - elapsed);
  const pct = Math.min(100, Math.round((elapsed / totalSec) * 100));

  // Resolve target devices
  const targetType = ev.target_type || "all";
  const targetId   = ev.target_id   || "";
  let targetDevices = [];
  if (targetType === "all") {
    targetDevices = DEVICES.filter(d => !d.uid.startsWith("therm_") && !d.uid.startsWith("batt_") && !d.uid.startsWith("ev_") && !d.uid.startsWith("gen_"));
  } else if (targetType === "group") {
    const groupNum = parseInt((targetId || "").replace("group_", ""));
    targetDevices = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(groupNum));
  } else {
    const d = DEVICES.find(d => d.uid === targetId);
    if (d) targetDevices = [d];
  }

  // Load latest readings for each device
  const deviceStatuses = await Promise.all(targetDevices.map(async device => {
    try {
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`
      );
      const r = rows?.[0];
      const relayOn = r && (r.relay_status_r1 > 0 || r.relay_status_r2 > 0 || r.relay_status_r3 > 0 || r.relay_status_r4 > 0 || r.relay_active_r1 || r.relay_active_r2);
      const lastSeen = r ? new Date(r.recorded_at) : null;
      const minsAgo  = lastSeen ? Math.round((now - lastSeen) / 60000) : null;
      return { device, relayOn, lastSeen, minsAgo, reading: r };
    } catch(e) { return { device, relayOn: false, lastSeen: null, minsAgo: null, reading: null }; }
  }));

  // Load opt-outs for this event
  let optOutMap = {};
  try {
    const optOuts = await supabaseGet(`event_opt_outs?event_name=eq.${encodeURIComponent(ev.name)}`);
    if (Array.isArray(optOuts)) optOuts.forEach(o => { optOutMap[o.device_uid] = o; });
  } catch(e) {}

  const participating = deviceStatuses.filter(d => !optOutMap[d.device.uid] && d.relayOn).length;
  const optedOut      = Object.keys(optOutMap).length;
  const targetLabel   = targetType === "all" ? "All Devices"
    : targetType === "group" ? `Group ${targetId.replace("group_","")}`
    : targetDevices[0]?.name || targetId;

  const fmtTime = s => {
    const m = Math.floor(s / 60), sec = s % 60;
    return `${m}:${sec.toString().padStart(2,"0")}`;
  };

  return `<div class="sched-card" style="margin-bottom:1rem;">
    <!-- Event Header -->
    <div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:14px;">
      <div>
        <div style="display:flex;align-items:center;gap:8px;">
          <span style="width:8px;height:8px;border-radius:50%;background:var(--green-dark);display:inline-block;animation:pulse 1.5s infinite;"></span>
          <span style="font-size:16px;font-weight:700;color:var(--text-primary);">${ev.name}</span>
          <span style="font-size:11px;padding:2px 8px;border-radius:10px;background:var(--green-bg);color:var(--green-dark);font-weight:600;">ACTIVE</span>
        </div>
        <div style="font-size:12px;color:var(--text-hint);margin-top:4px;">
          Target: <strong>${targetLabel}</strong> &bull;
          Started: ${fireAt.toLocaleTimeString()} &bull;
          Ends: ${endAt.toLocaleTimeString()} &bull;
          Strategy: ${ev.lc_strategy || "—"} &bull;
          Mode: ${(ev.lc_mode || "—").toUpperCase()}
        </div>
      </div>
      <div style="text-align:right;">
        <div style="font-size:28px;font-weight:700;font-family:monospace;color:var(--text-primary);" id="countdown-${ev.id}">${fmtTime(remaining)}</div>
        <div style="font-size:10px;color:var(--text-hint);">remaining</div>
      </div>
    </div>

    <!-- Progress Bar -->
    <div style="height:6px;background:var(--border-md);border-radius:3px;overflow:hidden;margin-bottom:14px;">
      <div style="height:100%;background:var(--green-dark);border-radius:3px;width:${pct}%;transition:width 1s linear;" id="progress-${ev.id}"></div>
    </div>

    <!-- KPI Row -->
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px;">
      <div style="text-align:center;padding:10px;background:var(--surface2);border-radius:var(--radius-sm);">
        <div style="font-size:20px;font-weight:700;color:var(--text-primary);">${targetDevices.length}</div>
        <div style="font-size:10px;color:var(--text-hint);">Devices Called</div>
      </div>
      <div style="text-align:center;padding:10px;background:var(--green-bg);border-radius:var(--radius-sm);">
        <div style="font-size:20px;font-weight:700;color:var(--green-dark);">${participating}</div>
        <div style="font-size:10px;color:var(--green-dark);">Confirmed Active</div>
      </div>
      <div style="text-align:center;padding:10px;background:rgba(245,158,11,0.1);border-radius:var(--radius-sm);">
        <div style="font-size:20px;font-weight:700;color:var(--amber);">${optedOut}</div>
        <div style="font-size:10px;color:var(--amber);">Opted Out</div>
      </div>
      <div style="text-align:center;padding:10px;background:var(--blue-bg);border-radius:var(--radius-sm);">
        <div style="font-size:20px;font-weight:700;color:var(--blue-dark);">${pct}%</div>
        <div style="font-size:10px;color:var(--blue-dark);">Elapsed</div>
      </div>
    </div>

    <!-- Device Status Cards -->
    <div style="font-size:11px;font-weight:700;color:var(--text-hint);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px;">Device Status</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px;">
      ${deviceStatuses.map(ds => {
        const optOut = optOutMap[ds.device.uid];
        const isOptedOut = !!optOut;
        const isDuring   = optOut?.opt_out_type === "during_event";
        const isPre      = optOut?.opt_out_type === "pre_event";
        const statusColor = isOptedOut ? "var(--amber)" : ds.relayOn ? "var(--green-dark)" : "var(--text-hint)";
        const statusBg    = isOptedOut ? "rgba(245,158,11,0.08)" : ds.relayOn ? "var(--green-bg)" : "var(--surface2)";
        const statusBorder = isOptedOut ? "var(--amber)" : ds.relayOn ? "var(--green)" : "var(--border)";
        const statusLabel = isOptedOut ? `🚫 Opted Out ${isDuring?"(during)":"(pre-event)"}` : ds.relayOn ? "✅ Relay Active" : "⚫ No Response";
        const lastSeenStr = ds.minsAgo !== null ? (ds.minsAgo < 1 ? "just now" : `${ds.minsAgo}m ago`) : "no data";
        return `<div style="padding:10px 12px;border-radius:var(--radius-sm);border:0.5px solid ${statusBorder};background:${statusBg};">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
            <span style="font-size:12px;font-weight:600;">${ds.device.name}</span>
            <span style="font-size:10px;color:var(--text-hint);">${lastSeenStr}</span>
          </div>
          <div style="font-size:11px;font-weight:600;color:${statusColor};margin-bottom:6px;">${statusLabel}</div>
          ${ds.reading ? `<div style="font-size:10px;color:var(--text-hint);">
            ${ds.reading.voltage ? (ds.reading.voltage/10).toFixed(1)+"V" : ""} 
            ${ds.reading.current ? (ds.reading.current/10).toFixed(1)+"A" : ""}
          </div>` : ""}
          ${!isOptedOut ? `<button onclick="liveOptOut('${ev.name}','${ds.device.uid}')"
            style="margin-top:6px;width:100%;padding:4px;border-radius:var(--radius-sm);border:0.5px solid var(--red);background:rgba(220,38,38,0.08);color:var(--red);font-size:10px;font-weight:600;cursor:pointer;">
            🚫 Opt Out Now
          </button>` : `<button onclick="liveUndoOptOut('${ev.name}','${ds.device.uid}')"
            style="margin-top:6px;width:100%;padding:4px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);color:var(--text-hint);font-size:10px;cursor:pointer;">
            Undo Opt-Out
          </button>`}
        </div>`;
      }).join("")}
    </div>
  </div>`;
}

function startEventCountdowns(events) {
  if (_currentEventCountdownTimer) clearInterval(_currentEventCountdownTimer);
  _currentEventCountdownTimer = setInterval(() => {
    const now = new Date();
    events.forEach(ev => {
      const fireAt    = new Date(ev.fire_at);
      const totalSec  = (ev.duration_minutes || 60) * 60;
      const elapsed   = Math.max(0, Math.floor((now - fireAt) / 1000));
      const remaining = Math.max(0, totalSec - elapsed);
      const pct       = Math.min(100, Math.round((elapsed / totalSec) * 100));
      const m = Math.floor(remaining / 60), s = remaining % 60;
      const countdownEl = document.getElementById(`countdown-${ev.id}`);
      const progressEl  = document.getElementById(`progress-${ev.id}`);
      if (countdownEl) countdownEl.textContent = `${m}:${s.toString().padStart(2,"0")}`;
      if (progressEl)  progressEl.style.width  = pct + "%";
      if (remaining === 0) {
        if (countdownEl) { countdownEl.textContent = "ENDED"; countdownEl.style.color = "var(--text-hint)"; }
        // Write ended_at if not already done
        if (!ev._endedLogged) {
          ev._endedLogged = true;
          supabasePatch(`schedule_queue?id=eq.${ev.id}`, {
            status:   "ended",
            ended_at: new Date().toISOString()
          }).catch(e => console.warn("ended_at write:", e.message));
        }
      }
    });
  }, 1000);
}

async function liveOptOut(eventName, deviceUID) {
  const device = DEVICES.find(d => d.uid === deviceUID);
  if (!confirm(`Opt out ${device?.name || deviceUID} from "${eventName}"?\n\nA restore command will be sent to this device only.`)) return;
  try {
    await supabasePost("event_opt_outs", {
      event_name:   eventName,
      device_uid:   deviceUID,
      opt_out_type: "during_event",
      opted_out_at: new Date().toISOString(),
      opted_out_by: currentUser?.email || "unknown",
      restore_sent: true
    });
    const restoreHex = buildRestoreHex("all_on");
    await fetch(PROXY_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Device-UID": deviceUID },
      body: JSON.stringify({ body: { LC: restoreHex }, req: "note.add", sync: true })
    });
    setStatus("success", `✅ ${device?.name || deviceUID} opted out — restore sent`);
    await loadCurrentEvent();
  } catch(e) { setStatus("error", `Opt-out failed: ${e.message}`); }
}

async function liveUndoOptOut(eventName, deviceUID) {
  const device = DEVICES.find(d => d.uid === deviceUID);
  if (!confirm(`Remove opt-out for ${device?.name || deviceUID}?`)) return;
  try {
    await supabaseDelete("event_opt_outs", `event_name=eq.${encodeURIComponent(eventName)}&device_uid=eq.${encodeURIComponent(deviceUID)}`);
    setStatus("success", `Opt-out removed for ${device?.name || deviceUID}`);
    await loadCurrentEvent();
  } catch(e) { setStatus("error", `Failed: ${e.message}`); }
}

// ── Opt-Out Panel ─────────────────────────────────────────────────────────────
function openOptOutForEvent(eventName, fireAt) {
  // Show the opt-out panel
  const panel = document.getElementById("opt-out-panel");
  if (panel) panel.style.display = "block";

  // Populate and pre-select the event
  populateOptOutEventSelect().then(() => {
    const sel = document.getElementById("opt-out-event-select");
    if (sel) {
      sel.value = eventName;
      loadOptOutPanel();
    }
  });

  // Scroll panel into view
  panel?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function toggleOptOutPanel() {
  const panel = document.getElementById("opt-out-panel");
  if (!panel) return;
  const isOpen = panel.style.display !== "none";
  panel.style.display = isOpen ? "none" : "block";
  if (!isOpen) populateOptOutEventSelect();
}

async function populateOptOutEventSelect() {
  const sel = document.getElementById("opt-out-event-select");
  if (!sel) return;
  try {
    const rows = await supabaseGet("schedule_queue?order=fire_at.desc&limit=50&select=name,fire_at,status");
    sel.innerHTML = '<option value="">— Select Event —</option>';
    if (Array.isArray(rows)) rows.forEach(r => {
      const opt = document.createElement("option");
      opt.value = r.name;
      opt.textContent = `${r.name} (${new Date(r.fire_at).toLocaleDateString()})`;
      sel.appendChild(opt);
    });
  } catch(e) { console.error("populateOptOutEventSelect:", e); }
}

async function loadOptOutPanel() {
  const eventName = document.getElementById("opt-out-event-select")?.value;
  const listEl    = document.getElementById("opt-out-device-list");
  if (!listEl) return;
  if (!eventName) { listEl.innerHTML = '<div class="sched-empty">Select an event above.</div>'; return; }
  listEl.innerHTML = '<div class="sched-empty">Loading…</div>';

  try {
    const qRows = await supabaseGet(`schedule_queue?name=eq.${encodeURIComponent(eventName)}&order=fire_at.desc&limit=1`);
    const event = qRows?.[0];
    const fireAt = event ? new Date(event.fire_at) : null;
    const now    = new Date();
    const eventStarted = fireAt && now >= fireAt;

    // Resolve which devices were targeted by this event
    const targetType = event?.target_type || "all";
    const targetId   = event?.target_id   || "";
    let targetDevices = [];

    if (targetType === "all") {
      targetDevices = DEVICES.filter(d => !d.uid.startsWith("therm_") && !d.uid.startsWith("batt_") && !d.uid.startsWith("ev_") && !d.uid.startsWith("gen_"));
    } else if (targetType === "group") {
      const groupNum = parseInt((targetId || "").replace("group_", ""));
      targetDevices = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(groupNum));
    } else {
      // Single device
      const d = DEVICES.find(d => d.uid === targetId);
      if (d) targetDevices = [d];
    }

    if (!targetDevices.length) {
      listEl.innerHTML = '<div class="sched-empty">No devices found for this event target.</div>';
      return;
    }

    // Load existing opt-outs for this event
    let optOutMap = {};
    try {
      const optOutRows = await supabaseGet(`event_opt_outs?event_name=eq.${encodeURIComponent(eventName)}`);
      if (Array.isArray(optOutRows)) optOutRows.forEach(o => { optOutMap[o.device_uid] = o; });
    } catch(e) {}

    const targetLabel = targetType === "all" ? "All Devices"
      : targetType === "group" ? `Group ${targetId.replace("group_","")}`
      : targetDevices[0]?.name || targetId;

    listEl.innerHTML = `
      <div style="font-size:11px;color:var(--text-hint);margin-bottom:10px;">
        Event: <strong>${eventName}</strong> &bull; Target: <strong>${targetLabel}</strong> (${targetDevices.length} device${targetDevices.length !== 1 ? "s" : ""}) —
        ${fireAt ? (eventStarted ? '<span style="color:var(--green-dark);">In progress / completed</span>' : `Starts ${fireAt.toLocaleString()}`) : "Unknown timing"}
      </div>
      <div style="display:flex;flex-direction:column;gap:6px;">
        ${targetDevices.map(device => {
          const optOut    = optOutMap[device.uid];
          const isOptedOut = !!optOut;
          const isDuring  = optOut?.opt_out_type === "during_event";
          const optTime   = optOut ? new Date(optOut.opted_out_at).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}) : null;
          return `<div style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:${isOptedOut?"rgba(245,158,11,0.08)":"var(--surface)"};border-radius:var(--radius-sm);border:0.5px solid ${isOptedOut?"var(--amber)":"var(--border)"};flex-wrap:wrap;">
            <span style="font-size:12px;font-weight:600;flex:1;min-width:100px;">${device.name}</span>
            ${isOptedOut
              ? `<span style="font-size:11px;color:var(--amber);font-weight:600;">🚫 Opted Out ${isDuring?"(during)":"(pre-event)"}</span>
                 <span style="font-size:10px;color:var(--text-hint);">${optTime}</span>
                 <button onclick="undoOptOut('${eventName}','${device.uid}')" style="padding:3px 10px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;color:var(--text-hint);">Undo</button>`
              : `${!eventStarted ? `<button onclick="optOutDevice('${eventName}','${device.uid}','pre_event')" style="padding:4px 10px;border-radius:var(--radius-sm);border:0.5px solid var(--amber);background:rgba(245,158,11,0.1);color:var(--amber);font-size:11px;font-weight:600;cursor:pointer;">Pre-Event Opt-Out</button>` : ""}
                 <button onclick="optOutDevice('${eventName}','${device.uid}','during_event')" style="padding:4px 10px;border-radius:var(--radius-sm);border:0.5px solid var(--red);background:rgba(220,38,38,0.08);color:var(--red);font-size:11px;font-weight:600;cursor:pointer;">${eventStarted?"Opt Out Now":"Opt Out During Event"}</button>`
            }
          </div>`;
        }).join("")}
      </div>`;
  } catch(e) {
    listEl.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error: ${e.message}</div>`;
  }
}

async function optOutDevice(eventName, deviceUID, optOutType) {
  const device = DEVICES.find(d => d.uid === deviceUID);
  if (!confirm(`Opt out ${device?.name || deviceUID} from "${eventName}"?\n\n${optOutType === "during_event" ? "Restore command will be sent to this device only." : "Device will be skipped when event fires."}`)) return;
  try {
    await supabasePost("event_opt_outs", {
      event_name:   eventName,
      device_uid:   deviceUID,
      opt_out_type: optOutType,
      opted_out_at: new Date().toISOString(),
      opted_out_by: currentUser?.email || "unknown",
      restore_sent: optOutType === "during_event"
    });
    if (optOutType === "during_event") {
      const restoreHex = buildRestoreHex("all_on");
      await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": deviceUID },
        body: JSON.stringify({ body: { LC: restoreHex }, req: "note.add", sync: true })
      });
      const optRows = await supabaseGet(`event_opt_outs?event_name=eq.${encodeURIComponent(eventName)}&device_uid=eq.${encodeURIComponent(deviceUID)}&limit=1`);
      if (optRows?.[0]?.id) await supabasePatch(`event_opt_outs?id=eq.${optRows[0].id}`, { restore_sent: true, restore_sent_at: new Date().toISOString(), restore_hex: restoreHex });
      setStatus("success", `✅ ${device?.name || deviceUID} opted out — restore sent`);
    } else {
      setStatus("success", `✅ ${device?.name || deviceUID} pre-event opt-out recorded`);
    }
    await loadOptOutPanel();
  } catch(e) { setStatus("error", `Opt-out failed: ${e.message}`); console.error("optOutDevice:", e); }
}

async function undoOptOut(eventName, deviceUID) {
  const device = DEVICES.find(d => d.uid === deviceUID);
  if (!confirm(`Remove opt-out for ${device?.name || deviceUID}?`)) return;
  try {
    await supabaseDelete("event_opt_outs", `event_name=eq.${encodeURIComponent(eventName)}&device_uid=eq.${encodeURIComponent(deviceUID)}`);
    setStatus("success", `Opt-out removed for ${device?.name || deviceUID}`);
    await loadOptOutPanel();
  } catch(e) { setStatus("error", `Failed to remove opt-out: ${e.message}`); }
}

// ── BUBBLE-UP SCHEDULE ENGINE ────────────────────────────────────────────────
// Rules are stored in localStorage and evaluated every minute
// Each rule: { id, label, condition, days, intervalMins, enabled }
// Conditions: 'peak_season_peak_hours', 'peak_season_offpeak', 'peak_season_weekend',
//             'offseason_weekday', 'offseason_weekend', 'always'
// Days: 'weekday', 'weekend', 'all'

const BUBBLE_SCHED_KEY = "bubble_up_schedule_v1";
let bubbleRules = [];
let bubbleSeasonConfig = {
  summer: { start: "06/01", end: "09/30", peakStart: 14, peakEnd: 19,  enabled: true },
  winter: { start: "12/01", end: "02/28", peakStart: 6,  peakEnd: 21,  enabled: true }
};
let bubbleCheckInterval = null;
let bubbleManualOverrideUntil = null; // timestamp when manual override expires

const BUBBLE_CONDITIONS = [
  { value: "peak_season_peak_hours", label: "DR Season (Either) — Peak Hours" },
  { value: "peak_season_offpeak",    label: "DR Season (Either) — Off-Peak Hours" },
  { value: "peak_season_weekend",    label: "DR Season (Either) — Weekend" },
  { value: "summer_peak_hours",      label: "Summer Season — Peak Hours" },
  { value: "summer_offpeak",         label: "Summer Season — Off-Peak" },
  { value: "winter_peak_hours",      label: "Winter Season — Peak Hours" },
  { value: "winter_offpeak",         label: "Winter Season — Off-Peak" },
  { value: "offseason_weekday",      label: "Off-Season — Weekday" },
  { value: "offseason_weekend",      label: "Off-Season — Weekend" },
  { value: "overnight",              label: "Overnight (10 PM – 6 AM)" },
  { value: "always",                 label: "Always (catch-all)" },
];

const DEFAULT_RULES = [
  { id:1, label:"DR Season Peak Hours",    condition:"peak_season_peak_hours", days:"weekday", intervalMins:15,  enabled:true },
  { id:2, label:"DR Season Off-Peak",      condition:"peak_season_offpeak",    days:"weekday", intervalMins:30,  enabled:true },
  { id:3, label:"DR Season Weekend",       condition:"peak_season_weekend",    days:"weekend", intervalMins:60,  enabled:true },
  { id:4, label:"Off-Season Weekday",      condition:"offseason_weekday",      days:"weekday", intervalMins:240, enabled:true },
  { id:5, label:"Overnight / Off-Hours",   condition:"overnight",              days:"all",     intervalMins:720, enabled:true },
  { id:6, label:"Off-Season Weekend",      condition:"offseason_weekend",      days:"weekend", intervalMins:720, enabled:true },
];

function loadBubbleSchedule() {
  try {
    const saved = localStorage.getItem(BUBBLE_SCHED_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      bubbleRules = data.rules || DEFAULT_RULES;
      bubbleSeasonConfig = data.season || bubbleSeasonConfig;
    } else {
      bubbleRules = [...DEFAULT_RULES];
    }
  } catch(e) { bubbleRules = [...DEFAULT_RULES]; }

  // Populate summer season inputs
  const sumStart   = document.getElementById("summer-start");
  const sumEnd     = document.getElementById("summer-end");
  const sumPkStart = document.getElementById("summer-peak-start");
  const sumPkEnd   = document.getElementById("summer-peak-end");
  const sumEnabled = document.getElementById("summer-enabled");
  if (sumStart)   sumStart.value   = bubbleSeasonConfig.summer?.start    || "06/01";
  if (sumEnd)     sumEnd.value     = bubbleSeasonConfig.summer?.end      || "09/30";
  if (sumPkStart) sumPkStart.value = String(bubbleSeasonConfig.summer?.peakStart || 14);
  if (sumPkEnd)   sumPkEnd.value   = String(bubbleSeasonConfig.summer?.peakEnd   || 19);
  if (sumEnabled) sumEnabled.checked = bubbleSeasonConfig.summer?.enabled !== false;

  // Populate winter season inputs
  const winStart   = document.getElementById("winter-start");
  const winEnd     = document.getElementById("winter-end");
  const winPkStart = document.getElementById("winter-peak-start");
  const winPkEnd   = document.getElementById("winter-peak-end");
  const winEnabled = document.getElementById("winter-enabled");
  if (winStart)   winStart.value   = bubbleSeasonConfig.winter?.start    || "12/01";
  if (winEnd)     winEnd.value     = bubbleSeasonConfig.winter?.end      || "02/28";
  if (winPkStart) winPkStart.value = String(bubbleSeasonConfig.winter?.peakStart || 6);
  if (winPkEnd)   winPkEnd.value   = String(bubbleSeasonConfig.winter?.peakEnd   || 21);
  if (winEnabled) winEnabled.checked = bubbleSeasonConfig.winter?.enabled !== false;

  renderBubbleRules();
  evaluateAndShowCurrentRule();
}

function saveBubbleSchedule() {
  // Read summer season config
  bubbleSeasonConfig.summer = {
    start:     document.getElementById("summer-start")?.value    || "06/01",
    end:       document.getElementById("summer-end")?.value      || "09/30",
    peakStart: parseInt(document.getElementById("summer-peak-start")?.value || "14"),
    peakEnd:   parseInt(document.getElementById("summer-peak-end")?.value   || "19"),
    enabled:   document.getElementById("summer-enabled")?.checked !== false
  };
  // Read winter season config
  bubbleSeasonConfig.winter = {
    start:     document.getElementById("winter-start")?.value    || "12/01",
    end:       document.getElementById("winter-end")?.value      || "02/28",
    peakStart: parseInt(document.getElementById("winter-peak-start")?.value || "6"),
    peakEnd:   parseInt(document.getElementById("winter-peak-end")?.value   || "21"),
    enabled:   document.getElementById("winter-enabled")?.checked !== false
  };

  // Read rules from DOM
  bubbleRules = bubbleRules.map(r => {
    const cond = document.getElementById(`rule-cond-${r.id}`)?.value || r.condition;
    const days = document.getElementById(`rule-days-${r.id}`)?.value || r.days;
    const mins = parseInt(document.getElementById(`rule-mins-${r.id}`)?.value || r.intervalMins);
    const enbl = document.getElementById(`rule-enbl-${r.id}`)?.checked ?? r.enabled;
    return { ...r, condition: cond, days, intervalMins: mins, enabled: enbl };
  });

  localStorage.setItem(BUBBLE_SCHED_KEY, JSON.stringify({ rules: bubbleRules, season: bubbleSeasonConfig }));

  // Evaluate current rule and apply via Assignment Command
  const match = evaluateAndShowCurrentRule();
  if (match) {
    // Send Assignment Command to all real devices
    const realDevices = DEVICES.filter(d => !d.uid.includes('PLACEHOLDER'));
    showBubbleStatus(`Applying ${match.intervalMins} min (${match.label}) to ${realDevices.length} device(s)...`, "ok");
    Promise.all(realDevices.map(d => setBubbleUp(d.uid, d.id, match.intervalMins)))
      .then(() => showBubbleStatus(`✅ Saved & applied — ${match.intervalMins} min (${match.label})`, "ok"));
  } else {
    showBubbleStatus("✅ Schedule saved. No matching rule for current time — no command sent.", "ok");
  }
}

function renderBubbleRules() {
  const list = document.getElementById("bubble-rules-list");
  if (!list) return;
  list.innerHTML = bubbleRules.map((r, idx) => `
    <div style="display:grid;grid-template-columns:16px 1fr 120px 80px auto;gap:8px;align-items:center;padding:8px 0;border-bottom:0.5px solid var(--border);">
      <input type="checkbox" id="rule-enbl-${r.id}" ${r.enabled?"checked":""} style="cursor:pointer;" />
      <select id="rule-cond-${r.id}" class="sched-select" style="font-size:11px;">
        ${BUBBLE_CONDITIONS.map(c => `<option value="${c.value}" ${c.value===r.condition?"selected":""}>${c.label}</option>`).join("")}
      </select>
      <select id="rule-days-${r.id}" class="sched-select" style="font-size:11px;">
        <option value="all"     ${r.days==="all"    ?"selected":""}>All Days</option>
        <option value="weekday" ${r.days==="weekday"?"selected":""}>Weekday</option>
        <option value="weekend" ${r.days==="weekend"?"selected":""}>Weekend</option>
      </select>
      <div style="display:flex;align-items:center;gap:4px;">
        <input type="number" id="rule-mins-${r.id}" value="${r.intervalMins}" min="1" max="1440"
          style="width:55px;padding:4px 6px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:12px;" />
        <span style="font-size:10px;color:var(--text-hint);">min</span>
      </div>
      <button onclick="deleteBubbleRule(${r.id})" style="background:none;border:none;color:var(--red);cursor:pointer;font-size:16px;padding:0 4px;">×</button>
    </div>`
  ).join("");
}

function addBubbleRule() {
  const newId = Math.max(0, ...bubbleRules.map(r => r.id)) + 1;
  bubbleRules.push({ id: newId, label: "New Rule", condition: "always", days: "all", intervalMins: 60, enabled: true });
  renderBubbleRules();
}

function deleteBubbleRule(id) {
  bubbleRules = bubbleRules.filter(r => r.id !== id);
  renderBubbleRules();
}

function isInDRSeason(now) {
  const mmdd = String(now.getMonth()+1).padStart(2,"0") + "/" + String(now.getDate()).padStart(2,"0");
  const { summer, winter } = bubbleSeasonConfig;

  // Check summer season
  if (summer?.enabled && summer.start && summer.end) {
    if (mmdd >= summer.start && mmdd <= summer.end) return "summer";
  }

  // Check winter season — may span year boundary (e.g. 12/01 – 02/28)
  if (winter?.enabled && winter.start && winter.end) {
    if (winter.start > winter.end) {
      // Spans year boundary
      if (mmdd >= winter.start || mmdd <= winter.end) return "winter";
    } else {
      if (mmdd >= winter.start && mmdd <= winter.end) return "winter";
    }
  }
  return null; // off-season
}

function isWeekend(now) {
  const day = now.getDay();
  return day === 0 || day === 6;
}

function isOvernightHours(now) {
  const h = now.getHours();
  return h >= 22 || h < 6;
}

function isPeakHours(now) {
  const h      = now.getHours();
  const season = isInDRSeason(now);
  if (season === "summer") {
    return h >= bubbleSeasonConfig.summer.peakStart && h < bubbleSeasonConfig.summer.peakEnd;
  }
  if (season === "winter") {
    return h >= bubbleSeasonConfig.winter.peakStart && h < bubbleSeasonConfig.winter.peakEnd;
  }
  return false;
}

function evaluateRules(now) {
  const seasonVal = isInDRSeason(now);
  const inSeason  = !!seasonVal;
  const weekend   = isWeekend(now);
  const overnight = isOvernightHours(now);
  const peak      = isPeakHours(now);

  for (const rule of bubbleRules) {
    if (!rule.enabled) continue;

    // Check days match
    if (rule.days === "weekday" && weekend) continue;
    if (rule.days === "weekend" && !weekend) continue;

    // Check condition match
    switch (rule.condition) {
      case "peak_season_peak_hours": if (!inSeason || !peak || overnight) continue; break;
      case "peak_season_offpeak":    if (!inSeason || peak  || overnight) continue; break;
      case "peak_season_weekend":    if (!inSeason || !weekend)           continue; break;
      case "summer_peak_hours":      if (seasonVal !== "summer" || !peak || overnight) continue; break;
      case "summer_offpeak":         if (seasonVal !== "summer" || peak  || overnight) continue; break;
      case "winter_peak_hours":      if (seasonVal !== "winter" || !peak || overnight) continue; break;
      case "winter_offpeak":         if (seasonVal !== "winter" || peak  || overnight) continue; break;
      case "offseason_weekday":      if (inSeason  || weekend)            continue; break;
      case "offseason_weekend":      if (inSeason  || !weekend)           continue; break;
      case "overnight":              if (!overnight)                       continue; break;
      case "always":                                                                 break;
    }
    return rule; // First match wins
  }
  return null;
}

function evaluateAndShowCurrentRule() {
  const now   = new Date();
  const match = evaluateRules(now);
  const el    = document.getElementById("bubble-current-rule");
  if (!el) return match;

  if (match) {
    const season = isInDRSeason(now);
    const seasonLabel = season === "summer" ? "☀️ Summer Season"
      : season === "winter" ? "❄️ Winter Season" : "Off-Season";
    const overrideActive = bubbleManualOverrideUntil && Date.now() < bubbleManualOverrideUntil;
    const overrideLabel = overrideActive
      ? `<span style="color:var(--amber);font-weight:500;margin-left:8px;">⏸ Auto-schedule paused (manual override active ${Math.round((bubbleManualOverrideUntil-Date.now())/60000)} min remaining)</span>`
      : "";
    el.innerHTML = `<span style="color:var(--green-dark);font-weight:600;">▶ ${match.label}</span> — ${match.intervalMins} min interval
      <span style="margin-left:8px;font-size:10px;color:var(--text-hint);">${seasonLabel} &bull; ${isWeekend(now)?"Weekend":"Weekday"} &bull; ${isPeakHours(now)?"Peak Hours":"Off-Peak"}</span>${overrideLabel}`;
  } else {
    el.innerHTML = `<span style="color:var(--text-hint);">No matching rule — using firmware default</span>`;
  }
  return match;
}

// Bubble-up scheduler — advisory only, updates display but does NOT auto-send commands
// User must click "Save & Apply" to push changes to devices
function startBubbleScheduler() {
  if (bubbleCheckInterval) clearInterval(bubbleCheckInterval);
  bubbleCheckInterval = setInterval(() => {
    // Just update the display — no auto-sending of Assignment Commands
    evaluateAndShowCurrentRule();
  }, 60 * 1000); // Check every 60 seconds for display update only
}

// ── BUBBLE-UP INTERVAL CONTROL ───────────────────────────────────────────────
// All Notehub API calls routed through Worker to avoid CORS + hide token

// Store known intervals per device (loaded from Notehub)
const deviceIntervals = {};

async function initEventStats() {
  await loadEventStatsOverview();
  await populateParticipationEventSelect();
}

async function loadEventStatsOverview() {
  try {
    const rows = await supabaseGet("schedule_queue?order=fire_at.desc&limit=500");
    if (!Array.isArray(rows) || rows.length === 0) return;

    // Total events (unique names)
    const uniqueEvents = new Set(rows.filter(r => r.name).map(r => r.name));
    document.getElementById("stats-total-events").textContent = uniqueEvents.size;

    // Total event hours
    const totalMins = rows.reduce((sum, r) => sum + (r.duration_minutes || 0), 0);
    const totalHrs  = (totalMins / 60).toFixed(1);
    document.getElementById("stats-total-hours").textContent = totalHrs + "h";

    // Avg participation — placeholder until we compute per event
    document.getElementById("stats-avg-participation").textContent = "—";
  } catch(e) { console.error("loadEventStatsOverview:", e); }
}

async function loadEventHistory() {
  const container = document.getElementById("event-history-container");
  if (!container) return;
  container.innerHTML = `<div class="sched-empty">Loading...</div>`;
  const rangeHours = document.getElementById("stats-range")?.value;
  try {
    // Order by fired_at (when sent) not fire_at (scheduled time)
    // Use OR logic — match on either fired_at or fire_at within range
    let query = `schedule_queue?order=fired_at.desc.nullslast&limit=500`;
    if (rangeHours) {
      const since = new Date(Date.now() - parseInt(rangeHours)*60*60*1000).toISOString();
      // Filter by fired_at (when actually sent) falling within range
      query += `&fired_at=gte.${since}`;
    }
    const rows = await supabaseGet(query);
    if (!rows || rows.length === 0) {
      // Fallback: try without date filter to see if any rows exist at all
      const allRows = await supabaseGet(`schedule_queue?order=fired_at.desc.nullslast&limit=10`);
      if (!allRows || allRows.length === 0) {
        container.innerHTML = `<div class="sched-empty">No events found in schedule_queue table.</div>`;
      } else {
        container.innerHTML = `<div class="sched-empty" style="color:var(--amber);">No events found in selected time range. ${allRows.length} total events exist — try selecting a wider range or "All time".</div>`;
      }
      return;
    }

    const statusIcon = { sent:"📤", received:"📥", started:"▶️", ended:"✅", cancelled:"🚫", rejected:"❌", pending:"🕐" };
    const statusClass = { sent:"sent", received:"received", started:"started", ended:"ended", cancelled:"cancelled", rejected:"rejected" };

    // Render as clickable pill-style rows
    container.innerHTML = `<div style="display:flex;flex-direction:column;gap:6px;">` +
      rows.map(r => {
        const fireAt     = r.fire_at ? new Date(r.fire_at) : null;
        const durationMs = (r.duration_minutes || 0) * 60 * 1000;
        const endAt      = fireAt ? new Date(fireAt.getTime() + durationMs) : null;
        const sc         = statusClass[r.status] || "sent";
        const icon       = statusIcon[r.status]  || "📋";
        const fireStr    = fireAt ? fireAt.toLocaleString() : "—";
        const endStr     = endAt  ? endAt.toLocaleString()  : "—";
        const dur        = r.duration_minutes ? formatDuration(r.duration_minutes) : "—";

        // Encode item for modal
        const rData = encodeURIComponent(JSON.stringify({ type:"queue", item:r }));

        return `<div class="queue-item ${sc}" style="cursor:pointer;" onclick="showEventDetail(JSON.parse(decodeURIComponent('${rData}')))">
          <div class="queue-info">
            <div class="queue-name">${r.name || r.target_name || "Unnamed Event"} &bull; ${r.target_name || "—"} &bull; ${RELAY_ACTION_LABELS[r.relay_action] || r.relay_action || "—"}</div>
            <div class="queue-detail">${icon} ${r.status} &bull; 📅 ${fireStr} &bull; ⏱ ${dur} &bull; ends ${endStr}</div>
            <div class="queue-detail" style="color:var(--text-hint);margin-top:1px;">Mode: ${(r.lc_mode||"—").toUpperCase()} &bull; Strategy: ${r.lc_strategy||"—"} &bull; Duration: ${r.duration_minutes ? formatDuration(r.duration_minutes) : "—"} &nbsp;|&nbsp; <span style="color:var(--blue);text-decoration:underline;">Click to view hex &amp; details</span></div>
          </div>
          <span class="queue-status ${sc}">${r.status}</span>
        </div>`;
      }).join("") + `</div>`;
  } catch(e) { container.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error: ${e.message}</div>`; }
}

async function exportEventHistory() {
  const rangeHours = document.getElementById("stats-range")?.value;
  setStatus("sending", "Preparing event history export...");
  try {
    let query = `schedule_queue?order=fire_at.desc&limit=5000`;
    if (rangeHours) {
      const since = new Date(Date.now() - parseInt(rangeHours)*60*60*1000).toISOString();
      query += `&fire_at=gte.${since}`;
    }
    const rows = await supabaseGet(query);
    if (!rows || rows.length === 0) { setStatus("error", "No events to export."); return; }
    const headers = ["Event Name","Target","Action","Mode","Strategy","Reps","Duration","Scheduled","Sent","Status"];
    const csvRows = rows.map(r => [
      r.name || "",
      r.target_name || "",
      RELAY_ACTION_LABELS[r.relay_action] || r.relay_action || "",
      (r.lc_mode || "").toUpperCase(),
      r.lc_strategy || "",
      r.lc_reps || "",
      r.duration_minutes ? formatDuration(r.duration_minutes) : "",
      r.fire_at   ? new Date(r.fire_at).toLocaleString()   : "",
      r.fired_at  ? new Date(r.fired_at).toLocaleString()  : "",
      r.status || ""
    ].map(v => `"${v}"`).join(","));
    const csv  = [headers.join(","), ...csvRows].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement("a");
    a.href = url; a.download = "event_history.csv"; a.click();
    URL.revokeObjectURL(url);
    setStatus("ready", `Exported ${rows.length} events.`);
  } catch(e) { setStatus("error", "Export failed."); }
}

async function initWeatherTab() {
  await initWeather();
  // Set default date range for backfill picker: yesterday → today
  const fromEl = document.getElementById("backfill-from");
  const toEl   = document.getElementById("backfill-to");
  if (fromEl && !fromEl.value) {
    const today     = new Date();
    const yesterday = new Date(today - 24 * 60 * 60 * 1000);
    const fmt = d => d.toISOString().split("T")[0];
    // Min = 7 days ago, max = today
    const minDate = fmt(new Date(today - 7 * 24 * 60 * 60 * 1000));
    fromEl.value = fmt(yesterday);
    fromEl.min   = minDate;
    fromEl.max   = fmt(today);
    if (toEl) {
      toEl.value = fmt(today);
      toEl.min   = minDate;
      toEl.max   = fmt(today);
    }
  }
}

async function initSettingsTab() {
  await loadBubbleUpIntervals();
  await refreshBubbleStatus();
  loadBubbleSchedule();
  startBubbleScheduler();
  // Auto-refresh status every 2 minutes while on settings tab
  if (window._bubbleStatusInterval) clearInterval(window._bubbleStatusInterval);
  window._bubbleStatusInterval = setInterval(async () => {
    const settingsTab = document.getElementById("tab-settings");
    if (settingsTab && settingsTab.classList.contains("active")) {
      await refreshBubbleStatus();
    }
  }, 2 * 60 * 1000);
}

async function refreshBubbleStatus() {
  // 1. Configured interval — from Notehub env vars (what was SET)
  const configuredEl  = document.getElementById("global-configured-interval");
  const configLabelEl = document.getElementById("global-configured-label");

  // 2. Actual interval — calculated from last 2 bubble-up timestamps in Supabase
  const actualEl      = document.getElementById("global-actual-interval");
  const actualLabelEl = document.getElementById("global-actual-label");

  // Show last known configured interval from deviceIntervals cache
  try {
    const firstDevice = DEVICES.find(d => !d.uid.includes('PLACEHOLDER')) || DEVICES[0];
    const cachedMins = deviceIntervals[firstDevice.uid];
    if (configuredEl) {
      if (cachedMins) {
        configuredEl.textContent = formatIntervalMins(parseInt(cachedMins));
        if (configLabelEl) configLabelEl.textContent = `Last set: ${cachedMins} min (via Assignment Command)`;
      } else {
        configuredEl.textContent = "Unknown";
        if (configLabelEl) configLabelEl.textContent = "Set an interval to track it here";
      }
    }
  } catch(e) {
    if (configuredEl) configuredEl.textContent = "—";
  }

  // Calculate actual interval from last 2 readings for first online device
  try {
    for (const device of DEVICES) {
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=2`
      );
      if (Array.isArray(rows) && rows.length === 2) {
        const t1 = new Date(rows[0].recorded_at);
        const t2 = new Date(rows[1].recorded_at);
        const diffMs   = t1 - t2;
        const diffMins = Math.round(diffMs / 60000);
        if (diffMins > 0 && diffMins < 1440) {
          if (actualEl) actualEl.textContent = formatIntervalMins(diffMins);
          if (actualLabelEl) {
            const devName = device.name;
            const timeAgo = Math.round((Date.now() - t1) / 60000);
            actualLabelEl.textContent = `${devName} — last seen ${timeAgo < 1 ? "< 1 min" : timeAgo + " min"} ago`;
          }
          break;
        }
      }
    }
    if (actualEl && actualEl.textContent === "Loading...") {
      actualEl.textContent = "No data";
      if (actualLabelEl) actualLabelEl.textContent = "No recent bubble-ups found";
    }
  } catch(e) {
    if (actualEl) actualEl.textContent = "—";
  }
}

function formatIntervalMins(mins) {
  if (!mins || isNaN(mins)) return "—";
  if (mins < 60) return `${mins} min`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m > 0 ? `${h} hr ${m} min` : `${h} hr`;
}

async function loadBubbleUpIntervals() {
  const tbody = document.getElementById("bubble-up-device-rows");
  if (!tbody) return;
  tbody.innerHTML = DEVICES.map(d =>
    `<tr>
      <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">
        <div style="font-weight:500;">${d.name}</div>
        <div style="font-size:10px;color:var(--text-hint);font-family:monospace;">${d.uid}</div>
      </td>
      <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">
        <span id="bubble-current-${d.id}">Loading...</span>
      </td>
      <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">
        <input type="number" id="bubble-mins-${d.id}" min="1" max="1440" placeholder="mins"
          style="width:70px;padding:4px 6px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:12px;" />
      </td>
      <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">
        <button class="queue-refresh" onclick="setBubbleUp('${d.uid}','${d.id}')">Set</button>
        <button class="queue-refresh" style="color:var(--text-secondary);border-color:var(--border-md);margin-left:4px;" onclick="clearBubbleUp('${d.uid}','${d.id}')">Clear</button>
      </td>
    </tr>`
  ).join("");

  // Read actual interval from last 2 bubble-up timestamps per device
  for (const d of DEVICES) {
    try {
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(d.uid)}&order=recorded_at.desc&limit=2`
      );
      const el = document.getElementById(`bubble-current-${d.id}`);
      if (Array.isArray(rows) && rows.length === 2) {
        const diffMins = Math.round((new Date(rows[0].recorded_at) - new Date(rows[1].recorded_at)) / 60000);
        if (el && diffMins > 0 && diffMins < 1440) {
          el.textContent = `~${diffMins} min (measured)`;
          deviceIntervals[d.uid] = diffMins;
        } else if (el) { el.textContent = "Insufficient data"; }
      } else if (el) { el.textContent = "No recent data"; }
    } catch(e) {
      const el = document.getElementById(`bubble-current-${d.id}`);
      if (el) el.textContent = "—";
    }
  }
}

async function setBubbleUp(uid, deviceId, minutes) {
  const mins = minutes ?? document.getElementById(`bubble-mins-${deviceId}`)?.value;
  if (!mins || isNaN(mins) || parseInt(mins) < 1) {
    showBubbleStatus("Please enter a valid number of minutes.", "error"); return;
  }
  const minsInt = parseInt(mins);
  try {
    // Send Assignment Command 0x04 directly to device via data.qi
    // This writes to non-volatile memory — persists through reboots
    const assignHex = buildAssignBubbleUpHex(minsInt);
    console.log(`Sending bubble-up assignment to ${uid}: ${assignHex} (${minsInt} min)`);
    const payload = { body: { LC: assignHex }, req: "note.add", sync: true };
    const res = await fetch(PROXY_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Device-UID": uid },
      body: JSON.stringify(payload)
    });
    if (res.ok) {
      const el = document.getElementById(`bubble-current-${deviceId}`);
      if (el) el.textContent = `${minsInt} min (pending sync)`;
      deviceIntervals[uid] = minsInt;
      showBubbleStatus(`✅ ${DEVICES.find(d=>d.id===deviceId)?.name} — assignment command sent (${minsInt} min). Takes effect on next bubble-up.`, "ok");
    } else {
      const err = await res.text();
      console.error("setBubbleUp error:", res.status, err);
      showBubbleStatus(`❌ Error ${res.status}: ${err}`, "error");
    }
  } catch(e) {
    showBubbleStatus(`❌ Network error: ${e.message}`, "error");
  }
}

async function clearBubbleUp(uid, deviceId) {
  // Send assignment with 30 min to revert to factory default
  await setBubbleUp(uid, deviceId, 30);
  const el = document.getElementById(`bubble-current-${deviceId}`);
  if (el) el.textContent = "30 min (factory default)";
  deviceIntervals[uid] = 30;
  showBubbleStatus(`✅ ${DEVICES.find(d=>d.id===deviceId)?.name} reverted to 30 min factory default.`, "ok");
}

async function setAllBubbleUp() {
  const mins = document.getElementById("bubble-all-mins")?.value;
  if (!mins || isNaN(mins) || parseInt(mins) < 1) {
    showBubbleStatus("Please enter a valid number of minutes.", "error"); return;
  }
  showBubbleStatus(`Setting all devices to ${mins} min...`, "ok");
  for (const d of DEVICES) {
    await setBubbleUp(d.uid, d.id, mins);
  }
  showBubbleStatus(`✅ All devices set to ${mins} min — takes effect on next sync.`, "ok");
}

async function setEventMode() {
  const statusEl = document.getElementById("mode-status");
  if (statusEl) {
    statusEl.style.display = "block";
    statusEl.style.background = "var(--green-bg)";
    statusEl.style.color = "var(--green-dark)";
    statusEl.style.border = "0.5px solid var(--green)";
    statusEl.textContent = "🟢 Activating Event Mode — setting all devices to 5 min inbound & outbound...";
  }
  let successCount = 0;
  for (const d of DEVICES.filter(d => !d.uid.includes('PLACEHOLDER'))) {
    try {
      const assignHex = buildAssignBubbleUpHex(5);
      const payload = { body: { LC: assignHex }, req: "note.add", sync: true };
      const res = await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": d.uid },
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        successCount++;
        const outEl = document.getElementById(`bubble-current-${d.id}`);
        if (outEl) outEl.textContent = "5 min (Event Mode)";
      }
    } catch(e) { console.error("setEventMode error:", d.uid, e); }
  }
  // Pause auto-scheduler for 4 hours during event mode
  bubbleManualOverrideUntil = Date.now() + (4 * 60 * 60 * 1000);
  if (statusEl) {
    statusEl.textContent = `🟢 Event Mode active — ${successCount}/${DEVICES.length} devices set to 5 min. Auto-schedule paused 4 hrs.`;
  }
  showBubbleStatus(`🟢 Event Mode activated — 5 min inbound & outbound. Auto-schedule paused for 4 hours.`, "ok");
}

async function setNormalMode() {
  const statusEl = document.getElementById("mode-status");
  if (statusEl) {
    statusEl.style.display = "block";
    statusEl.style.background = "var(--surface2)";
    statusEl.style.color = "var(--text-primary)";
    statusEl.style.border = "0.5px solid var(--border-md)";
    statusEl.textContent = "⚙️ Activating Normal Mode — evaluating schedule and applying intervals...";
  }

  // Evaluate current bubble-up schedule rule
  const match = bubbleRules.length > 0 ? evaluateRules(new Date()) : null;
  const outboundMins = match ? String(match.intervalMins) : null;
  const ruleLabel = match ? match.label : "firmware default";

  let successCount = 0;
  for (const d of DEVICES) {
    try {
      const envVars = outboundMins
        ? { _sync_outbound_mins: outboundMins, _sync_inbound_mins: outboundMins }
        : {};  // Empty = clear vars, revert to firmware default

      const normalMins = outboundMins ? parseInt(outboundMins) : 30;
      const assignHex = buildAssignBubbleUpHex(normalMins);
      const payload = { body: { LC: assignHex }, req: "note.add", sync: true };
      const res = await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": d.uid },
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        successCount++;
        const outEl = document.getElementById(`bubble-current-${d.id}`);
        if (outEl) outEl.textContent = outboundMins ? `${outboundMins} min (${ruleLabel})` : "Firmware default";
      }
    } catch(e) { console.error("setNormalMode error:", d.uid, e); }
  }

  // Resume auto-scheduler
  bubbleManualOverrideUntil = null;
  if (statusEl) {
    statusEl.textContent = `⚙️ Normal Mode active — ${successCount}/${DEVICES.length} devices set to ${outboundMins ? outboundMins + " min" : "firmware default"} (${ruleLabel}). Auto-schedule resumed.`;
    statusEl.style.color = "var(--text-secondary)";
  }
  showBubbleStatus(`⚙️ Normal Mode activated — auto-schedule resumed (${ruleLabel}).`, "ok");
}

async function applyBubbleUpPreset(mins) {
  if (mins === null) {
    // Clear override and revert to firmware default
    bubbleManualOverrideUntil = null;
    showBubbleStatus("Clearing all device intervals — reverting to firmware default...", "ok");
    for (const d of DEVICES) await clearBubbleUp(d.uid, d.id);
    showBubbleStatus("✅ All devices reverted to firmware default. Auto-schedule resumed.", "ok");
  } else {
    // Set manual override for 2 hours to prevent scheduler from overwriting
    bubbleManualOverrideUntil = Date.now() + (2 * 60 * 60 * 1000);
    showBubbleStatus(`Applying ${mins} min preset to all devices... (auto-schedule paused 2 hrs)`, "ok");
    for (const d of DEVICES) await setBubbleUp(d.uid, d.id, mins);
    showBubbleStatus(`✅ All devices set to ${mins} min — takes effect on next sync. Auto-schedule paused for 2 hours.`, "ok");
  }
}

function showBubbleStatus(msg, type) {
  const el = document.getElementById("bubble-up-status");
  if (!el) return;
  el.textContent = msg;
  el.style.color = type === "error" ? "var(--red)" : "var(--green-dark)";
}

// ── WEATHER FORECAST ─────────────────────────────────────────────────────────
const WEATHER_LOC_KEY = "wx_location_demo_v1";
let wxLocationData = null;  // { name, lat, lon }
let wxForecastData = null;  // NWS forecast data
let wxSelectedDay  = null;  // index of selected day

async function initWeather() {
  try {
    const saved = localStorage.getItem(WEATHER_LOC_KEY);
    if (saved) {
      wxLocationData = JSON.parse(saved);
      showWeatherLocation();
      await fetchWeatherForecast(); // also calls renderHeaderWeather
    }
  } catch(e) {}
}

async function initHeaderWeather() {
  loadSavedNWSStation();
  initWxExportDates();
  // Called on page load — fetch weather if location is saved
  try {
    const saved = localStorage.getItem(WEATHER_LOC_KEY);
    if (saved) {
      wxLocationData = JSON.parse(saved);
      await fetchWeatherForecast();
    }
  } catch(e) {}
}

async function searchWeatherLocation() {
  const input = document.getElementById("weather-location-input");
  const query = input?.value?.trim();
  if (!query) return;
  const container = document.getElementById("weather-forecast-container");
  container.innerHTML = `<div class="wx-loading">🔍 Searching for "${query}"...</div>`;
  try {
    let lat, lon, locationName;
    const isZip = /^\d{5}(-\d{4})?$/.test(query);

    if (isZip) {
      // ZIP code — use Zippopotam.us (free, no key needed)
      const zipRes  = await fetch(`https://api.zippopotam.us/us/${query.slice(0,5)}`);
      if (!zipRes.ok) {
        container.innerHTML = `<div class="wx-loading" style="color:var(--red);">ZIP code not found. Try a city name or "City, ST".</div>`;
        return;
      }
      const zipData = await zipRes.json();
      const place   = zipData.places?.[0];
      if (!place) {
        container.innerHTML = `<div class="wx-loading" style="color:var(--red);">ZIP code not found.</div>`;
        return;
      }
      lat          = parseFloat(place.latitude);
      lon          = parseFloat(place.longitude);
      locationName = `${place["place name"]}, ${place["state abbreviation"]} ${query.slice(0,5)}`;

    } else {
      // City/State — split on comma so Open-Meteo only sees the city name
      const parts    = query.split(/,\s*/);
      const cityPart = parts[0].trim();
      const statePart = parts[1]?.trim() || "";

      // Search Open-Meteo with just the city name, then filter by state
      const geoRes  = await fetch(
        `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(cityPart)}&count=10&language=en&format=json`
      );
      const geoData = await geoRes.json();
      let result = null;

      if (geoData?.results?.length) {
        if (statePart) {
          const stateUpper = statePart.toUpperCase();
          result = geoData.results.find(r =>
            r.country_code === "US" && (
              r.admin1?.toUpperCase().startsWith(stateUpper) ||
              r.admin1_code?.toUpperCase() === stateUpper ||
              r.admin1?.toUpperCase() === stateUpper
            )
          ) || geoData.results.find(r => r.country_code === "US")
            || geoData.results[0];
        } else {
          result = geoData.results.find(r => r.country_code === "US") || geoData.results[0];
        }
      }

      // Fallback to Nominatim (OpenStreetMap) if Open-Meteo found nothing
      if (!result) {
        const nomRes  = await fetch(
          `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=1&countrycodes=us`,
          { headers: { "Accept-Language": "en", "User-Agent": "LoadControlDashboard/1.0" } }
        );
        const nomData = await nomRes.json();
        if (nomData?.[0]) {
          lat          = parseFloat(nomData[0].lat);
          lon          = parseFloat(nomData[0].lon);
          locationName = nomData[0].display_name.split(",").slice(0,3).join(",").trim();
        } else {
          container.innerHTML = `<div class="wx-loading" style="color:var(--red);">Location not found. Try "Oklahoma City, OK" or a 5-digit ZIP code.</div>`;
          return;
        }
      } else {
        lat          = result.latitude;
        lon          = result.longitude;
        locationName = [result.name, result.admin1, result.country_code].filter(Boolean).join(", ");
      }
    }

    wxLocationData = { name: locationName, lat, lon };
    localStorage.setItem(WEATHER_LOC_KEY, JSON.stringify(wxLocationData));
    const prevLocation = JSON.parse(localStorage.getItem(WEATHER_LOC_KEY) || "{}");
    const locationChanged = Math.abs((prevLocation.lat||0) - lat) > 0.1
                         || Math.abs((prevLocation.lon||0) - lon) > 0.1;
    if (locationChanged) {
      try { localStorage.removeItem(NWS_STATION_KEY); } catch(e) {}
      nwsStationId   = null;
      nwsStationName = null;
    } else {
      loadSavedNWSStation();
    }
    startNWSPoller();
    showWeatherLocation();
    await fetchWeatherForecast();
  } catch(e) {
    container.innerHTML = `<div class="wx-loading" style="color:var(--red);">Error searching location: ${e.message}</div>`;
  }
}

function showWeatherLocation() {
  const display = document.getElementById("weather-location-display");
  const name    = document.getElementById("weather-location-name");
  const input   = document.getElementById("weather-location-input");
  if (display) display.style.display = "block";
  if (name)    name.textContent = wxLocationData?.name || "Unknown";
  if (input)   input.style.display = "none";
  const searchBtn = document.querySelector('#weather-card .queue-refresh');
  if (searchBtn) searchBtn.style.display = "none";
}

let headerWxSelectedDay = null;

function renderHeaderWeather() {
  const strip = document.getElementById("header-wx-strip");
  const daysEl = document.getElementById("header-wx-days");
  const locEl  = document.getElementById("header-wx-loc");
  if (!strip || !daysEl) return;

  if (!wxForecastData?.daily || !wxLocationData) {
    strip.style.display = "none";
    return;
  }

  const { time, temperature_2m_max, temperature_2m_min, weathercode } = wxForecastData.daily;

  // Show only first 7 days in header
  const days7 = time.slice(0, 7);
  daysEl.innerHTML = days7.map((dateStr, i) => {
    const d    = new Date(dateStr + "T12:00:00");
    const name = i === 0 ? "Today" : d.toLocaleDateString("en-US", { weekday: "short" });
    const sel  = headerWxSelectedDay === i;
    return `<div class="header-wx-day${sel ? " selected" : ""}" onclick="toggleHeaderHourly(${i})" style="cursor:pointer;${sel ? "border-color:var(--blue);background:var(--blue-bg);" : ""}">
      <div class="header-wx-day-name">${name}</div>
      <div class="header-wx-icon">${wxIcon(weathercode[i])}</div>
      <div class="header-wx-high">${Math.round(temperature_2m_max[i])}°</div>
      <div class="header-wx-low">${Math.round(temperature_2m_min[i])}°</div>
    </div>`;
  }).join("");

  if (locEl) locEl.textContent = `📍 ${wxLocationData.name}`;
  strip.style.display = "block";

  // Render or hide hourly panel
  renderHeaderHourly();
}

function toggleHeaderHourly(dayIndex) {
  headerWxSelectedDay = headerWxSelectedDay === dayIndex ? null : dayIndex;
  renderHeaderWeather();
}

function renderHeaderHourly() {
  const panel = document.getElementById("header-wx-hourly");
  if (!panel) return;

  if (headerWxSelectedDay === null || !wxForecastData?.hourly) {
    panel.style.display = "none";
    return;
  }

  const dateStr = wxForecastData.daily.time[headerWxSelectedDay];
  const { time, temperature_2m, weathercode } = wxForecastData.hourly;

  const dayHours = time.reduce((acc, t, i) => {
    if (t.startsWith(dateStr)) acc.push({ time: t, temp: temperature_2m[i], code: weathercode[i] });
    return acc;
  }, []);

  if (dayHours.length === 0) { panel.style.display = "none"; return; }

  const selDate  = new Date(dateStr + "T12:00:00");
  const dayLabel = headerWxSelectedDay === 0
    ? "Today"
    : selDate.toLocaleDateString("en-US", { weekday:"long", month:"short", day:"numeric" });

  panel.innerHTML = `
    <div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:0.05em;padding:4px 1rem 4px;text-align:center;">
      ${dayLabel} — Hourly Forecast
      <span style="font-size:10px;font-weight:400;color:var(--text-hint);margin-left:6px;">(click day again to close)</span>
    </div>
    <div style="display:flex;gap:6px;padding:4px 1rem 8px;overflow-x:auto;justify-content:center;flex-wrap:nowrap;">
      ${dayHours.map(h => {
        const hour = new Date(h.time).toLocaleTimeString("en-US", { hour:"numeric", hour12:true });
        return `<div style="display:flex;flex-direction:column;align-items:center;min-width:52px;padding:5px 8px;border-radius:var(--radius-sm);background:var(--surface);border:0.5px solid var(--border);flex-shrink:0;">
          <div style="font-size:10px;color:var(--text-hint);margin-bottom:2px;">${hour}</div>
          <div style="font-size:18px;line-height:1;margin:2px 0;">${wxIcon(h.code)}</div>
          <div style="font-size:13px;font-weight:700;color:var(--text-primary);">${Math.round(h.temp)}°</div>
          <div style="font-size:9px;color:var(--text-hint);margin-top:1px;text-align:center;line-height:1.2;">${wxDesc(h.code)}</div>
        </div>`;
      }).join("")}
    </div>`;
  panel.style.display = "block";
}

function clearWeatherLocation() {
  wxLocationData = null;
  wxForecastData = null;
  nwsStationId   = null;
  nwsStationName = null;
  nwsObsData     = null;
  stopNWSPoller();
  const nwsContainer = document.getElementById("nws-current-container");
  if (nwsContainer) nwsContainer.innerHTML = '<div class="sched-empty">Set a location in the forecast card below to load current conditions.</div>';
  const nwsStation = document.getElementById("nws-station-label");
  if (nwsStation) nwsStation.textContent = "";
  wxSelectedDay  = null;
  localStorage.removeItem(WEATHER_LOC_KEY);
  const display   = document.getElementById("weather-location-display");
  const container = document.getElementById("weather-forecast-container");
  const input     = document.getElementById("weather-location-input");
  const searchBtn = document.querySelector('#weather-card .queue-refresh');
  if (display)   display.style.display = "none";
  if (container) container.innerHTML = `<div class="sched-empty">Enter a location to see the forecast.</div>`;
  if (input)     { input.style.display = ""; input.value = ""; }
  if (searchBtn) searchBtn.style.display = "";
  // Hide header strip
  const strip = document.getElementById("header-wx-strip");
  if (strip) strip.style.display = "none";
}

async function fetchWeatherForecast() {
  if (!wxLocationData) return;
  const container = document.getElementById("weather-forecast-container");
  container.innerHTML = `<div class="wx-loading">☁️ Loading forecast for ${wxLocationData.name}...</div>`;
  try {
    const { lat, lon } = wxLocationData;
    // Open-Meteo free API — no key required
    const res = await fetch(
      `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
      `&daily=temperature_2m_max,temperature_2m_min,weathercode` +
      `&hourly=temperature_2m,weathercode,uv_index,precipitation_probability` +
      `&temperature_unit=fahrenheit&wind_speed_unit=mph&timezone=auto&forecast_days=14`
    );
    const data = await res.json();
    wxForecastData = data;
    wxSelectedDay  = null;
    headerWxSelectedDay = null;
    renderWeatherForecast();
    renderHeaderWeather(); // Update header strip
  } catch(e) {
    container.innerHTML = `<div class="wx-loading" style="color:var(--red);">Error loading forecast: ${e.message}</div>`;
  }
}

const WX_CODES = {
  0:"☀️",1:"🌤️",2:"⛅",3:"☁️",
  45:"🌫️",48:"🌫️",
  51:"🌦️",53:"🌦️",55:"🌧️",
  61:"🌧️",63:"🌧️",65:"🌧️",
  71:"🌨️",73:"🌨️",75:"❄️",77:"❄️",
  80:"🌦️",81:"🌧️",82:"⛈️",
  85:"🌨️",86:"❄️",
  95:"⛈️",96:"⛈️",99:"⛈️"
};
const WX_DESC = {
  0:"Clear",1:"Mostly Clear",2:"Partly Cloudy",3:"Overcast",
  45:"Foggy",48:"Icy Fog",51:"Light Drizzle",53:"Drizzle",55:"Heavy Drizzle",
  61:"Light Rain",63:"Rain",65:"Heavy Rain",71:"Light Snow",73:"Snow",75:"Heavy Snow",
  80:"Showers",81:"Heavy Showers",82:"Violent Showers",95:"Thunderstorm",99:"Hail Storm"
};

function wxIcon(code) { return WX_CODES[code] || "🌡️"; }
function wxDesc(code) { return WX_DESC[code]  || ""; }

function renderWeatherForecast() {
  const container = document.getElementById("weather-forecast-container");
  if (!wxForecastData?.daily) { container.innerHTML = `<div class="wx-loading">No forecast data.</div>`; return; }
  const { time, temperature_2m_max, temperature_2m_min, weathercode } = wxForecastData.daily;

  const daysHtml = time.map((dateStr, i) => {
    const d    = new Date(dateStr + "T12:00:00");
    const name = i === 0 ? "Today" : d.toLocaleDateString("en-US", { weekday: "short" });
    const sel  = wxSelectedDay === i ? "selected" : "";
    return `<div class="wx-day ${sel}" onclick="selectWeatherDay(${i})">
      <div class="wx-day-name">${name}</div>
      <div class="wx-icon">${wxIcon(weathercode[i])}</div>
      <div class="wx-high">${Math.round(temperature_2m_max[i])}°</div>
      <div class="wx-low">${Math.round(temperature_2m_min[i])}°</div>
      <div class="wx-desc">${wxDesc(weathercode[i])}</div>
    </div>`;
  }).join("");

  let hourlyHtml = "";
  if (wxSelectedDay !== null) {
    hourlyHtml = renderHourlyForecast(wxSelectedDay);
  }

  container.innerHTML = `<div class="wx-days">${daysHtml}</div>${hourlyHtml}`;
}

function selectWeatherDay(dayIndex) {
  if (wxSelectedDay === dayIndex) {
    // Deselect if clicking same day
    wxSelectedDay = null;
  } else {
    wxSelectedDay = dayIndex;
  }
  renderWeatherForecast();
}

function renderHourlyForecast(dayIndex) {
  if (!wxForecastData?.hourly) return "";
  const { time, temperature_2m, weathercode } = wxForecastData.hourly;
  const dateStr = wxForecastData.daily.time[dayIndex];

  // Filter hours for selected day
  const dayHours = time.reduce((acc, t, i) => {
    if (t.startsWith(dateStr)) acc.push({ time: t, temp: temperature_2m[i], code: weathercode[i] });
    return acc;
  }, []);

  if (dayHours.length === 0) return "";

  const hoursHtml = dayHours.map(h => {
    const hour = new Date(h.time).toLocaleTimeString("en-US", { hour: "numeric", hour12: true });
    return `<div class="wx-hour">
      <div class="wx-hour-time">${hour}</div>
      <div class="wx-hour-icon">${wxIcon(h.code)}</div>
      <div class="wx-hour-temp">${Math.round(h.temp)}°F</div>
      <div class="wx-hour-desc">${wxDesc(h.code)}</div>
    </div>`;
  }).join("");

  const selDate = new Date(dateStr + "T12:00:00");
  const dayLabel = wxSelectedDay === 0 ? "Today" : selDate.toLocaleDateString("en-US", { weekday:"long", month:"short", day:"numeric" });

  return `<div class="wx-hourly">
    <div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:0.05em;margin-bottom:8px;">
      Hourly — ${dayLabel}
      <span style="font-size:10px;font-weight:400;color:var(--text-hint);margin-left:6px;">(click day to hide)</span>
    </div>
    <div class="wx-hourly-grid">${hoursHtml}</div>
  </div>`;
}

// ── SUPABASE AUTH ────────────────────────────────────────────────────────────
const supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_KEY);

let currentUser     = null;
let currentUserRole = null;
let currentSession  = null;
let pendingEmail    = null; // for OTP flow

const ROLE_LABELS = {
  administrator: "Administrator",
  operator:      "Operator",
  readonly:      "Read Only"
};

// ── Proactive token refresh ───────────────────────────────────────────────────
// Checks every 60 seconds whether the current JWT is within 5 minutes of
// expiry and silently refreshes it. This keeps the dashboard session alive
// indefinitely without interrupting the user, even if the tab is idle.
let _tokenRefreshTimer = null;

function startTokenRefreshPoller() {
  if (_tokenRefreshTimer) clearInterval(_tokenRefreshTimer);
  _tokenRefreshTimer = setInterval(async () => {
    try {
      const { data: { session }, error } = await supabaseClient.auth.getSession();
      if (error || !session) return; // not logged in — don't interfere

      const expiresAt  = session.expires_at;       // Unix timestamp (seconds)
      const nowSecs    = Math.floor(Date.now() / 1000);
      const secsLeft   = expiresAt - nowSecs;

      // Refresh proactively when less than 5 minutes remain
      if (secsLeft < 300) {
        console.log(`[Auth] Token expiring in ${secsLeft}s — refreshing proactively`);
        const { data, error: refreshErr } = await supabaseClient.auth.refreshSession();
        if (refreshErr) {
          console.warn("[Auth] Token refresh failed:", refreshErr.message);
        } else if (data?.session) {
          currentSession = data.session;
          console.log("[Auth] Token refreshed — new expiry:", new Date(data.session.expires_at * 1000).toLocaleTimeString());
        }
      }
    } catch(e) {
      console.warn("[Auth] Token refresh poller error:", e.message);
    }
  }, 60000); // check every 60 seconds
}

function stopTokenRefreshPoller() {
  if (_tokenRefreshTimer) { clearInterval(_tokenRefreshTimer); _tokenRefreshTimer = null; }
}

// ── Init Auth on page load ────────────────────────────────────────────────────
async function initAuth() {
  // Always show login screen — sign out any existing session first
  showLoginOverlay();
  await supabaseClient.auth.signOut();

  // Listen for auth state changes (fires after successful login)
  supabaseClient.auth.onAuthStateChange(async (event, session) => {
    if (event === "SIGNED_IN" && session) {
      await onSignedIn(session);
    } else if (event === "SIGNED_OUT") {
      stopTokenRefreshPoller();
      currentUser = null; currentUserRole = null;
      showLoginOverlay();
    } else if (event === "PASSWORD_RECOVERY") {
      showStep(3);
    } else if (event === "TOKEN_REFRESHED" && session) {
      currentSession = session;
    } else if (event === "SIGNED_OUT" || event === "USER_DELETED") {
      currentUser = null; currentUserRole = null; currentSession = null;
      showLoginOverlay();
    }
  });

  // Handle token refresh failures — re-prompt login
  supabaseClient.auth.onAuthStateChange((event) => {
    if (event === "SIGNED_OUT") {
      currentUser = null; currentUserRole = null; currentSession = null;
      showLoginOverlay();
      showLoginError("login-error", "Your session expired. Please sign in again.");
      document.getElementById("login-step-1").style.display = "block";
    }
  });
}

async function onSignedIn(session) {
  currentSession = session;
  currentUser    = session.user;

  // Start proactive token refresh — refreshes 5 minutes before expiry
  // so the session never lapses even if the tab is idle
  startTokenRefreshPoller();

  // Load user profile (role)
  const { data: profile } = await supabaseClient
    .from("user_profiles")
    .select("*")
    .eq("id", currentUser.id)
    .single();

  currentUserRole = profile?.role || "readonly";

  // Update last login
  await supabaseClient
    .from("user_profiles")
    .update({ last_login: new Date().toISOString() })
    .eq("id", currentUser.id);

  // Refresh devices from Supabase then rebuild UI
  await loadDevicesFromDB();
  buildControls();
  buildDataCards();
  loadLatest();  // Initialize device badges (online/offline) immediately on login
  // Load LC event ID counter from Supabase to prevent cross-device collisions
  loadLCEventId().catch(e => console.warn("loadLCEventId:", e.message));
  // Load Pelican sites in background (non-blocking)
  loadPelicanSites().catch(e => console.warn("Pelican load:", e.message));
  loadDerapiAssets().catch(e => console.warn("DERapi load:", e.message));
  initDerapiEventTimes();
  // Pre-load summary programs so counts are ready when user visits the tab
  loadSummaryPrograms().catch(e => console.warn("Summary load:", e.message));
  // Start OpenADR background poller immediately after login
  startOADRPoller();
  // Start NWS weather poller if location is already saved
  if (wxLocationData) startNWSPoller();
  // Auto-backfill last 48 hours of missing weather observations (silent, background)
  setTimeout(() => autoBackfillWeather(), 5000);
  // Apply saved theme and font size
  initTheme();
  initFontSize();
  hideLoginOverlay();
  applyRolePermissions(currentUserRole);
  updateAdminHeader();
}

function showLoginOverlay() {
  const overlay = document.getElementById("login-overlay");
  if (overlay) overlay.style.display = "flex";
  showStep(1);
}

function hideLoginOverlay() {
  const overlay = document.getElementById("login-overlay");
  if (overlay) overlay.style.display = "none";
}

function showStep(n) {
  [1,2,3].forEach(i => {
    const el = document.getElementById(`login-step-${i}`);
    if (el) el.style.display = i === n ? "block" : "none";
  });
  clearLoginErrors();
}

function clearLoginErrors() {
  ["login-error","otp-error","pw-error"].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.style.display = "none"; el.textContent = ""; }
  });
}

function showLoginError(id, msg) {
  const el = document.getElementById(id);
  if (el) { el.textContent = msg; el.style.display = "block"; }
}

// ── Step 1: Email + Password login ───────────────────────────────────────────
async function loginSubmit() {
  const email    = document.getElementById("login-email")?.value?.trim();
  const password = document.getElementById("login-password")?.value;
  const btn      = document.getElementById("login-btn");
  if (!email || !password) { showLoginError("login-error", "Please enter your email and password."); return; }

  btn.textContent = "Signing in...";
  btn.disabled    = true;
  clearLoginErrors();

  const { data, error } = await supabaseClient.auth.signInWithPassword({ email, password });

  btn.textContent = "Sign In";
  btn.disabled    = false;

  if (error) {
    showLoginError("login-error", error.message || "Invalid email or password.");
    return;
  }

  // Check if 2FA required for this user
  const { data: profile } = await supabaseClient
    .from("user_profiles")
    .select("two_fa_required, is_active")
    .eq("id", data.user.id)
    .single();

  if (profile && !profile.is_active) {
    await supabaseClient.auth.signOut();
    showLoginError("login-error", "Your account has been deactivated. Contact your administrator.");
    return;
  }

  if (profile?.two_fa_required) {
    // Send OTP email
    pendingEmail = email;
    const { error: otpError } = await supabaseClient.auth.signInWithOtp({
      email,
      options: { shouldCreateUser: false }
    });
    if (otpError) {
      showLoginError("login-error", "Could not send verification code: " + otpError.message);
      return;
    }
    document.getElementById("login-email-display").textContent = email;
    await supabaseClient.auth.signOut(); // Sign out until OTP verified
    showStep(2);
  }
  // If no 2FA required, onSignedIn fires via auth state change
}

// ── Step 2: OTP verification ──────────────────────────────────────────────────
async function otpSubmit() {
  const code = document.getElementById("login-otp")?.value?.trim();
  const btn  = document.getElementById("otp-btn");
  if (!code || code.length < 6) { showLoginError("otp-error", "Please enter the 6-digit code."); return; }

  btn.textContent = "Verifying...";
  btn.disabled    = true;
  clearLoginErrors();

  const { data, error } = await supabaseClient.auth.verifyOtp({
    email: pendingEmail,
    token: code,
    type:  "email"
  });

  btn.textContent = "Verify Code";
  btn.disabled    = false;

  if (error) {
    showLoginError("otp-error", "Invalid or expired code. Please try again.");
    return;
  }
  // onSignedIn fires via auth state change
}

// ── Step 3: Change password ───────────────────────────────────────────────────
async function changePasswordSubmit() {
  const pw1 = document.getElementById("new-password")?.value;
  const pw2 = document.getElementById("confirm-password")?.value;
  if (!pw1 || pw1.length < 8) { showLoginError("pw-error", "Password must be at least 8 characters."); return; }
  if (pw1 !== pw2) { showLoginError("pw-error", "Passwords do not match."); return; }

  const { error } = await supabaseClient.auth.updateUser({ password: pw1 });
  if (error) { showLoginError("pw-error", error.message); return; }
  // Auth state change fires onSignedIn
}

// ── Sign out ──────────────────────────────────────────────────────────────────
async function signOut() {
  await supabaseClient.auth.signOut();
  currentUser = null; currentUserRole = null; currentSession = null;
  showLoginOverlay();
}

// ── Role-based UI permissions ─────────────────────────────────────────────────
function applyRolePermissions(role) {
  // Show Admin tab only for administrators
  const adminBtn    = document.getElementById("main-admin");
  const monitorBtn  = document.getElementById("main-monitor");
  if (adminBtn)   adminBtn.style.display   = role === "administrator" ? "" : "none";
  if (monitorBtn) monitorBtn.style.display = ""; // visible to all roles

  // Read-only users: disable all command buttons
  if (role === "readonly") {
    // Disable send/save/apply buttons after DOM loads
    setTimeout(() => {
      document.querySelectorAll(
        ".sched-submit-btn, .group-cmd-btn, .sched-delete-btn, #send-lc-btn"
      ).forEach(btn => {
        btn.disabled = true;
        btn.style.opacity = "0.4";
        btn.title = "Read-only access";
      });
    }, 500);
  }
}

// ── Admin tab functions ───────────────────────────────────────────────────────
function updateAdminHeader() {
  const userEl = document.getElementById("admin-current-user");
  const roleEl = document.getElementById("admin-current-role");
  if (userEl) userEl.textContent = currentUser?.email || "—";
  if (roleEl) roleEl.textContent = ROLE_LABELS[currentUserRole] || currentUserRole;
  // Also update header bar
  const headerEmail = document.getElementById("header-user-email");
  const headerRole  = document.getElementById("header-user-role");
  if (headerEmail) headerEmail.textContent = currentUser?.email || "";
  if (headerRole)  headerRole.textContent  = ROLE_LABELS[currentUserRole] || currentUserRole || "";
}

function showAddUserForm() {
  const form = document.getElementById("add-user-form");
  if (form) form.style.display = form.style.display === "none" ? "block" : "none";
}

async function createUser() {
  const name     = document.getElementById("new-user-name")?.value?.trim();
  const email    = document.getElementById("new-user-email")?.value?.trim();
  const password = document.getElementById("new-user-password")?.value?.trim();
  const role     = document.getElementById("new-user-role")?.value;
  const twoFa    = document.getElementById("new-user-2fa")?.checked;
  const errEl    = document.getElementById("add-user-error");

  if (!email || !password || !role) {
    errEl.textContent = "Email, password and role are required.";
    errEl.style.display = "block"; return;
  }
  if (password.length < 8) {
    errEl.textContent = "Password must be at least 8 characters.";
    errEl.style.display = "block"; return;
  }

  errEl.style.display = "none";

  // Show loading state
  const createBtn = errEl.previousElementSibling?.querySelector('button');
  if (createBtn) { createBtn.textContent = "Creating..."; createBtn.disabled = true; }

  try {
    // Use a SEPARATE client instance so admin session is not affected
    const tempClient = supabase.createClient(SUPABASE_URL, SUPABASE_KEY, {
      auth: { persistSession: false, autoRefreshToken: false }
    });

    const { data: su, error: suErr } = await tempClient.auth.signUp({
      email,
      password,
      options: { data: { full_name: name } }
    });

    console.log("signUp result:", su, suErr);

    if (suErr) {
      errEl.textContent = suErr.message || "Failed to create user account.";
      errEl.style.display = "block";
      return;
    }

    if (!su?.user?.id) {
      errEl.textContent = "User may already exist or email confirmation is required.";
      errEl.style.display = "block";
      return;
    }

    const userId = su.user.id;

    // Insert profile using the admin's current session token
    const profileRes = await fetch(`${SUPABASE_URL}/rest/v1/user_profiles`, {
      method: "POST",
      headers: {
        "apikey":        SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token}`,
        "Content-Type":  "application/json",
        "Prefer":        "return=minimal"
      },
      body: JSON.stringify({
        id:              userId,
        email,
        full_name:       name || "",
        role,
        two_fa_required: twoFa || false,
        is_active:       true,
        created_by:      currentUser?.id
      })
    });

    if (!profileRes.ok) {
      const profileErr = await profileRes.text();
      console.error("Profile insert error:", profileErr);
      errEl.textContent = `Account created but profile failed: ${profileErr}`;
      errEl.style.display = "block";
      return;
    }

    // Success — admin session untouched
    errEl.style.display = "none";
    document.getElementById("add-user-form").style.display = "none";
    ["new-user-name","new-user-email","new-user-password"].forEach(id => {
      const el = document.getElementById(id); if (el) el.value = "";
    });
    document.getElementById("new-user-2fa").checked = false;
    await loadUsersTable();
    alert(`✅ User ${email} created! They can log in with the temporary password.`);

  } catch(e) {
    errEl.textContent = `Error: ${e.message}`;
    errEl.style.display = "block";
    console.error("createUser exception:", e);
  } finally {
    if (createBtn) { createBtn.textContent = "Create User"; createBtn.disabled = false; }
  }
}

async function loadUsersTable() {
  const container = document.getElementById("users-table-container");
  if (!container || currentUserRole !== "administrator") return;
  // container stays as-is while loading to avoid flash

  // Use raw fetch with admin's JWT to bypass any RLS caching issues
  const usersRes = await fetch(
    `${SUPABASE_URL}/rest/v1/user_profiles?select=*&order=created_at.asc`,
    {
      headers: {
        "apikey":        SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token}`,
        "Content-Type":  "application/json"
      }
    }
  );

  if (!usersRes.ok) {
    const err = await usersRes.text();
    container.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error loading users: ${err}</div>`;
    console.error("loadUsersTable error:", err);
    return;
  }

  const users = await usersRes.json();
  if (!users || users.length === 0) {
    container.innerHTML = `<div class="sched-empty">No users found.</div>`;
    return;
  }

  // Build table using DOM createElement to avoid all quote escaping issues
  const wrap  = document.createElement("div");
  wrap.style.overflowX = "auto";
  const table = document.createElement("table");
  table.style.cssText = "width:100%;border-collapse:collapse;font-size:12px;";

  // Header
  const thead = table.createTHead();
  const hrow  = thead.insertRow();
  ["Name","Email","Role","2FA","Alerts","Status","Last Login",""].forEach(h => {
    const th = document.createElement("th");
    th.textContent = h;
    th.style.cssText = "text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);";
    hrow.appendChild(th);
  });

  // Body
  const tbody = table.createTBody();
  users.forEach(u => {
    const isMe = u.id === currentUser?.id;
    const tr   = tbody.insertRow();
    if (!u.is_active) tr.style.opacity = "0.5";

    // Name
    const tdName = tr.insertCell();
    tdName.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);";
    tdName.textContent = u.full_name || "—";
    if (isMe) {
      const badge = document.createElement("span");
      badge.textContent = " (you)";
      badge.style.cssText = "font-size:10px;color:var(--blue-dark);";
      tdName.appendChild(badge);
    }

    // Email
    const tdEmail = tr.insertCell();
    tdEmail.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);";
    tdEmail.textContent = u.email;

    // Role
    const tdRole = tr.insertCell();
    tdRole.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);";
    const sel = document.createElement("select");
    sel.style.cssText = "font-size:11px;padding:2px 4px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);";
    if (isMe) sel.disabled = true;
    [["readonly","Read Only"],["operator","Operator"],["administrator","Administrator"]].forEach(([val,label]) => {
      const opt = document.createElement("option");
      opt.value = val; opt.textContent = label;
      if (u.role === val) opt.selected = true;
      sel.appendChild(opt);
    });
    sel.addEventListener("change", () => updateUserRole(u.id, sel.value));
    tdRole.appendChild(sel);

    // 2FA
    const td2fa = tr.insertCell();
    td2fa.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);";
    const chk = document.createElement("input");
    chk.type = "checkbox";
    chk.checked = !!u.two_fa_required;
    chk.style.cursor = "pointer";
    chk.addEventListener("change", () => updateUser2FA(u.id, chk.checked));
    td2fa.appendChild(chk);

    // Alerts
    const tdAlerts = tr.insertCell();
    tdAlerts.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);";
    const alertChk = document.createElement("input");
    alertChk.type = "checkbox";
    alertChk.checked = !!u.receive_alerts;
    alertChk.style.cursor = "pointer";
    alertChk.title = "Receive email notifications for alerts, suggestions, and autopilot events";
    alertChk.addEventListener("change", () => updateUserAlerts(u.id, alertChk.checked));
    tdAlerts.appendChild(alertChk);

    // Status
    const tdStatus = tr.insertCell();
    tdStatus.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);color:" + (u.is_active ? "var(--green-dark)" : "var(--red)") + ";";
    tdStatus.textContent = u.is_active ? "Active" : "Inactive";

    // Last Login
    const tdLogin = tr.insertCell();
    tdLogin.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);color:var(--text-hint);";
    tdLogin.textContent = u.last_login ? new Date(u.last_login).toLocaleString() : "Never";

    // Actions
    const tdAct = tr.insertCell();
    tdAct.style.cssText = "padding:8px;border-bottom:0.5px solid var(--border);";
    if (!isMe) {
      const btn = document.createElement("button");
      btn.textContent = u.is_active ? "Deactivate" : "Activate";
      btn.style.cssText = "font-size:10px;padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);cursor:pointer;color:" +
        (u.is_active ? "var(--red)" : "var(--green-dark)") + ";";
      btn.addEventListener("click", () => toggleUserActive(u.id, u.is_active));
      tdAct.appendChild(btn);
    }
  });

  wrap.appendChild(table);
  container.innerHTML = "";
  container.appendChild(wrap);
}

async function updateUserRole(userId, role) {
  await updateUserProfile(userId, { role });
}

async function updateUser2FA(userId, required) {
  await updateUserProfile(userId, { two_fa_required: required });
}

async function updateUserAlerts(userId, receive) {
  await updateUserProfile(userId, { receive_alerts: receive });
  setStatus("ready", `Alert notification ${receive ? "enabled" : "disabled"} for user.`);
}

async function toggleUserActive(userId, currentlyActive) {
  await updateUserProfile(userId, { is_active: !currentlyActive });
  await loadUsersTable();
}

async function changeMyPassword() {
  const pw1   = document.getElementById("my-new-password")?.value;
  const pw2   = document.getElementById("my-confirm-password")?.value;
  const msgEl = document.getElementById("my-pw-status");
  if (!pw1 || pw1.length < 8) { msgEl.textContent = "Password must be at least 8 characters."; msgEl.style.color = "var(--red)"; msgEl.style.display = "block"; return; }
  if (pw1 !== pw2) { msgEl.textContent = "Passwords do not match."; msgEl.style.color = "var(--red)"; msgEl.style.display = "block"; return; }
  const { error } = await supabaseClient.auth.updateUser({ password: pw1 });
  if (error) { msgEl.textContent = error.message; msgEl.style.color = "var(--red)"; }
  else { msgEl.textContent = "✅ Password updated successfully."; msgEl.style.color = "var(--green-dark)"; }
  msgEl.style.display = "block";
}

