// ── Register Asset as Device ──────────────────────────────────────────────────
// Gives EV chargers, batteries, and generators a dev: UID so they participate
// in group assignments and event dispatch exactly like relay devices.
async function registerAssetAsDevice(assetId, name, type, location) {
  // Use same UID prefix as injectXxxIntoDevices functions
  const prefix = type === "battery" ? "batt" : type === "generator" ? "gen" : type === "thermostat" ? "therm" : "ev";
  const uid = `${prefix}_${assetId}`;

  // 1. Write to Supabase devices table
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/devices?uid=eq.${encodeURIComponent(uid)}`, {
      method: "DELETE",
      headers: { "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
    });
    await fetch(`${SUPABASE_URL}/rest/v1/devices`, {
      method: "POST",
      headers: { "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type":"application/json", "Prefer":"return=minimal" },
      body: JSON.stringify({ uid, name, type, location: location||null, enabled:true })
    });
  } catch(e) { console.warn("registerAssetAsDevice Supabase:", e.message); }

  // 2. Write to in-memory DEVICES array
  const existing = DEVICES.findIndex(d => d.uid === uid);
  const entry = { id: uid, uid, name, type, location: location||"", enabled:true };
  if (existing >= 0) DEVICES[existing] = entry;
  else DEVICES.push(entry);

  return uid;
}

async function unregisterAssetDevice(assetId, type) {
  const prefix = type === "battery" ? "batt" : type === "generator" ? "gen" : type === "thermostat" ? "therm" : "ev";
  const uid = `${prefix}_${assetId}`;
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/devices?uid=eq.${encodeURIComponent(uid)}`, {
      method: "DELETE",
      headers: { "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
    });
  } catch(e) {}
  const idx = DEVICES.findIndex(d => d.uid === uid);
  if (idx >= 0) DEVICES.splice(idx, 1);
}
// ══════════════════════════════════════════════════════════════════════════════
// RUNTIME MONITOR — Equipment Runtime Tracking
// ══════════════════════════════════════════════════════════════════════════════

// ── Init ──────────────────────────────────────────────────────────────────────
async function initRuntimeMonitor() {
  logRmDdlHint();
  await loadRmSettings();    // also calls populateRmHexPreviews()
  populateRmFeedSelects();
  populateRmDeviceSelects();
  await loadRmSchedules();
  await loadRmTriggers();
  await loadRuntimeAnalytics();
  // Set backfill date defaults: last 30 days
  const today = new Date();
  const prior = new Date(today); prior.setDate(prior.getDate() - 30);
  const fmt = d => d.toISOString().split("T")[0];
  const fromEl = document.getElementById("rm-backfill-from");
  const toEl   = document.getElementById("rm-backfill-to");
  if (fromEl && !fromEl.value) fromEl.value = fmt(prior);
  if (toEl   && !toEl.value)   toEl.value   = fmt(today);
  // Start pollers
  if (!rmSchedulePoller) rmSchedulePoller = setInterval(tickRmSchedules, 60000);
  if (!rmTriggerPoller)  rmTriggerPoller  = setInterval(tickRmTriggers,  60000);
}

// ── Settings ──────────────────────────────────────────────────────────────────
async function loadRmSettings() {
  try {
    const rows = await supabaseGet("program_settings?setting_key=like.rm_%25");
    if (Array.isArray(rows)) {
      rows.forEach(r => { rmSettings[r.setting_key.replace("rm_","")] = r.setting_value; });
    }
  } catch(e) {}
  const set = (id, key) => { const el = document.getElementById(id); if (el && rmSettings[key] != null) el.value = rmSettings[key]; };
  set("rm-current-on-threshold", "current_on_threshold");
  set("rm-feed-key",             "feed_key");
  set("rm-note-file",            "note_file");
  // Populate live hex previews — these are deterministic, no user input needed
  populateRmHexPreviews();
}

function populateRmHexPreviews() {
  const onHex  = buildCurrentChangeFlagHex(true);
  const offHex = buildCurrentChangeFlagHex(false);
  const onEl   = document.getElementById("rm-hex-preview-on");
  const offEl  = document.getElementById("rm-hex-preview-off");
  if (onEl)  onEl.textContent  = onHex.match(/.{1,2}/g).join(" ");
  if (offEl) offEl.textContent = offHex.match(/.{1,2}/g).join(" ");
}

async function saveRuntimeSettings() {
  const pairs = [
    ["rm_current_on_threshold", document.getElementById("rm-current-on-threshold")?.value?.trim() || "0.5"],
    ["rm_feed_key",             document.getElementById("rm-feed-key")?.value                     || ""],
    ["rm_note_file",            document.getElementById("rm-note-file")?.value?.trim()            || "data.qi"],
  ];
  for (const [key, val] of pairs) {
    rmSettings[key.replace("rm_","")] = val;
    try {
      await supabaseUpsert("program_settings",
        { setting_key: key, setting_value: val, updated_at: new Date().toISOString() },
        "setting_key");
    } catch(e) { console.warn("rm settings save:", e.message); }
  }
  const badge = document.getElementById("rm-settings-saved-badge");
  if (badge) { badge.style.display = "inline-block"; setTimeout(() => badge.style.display = "none", 2500); }
  setStatus("ready", "Runtime monitor settings saved.");
  populateRmFeedSelects();
}

// ── Feed select population ─────────────────────────────────────────────────────
function populateRmFeedSelects() {
  const feedKeys = Object.keys(FEED_DEFS || {});
  const activeFeedKeys = (monitorFeeds || []).map(f => f.feed_key);
  const allKeys = [...new Set([...activeFeedKeys, ...feedKeys])];
  const opts = allKeys.map(k => {
    const def = (FEED_DEFS || {})[k] || { label: k, unit: "" };
    return `<option value="${k}">${def.icon||""} ${def.label} (${def.unit})</option>`;
  }).join("");

  ["rm-feed-key","rm-trig-activate-feed","rm-trig-deactivate-feed"].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    const prev = el.value;
    const placeholder = id === "rm-trig-deactivate-feed"
      ? '<option value="">-- Same as activate --</option>'
      : '<option value="">-- Select feed --</option>';
    el.innerHTML = placeholder + opts;
    if (prev) el.value = prev;
  });

  // Update unit hint on activate feed change
  const af = document.getElementById("rm-trig-activate-feed");
  if (af) af.onchange = () => {
    const def = (FEED_DEFS || {})[af.value] || {};
    const u = document.getElementById("rm-trig-activate-unit");
    if (u) u.textContent = def.unit || "";
  };

  // Load saved feed key into settings dropdown
  const rmFeedEl = document.getElementById("rm-feed-key");
  if (rmFeedEl && rmSettings.feed_key) rmFeedEl.value = rmSettings.feed_key;
}

// ── Device select population ───────────────────────────────────────────────────
function populateRmDeviceSelects() {
  const relayDevs  = (DEVICES || []).filter(d => !d.type || d.type === "relay");
  const deviceOpts = relayDevs.map(d => `<option value="${d.uid}">${d.name}</option>`).join("");

  // Analytics device dropdown — single device selection
  const aDevEl = document.getElementById("rm-analytics-device");
  if (aDevEl) {
    const prev = aDevEl.value;
    aDevEl.innerHTML = `<option value="">-- Select Device --</option>` + deviceOpts;
    if (prev) aDevEl.value = prev;
  }
  // Backfill device dropdown
  const bDevEl = document.getElementById("rm-backfill-device");
  if (bDevEl) {
    const prev = bDevEl.value;
    bDevEl.innerHTML = `<option value="">All Devices</option>` + deviceOpts;
    if (prev) bDevEl.value = prev;
  }
  // Manual target relay device for relay fallback thermostat
  const relayDev = document.getElementById("therm-relay-device");
  if (relayDev) {
    relayDev.innerHTML = `<option value="">-- Select relay device --</option>` + deviceOpts;
  }
}

function buildRmTargetOptions(targetType) {
  const relayDevs = (DEVICES || []).filter(d => !d.type || d.type === "relay");
  if (targetType === "device") {
    return relayDevs.map(d => `<option value="${d.uid}">${d.name}</option>`).join("");
  } else if (targetType === "group") {
    return Object.entries(groupNames || {})
      .sort(([a],[b]) => parseInt(a)-parseInt(b))
      .map(([n,name]) => `<option value="group_${n}">Group ${n}: ${name}</option>`).join("");
  }
  return "";
}

function onRmTargetTypeChange() {
  const tt  = document.getElementById("rm-manual-target-type")?.value;
  const sel = document.getElementById("rm-manual-target");
  if (!sel) return;
  if (tt === "all") { sel.innerHTML = `<option value="all">All Devices</option>`; sel.value = "all"; return; }
  sel.innerHTML = `<option value="" disabled selected>— Choose —</option>` + buildRmTargetOptions(tt);
}
function onRmSchedTargetTypeChange() {
  const tt  = document.getElementById("rm-sched-target-type")?.value;
  const sel = document.getElementById("rm-sched-target");
  if (!sel) return;
  if (tt === "all") { sel.innerHTML = `<option value="all">All Devices</option>`; sel.value = "all"; return; }
  sel.innerHTML = `<option value="" disabled selected>— Choose —</option>` + buildRmTargetOptions(tt);
}
function onRmTrigTargetTypeChange() {
  const tt  = document.getElementById("rm-trig-target-type")?.value;
  const sel = document.getElementById("rm-trig-target");
  if (!sel) return;
  if (tt === "all") { sel.innerHTML = `<option value="all">All Devices</option>`; sel.value = "all"; return; }
  sel.innerHTML = `<option value="" disabled selected>— Choose —</option>` + buildRmTargetOptions(tt);
}

// ── Mode tile selector ─────────────────────────────────────────────────────────
function selectRmMode(mode, el) {
  rmSelectedMode = mode;
  document.querySelectorAll(".rm-mode-tile").forEach(t => t.classList.remove("selected"));
  if (el) el.classList.add("selected");
  document.querySelectorAll(".rm-mode-panel").forEach(p => p.style.display = "none");
  const panel = document.getElementById(`rm-mode-panel-${mode}`);
  if (panel) panel.style.display = "block";
}

// ── Form toggles ──────────────────────────────────────────────────────────────
function toggleRmScheduleForm() {
  const form = document.getElementById("rm-schedule-form");
  if (!form) return;
  const open = form.style.display !== "none";
  form.style.display = open ? "none" : "block";
  if (!open) {
    // Opening fresh — reset all state
    rmEditingSchedId = null;
    rmSelectedMode   = null;
    document.querySelectorAll(".rm-mode-tile").forEach(t => t.classList.remove("selected"));
    document.querySelectorAll(".rm-mode-panel").forEach(p => p.style.display = "none");
    document.getElementById("rm-sched-form-title").textContent = "New Monitoring Schedule";
    const nameEl = document.getElementById("rm-sched-name"); if (nameEl) nameEl.value = "";
    document.getElementById("rm-sched-target-type").value = "";
    document.getElementById("rm-sched-target").innerHTML = `<option value="" disabled selected>— Choose —</option>`;
    // Reset day checkboxes to Mon–Fri
    document.querySelectorAll(".rm-cron-day").forEach(cb => {
      cb.checked = parseInt(cb.value) <= 5;
    });
  } else {
    // Closing — always reset editing state
    rmEditingSchedId = null;
    rmSelectedMode   = null;
    document.querySelectorAll(".rm-mode-tile").forEach(t => t.classList.remove("selected"));
    document.querySelectorAll(".rm-mode-panel").forEach(p => p.style.display = "none");
    document.getElementById("rm-sched-form-title").textContent = "New Monitoring Schedule";
  }
}
function toggleRmTriggerForm() {
  const form = document.getElementById("rm-trigger-form");
  if (!form) return;
  const open = form.style.display !== "none";
  form.style.display = open ? "none" : "block";
  if (!open) {
    // Opening fresh
    rmEditingTrigId = null;
    document.getElementById("rm-trigger-form-title").textContent = "New Feed Trigger";
    ["rm-trig-name","rm-trig-activate-threshold","rm-trig-deactivate-threshold"].forEach(id => {
      const el = document.getElementById(id); if(el) el.value = "";
    });
    document.getElementById("rm-trig-target-type").value = "";
    document.getElementById("rm-trig-target").innerHTML = `<option value="" disabled selected>— Choose —</option>`;
    document.getElementById("rm-trig-min-rest").value = "30";
    document.getElementById("rm-trig-season").value = "";
    populateRmFeedSelects();
  } else {
    // Closing
    rmEditingTrigId = null;
    document.getElementById("rm-trigger-form-title").textContent = "New Feed Trigger";
  }
}

// ── Manual command dispatch ───────────────────────────────────────────────────
async function sendRuntimeCommand(action) {
  const logEl    = document.getElementById("rm-manual-log");
  const enable   = action === "activate";
  const lcHex    = buildCurrentChangeFlagHex(enable);

  const targetType = document.getElementById("rm-manual-target-type")?.value;
  const targetVal  = document.getElementById("rm-manual-target")?.value;
  if (!targetType) { if (logEl) logEl.textContent = "⚠ Select a target type first."; return; }

  const targets = resolveRmTargets(targetType, targetVal);
  if (!targets.length) { if (logEl) logEl.textContent = "⚠ No devices matched target."; return; }

  if (logEl) logEl.textContent = `Sending ${action} [${lcHex.match(/.{1,2}/g).join(" ")}] to ${targets.length} device(s)…`;

  let sent = 0;
  for (const uid of targets) {
    await sendLCToDevice(uid, lcHex);  // uses existing proxy + DEVICES guard
    sent++;
  }

  if (logEl) logEl.textContent = `✓ ${action.toUpperCase()} (bit 8 ${enable ? "SET 0x80" : "CLEARED 0x00"}) sent to ${sent}/${targets.length} device(s) at ${new Date().toLocaleTimeString()}.`;

  try {
    await supabasePost("runtime_monitor_log", {
      action, target_type: targetType, target_id: targetVal,
      lc_hex: lcHex, device_count: sent, trigger_source: "manual",
      fired_at: new Date().toISOString()
    });
  } catch(e) {}
}

function resolveRmTargets(targetType, targetVal) {
  if (targetType === "all") return (DEVICES || []).filter(d => !d.type || d.type === "relay").map(d => d.uid);
  if (targetType === "group") {
    const gNum = parseInt((targetVal || "").replace("group_",""));
    return (DEVICES || []).filter(d => (groupAssignments[d.uid]||[]).includes(gNum)).map(d => d.uid);
  }
  if (targetType === "device" && targetVal) return [targetVal];
  return [];
}

// ── Schedules ─────────────────────────────────────────────────────────────────
async function saveRmSchedule() {
  if (!rmSelectedMode) { setStatus("error", "Select a schedule mode."); return; }
  const name = document.getElementById("rm-sched-name")?.value?.trim();
  if (!name)  { setStatus("error", "Schedule name required."); return; }
  const targetType = document.getElementById("rm-sched-target-type")?.value;
  const targetVal  = document.getElementById("rm-sched-target")?.value;
  if (!targetType) { setStatus("error", "Select a target type."); return; }

  const now    = new Date().toISOString();
  const config = buildRmSchedConfig();
  const record = {
    name, mode: rmSelectedMode,
    target_type: targetType, target_id: targetVal || "all",
    config: JSON.stringify(config), enabled: true,
    created_at: now, updated_at: now
  };

  let savedToDb  = false;
  let savedRecord = { ...record, config, id: rmEditingSchedId || Date.now() };

  try {
    if (rmEditingSchedId) {
      const res = await supabasePatch(`runtime_monitor_schedules?id=eq.${rmEditingSchedId}`,
        { ...record, updated_at: now, created_at: undefined });
      if (res?.ok) { savedToDb = true; savedRecord.id = rmEditingSchedId; }
      else console.warn("rm schedule PATCH failed:", res?.status);
    } else {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/runtime_monitor_schedules`, {
        method: "POST",
        headers: {
          "apikey":        SUPABASE_KEY,
          "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
          "Content-Type":  "application/json",
          "Prefer":        "return=representation"
        },
        body: JSON.stringify(record)
      });
      if (res.ok) {
        const inserted = await res.json();
        savedRecord = Array.isArray(inserted) ? inserted[0] : inserted;
        if (typeof savedRecord.config === "string") {
          try { savedRecord.config = JSON.parse(savedRecord.config); } catch(e) {}
        }
        savedToDb = true;
      } else {
        const errText = await res.text();
        console.warn("rm schedule POST failed:", res.status, errText);
        setStatus("error", `Save failed (${res.status}): ${errText.substring(0,120)}`);
      }
    }
  } catch(e) {
    console.warn("rm schedule save exception:", e.message);
    setStatus("error", `Save error: ${e.message}`);
  }

  // localStorage fallback
  try {
    const existing = JSON.parse(localStorage.getItem(RM_SCHEDULES_KEY) || "[]");
    const filtered = existing.filter(s => s.id !== savedRecord.id);
    filtered.push({ ...savedRecord, config });
    localStorage.setItem(RM_SCHEDULES_KEY, JSON.stringify(filtered));
  } catch(e) {}

  toggleRmScheduleForm();
  rmEditingSchedId = null;
  await loadRmSchedules();
  setStatus("ready", savedToDb
    ? `Schedule "${name}" saved to database.`
    : `Schedule "${name}" saved locally (database table may need to be created — check console for DDL).`);
}

function buildRmSchedConfig() {
  const c = {};
  if (rmSelectedMode === "daytime") {
    c.start_time  = document.getElementById("rm-cron-start")?.value || "08:00";
    c.end_time    = document.getElementById("rm-cron-end")?.value   || "18:00";
    c.timezone    = document.getElementById("rm-cron-tz")?.value    || "America/Chicago";
    c.days        = Array.from(document.querySelectorAll(".rm-cron-day:checked")).map(cb => parseInt(cb.value));
  } else if (rmSelectedMode === "dr_summer") {
    c.start_month = parseInt(document.getElementById("rm-summer-start-month")?.value || "5");
    c.end_month   = parseInt(document.getElementById("rm-summer-end-month")?.value   || "9");
    c.sub_mode    = document.getElementById("rm-summer-mode")?.value || "always";
  } else if (rmSelectedMode === "dr_winter") {
    c.start_month = parseInt(document.getElementById("rm-winter-start-month")?.value || "11");
    c.end_month   = parseInt(document.getElementById("rm-winter-end-month")?.value   || "3");
    c.sub_mode    = document.getElementById("rm-winter-mode")?.value || "always";
  } else if (rmSelectedMode === "onpeak") {
    c.follow_tou = true;
  }
  return c;
}

async function loadRmSchedules() {
  let dbRows    = [];
  let localRows = [];

  try {
    const rows = await supabaseGet("runtime_monitor_schedules?order=created_at.asc");
    if (Array.isArray(rows) && rows.length) dbRows = rows;
  } catch(e) { console.warn("loadRmSchedules DB:", e.message); }

  try {
    const saved = localStorage.getItem(RM_SCHEDULES_KEY);
    if (saved) localRows = JSON.parse(saved);
  } catch(e) {}

  if (dbRows.length) {
    try { localStorage.setItem(RM_SCHEDULES_KEY, JSON.stringify(dbRows)); } catch(e) {}
    rmSchedules = dbRows.map(r => ({
      ...r,
      config: typeof r.config === "string"
        ? (() => { try { return JSON.parse(r.config); } catch(e) { return {}; } })()
        : (r.config || {})
    }));
  } else if (localRows.length) {
    rmSchedules = localRows;
  } else {
    rmSchedules = [];
  }

  renderRmSchedules();
}

function renderRmSchedules() {
  const list = document.getElementById("rm-schedule-list");
  if (!list) return;
  if (!rmSchedules.length) { list.innerHTML = '<div class="sched-empty">No monitoring schedules configured.</div>'; return; }
  const MODE_LABELS = { daytime:"🕐 Day / Time", dr_summer:"☀️ Summer DR", dr_winter:"❄️ Winter DR", onpeak:"⏰ On-Peak" };
  list.innerHTML = rmSchedules.map(s => {
    const cfg   = s.config || {};
    let detail  = "";
    if (s.mode === "daytime")    detail = `${cfg.start_time||"?"}–${cfg.end_time||"?"} • Days: ${(cfg.days||[]).join(",")} • ${cfg.timezone||""}`;
    if (s.mode === "dr_summer") detail = `Months ${cfg.start_month}–${cfg.end_month} • ${cfg.sub_mode||"always"}`;
    if (s.mode === "dr_winter") detail = `Months ${cfg.start_month}–${cfg.end_month} • ${cfg.sub_mode||"always"}`;
    if (s.mode === "onpeak")    detail = "Follows TOU peak window";
    const targetLabel = s.target_type === "all" ? "All Devices"
      : s.target_type === "group" ? `Group ${(s.target_id||"").replace("group_","")}: ${groupNames[parseInt((s.target_id||"").replace("group_",""))]||""}`
      : unitName(s.target_id) || s.target_id;
    return `<div class="rm-sched-card">
      <div style="flex:1;">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">
          <span style="font-size:12px;font-weight:700;color:var(--text-primary);">${s.name}</span>
          <span style="font-size:10px;padding:2px 8px;border-radius:10px;background:var(--blue-lt,#eff6ff);color:var(--blue-dark);font-family:monospace;">${MODE_LABELS[s.mode]||s.mode}</span>
          <span style="font-size:10px;padding:2px 8px;border-radius:10px;background:${s.enabled?"var(--green-bg)":"var(--surface2)"};color:${s.enabled?"var(--green-dark)":"var(--text-hint)"};">${s.enabled?"Enabled":"Disabled"}</span>
        </div>
        <div style="font-size:11px;color:var(--text-hint);">${targetLabel} • ${detail}</div>
      </div>
      <div style="display:flex;gap:6px;">
        <button onclick="editRmSchedule(${s.id})" style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--blue-dark);background:var(--blue-lt,#eff6ff);color:var(--blue-dark);font-size:10px;cursor:pointer;">Edit</button>
        <button onclick="toggleRmScheduleEnabled(${s.id},${!s.enabled})" style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">${s.enabled?"Pause":"Enable"}</button>
        <button onclick="deleteRmSchedule(${s.id})" style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
      </div>
    </div>`;
  }).join("");
}

function editRmSchedule(id) {
  const s = rmSchedules.find(x => x.id === id);
  if (!s) return;

  rmEditingSchedId = id;
  const cfg = s.config || {};

  // Open the form
  const form = document.getElementById("rm-schedule-form");
  if (form) form.style.display = "block";

  // Update title and save button
  const titleEl = document.getElementById("rm-sched-form-title");
  if (titleEl) titleEl.textContent = `Editing: ${s.name}`;

  // Populate common fields
  const setVal = (id, val) => { const el = document.getElementById(id); if (el && val != null) el.value = val; };
  setVal("rm-sched-name", s.name);

  // Target type + target
  const ttEl = document.getElementById("rm-sched-target-type");
  if (ttEl) { ttEl.value = s.target_type || ""; onRmSchedTargetTypeChange(); }
  // Small delay so target options populate before setting value
  setTimeout(() => { setVal("rm-sched-target", s.target_id); }, 50);

  // Mode tile
  const modeEl = document.querySelector(`.rm-mode-tile[data-mode="${s.mode}"]`);
  selectRmMode(s.mode, modeEl);

  // Populate mode-specific fields
  if (s.mode === "daytime") {
    setVal("rm-cron-start", cfg.start_time);
    setVal("rm-cron-end",   cfg.end_time);
    setVal("rm-cron-tz",    cfg.timezone);
    // Restore day checkboxes
    document.querySelectorAll(".rm-cron-day").forEach(cb => {
      cb.checked = (cfg.days || []).includes(parseInt(cb.value));
    });
  } else if (s.mode === "dr_summer") {
    setVal("rm-summer-start-month", cfg.start_month);
    setVal("rm-summer-end-month",   cfg.end_month);
    setVal("rm-summer-mode",        cfg.sub_mode || "always");
  } else if (s.mode === "dr_winter") {
    setVal("rm-winter-start-month", cfg.start_month);
    setVal("rm-winter-end-month",   cfg.end_month);
    setVal("rm-winter-mode",        cfg.sub_mode || "always");
  }
  // onpeak has no extra fields

  // Scroll form into view
  form?.scrollIntoView({ behavior: "smooth", block: "start" });
}

async function toggleRmScheduleEnabled(id, enabled) {
  try { await supabasePatch(`runtime_monitor_schedules?id=eq.${id}`, { enabled, updated_at: new Date().toISOString() }); } catch(e) {}
  try {
    const local = JSON.parse(localStorage.getItem(RM_SCHEDULES_KEY) || "[]");
    const updated = local.map(s => s.id === id ? { ...s, enabled } : s);
    localStorage.setItem(RM_SCHEDULES_KEY, JSON.stringify(updated));
  } catch(e) {}
  await loadRmSchedules();
}

async function deleteRmSchedule(id) {
  if (!confirm("Remove this monitoring schedule?")) return;
  try { await supabaseDelete("runtime_monitor_schedules", `id=eq.${id}`); } catch(e) {}
  try {
    const local = JSON.parse(localStorage.getItem(RM_SCHEDULES_KEY) || "[]");
    localStorage.setItem(RM_SCHEDULES_KEY, JSON.stringify(local.filter(s => s.id !== id)));
  } catch(e) {}
  await loadRmSchedules();
}

// ── Schedule tick (called every 60s) ──────────────────────────────────────────
async function tickRmSchedules() {
  const now = new Date();
  for (const s of rmSchedules.filter(s => s.enabled)) {
    const cfg     = s.config || {};
    const targets = resolveRmTargets(s.target_type, s.target_id);
    let shouldBeActive = false;

    if (s.mode === "daytime") {
      const tz  = cfg.timezone || "America/Chicago";
      const loc = new Date(now.toLocaleString("en-US", { timeZone: tz }));
      const day = loc.getDay() || 7; // 1=Mon..7=Sun
      const hm  = `${String(loc.getHours()).padStart(2,"0")}:${String(loc.getMinutes()).padStart(2,"0")}`;
      shouldBeActive = (cfg.days||[]).includes(day) && hm >= (cfg.start_time||"00:00") && hm < (cfg.end_time||"23:59");
    } else if (s.mode === "dr_summer" || s.mode === "dr_winter") {
      const mo = now.getMonth() + 1;
      const sm = cfg.start_month, em = cfg.end_month;
      const inSeason = sm <= em ? (mo >= sm && mo <= em) : (mo >= sm || mo <= em);
      if (inSeason) {
        shouldBeActive = cfg.sub_mode !== "onpeak" || (feedValues["tou_peak"]?.value === 1);
      }
    } else if (s.mode === "onpeak") {
      shouldBeActive = feedValues["tou_peak"]?.value === 1;
    }

    const stateKey = `rm_sched_active_${s.id}`;
    const wasActive = !!window[stateKey];
    if (shouldBeActive && !wasActive) {
      window[stateKey] = true;
      for (const uid of targets) await sendRmCmd("activate", uid, "schedule");
    } else if (!shouldBeActive && wasActive) {
      window[stateKey] = false;
      for (const uid of targets) await sendRmCmd("deactivate", uid, "schedule");
    }
  }
}

// ── Triggers ──────────────────────────────────────────────────────────────────
async function saveRmTrigger() {
  const name       = document.getElementById("rm-trig-name")?.value?.trim();
  const targetType = document.getElementById("rm-trig-target-type")?.value;
  const targetVal  = document.getElementById("rm-trig-target")?.value;
  const actFeed    = document.getElementById("rm-trig-activate-feed")?.value;
  const actOp      = document.getElementById("rm-trig-activate-op")?.value;
  const actThr     = parseFloat(document.getElementById("rm-trig-activate-threshold")?.value);
  const deactFeed  = document.getElementById("rm-trig-deactivate-feed")?.value || actFeed;
  const deactOp    = document.getElementById("rm-trig-deactivate-op")?.value;
  const deactThr   = parseFloat(document.getElementById("rm-trig-deactivate-threshold")?.value);
  const season     = document.getElementById("rm-trig-season")?.value || "";
  const minRest    = parseInt(document.getElementById("rm-trig-min-rest")?.value || "30");

  if (!name)         { setStatus("error", "Trigger name required."); return; }
  if (!actFeed)      { setStatus("error", "Select an activate feed."); return; }
  if (isNaN(actThr)) { setStatus("error", "Enter an activate threshold value."); return; }
  if (!actOp)        { setStatus("error", "Select an activate operator."); return; }

  const now = new Date().toISOString();
  const record = {
    name,
    target_type:          targetType || "all",
    target_id:            targetVal  || "all",
    activate_feed:        actFeed,
    activate_op:          actOp,
    activate_threshold:   actThr,
    deactivate_feed:      deactFeed  || null,
    deactivate_op:        deactOp    || null,
    deactivate_threshold: isNaN(deactThr) ? null : deactThr,
    season_guard:         season     || null,
    min_rest_minutes:     minRest,
    enabled:              true,
    last_fired_at:        null,
    created_at:           now,
    updated_at:           now
  };

  let savedToDb = false;
  let savedRecord = { ...record, id: rmEditingTrigId || Date.now() };

  try {
    if (rmEditingTrigId) {
      const res = await supabasePatch(`runtime_monitor_triggers?id=eq.${rmEditingTrigId}`,
        { ...record, created_at: undefined }); // don't overwrite created_at on edit
      if (res?.ok) { savedToDb = true; savedRecord.id = rmEditingTrigId; }
      else console.warn("rm trigger PATCH failed:", res?.status);
    } else {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/runtime_monitor_triggers`, {
        method: "POST",
        headers: {
          "apikey":        SUPABASE_KEY,
          "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
          "Content-Type":  "application/json",
          "Prefer":        "return=representation"   // get the row back so we have the DB id
        },
        body: JSON.stringify(record)
      });
      if (res.ok) {
        const inserted = await res.json();
        savedRecord = Array.isArray(inserted) ? inserted[0] : inserted;
        savedToDb = true;
      } else {
        const errText = await res.text();
        console.warn("rm trigger POST failed:", res.status, errText);
        // Surface the actual Supabase error so the user knows what's wrong
        setStatus("error", `Save failed (${res.status}): ${errText.substring(0,120)}`);
      }
    }
  } catch(e) {
    console.warn("rm trigger save exception:", e.message);
    setStatus("error", `Save error: ${e.message}`);
  }

  // Always write to localStorage as fallback / cache
  try {
    const existing = JSON.parse(localStorage.getItem(RM_TRIGGERS_KEY) || "[]");
    const filtered = existing.filter(t => t.id !== savedRecord.id);
    filtered.push(savedRecord);
    localStorage.setItem(RM_TRIGGERS_KEY, JSON.stringify(filtered));
  } catch(e) {}

  toggleRmTriggerForm();
  rmEditingTrigId = null;
  await loadRmTriggers();
  setStatus("ready", savedToDb
    ? `Trigger "${name}" saved to database.`
    : `Trigger "${name}" saved locally (database table may need to be created — check console for DDL).`);
}

async function loadRmTriggers() {
  let dbRows    = [];
  let localRows = [];

  try {
    const rows = await supabaseGet("runtime_monitor_triggers?order=created_at.asc");
    if (Array.isArray(rows) && rows.length) dbRows = rows;
  } catch(e) { console.warn("loadRmTriggers DB:", e.message); }

  try {
    const saved = localStorage.getItem(RM_TRIGGERS_KEY);
    if (saved) localRows = JSON.parse(saved);
  } catch(e) {}

  // Merge: DB wins for any id that exists in both
  if (dbRows.length) {
    // Sync localStorage to match DB
    try { localStorage.setItem(RM_TRIGGERS_KEY, JSON.stringify(dbRows)); } catch(e) {}
    rmTriggers = dbRows;
  } else if (localRows.length) {
    // DB table may not exist yet — use localStorage
    rmTriggers = localRows;
  } else {
    rmTriggers = [];
  }

  renderRmTriggers();
}

function renderRmTriggers() {
  const list = document.getElementById("rm-trigger-list");
  if (!list) return;
  if (!rmTriggers.length) { list.innerHTML = '<div class="sched-empty">No feed triggers configured.</div>'; return; }
  const OP = { gt:">", gte:"≥", lt:"<", lte:"≤", eq:"=" };
  list.innerHTML = rmTriggers.map(t => {
    const aFeedDef = (FEED_DEFS||{})[t.activate_feed] || { label: t.activate_feed, unit:"" };
    const dFeedDef = (FEED_DEFS||{})[t.deactivate_feed] || { label: t.deactivate_feed || "same", unit:"" };
    const actLabel  = `${aFeedDef.label} ${OP[t.activate_op]||t.activate_op} ${t.activate_threshold} ${aFeedDef.unit}`;
    const deactLabel = t.deactivate_threshold != null
      ? `${dFeedDef.label} ${OP[t.deactivate_op]||t.deactivate_op} ${t.deactivate_threshold} ${dFeedDef.unit}`
      : "Manual/schedule deactivation";
    const targetLabel = t.target_type === "all" ? "All Devices"
      : t.target_type === "group" ? `Group: ${groupNames[parseInt((t.target_id||"").replace("group_",""))]||t.target_id}`
      : unitName(t.target_id) || t.target_id;
    return `<div class="rm-trigger-card">
      <div style="flex:1;">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">
          <span style="font-size:12px;font-weight:700;">${t.name}</span>
          <span style="font-size:10px;padding:2px 8px;border-radius:10px;background:${t.enabled?"var(--amber-bg)":"var(--surface2)"};color:${t.enabled?"var(--amber)":"var(--text-hint)"};">${t.enabled?"Active":"Disabled"}</span>
          ${t.season_guard ? `<span style="font-size:10px;padding:2px 8px;border-radius:10px;background:var(--surface2);color:var(--text-hint);">${t.season_guard} only</span>` : ""}
        </div>
        <div style="font-size:11px;color:var(--text-hint);margin-bottom:2px;">▶ <span style="color:var(--green-dark);font-weight:600;">ON:</span> ${actLabel}</div>
        <div style="font-size:11px;color:var(--text-hint);margin-bottom:2px;">⏹ <span style="color:var(--red);font-weight:600;">OFF:</span> ${deactLabel}</div>
        <div style="font-size:10px;color:var(--text-hint);">Target: ${targetLabel} • Rest: ${t.min_rest_minutes}min${t.last_fired_at ? ` • Last fired: ${new Date(t.last_fired_at).toLocaleString()}` : ""}</div>
      </div>
      <div style="display:flex;gap:6px;">
        <button onclick="editRmTrigger(${t.id})" style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--blue-dark);background:var(--blue-lt,#eff6ff);color:var(--blue-dark);font-size:10px;cursor:pointer;">Edit</button>
        <button onclick="toggleRmTriggerEnabled(${t.id},${!t.enabled})" style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">${t.enabled?"Pause":"Enable"}</button>
        <button onclick="deleteRmTrigger(${t.id})" style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
      </div>
    </div>`;
  }).join("");
}

function editRmTrigger(id) {
  const t = rmTriggers.find(x => x.id === id);
  if (!t) return;

  rmEditingTrigId = id;

  // Open the form
  const form = document.getElementById("rm-trigger-form");
  if (form) form.style.display = "block";

  // Update form title
  const titleEl = document.getElementById("rm-trigger-form-title");
  if (titleEl) titleEl.textContent = `Editing: ${t.name}`;

  const setVal = (id, val) => { const el = document.getElementById(id); if (el && val != null) el.value = val; };
  const setOpt = (id, val) => { const el = document.getElementById(id); if (el && val != null) el.value = val; };

  // Common fields
  setVal("rm-trig-name",       t.name);
  setVal("rm-trig-min-rest",   t.min_rest_minutes ?? 30);
  setOpt("rm-trig-season",     t.season_guard || "");

  // Target type + target
  const ttEl = document.getElementById("rm-trig-target-type");
  if (ttEl) { ttEl.value = t.target_type || "all"; onRmTrigTargetTypeChange(); }
  setTimeout(() => { setVal("rm-trig-target", t.target_id); }, 50);

  // Ensure feed selects are populated first
  populateRmFeedSelects();

  // Activate condition — small delay so options are rendered
  setTimeout(() => {
    setOpt("rm-trig-activate-feed",      t.activate_feed);
    setOpt("rm-trig-activate-op",        t.activate_op);
    setVal("rm-trig-activate-threshold", t.activate_threshold);

    // Update unit hint
    const def = (FEED_DEFS || {})[t.activate_feed] || {};
    const uEl = document.getElementById("rm-trig-activate-unit");
    if (uEl) uEl.textContent = def.unit || "";

    // Deactivate condition
    setOpt("rm-trig-deactivate-feed",      t.deactivate_feed || "");
    setOpt("rm-trig-deactivate-op",        t.deactivate_op   || "lt");
    setVal("rm-trig-deactivate-threshold", t.deactivate_threshold ?? "");
  }, 60);

  // Scroll into view
  form?.scrollIntoView({ behavior: "smooth", block: "start" });
}

async function toggleRmTriggerEnabled(id, enabled) {
  try { await supabasePatch(`runtime_monitor_triggers?id=eq.${id}`, { enabled, updated_at: new Date().toISOString() }); } catch(e) {}
  try {
    const local = JSON.parse(localStorage.getItem(RM_TRIGGERS_KEY) || "[]");
    const updated = local.map(t => t.id === id ? { ...t, enabled } : t);
    localStorage.setItem(RM_TRIGGERS_KEY, JSON.stringify(updated));
  } catch(e) {}
  await loadRmTriggers();
}

async function deleteRmTrigger(id) {
  if (!confirm("Remove this feed trigger?")) return;
  try { await supabaseDelete("runtime_monitor_triggers", `id=eq.${id}`); } catch(e) {}
  try {
    const local = JSON.parse(localStorage.getItem(RM_TRIGGERS_KEY) || "[]");
    localStorage.setItem(RM_TRIGGERS_KEY, JSON.stringify(local.filter(t => t.id !== id)));
  } catch(e) {}
  await loadRmTriggers();
}

// ── Trigger tick (called every 60s) ───────────────────────────────────────────
async function tickRmTriggers() {
  const now = new Date();
  const mo  = now.getMonth() + 1;
  for (const t of rmTriggers.filter(t => t.enabled)) {
    // Season guard
    if (t.season_guard === "summer" && !(mo >= 5 && mo <= 9)) continue;
    if (t.season_guard === "winter" && !((mo >= 11) || (mo <= 3))) continue;
    // Min rest guard
    if (t.last_fired_at) {
      const msSince = now - new Date(t.last_fired_at);
      if (msSince < (t.min_rest_minutes || 30) * 60000) continue;
    }
    const stateKey = `rm_trig_active_${t.id}`;
    const isActive = !!window[stateKey];
    const targets  = resolveRmTargets(t.target_type, t.target_id);
    if (!isActive && checkCondition(t.activate_feed, t.activate_op, t.activate_threshold)) {
      window[stateKey] = true;
      for (const uid of targets) await sendRmCmd("activate", uid, "feed_trigger");
      try {
        await supabasePatch(`runtime_monitor_triggers?id=eq.${t.id}`, { last_fired_at: now.toISOString() });
        t.last_fired_at = now.toISOString();
      } catch(e) {}
    } else if (isActive && t.deactivate_threshold != null &&
        checkCondition(t.deactivate_feed || t.activate_feed, t.deactivate_op, t.deactivate_threshold)) {
      window[stateKey] = false;
      for (const uid of targets) await sendRmCmd("deactivate", uid, "feed_trigger");
    }
  }
}

// ── Core command send ─────────────────────────────────────────────────────────
async function sendRmCmd(action, uid, source) {
  const enable = action === "activate";
  const lcHex  = buildCurrentChangeFlagHex(enable);
  await sendLCToDevice(uid, lcHex);  // uses existing proxy + DEVICES guard
  try {
    await supabasePost("runtime_monitor_log", {
      action, device_uid: uid, target_type: "device", target_id: uid,
      lc_hex: lcHex, device_count: 1, trigger_source: source,
      fired_at: new Date().toISOString()
    });
  } catch(e) { console.warn("sendRmCmd log:", e.message); }
}

// ── Analytics ─────────────────────────────────────────────────────────────────
// ── Chart toggle controls ──────────────────────────────────────────────────────────────────────────────
function switchRmDayNight(el) {
  rmShowDayNight = !rmShowDayNight;
  if (el) el.classList.toggle("active", rmShowDayNight);
  renderRmMainChart(rmAnalyticsSessions);
}

// ── Solar position engine — no API required ───────────────────────────────────
// Returns { sunrise, sunset } as UTC millisecond timestamps for a given
// calendar date (local) and lat/lon.
// Adapted from NOAA solar calculation — accurate to ±1-2 minutes.
function getSunriseSunset(localDateMidnight, lat, lon) {
  // localDateMidnight should be a Date set to local midnight (00:00:00 local)
  // We work entirely in Julian Day / UTC to avoid DST confusion
  const rad  = d => d * Math.PI / 180;
  const deg  = r => r * 180 / Math.PI;

  // Julian day of local noon (approximate)
  const JD = localDateMidnight.getTime() / 86400000 + 2440587.5 + 0.5;

  const n       = JD - 2451545.0;
  const L       = ((280.46 + 0.9856474 * n) % 360 + 360) % 360;
  const g       = ((357.528 + 0.9856003 * n) % 360 + 360) % 360;
  const lambda  = L + 1.915 * Math.sin(rad(g)) + 0.020 * Math.sin(rad(2*g));
  const e       = 23.439 - 0.0000004 * n;
  const sinDec  = Math.sin(rad(e)) * Math.sin(rad(lambda));
  const dec     = Math.asin(sinDec);

  // Equation of time (minutes)
  const RA      = deg(Math.atan2(Math.cos(rad(e)) * Math.sin(rad(lambda)), Math.cos(rad(lambda))));
  const eqTime  = 4 * (L - RA);

  // Hour angle at sunrise/sunset (solar zenith = 90.833° to account for refraction)
  const cosHA   = (Math.cos(rad(90.833)) - sinDec * Math.sin(rad(lat)))
                / (Math.cos(dec) * Math.cos(rad(lat)));
  const cosHAc  = Math.max(-1, Math.min(1, cosHA));
  const HA      = deg(Math.acos(cosHAc));   // degrees

  // Solar noon in minutes from UTC midnight
  const solarNoonUTC = 720 - 4 * lon - eqTime;
  const sunriseUTC   = solarNoonUTC - HA * 4;  // HA*4 = minutes
  const sunsetUTC    = solarNoonUTC + HA * 4;

  // Convert to absolute UTC timestamps
  // localDateMidnight.getTime() is UTC ms of local midnight
  // We need UTC ms of the UTC midnight of the SAME calendar day
  const utcMidnight = Date.UTC(
    localDateMidnight.getFullYear(),
    localDateMidnight.getMonth(),
    localDateMidnight.getDate()
  );

  return {
    sunrise: new Date(utcMidnight + sunriseUTC * 60000),
    sunset:  new Date(utcMidnight + sunsetUTC  * 60000),
  };
}

// Build night bands as UTC timestamp ranges covering the session window
function buildDayNightBands(sessions) {
  if (!sessions.length) return [];
  const lat = wxLocationData?.lat ?? 35.5;
  const lon = wxLocationData?.lon ?? -97.5;

  // Work in local time for calendar day boundaries
  const firstTs = new Date(sessions[0].session_start);
  const lastTs  = new Date(sessions[sessions.length-1].session_end || sessions[sessions.length-1].session_start);

  // Build array of local calendar dates spanning the session range
  const days = [];
  const cur  = new Date(firstTs.getFullYear(), firstTs.getMonth(), firstTs.getDate());
  const end  = new Date(lastTs.getFullYear(),  lastTs.getMonth(),  lastTs.getDate());
  while (cur <= end) {
    days.push(new Date(cur));
    cur.setDate(cur.getDate() + 1);
  }

  const bands = [];
  days.forEach((day, i) => {
    const { sunrise, sunset } = getSunriseSunset(day, lat, lon);

    // Local midnight start and end of this day
    const dayStart = day.getTime();
    const dayEnd   = new Date(day.getFullYear(), day.getMonth(), day.getDate()+1).getTime();

    // Pre-sunrise night band
    if (sunrise.getTime() > dayStart) {
      bands.push({ start: dayStart, end: sunrise.getTime(), isNight: true });
    }
    // Daytime band
    bands.push({ start: sunrise.getTime(), end: sunset.getTime(), isNight: false });
    // Post-sunset night band
    if (sunset.getTime() < dayEnd) {
      bands.push({ start: sunset.getTime(), end: dayEnd, isNight: true });
    }
  });

  return bands;
}

// Shared factory — returns a Chart.js inline plugin that draws night shading
// on any chart type. Pass the nightRanges array from buildDayNightAnnotations.
function buildDayNightPlugin(nightRanges) {
  return {
    id: "dayNightShading",
    beforeDraw(chart) {
      if (!nightRanges.length) return;
      const { ctx, chartArea, scales } = chart;
      if (!chartArea || !scales.x) return;
      ctx.save();
      nightRanges.forEach(range => {
        const x1 = scales.x.getPixelForValue(range.xMin);
        const x2 = scales.x.getPixelForValue(range.xMax);
        ctx.fillStyle = "rgba(20,20,60,0.09)";
        ctx.fillRect(Math.min(x1,x2), chartArea.top, Math.abs(x2-x1), chartArea.bottom - chartArea.top);
        ctx.font = "10px sans-serif";
        ctx.fillStyle = "rgba(80,80,140,0.5)";
        ctx.fillText("🌙", Math.min(x1,x2)+2, chartArea.top + 12);
      });
      ctx.restore();
    }
  };
}

// Map night bands to x-axis bar indices for canvas drawing
function buildDayNightAnnotations(bands, labelISOs) {
  if (!bands.length || !labelISOs.length) return [];
  // labelISOs are session_start timestamps from Supabase — parse to UTC ms
  const labelTimes = labelISOs.map(l => new Date(l).getTime());
  const nightRanges = [];

  bands.forEach(band => {
    if (!band.isNight) return;
    const bs = typeof band.start === "number" ? band.start : band.start.getTime();
    const be = typeof band.end   === "number" ? band.end   : band.end.getTime();

    // Find the first label index whose timestamp falls within this night band
    const firstIdx = labelTimes.findIndex(t => t >= bs && t < be);
    if (firstIdx === -1) return;
    let lastIdx = firstIdx;
    for (let j = firstIdx + 1; j < labelTimes.length; j++) {
      if (labelTimes[j] < be) lastIdx = j;
      else break;
    }
    nightRanges.push({ xMin: Math.max(0, firstIdx - 0.5), xMax: lastIdx + 0.5 });
  });

  return nightRanges;
}

function switchRmChart(mode, el) {
  rmChartMode = mode;
  document.querySelectorAll(".rm-chart-toggle[id^='rm-toggle']").forEach(b => b.classList.remove("active"));
  if (el) el.classList.add("active");
  const dailySumEl = document.getElementById("rm-daily-summary");
  if (dailySumEl) dailySumEl.style.display = mode === "daily" ? "block" : "none";
  renderRmMainChart(rmAnalyticsSessions);
}

function switchRmCondition(cond, el) {
  rmChartCondition = cond;
  document.querySelectorAll(".rm-chart-toggle[id^='rm-cond']").forEach(b => b.classList.remove("active"));
  if (el) el.classList.add("active");
  renderRmMainChart(rmAnalyticsSessions);
}

// ── Main analytics loader ─────────────────────────────────────────────────────────────────────────────
async function loadRuntimeAnalytics() {
  const deviceFilter = document.getElementById("rm-analytics-device")?.value;
  const rangeDays    = parseInt(document.getElementById("rm-analytics-range")?.value || "7");
  const since        = new Date(Date.now() - rangeDays * 864e5).toISOString();
  const tableEl      = document.getElementById("rm-sessions-table");

  if (!deviceFilter) {
    if (tableEl) tableEl.innerHTML = '<div class="sched-empty">Select a device from the dropdown to load analytics.</div>';
    return;
  }
  if (tableEl) tableEl.innerHTML = '<div class="sched-empty">Loading…</div>';

  let sessions = [];
  try {
    sessions = await supabaseGetPaged(
      `equipment_runtime_sessions?device_uid=eq.${encodeURIComponent(deviceFilter)}&session_start=gte.${since}&order=session_start.asc`,
      5000
    );
    if (!Array.isArray(sessions)) sessions = [];
  } catch(e) {
    if (tableEl) tableEl.innerHTML = `<div class="sched-empty">Error: ${e.message}</div>`;
    return;
  }

  if (!sessions.length) {
    if (tableEl) tableEl.innerHTML = '<div class="sched-empty">No sessions found for this device in the selected range. Run the Historical Backfill below to populate session data.</div>';
    const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
    ["rm-kpi-sessions","rm-kpi-total-hrs","rm-kpi-avg-dur","rm-kpi-longest",
     "rm-kpi-avg-temp","rm-kpi-avg-heat","rm-kpi-avg-humidity","rm-kpi-peak-pct"
    ].forEach(id => set(id, "—"));
    return;
  }

  // Live join feed data
  if (tableEl) tableEl.innerHTML = '<div class="sched-empty">Correlating feed data…</div>';
  sessions = await joinFeedDataToSessions(sessions);
  rmAnalyticsSessions = sessions;

  const complete  = sessions.filter(s => s.session_end && s.duration_minutes != null);
  const totalMins = complete.reduce((s,r) => s + (r.duration_minutes||0), 0);
  const avgDur    = complete.length ? totalMins / complete.length : 0;
  const longest   = complete.length ? Math.max(...complete.map(r => r.duration_minutes||0)) : 0;
  const temps     = sessions.map(s => s.temp_avg).filter(v => v != null);
  const heats     = sessions.map(s => s.heat_index_avg).filter(v => v != null);
  const humids    = sessions.map(s => s.humidity_avg).filter(v => v != null);
  const peakSess  = sessions.filter(s => s.is_peak).length;
  const avg       = arr => arr.length ? (arr.reduce((a,b)=>a+b,0)/arr.length).toFixed(1) : null;
  const peakPct   = sessions.length ? Math.round(peakSess/sessions.length*100) : 0;

  const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  set("rm-kpi-sessions",     sessions.length);
  set("rm-kpi-total-hrs",    totalMins < 60 ? Math.round(totalMins)+" min" : (totalMins/60).toFixed(1)+" h");
  set("rm-kpi-avg-dur",      avgDur < 60 ? Math.round(avgDur)+" min" : (avgDur/60).toFixed(1)+" h");
  set("rm-kpi-longest",      longest < 60 ? longest+" min" : (longest/60).toFixed(1)+" h");
  set("rm-kpi-avg-temp",     avg(temps)  ? avg(temps)+"°F"  : "—");
  set("rm-kpi-avg-heat",     avg(heats)  ? avg(heats)+"°F"  : "—");
  set("rm-kpi-avg-humidity", avg(humids) ? avg(humids)+"%" : "—");
  set("rm-kpi-peak-pct",     `${peakSess} (${peakPct}%)`);

  renderRmMainChart(sessions);
  renderRmDailySummary(sessions, rangeDays);
  renderRmSessionTable(sessions);
}

// ── Live feed join ────────────────────────────────────────────────────────────────────────────────────
async function joinFeedDataToSessions(sessions) {
  if (!sessions.length) return sessions;

  // Normalize Supabase timestamps — they come back as "2026-06-24 00:03:28+00"
  // (space instead of T, +00 instead of Z). new Date() handles this but URL
  // embedding needs a clean ISO string with no spaces or + signs.
  const toISO = ts => ts ? new Date(ts).toISOString() : null;

  // Add a 2-hour buffer on each side so feed readings that straddle the
  // session window edges are included in the nearest-timestamp lookups.
  const firstStart = new Date(sessions[0].session_start);
  firstStart.setHours(firstStart.getHours() - 2);
  const lastEnd = new Date(sessions[sessions.length-1].session_end || sessions[sessions.length-1].session_start);
  lastEnd.setHours(lastEnd.getHours() + 2);

  const earliest = firstStart.toISOString();
  const latest   = lastEnd.toISOString();

  console.log("[RM Analytics] Fetching feed data:", earliest, "→", latest);

  const [tempRows, heatRows, humidRows, touRows] = await Promise.all([
    supabaseGetPaged(`monitor_feed_readings?feed_key=eq.nws_temp&recorded_at=gte.${earliest}&recorded_at=lte.${latest}&order=recorded_at.asc&select=recorded_at,value`, 5000).catch(e => { console.warn("nws_temp fetch:", e.message); return []; }),
    supabaseGetPaged(`monitor_feed_readings?feed_key=eq.nws_heat_index&recorded_at=gte.${earliest}&recorded_at=lte.${latest}&order=recorded_at.asc&select=recorded_at,value`, 5000).catch(e => { console.warn("nws_heat_index fetch:", e.message); return []; }),
    supabaseGetPaged(`monitor_feed_readings?feed_key=eq.nws_humidity&recorded_at=gte.${earliest}&recorded_at=lte.${latest}&order=recorded_at.asc&select=recorded_at,value`, 5000).catch(e => { console.warn("nws_humidity fetch:", e.message); return []; }),
    supabaseGetPaged(`monitor_feed_readings?feed_key=eq.tou_peak&recorded_at=gte.${earliest}&recorded_at=lte.${latest}&order=recorded_at.asc&select=recorded_at,value`, 5000).catch(e => { console.warn("tou_peak fetch:", e.message); return []; }),
  ]);

  console.log(`[RM Analytics] Feed rows — temp:${tempRows.length} heat:${heatRows.length} humid:${humidRows.length} tou:${touRows.length}`);

  const nearest = (rows, ts) => {
    if (!rows.length || !ts) return null;
    const t = new Date(ts).getTime();
    let best = rows[0];
    for (const r of rows) {
      if (Math.abs(new Date(r.recorded_at).getTime()-t) < Math.abs(new Date(best.recorded_at).getTime()-t)) best = r;
    }
    return best?.value != null ? parseFloat(best.value) : null;
  };

  const rangeAvg = (rows, s0, e0) => {
    if (!rows.length || !s0) return null;
    if (!e0) return nearest(rows, s0);
    const s = new Date(s0).getTime(), e = new Date(e0).getTime();
    const ir = rows.filter(r => { const t = new Date(r.recorded_at).getTime(); return t >= s && t <= e; });
    if (!ir.length) return nearest(rows, s0); // fallback to nearest if nothing in range
    return parseFloat((ir.reduce((a,r) => a + parseFloat(r.value||0), 0) / ir.length).toFixed(1));
  };

  return sessions.map(s => ({
    ...s,
    temp_avg:       rangeAvg(tempRows,  s.session_start, s.session_end),
    heat_index_avg: rangeAvg(heatRows,  s.session_start, s.session_end),
    humidity_avg:   rangeAvg(humidRows, s.session_start, s.session_end),
    is_peak:        (nearest(touRows, s.session_start) == 1),
  }));
}

// ── Main chart ─────────────────────────────────────────────────────────────────────────────────────────
function renderRmMainChart(sessions) {
  const canvas = document.getElementById("rm-main-chart");
  if (!canvas || typeof Chart === "undefined") return;
  if (rmMainChart) { try { rmMainChart.destroy(); } catch(e) {} rmMainChart = null; }

  const complete = sessions.filter(s => s.session_end && s.duration_minutes != null);
  if (!complete.length) return;

  const condKey   = rmChartCondition === "temp" ? "temp_avg" : rmChartCondition === "heat" ? "heat_index_avg" : "humidity_avg";
  const condLabel = rmChartCondition === "temp" ? "Temperature (°F)" : rmChartCondition === "heat" ? "Heat Index (°F)" : "Humidity (%)";
  const condColor = rmChartCondition === "temp" ? "#e67e22" : rmChartCondition === "heat" ? "#c0392b" : "#2980b9";

  if (rmChartMode === "scatter") {
    // Line chart: session start time on x-axis, duration and condition as two lines
    const sorted    = complete.filter(s => s[condKey] != null)
                              .slice().sort((a,b) => new Date(a.session_start)-new Date(b.session_start));
    const labels    = sorted.map(s => new Date(s.session_start).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}));
    const labelISOs = sorted.map(s => s.session_start);
    const durLine   = sorted.map(s => s.duration_minutes||0);
    const condLine  = sorted.map(s => s[condKey]);
    const ptColors  = sorted.map(s => s.is_peak ? "rgba(192,57,43,0.85)" : "rgba(29,158,117,0.85)");

    // Day/night shading for line chart
    let nightRanges = [];
    if (rmShowDayNight) {
      const bands = buildDayNightBands(sorted);
      nightRanges = buildDayNightAnnotations(bands, labelISOs);
    }
    const lineNightPlugin = buildDayNightPlugin(nightRanges);

    rmMainChart = new Chart(canvas, {
      type: "line",
      plugins: rmShowDayNight ? [lineNightPlugin] : [],
      data: {
        labels,
        datasets: [
          {
            label:                "Duration (min)",
            data:                 durLine,
            borderColor:          "rgba(29,158,117,0.9)",
            backgroundColor:      "rgba(29,158,117,0.08)",
            pointBackgroundColor: ptColors,
            pointBorderColor:     ptColors,
            pointRadius:          4,
            pointHoverRadius:     6,
            borderWidth:          2,
            tension:              0.3,
            fill:                 true,
            yAxisID:              "y",
          },
          {
            label:                condLabel,
            data:                 condLine,
            borderColor:          condColor,
            backgroundColor:      "transparent",
            pointBackgroundColor: condColor,
            pointRadius:          sorted.length > 60 ? 0 : 3,
            borderWidth:          2,
            tension:              0.3,
            fill:                 false,
            yAxisID:              "y2",
            spanGaps:             true,
          }
        ]
      },
      options: {
        responsive:true, maintainAspectRatio:false,
        interaction:{ mode:"index", intersect:false },
        plugins: {
          legend:{ display:true, position:"top", labels:{ font:{size:11},
            generateLabels: () => [
              { text:"On-Peak cycle",  fillStyle:"rgba(192,57,43,0.85)",  strokeStyle:"rgba(192,57,43,0.85)",  lineWidth:1 },
              { text:"Off-Peak cycle", fillStyle:"rgba(29,158,117,0.85)", strokeStyle:"rgba(29,158,117,0.85)", lineWidth:1 },
              { text:condLabel,        fillStyle:"transparent",           strokeStyle:condColor,               lineWidth:2 },
              ...(rmShowDayNight ? [{text:"Night period",fillStyle:"rgba(20,20,60,0.09)",strokeStyle:"rgba(80,80,140,0.4)",lineWidth:1}] : [])
            ]
          }},
          title:{ display:true, text:`Cycle Duration & ${condLabel} Over Time`+(rmShowDayNight?" 🌙":""), font:{size:12,weight:"500"}, color:"#888780" },
          tooltip:{ callbacks:{
            label: ctx => ctx.datasetIndex === 0
              ? `Duration: ${ctx.parsed.y} min | ${sorted[ctx.dataIndex]?.is_peak ? "ON-PEAK" : "Off-Peak"}`
              : `${condLabel}: ${ctx.parsed.y}`
          }}
        },
        scales: {
          x:  { ticks:{ maxTicksLimit:12, font:{size:9}, maxRotation:45 }, grid:{ display:false } },
          y:  { beginAtZero:true, title:{ display:true, text:"Duration (min)", font:{size:10} }, ticks:{ font:{size:10} }, grid:{ color:"rgba(0,0,0,0.05)" } },
          y2: { position:"right", title:{ display:true, text:condLabel, font:{size:10} }, ticks:{ font:{size:10} }, grid:{ display:false } }
        }
      }
    });

  } else if (rmChartMode === "daily") {
    const rangeDays = parseInt(document.getElementById("rm-analytics-range")?.value || "7");
    const days = [];
    for (let i=rangeDays-1;i>=0;i--) { const d=new Date(Date.now()-i*864e5); days.push(d.toISOString().split("T")[0]); }
    const daily = {};
    days.forEach(d => daily[d] = {mins:0, conds:[]});
    complete.forEach(s => {
      const day = s.session_start.split("T")[0];
      if (daily[day]) { daily[day].mins += s.duration_minutes||0; if (s[condKey]!=null) daily[day].conds.push(s[condKey]); }
    });
    rmMainChart = new Chart(canvas, {
      type:"bar",
      data:{
        labels:days.map(d=>{const dt=new Date(d+"T12:00:00");return dt.toLocaleDateString([],{month:"short",day:"numeric"});}),
        datasets:[
          {label:"Runtime (hrs)",data:days.map(d=>parseFloat((daily[d].mins/60).toFixed(2))),backgroundColor:"rgba(29,158,117,0.6)",borderColor:"#1D9E75",borderWidth:1,borderRadius:3,yAxisID:"y"},
          {label:condLabel,data:days.map(d=>daily[d].conds.length?parseFloat((daily[d].conds.reduce((a,b)=>a+b,0)/daily[d].conds.length).toFixed(1)):null),type:"line",borderColor:condColor,backgroundColor:"transparent",pointRadius:3,pointBackgroundColor:condColor,borderWidth:2,yAxisID:"y2",spanGaps:true}
        ]
      },
      options:{
        responsive:true,maintainAspectRatio:false,interaction:{mode:"index",intersect:false},
        plugins:{legend:{display:true,position:"top",labels:{font:{size:11}}},title:{display:true,text:"Daily Runtime vs "+condLabel,font:{size:12,weight:"500"},color:"#888780"}},
        scales:{
          x:{grid:{display:false},ticks:{font:{size:10}}},
          y:{beginAtZero:true,title:{display:true,text:"Runtime (hrs)",font:{size:10}},ticks:{font:{size:10},callback:v=>v+"h"}},
          y2:{position:"right",title:{display:true,text:condLabel,font:{size:10}},ticks:{font:{size:10}},grid:{display:false}}
        }
      }
    });

  } else {
    // Timeline — each cycle as a bar, condition overlaid as line
    const labels  = complete.map(s => new Date(s.session_start).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}));
    // Keep raw Date strings for day/night calculation
    const labelISOs = complete.map(s => s.session_start);
    const durData  = complete.map(s => s.duration_minutes||0);
    const condData = complete.map(s => s[condKey]);
    const colors   = complete.map(s => s.is_peak ? "rgba(192,57,43,0.7)" : "rgba(29,158,117,0.6)");

    // Build day/night bands if toggle is on
    let nightRanges = [];
    if (rmShowDayNight) {
      const bands = buildDayNightBands(complete);
      nightRanges = buildDayNightAnnotations(bands, labelISOs);
    }
    const timelineNightPlugin = buildDayNightPlugin(nightRanges);

    rmMainChart = new Chart(canvas, {
      type:"bar",
      plugins: rmShowDayNight ? [timelineNightPlugin] : [],
      data:{
        labels,
        datasets:[
          {label:"Duration (min)",data:durData,backgroundColor:colors,borderRadius:2,yAxisID:"y"},
          {label:condLabel,data:condData,type:"line",borderColor:condColor,backgroundColor:"transparent",pointRadius:complete.length>50?0:3,pointBackgroundColor:condColor,borderWidth:2,yAxisID:"y2",spanGaps:true}
        ]
      },
      options:{
        responsive:true,maintainAspectRatio:false,interaction:{mode:"index",intersect:false},
        plugins:{
          legend:{display:true,position:"top",labels:{font:{size:11},generateLabels:()=>[
            {text:"On-Peak cycle",fillStyle:"rgba(192,57,43,0.7)",strokeStyle:"rgba(192,57,43,0.7)",lineWidth:1},
            {text:"Off-Peak cycle",fillStyle:"rgba(29,158,117,0.6)",strokeStyle:"rgba(29,158,117,0.6)",lineWidth:1},
            {text:condLabel,fillStyle:"transparent",strokeStyle:condColor,lineWidth:2},
            ...(rmShowDayNight?[{text:"Night period",fillStyle:"rgba(20,20,60,0.09)",strokeStyle:"rgba(80,80,140,0.4)",lineWidth:1}]:[])
          ]}},
          title:{display:true,text:"Cycle Timeline — Duration & "+condLabel+(rmShowDayNight?" 🌙":""),font:{size:12,weight:"500"},color:"#888780"},
          tooltip:{callbacks:{label:ctx=>ctx.datasetIndex===0?`Duration: ${ctx.parsed.y} min | ${complete[ctx.dataIndex]?.is_peak?"ON-PEAK":"Off-Peak"}`:`${condLabel}: ${ctx.parsed.y}`}}
        },
        scales:{
          x:{ticks:{maxTicksLimit:12,font:{size:9},maxRotation:45},grid:{display:false}},
          y:{beginAtZero:true,title:{display:true,text:"Duration (min)",font:{size:10}},ticks:{font:{size:10}}},
          y2:{position:"right",title:{display:true,text:condLabel,font:{size:10}},ticks:{font:{size:10}},grid:{display:false}}
        }
      }
    });
  }
}

// ── Daily summary table ─────────────────────────────────────────────────────────────────────────────────
function renderRmDailySummary(sessions, rangeDays) {
  const el = document.getElementById("rm-daily-table");
  if (!el) return;
  const days = [];
  for (let i=rangeDays-1;i>=0;i--) { const d=new Date(Date.now()-i*864e5); days.push(d.toISOString().split("T")[0]); }
  const daily = {};
  days.forEach(d => daily[d] = {cycles:0,mins:0,peakCycles:0,temps:[],heats:[],humids:[]});
  sessions.forEach(s => {
    const day = s.session_start?.split("T")[0];
    if (!daily[day]) return;
    daily[day].cycles++;
    daily[day].mins += s.duration_minutes||0;
    if (s.is_peak) daily[day].peakCycles++;
    if (s.temp_avg       != null) daily[day].temps.push(s.temp_avg);
    if (s.heat_index_avg != null) daily[day].heats.push(s.heat_index_avg);
    if (s.humidity_avg   != null) daily[day].humids.push(s.humidity_avg);
  });
  const avg    = arr => arr.length ? (arr.reduce((a,b)=>a+b,0)/arr.length).toFixed(1) : "—";
  const fmtHrs = m => m < 60 ? Math.round(m)+"min" : (m/60).toFixed(1)+"h";
  const active = days.filter(d => daily[d].cycles > 0);
  if (!active.length) { el.innerHTML = '<div class="sched-empty">No sessions in this range.</div>'; return; }
  el.innerHTML = `
    <div class="rm-daily-row" style="background:var(--surface2);font-size:10px;font-weight:700;color:var(--text-hint);text-transform:uppercase;letter-spacing:.04em;">
      <span>Date</span><span>Cycles</span><span>Total RT</span><span>Avg Cycle</span><span>Avg Temp</span><span>Avg Heat Idx</span><span>Avg Humid</span><span>Peak Cycles</span>
    </div>
    ${active.map(d => {
      const r=daily[d];
      const avgDur=r.cycles?Math.round(r.mins/r.cycles):0;
      const dt=new Date(d+"T12:00:00");
      return `<div class="rm-daily-row">
        <span style="font-weight:600;">${dt.toLocaleDateString([],{weekday:"short",month:"short",day:"numeric"})}</span>
        <span>${r.cycles}</span>
        <span style="color:var(--blue-dark);font-weight:600;">${fmtHrs(r.mins)}</span>
        <span>${avgDur} min</span>
        <span style="color:var(--red);">${avg(r.temps)}${r.temps.length?"°F":""}</span>
        <span style="color:var(--amber);">${avg(r.heats)}${r.heats.length?"°F":""}</span>
        <span style="color:var(--blue-dark);">${avg(r.humids)}${r.humids.length?"%":""}</span>
        <span style="color:${r.peakCycles>0?"var(--red)":"var(--text-hint)"};">${r.peakCycles} / ${r.cycles}</span>
      </div>`;
    }).join("")}`;
}

// ── Session detail table ───────────────────────────────────────────────────────────────────────────────
function renderRmSessionTable(sessions, limitOverride) {
  const el       = document.getElementById("rm-sessions-table");
  const countEl  = document.getElementById("rm-sessions-count");
  const sliderEl = document.getElementById("rm-sessions-slider");
  if (!el) return;
  if (!sessions.length) { el.innerHTML = '<div class="sched-empty">No sessions found.</div>'; return; }

  // Respect slider value (default 50); caller can override for re-renders
  const limit   = limitOverride ?? parseInt(sliderEl?.value || "50");
  const sorted  = sessions.slice().reverse();         // newest first
  const visible = sorted.slice(0, limit);
  const total   = sorted.length;

  // Update slider bounds to match actual session count
  if (sliderEl) {
    sliderEl.max = Math.max(total, 10);
    // Snap max option to total so user can always show all
    if (parseInt(sliderEl.value) > total) sliderEl.value = total;
  }
  if (countEl) countEl.textContent = `${visible.length} of ${total} session${total !== 1 ? "s" : ""}`;

  const fmtDur = m => m==null?"—":m<60?`${Math.round(m)} min`:`${(m/60).toFixed(1)} h`;
  const fmtTs  = ts => ts?new Date(ts).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}):"—";
  const fmtF   = (v,u) => v!=null?parseFloat(v).toFixed(1)+u:"—";

  el.innerHTML = `
    <div class="rm-session-row rm-session-header">
      <span>Start</span><span>Duration</span><span>Temp °F</span><span>Heat Idx</span><span>Humidity</span><span>TOU</span><span>Source</span><span>Status</span>
    </div>
    ${visible.map(s => {
      const dur=s.duration_minutes;
      const dc=dur==null?"var(--text-hint)":dur>30?"var(--red)":dur>15?"var(--amber)":"var(--text-primary)";
      const pk=s.is_peak
        ?'<span style="font-size:9px;padding:1px 5px;border-radius:8px;background:var(--red-lt,#fef2f2);color:var(--red);font-weight:700;">PEAK</span>'
        :'<span style="font-size:9px;padding:1px 5px;border-radius:8px;background:var(--surface2);color:var(--text-hint);">off</span>';
      return `<div class="rm-session-row">
        <span style="font-size:10px;">${fmtTs(s.session_start)}</span>
        <span style="font-weight:600;color:${dc};">${fmtDur(dur)}</span>
        <span style="color:var(--red);">${fmtF(s.temp_avg,"°")}</span>
        <span style="color:var(--amber);">${fmtF(s.heat_index_avg,"°")}</span>
        <span style="color:var(--blue-dark);">${fmtF(s.humidity_avg,"%")}</span>
        <span>${pk}</span>
        <span style="font-size:10px;color:var(--text-hint);">${s.trigger_source||"—"}</span>
        <span style="font-size:10px;color:${s.session_end?"var(--green-dark)":"var(--amber)"};">${s.session_end?"Complete":"Open"}</span>
      </div>`;
    }).join("")}`;
}

// Slider oninput handler — re-renders the table at the new row count without
// re-fetching from Supabase (uses the already-loaded rmAnalyticsSessions array)
function rmUpdateSessionSlider(val) {
  const labelEl = document.getElementById("rm-sessions-slider-label");
  const n = parseInt(val);
  if (labelEl) labelEl.textContent = n >= (rmAnalyticsSessions?.length || 0) ? "All" : `${n} rows`;
  if (Array.isArray(rmAnalyticsSessions) && rmAnalyticsSessions.length) {
    renderRmSessionTable(rmAnalyticsSessions, n);
  }
}

// ── CSV export ─────────────────────────────────────────────────────────────────────────────────────────────
function exportRuntimeCSV() {
  const sessions = rmAnalyticsSessions;
  if (!sessions.length) { setStatus("error","No data to export."); return; }
  const headers = ["Device","Start","End","Duration (min)","Temp Avg (°F)","Heat Index Avg (°F)","Humidity Avg (%)","On-Peak","Source"];
  const rows = sessions.map(s => [
    unitName(s.device_uid)||s.device_uid,
    s.session_start, s.session_end||"",
    s.duration_minutes||"",
    s.temp_avg||"", s.heat_index_avg||"", s.humidity_avg||"",
    s.is_peak?"Yes":"No",
    s.trigger_source||""
  ].map(v=>`"${v}"`).join(","));
  const csv  = [headers.join(","),...rows].join("\n");
  const blob = new Blob([csv],{type:"text/csv"});
  const a    = document.createElement("a");
  const dev  = document.getElementById("rm-analytics-device")?.value;
  a.href = URL.createObjectURL(blob);
  a.download = `runtime_sessions_${unitName(dev)||dev||"all"}_${new Date().toISOString().split("T")[0]}.csv`;
  a.click(); URL.revokeObjectURL(a.href);
  setStatus("ready",`Exported ${sessions.length} sessions.`);
}

// ── Backfill

// ── Backfill ──────────────────────────────────────────────────────────────────
async function runRuntimeBackfill() {
  const deviceFilter = document.getElementById("rm-backfill-device")?.value;
  const fromDate     = document.getElementById("rm-backfill-from")?.value;
  const toDate       = document.getElementById("rm-backfill-to")?.value;
  const progEl       = document.getElementById("rm-backfill-progress");
  const barEl        = document.getElementById("rm-backfill-bar");
  const statusEl     = document.getElementById("rm-backfill-status");
  const resultEl     = document.getElementById("rm-backfill-result");

  if (!fromDate || !toDate) { if(resultEl) resultEl.textContent = "⚠ Select a date range."; return; }
  if (progEl) progEl.style.display = "block";
  if (resultEl) resultEl.textContent = "Starting backfill…";

  const onThreshold = parseFloat(rmSettings.current_on_threshold || "0.5");
  const feedKey     = rmSettings.feed_key || null;
  const fromISO     = fromDate + "T00:00:00.000Z";
  const toISO       = toDate   + "T23:59:59.999Z";

  // Determine which devices to process
  let deviceUids = [];
  if (deviceFilter) {
    deviceUids = [deviceFilter];
  } else {
    deviceUids = (DEVICES || []).filter(d => !d.type || d.type === "relay").map(d => d.uid);
  }

  if (!deviceUids.length) { if(resultEl) resultEl.textContent = "⚠ No devices found."; return; }

  let totalSessions = 0;
  let totalProcessed = 0;

  for (let di = 0; di < deviceUids.length; di++) {
    const uid = deviceUids[di];
    const pct = Math.round((di / deviceUids.length) * 100);
    if (barEl)    barEl.style.width = pct + "%";
    if (statusEl) statusEl.textContent = `Scanning ${unitName(uid)||uid} (${di+1}/${deviceUids.length})…`;

    // Fetch readings in chronological order for this device in range
    let readings = [];
    try {
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(uid)}&recorded_at=gte.${fromISO}&recorded_at=lte.${toISO}&order=recorded_at.asc&limit=5000&select=recorded_at,current`
      );
      readings = Array.isArray(rows) ? rows : [];
    } catch(e) { continue; }

    if (!readings.length) continue;

    // Delete existing sessions for this device in this range to avoid dupes
    try {
      await supabaseDelete("equipment_runtime_sessions",
        `device_uid=eq.${encodeURIComponent(uid)}&session_start=gte.${fromISO}&session_start=lte.${toISO}&trigger_source=eq.backfill`);
    } catch(e) {}

    // Detect transitions
    const sessions = [];
    let sessionStart = null;
    let prevOn = false;

    for (const row of readings) {
      const amps  = row.current != null ? row.current / 10 : 0;
      const isOn  = amps >= onThreshold;
      if (isOn && !prevOn) {
        sessionStart = row.recorded_at;
      } else if (!isOn && prevOn && sessionStart) {
        sessions.push({ start: sessionStart, end: row.recorded_at });
        sessionStart = null;
      }
      prevOn = isOn;
    }
    // If still ON at end of range, close with null end
    if (prevOn && sessionStart) sessions.push({ start: sessionStart, end: null });

    // Fetch feed correlation if configured
    let feedReadings = [];
    if (feedKey) {
      try {
        const fr = await supabaseGet(
          `monitor_feed_readings?feed_key=eq.${encodeURIComponent(feedKey)}&recorded_at=gte.${fromISO}&recorded_at=lte.${toISO}&order=recorded_at.asc&limit=2000&select=recorded_at,value`
        );
        feedReadings = Array.isArray(fr) ? fr : [];
      } catch(e) {}
    }

    const getFeedAtTime = (ts) => {
      if (!feedReadings.length || !ts) return null;
      const target = new Date(ts).getTime();
      let closest = feedReadings[0];
      for (const fr of feedReadings) {
        if (Math.abs(new Date(fr.recorded_at).getTime() - target) < Math.abs(new Date(closest.recorded_at).getTime() - target)) closest = fr;
      }
      return closest?.value != null ? parseFloat(closest.value) : null;
    };

    const getAvgFeed = (startTs, endTs) => {
      if (!feedReadings.length || !startTs || !endTs) return null;
      const s = new Date(startTs).getTime(), e = new Date(endTs).getTime();
      const inRange = feedReadings.filter(fr => { const t = new Date(fr.recorded_at).getTime(); return t >= s && t <= e; });
      if (!inRange.length) return null;
      return inRange.reduce((a,fr) => a + parseFloat(fr.value||0), 0) / inRange.length;
    };

    // Write sessions to Supabase
    for (const sess of sessions) {
      const dur = sess.end ? Math.round((new Date(sess.end) - new Date(sess.start)) / 60000) : null;
      try {
        await supabasePost("equipment_runtime_sessions", {
          device_uid:        uid,
          session_start:     sess.start,
          session_end:       sess.end,
          duration_minutes:  dur,
          feed_key:          feedKey,
          feed_value_start:  getFeedAtTime(sess.start),
          feed_value_end:    sess.end ? getFeedAtTime(sess.end) : null,
          feed_value_avg:    sess.end ? getAvgFeed(sess.start, sess.end) : null,
          group_number:      null,
          trigger_source:    "backfill",
          created_at:        new Date().toISOString()
        });
        totalSessions++;
      } catch(e) { console.warn("backfill insert:", e.message); }
    }
    totalProcessed++;
  }

  if (barEl)    barEl.style.width = "100%";
  if (statusEl) statusEl.textContent = "Complete.";
  if (resultEl) resultEl.textContent = `✓ Backfill complete — ${totalSessions} sessions reconstructed across ${totalProcessed} device(s). Refresh Analytics to view.`;
  setTimeout(() => { if(progEl) progEl.style.display = "none"; }, 3000);
}

// ── SQL DDL hint for new tables (logged to console on init) ───────────────────
function logRmDdlHint() {
  console.info(`[Runtime Monitor] Required Supabase tables:

CREATE TABLE IF NOT EXISTS equipment_runtime_sessions (
  id                bigserial PRIMARY KEY,
  device_uid        text NOT NULL,
  session_start     timestamptz NOT NULL,
  session_end       timestamptz,
  duration_minutes  numeric,
  feed_key          text,
  feed_value_start  numeric,
  feed_value_end    numeric,
  feed_value_avg    numeric,
  group_number      integer,
  trigger_source    text,
  notes             text,
  created_at        timestamptz DEFAULT now()
);
CREATE INDEX ON equipment_runtime_sessions (device_uid, session_start);

CREATE TABLE IF NOT EXISTS runtime_monitor_schedules (
  id          bigserial PRIMARY KEY,
  name        text NOT NULL,
  mode        text NOT NULL,
  target_type text,
  target_id   text,
  config      jsonb,
  enabled     boolean DEFAULT true,
  created_at  timestamptz DEFAULT now(),
  updated_at  timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS runtime_monitor_triggers (
  id                    bigserial PRIMARY KEY,
  name                  text NOT NULL,
  target_type           text,
  target_id             text,
  activate_feed         text NOT NULL,
  activate_op           text NOT NULL,
  activate_threshold    numeric NOT NULL,
  deactivate_feed       text,
  deactivate_op         text,
  deactivate_threshold  numeric,
  season_guard          text,
  min_rest_minutes      integer DEFAULT 30,
  enabled               boolean DEFAULT true,
  last_fired_at         timestamptz,
  created_at            timestamptz DEFAULT now(),
  updated_at            timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS runtime_monitor_log (
  id             bigserial PRIMARY KEY,
  action         text,
  device_uid     text,
  target_type    text,
  target_id      text,
  lc_hex         text,
  device_count   integer,
  trigger_source text,
  fired_at       timestamptz DEFAULT now()
);`);
}

