// ── Master Assets Inventory ───────────────────────────────────────────────────
async function renderMasterAssets() {
  const tbody     = document.getElementById("asset-master-tbody");
  const ungrouped = document.getElementById("asset-ungrouped-callout");
  const ugList    = document.getElementById("asset-ungrouped-list");
  if (!tbody) return;

  tbody.innerHTML = `<tr><td colspan="7" style="padding:20px;text-align:center;color:var(--text-hint);">Loading…</td></tr>`;

  // ── Always load fresh from Supabase ───────────────────────────────────────
  let relayDevs     = [];
  let evRows        = [];
  let battRows      = [];
  let genRows       = [];
  let thermRows     = [];
  let groupMap      = {}; // { device_uid: [group_numbers] }
  let groupNameMap  = {}; // { group_number: name }

  try {
    // Helper: safe fetch that always returns an array
    const safeGet = async (q) => {
      try {
        const r = await supabaseGet(q);
        return Array.isArray(r) ? r : [];
      } catch(e) { return []; }
    };

    // Helper: merge Supabase rows with localStorage fallback (same pattern as battery/generator tabs)
    const safeGetWithLocal = async (q, storageKey) => {
      let dbRows = [];
      try {
        const r = await supabaseGet(q);
        if (Array.isArray(r)) dbRows = r;
      } catch(e) {}
      let localRows = [];
      try {
        const saved = localStorage.getItem(storageKey);
        if (saved) localRows = JSON.parse(saved);
      } catch(e) {}
      const dbIds = new Set(dbRows.map(r => r.asset_id));
      return [...dbRows, ...localRows.filter(r => !dbIds.has(r.asset_id))];
    };

    const [devices, assignments, ev, batt, gen, therm] = await Promise.all([
      safeGet("devices?order=name.asc"),
      safeGet("device_groups?order=group_number"),
      safeGetWithLocal("ev_chargers?enabled=eq.true&order=enrolled_at.asc",       "lcp_ev_chargers_v1"),
      safeGetWithLocal("battery_assets?enabled=eq.true&order=enrolled_at.asc",   "lcp_battery_assets_v1"),
      safeGetWithLocal("generator_assets?enabled=eq.true&order=enrolled_at.asc", "lcp_generator_assets_v1"),
      safeGetWithLocal("thermostat_assets?enabled=eq.true&order=enrolled_at.asc","lcp_thermostat_assets_v1"),
    ]);

    relayDevs = (Array.isArray(devices) ? devices : []).filter(d => !d.uid?.includes("PLACEHOLDER"));

    const assignArr = Array.isArray(assignments) ? assignments : [];

    assignArr.forEach(a => {
      if (!groupMap[a.device_uid]) groupMap[a.device_uid] = [];
      groupMap[a.device_uid].push(a.group_number);
      if (a.group_name) groupNameMap[a.group_number] = a.group_name;
    });
    // Fill any missing names
    Object.keys(groupMap).forEach(uid => groupMap[uid].forEach(n => {
      if (!groupNameMap[n]) groupNameMap[n] = `Group ${n}`;
    }));

    evRows   = ev   || [];
    battRows = batt || [];
    genRows  = gen  || [];
    thermRows = therm || [];

  } catch(e) {
    console.error("renderMasterAssets load error:", e);
    tbody.innerHTML = `<tr><td colspan="7" style="padding:20px;text-align:center;color:var(--red);">Error loading assets: ${e.message}</td></tr>`;
    return;
  }

  // ── Build rows ─────────────────────────────────────────────────────────────
  const TYPE_META = {
    relay:     { icon:"⚡", label:"Relay Device",   color:"var(--text-primary)" },
    ev:        { icon:"🔌", label:"EV Charger",      color:"var(--blue-dark)"   },
    battery:   { icon:"🔋", label:"Battery System",  color:"var(--green-dark)"  },
    generator: { icon:"⚙️", label:"Generator",       color:"var(--amber)"       },
    thermostat:{ icon:"🌡️", label:"Thermostat",      color:"var(--purple)"      },
  };

  const rows = [];

  relayDevs.forEach(d => {
    const gnums  = groupMap[d.uid] || [];
    const gNames = gnums.map(n => groupNameMap[n] || `G${n}`);
    rows.push({ type:"relay", name:d.name||d.uid, uid:d.uid, groups:gNames, gnums, status:null, qty:1, notes:d.location||"" });
  });

  evRows.forEach(c => {
    const uid    = `ev_${c.station_id||c.asset_id||c.id}`;
    const gnums  = groupMap[uid] || [];
    const gNames = gnums.map(n => groupNameMap[n] || `G${n}`);
    rows.push({ type:"ev", name:c.name||c.station_id, uid, groups:gNames, gnums, status:c.status||null, qty:1,
      notes:[c.brand, c.location].filter(Boolean).join(" — ") });
  });

  battRows.forEach(a => {
    const uid    = `batt_${a.asset_id}`;
    const gnums  = groupMap[uid] || [];
    const gNames = gnums.map(n => groupNameMap[n] || `G${n}`);
    rows.push({ type:"battery", name:a.name||a.asset_id, uid, groups:gNames, gnums, status:a.status||null, qty:1,
      notes:`${a.capacity_kwh||"?"}kWh / ${a.max_kw||"?"}kW${a.integration?` (${a.integration})`:""}`  });
  });

  genRows.forEach(a => {
    const uid    = `gen_${a.asset_id}`;
    const gnums  = groupMap[uid] || [];
    const gNames = gnums.map(n => groupNameMap[n] || `G${n}`);
    rows.push({ type:"generator", name:a.name||a.asset_id, uid, groups:gNames, gnums, status:a.status||null, qty:1,
      notes:`${a.capacity_kw||"?"}kW${a.integration?` (${a.integration})`:""}`  });
  });

  thermRows.forEach(a => {
    const uid    = `therm_${a.asset_id}`;
    const gnums  = groupMap[uid] || [];
    const gNames = gnums.map(n => groupNameMap[n] || `G${n}`);
    rows.push({ type:"thermostat", name:a.name||a.asset_id, uid, groups:gNames, gnums, status:a.status||null, qty:1,
      notes:`Cool: ${a.normal_cool||"?"}°F / Setback: ${a.setback_temp||"?"}°F${a.integration?` (${a.integration})`:""}`  });
  });

  // ── Summary counts ─────────────────────────────────────────────────────────
  const counts = { relay:0, ev:0, battery:0, generator:0, thermostat:0 };
  rows.forEach(r => counts[r.type] = (counts[r.type]||0) + 1);
  // Ungrouped = any asset whose UID isn't in groupMap
  const allAssetUids = [
    ...relayDevs.map(d => ({ uid:d.uid, name:d.name, icon:"⚡" })),
    ...evRows.map(c => ({ uid:`ev_${c.station_id||c.asset_id||c.id}`, name:c.name, icon:"🔌" })),
    ...battRows.map(a => ({ uid:`batt_${a.asset_id}`, name:a.name, icon:"🔋" })),
    ...genRows.map(a => ({ uid:`gen_${a.asset_id}`, name:a.name, icon:"⚙️" })),
    ...thermRows.map(a => ({ uid:`therm_${a.asset_id}`, name:a.name, icon:"🌡️" })),
  ];
  const ungroupedAssets = allAssetUids.filter(a => !(groupMap[a.uid]||[]).length);

  document.getElementById("asset-count-relay").textContent     = counts.relay;
  document.getElementById("asset-count-ev").textContent        = counts.ev;
  document.getElementById("asset-count-battery").textContent   = counts.battery;
  document.getElementById("asset-count-generator").textContent = counts.generator;
  const thermCountEl = document.getElementById("asset-count-thermostat");
  if (thermCountEl) thermCountEl.textContent = counts.thermostat;
  document.getElementById("asset-count-total").textContent     = rows.length;
  document.getElementById("asset-count-ungrouped").textContent = ungroupedAssets.length;

  // ── Ungrouped callout ──────────────────────────────────────────────────────
  if (ungrouped && ugList) {
    ungrouped.style.display = ungroupedAssets.length ? "block" : "none";
    ugList.innerHTML = ungroupedAssets.map(a =>
      `<span style="padding:4px 10px;background:var(--surface2);border:0.5px solid var(--amber);border-radius:20px;font-size:11px;font-weight:600;color:var(--amber);">${a.icon} ${a.name||a.uid}</span>`
    ).join("");
  }

  // ── Table ──────────────────────────────────────────────────────────────────
  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="7" style="padding:20px;text-align:center;color:var(--text-hint);">No assets found.</td></tr>`;
    return;
  }

  const ORDER = { relay:0, ev:1, battery:2, generator:3, thermostat:4 };
  rows.sort((a,b) => (ORDER[a.type]||0)-(ORDER[b.type]||0) || (a.name||"").localeCompare(b.name||""));

  tbody.innerHTML = rows.map((r, i) => {
    const meta = TYPE_META[r.type] || { icon:"📦", label:r.type, color:"var(--text-secondary)" };
    const groupBadges = r.groups.length
      ? r.groups.map(g => `<span style="padding:2px 7px;background:var(--surface2);border:0.5px solid var(--border-md);border-radius:10px;font-size:10px;">${g}</span>`).join(" ")
      : `<span style="font-size:10px;color:${r.type==="relay"?"var(--amber)":"var(--text-hint)"};">${r.type==="relay"?"⚠ Ungrouped":"—"}</span>`;
    const statusBadge = r.status
      ? `<span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:600;
           background:${["online","running"].includes(r.status)?"var(--green-lt)":"var(--surface2)"};
           color:${["online","running"].includes(r.status)?"var(--green-dark)":"var(--text-hint)"};">
           ${r.status}</span>`
      : `<span style="font-size:10px;color:var(--text-hint);">—</span>`;

    return `<tr style="border-bottom:0.5px solid var(--border);${i%2?"background:var(--surface2);":""}">
      <td style="padding:8px 10px;font-weight:600;color:var(--text-primary);">${r.name}</td>
      <td style="padding:8px 10px;">
        <span style="display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:10px;background:var(--surface2);font-size:11px;font-weight:600;color:${meta.color};">
          ${meta.icon} ${meta.label}
        </span>
      </td>
      <td style="padding:8px 10px;font-family:monospace;font-size:10px;color:var(--text-hint);max-width:160px;overflow:hidden;text-overflow:ellipsis;">${r.uid||"—"}</td>
      <td style="padding:8px 10px;">${groupBadges}</td>
      <td style="padding:8px 10px;">${statusBadge}</td>
      <td style="padding:8px 10px;text-align:center;">
        <input type="number" value="${r.qty||1}" min="1"
          style="width:50px;padding:3px 6px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:12px;text-align:center;"
          title="Quantity placeholder" />
      </td>
      <td style="padding:8px 10px;font-size:11px;color:var(--text-secondary);">${r.notes||""}</td>
    </tr>`;
  }).join("");
}
// ── End Master Assets ─────────────────────────────────────────────────────────

async function initFleetHealth() {
  // Always reload devices from DB to ensure we have the full current list.
  await loadDevicesFromDB().catch(e => console.warn("loadDevicesFromDB in initFleetHealth:", e));
  await loadThresholds();
  await loadFleetHealth();
  scheduleNightlyCheck();
  renderMasterAssets();
}

async function loadThresholds() {
  try {
    const rows = await supabaseGet("program_settings?select=setting_key,setting_value");
    if (Array.isArray(rows)) {
      rows.forEach(r => {
        switch(r.setting_key) {
          case "voltage_warn":       fleetThresholds.voltWarn      = parseFloat(r.setting_value); break;
          case "voltage_critical":   fleetThresholds.voltCrit      = parseFloat(r.setting_value); break;
          case "temp_high_warn":     fleetThresholds.tempHighWarn  = parseFloat(r.setting_value); break;
          case "temp_high_critical": fleetThresholds.tempHighCrit  = parseFloat(r.setting_value); break;
          case "temp_low_warn":      fleetThresholds.tempLowWarn   = parseFloat(r.setting_value); break;
          case "no_comms_warn_hrs":  fleetThresholds.noCommsWarn   = parseFloat(r.setting_value); break;
          case "no_comms_crit_hrs":  fleetThresholds.noCommsCrit   = parseFloat(r.setting_value); break;
          case "health_check_enabled":
            const sel = document.getElementById("th-health-enabled");
            if (sel) sel.value = r.setting_value;
            break;
        }
      });
      const fields = {
        "th-volt-warn":       fleetThresholds.voltWarn,
        "th-volt-crit":       fleetThresholds.voltCrit,
        "th-temp-high-warn":  fleetThresholds.tempHighWarn,
        "th-temp-high-crit":  fleetThresholds.tempHighCrit,
        "th-temp-low-warn":   fleetThresholds.tempLowWarn,
        "th-nocomms-warn":    fleetThresholds.noCommsWarn,
        "th-nocomms-crit":    fleetThresholds.noCommsCrit
      };
      Object.entries(fields).forEach(([id, val]) => {
        const el = document.getElementById(id);
        if (el) el.value = val;
      });
      // Update no comms label
      const ncEl = document.getElementById("fh-nocomms-hrs");
      if (ncEl) ncEl.textContent = fleetThresholds.noCommsWarn;
    }
  } catch(e) { console.error("loadThresholds error:", e); }
}

async function saveThresholds() {
  const statusEl = document.getElementById("th-save-status");
  const mappings = [
    ["voltage_warn",       "th-volt-warn"],
    ["voltage_critical",   "th-volt-crit"],
    ["temp_high_warn",     "th-temp-high-warn"],
    ["temp_high_critical", "th-temp-high-crit"],
    ["temp_low_warn",      "th-temp-low-warn"],
    ["no_comms_warn_hrs",  "th-nocomms-warn"],
    ["no_comms_crit_hrs",  "th-nocomms-crit"],
    ["health_check_enabled","th-health-enabled"]
  ];
  try {
    for (const [key, elId] of mappings) {
      const val = document.getElementById(elId)?.value;
      if (val !== undefined) {
        await supabasePatch(`program_settings?setting_key=eq.${key}`, {
          setting_value: String(val),
          updated_at: new Date().toISOString()
        });
      }
    }
    await loadThresholds();
    if (statusEl) { statusEl.textContent = "✅ Thresholds saved."; statusEl.style.color = "var(--green-dark)"; statusEl.style.display = "block"; }
    setTimeout(() => { if (statusEl) statusEl.style.display = "none"; }, 3000);
    // Refresh fleet health with new thresholds
    await loadFleetHealth();
  } catch(e) {
    if (statusEl) { statusEl.textContent = "❌ Error: " + e.message; statusEl.style.color = "var(--red)"; statusEl.style.display = "block"; }
  }
}

async function loadFleetHealth() {
  const statusEl = document.getElementById("fh-nightly-status");
  if (statusEl) statusEl.textContent = "Loading fleet health data...";

  try {
    // Build fleet health array from device_health table
    // At scale this would query device_health_daily aggregate instead
    const healthRows = [];
    // Only process relay devices — skip EV/battery/generator asset placeholders
    const relayUIDs = ["ev_", "batt_", "gen_", "pelican_"];
    for (const device of DEVICES.filter(d => !d.uid.includes("PLACEHOLDER") && !relayUIDs.some(p => d.uid.startsWith(p)))) {
      // Get best health record (prefer session.begin with signal data)
      let rows = await supabaseGet(
        `device_health?device_uid=eq.${encodeURIComponent(device.uid)}&rsrp=not.is.null&order=recorded_at.desc&limit=1`
      );
      if (!Array.isArray(rows) || rows.length === 0) {
        rows = await supabaseGet(
          `device_health?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`
        );
      }
      // Get last bubble-up for comms freshness
      const readings = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`
      );
      const lastReading = Array.isArray(readings) && readings.length > 0 ? readings[0] : null;
      const lastSeen = lastReading?.recorded_at || rows?.[0]?.recorded_at || null;
      healthRows.push({ device, health: rows?.[0] || null, lastSeen });
    }

    // Score each device
    fleetHealthData = healthRows.map(({ device, health, lastSeen }) => {
      const now = Date.now();
      const lastSeenMs = lastSeen ? new Date(lastSeen).getTime() : 0;
      const hoursAgo = lastSeenMs ? (now - lastSeenMs) / 3600000 : 9999;
      const voltage = health?.voltage != null ? parseFloat(health.voltage) : null;
      const temp    = health?.temperature != null ? parseFloat(health.temperature) : null;
      const movedTs = health?.moved ? parseInt(health.moved) : null;
      const lastHealthMs = health?.recorded_at ? new Date(health.recorded_at).getTime() : 0;
      // Flag as moved only if movement occurred within the last 2 hours (7200000ms)
      // Using 24h was too broad and flagged devices moved during installation/testing
      const movedRecently = movedTs && (movedTs * 1000) > (Date.now() - 7200000) && hoursAgo < fleetThresholds.noCommsWarn;

      // Use same ONLINE_THRESHOLD_MS (24h) as device badge logic elsewhere in dashboard
      const onlineThreshHrs = ONLINE_THRESHOLD_MS / 3600000;
      const isOnlineNow = lastSeenMs > 0 && (Date.now() - lastSeenMs) < ONLINE_THRESHOLD_MS;
      let commsStatus = hoursAgo > fleetThresholds.noCommsCrit ? "critical"
        : hoursAgo > fleetThresholds.noCommsWarn ? "warning"
        : !isOnlineNow ? "warning" : "ok";
      let voltStatus  = voltage == null ? "unknown"
        : voltage < fleetThresholds.voltCrit ? "critical"
        : voltage < fleetThresholds.voltWarn ? "warning" : "ok";
      let tempStatus  = temp == null ? "unknown"
        : (temp > fleetThresholds.tempHighCrit || temp < fleetThresholds.tempLowWarn) ? "critical"
        : temp > fleetThresholds.tempHighWarn ? "warning" : "ok";

      const overallStatus =
        commsStatus === "critical" || voltStatus === "critical" || tempStatus === "critical" ? "critical"
        : movedRecently ? "warning"
        : commsStatus === "warning" || voltStatus === "warning" || tempStatus === "warning" ? "warning"
        : !isOnlineNow ? "offline" : "ok";

      return {
        uid: device.uid, name: device.name,
        lastSeen, hoursAgo, voltage, temp,
        rsrp: health?.rsrp ?? null, bars: health?.bars ?? null,
        firmware: health?.firmware_version ?? null,
        location: health?.location ?? null,
        orientation: health?.orientation ?? null,
        movedRecently, movedTs,
        commsStatus, voltStatus, tempStatus, overallStatus
      };
    });

    updateFleetSummary();
    updateAlertCounts();
    // Re-render charts if panel is visible
    if (document.getElementById("fh-charts-panel")?.style.display !== "none") renderFleetCharts();
    if (statusEl) statusEl.textContent = `Last updated: ${new Date().toLocaleTimeString()}`;

  } catch(e) {
    console.error("loadFleetHealth error:", e);
    if (statusEl) statusEl.textContent = "Error loading fleet data.";
  }
}

function toggleFleetCharts() {
  const panel = document.getElementById("fh-charts-panel");
  const btn   = document.getElementById("fh-charts-btn");
  if (!panel) return;
  const showing = panel.style.display !== "none";
  panel.style.display = showing ? "none" : "grid";
  if (btn) btn.textContent = showing ? "📊 Show Charts" : "📊 Hide Charts";
  // Render charts when shown for first time
  if (!showing) renderFleetCharts();
}

function updateFleetSummary() {
  const total    = fleetHealthData.length;
  // Only count relay-type devices (not EV/battery/generator asset placeholders)
  const relayDevices = fleetHealthData.filter(d => !d.uid.startsWith("ev_") && !d.uid.startsWith("batt_") && !d.uid.startsWith("gen_"));
  const total2   = relayDevices.length;
  const online   = relayDevices.filter(d => d.overallStatus === "ok").length;
  const warning  = relayDevices.filter(d => d.overallStatus === "warning").length;
  const critical = relayDevices.filter(d => d.overallStatus === "critical").length;
  const offline  = relayDevices.filter(d => ["offline","critical"].includes(d.overallStatus)).length;
  const uptime   = total2 > 0 ? Math.round(((online + warning) / total2) * 100) : 0;

  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  set("fh-total",    total2);
  set("fh-online",   online);
  set("fh-warning",  warning);
  set("fh-critical", critical);
  set("fh-offline",  offline);
  set("fh-uptime",   uptime + "%");
}

function updateAlertCounts() {
  const noComms = fleetHealthData.filter(d => d.commsStatus !== "ok").length;
  const moved   = fleetHealthData.filter(d => d.movedRecently).length;
  const temp    = fleetHealthData.filter(d => d.tempStatus !== "ok" && d.tempStatus !== "unknown").length;
  const volt    = fleetHealthData.filter(d => d.voltStatus !== "ok" && d.voltStatus !== "unknown").length;

  const setCount = (id, val) => {
    const el = document.getElementById(id);
    if (el) { el.textContent = val; el.style.color = val > 0 ? "var(--red)" : "var(--text-hint)"; }
  };
  setCount("fh-nocomms-count", noComms);
  setCount("fh-moved-count",   moved);
  setCount("fh-temp-count",    temp);
  setCount("fh-volt-count",    volt);
}

function renderFleetCharts() {
  // Destroy existing charts
  Object.values(fleetCharts).forEach(c => { try { c.destroy(); } catch(e){} });
  fleetCharts = {};

  const isDark = document.documentElement.getAttribute("data-theme") === "dark";
  const textColor = isDark ? "#a0a0a0" : "#666";
  Chart.defaults.color = textColor;

  // 1. Comms Status Donut
  const commsCtx = document.getElementById("fh-chart-comms")?.getContext("2d");
  if (commsCtx) {
    const online   = fleetHealthData.filter(d => d.commsStatus === "ok").length;
    const warning  = fleetHealthData.filter(d => d.commsStatus === "warning").length;
    const critical = fleetHealthData.filter(d => d.commsStatus === "critical").length;
    fleetCharts.comms = new Chart(commsCtx, {
      type: "doughnut",
      data: {
        labels: ["Online", "Warning", "Critical/Offline"],
        datasets: [{ data: [online, warning, critical],
          backgroundColor: ["#16a34a","#f59e0b","#dc2626"],
          borderWidth: 0 }]
      },
      options: { plugins: { legend: { position: "bottom", labels: { font: { size: 11 } } } }, cutout: "65%" }
    });
  }

  // 2. Voltage Distribution Bar
  const voltCtx = document.getElementById("fh-chart-voltage")?.getContext("2d");
  if (voltCtx) {
    const buckets = [
      { label: ">3.6V (Good)",    min: 3.6,  max: 99,  color: "#16a34a" },
      { label: "3.3-3.6V (OK)",   min: 3.3,  max: 3.6, color: "#2563eb" },
      { label: "3.0-3.3V (Warn)", min: 3.0,  max: 3.3, color: "#f59e0b" },
      { label: "<3.0V (Critical)", min: -99,  max: 3.0, color: "#dc2626" },
      { label: "No Data",         min: null, max: null, color: "#999" }
    ];
    const counts = buckets.map(b =>
      b.min === null ? fleetHealthData.filter(d => d.voltage == null).length
      : fleetHealthData.filter(d => d.voltage != null && d.voltage >= b.min && d.voltage < b.max).length
    );
    fleetCharts.voltage = new Chart(voltCtx, {
      type: "bar",
      data: { labels: buckets.map(b => b.label),
        datasets: [{ label: "Devices", data: counts,
          backgroundColor: buckets.map(b => b.color), borderWidth: 0 }] },
      options: { plugins: { legend: { display: false } },
        scales: { y: { beginAtZero: true, ticks: { precision: 0 } } } }
    });
  }

  // 3. Signal Quality Donut
  const sigCtx = document.getElementById("fh-chart-signal")?.getContext("2d");
  if (sigCtx) {
    const excellent = fleetHealthData.filter(d => d.rsrp != null && d.rsrp >= -80).length;
    const good      = fleetHealthData.filter(d => d.rsrp != null && d.rsrp >= -90 && d.rsrp < -80).length;
    const fair      = fleetHealthData.filter(d => d.rsrp != null && d.rsrp >= -100 && d.rsrp < -90).length;
    const poor      = fleetHealthData.filter(d => d.rsrp != null && d.rsrp < -100).length;
    const noSig     = fleetHealthData.filter(d => d.rsrp == null).length;
    fleetCharts.signal = new Chart(sigCtx, {
      type: "doughnut",
      data: { labels: ["Excellent (≥-80)", "Good (-80 to -90)", "Fair (-90 to -100)", "Poor (<-100)", "No Data"],
        datasets: [{ data: [excellent, good, fair, poor, noSig],
          backgroundColor: ["#16a34a","#2563eb","#f59e0b","#dc2626","#999"],
          borderWidth: 0 }] },
      options: { plugins: { legend: { position: "bottom", labels: { font: { size: 10 } } } }, cutout: "65%" }
    });
  }

  // 4. Temperature Status Bar
  const tempCtx = document.getElementById("fh-chart-temp")?.getContext("2d");
  if (tempCtx) {
    const normal  = fleetHealthData.filter(d => d.tempStatus === "ok").length;
    const warn    = fleetHealthData.filter(d => d.tempStatus === "warning").length;
    const crit    = fleetHealthData.filter(d => d.tempStatus === "critical").length;
    const noTemp  = fleetHealthData.filter(d => d.tempStatus === "unknown").length;
    fleetCharts.temp = new Chart(tempCtx, {
      type: "bar",
      data: { labels: ["Normal", "Warning", "Critical", "No Data"],
        datasets: [{ label: "Devices", data: [normal, warn, crit, noTemp],
          backgroundColor: ["#16a34a","#f59e0b","#dc2626","#999"],
          borderWidth: 0 }] },
      options: { plugins: { legend: { display: false } },
        scales: { y: { beginAtZero: true, ticks: { precision: 0 } } } }
    });
  }
}

// ── Drill Down Side Panel ─────────────────────────────────────────────────────
function openDrillDown(type) {
  const titles = {
    nocomms: { title: "No Communications", sub: `Devices silent > ${fleetThresholds.noCommsWarn}h` },
    moved:   { title: "Moved / Tamper Alert", sub: "Devices that have moved recently" },
    temp:    { title: "Temperature Alert", sub: "Devices outside temperature threshold" },
    voltage: { title: "Voltage Alert", sub: "Devices below voltage threshold" }
  };
  const filters = {
    nocomms: d => d.commsStatus !== "ok",
    moved:   d => d.movedRecently,
    temp:    d => d.tempStatus !== "ok" && d.tempStatus !== "unknown",
    voltage: d => d.voltStatus !== "ok" && d.voltStatus !== "unknown"
  };

  drillDownType = type;
  drillDownData = fleetHealthData.filter(filters[type] || (() => true));
  drillDownPage = 0;

  const titleEl = document.getElementById("fh-drill-title");
  const subEl   = document.getElementById("fh-drill-subtitle");
  if (titleEl) titleEl.textContent = titles[type]?.title || "Device Details";
  if (subEl)   subEl.textContent   = `${drillDownData.length} devices — ${titles[type]?.sub || ""}`;

  // Clear search
  const searchEl = document.getElementById("fh-drill-search");
  if (searchEl) searchEl.value = "";

  renderDrillList();

  // Slide in panel
  const panel    = document.getElementById("fh-drill-panel");
  const backdrop = document.getElementById("fh-drill-backdrop");
  if (panel)    panel.style.right = "0px";
  if (backdrop) backdrop.style.display = "block";
}

function closeDrillDown() {
  const panel    = document.getElementById("fh-drill-panel");
  const backdrop = document.getElementById("fh-drill-backdrop");
  if (panel)    panel.style.right = "-480px";
  if (backdrop) backdrop.style.display = "none";
  drillDownType = null;
}

function drillPage(dir) {
  const search   = document.getElementById("fh-drill-search")?.value?.toLowerCase() || "";
  const filtered = drillDownData.filter(d =>
    !search || d.uid.toLowerCase().includes(search) || d.name.toLowerCase().includes(search)
  );
  const maxPage = Math.ceil(filtered.length / DRILL_PAGE_SIZE) - 1;
  drillDownPage = Math.max(0, Math.min(maxPage, drillDownPage + dir));
  renderDrillList();
}

function renderDrillList() {
  const list     = document.getElementById("fh-drill-list");
  const search   = document.getElementById("fh-drill-search")?.value?.toLowerCase() || "";
  const prevBtn  = document.getElementById("fh-drill-prev");
  const nextBtn  = document.getElementById("fh-drill-next");
  const pageLabel= document.getElementById("fh-drill-page-label");
  if (!list) return;

  const filtered = drillDownData.filter(d =>
    !search || d.uid.toLowerCase().includes(search) || d.name.toLowerCase().includes(search)
  );
  const totalPages = Math.ceil(filtered.length / DRILL_PAGE_SIZE) || 1;
  const page = drillDownData.slice(
    drillDownPage * DRILL_PAGE_SIZE,
    (drillDownPage + 1) * DRILL_PAGE_SIZE
  );

  if (pageLabel) pageLabel.textContent = `Page ${drillDownPage+1} of ${totalPages} (${filtered.length} devices)`;
  if (prevBtn)   prevBtn.disabled = drillDownPage === 0;
  if (nextBtn)   nextBtn.disabled = drillDownPage >= totalPages - 1;

  if (filtered.length === 0) {
    list.innerHTML = `<div class="sched-empty">No devices match.</div>`;
    return;
  }

  const statusColors = { ok:"var(--green-dark)", warning:"var(--amber)", critical:"var(--red)", offline:"var(--text-hint)" };

  list.innerHTML = filtered
    .slice(drillDownPage * DRILL_PAGE_SIZE, (drillDownPage + 1) * DRILL_PAGE_SIZE)
    .map(d => {
      const lastSeenStr = d.lastSeen ? new Date(d.lastSeen).toLocaleString() : "Never";
      const sc = statusColors[d.overallStatus] || "var(--text-secondary)";
      return `<div style="padding:10px 0;border-bottom:0.5px solid var(--border);cursor:pointer;" onclick="showDeviceDrillDetail('${d.uid}')">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;">
          <div>
            <div style="font-weight:600;font-size:13px;">${d.name}</div>
            <div style="font-size:10px;color:var(--text-hint);margin-top:1px;">${d.uid}</div>
          </div>
          <span style="color:${sc};font-size:11px;font-weight:600;">${d.overallStatus.toUpperCase()}</span>
        </div>
        <div style="display:flex;gap:12px;margin-top:6px;font-size:11px;color:var(--text-secondary);">
          <span>🕐 ${lastSeenStr}</span>
          ${d.voltage ? `<span>🔋 ${d.voltage.toFixed(3)}V</span>` : ""}
          ${d.temp ? `<span>🌡️ ${d.temp.toFixed(1)}°C</span>` : ""}
          ${d.rsrp ? `<span>📶 ${d.rsrp}dBm</span>` : ""}
          ${d.movedRecently ? `<span style="color:var(--amber);">🚨 Moved</span>` : ""}
        </div>
        ${d.location ? `<div style="font-size:10px;color:var(--text-hint);margin-top:2px;">📍 ${d.location}</div>` : ""}
        <div style="font-size:10px;color:var(--blue);margin-top:3px;">Click for details & health check →</div>
      </div>`;
    }).join("");
}

function showDeviceDrillDetail(uid) {
  const d = fleetHealthData.find(x => x.uid === uid);
  if (!d) return;
  const modal = document.getElementById("event-modal");
  const body  = document.getElementById("event-modal-body");
  if (!modal || !body) return;

  body.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:1rem;">
      <div><div style="font-size:10px;color:var(--text-hint);">Device</div><div style="font-weight:600;">${d.name}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">UID</div><div style="font-family:monospace;font-size:11px;">${d.uid}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Last Seen</div><div>${d.lastSeen ? new Date(d.lastSeen).toLocaleString() : "Never"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Hours Ago</div><div>${Math.round(d.hoursAgo)}h</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Voltage</div><div style="font-weight:600;color:${d.voltStatus==='critical'?'var(--red)':d.voltStatus==='warning'?'var(--amber)':'inherit'}">${d.voltage ? d.voltage.toFixed(3)+"V" : "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Temperature</div><div style="font-weight:600;color:${d.tempStatus==='critical'?'var(--red)':d.tempStatus==='warning'?'var(--amber)':'inherit'}">${d.temp ? d.temp.toFixed(1)+"°C" : "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">RSRP</div><div>${d.rsrp ? d.rsrp+"dBm" : "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Signal Bars</div><div>${d.bars ? "▮".repeat(d.bars)+"▯".repeat(5-d.bars) : "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Firmware</div><div>${d.firmware ? d.firmware.replace("notecard-u5-","v") : "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Orientation</div><div>${d.orientation || "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Location</div><div>${d.location || "—"}</div></div>
      <div><div style="font-size:10px;color:var(--text-hint);">Moved Recently</div><div>${d.movedRecently ? "🚨 Yes" : "✅ No"}</div></div>
    </div>
    <div style="display:flex;gap:8px;margin-top:12px;">
      <button onclick="requestHealthCheck('${uid}','${uid}');document.getElementById('event-modal').style.display='none';"
        style="padding:7px 16px;border-radius:var(--radius-sm);border:0.5px solid var(--green);background:transparent;color:var(--green-dark);font-size:12px;cursor:pointer;">
        🩺 Request Health Check
      </button>
    </div>`;

  modal.style.display = "flex";
}

function exportDrillCSV() {
  if (!drillDownData.length) return;
  const csv = ["Device Name,Device UID,Last Seen,Hours Ago,Voltage,Temp,RSRP,Bars,Firmware,Location,Moved,Overall Status",
    ...drillDownData.map(d =>
      `"${d.name}","${d.uid}","${d.lastSeen||''}","${Math.round(d.hoursAgo)}","${d.voltage||''}","${d.temp||''}","${d.rsrp||''}","${d.bars||''}","${d.firmware||''}","${d.location||''}","${d.movedRecently?'Yes':'No'}","${d.overallStatus}"`)
  ].join("\n");
  downloadCSV(csv, `Fleet_Alert_${drillDownType}_${new Date().toISOString().split("T")[0]}.csv`);
}

function exportFleetCSV() {
  if (!fleetHealthData.length) return;
  const csv = ["Device Name,Device UID,Last Seen,Hours Ago,Voltage,Temp,RSRP,Bars,Firmware,Location,Moved,Comms,Volt,Temp Status,Overall",
    ...fleetHealthData.map(d =>
      `"${d.name}","${d.uid}","${d.lastSeen||''}","${Math.round(d.hoursAgo)}","${d.voltage||''}","${d.temp||''}","${d.rsrp||''}","${d.bars||''}","${d.firmware||''}","${d.location||''}","${d.movedRecently?'Yes':'No'}","${d.commsStatus}","${d.voltStatus}","${d.tempStatus}","${d.overallStatus}"`)
  ].join("\n");
  downloadCSV(csv, `Fleet_Health_${new Date().toISOString().split("T")[0]}.csv`);
}

function downloadCSV(csv, filename) {
  const blob = new Blob([csv], { type: "text/csv" });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a); URL.revokeObjectURL(url);
}

async function generateFleetPDF() {
  alert("PDF generation will be built next. Use Export CSV for now.");
}

async function runHealthCheckNow() {
  const statusEl   = document.getElementById("fh-nightly-status");
  const progressEl = document.getElementById("fh-nightly-progress");
  const progressBar= document.getElementById("fh-progress-bar");
  const progressLbl= document.getElementById("fh-progress-label");

  const realDevices = DEVICES.filter(d => !d.uid.includes('PLACEHOLDER'));
  const total = realDevices.length;
  if (!total) { if (statusEl) statusEl.textContent = "No devices to check."; return; }

  if (progressEl) progressEl.style.display = "flex";
  if (statusEl)   statusEl.textContent = `Sending health check to ${total} device(s)...`;

  for (let i = 0; i < realDevices.length; i++) {
    const pct = Math.round(((i+1)/total)*100);
    if (progressBar) progressBar.style.width = pct + "%";
    if (progressLbl) progressLbl.textContent = `${i+1} / ${total} devices`;
    try {
      await fetch(`${PROXY_URL}env`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          deviceUID: realDevices[i].uid,
          environment_variables: { _restart: String(Math.floor(Date.now()/1000)) }
        })
      });
    } catch(e) { console.error("Health check error:", realDevices[i].uid, e); }
    await new Promise(r => setTimeout(r, 150));
  }

  if (statusEl) statusEl.textContent = `✅ Health check sent to ${total} device(s). Refreshing in 60s...`;
  setTimeout(() => { if (progressEl) progressEl.style.display = "none"; }, 3000);
  setTimeout(() => loadFleetHealth(), 60000);
}

function scheduleNightlyCheck() {
  if (nightlyCheckTimer) clearTimeout(nightlyCheckTimer);
  const enabled = document.getElementById("th-health-enabled")?.value !== "false";
  if (!enabled) return;
  const now = new Date();
  const midnight = new Date(now);
  midnight.setHours(0,0,0,0);
  if (now.getHours() >= 2) midnight.setDate(midnight.getDate() + 1);
  const msUntil = midnight.getTime() - now.getTime();
  nightlyCheckTimer = setTimeout(() => {
    runHealthCheckNow();
    setTimeout(scheduleNightlyCheck, 2*60*60*1000);
  }, msUntil);
  console.log(`Nightly health check scheduled in ${Math.round(msUntil/3600000)}h`);
}
// ── DEVICE MONITORING ────────────────────────────────────────────────────────
let activeSession      = null;
let monitoringTimer    = null;
let monitoringChart    = null;
let monitoringReadings = {};  // { device_uid: [readings] }
let sessionCountdown   = null;

async function initMonitoring() {
  // Populate device dropdown
  const devSel = document.getElementById("mon-target-device");
  if (devSel) {
    devSel.innerHTML = DEVICES.filter(d => !d.uid.includes('PLACEHOLDER'))
      .map(d => `<option value="${d.uid}">${d.name}</option>`).join("");
  }

  // Populate group dropdown
  const grpSel = document.getElementById("mon-target-group");
  if (grpSel) {
    const gNames = Object.entries(groupNames || {});
    grpSel.innerHTML = gNames.length
      ? gNames.map(([num, name]) => `<option value="group_${num}">${name}</option>`).join("")
      : `<option value="">No groups defined</option>`;
  }

  // Check for active session
  await checkActiveSession();
  await loadPastSessions();
}

function updateMonitorTargetUI() {
  const type = document.getElementById("mon-target-type")?.value;
  document.getElementById("mon-target-device-wrap").style.display = type === "device" ? "" : "none";
  document.getElementById("mon-target-list-wrap").style.display   = type === "list"   ? "" : "none";
  document.getElementById("mon-target-group-wrap").style.display  = type === "group"  ? "" : "none";
}

async function checkActiveSession() {
  try {
    const rows = await supabaseGet("monitoring_sessions?status=eq.active&order=started_at.desc&limit=1");
    if (Array.isArray(rows) && rows.length > 0) {
      activeSession = rows[0];
      showActiveSession();
    }
  } catch(e) { console.error("checkActiveSession:", e); }
}

async function startMonitoringSession() {
  const name     = document.getElementById("mon-name")?.value?.trim();
  const type     = document.getElementById("mon-target-type")?.value;
  const interval = parseInt(document.getElementById("mon-interval")?.value || "5");
  const duration = parseInt(document.getElementById("mon-duration")?.value || "120");
  const notes    = document.getElementById("mon-notes")?.value?.trim();
  const statusEl = document.getElementById("mon-form-status");

  if (!name) { if (statusEl) { statusEl.textContent = "Please enter a session name."; statusEl.style.color = "var(--red)"; } return; }

  // Get target UIDs
  let targetIds = [];
  if (type === "device") {
    const uid = document.getElementById("mon-target-device")?.value;
    if (uid) targetIds = [uid];
  } else if (type === "list") {
    const raw = document.getElementById("mon-target-list")?.value || "";
    targetIds = raw.split("\n").map(s => s.trim()).filter(s => s.startsWith("dev:"));
  } else if (type === "group") {
    const gVal = document.getElementById("mon-target-group")?.value;
    const gNum = parseInt(gVal?.replace("group_",""));
    targetIds = DEVICES.filter(d => (groupAssignments[d.uid]||[]).includes(gNum)).map(d => d.uid);
  }

  if (!targetIds.length) { if (statusEl) { statusEl.textContent = "No valid devices selected."; statusEl.style.color = "var(--red)"; } return; }

  if (statusEl) { statusEl.textContent = "Starting session..."; statusEl.style.color = "var(--text-secondary)"; }

  try {
    // Capture what the schedule SHOULD be right now for each device
    // Uses evaluateRules() so restore is accurate regardless of cached values
    const currentRule = evaluateRules(new Date());
    const scheduleIntervalMins = currentRule?.intervalMins || 240;
    const originalIntervals = {};
    targetIds.forEach(uid => { originalIntervals[uid] = scheduleIntervalMins; });
    console.log(`Monitoring: capturing schedule interval ${scheduleIntervalMins} min (${currentRule?.label || "no rule"}) for restore`);

    // Set bubble-up interval on all target devices
    for (const uid of targetIds) {
      const hex = buildAssignBubbleUpHex(interval);
      await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": uid },
        body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
      });
    }

    // Create session record in Supabase
    const session = {
      name, created_by: currentUser?.id,
      started_at: new Date().toISOString(),
      status: "active",
      target_type: type,
      target_ids: targetIds,
      bubble_interval: interval,
      duration_minutes: duration || null,
      notes: notes || null,
      original_intervals: originalIntervals
    };

    const res = await fetch(`${SUPABASE_URL}/rest/v1/monitoring_sessions`, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify(session)
    });

    if (!res.ok) { throw new Error(await res.text()); }
    const [saved] = await res.json();
    activeSession = saved;

    showActiveSession();
    if (statusEl) { statusEl.textContent = `✅ Session started — monitoring ${targetIds.length} device(s) at ${interval} min intervals.`; statusEl.style.color = "var(--green-dark)"; }

    // Start polling for new readings
    startMonitoringPoll();

  } catch(e) {
    console.error("startMonitoringSession:", e);
    if (statusEl) { statusEl.textContent = `Error: ${e.message}`; statusEl.style.color = "var(--red)"; }
  }
}

function showActiveSession() {
  if (!activeSession) return;

  const banner  = document.getElementById("mon-active-banner");
  const desc    = document.getElementById("mon-active-desc");
  const liveView= document.getElementById("mon-live-view");

  if (banner)   banner.style.display = "flex";
  if (liveView) liveView.style.display = "block";

  const deviceCount = activeSession.target_ids?.length || 0;
  const durStr = activeSession.duration_minutes
    ? `${activeSession.duration_minutes} min duration`
    : "Until manually stopped";

  if (desc) desc.textContent =
    `${activeSession.name} · ${deviceCount} device(s) · Every ${activeSession.bubble_interval} min · ${durStr}`;

  // Populate chart device selector
  const sel = document.getElementById("mon-chart-device");
  if (sel && activeSession.target_ids) {
    sel.innerHTML = activeSession.target_ids.map(uid => {
      const name = DEVICES.find(d => d.uid === uid)?.name || unitName(uid);
      return `<option value="${uid}">${name}</option>`;
    }).join("");
  }

  // Start countdown timer
  if (activeSession.duration_minutes && activeSession.started_at) {
    updateSessionCountdown();
    if (sessionCountdown) clearInterval(sessionCountdown);
    sessionCountdown = setInterval(updateSessionCountdown, 1000);
  }

  startMonitoringPoll();
}

function updateSessionCountdown() {
  if (!activeSession?.duration_minutes || !activeSession?.started_at) return;
  const timerEl = document.getElementById("mon-active-timer");
  const startMs = new Date(activeSession.started_at).getTime();
  const endMs   = startMs + (activeSession.duration_minutes * 60000);
  const remaining = endMs - Date.now();

  if (remaining <= 0) {
    console.log("Monitoring session duration elapsed — auto-stopping");
    stopMonitoringSession();
    return;
  }

  const h = Math.floor(remaining / 3600000);
  const m = Math.floor((remaining % 3600000) / 60000);
  const s = Math.floor((remaining % 60000) / 1000);
  if (timerEl) timerEl.textContent = `${h > 0 ? h+"h " : ""}${m}m ${s}s remaining`;
}

function startMonitoringPoll() {
  if (monitoringTimer) clearInterval(monitoringTimer);
  const interval = (activeSession?.bubble_interval || 5) * 60000;
  refreshMonitoringData();
  monitoringTimer = setInterval(refreshMonitoringData, interval);
}

async function refreshMonitoringData() {
  if (!activeSession) return;
  try {
    const rows = await supabaseGet(
      `monitoring_readings?session_id=eq.${activeSession.id}&order=recorded_at.desc&limit=500`
    );
    if (!Array.isArray(rows)) return;

    // Group by device
    monitoringReadings = {};
    rows.forEach(r => {
      if (!monitoringReadings[r.device_uid]) monitoringReadings[r.device_uid] = [];
      monitoringReadings[r.device_uid].push(r);
    });

    renderMonitoringChart();
    renderMonitoringTable();
  } catch(e) { console.error("refreshMonitoringData:", e); }
}

function renderMonitoringChart() {
  const uid = document.getElementById("mon-chart-device")?.value;
  const ctx = document.getElementById("mon-voltage-chart")?.getContext("2d");
  if (!ctx || !uid) return;

  const readings = (monitoringReadings[uid] || []).slice().reverse(); // oldest first
  const labels   = readings.map(r => new Date(r.recorded_at).toLocaleTimeString());
  const voltages = readings.map(r => r.voltage != null ? (r.voltage / 10).toFixed(1) : null);

  if (monitoringChart) { try { monitoringChart.destroy(); } catch(e){} }

  monitoringChart = new Chart(ctx, {
    type: "line",
    data: {
      labels,
      datasets: [{
        label: "Voltage (V)",
        data: voltages,
        borderColor: "#2563eb",
        backgroundColor: "rgba(37,99,235,0.1)",
        fill: true,
        tension: 0.3,
        pointRadius: 4,
        borderWidth: 2
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: {
        y: { title: { display: true, text: "Voltage (V)" }, beginAtZero: false },
        x: { ticks: { maxTicksLimit: 12, maxRotation: 45 } }
      }
    }
  });
}

function renderMonitoringTable() {
  const container = document.getElementById("mon-readings-table");
  if (!container) return;

  const uid = document.getElementById("mon-chart-device")?.value;
  const readings = (monitoringReadings[uid] || []).slice(0, 50);

  if (!readings.length) {
    container.innerHTML = `<div class="sched-empty">Waiting for first reading...</div>`;
    return;
  }

  const wrap  = document.createElement("div");
  wrap.style.overflowX = "auto";
  const table = document.createElement("table");
  table.style.cssText = "width:100%;border-collapse:collapse;font-size:11px;";

  const thead = table.createTHead();
  const hrow  = thead.insertRow();
  ["Time","R1","R2","R3","R4","Voltage","Current","Watts","SW","SQ"].forEach(h => {
    const th = document.createElement("th");
    th.textContent = h;
    th.style.cssText = "text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);white-space:nowrap;";
    hrow.appendChild(th);
  });

  const tbody = table.createTBody();
  readings.forEach(r => {
    const tr = tbody.insertRow();
    const relayDotStr = (v) => v ? "🟢" : "⚪";
    const cells = [
      new Date(r.recorded_at).toLocaleTimeString(),
      relayDotStr(r.relay_status_r1), relayDotStr(r.relay_status_r2),
      relayDotStr(r.relay_status_r3), relayDotStr(r.relay_status_r4),
      r.voltage ? (r.voltage/10).toFixed(1)+"V" : "—",
      r.current ? (r.current/10).toFixed(1)+"A" : "—",
      r.watts_consumed ? r.watts_consumed+"W" : "—",
      r.sw_value ?? "—", r.sq_value ?? "—"
    ];
    cells.forEach(val => {
      const td = tr.insertCell();
      td.textContent = val;
      td.style.cssText = "padding:6px 8px;border-bottom:0.5px solid var(--border);";
    });
  });

  wrap.appendChild(table);
  container.innerHTML = "";
  container.appendChild(wrap);
}

async function stopMonitoringSession() {
  if (!activeSession) return;
  if (!confirm(`Stop monitoring session "${activeSession.name}"? Original bubble-up intervals will be restored.`)) return;

  if (monitoringTimer)   clearInterval(monitoringTimer);
  if (sessionCountdown)  clearInterval(sessionCountdown);

  try {
    // Restore bubble-up interval using CURRENT schedule rule at time of stop
    // This ensures devices get the right interval for whatever time it is now
    const restoreRule = evaluateRules(new Date());
    const restoreMins = restoreRule?.intervalMins || 240;
    console.log(`Monitoring: restoring to schedule interval ${restoreMins} min (${restoreRule?.label || "no rule"})`);

    const targetIds = activeSession.target_ids || Object.keys(activeSession.original_intervals || {});
    for (const uid of targetIds) {
      const hex = buildAssignBubbleUpHex(restoreMins);
      await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": uid },
        body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
      });
      console.log(`Restored ${uid} to ${restoreMins} min`);
    }

    // Mark session as stopped
    await fetch(`${SUPABASE_URL}/rest/v1/monitoring_sessions?id=eq.${activeSession.id}`, {
      method: "PATCH",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token}`,
        "Content-Type": "application/json",
        "Prefer": "return=minimal"
      },
      body: JSON.stringify({ status: "stopped", ended_at: new Date().toISOString() })
    });

    activeSession = null;
    document.getElementById("mon-active-banner").style.display = "none";
    document.getElementById("mon-live-view").style.display = "none";
    await loadPastSessions();
    showBubbleStatus("✅ Monitoring session stopped. Original intervals restored.", "ok");

  } catch(e) { console.error("stopMonitoringSession:", e); }
}

async function loadPastSessions() {
  const container = document.getElementById("mon-past-sessions");
  if (!container) return;
  try {
    const rows = await supabaseGet(
      "monitoring_sessions?status=in.(completed,stopped)&order=started_at.desc&limit=20"
    );
    if (!Array.isArray(rows) || rows.length === 0) {
      container.innerHTML = `<div class="sched-empty">No past sessions yet.</div>`;
      return;
    }
    container.innerHTML = rows.map(s => {
      const startStr = s.started_at ? new Date(s.started_at).toLocaleString() : "—";
      const endStr   = s.ended_at   ? new Date(s.ended_at).toLocaleString()   : "—";
      const dur      = s.started_at && s.ended_at
        ? Math.round((new Date(s.ended_at) - new Date(s.started_at)) / 60000) + " min"
        : "—";
      return `<div class="sched-item">
        <div class="sched-info">
          <div class="sched-name">${s.name} <span style="font-size:10px;color:var(--text-hint);">${s.status}</span></div>
          <div class="sched-detail">${s.target_ids?.length || 0} device(s) · Every ${s.bubble_interval} min · ${dur} · ${startStr}</div>
          ${s.notes ? `<div class="sched-detail" style="color:var(--text-hint);">${s.notes}</div>` : ""}
        </div>
        <div class="sched-actions">
          <button class="sched-delete-btn" onclick="viewPastSession(${s.id})">View</button>
          <button class="sched-delete-btn" style="color:var(--green-dark);" onclick="exportSessionCSV(${s.id},'${s.name.replace(/'/g,"\\'")}')">CSV</button>
        </div>
      </div>`;
    }).join("");
  } catch(e) { console.error("loadPastSessions:", e); }
}

async function viewPastSession(sessionId) {
  // Load session and show live view with historical data
  const rows = await supabaseGet(`monitoring_sessions?id=eq.${sessionId}&limit=1`);
  if (!Array.isArray(rows) || !rows.length) return;
  activeSession = rows[0];
  await refreshMonitoringData();
  document.getElementById("mon-live-view").style.display = "block";
  document.getElementById("mon-active-banner").style.display = "none";
  // Scroll to live view
  document.getElementById("mon-live-view").scrollIntoView({ behavior: "smooth" });
}

async function exportSessionCSV(sessionId, sessionName) {
  const rows = await supabaseGet(
    `monitoring_readings?session_id=eq.${sessionId}&order=recorded_at.asc&limit=10000`
  );
  if (!Array.isArray(rows) || !rows.length) { alert("No readings found for this session."); return; }
  const csv = ["Time,Device UID,R1,R2,R3,R4,Voltage,Current,Power Factor,Watts,SW,SQ,Override Timer",
    ...rows.map(r =>
      `"${new Date(r.recorded_at).toLocaleString()}","${r.device_uid}","${r.relay_status_r1||0}","${r.relay_status_r2||0}","${r.relay_status_r3||0}","${r.relay_status_r4||0}","${r.voltage?r.voltage/10:''}","${r.current?r.current/10:''}","${r.power_factor||''}","${r.watts_consumed||''}","${r.sw_value||''}","${r.sq_value||''}","${r.override_timer||''}"`)
  ].join("\n");
  downloadCSV(csv, `Monitoring_${sessionName.replace(/[^a-z0-9]/gi,'_')}_${sessionId}.csv`);
}

async function exportMonitoringCSV() {
  if (activeSession) await exportSessionCSV(activeSession.id, activeSession.name);
}

// ── ENERGY MONITOR ───────────────────────────────────────────────────────────
let energyChart       = null;
let energyChartData   = [];
let activeEnergyMonitors = [];
let energyPollTimers  = {}; // { monitorId: intervalId }

async function initEnergyMonitor() {
  // Populate device dropdowns
  const devSel = document.getElementById("em-target-device");
  if (devSel) {
    devSel.innerHTML = DEVICES.filter(d => !d.uid.includes('PLACEHOLDER'))
      .map(d => `<option value="${d.uid}">${d.name}</option>`).join("");
  }
  const grpSel = document.getElementById("em-target-group");
  if (grpSel) {
    const gNames = Object.entries(groupNames || {});
    grpSel.innerHTML = gNames.length
      ? gNames.map(([num, name]) => `<option value="group_${num}">${name}</option>`).join("")
      : `<option value="">No groups defined</option>`;
  }
  await loadEnergyMonitors();
}

function updateEnergyTargetUI() {
  const type = document.getElementById("em-target-type")?.value;
  document.getElementById("em-target-device-wrap").style.display = type === "device" ? "" : "none";
  document.getElementById("em-target-list-wrap").style.display   = type === "list"   ? "" : "none";
  document.getElementById("em-target-group-wrap").style.display  = type === "group"  ? "" : "none";
}

async function startEnergyMonitor() {
  const name    = document.getElementById("em-name")?.value?.trim();
  const type    = document.getElementById("em-target-type")?.value;
  const notes   = document.getElementById("em-notes")?.value?.trim();
  const statusEl= document.getElementById("em-form-status");

  if (!name) {
    if (statusEl) { statusEl.textContent = "Please enter a monitor name."; statusEl.style.color = "var(--red)"; statusEl.style.display = "block"; }
    return;
  }

  // Get target UIDs
  let targetIds = [];
  if (type === "device") {
    const uid = document.getElementById("em-target-device")?.value;
    if (uid) targetIds = [uid];
  } else if (type === "list") {
    const raw = document.getElementById("em-target-list")?.value || "";
    targetIds = raw.split("\n").map(s => s.trim()).filter(s => s.startsWith("dev:"));
  } else if (type === "group") {
    const gVal = document.getElementById("em-target-group")?.value;
    const gNum = parseInt(gVal?.replace("group_",""));
    targetIds = DEVICES.filter(d => (groupAssignments[d.uid]||[]).includes(gNum)).map(d => d.uid);
  }

  if (!targetIds.length) {
    if (statusEl) { statusEl.textContent = "No valid devices selected."; statusEl.style.color = "var(--red)"; statusEl.style.display = "block"; }
    return;
  }

  if (statusEl) { statusEl.textContent = "Starting energy monitor..."; statusEl.style.color = "var(--text-secondary)"; statusEl.style.display = "block"; }

  try {
    // Set 5-minute bubble-up on all target devices
    for (const uid of targetIds) {
      const hex = buildAssignBubbleUpHex(5);
      await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": uid },
        body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
      });
    }

    // Get schedule fields
    const startDate  = document.getElementById("em-start-date")?.value || null;
    const stopDate   = document.getElementById("em-stop-date")?.value  || null;
    const startHour  = parseInt(document.getElementById("em-start-hour")?.value || "0");
    const stopHour   = parseInt(document.getElementById("em-stop-hour")?.value  || "23");
    const dowChecked = [...document.querySelectorAll(".em-dow:checked")].map(cb => parseInt(cb.value));
    const daysOfWeek = dowChecked.length ? dowChecked : [0,1,2,3,4,5,6];

    // Validate schedule
    if (startDate && stopDate && startDate > stopDate) {
      if (statusEl) { statusEl.textContent = "Stop date must be after start date."; statusEl.style.color = "var(--red)"; statusEl.style.display = "block"; }
      return;
    }

    // Check if we're currently in the monitoring window
    const now = new Date();
    const inWindow = isInEnergyWindow({ start_date: startDate, stop_date: stopDate, start_hour: startHour, stop_hour: stopHour, days_of_week: daysOfWeek }, now);

    // Only set 5-min bubble-up if we're currently in the window
    if (inWindow) {
      for (const uid of targetIds) {
        const hex = buildAssignBubbleUpHex(5);
        await fetch(PROXY_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Device-UID": uid },
          body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
        });
      }
    }

    // Create monitor record
    const res = await fetch(`${SUPABASE_URL}/rest/v1/energy_monitors`, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify({
        name, created_by: currentUser?.id,
        status: "active", target_type: type,
        target_ids: targetIds, notes: notes || null,
        start_date: startDate, stop_date: stopDate,
        start_hour: startHour, stop_hour: stopHour,
        days_of_week: daysOfWeek
      })
    });

    if (!res.ok) throw new Error(await res.text());
    const [saved] = await res.json();

    // Start polling every 5 minutes to collect readings
    startEnergyPoll(saved);

    if (statusEl) { statusEl.textContent = `✅ Energy monitor started — collecting data every 5 min from ${targetIds.length} device(s).`; statusEl.style.color = "var(--green-dark)"; }

    // Clear form
    document.getElementById("em-name").value = "";
    document.getElementById("em-notes").value = "";

    await loadEnergyMonitors();

  } catch(e) {
    console.error("startEnergyMonitor:", e);
    if (statusEl) { statusEl.textContent = `Error: ${e.message}`; statusEl.style.color = "var(--red)"; }
  }
}

function isInEnergyWindow(monitor, now = new Date()) {
  const { start_date, stop_date, start_hour, stop_hour, days_of_week } = monitor;
  const dateStr = now.toISOString().split("T")[0];
  const hour    = now.getHours();
  const dow     = now.getDay();

  if (start_date && dateStr < start_date) return false;
  if (stop_date  && dateStr > stop_date)  return false;
  if (Array.isArray(days_of_week) && days_of_week.length && !days_of_week.includes(dow)) return false;
  if (start_hour != null && stop_hour != null) {
    if (start_hour <= stop_hour) {
      if (hour < start_hour || hour > stop_hour) return false;
    } else {
      // Overnight window (e.g. 22:00 to 06:00)
      if (hour < start_hour && hour > stop_hour) return false;
    }
  }
  return true;
}

function startEnergyPoll(monitor) {
  if (energyPollTimers[monitor.id]) clearInterval(energyPollTimers[monitor.id]);

  // Check window and collect/adjust bubble-up every 5 minutes
  const tick = async () => {
    const now = new Date();
    const inWindow = isInEnergyWindow(monitor, now);

    // Auto-stop if past stop_date
    if (monitor.stop_date && now.toISOString().split("T")[0] > monitor.stop_date) {
      console.log(`Energy monitor ${monitor.id} reached stop date — auto-stopping`);
      await stopEnergyMonitor(monitor.id, monitor.name);
      return;
    }

    if (inWindow) {
      // Ensure 5-min bubble-up is set
      for (const uid of (monitor.target_ids || [])) {
        const hex = buildAssignBubbleUpHex(5);
        await fetch(PROXY_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Device-UID": uid },
          body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
        });
      }
      collectEnergyReadings(monitor);
    } else {
      // Outside window — restore schedule interval
      const restoreRule = evaluateRules(now);
      const restoreMins = restoreRule?.intervalMins || 240;
      for (const uid of (monitor.target_ids || [])) {
        const hex = buildAssignBubbleUpHex(restoreMins);
        await fetch(PROXY_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-Device-UID": uid },
          body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
        });
      }
    }
  };

  tick(); // Run immediately
  energyPollTimers[monitor.id] = setInterval(tick, 5 * 60 * 1000);
}

async function collectEnergyReadings(monitor) {
  if (!monitor?.target_ids?.length) return;
  for (const uid of monitor.target_ids) {
    try {
      // Get latest device_readings for this device
      const rows = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(uid)}&order=recorded_at.desc&limit=1`
      );
      if (!Array.isArray(rows) || !rows.length) continue;
      const r = rows[0];

      // Get current outside temp from weather data if available
      const outsideTemp = wxForecastData?.current_weather?.temperature ?? null;

      // Write to energy_readings
      await fetch(`${SUPABASE_URL}/rest/v1/energy_readings`, {
        method: "POST",
        headers: {
          "apikey": SUPABASE_KEY,
          "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
          "Content-Type": "application/json",
          "Prefer": "return=minimal"
        },
        body: JSON.stringify({
          monitor_id:      monitor.id,
          recorded_at:     new Date().toISOString(),
          device_uid:      uid,
          relay_status_r1: r.relay_status_r1,
          relay_status_r2: r.relay_status_r2,
          relay_status_r3: r.relay_status_r3,
          relay_status_r4: r.relay_status_r4,
          voltage:         r.voltage != null ? r.voltage / 10 : null,
          current:         r.current != null ? r.current / 10 : null,
          power_factor:    r.power_factor != null ? r.power_factor / 1000 : null,
          watts_consumed:  r.watts_consumed,
          sw_value:        r.sw_value,
          sq_value:        r.sq_value,
          outside_temp:    outsideTemp
        })
      });
    } catch(e) { console.error("collectEnergyReadings error:", uid, e); }
  }
}

async function loadEnergyMonitors() {
  const container = document.getElementById("em-monitors-list");
  const banner    = document.getElementById("em-active-banner");
  const countEl   = document.getElementById("em-active-count");
  if (!container) return;

  try {
    const rows = await supabaseGet("energy_monitors?order=created_at.desc&limit=50");
    if (!Array.isArray(rows) || !rows.length) {
      container.innerHTML = `<div class="sched-empty">No energy monitors yet.</div>`;
      return;
    }

    activeEnergyMonitors = rows.filter(r => r.status === "active");
    const activeCount = activeEnergyMonitors.length;

    if (banner) banner.style.display = activeCount > 0 ? "block" : "none";
    if (countEl) countEl.textContent = activeCount;

    // Resume polling for active monitors
    activeEnergyMonitors.forEach(m => {
      if (!energyPollTimers[m.id]) startEnergyPoll(m);
    });

    // Populate chart monitor selector
    const monSel = document.getElementById("em-chart-monitor");
    if (monSel) {
      monSel.innerHTML = rows.map(r =>
        `<option value="${r.id}">${r.name} (${r.status})</option>`
      ).join("");
      // Populate device selector for first monitor
      updateEnergyDeviceSelector(rows[0]);
    }

    // Show chart card
    const chartCard = document.getElementById("em-chart-card");
    if (chartCard) chartCard.style.display = "block";

    container.innerHTML = rows.map(m => {
      const startStr = m.created_at ? new Date(m.created_at).toLocaleString() : "—";
      const devCount = m.target_ids?.length || 0;
      const isActive = m.status === "active";
      return `<div class="sched-item">
        <div class="sched-info">
          <div class="sched-name">
            ${m.name}
            <span style="font-size:10px;font-weight:600;margin-left:6px;color:${isActive?"var(--green-dark)":"var(--text-hint)"};">
              ${isActive ? "🟢 Active" : m.status}
            </span>
          </div>
          <div class="sched-detail">${devCount} device(s) · 5 min interval · Started ${startStr}</div>
          <div class="sched-detail" style="color:var(--text-hint);">
            ${m.start_date || 'No start'} → ${m.stop_date || 'No end'} · 
            Hours: ${m.start_hour ?? 0}:00–${m.stop_hour ?? 23}:59 · 
            Days: ${(m.days_of_week||[0,1,2,3,4,5,6]).map(d=>['Su','Mo','Tu','We','Th','Fr','Sa'][d]).join(', ')}
          </div>
          ${m.notes ? `<div class="sched-detail" style="color:var(--text-hint);">${m.notes}</div>` : ""}
        </div>
        <div class="sched-actions">
          <button class="sched-delete-btn" onclick="viewEnergyMonitor(${m.id})">View</button>
          <button class="sched-delete-btn" style="color:var(--green-dark);" onclick="exportEnergyMonitorCSV(${m.id},'${m.name.replace(/'/g,"\\'")}')">CSV</button>
          ${isActive ? `<button class="sched-delete-btn" style="color:var(--red);" onclick="stopEnergyMonitor(${m.id},'${m.name.replace(/'/g,"\\'")}')">Stop</button>` : ""}
        </div>
      </div>`;
    }).join("");

  } catch(e) {
    console.error("loadEnergyMonitors:", e);
    container.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error loading monitors.</div>`;
  }
}

function updateEnergyDeviceSelector(monitor) {
  const sel = document.getElementById("em-chart-device");
  if (!sel || !monitor?.target_ids) return;
  sel.innerHTML = monitor.target_ids.map(uid => {
    const name = DEVICES.find(d => d.uid === uid)?.name || unitName(uid);
    return `<option value="${uid}">${name}</option>`;
  }).join("");
}

async function viewEnergyMonitor(monitorId) {
  const sel = document.getElementById("em-chart-monitor");
  if (sel) sel.value = monitorId;
  const monitor = activeEnergyMonitors.find(m => m.id === monitorId)
    || (await supabaseGet(`energy_monitors?id=eq.${monitorId}&limit=1`))?.[0];
  if (monitor) updateEnergyDeviceSelector(monitor);
  await loadEnergyChartData();
  document.getElementById("em-chart-card")?.scrollIntoView({ behavior: "smooth" });
}

async function loadEnergyChartData() {
  const monitorId = document.getElementById("em-chart-monitor")?.value;
  const deviceUid = document.getElementById("em-chart-device")?.value;
  const windowHrs = parseInt(document.getElementById("em-chart-window")?.value || "168");
  if (!monitorId || !deviceUid) return;

  const since = new Date(Date.now() - windowHrs * 3600000).toISOString();
  const rows = await supabaseGet(
    `energy_readings?monitor_id=eq.${monitorId}&device_uid=eq.${encodeURIComponent(deviceUid)}&recorded_at=gte.${since}&order=recorded_at.asc&limit=2000`
  );

  if (!Array.isArray(rows) || !rows.length) {
    if (energyChart) { try { energyChart.destroy(); } catch(e){} }
    return;
  }

  energyChartData = rows;

  // Summary stats
  const watts   = rows.map(r => r.watts_consumed).filter(v => v != null);
  const current = rows.map(r => r.current).filter(v => v != null);
  const avgW    = watts.length ? Math.round(watts.reduce((a,b)=>a+b,0)/watts.length) : null;
  const maxW    = watts.length ? Math.max(...watts) : null;
  const avgA    = current.length ? (current.reduce((a,b)=>a+b,0)/current.length/10).toFixed(1) : null;

  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val ?? "—"; };
  set("em-avg-watts",      avgW ? avgW+"W" : "—");
  set("em-max-watts",      maxW ? maxW+"W" : "—");
  set("em-avg-current",    avgA ? avgA+"A" : "—");
  set("em-readings-count", rows.length);

  renderEnergyChart(rows);
}

function renderEnergyChart(rows) {
  const ctx = document.getElementById("em-energy-chart")?.getContext("2d");
  if (!ctx) return;
  if (energyChart) { try { energyChart.destroy(); } catch(e){} }

  // Downsample for readability if too many points
  const maxPoints = 500;
  const step = Math.max(1, Math.floor(rows.length / maxPoints));
  const sampled = rows.filter((_, i) => i % step === 0);

  const labels  = sampled.map(r => {
    const d = new Date(r.recorded_at);
    return d.toLocaleDateString("en-US", { month:"short", day:"numeric" }) + " " +
           d.toLocaleTimeString("en-US", { hour:"numeric", minute:"2-digit", hour12:true });
  });
  const watts   = sampled.map(r => r.watts_consumed ?? null);
  const amps    = sampled.map(r => r.current != null ? (r.current/10).toFixed(2) : null);
  const temps   = sampled.map(r => r.outside_temp ?? null);
  const hasTemp = temps.some(t => t != null);

  const datasets = [
    {
      label: "Watts",
      data: watts,
      borderColor: "#2563eb",
      backgroundColor: "rgba(37,99,235,0.08)",
      fill: true,
      tension: 0.3,
      pointRadius: sampled.length > 100 ? 0 : 3,
      borderWidth: 2,
      yAxisID: "y"
    },
    {
      label: "Current (A)",
      data: amps,
      borderColor: "#7c3aed",
      backgroundColor: "transparent",
      fill: false,
      tension: 0.3,
      pointRadius: sampled.length > 100 ? 0 : 3,
      borderWidth: 2,
      borderDash: [4,4],
      yAxisID: "y"
    }
  ];

  const scales = {
    x: {
      ticks: { maxTicksLimit: 12, maxRotation: 45, font: { size: 10 } },
      grid: { color: "rgba(128,128,128,0.1)" }
    },
    y: {
      type: "linear", position: "left",
      title: { display: true, text: "Watts / Amps×10" },
      beginAtZero: true,
      grid: { color: "rgba(128,128,128,0.1)" }
    }
  };

  if (hasTemp) {
    datasets.push({
      label: "Outside Temp (°F)",
      data: temps,
      borderColor: "#f59e0b",
      backgroundColor: "transparent",
      fill: false,
      tension: 0.3,
      pointRadius: 0,
      borderWidth: 2,
      borderDash: [8,4],
      yAxisID: "y2"
    });
    scales.y2 = {
      type: "linear", position: "right",
      title: { display: true, text: "Temp (°F)" },
      grid: { drawOnChartArea: false }
    };
  }

  energyChart = new Chart(ctx, {
    type: "line",
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      plugins: {
        legend: { position: "top", labels: { font: { size: 11 } } },
        tooltip: {
          callbacks: {
            title: (items) => items[0]?.label || "",
            label: (item) => `${item.dataset.label}: ${item.raw ?? "—"}`
          }
        }
      },
      scales
    }
  });
}

async function stopEnergyMonitor(monitorId, monitorName) {
  if (!confirm(`Stop energy monitor "${monitorName}"?\n\nNote: Bubble-up interval will be restored to current schedule.`)) return;

  // Clear poll timer
  if (energyPollTimers[monitorId]) {
    clearInterval(energyPollTimers[monitorId]);
    delete energyPollTimers[monitorId];
  }

  // Restore bubble-up interval using current schedule rule
  const monitor = await supabaseGet(`energy_monitors?id=eq.${monitorId}&limit=1`);
  if (Array.isArray(monitor) && monitor[0]?.target_ids) {
    const restoreRule = evaluateRules(new Date());
    const restoreMins = restoreRule?.intervalMins || 240;
    for (const uid of monitor[0].target_ids) {
      const hex = buildAssignBubbleUpHex(restoreMins);
      await fetch(PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Device-UID": uid },
        body: JSON.stringify({ body: { LC: hex }, req: "note.add", sync: true })
      });
    }
  }

  // Update status
  await fetch(`${SUPABASE_URL}/rest/v1/energy_monitors?id=eq.${monitorId}`, {
    method: "PATCH",
    headers: {
      "apikey": SUPABASE_KEY,
      "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
      "Content-Type": "application/json",
      "Prefer": "return=minimal"
    },
    body: JSON.stringify({ status: "stopped" })
  });

  await loadEnergyMonitors();
  showBubbleStatus(`✅ Energy monitor stopped. Bubble-up interval restored.`, "ok");
}

async function exportEnergyMonitorCSV(monitorId, monitorName) {
  const rows = await supabaseGet(
    `energy_readings?monitor_id=eq.${monitorId}&order=recorded_at.asc&limit=50000`
  );
  if (!Array.isArray(rows) || !rows.length) { alert("No readings found."); return; }
  const csv = ["Time,Device UID,R1,R2,R3,R4,Watts,Current(A),Power Factor,Voltage,SW,SQ,Outside Temp",
    ...rows.map(r =>
      `"${new Date(r.recorded_at).toLocaleString()}","${r.device_uid}","${r.relay_status_r1||0}","${r.relay_status_r2||0}","${r.relay_status_r3||0}","${r.relay_status_r4||0}","${r.watts_consumed||''}","${r.current?r.current/10:''}","${r.power_factor||''}","${r.voltage?r.voltage/10:''}","${r.sw_value||''}","${r.sq_value||''}","${r.outside_temp||''}"`)
  ].join("\n");
  downloadCSV(csv, `Energy_Monitor_${monitorName.replace(/[^a-z0-9]/gi,'_')}.csv`);
}

async function exportEnergyCSV() {
  const monitorId = document.getElementById("em-chart-monitor")?.value;
  const name = document.getElementById("em-chart-monitor")?.selectedOptions[0]?.text || "export";
  if (monitorId) await exportEnergyMonitorCSV(monitorId, name);
}

// ── OPENADR VEN ───────────────────────────────────────────────────────────────
let oadrVTNConfig  = null;
let oadrMappings   = [
  { level: 1.0,  desc: "Emergency Shed",  strategy: 19, mode: "dlc", pct: 100 },
  { level: 0.75, desc: "High Shed",       strategy: 15, mode: "dlc", pct: 75  },
  { level: 0.5,  desc: "Medium Shed",     strategy: 9,  mode: "di",  pct: 50  },
  { level: 0.25, desc: "Low Shed",        strategy: 5,  mode: "di",  pct: 25  },
  { level: 0.0,  desc: "Restore All",     strategy: 61, mode: "dlc", pct: 0   },
];
let oadrReportTimer = null;

// ── DR Device Configuration ───────────────────────────────────────────────────
// In-memory store: { [device_uid]: { ven_resource, default_mode, relays: { [1-4]: { mode_override, shed_level, is_designated, enabled } } } }
let drDeviceConfig = {};

const DR_SHED_LEVELS = ["emergency", "high", "medium", "low"];
const DR_SHED_LABELS = { emergency: "Emergency", high: "High", medium: "Medium", low: "Low" };
const DR_MODES = { bas_di: "BAS Mode", direct_load: "Direct Load" };

async function loadDRConfig() {
  const list = document.getElementById("dr-device-config-list");
  if (!list) return;

  // Load device-level config
  let devRows = [];
  let relayRows = [];
  try {
    devRows   = await supabaseGet("device_dr_config?order=device_uid.asc") || [];
    relayRows = await supabaseGet("device_relay_dr_config?order=device_uid.asc,relay_number.asc") || [];
  } catch(e) { console.warn("DR config tables may not exist yet — using defaults.", e); }

  // Build in-memory config, defaulting any missing entries
  const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
  drDeviceConfig = {};

  for (const dev of realDevices) {
    const saved = devRows.find(r => r.device_uid === dev.uid) || {};
    const relays = {};
    for (let r = 1; r <= 4; r++) {
      const savedRelay = relayRows.find(x => x.device_uid === dev.uid && x.relay_number === r) || {};
      relays[r] = {
        mode_override:  savedRelay.mode_override  ?? null,
        shed_level:     savedRelay.shed_level      ?? null,
        is_designated:  savedRelay.is_designated   ?? (r === 1),
        enabled:        savedRelay.enabled         ?? true
      };
    }
    drDeviceConfig[dev.uid] = {
      ven_resource:  saved.ven_resource  ?? false,
      default_mode:  saved.default_mode  ?? "direct_load",
      relays
    };
  }
  renderDRConfig();
}

function renderDRConfig() {
  const list = document.getElementById("dr-device-config-list");
  if (!list) return;
  const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
  if (!realDevices.length) { list.innerHTML = '<div class="sched-empty">No devices configured.</div>'; return; }

  list.innerHTML = realDevices.map(dev => {
    const cfg = drDeviceConfig[dev.uid] || {};
    const effMode = cfg.default_mode || "direct_load";
    const isBAS   = effMode === "bas_di";
    const isVEN   = cfg.ven_resource || false;

    const relayRows = [1,2,3,4].map(r => {
      const rc = cfg.relays?.[r] || {};
      const effectiveMode = rc.mode_override ?? effMode;
      const isBASRelay    = effectiveMode === "bas_di";

      const modeOverrideOptions = [
        `<option value="" ${!rc.mode_override ? "selected" : ""}>Inherit (${DR_MODES[effMode]})</option>`,
        `<option value="bas_di" ${rc.mode_override === "bas_di" ? "selected" : ""}>BAS/DI</option>`,
        `<option value="direct_load" ${rc.mode_override === "direct_load" ? "selected" : ""}>Direct Load</option>`
      ].join("");

      const shedOptions = DR_SHED_LEVELS.map(sl =>
        `<option value="${sl}" ${rc.shed_level === sl ? "selected" : ""}>${DR_SHED_LABELS[sl]}</option>`
      ).join("");

      const shedCell = isBASRelay
        ? `<select onchange="drUpdateRelay('${dev.uid}',${r},'shed_level',this.value)"
              style="padding:3px 6px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
              <option value="">— None —</option>${shedOptions}
           </select>`
        : `<span style="font-size:11px;color:var(--text-hint);">N/A</span>`;

      const designatedCell = !isBASRelay
        ? `<label style="display:flex;align-items:center;gap:4px;cursor:pointer;font-size:11px;">
              <input type="checkbox" ${rc.is_designated ? "checked" : ""}
                onchange="drUpdateRelay('${dev.uid}',${r},'is_designated',this.checked)" />
              Designated
           </label>`
        : `<span style="font-size:11px;color:var(--text-hint);">N/A</span>`;

      return `<tr style="background:${rc.enabled ? "transparent" : "rgba(0,0,0,0.03)"};">
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:12px;font-weight:500;">R${r}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">
          <select onchange="drUpdateRelay('${dev.uid}',${r},'mode_override',this.value||null)"
            style="padding:3px 6px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
            ${modeOverrideOptions}
          </select>
        </td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">${shedCell}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">${designatedCell}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">
          <label style="display:flex;align-items:center;gap:4px;cursor:pointer;font-size:11px;">
            <input type="checkbox" ${rc.enabled ? "checked" : ""}
              onchange="drUpdateRelay('${dev.uid}',${r},'enabled',this.checked)" />
            Enabled
          </label>
        </td>
      </tr>`;
    }).join("");

    return `<div style="border:0.5px solid var(--border-md);border-radius:var(--radius-sm);margin-bottom:10px;overflow:hidden;">
      <!-- Device header row -->
      <div style="display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--surface2);flex-wrap:wrap;">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;font-weight:600;color:var(--text-primary);">${dev.name}</div>
          <div style="font-size:10px;color:var(--text-hint);font-family:monospace;margin-top:1px;">${dev.uid}</div>
        </div>
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
          <input type="checkbox" ${isVEN ? "checked" : ""}
            onchange="drUpdateDevice('${dev.uid}','ven_resource',this.checked)" />
          <span style="font-size:11px;font-weight:600;color:${isVEN ? "var(--green-dark)" : "var(--text-secondary)"};">VEN Resource</span>
        </label>
        <div style="display:flex;align-items:center;gap:6px;">
          <span style="font-size:11px;color:var(--text-hint);">Default Mode:</span>
          <select onchange="drUpdateDevice('${dev.uid}','default_mode',this.value);renderDRConfig();"
            style="padding:4px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface);font-size:11px;font-weight:600;">
            <option value="bas_di"      ${effMode === "bas_di"      ? "selected" : ""}>🏢 BAS Mode</option>
            <option value="direct_load" ${effMode === "direct_load" ? "selected" : ""}>🔌 Direct Load</option>
          </select>
        </div>
      </div>
      <!-- Relay sub-table -->
      <div style="padding:0 0 2px 0;${!isVEN ? "opacity:0.5;pointer-events:none;" : ""}">
        <table style="width:100%;border-collapse:collapse;font-size:12px;">
          <thead><tr style="background:var(--surface);">
            <th style="text-align:left;padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:10px;color:var(--text-hint);font-weight:600;">Relay</th>
            <th style="text-align:left;padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:10px;color:var(--text-hint);font-weight:600;">Mode Override</th>
            <th style="text-align:left;padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:10px;color:var(--text-hint);font-weight:600;">Shed Level (BAS Mode)</th>
            <th style="text-align:left;padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:10px;color:var(--text-hint);font-weight:600;">Designated Relay (Direct Load)</th>
            <th style="text-align:left;padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:10px;color:var(--text-hint);font-weight:600;">Participation</th>
          </tr></thead>
          <tbody>${relayRows}</tbody>
        </table>
        ${!isVEN ? '<div style="text-align:center;padding:6px;font-size:10px;color:var(--text-hint);">Enable as VEN Resource to configure relay DR behavior</div>' : ""}
      </div>
    </div>`;
  }).join("");
}

function drUpdateDevice(uid, field, value) {
  if (!drDeviceConfig[uid]) drDeviceConfig[uid] = { ven_resource: false, default_mode: "direct_load", relays: {} };
  drDeviceConfig[uid][field] = value;
}

function drUpdateRelay(uid, relayNum, field, value) {
  if (!drDeviceConfig[uid]) drDeviceConfig[uid] = { ven_resource: false, default_mode: "direct_load", relays: {} };
  if (!drDeviceConfig[uid].relays[relayNum]) drDeviceConfig[uid].relays[relayNum] = {};
  // If setting is_designated true, unset all other relays on same device (only one designated per device)
  if (field === "is_designated" && value === true) {
    for (let r = 1; r <= 4; r++) {
      if (r !== relayNum && drDeviceConfig[uid].relays[r]) {
        drDeviceConfig[uid].relays[r].is_designated = false;
      }
    }
  }
  drDeviceConfig[uid].relays[relayNum][field] = value === "" ? null : value;
  renderDRConfig();
}

function drSetAllMode(mode) {
  const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
  realDevices.forEach(dev => {
    if (!drDeviceConfig[dev.uid]) drDeviceConfig[dev.uid] = { ven_resource: false, default_mode: mode, relays: {} };
    drDeviceConfig[dev.uid].default_mode = mode;
  });
  renderDRConfig();
}

function drSetAllVEN(enabled) {
  const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
  realDevices.forEach(dev => {
    if (!drDeviceConfig[dev.uid]) drDeviceConfig[dev.uid] = { ven_resource: enabled, default_mode: "direct_load", relays: {} };
    drDeviceConfig[dev.uid].ven_resource = enabled;
  });
  renderDRConfig();
}

async function saveAllDRConfig() {
  const statusArea = document.getElementById("dr-device-config-list");
  const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
  let errors = 0;

  for (const dev of realDevices) {
    const cfg = drDeviceConfig[dev.uid];
    if (!cfg) continue;

    // Upsert device-level record
    try {
      await fetch(`${SUPABASE_URL}/rest/v1/device_dr_config?on_conflict=device_uid`, {
        method: "POST",
        headers: {
          "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
          "Content-Type": "application/json",
          "Prefer": "resolution=merge-duplicates,return=minimal"
        },
        body: JSON.stringify({
          device_uid:   dev.uid,
          ven_resource: cfg.ven_resource,
          default_mode: cfg.default_mode,
          updated_at:   new Date().toISOString()
        })
      });
    } catch(e) { console.error("Save device DR config failed:", dev.uid, e); errors++; }

    // Upsert relay-level records
    for (let r = 1; r <= 4; r++) {
      const rc = cfg.relays?.[r];
      if (!rc) continue;
      try {
        await fetch(`${SUPABASE_URL}/rest/v1/device_relay_dr_config?on_conflict=device_uid,relay_number`, {
          method: "POST",
          headers: {
            "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
            "Content-Type": "application/json",
            "Prefer": "resolution=merge-duplicates,return=minimal"
          },
          body: JSON.stringify({
            device_uid:    dev.uid,
            relay_number:  r,
            mode_override: rc.mode_override || null,
            shed_level:    rc.shed_level    || null,
            is_designated: rc.is_designated ?? false,
            enabled:       rc.enabled       ?? true,
            updated_at:    new Date().toISOString()
          })
        });
      } catch(e) { console.error("Save relay DR config failed:", dev.uid, r, e); errors++; }
    }
  }

  setStatus(errors ? "error" : "ready",
    errors ? `DR config saved with ${errors} error(s) — check console.`
           : "DR device configuration saved successfully.");
}

// ── Signal → Strategy mapping ─────────────────────────────────────────────────
function signalToStrategy(level) {
  const numLevel = parseFloat(level);
  // Find closest mapping
  let best = oadrMappings[0];
  let bestDiff = Math.abs(numLevel - best.level);
  oadrMappings.forEach(m => {
    const diff = Math.abs(numLevel - m.level);
    if (diff < bestDiff) { best = m; bestDiff = diff; }
  });
  return best;
}

// ── Config Tab ────────────────────────────────────────────────────────────────
async function initOpenADRConfig() {
  // Set endpoint URLs
  const epEvent  = document.getElementById("oadr-endpoint-event");
  const epCancel = document.getElementById("oadr-endpoint-cancel");
  const epReport = document.getElementById("oadr-endpoint-report");
  if (epEvent)  epEvent.textContent  = PROXY_URL + "openadr/event";
  if (epCancel) epCancel.textContent = PROXY_URL + "openadr/cancel";
  if (epReport) epReport.textContent = PROXY_URL + "openadr/report";

  // Load VTN config
  try {
    const rows = await supabaseGet("openadr_vtn_config?order=id.desc&limit=1");
    if (Array.isArray(rows) && rows.length > 0) {
      oadrVTNConfig = rows[0];
      const set = (id, val) => { const el = document.getElementById(id); if (el && val) el.value = val; };
      set("oadr-vtn-id",    oadrVTNConfig.vtn_id);
      set("oadr-ven-id",    oadrVTNConfig.ven_id);
      set("oadr-vtn-url",   oadrVTNConfig.vtn_url);
      set("oadr-transport", oadrVTNConfig.transport);
      set("oadr-reg-id",    oadrVTNConfig.registration_id);
      set("oadr-api-key",   oadrVTNConfig.api_key);
      set("oadr-mtls-cert-id", oadrVTNConfig.mtls_cert_id);
      if (oadrVTNConfig.vtn_ca_cert) set("oadr-vtn-ca-cert", oadrVTNConfig.vtn_ca_cert);
      // Restore auth mode
      if (oadrVTNConfig.auth_mode) selectOADRAuthMode(oadrVTNConfig.auth_mode, null, true);
      // Show cert status if configured
      if (oadrVTNConfig.mtls_cert_id) updateMTLSStatus(oadrVTNConfig.mtls_cert_id);
    }
  } catch(e) { console.error("initOpenADRConfig:", e); }

  renderMappingTable();
  loadDRConfig();
}

function renderMappingTable() {
  const tbody = document.getElementById("oadr-mapping-table");
  if (!tbody) return;
  tbody.innerHTML = oadrMappings.map((m, i) => `
    <tr>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">
        <input type="number" step="0.05" min="0" max="1" value="${m.level}"
          onchange="oadrMappings[${i}].level=parseFloat(this.value)"
          style="width:70px;padding:4px 6px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;" />
      </td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">
        <input type="text" value="${m.desc}"
          onchange="oadrMappings[${i}].desc=this.value"
          style="width:140px;padding:4px 6px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;" />
      </td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">
        <input type="number" min="0" max="63" value="${m.strategy}"
          onchange="oadrMappings[${i}].strategy=parseInt(this.value)"
          style="width:70px;padding:4px 6px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;" />
      </td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);">
        <select onchange="oadrMappings[${i}].mode=this.value"
          style="padding:4px 6px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
          <option value="dlc" ${m.mode==="dlc"?"selected":""}>DLC</option>
          <option value="di"  ${m.mode==="di" ?"selected":""}>DI</option>
        </select>
      </td>
      <td style="padding:8px;border-bottom:0.5px solid var(--border);color:var(--text-hint);">${m.pct}%</td>
    </tr>`).join("");
}

async function saveVTNConfig() {
  const authMode = document.querySelector(".oadr-auth-btn.active")?.dataset?.mode || "none";
  const config = {
    vtn_id:          document.getElementById("oadr-vtn-id")?.value?.trim(),
    ven_id:          document.getElementById("oadr-ven-id")?.value?.trim(),
    vtn_url:         document.getElementById("oadr-vtn-url")?.value?.trim(),
    transport:       document.getElementById("oadr-transport")?.value,
    registration_id: document.getElementById("oadr-reg-id")?.value?.trim(),
    auth_mode:       authMode,
    api_key:         authMode === "apikey" ? document.getElementById("oadr-api-key")?.value?.trim() : null,
    mtls_cert_id:    authMode === "mtls"   ? document.getElementById("oadr-mtls-cert-id")?.value?.trim() : null,
    vtn_ca_cert:     authMode === "mtls"   ? document.getElementById("oadr-vtn-ca-cert")?.value?.trim() : null,
    status:          "registered",
    updated_at:      new Date().toISOString()
  };
  const statusEl = document.getElementById("oadr-config-status");

  // Write each key to program_settings — Worker reads from here via loadVTNConfig()
  const pairs = [
    ["vtn_url",        config.vtn_url        || ""],
    ["vtn_id",         config.vtn_id         || ""],
    ["ven_id",         config.ven_id         || ""],
    ["ven_name",       config.ven_id         || ""],  // use VEN ID as name too
    ["oadr_transport", config.transport      || "rest"],
    ["oadr_reg_id",    config.registration_id|| ""],
    ["oadr_auth_mode", config.auth_mode      || "none"],
  ];

  try {
    for (const [key, value] of pairs) {
      await fetch(`${SUPABASE_URL}/rest/v1/program_settings`, {
        method: "POST",
        headers: {
          "apikey": SUPABASE_KEY,
          "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
          "Content-Type": "application/json",
          "Prefer": "resolution=merge-duplicates"
        },
        body: JSON.stringify({ setting_key: key, setting_value: value })
      });
    }

    // Also save to openadr_vtn_config for dashboard display (if table exists)
    try {
      if (oadrVTNConfig?.id) {
        await supabasePatch(`openadr_vtn_config?id=eq.${oadrVTNConfig.id}`, config);
      } else {
        await fetch(`${SUPABASE_URL}/rest/v1/openadr_vtn_config`, {
          method: "POST",
          headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
            "Content-Type": "application/json", "Prefer": "return=minimal" },
          body: JSON.stringify(config)
        });
      }
    } catch(e2) { console.warn("openadr_vtn_config table may not exist yet:", e2.message); }

    oadrVTNConfig = { ...oadrVTNConfig, ...config };
    if (statusEl) { statusEl.textContent = "✅ VTN config saved."; statusEl.style.color = "var(--green-dark)"; statusEl.style.display = "block"; }
    setTimeout(() => { if (statusEl) statusEl.style.display = "none"; }, 3000);

  } catch(e) {
    if (statusEl) { statusEl.textContent = `Error saving: ${e.message}`; statusEl.style.color = "var(--red)"; statusEl.style.display = "block"; }
    console.error("saveVTNConfig:", e);
  }
}

async function saveMappings() {
  // Store in program_settings as JSON
  await supabasePatch("program_settings?setting_key=eq.openadr_mappings",
    { setting_value: JSON.stringify(oadrMappings), updated_at: new Date().toISOString() });
  const statusEl = document.getElementById("oadr-mapping-status");
  if (statusEl) { statusEl.textContent = "✅ Mappings saved."; statusEl.style.color = "var(--green-dark)"; statusEl.style.display = "block"; }
  setTimeout(() => { if (statusEl) statusEl.style.display = "none"; }, 2000);
}


// ── Events Tab ────────────────────────────────────────────────────────────────
function startOADRPoller() {
  // Starts the background poller — called on login so it runs regardless of which tab is open
  if (oadrReportTimer) clearInterval(oadrReportTimer);
  oadrReportTimer = setInterval(async () => {
    await checkAndFirePendingEvents();
    await sendPendingReports();
    // Refresh UI if the OpenADR Events tab is currently active
    if (document.getElementById("tab-openadr")?.classList.contains("active")) {
      await loadOpenADREvents();
      await loadDispatchLog();
    }
  }, 30000);
  console.log("OpenADR poller started.");
}

async function initOpenADREvents() {
  await loadOpenADRVTNStatus();
  await loadOpenADREvents();
  await loadOpenADRReports();
  await loadDispatchLog();
  // Ensure poller is running (in case it wasn't started yet)
  if (!oadrReportTimer) startOADRPoller();
}

async function loadOpenADRVTNStatus() {
  try {
    const rows = await supabaseGet("openadr_vtn_config?order=id.desc&limit=1");
    const labelEl = document.getElementById("oadr-vtn-status-label");
    const dotEl   = document.getElementById("oadr-vtn-status-dot");
    if (Array.isArray(rows) && rows.length > 0) {
      oadrVTNConfig = rows[0];
      if (labelEl) labelEl.textContent = `VTN: ${oadrVTNConfig.vtn_id} · VEN: ${oadrVTNConfig.ven_id}`;
      if (dotEl) { dotEl.textContent = "🟢 Registered"; dotEl.style.background = "var(--green-bg)"; dotEl.style.color = "var(--green-dark)"; }
    } else {
      if (labelEl) labelEl.textContent = "Not configured — go to Admin → OpenADR Config";
      if (dotEl) { dotEl.textContent = "⚫ Not Configured"; }
    }
  } catch(e) { console.error("loadOpenADRVTNStatus:", e); }
}

async function loadOpenADREvents() {
  const list = document.getElementById("oadr-events-list");
  if (!list) return;
  try {
    const filter = document.getElementById("oadr-filter")?.value || "active";
    let query = "openadr_events?order=dtstart.desc&limit=50";
    if (filter === "active")    query += "&event_status=not.in.(completed,cancelled)";
    if (filter === "completed") query += "&event_status=in.(completed,cancelled)";

    const rows = await supabaseGet(query);

    // Update counts
    const all       = await supabaseGet("openadr_events?select=id,event_status,opt_type");
    const total     = all?.length || 0;
    const pending   = all?.filter(e => e.event_status === "far" || e.event_status === "near").length || 0;
    const active    = all?.filter(e => e.event_status === "active").length || 0;
    const optIn     = all?.filter(e => e.opt_type === "optIn").length || 0;
    const optOut    = all?.filter(e => e.opt_type === "optOut").length || 0;

    const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    set("oadr-count-total",  total);
    set("oadr-count-pending", pending);
    set("oadr-count-active",  active);
    set("oadr-count-optin",   optIn);
    set("oadr-count-optout",  optOut);

    if (!Array.isArray(rows) || !rows.length) {
      list.innerHTML = `<div class="sched-empty">No OpenADR events found.</div>`;
      return;
    }

    const statusColors = {
      far:"var(--text-hint)", near:"var(--amber)", active:"var(--green-dark)",
      completed:"var(--text-secondary)", cancelled:"var(--red)"
    };

    list.innerHTML = rows.map(e => {
      const dtstart  = e.dtstart ? new Date(e.dtstart).toLocaleString() : "—";
      const end      = e.dtstart && e.duration_mins
        ? new Date(new Date(e.dtstart).getTime() + e.duration_mins*60000).toLocaleString()
        : "—";
      const sc       = statusColors[e.event_status] || "var(--text-secondary)";
      const mapping  = signalToStrategy(e.signal_level || 0);
      const isActive = e.event_status === "active";
      const canOverride = e.opt_type !== "optOut" && e.event_status !== "completed";

      return `<div class="queue-item ${e.event_status}">
        <div class="queue-info">
          <div class="queue-name">
            VTN Event: ${e.vtn_event_id}
            <span style="font-size:10px;font-weight:600;padding:2px 8px;border-radius:8px;background:var(--surface2);color:${sc};margin-left:6px;">${e.event_status}</span>
            <span style="font-size:10px;padding:2px 8px;border-radius:8px;margin-left:4px;background:${e.opt_type==='optIn'?'var(--green-bg)':'var(--surface2)'};color:${e.opt_type==='optIn'?'var(--green-dark)':'var(--text-hint)'};">${e.opt_type}</span>
          </div>
          <div class="queue-detail">
            Signal: ${e.signal_name || "SIMPLE"} @ ${e.signal_level ?? "—"} → ${mapping.desc} (Strategy ${mapping.strategy}, ${mapping.pct}% shed)
          </div>
          <div class="queue-detail">
            📅 Start: ${dtstart} · End: ${end} · ${e.duration_mins || "—"} min
          </div>
        </div>
        <div class="sched-actions">
          ${canOverride ? `
            <button class="sched-delete-btn" style="color:var(--red);"
              onclick="overrideOpenADREvent('${e.vtn_event_id}', 'optOut')">Opt Out</button>
            ${e.opt_type === "optOut" ? `<button class="sched-delete-btn" style="color:var(--green-dark);"
              onclick="overrideOpenADREvent('${e.vtn_event_id}', 'optIn')">Re-Opt In</button>` : ""}
          ` : ""}
        </div>
      </div>`;
    }).join("");

  } catch(e) {
    console.error("loadOpenADREvents:", e);
    if (list) list.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error loading events.</div>`;
  }
}

async function overrideOpenADREvent(vtnEventId, optType) {
  const reason = optType === "optOut"
    ? prompt("Reason for opting out (optional):") || "Manual override by operator"
    : null;
  await supabasePatch(
    `openadr_events?vtn_event_id=eq.${encodeURIComponent(vtnEventId)}`,
    { opt_type: optType, override_opt: optType, override_reason: reason }
  );
  // Send oadrCreatedEvent to VTN with updated opt
  await sendOptResponse(vtnEventId, optType);
  await loadOpenADREvents();
  setStatus("ready", `Event ${vtnEventId} — ${optType === "optOut" ? "Opted Out" : "Re-Opted In"}`);
}

async function logOADRDispatch(evt, device, relayNum, relayAction, architecture, shedLabel, mapping, reps, schedUnix, hex) {
  // Build the OpenADR payload that would be sent to VTN for reference
  const oadrPayload = buildOADRPayload("oadrCreatedEvent", {
    venId:       oadrVTNConfig?.ven_id || "local-ven",
    vtnEventId:  evt.vtn_event_id,
    optType:     "optIn",
    signalLevel: evt.signal_level,
    signalName:  evt.signal_name || "SIMPLE",
    dtstart:     evt.dtstart,
    duration:    evt.duration_mins,
    created:     new Date().toISOString()
  });

  const record = {
    vtn_event_id:  evt.vtn_event_id,
    fired_at:      new Date().toISOString(),
    device_uid:    device.uid,
    device_name:   device.name,
    relay_number:  relayNum,
    relay_action:  relayAction,
    architecture,
    shed_level:    shedLabel,
    signal_level:  evt.signal_level,
    lc_mode:       mapping.mode,
    lc_strategy:   mapping.strategy,
    lc_reps:       reps,
    lc_hex:        hex,
    oadr_payload:  JSON.stringify(oadrPayload.json),
    sched_unix:    schedUnix
  };

  try {
    await supabasePost("openadr_dispatch_log", record);
    console.log(`OpenADR dispatch logged: ${device.name} R${relayNum} ${relayAction} hex=${hex}`);
  } catch(e) { console.error("logOADRDispatch:", e); }
}

async function checkAndFirePendingEvents() {
  // Don't run without a valid session — avoids 401 errors during page load
  if (!currentSession?.access_token) return;
  const now = new Date().toISOString();

  // ── Cleanup: mark expired active events as completed and send restore ──
  try {
    const active = await supabaseGet("openadr_events?event_status=eq.active&opt_type=eq.optIn&limit=20");
    if (Array.isArray(active)) {
      for (const evt of active) {
        if (!evt.dtstart || !evt.duration_mins) continue;
        const endTime = new Date(new Date(evt.dtstart).getTime() + evt.duration_mins * 60000);
        if (new Date() >= endTime) {
          console.log(`Cleaning up expired event: ${evt.vtn_event_id} (ended ${endTime.toLocaleString()})`);
          // Send restore to all VEN devices
          const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
          const venDevices  = realDevices.filter(d => drDeviceConfig[d.uid]?.ven_resource === true);
          const targetDevices = venDevices.length > 0 ? venDevices : realDevices;
          const restoreHex = buildRestoreHex("all_on");
          for (const device of targetDevices) await sendLCToDevice(device.uid, restoreHex);
          await supabasePatch(
            `openadr_events?vtn_event_id=eq.${encodeURIComponent(evt.vtn_event_id)}`,
            { event_status: "completed" }
          );
          await sendCompletionReport(evt);
          console.log(`Event ${evt.vtn_event_id} marked completed.`);
        }
      }
    }
  } catch(e) { console.error("checkAndFirePendingEvents cleanup:", e); }

  // ── Find and fire events that should start now ──
  const rows = await supabaseGet(
    `openadr_events?event_status=in.(far,near)&dtstart=lte.${now}&opt_type=eq.optIn&order=dtstart.asc&limit=10`
  );
  if (!Array.isArray(rows) || !rows.length) return;

  for (const evt of rows) {
    try {
      console.log(`Firing OpenADR event: ${evt.vtn_event_id} signal=${evt.signal_level}`);
      const mapping   = signalToStrategy(evt.signal_level || 0);
      const schedUnix = Math.floor(new Date(evt.dtstart).getTime() / 1000);
      const cycleTime = mapping.strategy <= 3 ? 7.5 : 15;
      const reps      = evt.duration_mins ? Math.max(1, Math.round(evt.duration_mins / cycleTime)) : 1;

      // Config-aware dispatch: respect device DR configuration
      const realDevices = DEVICES.filter(d => !d.uid.includes("PLACEHOLDER"));
      const venDevices  = realDevices.filter(d => drDeviceConfig[d.uid]?.ven_resource === true);

      // If no devices are configured as VEN resources yet, fall back to all real devices
      const targetDevices = venDevices.length > 0 ? venDevices : realDevices;

      for (const device of targetDevices) {
        const devCfg     = drDeviceConfig[device.uid];
        const devMode    = devCfg?.default_mode || "direct_load";
        const shedLabel  = mapping.desc.toLowerCase().includes("emergency") ? "emergency"
                         : mapping.desc.toLowerCase().includes("high")      ? "high"
                         : mapping.desc.toLowerCase().includes("medium")    ? "medium"
                         : mapping.desc.toLowerCase().includes("low")       ? "low"
                         : null;

        // Determine which relay(s) to fire and what hex to send
        let sentAny = false;
        for (let rNum = 1; rNum <= 4; rNum++) {
          const rc           = devCfg?.relays?.[rNum] || {};
          const effectiveMode = rc.mode_override ?? devMode;
          if (rc.enabled === false) continue;

          if (effectiveMode === "bas_di") {
            // BAS/DI: fire the relay whose shed_level matches the incoming signal
            if (!shedLabel || rc.shed_level !== shedLabel) continue;
            const relayAction = `relay${rNum}_on`;
            const hex = buildLCHex(relayAction, mapping.mode, mapping.strategy, reps, schedUnix);
            await sendLCToDevice(device.uid, hex);
            await logOADRDispatch(evt, device, rNum, relayAction, "bas_di", shedLabel, mapping, reps, schedUnix, hex);
            sentAny = true;
          } else {
            // Direct Load: fire only the designated relay, duty cycle carries the shed level
            if (!rc.is_designated) continue;
            const relayAction = `relay${rNum}_on`;
            const hex = buildLCHex(relayAction, mapping.mode, mapping.strategy, reps, schedUnix);
            await sendLCToDevice(device.uid, hex);
            await logOADRDispatch(evt, device, rNum, relayAction, "direct_load", shedLabel, mapping, reps, schedUnix, hex);
            sentAny = true;
          }
        }
        // Fallback: if device has no relay config at all, send all_on with mapping strategy
        if (!sentAny) {
          const hex = buildLCHex("all_on", mapping.mode, mapping.strategy, reps, schedUnix);
          await sendLCToDevice(device.uid, hex);
          await logOADRDispatch(evt, device, null, "all_on", "fallback", shedLabel, mapping, reps, schedUnix, hex);
        }
      }

      // Update event status
      await supabasePatch(
        `openadr_events?vtn_event_id=eq.${encodeURIComponent(evt.vtn_event_id)}`,
        { event_status: "active" }
      );

      // Schedule end restore
      setTimeout(async () => {
        const restoreHex = buildRestoreHex("all_on");
        for (const device of targetDevices) await sendLCToDevice(device.uid, restoreHex);
        await supabasePatch(
          `openadr_events?vtn_event_id=eq.${encodeURIComponent(evt.vtn_event_id)}`,
          { event_status: "completed" }
        );
        await sendCompletionReport(evt);
      }, (evt.duration_mins || 30) * 60000);

      // Send initial telemetry report
      await sendUpdateReport(evt, "x-resourceStatus", "AVAILABLE");

    } catch(e) { console.error("checkAndFirePendingEvents:", evt.vtn_event_id, e); }
  }
}

// ── OpenADR Reporting ─────────────────────────────────────────────────────────
async function sendOptResponse(vtnEventId, optType) {
  if (!oadrVTNConfig?.vtn_url) return;
  // Build oadrCreatedEvent payload
  const payload = buildOADRPayload("oadrCreatedEvent", {
    venId:      oadrVTNConfig.ven_id,
    vtnEventId, optType,
    created:    new Date().toISOString()
  });
  try {
    await fetch(`${PROXY_URL}openadr/send`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ vtn_url: oadrVTNConfig.vtn_url, transport: oadrVTNConfig.transport, payload })
    });
  } catch(e) { console.error("sendOptResponse:", e); }
}

async function sendUpdateReport(evt, readingType, value) {
  if (!oadrVTNConfig?.vtn_url) return;
  const payload = buildOADRPayload("oadrUpdateReport", {
    venId:      oadrVTNConfig.ven_id,
    vtnEventId: evt.vtn_event_id,
    readingType, value,
    dtstart:    new Date().toISOString(),
    devices:    DEVICES.filter(d => !d.uid.includes("PLACEHOLDER")).map(d => d.uid)
  });
  // Store in openadr_reports
  await fetch(`${SUPABASE_URL}/rest/v1/openadr_reports`, {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
      "Content-Type": "application/json", "Prefer": "return=minimal" },
    body: JSON.stringify({
      vtn_event_id: evt.vtn_event_id, report_name: "oadrUpdateReport",
      created_dt: new Date().toISOString(), dtstart: evt.dtstart,
      duration_mins: evt.duration_mins, reading_type: readingType,
      value: typeof value === "number" ? value : null,
      raw_payload: JSON.stringify(payload)
    })
  });
  // Send to VTN
  try {
    await fetch(`${PROXY_URL}openadr/send`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ vtn_url: oadrVTNConfig.vtn_url, transport: oadrVTNConfig.transport, payload })
    });
  } catch(e) { console.error("sendUpdateReport:", e); }
}

async function sendCompletionReport(evt) {
  // Gather actual device readings during event
  const startMs = new Date(evt.dtstart).getTime();
  const endMs   = startMs + ((evt.duration_mins || 30) * 60000);
  const since   = new Date(startMs).toISOString();
  const until   = new Date(endMs).toISOString();

  const readings = await supabaseGet(
    `device_readings?recorded_at=gte.${since}&recorded_at=lte.${until}&order=recorded_at.desc&limit=500`
  );

  let totalWatts = 0, count = 0;
  if (Array.isArray(readings)) {
    readings.forEach(r => { if (r.watts_consumed) { totalWatts += r.watts_consumed; count++; } });
  }
  const avgWatts = count ? Math.round(totalWatts / count) : 0;

  await sendUpdateReport(evt, "x-resourceStatus", avgWatts);
}

async function sendPendingReports() {
  // Send 5-min telemetry reports for active events
  const active = await supabaseGet("openadr_events?event_status=eq.active&opt_type=eq.optIn&limit=10");
  if (!Array.isArray(active) || !active.length) return;
  for (const evt of active) {
    // Get latest device readings
    const readings = await supabaseGet("device_readings?order=recorded_at.desc&limit=20");
    if (!Array.isArray(readings) || !readings.length) continue;
    const watts = readings.filter(r => r.watts_consumed).map(r => r.watts_consumed);
    const avgW  = watts.length ? Math.round(watts.reduce((a,b)=>a+b,0)/watts.length) : 0;
    await sendUpdateReport(evt, "x-resourceStatus", avgW);
  }
}

// ── OpenADR XML/JSON Payload Builder ─────────────────────────────────────────
function buildOADRPayload(type, data) {
  const ts = new Date().toISOString();
  // Returns both REST (JSON) and SOAP (XML) formats
  const json = { oadrPayload: { type, ...data, requestID: `req-${Date.now()}`, createdDateTime: ts } };
  const xml  = `<?xml version="1.0" encoding="UTF-8"?>
<oadrPayload xmlns="http://openadr.org/oadr-2.0b/2012/07">
  <eiResponse>
    <responseCode>200</responseCode>
    <requestID>req-${Date.now()}</requestID>
  </eiResponse>
  <${type}>
    <venID>${data.venId || ""}</venID>
    <vtnEventID>${data.vtnEventId || ""}</vtnEventID>
    <optType>${data.optType || ""}</optType>
    <createdDateTime>${ts}</createdDateTime>
  </${type}>
</oadrPayload>`;
  return { json, xml };
}

// ── Simulate incoming OpenADR event (for testing) ─────────────────────────────
async function simulateOpenADREvent() {
  const signalLevel = parseFloat(document.getElementById("oadr-test-signal")?.value || "0.5");
  const startMins   = parseInt(document.getElementById("oadr-test-start")?.value || "1");
  const duration    = parseInt(document.getElementById("oadr-test-duration")?.value || "30");
  const statusEl    = document.getElementById("oadr-test-status");

  const dtstart = new Date(Date.now() + startMins * 60000).toISOString();
  const mapping = signalToStrategy(signalLevel);
  const vtnEventId = `TEST-${Date.now()}`;

  if (statusEl) { statusEl.textContent = "Simulating incoming OpenADR event..."; statusEl.style.color = "var(--text-secondary)"; statusEl.style.display = "block"; }

  try {
    // Insert simulated event
    await fetch(`${SUPABASE_URL}/rest/v1/openadr_events`, {
      method: "POST",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json", "Prefer": "return=minimal" },
      body: JSON.stringify({
        vtn_event_id:  vtnEventId,
        event_status:  "near",
        opt_type:      "optIn",
        signal_name:   "SIMPLE",
        signal_type:   "LOAD_DISPATCH",
        signal_level:  signalLevel,
        target_all:    true,
        dtstart,
        duration_mins: duration,
        created_dt:    new Date().toISOString(),
        lc_strategy:   mapping.strategy,
        lc_mode:       mapping.mode,
        raw_payload:   JSON.stringify({ simulated: true, signalLevel, mapping })
      })
    });

    if (statusEl) { statusEl.textContent = `✅ Simulated event created — ${mapping.desc} (${mapping.pct}% shed) starting in ${startMins} min. Switch to OpenADR Events tab to monitor.`; statusEl.style.color = "var(--green-dark)"; }

    // Load events immediately
    await loadOpenADREvents();

  } catch(e) {
    console.error("simulateOpenADREvent:", e);
    if (statusEl) { statusEl.textContent = `Error: ${e.message}`; statusEl.style.color = "var(--red)"; }
  }
}

async function loadOpenADRReports() {
  const list = document.getElementById("oadr-reports-list");
  if (!list) return;
  try {
    const rows = await supabaseGet("openadr_reports?order=created_dt.desc&limit=20");
    if (!Array.isArray(rows) || !rows.length) {
      list.innerHTML = `<div class="sched-empty">No telemetry reports sent yet.</div>`;
      return;
    }
    list.innerHTML = rows.map(r => `
      <div class="queue-item sent" style="margin-bottom:6px;">
        <div class="queue-info">
          <div class="queue-name">${r.report_name} — Event: ${r.vtn_event_id}</div>
          <div class="queue-detail">Type: ${r.reading_type} · Value: ${r.value ?? "—"} · ${new Date(r.created_dt).toLocaleString()}</div>
        </div>
        <span class="queue-status sent">Sent</span>
      </div>`).join("");
  } catch(e) { console.error("loadOpenADRReports:", e); }
}

async function loadDispatchLog() {
  const list = document.getElementById("oadr-dispatch-log");
  if (!list) return;
  list.innerHTML = '<div class="sched-empty">Loading...</div>';
  try {
    const rows = await supabaseGet("openadr_dispatch_log?order=fired_at.desc&limit=50");
    if (!Array.isArray(rows) || !rows.length) {
      list.innerHTML = '<div class="sched-empty">No dispatches logged yet.</div>';
      return;
    }
    list.innerHTML = `
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:11px;">
          <thead><tr>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Fired At</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Device</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Relay</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Architecture</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Shed Level</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Signal</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Mode</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Strategy</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Reps</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">LC Hex</th>
            <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">OpenADR Payload</th>
          </tr></thead>
          <tbody>
            ${rows.map(r => `
              <tr>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${new Date(r.fired_at).toLocaleString()}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${r.device_name || r.device_uid}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${r.relay_number ?? "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">
                  <span style="padding:2px 7px;border-radius:10px;font-size:10px;font-weight:600;
                    background:${r.architecture === "bas_di" ? "var(--blue-bg)" : r.architecture === "direct_load" ? "var(--green-bg)" : "var(--surface2)"};
                    color:${r.architecture === "bas_di" ? "var(--blue-dark)" : r.architecture === "direct_load" ? "var(--green-dark)" : "var(--text-hint)"};">
                    ${r.architecture === "bas_di" ? "BAS Mode" : r.architecture === "direct_load" ? "Direct Load" : r.architecture || "—"}
                  </span>
                </td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-transform:capitalize;">${r.shed_level || "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${r.signal_level ?? "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-transform:uppercase;">${r.lc_mode || "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${r.lc_strategy ?? "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${r.lc_reps ?? "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);font-family:monospace;font-size:10px;color:var(--blue-dark);">${r.lc_hex || "—"}</td>
                <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">
                  <button onclick="showDispatchPayload(${r.id})"
                    style="padding:2px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">
                    View JSON
                  </button>
                </td>
              </tr>`).join("")}
          </tbody>
        </table>
      </div>`;

    // Store rows for payload modal
    window._dispatchLogRows = rows;
  } catch(e) { console.error("loadDispatchLog:", e); list.innerHTML = '<div class="sched-empty">Error loading dispatch log.</div>'; }
}

function showDispatchPayload(id) {
  const row = (window._dispatchLogRows || []).find(r => r.id === id);
  if (!row) return;
  try {
    const parsed = JSON.parse(row.oadr_payload);
    const pretty = JSON.stringify(parsed, null, 2);
    const modal  = document.getElementById("event-modal");
    document.getElementById("modal-title").textContent = `OpenADR Payload — ${row.device_name} R${row.relay_number} @ ${new Date(row.fired_at).toLocaleString()}`;
    document.getElementById("modal-body").innerHTML = `
      <div style="margin-bottom:10px;">
        <div class="modal-section-title">LC Hex Sent to Device</div>
        <div class="modal-hex">${row.lc_hex}</div>
      </div>
      <div>
        <div class="modal-section-title">OpenADR JSON Payload</div>
        <pre style="font-family:monospace;font-size:11px;background:var(--surface2);border:0.5px solid var(--border-md);border-radius:var(--radius-sm);padding:10px;overflow-x:auto;white-space:pre-wrap;word-break:break-all;">${pretty}</pre>
      </div>`;
    modal.classList.add("active");
  } catch(e) { alert("Could not parse payload: " + e.message); }
}

function buildControls() {
  const grid = document.getElementById("devices-grid");
  grid.innerHTML = "";
  DEVICES.forEach(device => {
    const card = document.createElement("div");
    card.className = "device-card";
    card.innerHTML = `
      <div class="device-header">
        <div><div class="device-name">${device.name}</div><div class="device-uid">${device.uid}</div></div>
        <div class="device-badge" id="badge-${device.id}"></div>
      </div>
      ${buildTzSelector(device.id, deviceTimezones[device.id] || "America/Chicago")}
      <div class="relay-rows">
        ${[1,2,3,4].map(n => `
          <div class="relay-row" id="row-${device.id}-${n}" onclick="toggleRelay('${device.id}',${n})">
            <span class="relay-row-label">Relay ${n}</span>
            <div style="display:flex;align-items:center;gap:10px;">
              <span class="relay-row-state" id="rlbl-${device.id}-${n}">Off</span>
              ${device.sensing_capable ? `<span class="load-calling-badge" id="lcbadge-${device.id}-${n}" style="display:none;">Load Calling</span>` : ""}
              <div class="toggle" id="rtgl-${device.id}-${n}"><div class="track"></div><div class="thumb"></div></div>
            </div>
          </div>`).join("")}
      </div>
      <div class="all-row" id="allrow-${device.id}" onclick="toggleAll('${device.id}')">
        <span class="all-row-label">All Relays</span>
        <div style="display:flex;align-items:center;gap:10px;">
          <span class="all-row-state" id="alllbl-${device.id}">All off</span>
          <div class="toggle blue" id="atgl-${device.id}"><div class="track"></div><div class="thumb"></div></div>
        </div>
      </div>
`;
    grid.appendChild(card);
  });
}

// ── Data Cards ────────────────────────────────────────────────────────────────
function buildDataCards() {
  const grid = document.getElementById("data-grid");
  grid.innerHTML = "";
  const sel = document.getElementById("history-device-select");
  DEVICES.forEach(device => {
    const card = document.createElement("div");
    card.className = "data-card";
    card.innerHTML = `
      <div class="data-card-header">
        <div class="data-card-title">${device.name} — Latest</div>
        <button class="data-refresh-btn" onclick="loadLatestDevice('${device.id}')">Refresh</button>
        <button class="data-refresh-btn" style="color:var(--blue-dark);border-color:var(--blue);background:var(--blue-bg);" onclick="viewDeviceHistory('${device.uid}')">📋 History</button>
        <button class="data-refresh-btn" style="color:var(--green-dark);border-color:var(--green);" onclick="requestHealthCheck('${device.uid}','${device.id}')">🩺 Health Check</button>
      </div>
      <div id="data-fields-${device.id}"><div class="data-empty">No data yet</div></div>
      <div class="data-timestamp" id="data-ts-${device.id}"></div>
      <div id="health-strip-${device.id}"></div>`;
    grid.appendChild(card);
    const opt = document.createElement("option");
    opt.value = device.uid; opt.textContent = device.name;
    sel.appendChild(opt);
    // Also populate chart device selector
    const chartSel = document.getElementById("chart-device-select");
    if (chartSel) {
      const copt = document.createElement("option");
      copt.value = device.uid; copt.textContent = device.name;
      chartSel.appendChild(copt);
    }
  });
}

// ── UI Helpers ────────────────────────────────────────────────────────────────
function setRelayUI(deviceId, num, on, loadCalling) {
  relayState[deviceId][num] = on;
  document.getElementById(`row-${deviceId}-${num}`).classList.toggle("on", on);
  document.getElementById(`rtgl-${deviceId}-${num}`).classList.toggle("on", on);
  const lbl = document.getElementById(`rlbl-${deviceId}-${num}`);
  lbl.textContent = on ? "On" : "Off";
  lbl.className = "relay-row-state" + (on ? " on" : "");
  // Load calling badge — only present on sensing_capable devices.
  // Show when relay is OFF and load is calling (y bit = 1).
  const badge = document.getElementById(`lcbadge-${deviceId}-${num}`);
  if (badge) badge.style.display = (!on && loadCalling) ? "" : "none";
}
function setAllUI(deviceId, on) {
  relayState[deviceId].all = on;
  document.getElementById(`allrow-${deviceId}`).classList.toggle("on", on);
  document.getElementById(`atgl-${deviceId}`).classList.toggle("on", on);
  const lbl = document.getElementById(`alllbl-${deviceId}`);
  lbl.textContent = on ? "All on" : "All off";
  lbl.className = "all-row-state" + (on ? " on" : "");
}
function setDeviceDisabled(deviceId, disabled) {
  [1,2,3,4].forEach(n => document.getElementById(`row-${deviceId}-${n}`).classList.toggle("disabled", disabled));
  document.getElementById(`allrow-${deviceId}`).classList.toggle("disabled", disabled);
}

// ── Send Command ──────────────────────────────────────────────────────────────
async function send(deviceId, key, label) {
  if (busy) return false;
  const dev = DEVICES.find(d => d.id === deviceId);
  if (!dev) { setStatus("error", "Unknown device — command blocked."); return false; }
  busy = true; setDeviceDisabled(deviceId, true); setStatus("sending", label + "...");
  try {
    const res = await fetch(PROXY_URL, { method: "POST", headers: { "Content-Type": "application/json", "X-Device-UID": dev.uid }, body: JSON.stringify(COMMANDS[key]) });
    if (res.ok) { setStatus("ready", label + " — done."); busy = false; setDeviceDisabled(deviceId, false); return true; }
    else { setStatus("error", "Error " + res.status + " — command failed."); busy = false; setDeviceDisabled(deviceId, false); return false; }
  } catch(e) { setStatus("error", "Network error — check connection."); busy = false; setDeviceDisabled(deviceId, false); return false; }
}
async function sendToDevice(uid, key) {
  // Route EV chargers to DR dispatch instead of Notehub relay
  if (uid.startsWith("ev_")) {
    const stationId = uid.replace("ev_", "");
    const isShed    = key === "all_off" || key.endsWith("_off");
    if (isShed) await dispatchEVDRSingle(stationId, 0.75);
    else        await restoreEVSingle(stationId);
    return;
  }
  // Route battery assets to battery DR dispatch
  if (uid.startsWith("batt_")) {
    const assetId = uid.replace("batt_","");
    const isShed  = key === "all_off" || key.endsWith("_off");
    if (isShed) await dispatchBatteryDRSingle(assetId, "hold");
    else        await restoreBatterySingle(assetId);
    return;
  }
  // Route generators — shed = start generator (site sheds utility load)
  if (uid.startsWith("gen_")) {
    const assetId = uid.replace("gen_","");
    const isShed  = key === "all_off" || key.endsWith("_off");
    if (isShed) await startGeneratorSingle(assetId);
    else        await stopGeneratorSingle(assetId);
    return;
  }
  try {
    await fetch(PROXY_URL, { method: "POST", headers: { "Content-Type": "application/json", "X-Device-UID": uid }, body: JSON.stringify(COMMANDS[key]) });
  } catch(e) { console.error("Send error", uid, e); }
}
async function toggleRelay(deviceId, num) {
  const on = !relayState[deviceId][num];
  const ok = await send(deviceId, `${num}_${on?"on":"off"}`, `${DEVICES.find(d=>d.id===deviceId).name} Relay ${num} ${on?"ON":"OFF"}`);
  if (ok) {
    setRelayUI(deviceId, num, on);
    if ([1,2,3,4].every(n => relayState[deviceId][n])) setAllUI(deviceId, true);
    else if ([1,2,3,4].every(n => !relayState[deviceId][n])) setAllUI(deviceId, false);
  }
}
async function toggleAll(deviceId) {
  const on = !relayState[deviceId].all;
  const ok = await send(deviceId, `all_${on?"on":"off"}`, `${DEVICES.find(d=>d.id===deviceId).name} All ${on?"ON":"OFF"}`);
  if (ok) { setAllUI(deviceId, on); [1,2,3,4].forEach(n => setRelayUI(deviceId, n, on)); }
}

// ── Group Commands ────────────────────────────────────────────────────────────
async function sendGroupCommand(groupNum, key) {
  const members = DEVICES.filter(d => (groupAssignments[d.uid] || []).includes(groupNum));
  if (members.length === 0) { setStatus("error", "No devices in this group."); return; }
  const gname   = groupNames[groupNum];
  const isShed  = key === "all_off" || key.endsWith("_off");
  const relayMembers = members.filter(d => d.type !== "ev");
  const evMembers    = members.filter(d => d.type === "ev");
  setStatus("sending", `${gname} — sending ${key.replace("_"," ").toUpperCase()}...`);

  // Send relay commands to Notecard devices
  for (const device of relayMembers) {
    await sendToDevice(device.uid, key);
  }
  // Dispatch EV chargers via their integration
  for (const device of evMembers) {
    const stationId = device.uid.replace("ev_","");
    if (isShed) await dispatchEVDRSingle(stationId, 0.75);
    else        await restoreEVSingle(stationId);
  }

  setStatus("ready", `${gname} — ${key.replace("_"," ").toUpperCase()} sent to ${relayMembers.length} relay device${relayMembers.length!==1?"s":""} + ${evMembers.length} EV charger${evMembers.length!==1?"s":""}.`);
}

// ── Groups Tab ────────────────────────────────────────────────────────────────
async function loadGroups() {
  const container = document.getElementById("groups-container");
  container.innerHTML = `<div class="groups-loading">Loading groups...</div>`;
  try {
    // Load group names
    const names = await supabaseGet("group_names?order=group_number");
    if (Array.isArray(names) && names.length) {
      names.forEach(n => {
        groupNames[n.group_number] = n.group_name;
        if (!groupTags) groupTags = {};
        groupTags[n.group_number]  = n.group_tag || "";
      });
      numGroups = names.length;
    }
    // Load assignments
    const assignments = await supabaseGet("device_groups?order=group_number");
    groupAssignments = {};
    if (Array.isArray(assignments)) {
      assignments.forEach(a => {
        if (!groupAssignments[a.device_uid]) groupAssignments[a.device_uid] = [];
        groupAssignments[a.device_uid].push(a.group_number);
      });
    }
    renderGroups();
    refreshGroupSelectors();
  } catch(e) {
    container.innerHTML = `<div class="groups-loading">Error loading groups.</div>`;
  }
}

function renderGroups() {
  const container = document.getElementById("groups-container");
  const groupNums = Object.keys(groupNames).map(Number).sort((a,b) => a-b);
  numGroups = groupNums.length || 3;

  const html = `
    <!-- Group management header -->
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;padding:0 2px;">
      <div style="font-size:12px;color:var(--text-hint);">${numGroups} group${numGroups!==1?"s":""} configured &bull; Devices can belong to multiple groups</div>
      <div style="display:flex;gap:8px;">
        <button onclick="addGroup()" style="padding:6px 14px;border-radius:var(--radius-sm);border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:12px;font-weight:600;cursor:pointer;">+ Add Group</button>
        ${numGroups > 1 ? `<button onclick="removeLastGroup()" style="padding:6px 14px;border-radius:var(--radius-sm);border:0.5px solid var(--red);background:none;color:var(--red);font-size:12px;cursor:pointer;">− Remove Last</button>` : ""}
      </div>
    </div>
    <div class="groups-layout">
    ${groupNums.map(gn => `
      <div class="group-card" id="group-card-${gn}">
        <div class="group-header">
          <div style="flex:1;display:flex;flex-direction:column;gap:4px;">
            <div style="display:flex;align-items:center;gap:6px;">
              <span style="font-size:10px;font-weight:700;color:var(--text-hint);font-family:monospace;flex-shrink:0;">GROUP ${gn}</span>
            </div>
            <input class="group-name-input" id="gname-${gn}"
              value="${groupNames[gn]||"Group "+gn}"
              placeholder="Group name or nickname..."
              onkeydown="if(event.key==='Enter') saveGroupName(${gn})"
              style="font-size:14px;font-weight:600;" />
            <input class="group-name-input" id="gtag-${gn}"
              value="${groupTags[gn]||""}"
              placeholder="Tag / description (optional)"
              onkeydown="if(event.key==='Enter') saveGroupName(${gn})"
              style="font-size:11px;color:var(--text-hint);font-weight:400;border-color:transparent;" />
          </div>
          <button class="group-save-btn" onclick="saveGroupName(${gn})">Save</button>
        </div>
        <div style="font-size:11px;color:var(--text-hint);margin-bottom:8px;">
          ${(Object.entries(groupAssignments).filter(([uid,groups]) => groups.includes(gn)).length)} device${(Object.entries(groupAssignments).filter(([uid,groups]) => groups.includes(gn)).length)!==1?"s":""} assigned
        </div>
        <div style="font-size:11px;font-weight:600;color:var(--red);text-transform:uppercase;letter-spacing:0.05em;margin-bottom:6px;">Emergency Direct Control</div>
        <div class="group-actions">
          <button class="group-cmd-btn on" onclick="sendGroupCommand(${gn}, 'all_on')">All Relays ON</button>
          <button class="group-cmd-btn off" onclick="sendGroupCommand(${gn}, 'all_off')">All Relays OFF</button>
        </div>
        <div class="group-devices">
          ${(() => {
            const relayDevs = DEVICES.filter(d => (!d.type || d.type === "relay") && !d.uid.includes("PLACEHOLDER"));
            const evDevs    = DEVICES.filter(d => d.type === "ev");
            let html = "";
            if (relayDevs.length) {
              html += `<div style="font-size:10px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.05em;padding:6px 0 4px;font-family:monospace;">Relay Devices</div>`;
              html += relayDevs.map(d => `
                <label class="group-device-row ${(groupAssignments[d.uid] || []).includes(gn) ? "group-member" : ""}">
                  <input type="checkbox" ${(groupAssignments[d.uid] || []).includes(gn) ? "checked" : ""}
                    onchange="assignDevice('${d.uid}', ${gn}, this.checked)" />
                  <div>
                    <div class="group-device-label">${d.name}</div>
                    <div class="group-device-uid">${d.uid}</div>
                  </div>
                </label>`).join("");
            }
            if (evDevs.length) {
              html += `<div style="font-size:10px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.05em;padding:8px 0 4px;font-family:monospace;border-top:0.5px solid var(--border);margin-top:6px;">EV Chargers</div>`;
              html += evDevs.map(d => `
                <label class="group-device-row ${(groupAssignments[d.uid] || []).includes(gn) ? "group-member" : ""}">
                  <input type="checkbox" ${(groupAssignments[d.uid] || []).includes(gn) ? "checked" : ""}
                    onchange="assignDevice('${d.uid}', ${gn}, this.checked)" />
                  <div>
                    <div class="group-device-label">&#9889; ${d.name}</div>
                    <div class="group-device-uid">${d.evAsset?.integration||"OCPP"} &bull; ${d.uid.replace("ev_","")}</div>
                  </div>
                </label>`).join("");
            }
            const battDevs = DEVICES.filter(d => d.type === "battery");
            if (battDevs.length) {
              html += `<div style="font-size:10px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.05em;padding:8px 0 4px;font-family:monospace;border-top:0.5px solid var(--border);margin-top:6px;">Battery Systems</div>`;
              html += battDevs.map(d => `
                <label class="group-device-row ${(groupAssignments[d.uid] || []).includes(gn) ? "group-member" : ""}">
                  <input type="checkbox" ${(groupAssignments[d.uid] || []).includes(gn) ? "checked" : ""}
                    onchange="assignDevice('${d.uid}', ${gn}, this.checked)" />
                  <div>
                    <div class="group-device-label">&#128267; ${d.name}</div>
                    <div class="group-device-uid">${d.battAsset?.integration||"Battery"} &bull; ${d.battAsset?.capacity_kwh||""}kWh</div>
                  </div>
                </label>`).join("");
            }
            const genDevs = DEVICES.filter(d => d.type === "generator");
            if (genDevs.length) {
              html += `<div style="font-size:10px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.05em;padding:8px 0 4px;font-family:monospace;border-top:0.5px solid var(--border);margin-top:6px;">Generators</div>`;
              html += genDevs.map(d => `
                <label class="group-device-row ${(groupAssignments[d.uid] || []).includes(gn) ? "group-member" : ""}">
                  <input type="checkbox" ${(groupAssignments[d.uid] || []).includes(gn) ? "checked" : ""}
                    onchange="assignDevice('${d.uid}', ${gn}, this.checked)" />
                  <div>
                    <div class="group-device-label">&#9889; ${d.name}</div>
                    <div class="group-device-uid">${d.genAsset?.make||"Generator"} &bull; ${d.genAsset?.rated_kw||""}kW &bull; ${(d.genAsset?.integration||"relay").replace(/_/g," ")}</div>
                  </div>
                </label>`).join("");
            }
            const thermDevs = DEVICES.filter(d => d.type === "thermostat");
            if (thermDevs.length) {
              html += `<div style="font-size:10px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.05em;padding:8px 0 4px;font-family:monospace;border-top:0.5px solid var(--border);margin-top:6px;">Thermostats</div>`;
              html += thermDevs.map(d => `
                <label class="group-device-row ${(groupAssignments[d.uid] || []).includes(gn) ? "group-member" : ""}">
                  <input type="checkbox" ${(groupAssignments[d.uid] || []).includes(gn) ? "checked" : ""}
                    onchange="assignDevice('${d.uid}', ${gn}, this.checked)" />
                  <div>
                    <div class="group-device-label">🌡️ ${d.name}</div>
                    <div class="group-device-uid">${d.thermAsset?.integration||"thermostat"} &bull; Cool: ${d.thermAsset?.normal_cool||"?"}°F / Setback: ${d.thermAsset?.setback_temp||"?"}°F</div>
                  </div>
                </label>`).join("");
            }
            return html;
          })()}
        </div>
      </div>`).join("")}
    </div>`;
  container.innerHTML = html;
}

async function addGroup() {
  const nums    = Object.keys(groupNames).map(Number);
  const nextNum = nums.length ? Math.max(...nums) + 1 : 1;
  const name    = `Group ${nextNum}`;
  groupNames[nextNum] = name;
  if (!groupTags) groupTags = {};
  groupTags[nextNum]  = "";
  numGroups = Object.keys(groupNames).length;
  try {
    await supabaseUpsert("group_names",
      { group_number: nextNum, group_name: name, group_tag: "" }, "group_number");
  } catch(e) {}
  renderGroups();
  // Scroll to new group and focus name
  setTimeout(() => {
    const el = document.getElementById(`group-card-${nextNum}`);
    if (el) el.scrollIntoView({ behavior:"smooth", block:"nearest" });
    const inp = document.getElementById(`gname-${nextNum}`);
    if (inp) inp.focus();
  }, 100);
  setStatus("ready", `Group ${nextNum} created. Enter a name to customize it.`);
}

async function removeLastGroup() {
  const nums    = Object.keys(groupNames).map(Number).sort((a,b) => a-b);
  if (nums.length <= 1) { setStatus("error", "Must have at least one group."); return; }
  const lastNum = nums[nums.length - 1];
  // Check if any devices are in this group
  const memberCount = Object.values(groupAssignments).filter(gs => gs.includes(lastNum)).length;
  if (memberCount > 0) {
    if (!confirm(`Group ${lastNum} (${groupNames[lastNum]}) has ${memberCount} device${memberCount!==1?"s":""} assigned. Remove the group and unassign them?`)) return;
    // Remove all device assignments for this group
    try {
      await fetch(`${SUPABASE_URL}/rest/v1/device_groups?group_number=eq.${lastNum}`, {
        method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
      });
    } catch(e) {}
    Object.keys(groupAssignments).forEach(uid => {
      groupAssignments[uid] = (groupAssignments[uid]||[]).filter(g => g !== lastNum);
    });
  }
  // Remove from group_names
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/group_names?group_number=eq.${lastNum}`, {
      method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
    });
  } catch(e) {}
  delete groupNames[lastNum];
  if (groupTags) delete groupTags[lastNum];
  numGroups = Object.keys(groupNames).length;
  renderGroups();
  setStatus("ready", `Group ${lastNum} removed.`);
}

async function saveGroupName(groupNum) {
  const input  = document.getElementById(`gname-${groupNum}`);
  const tagEl  = document.getElementById(`gtag-${groupNum}`);
  const name   = input?.value?.trim() || `Group ${groupNum}`;
  const tag    = tagEl?.value?.trim() || "";
  groupNames[groupNum] = name;
  if (!groupTags) groupTags = {};
  groupTags[groupNum]  = tag;
  try {
    await supabaseUpsert("group_names",
      { group_number: groupNum, group_name: name, group_tag: tag },
      "group_number");
  } catch(e) { console.warn("saveGroupName:", e.message); }
  renderGroups();
  // Refresh anywhere groupNames is displayed
  refreshGroupSelectors();
  setStatus("ready", `"${name}" saved.`);
}

function refreshGroupSelectors() {
  // Update group dropdowns in scheduler, rules, etc.
  const groupNums = Object.keys(groupNames).map(Number).sort((a,b)=>a-b);
  document.querySelectorAll("select.group-target-sel, #rule-target, #inline-target, #ev-relay-device").forEach(sel => {
    const prevVal = sel.value;
    // Rebuild group options only
    Array.from(sel.options).forEach(o => {
      if (o.value.startsWith("group_")) o.remove();
    });
    // Re-add updated groups
    groupNums.forEach(n => {
      const label   = `Group ${n}: ${groupNames[n]||"Group "+n}${groupTags?.[n]?" — "+groupTags[n]:""}`;
      const exists  = Array.from(sel.options).some(o => o.value === `group_${n}`);
      if (!exists) {
        const o = document.createElement("option");
        o.value = `group_${n}`;
        o.textContent = label;
        sel.appendChild(o);
      } else {
        const o = Array.from(sel.options).find(o => o.value === `group_${n}`);
        if (o) o.textContent = label;
      }
    });
    sel.value = prevVal;
  });
}

async function assignDevice(uid, groupNum, checked) {
  if (checked) {
    // Add to this group (other group memberships stay intact)
    await supabaseUpsert("device_groups", { group_number: groupNum, group_name: groupNames[groupNum], device_uid: uid }, "group_number,device_uid");
    if (!groupAssignments[uid]) groupAssignments[uid] = [];
    if (!groupAssignments[uid].includes(groupNum)) groupAssignments[uid].push(groupNum);
  } else {
    // Remove from this group only
    await supabaseDelete("device_groups", `device_uid=eq.${encodeURIComponent(uid)}&group_number=eq.${groupNum}`);
    if (groupAssignments[uid]) groupAssignments[uid] = groupAssignments[uid].filter(g => g !== groupNum);
  }
  renderGroups();
  setStatus("ready", `${unitName(uid)} group assignment saved.`);
}

// ── Data Loading ──────────────────────────────────────────────────────────────
function relayDot(val, loadPresent) {
  // relay_status_rN — non-zero means relay is active/energized
  // loadPresent flag indicates load is calling for power on the line side
  const active  = val > 0;
  const calling = loadPresent === true || loadPresent === 1;
  const dot     = active ? "on" : (calling ? "calling" : "off");
  const label   = active
    ? (calling ? `On <span style="color:#b45309;font-size:10px;font-weight:600;">● Calling</span>` : "On")
    : (calling ? `<span style="color:#b45309;font-weight:600;">Calling</span>` : "Off");
  return `<span class="relay-dot ${dot}"></span>${label}`;
}
async function requestHealthCheck(uid, deviceId) {
  // Set _restart env var to force Notecard restart → new session → _session.qo fires
  setStatus("sending", "Requesting health check — restarting Notecard...");
  try {
    const res = await fetch(`${PROXY_URL}env`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        deviceUID: uid,
        environment_variables: { _restart: String(Math.floor(Date.now()/1000)) }
      })
    });
    if (res.ok) {
      setStatus("ready", "Health check requested — device will restart on next sync and send fresh health data.");
      // Clear the restart flag after 30 seconds
      setTimeout(async () => {
        await fetch(`${PROXY_URL}env`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            deviceUID: uid,
            environment_variables: { _restart: "" }
          })
        });
      }, 30000);
    } else {
      const err = await res.text();
      setStatus("error", `Health check failed: ${err}`);
    }
  } catch(e) {
    setStatus("error", `Network error: ${e.message}`);
  }
}

async function loadLatestDevice(deviceId) {
  const device    = DEVICES.find(d => d.id === deviceId);
  const container = document.getElementById(`data-fields-${deviceId}`);
  const tsEl      = document.getElementById(`data-ts-${deviceId}`);
  if (!container || !device) return;  // EV/battery/generator devices don't have data tiles
  container.innerHTML = `<div class="data-empty">Loading...</div>`;
  try {
    const rows = await supabaseGet(`device_readings?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`);
    if (!rows || rows.length === 0) { container.innerHTML = `<div class="data-empty">No data yet</div>`; tsEl.textContent = ""; return; }
    const r = rows[0];
    // Badge: green only if within ONLINE_THRESHOLD_MS (same logic as status table)
    const lastSeen = r.recorded_at ? new Date(r.recorded_at) : null;
    const isOnlineNow = lastSeen && (Date.now() - lastSeen.getTime()) < ONLINE_THRESHOLD_MS;
    const badgeEl = document.getElementById(`badge-${deviceId}`);
    if (badgeEl) {
      badgeEl.classList.toggle("online", isOnlineNow);
      badgeEl.title = lastSeen ? `Last seen: ${lastSeen.toLocaleString()}` : "No data";
    }

    // Check for active event for this device
    const now = new Date();
    const lookback = new Date(now - 24*60*60*1000).toISOString();
    const activeEvents = await supabaseGet(
      `schedule_queue?status=not.eq.cancelled&target_id=eq.${encodeURIComponent(device.uid)}&fire_at=gte.${lookback}&order=fire_at.desc&limit=5`
    );
    let activeEventPill = "";
    if (Array.isArray(activeEvents)) {
      const active = activeEvents.find(q => {
        const fireAt  = new Date(q.fire_at);
        const endAt   = new Date(fireAt.getTime() + ((q.duration_minutes||240)*60*1000));
        return fireAt <= now && endAt > now;
      });
      if (active) {
        const endAt   = new Date(new Date(active.fire_at).getTime() + ((active.duration_minutes||0)*60*1000));
        const endStr  = endAt.toLocaleTimeString("en-US", {hour:"numeric",minute:"2-digit"});
        const qData   = encodeURIComponent(JSON.stringify({type:"queue",item:active}));
        activeEventPill = `<div style="margin-bottom:8px;">
          <span class="event-pill started" onclick="showEventDetail(JSON.parse(decodeURIComponent('${qData}')))"
            style="display:inline-flex;align-items:center;gap:6px;cursor:pointer;">
            🟢 Active: ${active.name || active.target_name} &bull; ends ${endStr}
          </span>
        </div>`;
      }
    }

    container.innerHTML = activeEventPill + `<div class="data-fields">
      <div class="data-field"><span class="data-field-name">Relay 1</span><span class="data-field-value">${relayDot(r.relay_status_r1, r.load_present_r1)}</span></div>
      <div class="data-field"><span class="data-field-name">Relay 2</span><span class="data-field-value">${relayDot(r.relay_status_r2, r.load_present_r2)}</span></div>
      <div class="data-field"><span class="data-field-name">Relay 3</span><span class="data-field-value">${relayDot(r.relay_status_r3, r.load_present_r3)}</span></div>
      <div class="data-field"><span class="data-field-name">Relay 4</span><span class="data-field-value">${relayDot(r.relay_status_r4, r.load_present_r4)}</span></div>
      <div class="data-field"><span class="data-field-name">Voltage</span><span class="data-field-value">${r.voltage ? (r.voltage/10).toFixed(1) + " V" : "—"}</span></div>
      <div class="data-field"><span class="data-field-name">Current</span><span class="data-field-value">${r.current ? (r.current/10).toFixed(1) + " A" : "—"}</span></div>
      <div class="data-field"><span class="data-field-name">Watts</span><span class="data-field-value">${r.watts_consumed ? r.watts_consumed + " W" : "—"}</span></div>
      <div class="data-field"><span class="data-field-name">Comfort</span><span class="data-field-value">${r.customer_comfort > 0 ? "On" : "Off"}</span></div>
      <div class="data-field"><span class="data-field-name">Location</span><span class="data-field-value">${r.location ?? "—"}</span></div>
    </div>`;
    tsEl.textContent = `Last updated: ${new Date(r.recorded_at).toLocaleString()}`;

    // Sync load calling badges — show whenever load is present, relay open or closed.
    // Bit 3 (0x08) = relay active; bit 0 (0x01) = load calling.
    if (device.sensing_capable) {
      [1,2,3,4].forEach(n => {
        const badge = document.getElementById(`lcbadge-${deviceId}-${n}`);
        if (!badge) return;
        const statusByte = r[`relay_status_r${n}`] ?? 0;
        const calling = r[`load_present_r${n}`] === true || r[`load_present_r${n}`] === 1 || (statusByte & 0x01) !== 0;
        badge.style.display = calling ? "" : "none";
      });
    }

    // Load health data - use device_readings SW/SQ as primary, device_health for voltage/temp
    const healthEl = document.getElementById(`health-strip-${deviceId}`);
    if (healthEl) {
      try {
        // Get most recent session.begin row (has full signal data)
        // Fall back to most recent any row if no signal data available
        let hRows = await supabaseGet(
          `device_health?device_uid=eq.${encodeURIComponent(device.uid)}&rsrp=not.is.null&order=recorded_at.desc&limit=1`
        );
        if (!Array.isArray(hRows) || hRows.length === 0) {
          hRows = await supabaseGet(
            `device_health?device_uid=eq.${encodeURIComponent(device.uid)}&order=recorded_at.desc&limit=1`
          );
        }
        // Merge: prefer device_health for voltage/temp/firmware, use bubble-up for signal
        const h = (Array.isArray(hRows) && hRows.length > 0) ? {
          ...hRows[0],
          // Override signal values with latest bubble-up if available
          rsrp: hRows[0].rsrp,
          rsrq: hRows[0].rsrq,
          bars: hRows[0].bars,
          // Add SW/SQ from current bubble-up reading
          sw_value: r.sw_value,
          sq_value: r.sq_value
        } : {
          // No device_health yet - use what we can from bubble-up
          rsrp: null, rsrq: null, bars: null,
          voltage: null, temperature: null,
          firmware_version: null, orientation: null,
          moved: null, location: r.location,
          sw_value: r.sw_value, sq_value: r.sq_value,
          recorded_at: r.recorded_at
        };
        if (true) {
          const volt = h.voltage ? parseFloat(h.voltage) : null;
          const temp = h.temperature ? parseFloat(h.temperature) : null;
          const rsrp = h.rsrp ? parseInt(h.rsrp) : null;
          const bars = h.bars ? parseInt(h.bars) : null;

          const voltColor  = !volt ? "" : volt >= 3.6 ? "health-good" : volt >= 3.3 ? "health-warn" : "health-bad";
          const tempColor  = !temp ? "" : temp <= 60 ? "health-good" : temp <= 75 ? "health-warn" : "health-bad";
          const rsrpColor  = !rsrp ? "" : rsrp >= -90 ? "health-good" : rsrp >= -105 ? "health-warn" : "health-bad";
          const barsHtml   = [1,2,3,4,5].map(b =>
            `<div class="signal-bar ${bars && bars >= b ? "active" : ""}" style="height:${b*3}px;"></div>`
          ).join("");
          const movedAgo   = h.moved ? Math.round((Date.now()/1000 - parseInt(h.moved))/86400) : null;
          const movedStr   = movedAgo !== null ? (movedAgo < 1 ? "Today" : movedAgo + "d ago") : "—";
          const movedColor = movedAgo !== null && movedAgo < 1 ? "health-warn" : "health-good";
          const fwShort    = h.firmware_version ? h.firmware_version.replace("notecard-u5-","v") : "—";
          const ratStr     = h.rat ? h.rat.toUpperCase() : "—";
          const voltStr    = volt ? volt.toFixed(3)+"V" : "—";
          const tempStr    = temp ? temp.toFixed(1)+"°C" : "—";
          const signalStr  = rsrp ? rsrp+"dBm" : (h.sw_value ?? "—");
          const qualStr    = h.rsrq ? h.rsrq+"dB" : (h.sq_value ?? "—");

          healthEl.innerHTML =
            `<div class="health-strip">
              <div class="health-item"><div class="health-label">Voltage</div><div class="health-value ${voltColor}">${voltStr}</div></div>
              <div class="health-item"><div class="health-label">Temp</div><div class="health-value ${tempColor}">${tempStr}</div></div>
              <div class="health-item"><div class="health-label">Signal</div><div class="health-value"><div class="signal-bars">${barsHtml}</div></div></div>
              <div class="health-item"><div class="health-label">${rsrp ? "RSRP" : "SW"}</div><div class="health-value ${rsrpColor}">${signalStr}</div></div>
              <div class="health-item"><div class="health-label">${h.rsrq ? "RSRQ" : "SQ"}</div><div class="health-value">${qualStr}</div></div>
              <div class="health-item"><div class="health-label">RAT</div><div class="health-value" style="font-size:10px;">${ratStr}</div></div>
              <div class="health-item"><div class="health-label">Moved</div><div class="health-value ${movedColor}">${movedStr}</div></div>
              <div class="health-item"><div class="health-label">Firmware</div><div class="health-value" style="font-size:10px;">${fwShort}</div></div>
            </div>
            <div style="font-size:10px;color:var(--text-hint);margin-top:2px;">
              📍 ${h.location || "—"} &bull; 🕐 ${new Date(h.recorded_at).toLocaleString()}
            </div>`;
        } else {
          // Only show "no data" message if strip is currently empty
          if (!healthEl.innerHTML.includes('health-strip')) {
            healthEl.innerHTML = `<div style="font-size:11px;color:var(--text-hint);padding:6px 0;">SW=${r.sw_value ?? "—"} SQ=${r.sq_value ?? "—"} &bull; No health data yet — click 🩺 Health Check</div>`;
          }
        }
      } catch(e) { console.error("Health load error:", e); }
    }

  } catch(e) { container.innerHTML = `<div class="data-empty">Error loading data</div>`; }
}
async function loadLatest() { DEVICES.forEach(d => loadLatestDevice(d.id)); }
function onHistoryRangeChange() {
  const val     = document.getElementById("history-range")?.value;
  const custom  = document.getElementById("history-custom-range");
  if (custom) custom.style.display = val === "custom" ? "flex" : "none";
  // Default custom dates to last 7 days if not already set
  if (val === "custom") {
    const today  = new Date().toISOString().split("T")[0];
    const prior  = new Date(Date.now() - 7*24*60*60*1000).toISOString().split("T")[0];
    const fromEl = document.getElementById("history-from-date");
    const toEl   = document.getElementById("history-to-date");
    if (fromEl && !fromEl.value) fromEl.value = prior;
    if (toEl   && !toEl.value)   toEl.value   = today;
  }
}

function buildHistoryQuery(baseTable, limit) {
  const deviceFilter = document.getElementById("history-device-select")?.value;
  const rangeVal     = document.getElementById("history-range")?.value;
  const fromDate     = document.getElementById("history-from-date")?.value;
  const toDate       = document.getElementById("history-to-date")?.value;

  let query = `${baseTable}?order=recorded_at.desc&limit=${limit}`;
  if (deviceFilter) query += `&device_uid=eq.${encodeURIComponent(deviceFilter)}`;

  if (rangeVal === "custom") {
    if (fromDate) query += `&recorded_at=gte.${fromDate}T00:00:00.000Z`;
    if (toDate)   query += `&recorded_at=lte.${toDate}T23:59:59.999Z`;
  } else if (rangeVal) {
    const since = new Date(Date.now() - parseInt(rangeVal) * 60 * 60 * 1000).toISOString();
    query += `&recorded_at=gte.${since}`;
  }
  return query;
}

async function loadHistory() {
  const tbody    = document.getElementById("history-body");
  const limitEl  = document.getElementById("history-limit");
  const maxRows  = parseInt(limitEl?.value || "1000");
  tbody.innerHTML = `<tr><td colspan="10" class="no-data">Loading… (fetching in pages, please wait)</td></tr>`;
  try {
    // Strip any limit= from the query — pagination handles the ceiling
    const query = buildHistoryQuery("device_readings", maxRows).replace(/&limit=\d+/, "");
    const rows  = await supabaseGetPaged(query, maxRows, 1000);
    if (!rows || rows.length === 0) {
      tbody.innerHTML = `<tr><td colspan="10" class="no-data">No history found for the selected range</td></tr>`;
      return;
    }
    const capWarning = rows.length >= maxRows
      ? `<tr><td colspan="10" style="padding:6px 10px;font-size:10px;color:var(--amber);background:var(--amber-bg);text-align:center;font-family:monospace;">
           ⚠ Result capped at ${maxRows.toLocaleString()} rows — increase the row limit or narrow the date range to see all records
         </td></tr>`
      : `<tr><td colspan="10" style="padding:4px 10px;font-size:10px;color:var(--text-hint);background:var(--surface2);text-align:right;font-family:monospace;">
           ${rows.length.toLocaleString()} records — oldest: ${new Date(rows[rows.length-1].recorded_at).toLocaleString()}
         </td></tr>`;
    tbody.innerHTML = capWarning + rows.map(r => {
      const devName = DEVICES.find(d => d.uid === r.device_uid)?.name ?? unitName(r.device_uid);
      return `<tr>
        <td>${new Date(r.recorded_at).toLocaleString()}</td><td>${devName}</td>
        <td>${relayDot(r.relay_status_r1, r.load_present_r1)}</td>
        <td>${relayDot(r.relay_status_r2, r.load_present_r2)}</td>
        <td>${relayDot(r.relay_status_r3, r.load_present_r3)}</td>
        <td>${relayDot(r.relay_status_r4, r.load_present_r4)}</td>
        <td>${r.voltage       != null ? (r.voltage/10).toFixed(1)+"V"        : "—"}</td>
        <td>${r.current       != null ? (r.current/10).toFixed(1)+"A"        : "—"}</td>
        <td>${r.watts_consumed != null ? r.watts_consumed+"W"                 : "—"}</td>
        <td>${r.customer_comfort > 0 ? "On" : "Off"}</td>
      </tr>`;
    }).join("");
  } catch(e) {
    tbody.innerHTML = `<tr><td colspan="10" class="no-data">Error loading history: ${e.message}</td></tr>`;
    console.error("loadHistory:", e);
  }
}

