async function loadDeviceManagement() {
  const list = document.getElementById("device-mgmt-list");
  if (!list) return;
  list.innerHTML = '<div class="sched-empty">Loading...</div>';
  try {
    const rows = await supabaseGet("devices?order=id.asc");
    if (!Array.isArray(rows) || rows.length === 0) {
      list.innerHTML = '<div class="sched-empty">No devices registered yet.</div>';
      return;
    }
    list.innerHTML = `
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr>
          <th style="text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Name</th>
          <th style="text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Device UID</th>
          <th style="text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Device ID</th>
          <th style="text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Status</th>
          <th style="text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Added</th>
          <th style="text-align:left;padding:8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Actions</th>
        </tr></thead>
        <tbody>${rows.map(r => `
          <tr>
            <td style="padding:8px;border-bottom:0.5px solid var(--border);font-weight:600;">${r.name}</td>
            <td style="padding:8px;border-bottom:0.5px solid var(--border);font-family:monospace;font-size:11px;">${r.uid}</td>
            <td style="padding:8px;border-bottom:0.5px solid var(--border);font-family:monospace;font-size:11px;color:var(--text-hint);">${r.device_id}</td>
            <td style="padding:8px;border-bottom:0.5px solid var(--border);">
              <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
                <input type="checkbox" ${r.enabled ? "checked" : ""}
                  onchange="toggleDeviceEnabled(${r.id}, this.checked, '${r.name}')" />
                <span style="font-size:11px;color:${r.enabled ? "var(--green-dark)" : "var(--text-hint)"};">
                  ${r.enabled ? "Enabled" : "Disabled"}
                </span>
              </label>
            </td>
            <td style="padding:8px;border-bottom:0.5px solid var(--border);color:var(--text-hint);font-size:11px;">
              ${r.created_at ? new Date(r.created_at).toLocaleDateString() : "—"}
            </td>
            <td style="padding:8px;border-bottom:0.5px solid var(--border);">
              <button onclick="removeDevice(${r.id}, '${r.name}')"
                style="padding:3px 10px;border-radius:4px;border:0.5px solid var(--red);background:transparent;color:var(--red);font-size:11px;cursor:pointer;">
                Remove
              </button>
            </td>
          </tr>`).join("")}
        </tbody>
      </table>`;
  } catch(e) {
    list.innerHTML = '<div class="sched-empty">Error loading devices.</div>';
    console.error("loadDeviceManagement:", e);
  }
}

async function addNewDevice() {
  const uidEl    = document.getElementById("new-device-uid");
  const nameEl   = document.getElementById("new-device-name");
  const statusEl = document.getElementById("add-device-status");
  const uid      = uidEl?.value.trim();
  let   name     = nameEl?.value.trim();

  const showStatus = (msg, ok) => {
    statusEl.textContent = msg;
    statusEl.style.color = ok ? "var(--green-dark)" : "var(--red)";
    statusEl.style.display = "block";
    if (ok) setTimeout(() => { statusEl.style.display = "none"; }, 3000);
  };

  if (!uid)  return showStatus("⚠️ Device UID is required.", false);
  if (!uid.startsWith("dev:")) return showStatus('⚠️ UID must start with "dev:"', false);

  // Auto-generate name if blank
  if (!name) name = "Unit " + uid.slice(-4);

  // Generate a device_id based on next available slot
  let existingRows = [];
  try { existingRows = await supabaseGet("devices?order=id.asc") || []; } catch(e) {}
  const nextNum  = existingRows.length + 1;
  const deviceId = "device" + nextNum;

  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/devices`, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json", "Prefer": "return=minimal"
      },
      body: JSON.stringify({ device_id: deviceId, uid, name, enabled: true })
    });
    if (!res.ok) {
      const err = await res.text();
      return showStatus(`Error: ${err}`, false);
    }
    showStatus(`✅ ${name} added successfully. Reload the page to activate.`, true);
    uidEl.value  = "";
    nameEl.value = "";
    await loadDeviceManagement();
    await loadDevicesFromDB(); // Refresh in-memory DEVICES array
  } catch(e) {
    showStatus(`Error: ${e.message}`, false);
  }
}

async function toggleDeviceEnabled(id, enabled, name) {
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/devices?id=eq.${id}`, {
      method: "PATCH",
      headers: {
        "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json", "Prefer": "return=minimal"
      },
      body: JSON.stringify({ enabled })
    });
    setStatus("ready", `${name} ${enabled ? "enabled" : "disabled"}.`);
    await loadDevicesFromDB();   // Updates DEVICES array immediately
    buildControls();             // Rebuilds device cards
    buildDataCards();            // Rebuilds data cards
    await loadDeviceManagement(); // Refreshes the admin table
  } catch(e) { console.error("toggleDeviceEnabled:", e); }
}

async function removeDevice(id, name) {
  if (!confirm(`Remove "${name}" from the dashboard? This does not delete any historical data.`)) return;
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/devices?id=eq.${id}`, {
      method: "DELETE",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
    });
    setStatus("ready", `${name} removed.`);
    await loadDevicesFromDB();
    await loadDeviceManagement();
  } catch(e) { console.error("removeDevice:", e); }
}




// ── NWS Current Conditions ────────────────────────────────────────────────────

let nwsStationId   = null;   // e.g. "KOKC"
let nwsStationName = null;   // e.g. "Oklahoma City / Will Rogers"
let nwsObsData     = null;   // latest observation properties
let nwsPollTimer   = null;   // 15-minute interval timer
const NWS_USER_AGENT = "LCP-Dashboard/2.0 (contact@yourdomain.com)"; // NWS requires User-Agent

// Step 1: Given lat/lon, find the nearest NWS observation station
async function discoverNWSStation(lat, lon) {
  // If a station is already configured (manually selected), skip auto-discovery
  if (nwsStationId) {
    console.log(`Using configured NWS station: ${nwsStationId}`);
    return true;
  }
  // Check localStorage before hitting API
  const saved = loadSavedNWSStation();
  if (saved) {
    console.log(`Restored saved NWS station: ${nwsStationId}`);
    return true;
  }
  try {
    // Point lookup — returns forecast office and observation stations URL
    const pointRes = await fetch(
      `https://api.weather.gov/points/${parseFloat(lat).toFixed(4)},${parseFloat(lon).toFixed(4)}`,
      { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
    );
    if (!pointRes.ok) throw new Error(`Points API: ${pointRes.status}`);
    const pointData = await pointRes.json();
    const stationsUrl = pointData?.properties?.observationStations;
    if (!stationsUrl) throw new Error("No observation stations URL");

    // Get nearby stations list
    const stationsRes = await fetch(stationsUrl,
      { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
    );
    if (!stationsRes.ok) throw new Error(`Stations API: ${stationsRes.status}`);
    const stationsData = await stationsRes.json();
    const firstStation = stationsData?.features?.[0];
    if (!firstStation) throw new Error("No stations found");

    nwsStationId   = firstStation.properties.stationIdentifier;
    nwsStationName = firstStation.properties.name;

    const labelEl = document.getElementById("nws-station-label");
    const shortEl = document.getElementById("nws-station-name-short");
    if (labelEl) { labelEl.title = nwsStationName; }
    if (shortEl) shortEl.textContent = nwsStationId;
    // Save discovered station
    try { localStorage.setItem(NWS_STATION_KEY, JSON.stringify({ id: nwsStationId, name: nwsStationName })); } catch(e) {}

    console.log(`NWS station discovered: ${nwsStationId} — ${nwsStationName}`);
    return true;
  } catch(e) {
    console.warn("NWS station discovery failed:", e.message);
    return false;
  }
}

// Step 2: Fetch latest observation from discovered station
async function fetchNWSObservations(manual = false) {
  if (!nwsStationId) {
    if (!wxLocationData) return;
    const ok = await discoverNWSStation(wxLocationData.lat, wxLocationData.lon);
    if (!ok) return;
  }

  const container = document.getElementById("nws-current-container");
  if (manual && container) container.innerHTML = '<div class="sched-empty">Loading current conditions...</div>';

  try {
    const res = await fetch(
      `https://api.weather.gov/stations/${nwsStationId}/observations/latest`,
      { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
    );
    if (!res.ok) throw new Error(`Observations API: ${res.status}`);
    const data = await res.json();
    nwsObsData = data?.properties;
    if (!nwsObsData) throw new Error("No observation data");

    renderNWSCurrentConditions();
    await saveNWSObservationToSupabase();

  } catch(e) {
    console.warn("NWS fetch failed:", e.message);
    if (container) container.innerHTML = `<div class="sched-empty" style="color:var(--red);">Could not load NWS conditions: ${e.message}</div>`;
  }
}

// Convert Celsius to Fahrenheit
function cToF(c) { return c == null ? null : Math.round(c * 9/5 + 32); }
// Convert m/s to mph
function msToMph(ms) { return ms == null ? null : Math.round(ms * 2.237); }
// Convert Pa to inHg
function paToInHg(pa) { return pa == null ? null : (pa * 0.0002953).toFixed(2); }
// Compute heat index (°F) — NWS formula
function heatIndex(tempF, rh) {
  if (tempF == null || rh == null || tempF < 80) return tempF;
  const hi = -42.379 + 2.04901523*tempF + 10.14333127*rh
    - 0.22475541*tempF*rh - 0.00683783*tempF*tempF
    - 0.05481717*rh*rh + 0.00122874*tempF*tempF*rh
    + 0.00085282*tempF*rh*rh - 0.00000199*tempF*tempF*rh*rh;
  return Math.round(hi);
}

function nwsWindDir(deg) {
  if (deg == null) return "—";
  const dirs = ["N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"];
  return dirs[Math.round(deg / 22.5) % 16];
}

function renderNWSCurrentConditions() {
  const container = document.getElementById("nws-current-container");
  if (!container || !nwsObsData) return;

  const p        = nwsObsData;
  const tempF    = cToF(p.temperature?.value);
  const dewF     = cToF(p.dewpoint?.value);
  const rh       = p.relativeHumidity?.value != null ? Math.round(p.relativeHumidity.value) : null;
  const windMph  = msToMph(p.windSpeed?.value);
  const windDir  = nwsWindDir(p.windDirection?.value);
  const gustMph  = msToMph(p.windGust?.value);
  const pressIn  = paToInHg(p.barometricPressure?.value);
  const visM     = p.visibility?.value;
  const visMi    = visM != null ? (visM / 1609.34).toFixed(1) : null;
  const hiF      = heatIndex(tempF, rh);
  const desc     = p.textDescription || "—";
  const obsTime  = p.timestamp ? new Date(p.timestamp).toLocaleTimeString([], { hour:"2-digit", minute:"2-digit" }) : "—";

  // Temperature color
  const tempColor = tempF == null ? "var(--text-primary)"
    : tempF >= 100 ? "#c0392b"
    : tempF >= 90  ? "#e67e22"
    : tempF >= 70  ? "#27ae60"
    : tempF >= 50  ? "#2980b9"
    : "#8e44ad";

  // Weather alerts
  let alertHtml = "";
  if (p.presentWeather?.length > 0) {
    const wx = p.presentWeather.map(w => w.rawString).filter(Boolean).join(", ");
    if (wx) alertHtml = `<div class="nws-alert"><span>⚠️</span><span>${wx}</span></div>`;
  }

  container.innerHTML = `
    ${alertHtml}
    <div class="nws-headline">
      <div class="nws-headline-temp" style="color:${tempColor};">${tempF != null ? tempF + "°" : "—"}</div>
      <div class="nws-headline-detail">
        <div class="nws-headline-desc">${desc}</div>
        <div class="nws-headline-station">${nwsStationName || nwsStationId} &bull; Observed ${obsTime}</div>
        ${hiF && hiF !== tempF ? `<div style="font-size:11px;color:var(--amber);margin-top:2px;">Feels like ${hiF}°F</div>` : ""}
      </div>
    </div>
    <div class="nws-grid">
      <div class="nws-tile"><div class="nws-tile-icon">💧</div><div class="nws-tile-value">${rh != null ? rh+"%" : "—"}</div><div class="nws-tile-label">Humidity</div></div>
      <div class="nws-tile"><div class="nws-tile-icon">🌡️</div><div class="nws-tile-value">${dewF != null ? dewF+"°" : "—"}</div><div class="nws-tile-label">Dewpoint</div></div>
      <div class="nws-tile"><div class="nws-tile-icon">💨</div><div class="nws-tile-value" style="font-size:14px;">${windMph != null ? windMph+" mph" : "—"}<br/><span style="font-size:11px;font-weight:400;">${windDir}${gustMph ? " G"+gustMph : ""}</span></div><div class="nws-tile-label">Wind</div></div>
      <div class="nws-tile"><div class="nws-tile-icon">🔵</div><div class="nws-tile-value" style="font-size:14px;">${pressIn || "—"}"</div><div class="nws-tile-label">Pressure</div></div>
      ${visMi != null ? `<div class="nws-tile"><div class="nws-tile-icon">👁️</div><div class="nws-tile-value" style="font-size:14px;">${visMi} mi</div><div class="nws-tile-label">Visibility</div></div>` : ""}
    </div>`;

  // Update last-updated label
  const updEl = document.getElementById("nws-last-updated");
  if (updEl) { updEl.textContent = `Last updated: ${new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})} &bull; Source: NOAA / NWS &bull; Station: ${nwsStationId}`; updEl.style.display = "block"; }

  // Update header if weather tab not active
  updateHeaderNWSTemp(tempF, desc);

  // Immediately seed feedValues so monitor poller has fresh data without waiting
  if (tempF != null) feedValues["nws_temp"]       = { value: tempF,             timestamp: p.timestamp||new Date().toISOString(), unit:"°F" };
  if (rh    != null) feedValues["nws_humidity"]   = { value: rh,                timestamp: p.timestamp||new Date().toISOString(), unit:"%" };
  const hi = heatIndex(tempF, rh);
  if (hi    != null) feedValues["nws_heat_index"] = { value: hi,                timestamp: p.timestamp||new Date().toISOString(), unit:"°F" };
}

function updateHeaderNWSTemp(tempF, desc) {
  const pill = document.getElementById("header-nws-current");
  const headerEl = document.getElementById("header-wx-current-temp");
  const headerDescEl = document.getElementById("header-wx-current-desc");
  if (headerEl && tempF != null) { headerEl.textContent = `${tempF}°F`; }
  if (headerDescEl && desc) { headerDescEl.textContent = desc; }
  if (pill && tempF != null) { pill.style.display = "inline-flex"; }
}

// Save 15-minute observation snapshot to Supabase
async function saveNWSObservationToSupabase() {
  if (!nwsObsData || !wxLocationData) return;
  // Don't attempt save without a valid session — avoids JWT expired errors
  if (!currentSession?.access_token) return;
  const p = nwsObsData;
  const record = {
    station_id:   nwsStationId,
    station_name: nwsStationName,
    location_name: wxLocationData.name,
    lat:          wxLocationData.lat,
    lon:          wxLocationData.lon,
    observed_at:  p.timestamp || new Date().toISOString(),
    recorded_at:  new Date().toISOString(),
    temp_f:       cToF(p.temperature?.value),
    dewpoint_f:   cToF(p.dewpoint?.value),
    humidity_pct: p.relativeHumidity?.value != null ? Math.round(p.relativeHumidity.value) : null,
    wind_mph:     msToMph(p.windSpeed?.value),
    wind_dir_deg: p.windDirection?.value != null ? Math.round(p.windDirection.value) : null,
    wind_gust_mph: msToMph(p.windGust?.value),
    pressure_inhg: paToInHg(p.barometricPressure?.value) ? parseFloat(paToInHg(p.barometricPressure.value)) : null,
    visibility_mi: p.visibility?.value != null ? parseFloat((p.visibility.value / 1609.34).toFixed(2)) : null,
    heat_index_f: heatIndex(cToF(p.temperature?.value), p.relativeHumidity?.value != null ? Math.round(p.relativeHumidity.value) : null),
    description:  p.textDescription || null,
    raw_station_id: nwsStationId
  };
  try {
    await supabasePost("weather_readings", record);
  } catch(e) { console.warn("NWS weather_readings save failed:", e.message); }

  // ── Also write to monitor_feed_readings ───────────────────────────────────
  // This ensures weather data is available for runtime analytics correlation
  // even when the Monitor tab is not active (NWS poller runs independently
  // every 15 min regardless of which tab is open — backup mechanism for Azure)
  const now = new Date().toISOString();
  const feedWrites = [];
  if (record.temp_f        != null) feedWrites.push({ feed_key: "nws_temp",       value: record.temp_f,        unit: "°F", recorded_at: now });
  if (record.humidity_pct  != null) feedWrites.push({ feed_key: "nws_humidity",   value: record.humidity_pct,  unit: "%",  recorded_at: now });
  if (record.heat_index_f  != null) feedWrites.push({ feed_key: "nws_heat_index", value: record.heat_index_f,  unit: "°F", recorded_at: now });
  if (record.dewpoint_f    != null) feedWrites.push({ feed_key: "nws_dewpoint",   value: record.dewpoint_f,    unit: "°F", recorded_at: now });
  if (record.wind_mph      != null) feedWrites.push({ feed_key: "nws_wind_mph",   value: record.wind_mph,      unit: "mph",recorded_at: now });
  if (record.pressure_inhg != null) feedWrites.push({ feed_key: "nws_pressure",   value: record.pressure_inhg, unit: "inHg",recorded_at: now });

  for (const fw of feedWrites) {
    try { await supabasePost("monitor_feed_readings", fw); } catch(e) {}
  }
}

// Start 15-minute NWS polling (called after location is set and on login)
function startNWSPoller() {
  if (nwsPollTimer) clearInterval(nwsPollTimer);
  // Fire immediately then every 15 minutes
  fetchNWSObservations();
  nwsPollTimer = setInterval(() => fetchNWSObservations(), 15 * 60 * 1000);
  console.log("NWS weather poller started (15 min interval)");
}

// ── Weather History Backfill ──────────────────────────────────────────────────
// Core function: fetch NWS historical observations for a time window and
// insert any that are missing from weather_readings. Idempotent — safe to
// run repeatedly; skips hours already in the DB.
//
// fromISO / toISO : ISO 8601 strings (e.g. "2026-07-01T00:00:00Z")
// opts.silent     : suppress UI updates (used by auto-backfill on login)
// opts.logEl      : element to write progress lines into
// opts.progressEl : { bar, label, pct, wrap } progress bar elements
async function backfillWeather(fromISO, toISO, opts = {}) {
  const station = nwsStationId || "KTIK";
  const { silent = false, logEl = null, progressEl = null } = opts;

  const log = (msg, color) => {
    if (silent) { console.log("[weather backfill]", msg); return; }
    if (!logEl) return;
    const line = document.createElement("div");
    line.style.color = color || "var(--text-hint)";
    line.textContent = msg;
    logEl.appendChild(line);
    logEl.scrollTop = logEl.scrollHeight;
  };

  const setProgress = (pct, label) => {
    if (silent || !progressEl) return;
    progressEl.wrap.style.display = "";
    progressEl.bar.style.width    = pct + "%";
    progressEl.label.textContent  = label;
    progressEl.pct.textContent    = Math.round(pct) + "%";
  };

  try {
    // 1. Fetch existing recorded_at timestamps in the window from Supabase
    log(`Checking existing records ${fromISO.slice(0,10)} → ${toISO.slice(0,10)}…`);
    const existingRes = await fetch(
      `${SUPABASE_URL}/rest/v1/weather_readings?recorded_at=gte.${encodeURIComponent(fromISO)}&recorded_at=lte.${encodeURIComponent(toISO)}&select=observed_at&limit=5000`,
      { headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}` } }
    );
    const existing = await existingRes.json();

    // Build a set of hours already covered (round to the hour)
    const coveredHours = new Set(
      (Array.isArray(existing) ? existing : []).map(r => {
        const d = new Date(r.observed_at || 0);
        d.setMinutes(0, 0, 0);
        return d.toISOString();
      })
    );
    log(`Found ${coveredHours.size} existing hourly observation(s) in range.`);

    // 2. Fetch NWS historical observations for the window
    setProgress(10, "Fetching NWS observations…");
    log(`Fetching NWS observations from station ${station}…`);
    const nwsUrl = `https://api.weather.gov/stations/${station}/observations?start=${encodeURIComponent(fromISO)}&end=${encodeURIComponent(toISO)}&limit=500`;
    const nwsRes = await fetch(nwsUrl, {
      headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" }
    });
    if (!nwsRes.ok) throw new Error(`NWS API returned ${nwsRes.status}`);
    const nwsData = await nwsRes.json();
    const features = nwsData?.features || [];
    log(`NWS returned ${features.length} observation(s).`);

    if (features.length === 0) {
      log("No NWS observations available for this range.", "var(--amber)");
      setProgress(100, "Done — no observations found");
      return { inserted: 0, skipped: 0 };
    }

    // 3. For each observation, check if the hour is covered; insert if not
    let inserted = 0, skipped = 0;
    for (let i = 0; i < features.length; i++) {
      const p          = features[i]?.properties;
      if (!p) continue;
      const obsTime    = p.timestamp;
      const obsHour    = new Date(obsTime);
      obsHour.setMinutes(0, 0, 0);
      const hourKey    = obsHour.toISOString();

      setProgress(10 + (i / features.length) * 85, `Processing ${obsTime?.slice(0,16) || i}…`);

      if (coveredHours.has(hourKey)) {
        skipped++;
        continue;
      }

      // Build record matching saveNWSObservationToSupabase exactly
      const record = {
        station_id:    station,
        station_name:  nwsStationName || station,
        location_name: wxLocationData?.name || null,
        lat:           wxLocationData?.lat   || null,
        lon:           wxLocationData?.lon   || null,
        observed_at:   obsTime,
        recorded_at:   new Date().toISOString(),
        temp_f:        cToF(p.temperature?.value),
        dewpoint_f:    cToF(p.dewpoint?.value),
        humidity_pct:  p.relativeHumidity?.value != null ? Math.round(p.relativeHumidity.value) : null,
        wind_mph:      msToMph(p.windSpeed?.value),
        wind_dir_deg:  p.windDirection?.value != null ? Math.round(p.windDirection.value) : null,
        wind_gust_mph: msToMph(p.windGust?.value),
        pressure_inhg: paToInHg(p.barometricPressure?.value) ? parseFloat(paToInHg(p.barometricPressure.value)) : null,
        visibility_mi: p.visibility?.value != null ? parseFloat((p.visibility.value / 1609.34).toFixed(2)) : null,
        heat_index_f:  heatIndex(cToF(p.temperature?.value), p.relativeHumidity?.value != null ? Math.round(p.relativeHumidity.value) : null),
        description:   p.textDescription || null,
        raw_station_id: station
      };

      const dbRes = await supabasePost("weather_readings", record);
      if (dbRes.ok) {
        inserted++;
        coveredHours.add(hourKey); // prevent re-insert if NWS returns same hour twice
        log(`  ✅ Inserted ${obsTime?.slice(0,16)} — ${record.temp_f}°F ${record.description || ""}`, "var(--green-dark)");

        // Also backfill monitor_feed_readings for analytics correlation
        const feedWrites = [];
        if (record.temp_f        != null) feedWrites.push({ feed_key: "nws_temp",       value: record.temp_f,        unit: "°F",  recorded_at: obsTime });
        if (record.humidity_pct  != null) feedWrites.push({ feed_key: "nws_humidity",   value: record.humidity_pct,  unit: "%",   recorded_at: obsTime });
        if (record.heat_index_f  != null) feedWrites.push({ feed_key: "nws_heat_index", value: record.heat_index_f,  unit: "°F",  recorded_at: obsTime });
        if (record.dewpoint_f    != null) feedWrites.push({ feed_key: "nws_dewpoint",   value: record.dewpoint_f,    unit: "°F",  recorded_at: obsTime });
        if (record.wind_mph      != null) feedWrites.push({ feed_key: "nws_wind_mph",   value: record.wind_mph,      unit: "mph", recorded_at: obsTime });
        if (record.pressure_inhg != null) feedWrites.push({ feed_key: "nws_pressure",   value: record.pressure_inhg, unit: "inHg",recorded_at: obsTime });
        for (const fw of feedWrites) {
          try { await supabasePost("monitor_feed_readings", fw); } catch(e) {}
        }
      } else {
        log(`  ⚠ Failed to insert ${obsTime?.slice(0,16)}: ${await dbRes.text()}`, "var(--amber)");
      }
    }

    setProgress(100, "Complete");
    const summary = `Done — ${inserted} inserted, ${skipped} already existed.`;
    log(summary, inserted > 0 ? "var(--green-dark)" : "var(--text-hint)");
    return { inserted, skipped };

  } catch(e) {
    log(`❌ Backfill error: ${e.message}`, "var(--red)");
    console.error("backfillWeather:", e);
    return { inserted: 0, skipped: 0, error: e.message };
  }
}

// Manual backfill — called from the Weather tab UI button
async function runWeatherBackfill() {
  const fromEl  = document.getElementById("backfill-from");
  const toEl    = document.getElementById("backfill-to");
  const logEl   = document.getElementById("backfill-log");
  const btn     = document.getElementById("backfill-btn");
  const progWrap = document.getElementById("backfill-progress");
  const progBar  = document.getElementById("backfill-progress-bar");
  const progLbl  = document.getElementById("backfill-progress-label");
  const progPct  = document.getElementById("backfill-progress-pct");

  if (!fromEl?.value || !toEl?.value) {
    if (logEl) logEl.textContent = "⚠ Please select both a From and To date.";
    return;
  }

  // Enforce 7-day max
  const fromD = new Date(fromEl.value);
  const toD   = new Date(toEl.value + "T23:59:59Z");
  const diffDays = (toD - fromD) / (1000 * 60 * 60 * 24);
  if (diffDays > 7) {
    if (logEl) logEl.textContent = "⚠ Range cannot exceed 7 days. Please narrow the selection.";
    return;
  }
  if (fromD > toD) {
    if (logEl) logEl.textContent = "⚠ From date must be before To date.";
    return;
  }

  btn.disabled    = true;
  btn.textContent = "Working…";
  if (logEl) { logEl.textContent = ""; }

  const fromISO = fromEl.value + "T00:00:00Z";
  const toISO   = toEl.value   + "T23:59:59Z";

  await backfillWeather(fromISO, toISO, {
    silent:     false,
    logEl,
    progressEl: { wrap: progWrap, bar: progBar, label: progLbl, pct: progPct }
  });

  btn.disabled    = false;
  btn.textContent = "⬇ Backfill";
}

// Auto-backfill on login — silently fills last 48 hours of gaps
async function autoBackfillWeather() {
  if (!currentSession?.access_token) return;
  const statusEl = document.getElementById("backfill-auto-status");
  if (statusEl) statusEl.textContent = "Auto-filling last 48 hrs…";
  const toISO   = new Date().toISOString();
  const fromISO = new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString();
  const result  = await backfillWeather(fromISO, toISO, { silent: true });
  if (statusEl) {
    statusEl.textContent = result.error
      ? "Auto-fill failed"
      : result.inserted > 0
        ? `Auto-filled ${result.inserted} missing observation(s)`
        : "Weather data up to date";
    setTimeout(() => { if (statusEl) statusEl.textContent = ""; }, 8000);
  }
  console.log("Auto weather backfill:", result);
}

function stopNWSPoller() {
  if (nwsPollTimer) { clearInterval(nwsPollTimer); nwsPollTimer = null; }
}


// ── NWS Station Configuration ─────────────────────────────────────────────────

const NWS_STATION_KEY = "lcp_nws_station_v1";

function toggleStationConfig() {
  const el = document.getElementById("nws-station-config");
  if (!el) return;
  const isOpen = el.style.display !== "none";
  el.style.display = isOpen ? "none" : "block";
  if (!isOpen) {
    // Pre-fill with current station
    const inp = document.getElementById("nws-station-search");
    if (inp && nwsStationId) inp.value = nwsStationId;
  }
}

async function searchNWSStations() {
  const inp     = document.getElementById("nws-station-search");
  const results = document.getElementById("nws-station-results");
  const query   = inp?.value?.trim().toUpperCase();
  if (!query || !results) return;

  results.innerHTML = '<span style="color:var(--text-hint)">Searching...</span>';

  // If it looks like a direct station ID (4 chars, starts with K or P)
  if (/^[KP][A-Z0-9]{3}$/.test(query)) {
    await setNWSStationById(query);
    return;
  }

  // Otherwise search by text using NWS stations API with location from current lat/lon
  if (!wxLocationData) {
    results.innerHTML = '<span style="color:var(--red)">Set a location first using the forecast card below.</span>';
    return;
  }

  try {
    const pointRes = await fetch(
      `https://api.weather.gov/points/${wxLocationData.lat},${wxLocationData.lon}`,
      { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
    );
    const pointData = await pointRes.json();
    const stationsUrl = pointData?.properties?.observationStations;
    if (!stationsUrl) throw new Error("Cannot find stations for this location");

    const stationsRes = await fetch(stationsUrl,
      { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
    );
    const stationsData = await stationsRes.json();
    const features = stationsData?.features || [];

    // Filter by query text
    const filtered = features.filter(f => {
      const id   = f.properties.stationIdentifier?.toUpperCase() || "";
      const name = f.properties.name?.toUpperCase() || "";
      return id.includes(query) || name.includes(query) || features.indexOf(f) < 8;
    }).slice(0, 8);

    if (!filtered.length) {
      results.innerHTML = '<span style="color:var(--red)">No matching stations found near your location.</span>';
      return;
    }

    results.innerHTML = filtered.map(f => {
      const id   = f.properties.stationIdentifier;
      const name = f.properties.name;
      const elev = f.properties.elevation?.value != null
        ? `${Math.round(f.properties.elevation.value * 3.281)} ft`
        : "";
      const isActive = id === nwsStationId;
      return `<div style="display:flex;align-items:center;justify-content:space-between;padding:7px 10px;
        border-radius:var(--radius-sm);margin-bottom:4px;
        background:${isActive ? "var(--green-bg)" : "var(--surface)"};
        border:0.5px solid ${isActive ? "var(--green)" : "var(--border)"};">
        <div>
          <span style="font-family:monospace;font-weight:600;font-size:12px;color:${isActive ? "var(--green-dark)" : "var(--text-primary)"};">${id}</span>
          <span style="font-size:11px;color:var(--text-secondary);margin-left:8px;">${name}</span>
          ${elev ? `<span style="font-size:10px;color:var(--text-hint);margin-left:6px;">${elev}</span>` : ""}
          ${isActive ? ' <span style="font-size:10px;color:var(--green-dark);margin-left:6px;">&#10003; Active</span>' : ""}
        </div>
        <button onclick="selectNWSStation('${id}','${name.replace(/'/g,"\'")}')"
          style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--border-md);background:${isActive ? "var(--green-dark)" : "var(--surface2)"};color:${isActive ? "#fff" : "var(--text-secondary)"};font-size:11px;cursor:pointer;">
          ${isActive ? "Selected" : "Use This"}
        </button>
      </div>`;
    }).join("");

  } catch(e) {
    results.innerHTML = `<span style="color:var(--red)">${e.message}</span>`;
  }
}

async function setNWSStationById(stationId) {
  const results = document.getElementById("nws-station-results");
  results.innerHTML = `<span style="color:var(--text-hint)">Verifying ${stationId}...</span>`;
  try {
    const res = await fetch(
      `https://api.weather.gov/stations/${stationId}`,
      { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
    );
    if (!res.ok) throw new Error(`Station ${stationId} not found (${res.status})`);
    const data = await res.json();
    const name = data?.properties?.name || stationId;
    selectNWSStation(stationId, name);
  } catch(e) {
    results.innerHTML = `<span style="color:var(--red)">${e.message}</span>`;
  }
}

function selectNWSStation(stationId, stationName) {
  nwsStationId   = stationId;
  nwsStationName = stationName;

  // Persist
  try {
    localStorage.setItem(NWS_STATION_KEY, JSON.stringify({ id: stationId, name: stationName }));
  } catch(e) {}

  // Update UI
  const labelEl = document.getElementById("nws-station-label");
  const shortEl = document.getElementById("nws-station-name-short");
  if (labelEl) labelEl.title = stationName;
  if (shortEl) shortEl.textContent = stationId;

  // Close config panel
  const configEl = document.getElementById("nws-station-config");
  if (configEl) configEl.style.display = "none";

  // Refresh observations with new station
  fetchNWSObservations(true);
  setStatus("ready", `NWS station set to ${stationId} — ${stationName}`);
}

async function rediscoverNWSStation() {
  if (!wxLocationData) {
    setStatus("error", "Set a location first.");
    return;
  }
  // Clear saved station and rediscover
  try { localStorage.removeItem(NWS_STATION_KEY); } catch(e) {}
  nwsStationId   = null;
  nwsStationName = null;
  const results = document.getElementById("nws-station-results");
  if (results) results.innerHTML = '<span style="color:var(--text-hint)">Auto-detecting nearest station...</span>';
  const ok = await discoverNWSStation(wxLocationData.lat, wxLocationData.lon);
  if (ok) {
    // Save the discovered station
    try { localStorage.setItem(NWS_STATION_KEY, JSON.stringify({ id: nwsStationId, name: nwsStationName })); } catch(e) {}
    selectNWSStation(nwsStationId, nwsStationName);
  } else {
    if (results) results.innerHTML = '<span style="color:var(--red)">Auto-detection failed. Try entering a station ID manually.</span>';
  }
}

// Load saved station on startup (called from initHeaderWeather)
function loadSavedNWSStation() {
  try {
    const saved = localStorage.getItem(NWS_STATION_KEY);
    if (saved) {
      const { id, name } = JSON.parse(saved);
      if (!id) return false;
      nwsStationId   = id;
      nwsStationName = name;
      const labelEl = document.getElementById("nws-station-label");
      const shortEl = document.getElementById("nws-station-name-short");
      if (labelEl) labelEl.title = name || id;
      if (shortEl) shortEl.textContent = id;
      console.log(`Loaded saved NWS station: ${id} — ${name}`);
      return true;
    }
  } catch(e) {}
  return false;
}

// ── Weather CSV Export ────────────────────────────────────────────────────────

async function previewWxExport() {
  const startEl = document.getElementById("wx-export-start");
  const endEl   = document.getElementById("wx-export-end");
  const preview = document.getElementById("wx-export-preview");
  if (!startEl?.value || !endEl?.value) {
    if (preview) preview.innerHTML = '<span style="color:var(--red)">Please select both start and end dates.</span>';
    return;
  }
  if (preview) preview.innerHTML = '<span style="color:var(--text-hint)">Counting records...</span>';
  try {
    const start = startEl.value + "T00:00:00";
    const end   = endEl.value   + "T23:59:59";
    const rows = await supabaseGet(
      `weather_readings?recorded_at=gte.${encodeURIComponent(start)}&recorded_at=lte.${encodeURIComponent(end)}&select=id&order=recorded_at.asc`
    );
    const count = Array.isArray(rows) ? rows.length : 0;
    const days  = Math.round((new Date(endEl.value) - new Date(startEl.value)) / 86400000) + 1;
    if (preview) {
      preview.innerHTML = count > 0
        ? `<span style="color:var(--green-dark)">&#10003; ${count.toLocaleString()} records found over ${days} day${days!==1?"s":""} &bull; Approx ${(count * 0.15).toFixed(1)} hours of data</span>`
        : `<span style="color:var(--amber)">No records found for this date range. Data is recorded every 15 minutes when a location is set.</span>`;
    }
  } catch(e) {
    if (preview) preview.innerHTML = `<span style="color:var(--red)">Error: ${e.message}</span>`;
  }
}

async function exportWeatherCSV() {
  const startEl = document.getElementById("wx-export-start");
  const endEl   = document.getElementById("wx-export-end");
  const preview = document.getElementById("wx-export-preview");

  if (!startEl?.value || !endEl?.value) {
    if (preview) preview.innerHTML = '<span style="color:var(--red)">Please select both start and end dates.</span>';
    return;
  }

  if (preview) preview.innerHTML = '<span style="color:var(--text-hint)">Fetching data...</span>';

  try {
    const start = startEl.value + "T00:00:00";
    const end   = endEl.value   + "T23:59:59";

    // Fetch all records — Supabase default limit is 1000, use range header for more
    const rows = await supabaseGet(
      `weather_readings?recorded_at=gte.${encodeURIComponent(start)}&recorded_at=lte.${encodeURIComponent(end)}&order=recorded_at.asc&limit=10000`
    );

    if (!Array.isArray(rows) || !rows.length) {
      if (preview) preview.innerHTML = '<span style="color:var(--amber)">No data found for this date range.</span>';
      return;
    }

    // Build CSV
    const headers = [
      "recorded_at","observed_at","station_id","station_name","location_name",
      "lat","lon","temp_f","dewpoint_f","humidity_pct","heat_index_f",
      "wind_mph","wind_dir_deg","wind_gust_mph","pressure_inhg","visibility_mi","description"
    ];

    const escape = (v) => {
      if (v == null) return "";
      const s = String(v);
      return s.includes(",") || s.includes('"') || s.includes("\n") ? `"${s.replace(/"/g,'""')}"` : s;
    };

    const csvRows = [
      headers.join(","),
      ...rows.map(r => headers.map(h => escape(r[h])).join(","))
    ];

    const csv  = csvRows.join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement("a");
    const station = (nwsStationId || "weather").toLowerCase();
    a.href     = url;
    a.download = `weather_${station}_${startEl.value}_to_${endEl.value}.csv`;
    a.click();
    URL.revokeObjectURL(url);

    if (preview) preview.innerHTML = `<span style="color:var(--green-dark)">&#10003; Exported ${rows.length.toLocaleString()} records to CSV.</span>`;

  } catch(e) {
    if (preview) preview.innerHTML = `<span style="color:var(--red)">Export failed: ${e.message}</span>`;
  }
}

// Set default export date range to last 7 days
function initWxExportDates() {
  const endEl   = document.getElementById("wx-export-end");
  const startEl = document.getElementById("wx-export-start");
  if (!endEl || !startEl) return;
  const today = new Date();
  const week  = new Date(today);
  week.setDate(today.getDate() - 7);
  endEl.value   = today.toISOString().slice(0, 10);
  startEl.value = week.toISOString().slice(0, 10);
}


// ── Chart Resize Handler ───────────────────────────────────────────────────────
// Handles browser zoom changes which don't always fire window resize
(function() {
  let resizeTimer;
  function resizeAllCharts() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      Object.values(chartInstances).forEach(chart => {
        try { chart.resize(); } catch(e) {}
      });
    }, 150);
  }
  window.addEventListener("resize", resizeAllCharts);
  // Also observe the main content area for size changes (zoom)
  if (typeof ResizeObserver !== "undefined") {
    const ro = new ResizeObserver(resizeAllCharts);
    const target = document.querySelector(".scroll-content") || document.body;
    ro.observe(target);
  }
})();


