// ── Init ───────────────────────────────────────────────────────────────────────
async function initMonitorTriggers() {
  // Auto-fill coords from current weather location
  const coordEl = document.getElementById("fd-coords");
  if (coordEl && wxLocationData && !coordEl.value) {
    coordEl.value = `${wxLocationData.lat},${wxLocationData.lon}`;
  }
  await loadActiveFeeds();
  await loadRules();
  await loadTriggerLog();
  if (!monitorPoller) startMonitorPoller();
}

// ── Feed Discovery ─────────────────────────────────────────────────────────────
async function runFeedDiscovery() {
  const state   = document.getElementById("fd-state")?.value;
  const utility = document.getElementById("fd-utility")?.value?.trim();
  const coords  = document.getElementById("fd-coords")?.value?.trim();
  const results = document.getElementById("fd-results");
  if (!state) { results.innerHTML = '<div style="color:var(--red);font-size:12px;">Please select a state.</div>'; return; }

  results.innerHTML = '<div style="font-size:12px;color:var(--text-hint);padding:8px 0;">&#128269; Discovering available feeds for ' + state + '...</div>';

  const isoInfo   = STATE_ISO_MAP[state];
  const isoFeeds  = isoInfo?.feeds || [];
  const weatherFeeds = ["nws_temp","nws_humidity","nws_heat_index","openmeteo_uv","openmeteo_temp_forecast","tou_peak"];

  const allFeedKeys = [...new Set([...isoFeeds, ...weatherFeeds])];

  // Test each feed live
  const tested = await Promise.all(allFeedKeys.map(async key => {
    const def = FEED_DEFS[key];
    if (!def) return null;
    let status = "live";
    let latency = null;
    if (def.auth === "registration") {
      status = "registration";
    } else if (def.testUrl) {
      try {
        const t0 = Date.now();
        const res = await fetch(def.testUrl, { method:"HEAD", signal: AbortSignal.timeout(3000) });
        latency = Date.now() - t0;
        status = res.ok ? "live" : "unavailable";
      } catch(e) {
        // HEAD might be blocked, try GET with short timeout
        try {
          const t0 = Date.now();
          const res = await fetch(def.testUrl, { signal: AbortSignal.timeout(4000) });
          latency = Date.now() - t0;
          status = res.ok ? "live" : "unavailable";
        } catch(e2) {
          status = "unavailable";
        }
      }
    } else if (key.startsWith("tou_")) {
      status = "live"; // time-based, always available
    }
    return { key, def, status, latency };
  }));

  const valid = tested.filter(Boolean);

  // Find utility portals for the state
  const stateUtilityPortals = Object.values(UTILITY_PORTALS).filter(u => u.states.includes(state));

  let html = "";

  // ISO info banner
  if (isoInfo) {
    const badgeColor = isoInfo.iso === "SERC" ? "var(--amber)" : "var(--green-dark)";
    html += `<div style="background:var(--surface2);border:0.5px solid var(--border-md);border-radius:var(--radius-sm);padding:10px 14px;margin-bottom:12px;display:flex;align-items:center;gap:10px;">
      <span style="font-size:20px;">&#128204;</span>
      <div>
        <div style="font-size:13px;font-weight:600;color:var(--text-primary);">${state} is in the <span style="color:${badgeColor};">${isoInfo.iso}</span> territory</div>
        <div style="font-size:11px;color:var(--text-hint);">${isoInfo.name}</div>
        ${isoInfo.iso === "SERC" ? '<div style="font-size:11px;color:var(--amber);margin-top:2px;">&#9888;&#65039; Southeast states are not in a public ISO market. Grid pricing data is utility-specific and not publicly available.</div>' : ""}
      </div>
    </div>`;
  }

  // Feed results
  html += `<div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;font-family:monospace;">Available Feeds (${valid.length})</div>`;

  const liveCount = valid.filter(f => f.status === "live").length;
  const regCount  = valid.filter(f => f.status === "registration").length;

  html += valid.map(f => {
    const statusLabel = f.status === "live" ? "&#9679; Live" : f.status === "registration" ? "&#9679; Requires Registration" : "&#9679; Unavailable";
    const statusColor = f.status === "live" ? "var(--green-dark)" : f.status === "registration" ? "var(--amber)" : "var(--red)";
    const alreadyAdded = monitorFeeds.some(mf => mf.feed_key === f.key);
    return `<div class="feed-card">
      <div class="feed-status-dot ${f.status === "live" ? "live" : f.status === "registration" ? "registration" : "unavailable"}"></div>
      <div class="feed-info">
        <div class="feed-name">${f.def.icon} ${f.def.label}</div>
        <div class="feed-meta">${f.def.description}</div>
        <div class="feed-meta" style="margin-top:3px;">
          <span style="color:${statusColor};font-weight:600;">${statusLabel}</span>
          ${f.latency ? ` &bull; ${f.latency}ms` : ""}
          &bull; Updates every ${f.def.interval} min
          &bull; Typical: ${f.def.typical}
        </div>
        ${f.def.auth === "registration" ? `<div style="font-size:11px;color:var(--amber);margin-top:4px;">&#128279; Requires free account — <a href="${f.def.testUrl || "#"}" target="_blank" style="color:var(--amber);">Register here</a></div>` : ""}
      </div>
      <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end;">
        ${alreadyAdded
          ? '<span style="font-size:11px;color:var(--green-dark);font-weight:600;">&#10003; Added</span>'
          : f.status !== "unavailable"
            ? `<button onclick="addFeedFromDiscovery('${f.key}')" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap;">+ Add Feed</button>`
            : '<span style="font-size:11px;color:var(--red);">Unavailable</span>'
        }
      </div>
    </div>`;
  }).join("");

  // Utility portals
  if (stateUtilityPortals.length > 0) {
    html += `<div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.06em;margin:12px 0 8px;font-family:monospace;">Utility Data Portals</div>`;
    html += stateUtilityPortals.map(u => `
      <div class="feed-card">
        <div class="feed-status-dot" style="background:var(--blue-dark);"></div>
        <div class="feed-info">
          <div class="feed-name">&#127968; ${u.name}</div>
          <div class="feed-meta">Utility-specific rate and usage data portal</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:6px;">
          <a href="${u.url}" target="_blank" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);color:var(--text-secondary);font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;">Open Portal &#8599;</a>
          ${u.dataUrl ? `<a href="${u.dataUrl}" target="_blank" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--blue);background:var(--blue-lt);color:var(--blue-dark);font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;">Rate Data &#8599;</a>` : ""}
        </div>
      </div>`).join("");
  }

  // Weather feeds note
  html += `<div style="font-size:11px;color:var(--text-hint);margin-top:10px;padding:8px 12px;background:var(--surface2);border-radius:var(--radius-sm);">
    &#127777;&#65039; <strong>Weather feeds</strong> (NWS temperature, humidity, UV index) are always available for any location at no cost. Set your location in the Weather tab to activate them.
  </div>`;

  results.innerHTML = html;
}

async function addFeedFromDiscovery(feedKey) {
  const def = FEED_DEFS[feedKey];
  if (!def) return;
  try {
    // Check if already exists to avoid duplicates
    const existing = await supabaseGet(`monitor_feeds?feed_key=eq.${encodeURIComponent(feedKey)}&limit=1`);
    if (Array.isArray(existing) && existing.length > 0) {
      setStatus("ready", `${def.label} is already in your active feeds.`);
      await loadActiveFeeds();
      return;
    }
    const res = await fetch(`${SUPABASE_URL}/rest/v1/monitor_feeds`, {
      method:"POST",
      headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type":"application/json", "Prefer":"return=representation" },
      body: JSON.stringify({ feed_key:feedKey, label:def.label, unit:def.unit, interval_minutes:def.interval, auth_required:def.auth !== "none", endpoint_url:def.testUrl||null, enabled:true, added_at:new Date().toISOString() })
    });
    if (!res.ok) {
      const err = await res.text();
      console.error("addFeedFromDiscovery error:", res.status, err);
      setStatus("error", `Failed to add feed: ${res.status}`);
      return;
    }
    setStatus("ready", `${def.label} added to active feeds.`);
    await loadActiveFeeds();
    // Refresh discovery to show "Added" badge without re-testing endpoints
    const btn = document.querySelector(`[onclick="addFeedFromDiscovery('${feedKey}')"]`);
    if (btn) btn.outerHTML = `<span style="font-size:11px;color:var(--green-dark);font-weight:600;">&#10003; Added</span>`;
  } catch(e) {
    console.error("addFeedFromDiscovery:", e);
    setStatus("error", "Failed to add feed: " + e.message);
  }
}

// ── Active Feeds ───────────────────────────────────────────────────────────────
async function loadActiveFeeds() {
  const list = document.getElementById("active-feeds-list");
  if (!list) return;
  try {
    const rows = await supabaseGet("monitor_feeds?enabled=eq.true&order=added_at.asc");
    monitorFeeds = Array.isArray(rows) ? rows : [];
    if (!monitorFeeds.length) { list.innerHTML = '<div class="sched-empty">No feeds configured. Use Feed Discovery above to add feeds.</div>'; return; }
    list.innerHTML = monitorFeeds.map(f => {
      const def  = FEED_DEFS[f.feed_key] || {};
      const fv   = feedValues[f.feed_key];
      const val  = fv ? `${fv.value} ${f.unit}` : "—";
      const ts   = fv ? new Date(fv.timestamp).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"}) : "";
      return `<div class="feed-card">
        <div class="feed-status-dot live"></div>
        <div class="feed-info">
          <div class="feed-name">${def.icon||"📡"} ${f.label}</div>
          <div class="feed-meta">Updates every ${f.interval_minutes} min${ts ? ` &bull; Last: ${ts}` : ""}</div>
        </div>
        <div style="text-align:right;">
          <div class="feed-value">${val}</div>
          <div style="display:flex;gap:4px;margin-top:4px;justify-content:flex-end;">
            <button onclick="exportFeedCSV('${f.feed_key}','${f.label}')" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--green);background:none;color:var(--green-dark);font-size:10px;cursor:pointer;">⬇ CSV</button>
            <button onclick="removeFeed(${f.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
          </div>
        </div>
      </div>`;
    }).join("");
  } catch(e) { list.innerHTML = '<div class="sched-empty">Error loading feeds.</div>'; }
}

async function removeFeed(id) {
  if (!confirm("Remove this feed? Any rules using it will be disabled.")) return;
  await fetch(`${SUPABASE_URL}/rest/v1/monitor_feeds?id=eq.${id}`, {
    method:"DELETE", headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
  });
  await loadActiveFeeds();
}

// ── Rules ──────────────────────────────────────────────────────────────────────
async function loadRules() {
  const list = document.getElementById("rules-list");
  if (!list) return;
  try {
    const rows = await supabaseGet("monitor_rules?order=created_at.asc");
    monitorRules = Array.isArray(rows) ? rows : [];
    if (!monitorRules.length) { list.innerHTML = '<div class="sched-empty">No rules configured. Click + Add Rule to create one.</div>'; return; }
    list.innerHTML = monitorRules.map(r => {
      const feed1  = FEED_DEFS[r.feed_key]  || { label:r.feed_key, unit:"" };
      const feed2  = r.feed_key2 ? FEED_DEFS[r.feed_key2] : null;
      const op1    = { gt:">", gte:"≥", lt:"<", lte:"≤", eq:"=" }[r.operator] || r.operator;
      const op2    = { gt:">", gte:"≥", lt:"<", lte:"≤", eq:"=" }[r.operator2] || "";
      const cond1  = `${feed1.label} ${op1} ${r.threshold} ${feed1.unit}`;
      const cond2  = feed2 && r.threshold2 ? ` AND ${feed2.label} ${op2} ${r.threshold2} ${feed2.unit}` : "";
      const tierColors = { alert:"var(--blue-dark)", suggest:"var(--amber)", autopilot:"var(--red)" };
      return `<div class="rule-card">
        <div class="rule-card-header">
          <div class="rule-status ${r.enabled ? "enabled" : "disabled"}"></div>
          <span class="rule-tier-badge ${r.tier}">${r.tier.toUpperCase()}</span>
          <div class="rule-condition">${r.name || cond1 + cond2}</div>
          <div style="display:flex;gap:6px;">
            <button onclick="editRule(${r.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;cursor:pointer;">Edit</button>
            <button onclick="toggleRuleEnabled(${r.id}, ${!r.enabled})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;cursor:pointer;">${r.enabled ? "Disable" : "Enable"}</button>
            <button onclick="deleteRule(${r.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:11px;cursor:pointer;">Delete</button>
          </div>
        </div>
        <div class="rule-card-body">
          <strong>Condition:</strong> ${cond1}${cond2}<br/>
          <strong>Action:</strong> ${r.relay_action || "—"} on ${r.target_name || r.target_id || "—"} &bull; Strategy ${(r.strategy_val||"").split("|")[0]} &bull; ${r.duration_mins} min<br/>
          <strong>Guards:</strong> Max ${r.max_per_day}/day &bull; ${r.min_rest_mins} min rest${r.grace_mins ? ` &bull; ${r.grace_mins} min grace` : ""}${r.blackout_start ? ` &bull; Blackout ${r.blackout_start}–${r.blackout_end}` : ""}
        </div>
      </div>`;
    }).join("");
  } catch(e) { list.innerHTML = '<div class="sched-empty">Error loading rules.</div>'; }
}

function showAddRuleModal() {
  editingRuleId = null;
  selectedTier  = null;
  document.getElementById("rule-modal-title").textContent = "New Trigger Rule";
  // Reset form
  ["rule-name","rule-threshold","rule-threshold2"].forEach(id => { const el = document.getElementById(id); if(el) el.value = ""; });
  ["rule-feed","rule-operator","rule-feed2","rule-operator2","rule-target-type","rule-target","rule-relay-action","rule-mode","rule-strategy"].forEach(id => { const el = document.getElementById(id); if(el) el.selectedIndex=0; });
  document.getElementById("rule-duration").value = "60";
  document.getElementById("rule-max-per-day").value = "3";
  document.getElementById("rule-min-rest").value = "120";
  document.getElementById("rule-grace").value = "5";
  document.getElementById("rule-blackout-start").value = "";
  document.getElementById("rule-blackout-end").value = "";
  document.getElementById("rule-use-condition2").checked = false;
  document.getElementById("rule-condition2").style.display = "none";
  document.getElementById("rule-grace-row").style.display = "none";
  document.getElementById("autopilot-warning").style.display = "none";
  if (document.getElementById("rule-action-section")) document.getElementById("rule-action-section").style.display = "none";
  if (document.getElementById("rule-notify-cancel-row")) document.getElementById("rule-notify-cancel-row").style.display = "none";
  ["tier-alert","tier-suggest","tier-autopilot"].forEach(id => document.getElementById(id)?.classList.remove("selected"));
  populateSCADARuleFeedOptions();
  document.getElementById("rule-modal").classList.add("active");
}

function closeRuleModal(e) {
  if (e && e.target !== document.getElementById("rule-modal")) return;
  document.getElementById("rule-modal").classList.remove("active");
}

function selectRuleTier(tier) {
  selectedTier = tier;
  ["tier-alert","tier-suggest","tier-autopilot"].forEach(id => document.getElementById(id)?.classList.remove("selected"));
  document.getElementById(`tier-${tier}`)?.classList.add("selected");
  const graceRow = document.getElementById("rule-grace-row");
  const apWarn   = document.getElementById("autopilot-warning");
  if (graceRow) graceRow.style.display = tier === "autopilot" ? "block" : "none";
  if (apWarn)   apWarn.style.display   = tier === "autopilot" ? "block" : "none";
  applyRuleTierVisibility(tier);
}

function onRuleFeedChange() {
  const feedKey = document.getElementById("rule-feed")?.value;
  const def = FEED_DEFS[feedKey];
  const hintEl = document.getElementById("rule-feed-hint");
  const threshEl = document.getElementById("rule-threshold-hint");
  if (def && hintEl) {
    hintEl.textContent = `${def.description} — Typical: ${def.typical}. Suggested trigger: ${def.typical_trigger} ${def.unit}`;
    hintEl.style.display = "block";
  } else if (hintEl) hintEl.style.display = "none";
  if (threshEl) threshEl.textContent = def?.unit || "";
}

function toggleCondition2() {
  const checked = document.getElementById("rule-use-condition2")?.checked;
  const el = document.getElementById("rule-condition2");
  if (el) el.style.display = checked ? "grid" : "none";
}

function onRuleTargetChange() {
  const type = document.getElementById("rule-target-type")?.value;
  const sel  = document.getElementById("rule-target");
  if (!sel || !type) return;
  sel.innerHTML = '<option value="" disabled selected>-- Choose One --</option>';
  if (type === "group") {
    Object.keys(groupNames).map(Number).sort((a,b)=>a-b).forEach(n => {
      const o   = document.createElement("option");
      o.value   = `group_${n}`;
      const tag = groupTags?.[n] ? ` — ${groupTags[n]}` : "";
      o.textContent = `Group ${n}: ${groupNames[n]||"Group "+n}${tag}`;
      sel.appendChild(o);
    });
  } else {
    const relayDevs = DEVICES.filter(d => d.type !== "ev" && !d.uid.includes("PLACEHOLDER"));
    const evDevs    = DEVICES.filter(d => d.type === "ev");
    if (relayDevs.length) {
      const grp = document.createElement("optgroup"); grp.label = "Relay Devices";
      relayDevs.forEach(d => { const o = document.createElement("option"); o.value=d.uid; o.textContent=d.name; grp.appendChild(o); });
      sel.appendChild(grp);
    }
    if (evDevs.length) {
      const grp = document.createElement("optgroup"); grp.label = "EV Chargers";
      evDevs.forEach(d => { const o = document.createElement("option"); o.value=d.uid; o.textContent="⚡ "+d.name; grp.appendChild(o); });
      sel.appendChild(grp);
    }
    const genDevs = DEVICES.filter(d => d.type === "generator");
    if (genDevs.length) {
      const grp = document.createElement("optgroup"); grp.label = "Generators";
      genDevs.forEach(d => { const o = document.createElement("option"); o.value=d.uid; o.textContent="⚡ "+d.name; grp.appendChild(o); });
      sel.appendChild(grp);
    }
  }
}

async function saveRule() {
  if (!selectedTier) { alert("Please select an action tier."); return; }
  const feedKey = document.getElementById("rule-feed")?.value;
  if (!feedKey) { alert("Please select a feed to monitor."); return; }
  const threshold = parseFloat(document.getElementById("rule-threshold")?.value);
  if (isNaN(threshold)) { alert("Please enter a threshold value."); return; }
  const targetId = document.getElementById("rule-target")?.value;
  if (!targetId && selectedTier !== "alert") { alert("Please select a target device or group."); return; }

  // Autopilot requires admin role
  if (selectedTier === "autopilot" && currentUserRole !== "administrator") {
    alert("Autopilot rules can only be created by Administrators."); return;
  }

  const useC2  = document.getElementById("rule-use-condition2")?.checked;
  const feed2  = useC2 ? document.getElementById("rule-feed2")?.value : null;
  const op2    = useC2 ? document.getElementById("rule-operator2")?.value : null;
  const thresh2= useC2 ? parseFloat(document.getElementById("rule-threshold2")?.value) : null;

  const targetType = document.getElementById("rule-target-type")?.value;
  const targetName = targetType === "group"
    ? (groupNames[parseInt(targetId.replace("group_",""))] || targetId)
    : (DEVICES.find(d => d.uid === targetId)?.name || targetId);

  const ruleEventType  = document.querySelector("#rule-event-type-tiles .rule-event-tile.selected")?.dataset?.type || "switch";
  const ruleSwitchMode = document.getElementById("rule-switch-mode")?.value || "uniform";
  const ruleHybridCfg  = ruleSwitchMode === "hybrid" ? JSON.stringify(getRuleHybridConfig()) : null;
  const ruleStratVal   = ruleEventType === "bas_di"
    ? (document.getElementById("rule-bas-strategy")?.value || "19|30|30")
    : (document.getElementById("rule-strategy")?.value || "9|15|30");

  const record = {
    tier:           selectedTier,
    name:           document.getElementById("rule-name")?.value?.trim() || null,
    feed_key:       feedKey,
    operator:       document.getElementById("rule-operator")?.value || "gt",
    threshold:      threshold,
    feed_key2:      feed2 || null,
    operator2:      op2   || null,
    threshold2:     isNaN(thresh2) ? null : thresh2,
    target_type:    targetType || null,
    target_id:      targetId   || null,
    target_name:    targetName || null,
    event_type:     ruleEventType,
    relay_action:   ruleSwitchMode === "hybrid" ? "hybrid" : (document.getElementById("rule-relay-action")?.value || "all_on"),
    mode:           document.getElementById("rule-mode")?.value || "dlc",
    strategy_val:   ruleStratVal,
    hybrid_config:  ruleHybridCfg,
    duration_mins:  parseInt(document.getElementById("rule-duration")?.value) || 60,
    max_per_day:    parseInt(document.getElementById("rule-max-per-day")?.value) || 3,
    min_rest_mins:  parseInt(document.getElementById("rule-min-rest")?.value) || 120,
    grace_mins:     selectedTier === "autopilot" ? parseInt(document.getElementById("rule-grace")?.value) || 5 : null,
    blackout_start: document.getElementById("rule-blackout-start")?.value || null,
    blackout_end:   document.getElementById("rule-blackout-end")?.value   || null,
    enabled:             true,
    notify:              document.getElementById("rule-notify-alert")?.checked !== false,
    notify_cancel_link:  document.getElementById("rule-notify-cancel-link")?.checked !== false,
    notify_message:      document.getElementById("rule-notify-message")?.value?.trim() || null,
    created_by:          currentUser?.email || null,
    created_at:          new Date().toISOString()
  };

  try {
    if (editingRuleId) {
      await fetch(`${SUPABASE_URL}/rest/v1/monitor_rules?id=eq.${editingRuleId}`, {
        method:"PATCH", headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type":"application/json", "Prefer":"return=minimal" },
        body: JSON.stringify(record)
      });
    } else {
      await supabasePost("monitor_rules", record);
    }
    closeRuleModal();
    await loadRules();
    setStatus("ready", `Rule "${record.name || feedKey}" saved.`);
  } catch(e) { console.error("saveRule:", e); setStatus("error", "Failed to save rule: " + e.message); }
}

async function editRule(id) {
  const rule = monitorRules.find(r => r.id === id);
  if (!rule) return;
  editingRuleId = id;
  showAddRuleModal();
  document.getElementById("rule-modal-title").textContent = "Edit Trigger Rule";
  setTimeout(() => {
    document.getElementById("rule-name").value      = rule.name || "";
    document.getElementById("rule-feed").value      = rule.feed_key;
    document.getElementById("rule-operator").value  = rule.operator;
    document.getElementById("rule-threshold").value = rule.threshold;
    if (rule.event_type) selectRuleEventType(rule.event_type);
    if (rule.event_type === "switch" && rule.relay_action === "hybrid") {
      document.getElementById("rule-switch-mode").value = "hybrid";
      onRuleSwitchModeChange();
      if (rule.hybrid_config) {
        try { applyRuleHybridConfig(JSON.parse(rule.hybrid_config)); } catch(e) {}
      }
    }
    if (rule.event_type === "bas_di" && rule.strategy_val) {
      setTimeout(() => { const el = document.getElementById("rule-bas-strategy"); if(el) el.value = rule.strategy_val; }, 50);
    }
    document.getElementById("rule-duration").value  = rule.duration_mins;
    document.getElementById("rule-max-per-day").value = rule.max_per_day;
    document.getElementById("rule-min-rest").value  = rule.min_rest_mins;
    if (rule.grace_mins) document.getElementById("rule-grace").value = rule.grace_mins;
    if (rule.blackout_start) document.getElementById("rule-blackout-start").value = rule.blackout_start;
    if (rule.blackout_end)   document.getElementById("rule-blackout-end").value   = rule.blackout_end;
    if (rule.feed_key2) {
      document.getElementById("rule-use-condition2").checked = true;
      document.getElementById("rule-condition2").style.display = "grid";
      document.getElementById("rule-feed2").value      = rule.feed_key2;
      document.getElementById("rule-operator2").value  = rule.operator2;
      document.getElementById("rule-threshold2").value = rule.threshold2;
    }
    selectRuleTier(rule.tier);
    applyRuleTierVisibility(rule.tier);
    onRuleFeedChange();
    onRuleTargetChange();
    setTimeout(() => {
      document.getElementById("rule-target-type").value = rule.target_type || "";
      onRuleTargetChange();
      setTimeout(() => {
        document.getElementById("rule-target").value       = rule.target_id || "";
        document.getElementById("rule-relay-action").value = rule.relay_action || "all_on";
        document.getElementById("rule-mode").value         = rule.mode || "dlc";
        document.getElementById("rule-strategy").value     = rule.strategy_val || "9|15|30";
      }, 50);
    }, 50);
  }, 50);
}

async function toggleRuleEnabled(id, enabled) {
  await fetch(`${SUPABASE_URL}/rest/v1/monitor_rules?id=eq.${id}`, {
    method:"PATCH", headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type":"application/json", "Prefer":"return=minimal" },
    body: JSON.stringify({ enabled })
  });
  await loadRules();
}

async function deleteRule(id) {
  if (!confirm("Delete this rule?")) return;
  await fetch(`${SUPABASE_URL}/rest/v1/monitor_rules?id=eq.${id}`, {
    method:"DELETE", headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
  });
  await loadRules();
}

// ── Trigger Log ────────────────────────────────────────────────────────────────
async function loadTriggerLog() {
  const list = document.getElementById("trigger-log-list");
  if (!list) return;
  try {
    const limit = parseInt(document.getElementById("trigger-log-range")?.value || "50");
    const query = limit > 0
      ? `monitor_trigger_log?order=triggered_at.desc&limit=${limit}`
      : `monitor_trigger_log?order=triggered_at.desc`;
    _triggerLogRows = [];
    const rows = await supabaseGet(query);
    if (Array.isArray(rows)) _triggerLogRows = rows;
    if (!Array.isArray(rows) || !rows.length) { list.innerHTML = '<div class="sched-empty">No trigger events yet.</div>'; return; }
    list.innerHTML = `<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">
      <thead><tr>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Time</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Rule</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Tier</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Feed Value</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Action</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Outcome</th>
      </tr></thead>
      <tbody>${rows.map(r => `<tr>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);white-space:nowrap;">${new Date(r.triggered_at).toLocaleString()}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">${r.rule_name || "—"}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);"><span class="trigger-tier ${r.tier}">${(r.tier||"").toUpperCase()}</span></td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-family:monospace;">${r.feed_value != null ? r.feed_value + " " + (r.feed_unit||"") : "—"}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">${r.action_description || "—"}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);color:${r.outcome === "fired" ? "var(--green-dark)" : r.outcome === "cancelled" ? "var(--amber)" : "var(--text-hint)"};">${r.outcome || "—"}</td>
      </tr>`).join("")}
      </tbody></table></div>`;
  } catch(e) { list.innerHTML = '<div class="sched-empty">Error loading trigger log.</div>'; }
}

// ── Monitor Poller ─────────────────────────────────────────────────────────────
function startMonitorPoller() {
  if (monitorPoller) clearInterval(monitorPoller);
  // Run immediately then every 5 minutes
  runMonitorCycle();
  monitorPoller = setInterval(runMonitorCycle, 5 * 60 * 1000);
  console.log("Monitor & Triggers poller started (5 min interval)");
}

async function runMonitorCycle() {
  if (!monitorRules.length && !monitorFeeds.length) return;

  // Collect current feed values
  await collectFeedValues();

  // Evaluate rules
  const enabledRules = monitorRules.filter(r => r.enabled);
  for (const rule of enabledRules) {
    await evaluateRule(rule);
  }

  // Update feed display if tab is active
  if (document.getElementById("tab-admin-monitor-triggers")?.classList.contains("active")) {
    loadActiveFeeds();
  }
}

async function collectFeedValues() {
  // ── NWS weather — use cached nwsObsData (relaxed age: 90 min to cover hourly obs) ──
  let nwsData = nwsObsData;

  // If no cached data or data is very old, try a fresh fetch
  if (!nwsData || !nwsData.timestamp) {
    if (nwsStationId) {
      try {
        const res = await fetch(
          `https://api.weather.gov/stations/${nwsStationId}/observations/latest`,
          { headers: { "User-Agent": NWS_USER_AGENT, "Accept": "application/json" } }
        );
        if (res.ok) {
          const d = await res.json();
          nwsData = d?.properties;
          if (nwsData) nwsObsData = nwsData; // update cache
        }
      } catch(e) { console.warn("collectFeedValues NWS fetch:", e.message); }
    }
  }

  if (nwsData) {
    // NWS stations update hourly — accept data up to 90 minutes old
    const obsAge = nwsData.timestamp
      ? (Date.now() - new Date(nwsData.timestamp).getTime()) / 60000
      : 0;
    if (obsAge < 90) {
      const p    = nwsData;
      const tempF = cToF(p.temperature?.value);
      const rh    = p.relativeHumidity?.value != null ? Math.round(p.relativeHumidity.value) : null;
      if (tempF != null) feedValues["nws_temp"]       = { value: tempF,               timestamp: p.timestamp, unit:"°F" };
      if (rh    != null) feedValues["nws_humidity"]   = { value: rh,                  timestamp: p.timestamp, unit:"%" };
      const hi = heatIndex(tempF, rh);
      if (hi   != null) feedValues["nws_heat_index"] = { value: hi,                  timestamp: p.timestamp, unit:"°F" };
    } else {
      console.warn(`NWS obs age ${Math.round(obsAge)} min — too old, skipping`);
    }
  }

  // ── Open-Meteo UV index ────────────────────────────────────────────────────
  // First try from cached wxForecastData (updated when weather tab loads)
  if (wxForecastData?.hourly) {
    const now  = new Date();
    const hour = now.getHours();
    // Try uv_index (requested in updated URL) or uv_index_instant as fallback
    const uv = wxForecastData.hourly.uv_index?.[hour]
            ?? wxForecastData.hourly.uv_index_instant?.[hour];
    if (uv != null) feedValues["openmeteo_uv"] = { value: Math.round(uv*10)/10, timestamp: now.toISOString(), unit:"" };
    // Forecast high — index 0 = today, 1 = tomorrow
    const forecastHigh = wxForecastData.daily?.temperature_2m_max?.[1];
    if (forecastHigh != null) feedValues["openmeteo_temp_forecast"] = { value: Math.round(forecastHigh), timestamp: now.toISOString(), unit:"°F" };
  }

  // If UV still not available, fetch directly from Open-Meteo
  if (feedValues["openmeteo_uv"] == null && wxLocationData) {
    try {
      const { lat, lon } = wxLocationData;
      const res = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&hourly=uv_index&forecast_days=1&timezone=auto`
      );
      if (res.ok) {
        const d = await res.json();
        const now  = new Date();
        const hour = now.getHours();
        const uv   = d?.hourly?.uv_index?.[hour];
        if (uv != null) feedValues["openmeteo_uv"] = { value: Math.round(uv*10)/10, timestamp: now.toISOString(), unit:"" };
      }
    } catch(e) { console.warn("Open-Meteo UV direct fetch:", e.message); }
  }

  // If forecast high still not available, fetch directly
  if (feedValues["openmeteo_temp_forecast"] == null && wxLocationData) {
    try {
      const { lat, lon } = wxLocationData;
      const res = await fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max&forecast_days=2&temperature_unit=fahrenheit&timezone=auto`
      );
      if (res.ok) {
        const d = await res.json();
        const high = d?.daily?.temperature_2m_max?.[1];
        if (high != null) feedValues["openmeteo_temp_forecast"] = { value: Math.round(high), timestamp: new Date().toISOString(), unit:"°F" };
      }
    } catch(e) { console.warn("Open-Meteo forecast fetch:", e.message); }
  }

  // Time-of-use — simple peak hours check (configurable later)
  const hour = new Date().getHours();
  const isPeak = (hour >= 14 && hour < 20); // 2pm-8pm typical peak
  feedValues["tou_peak"]    = { value: isPeak ? 1 : 0,  timestamp: new Date().toISOString(), unit:"" };
  feedValues["tou_offpeak"] = { value: isPeak ? 0 : 1,  timestamp: new Date().toISOString(), unit:"" };

  // SPP LMP — fetch CSV, parse first numeric LMP value
  if (monitorFeeds.some(f => f.feed_key === "spp_lmp")) {
    try {
      const res = await fetch("https://portal.spp.org/file-browser-api/download/rtbm-lmp-by-location?path=/RTBM-LMP-SL-latestInterval.csv");
      if (res.ok) {
        const text = await res.text();
        const lines = text.trim().split("\n");
        if (lines.length > 1) {
          const cols = lines[1].split(",");
          const lmp = parseFloat(cols[2]); // LMP column
          if (!isNaN(lmp)) feedValues["spp_lmp"] = { value: Math.round(lmp*100)/100, timestamp: new Date().toISOString(), unit:"$/MWh" };
        }
      }
    } catch(e) { console.warn("SPP LMP fetch:", e.message); }
  }

  // ── SCADA live data → feedValues ─────────────────────────────────────────
  // Any point in scadaLiveData gets registered as a feed value with key scada_{point_id}
  if (typeof scadaLiveData !== "undefined") {
    Object.entries(scadaLiveData).forEach(([pointId, live]) => {
      if (live.value != null) {
        feedValues[`scada_${pointId}`] = {
          value:     live.value,
          timestamp: live.timestamp || new Date().toISOString(),
          unit:      live.unit || ""
        };
      }
    });
  }

  // Save to Supabase monitor_feed_readings
  for (const [key, fv] of Object.entries(feedValues)) {
    if (fv.value == null) continue;
    try {
      await supabasePost("monitor_feed_readings", {
        feed_key: key, value: fv.value, unit: fv.unit, recorded_at: new Date().toISOString()
      });
    } catch(e) {} // silent — table might not exist yet
  }
}

function populateSCADARuleFeedOptions() {
  // Populate SCADA optgroups in rule feed selectors from configured points
  ["rule-feed-scada-group", "rule-feed2-scada-group"].forEach(groupId => {
    const grp = document.getElementById(groupId);
    if (!grp) return;
    if (typeof scadaPoints !== "undefined" && scadaPoints.length) {
      grp.innerHTML = scadaPoints.map(p =>
        `<option value="scada_${p.point_id}">${p.name} (${p.type}${p.unit ? ", " + p.unit : ""})</option>`
      ).join("");
    } else {
      grp.innerHTML = '<option disabled>No SCADA points configured</option>';
    }
  });

  // Also inject SCADA points into FEED_DEFS so hints work
  if (typeof scadaPoints !== "undefined") {
    scadaPoints.forEach(p => {
      const key = `scada_${p.point_id}`;
      if (!FEED_DEFS[key]) {
        FEED_DEFS[key] = {
          label:           p.name,
          unit:            p.unit || "",
          icon:            p.type === "analog" ? "〰" : p.type === "status" ? "⊙" : p.type === "alarm" ? "🔔" : "∑",
          interval:        15,
          testUrl:         null,
          auth:            "none",
          typical:         `${p.type} point`,
          typical_trigger: p.hi_limit || p.lo_limit || null,
          description:     `SCADA ${p.type} point — ${p.name}${p.unit ? " (" + p.unit + ")" : ""}`
        };
      }
    });
  }
}

function checkCondition(feedKey, operator, threshold) {
  const fv = feedValues[feedKey];
  if (!fv || fv.value == null) return false;
  const v = parseFloat(fv.value);
  switch(operator) {
    case "gt":  return v > threshold;
    case "gte": return v >= threshold;
    case "lt":  return v < threshold;
    case "lte": return v <= threshold;
    case "eq":  return v === threshold;
    default:    return false;
  }
}

async function evaluateRule(rule) {
  const cond1 = checkCondition(rule.feed_key, rule.operator, rule.threshold);
  const cond2 = rule.feed_key2
    ? checkCondition(rule.feed_key2, rule.operator2, rule.threshold2)
    : true;
  const triggered = cond1 && cond2;
  if (!triggered) return;

  // Guard: blackout hours
  if (rule.blackout_start && rule.blackout_end) {
    const now  = new Date();
    const hhmm = `${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
    if (hhmm >= rule.blackout_start && hhmm <= rule.blackout_end) {
      console.log(`Rule "${rule.name}" triggered but within blackout window. Skipping.`);
      return;
    }
  }

  // Guard: check recent trigger log for this rule (max per day, min rest)
  try {
    const dayAgo = new Date(Date.now() - 24*60*60*1000).toISOString();
    const recent = await supabaseGet(`monitor_trigger_log?rule_id=eq.${rule.id}&triggered_at=gte.${encodeURIComponent(dayAgo)}&order=triggered_at.desc&limit=20`);
    if (Array.isArray(recent)) {
      if (recent.length >= rule.max_per_day) {
        console.log(`Rule "${rule.name}" hit max_per_day limit. Skipping.`);
        return;
      }
      if (recent.length > 0) {
        const lastFired = new Date(recent[0].triggered_at).getTime();
        const minutesSince = (Date.now() - lastFired) / 60000;
        if (minutesSince < rule.min_rest_mins) {
          console.log(`Rule "${rule.name}" within min_rest_mins. Skipping.`);
          return;
        }
      }
    }
  } catch(e) { console.warn("Guard check failed:", e); }

  const fv = feedValues[rule.feed_key];
  const def = FEED_DEFS[rule.feed_key] || {};
  const actionDesc = `${rule.relay_action || "all_on"} on ${rule.target_name || rule.target_id} — Strategy ${(rule.strategy_val||"").split("|")[0]} — ${rule.duration_mins} min`;

  console.log(`Rule triggered: "${rule.name}" — ${def.label} = ${fv?.value} ${def.unit} — Tier: ${rule.tier}`);

  const recipients = await getAlertRecipients();
  const fvUnit  = FEED_DEFS[rule.feed_key]?.unit || "";
  const fvLabel = FEED_DEFS[rule.feed_key]?.label || rule.feed_key;
  const notify  = rule.notify !== false; // default true

  if (rule.tier === "alert") {
    await fireTrigger(rule, fv, "alert", "notified", actionDesc);
    setStatus("ready", `⚠️ Monitor Alert: ${rule.name || def.label + " threshold crossed"} — ${fv?.value} ${def.unit}`);
    if (notify) {
      await sendNotificationEmail({ recipients, rule, tier:"alert", feedValue:fv?.value, feedUnit:fvUnit, feedLabel:fvLabel, eventDesc:actionDesc, cancelToken:null, graceMins:null });
    }

  } else if (rule.tier === "suggest") {
    await fireTrigger(rule, fv, "suggest", "suggested", actionDesc);
    const token = rule.notify_cancel_link !== false ? await createCancelToken(rule.id, actionDesc, rule.grace_mins || 5) : null;
    showCancellationBanner(rule, fv, "suggest", token);
    if (notify) {
      await sendNotificationEmail({ recipients, rule, tier:"suggest", feedValue:fv?.value, feedUnit:fvUnit, feedLabel:fvLabel, eventDesc:actionDesc, cancelToken:token, graceMins:rule.grace_mins||5 });
    }

  } else if (rule.tier === "autopilot") {
    if (currentUserRole !== "administrator") return;
    if (pendingAutopilotEvents[rule.id]) return;
    const token = rule.notify_cancel_link !== false ? await createCancelToken(rule.id, actionDesc, rule.grace_mins || 5) : null;
    await fireTrigger(rule, fv, "autopilot", "pending", actionDesc);
    showCancellationBanner(rule, fv, "autopilot", token);
    if (notify) {
      await sendNotificationEmail({ recipients, rule, tier:"autopilot", feedValue:fv?.value, feedUnit:fvUnit, feedLabel:fvLabel, eventDesc:actionDesc, cancelToken:token, graceMins:rule.grace_mins||5 });
    }
    startAutopilotGrace(rule, fv);
  }
}

async function fireTrigger(rule, fv, tier, outcome, actionDesc) {
  try {
    await supabasePost("monitor_trigger_log", {
      rule_id:           rule.id,
      rule_name:         rule.name || rule.feed_key,
      tier,
      feed_key:          rule.feed_key,
      feed_value:        fv?.value,
      feed_unit:         FEED_DEFS[rule.feed_key]?.unit || "",
      action_description: actionDesc,
      outcome,
      triggered_at:      new Date().toISOString()
    });
    loadTriggerLog();
  } catch(e) { console.warn("fireTrigger log:", e); }
}

function showSuggestModal(rule, fv) {
  const def = FEED_DEFS[rule.feed_key] || {};
  const msg = `📡 Monitor Trigger: ${rule.name || def.label}\n\nCurrent value: ${fv?.value} ${def.unit}\nThreshold: ${rule.operator} ${rule.threshold} ${def.unit}\n\nSuggested action:\n${rule.relay_action} on ${rule.target_name || rule.target_id}\nStrategy ${(rule.strategy_val||"").split("|")[0]} — ${rule.duration_mins} min\n\nOpen the Event Scheduler to confirm this event?`;
  if (confirm(msg)) {
    switchMain("events", document.getElementById("main-events"));
    const histBtn = document.getElementById("sub-event-history");
    if (histBtn) switchSub("events", "event-history", histBtn);
  }
}

function startAutopilotGrace(rule, fv) {
  const graceMs = (rule.grace_mins || 5) * 60 * 1000;
  let remaining  = rule.grace_mins || 5;

  setStatus("ready", `⚡ Autopilot: "${rule.name}" firing in ${remaining} min — click to cancel`);

  const countdown = setInterval(() => {
    remaining--;
    setStatus("ready", `⚡ Autopilot: "${rule.name}" firing in ${remaining} min — click status to cancel`);
    if (remaining <= 0) clearInterval(countdown);
  }, 60000);

  const timer = setTimeout(async () => {
    clearInterval(countdown);
    delete pendingAutopilotEvents[rule.id];
    // Fire the actual event
    await fireAutopilotEvent(rule, fv);
    setStatus("ready", `⚡ Autopilot event fired: "${rule.name}"`);
  }, graceMs);

  pendingAutopilotEvents[rule.id] = { timer, countdown, rule, fv };
}

async function cancelAutopilot(ruleId) {
  const pending = pendingAutopilotEvents[ruleId];
  if (!pending) return;
  clearTimeout(pending.timer);
  clearInterval(pending.countdown);
  delete pendingAutopilotEvents[ruleId];
  // Update log entry
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/monitor_trigger_log?rule_id=eq.${ruleId}&outcome=eq.pending`, {
      method:"PATCH", headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type":"application/json" },
      body: JSON.stringify({ outcome:"cancelled" })
    });
  } catch(e) {}
  setStatus("ready", `Autopilot cancelled for rule ${ruleId}`);
  loadTriggerLog();
}

async function fireAutopilotEvent(rule, fv) {
  const evType    = rule.event_type || "switch";
  const schedUnix = Math.floor(Date.now() / 1000);
  const duration  = rule.duration_mins || 60;

  // Helper: dispatch to a single device by type
  async function dispatchToDevice(d, hex) {
    const dtype = d.type || "relay";
    if (dtype === "battery")   { if (typeof dispatchBatteryDR   === "function") await dispatchBatteryDR(rule);   return; }
    if (dtype === "generator") { if (typeof dispatchGeneratorDR  === "function") await dispatchGeneratorDR(rule);  return; }
    if (dtype === "ev")        { if (typeof dispatchEVChargersDR === "function") await dispatchEVChargersDR(parseFloat(rule?.signal_level||"0.75")); return; }
    if (dtype === "thermostat"){ if (typeof dispatchThermostatDR === "function") await dispatchThermostatDR(rule?.therm_action || "high"); return; }
    await sendLCToDevice(d.uid, hex);
  }

  // Helper: send to device or all group members routed by type
  async function sendToTarget(hex) {
    if (rule.target_type === "group") {
      const gNum    = parseInt((rule.target_id || "group_1").replace("group_",""));
      const members = DEVICES.filter(d => (groupAssignments[d.uid]||[]).includes(gNum));
      for (const d of members) await dispatchToDevice(d, hex);
    } else {
      const d = DEVICES.find(x => x.uid === rule.target_id) || { uid: rule.target_id, type:"relay" };
      await dispatchToDevice(d, hex);
    }
  }

  // ── Route by event type ───────────────────────────────────────────────────
  if (evType === "switch" && rule.relay_action === "hybrid" && rule.hybrid_config) {
    // Hybrid: send DLC and BAS commands per relay config
    try {
      const cfg = JSON.parse(rule.hybrid_config);
      for (const rel of (cfg.dlcRelays || [])) {
        const [sn,,sc] = (rel.stratVal||"9|15|30").split("|").map(Number);
        const reps = Math.max(1, Math.round(duration / (sc||30)));
        await sendToTarget(buildLCHex(rel.action, "dlc", sn, reps, schedUnix));
      }
      for (const rel of (cfg.basRelays || [])) {
        const [sn,,sc] = (rel.stratVal||"19|30|30").split("|").map(Number);
        const reps = Math.max(1, Math.round(duration / (sc||30)));
        await sendToTarget(buildLCHex(rel.action, "di", sn, reps, schedUnix));
      }
    } catch(e) { console.error("Hybrid fire error:", e); }

  } else if (evType === "switch") {
    const [stratNum,,stratCycle] = (rule.strategy_val || "9|15|30").split("|").map(Number);
    const reps = Math.max(1, Math.round(duration / (stratCycle||30)));
    await sendToTarget(buildLCHex(rule.relay_action || "all_on", rule.mode || "dlc", stratNum, reps, schedUnix));

  } else if (evType === "bas_di") {
    const [stratNum,,stratCycle] = (rule.strategy_val || "19|30|30").split("|").map(Number);
    const reps = Math.max(1, Math.round(duration / (stratCycle||30)));
    await sendToTarget(buildLCHex("all_on", "di", stratNum, reps, schedUnix));

  } else if (evType === "ev") {
    if (typeof dispatchEVChargersDR === "function") await dispatchEVChargersDR(parseFloat(rule?.signal_level || "0.75"));

  } else if (evType === "battery") {
    if (typeof dispatchBatteryDR === "function") await dispatchBatteryDR(rule);

  } else if (evType === "generator") {
    if (typeof dispatchGeneratorDR === "function") await dispatchGeneratorDR(rule);

  } else if (evType === "thermostat") {
    const action = rule.relay_action || rule.therm_action || "high";
    if (typeof dispatchThermostatDR === "function") await dispatchThermostatDR(action);

  } else if (evType === "openADR") {
    if (typeof dispatchOpenADREvent === "function") await dispatchOpenADREvent(rule);
  }

  // ── Audit log to schedule_queue ───────────────────────────────────────────
  try {
    await supabasePost("schedule_queue", {
      name:             `AUTO: ${rule.name || rule.feed_key}`,
      fire_at:          new Date().toISOString(),
      fired_at:         new Date().toISOString(),
      target_type:      rule.target_type,
      target_id:        rule.target_id,
      target_name:      rule.target_name,
      relay_action:     rule.relay_action || "all_on",
      duration_minutes: duration,
      lc_mode:          rule.mode || "dlc",
      event_type:       evType,
      status:           "fired"
    });
  } catch(e) { console.warn("schedule_queue log:", e); }

  // ── Update trigger log outcome ────────────────────────────────────────────
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/monitor_trigger_log?rule_id=eq.${rule.id}&outcome=eq.pending`, {
      method:"PATCH",
      headers:{ "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type":"application/json" },
      body: JSON.stringify({ outcome:"fired" })
    });
  } catch(e) {}
  loadTriggerLog();
}



// ── Monitor Main Tab Functions ────────────────────────────────────────────────

function initMonitorTriggersMain() {
  // Sync coords from weather location
  const coordEl = document.getElementById("fd-coords-m");
  if (coordEl && wxLocationData && !coordEl.value) {
    coordEl.value = `${wxLocationData.lat},${wxLocationData.lon}`;
  }
  loadActiveFeedsM();
  loadRulesList("rules-list-m");
  loadTriggerLogM();
  if (!monitorPoller) startMonitorPoller();
}

// Feed Discovery (Monitor tab version — reads from -m suffixed inputs)
async function runFeedDiscoveryM() {
  const state   = document.getElementById("fd-state-m")?.value;
  const utility = document.getElementById("fd-utility-m")?.value?.trim();
  const coords  = document.getElementById("fd-coords-m")?.value?.trim();
  const results = document.getElementById("fd-results-m");
  if (!state) { results.innerHTML = '<div style="color:var(--red);font-size:12px;">Please select a state.</div>'; return; }

  results.innerHTML = `<div style="font-size:12px;color:var(--text-hint);padding:8px 0;">&#128269; Discovering feeds for ${state}...</div>`;

  // Override fd-state and fd-coords temporarily so runFeedDiscovery can use same logic
  const fakeStateEl  = document.getElementById("fd-state");
  const fakeCoordsEl = document.getElementById("fd-coords");
  const fakeResultsEl = document.getElementById("fd-results");
  const origState    = fakeStateEl?.value;
  const origCoords   = fakeCoordsEl?.value;

  if (fakeStateEl)  fakeStateEl.value  = state;
  if (fakeCoordsEl) fakeCoordsEl.value = coords || "";

  // Temporarily redirect results to -m container
  const origDisplay = fakeResultsEl?.id;

  // Run discovery using shared FEED_DEFS and utility portal logic
  const isoInfo  = STATE_ISO_MAP[state];
  const isoFeeds = isoInfo?.feeds || [];
  const weatherFeeds = ["nws_temp","nws_humidity","nws_heat_index","openmeteo_uv","openmeteo_temp_forecast","tou_peak"];
  const allFeedKeys  = [...new Set([...isoFeeds, ...weatherFeeds])];

  const tested = await Promise.all(allFeedKeys.map(async key => {
    const def = FEED_DEFS[key];
    if (!def) return null;
    let status = "live", latency = null;
    if (def.auth === "registration") {
      status = "registration";
    } else if (def.testUrl) {
      try {
        const t0 = Date.now();
        const res = await fetch(def.testUrl, { method:"HEAD", signal:AbortSignal.timeout(3000) });
        latency = Date.now() - t0;
        status = res.ok ? "live" : "unavailable";
      } catch(e) {
        try {
          const t0 = Date.now();
          const res = await fetch(def.testUrl, { signal:AbortSignal.timeout(4000) });
          latency = Date.now() - t0;
          status = res.ok ? "live" : "unavailable";
        } catch(e2) { status = "unavailable"; }
      }
    } else if (key.startsWith("tou_")) { status = "live"; }
    return { key, def, status, latency };
  }));

  const valid = tested.filter(Boolean);
  const stateUtilityPortals = Object.values(UTILITY_PORTALS).filter(u => u.states.includes(state));

  let html = "";

  if (isoInfo) {
    const bc = isoInfo.iso === "SERC" ? "var(--amber)" : "var(--green-dark)";
    html += `<div style="background:var(--surface2);border:0.5px solid var(--border-md);border-radius:var(--radius-sm);padding:10px 14px;margin-bottom:12px;display:flex;align-items:center;gap:10px;">
      <span style="font-size:20px;">&#128204;</span>
      <div>
        <div style="font-size:13px;font-weight:600;color:var(--text-primary);">${state} is in <span style="color:${bc};">${isoInfo.iso}</span> — ${isoInfo.name}</div>
        ${isoInfo.iso==="SERC"?'<div style="font-size:11px;color:var(--amber);margin-top:2px;">&#9888;&#65039; Southeast — no public ISO market. Grid pricing via utility only.</div>':""}
      </div></div>`;
  }

  html += `<div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;font-family:monospace;">Available Feeds (${valid.length})</div>`;

  html += valid.map(f => {
    const sc = f.status==="live"?"var(--green-dark)":f.status==="registration"?"var(--amber)":"var(--red)";
    const sl = f.status==="live"?"&#9679; Live":f.status==="registration"?"&#9679; Requires Registration":"&#9679; Unavailable";
    const alreadyAdded = monitorFeeds.some(mf => mf.feed_key === f.key);
    return `<div class="feed-card">
      <div class="feed-status-dot ${f.status==="live"?"live":f.status==="registration"?"registration":"unavailable"}"></div>
      <div class="feed-info">
        <div class="feed-name">${f.def.icon} ${f.def.label}</div>
        <div class="feed-meta">${f.def.description}</div>
        <div class="feed-meta" style="margin-top:3px;">
          <span style="color:${sc};font-weight:600;">${sl}</span>
          ${f.latency?` &bull; ${f.latency}ms`:""} &bull; Every ${f.def.interval} min &bull; Typical: ${f.def.typical}
        </div>
      </div>
      <div>
        ${alreadyAdded
          ? '<span style="font-size:11px;color:var(--green-dark);font-weight:600;">&#10003; Added</span>'
          : f.status!=="unavailable"
            ? `<button onclick="addFeedFromDiscovery('${f.key}')" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap;">+ Add Feed</button>`
            : '<span style="font-size:11px;color:var(--red);">Unavailable</span>'
        }
      </div>
    </div>`;
  }).join("");

  if (stateUtilityPortals.length > 0) {
    html += `<div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.06em;margin:12px 0 8px;font-family:monospace;">Utility Data Portals</div>`;
    html += stateUtilityPortals.map(u => `
      <div class="feed-card">
        <div class="feed-status-dot" style="background:var(--blue-dark);"></div>
        <div class="feed-info">
          <div class="feed-name">&#127968; ${u.name}</div>
          <div class="feed-meta">Utility-specific rate and usage data portal</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:6px;">
          <a href="${u.url}" target="_blank" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);color:var(--text-secondary);font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;">Portal &#8599;</a>
          ${u.dataUrl?`<a href="${u.dataUrl}" target="_blank" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--blue);background:var(--blue-lt);color:var(--blue-dark);font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;">Rates &#8599;</a>`:""}
        </div>
      </div>`).join("");
  }

  html += `<div style="font-size:11px;color:var(--text-hint);margin-top:10px;padding:8px 12px;background:var(--surface2);border-radius:var(--radius-sm);">
    &#127777;&#65039; Weather feeds (NWS temperature, humidity, UV) are always available — set location in the Weather tab to activate.
  </div>`;

  // Add SCADA points section if any are configured
  if (typeof scadaPoints !== "undefined" && scadaPoints.length) {
    html += `<div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.06em;margin:12px 0 8px;font-family:monospace;">SCADA Data Points (${scadaPoints.length})</div>`;
    html += scadaPoints.map(p => {
      const feedKey = `scada_${p.point_id}`;
      const alreadyAdded = monitorFeeds.some(f => f.feed_key === feedKey);
      return `<div class="feed-card">
        <div class="feed-status-dot live"></div>
        <div class="feed-info">
          <div class="feed-name">${p.type === "analog" ? "〰" : p.type === "status" ? "⊙" : p.type === "alarm" ? "🔔" : "∑"} ${p.name}</div>
          <div class="feed-meta">SCADA ${p.type} point &bull; Tag: <code style="font-size:10px;">${p.point_id}</code>${p.unit ? " &bull; Unit: " + p.unit : ""}</div>
          <div class="feed-meta" style="margin-top:3px;"><span style="color:var(--green-dark);font-weight:600;">&#9679; Live — from SCADA source</span> &bull; Records every 15 min</div>
        </div>
        <div>
          ${alreadyAdded
            ? '<span style="font-size:11px;color:var(--green-dark);font-weight:600;">&#10003; Added</span>'
            : `<button onclick="addFeedFromDiscovery('${feedKey}')" style="padding:5px 12px;border-radius:var(--radius-sm);border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap;">+ Add Feed</button>`
          }
        </div>
      </div>`;
    }).join("");
  }

  results.innerHTML = html;

  // Restore originals
  if (fakeStateEl)  fakeStateEl.value  = origState  || "";
  if (fakeCoordsEl) fakeCoordsEl.value = origCoords || "";
}

// Active feeds for Monitor tab
async function loadActiveFeedsM() {
  const list = document.getElementById("active-feeds-list-m");
  if (!list) return;
  try {
    const rows = await supabaseGet("monitor_feeds?enabled=eq.true&order=added_at.asc");
    monitorFeeds = Array.isArray(rows) ? rows : [];
    if (!monitorFeeds.length) {
      list.innerHTML = '<div class="sched-empty">No feeds configured. Use Feed Discovery above to add feeds.</div>';
      return;
    }
    list.innerHTML = monitorFeeds.map(f => {
      const def = FEED_DEFS[f.feed_key] || {};
      const fv  = feedValues[f.feed_key];
      const val = fv ? `${fv.value} ${f.unit||""}` : "—";
      const ts  = fv ? new Date(fv.timestamp).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}) : "";
      return `<div class="feed-card">
        <div class="feed-status-dot live"></div>
        <div class="feed-info">
          <div class="feed-name">${def.icon||"📡"} ${f.label}</div>
          <div class="feed-meta">Every ${f.interval_minutes} min${ts?` &bull; Last: ${ts}`:""}</div>
        </div>
        <div style="text-align:right;">
          <div class="feed-value">${val}</div>
          <button onclick="removeFeed(${f.id})" style="margin-top:4px;padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
        </div>
      </div>`;
    }).join("");
  } catch(e) { list.innerHTML = '<div class="sched-empty">Error loading feeds.</div>'; }
}

// Rules list for Monitor tab (reuses same data, different container)
async function loadRulesList(containerId) {
  const list = document.getElementById(containerId);
  if (!list) return;
  try {
    const rows = await supabaseGet("monitor_rules?order=created_at.asc");
    monitorRules = Array.isArray(rows) ? rows : [];
    if (!monitorRules.length) { list.innerHTML = '<div class="sched-empty">No rules configured. Click + Add Rule to create one.</div>'; return; }
    const tierColors = { alert:"var(--blue-dark)", suggest:"var(--amber)", autopilot:"var(--red)" };
    list.innerHTML = monitorRules.map(r => {
      const feed1 = FEED_DEFS[r.feed_key]||{label:r.feed_key,unit:""};
      const feed2 = r.feed_key2 ? FEED_DEFS[r.feed_key2] : null;
      const op1   = {gt:">",gte:"≥",lt:"<",lte:"≤",eq:"="}[r.operator]||r.operator;
      const op2   = {gt:">",gte:"≥",lt:"<",lte:"≤",eq:"="}[r.operator2]||"";
      const cond1 = `${feed1.label} ${op1} ${r.threshold} ${feed1.unit}`;
      const cond2 = feed2&&r.threshold2?` AND ${feed2.label} ${op2} ${r.threshold2} ${feed2.unit}`:"";
      return `<div class="rule-card">
        <div class="rule-card-header">
          <div class="rule-status ${r.enabled?"enabled":"disabled"}"></div>
          <span class="rule-tier-badge ${r.tier}">${r.tier.toUpperCase()}</span>
          <div class="rule-condition">${r.name||cond1+cond2}</div>
          <div style="display:flex;gap:6px;">
            <button onclick="editRule(${r.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;cursor:pointer;">Edit</button>
            <button onclick="toggleRuleEnabled(${r.id},${!r.enabled})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;cursor:pointer;">${r.enabled?"Disable":"Enable"}</button>
            <button onclick="deleteRule(${r.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:11px;cursor:pointer;">Delete</button>
          </div>
        </div>
        <div class="rule-card-body">
          <strong>Condition:</strong> ${cond1}${cond2}<br/>
          <strong>Action:</strong> ${r.relay_action||"—"} on ${r.target_name||r.target_id||"—"} &bull; Strategy ${(r.strategy_val||"").split("|")[0]} &bull; ${r.duration_mins} min<br/>
          <strong>Guards:</strong> Max ${r.max_per_day}/day &bull; ${r.min_rest_mins} min rest${r.grace_mins?` &bull; ${r.grace_mins} min grace`:""}${r.blackout_start?` &bull; Blackout ${r.blackout_start}–${r.blackout_end}`:""}
        </div>
      </div>`;
    }).join("");
  } catch(e) { list.innerHTML = '<div class="sched-empty">Error loading rules.</div>'; }
}

