// ── Data Feeds Chart ──────────────────────────────────────────────────────────

let feedChartInstance = null;

async function initFeedCharts() {
  // Populate feed selector from active feeds
  const sel = document.getElementById("feed-chart-key");
  if (!sel) return;

  const rows = await supabaseGet("monitor_feeds?enabled=eq.true&order=added_at.asc").catch(() => []);
  monitorFeeds = Array.isArray(rows) ? rows : [];

  sel.innerHTML = '<option value="">-- Select Feed --</option>';
  monitorFeeds.forEach(f => {
    const def = FEED_DEFS[f.feed_key] || {};
    const o = document.createElement("option");
    o.value       = f.feed_key;
    o.textContent = `${def.icon||""} ${f.label} (${f.unit||""})`;
    sel.appendChild(o);
  });

  // Also ensure SCADA point FEED_DEFS are populated
  populateSCADARuleFeedOptions();

  // Auto-select first feed
  if (monitorFeeds.length > 0) {
    sel.value = monitorFeeds[0].feed_key;
    await loadFeedChart();
  }

  await loadLatestFeedValues();
}

async function loadFeedChart() {
  const feedKey  = document.getElementById("feed-chart-key")?.value;
  const rangeHrs = parseInt(document.getElementById("feed-chart-range")?.value || "24");
  const metaEl   = document.getElementById("feed-chart-meta");
  const ctx      = document.getElementById("feed-data-chart");
  if (!ctx) return;

  if (!feedKey) {
    if (metaEl) metaEl.textContent = "Select a feed to chart.";
    return;
  }

  const def   = FEED_DEFS[feedKey] || {};
  const since = new Date(Date.now() - rangeHrs * 60 * 60 * 1000).toISOString();

  if (metaEl) metaEl.textContent = "Loading...";

  try {
    // For SCADA feeds pull from scada_readings table, otherwise monitor_feed_readings
    let rows;
    if (feedKey.startsWith("scada_")) {
      const pointId = feedKey.replace("scada_", "");
      rows = await supabaseGet(
        `scada_readings?point_id=eq.${encodeURIComponent(pointId)}&recorded_at=gte.${encodeURIComponent(since)}&order=recorded_at.asc&limit=2000`
      );
    } else {
      rows = await supabaseGet(
        `monitor_feed_readings?feed_key=eq.${encodeURIComponent(feedKey)}&recorded_at=gte.${encodeURIComponent(since)}&order=recorded_at.asc&limit=2000`
      );
    }

    if (!Array.isArray(rows) || !rows.length) {
      if (metaEl) metaEl.textContent = `No data for "${def.label}" in the last ${rangeHrs} hours. Data is collected every 5 minutes during monitor cycles.`;
      if (feedChartInstance) { feedChartInstance.destroy(); feedChartInstance = null; }
      await loadFeedRules(feedKey);
      return;
    }

    const labels = rows.map(r => {
      const d = new Date(r.recorded_at);
      return rangeHrs <= 24
        ? d.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})
        : d.toLocaleDateString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});
    });
    const data = rows.map(r => r.value);

    const min   = Math.min(...data.filter(v=>v!=null));
    const max   = Math.max(...data.filter(v=>v!=null));
    const avg   = (data.filter(v=>v!=null).reduce((a,b)=>a+b,0)/data.length).toFixed(1);
    const last  = data[data.length-1];

    if (metaEl) metaEl.innerHTML = `
      <span style="margin-right:16px;"><strong>Latest:</strong> ${last} ${def.unit||""}</span>
      <span style="margin-right:16px;"><strong>Min:</strong> ${min} ${def.unit||""}</span>
      <span style="margin-right:16px;"><strong>Max:</strong> ${max} ${def.unit||""}</span>
      <span><strong>Avg:</strong> ${avg} ${def.unit||""}</span>
      <span style="margin-left:16px;color:var(--text-hint);">${rows.length} readings</span>`;

    // Color by feed type
    const color = feedKey.includes("temp")||feedKey.includes("heat") ? "#e67e22"
      : feedKey.includes("lmp") ? "#c0392b"
      : feedKey.includes("humidity") ? "#2980b9"
      : feedKey.includes("uv")  ? "#8e44ad"
      : "#1a5f4a";

    if (feedChartInstance) { feedChartInstance.destroy(); feedChartInstance = null; }
    feedChartInstance = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: `${def.label}${def.unit?" ("+def.unit+")":""}`,
          data,
          borderColor: color,
          backgroundColor: color + "18",
          borderWidth: 2,
          pointRadius: rows.length > 100 ? 0 : 3,
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode:"index", intersect:false },
        plugins: {
          legend: { display:false },
          tooltip: { callbacks: { label: ctx => `${ctx.parsed.y} ${def.unit||""}` } }
        },
        scales: {
          x: { ticks: { maxTicksLimit:10, font:{size:10}, color:"#888780" }, grid:{color:"rgba(0,0,0,0.05)"} },
          y: {
            ticks: { font:{size:10}, color:"#888780" },
            grid:  { color:"rgba(0,0,0,0.05)" },
            title: { display:true, text: def.unit||"", font:{size:10}, color:"#888780" }
          }
        }
      }
    });
    if (chartInstances) chartInstances["feed-data-chart"] = feedChartInstance;

    // Load rules for this feed below the chart
    await loadFeedRules(feedKey);

  } catch(e) {
    if (metaEl) metaEl.innerHTML = `<span style="color:var(--red);">Error loading feed data: ${e.message}</span>`;
  }
}

async function loadLatestFeedValues() {
  const container = document.getElementById("feed-latest-values");
  if (!container) return;
  if (!monitorFeeds.length) {
    container.innerHTML = '<div class="sched-empty">No active feeds.</div>';
    return;
  }
  try {
    // Get the latest reading for each feed
    const results = await Promise.all(monitorFeeds.map(async f => {
      const rows = await supabaseGet(
        `monitor_feed_readings?feed_key=eq.${encodeURIComponent(f.feed_key)}&order=recorded_at.desc&limit=1`
      ).catch(() => []);
      const latest = Array.isArray(rows) && rows.length ? rows[0] : null;
      return { feed:f, latest };
    }));

    container.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Feed</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Latest Value</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Recorded</th>
        <th style="text-align:center;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Chart</th>
      </tr></thead>
      <tbody>${results.map(({feed:f,latest}) => {
        const def = FEED_DEFS[f.feed_key]||{};
        const val = latest ? `${latest.value} ${f.unit||""}` : "No data";
        const ts  = latest ? new Date(latest.recorded_at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}) : "—";
        return `<tr>
          <td style="padding:7px 10px;border-bottom:0.5px solid var(--border);">${def.icon||"📡"} ${f.label}</td>
          <td style="padding:7px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;font-weight:600;color:var(--text-primary);">${val}</td>
          <td style="padding:7px 10px;border-bottom:0.5px solid var(--border);text-align:right;color:var(--text-hint);">${ts}</td>
          <td style="padding:7px 10px;border-bottom:0.5px solid var(--border);text-align:center;">
            <button onclick="document.getElementById('feed-chart-key').value='${f.feed_key}';loadFeedChart();"
              style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">&#128202; Chart</button>
          </td>
        </tr>`;
      }).join("")}</tbody></table>`;
  } catch(e) {
    container.innerHTML = `<div class="sched-empty">Error: ${e.message}</div>`;
  }
}



// ── Inline Rule Form (Data Feeds tab) ─────────────────────────────────────────

let inlineSelectedTier = null;
let inlineCurrentFeedKey = null;

function showInlineRuleForm() {
  const form = document.getElementById("inline-rule-form");
  if (!form) return;
  form.style.display = "block";

  // Pre-populate feed label and hint
  const feedKey = document.getElementById("feed-chart-key")?.value;
  inlineCurrentFeedKey = feedKey;
  const def = FEED_DEFS[feedKey] || {};
  const labelEl = document.getElementById("inline-feed-label");
  const unitEl  = document.getElementById("inline-threshold-unit");
  const hintEl  = document.getElementById("inline-threshold-hint");
  if (labelEl) labelEl.textContent = def.label || feedKey;
  if (unitEl)  unitEl.textContent  = def.unit || "";
  if (hintEl)  hintEl.textContent  = `Typical: ${def.typical || "—"} — Suggested trigger: ${def.typical_trigger || "?"} ${def.unit || ""}`;

  // Pre-fill threshold with current value if available
  const fv = feedValues[feedKey];
  const threshEl = document.getElementById("inline-threshold");
  if (threshEl && def.typical_trigger) {
    threshEl.placeholder = `e.g. ${def.typical_trigger}`;
  }

  // Reset tier selection
  inlineSelectedTier = null;
  document.querySelectorAll(".inline-tier-btn").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface)";
  });
  document.getElementById("inline-autopilot-warning").style.display = "none";
  document.getElementById("inline-grace-row").style.display = "none";

  // Reset target
  document.getElementById("inline-target-type").selectedIndex = 0;
  document.getElementById("inline-target").innerHTML = '<option value="" disabled selected>-- Choose --</option>';
  document.getElementById("inline-rule-name").value = "";
  document.getElementById("inline-threshold").value = "";

  form.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function hideInlineRuleForm() {
  const form = document.getElementById("inline-rule-form");
  if (form) form.style.display = "none";
  inlineSelectedTier = null;
}

function selectInlineTier(tier, btn) {
  inlineSelectedTier = tier;
  // Update button styles
  document.querySelectorAll(".inline-tier-btn").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface)";
    b.style.fontWeight  = "600";
  });
  const colors = { alert:"var(--blue-dark)", suggest:"var(--amber)", autopilot:"var(--red)" };
  btn.style.borderColor = colors[tier];
  btn.style.background  = tier === "alert" ? "var(--blue-lt)" : tier === "suggest" ? "var(--amber-bg)" : "var(--red-lt)";

  // Show autopilot warning and grace period
  const apWarn   = document.getElementById("inline-autopilot-warning");
  const graceRow = document.getElementById("inline-grace-row");
  if (apWarn)   apWarn.style.display   = tier === "autopilot" ? "block" : "none";
  if (graceRow) graceRow.style.display = tier === "autopilot" ? "block" : "none";
}

function onInlineTargetChange() {
  const type = document.getElementById("inline-target-type")?.value;
  const sel  = document.getElementById("inline-target");
  if (!sel || !type) return;
  sel.innerHTML = '<option value="" disabled selected>-- Choose --</option>';
  if (type === "group") {
    Object.keys(groupNames).map(Number).sort((a,b)=>a-b).forEach(n => {
      const o = document.createElement("option");
      o.value = `group_${n}`;
      o.textContent = `Group ${n}: ${groupNames[n]||"Group "+n}${groupTags?.[n]?" — "+groupTags[n]:""}`;
      sel.appendChild(o);
    });
  } else {
    const relayDevs = DEVICES.filter(d => d.type !== "ev" && !d.uid.includes("PLACEHOLDER"));
    const evDevs    = DEVICES.filter(d => d.type === "ev");
    if (relayDevs.length) {
      const grp = document.createElement("optgroup"); grp.label = "Relay Devices";
      relayDevs.forEach(d => { const o = document.createElement("option"); o.value=d.uid; o.textContent=d.name; grp.appendChild(o); });
      sel.appendChild(grp);
    }
    if (evDevs.length) {
      const grp = document.createElement("optgroup"); grp.label = "EV Chargers";
      evDevs.forEach(d => { const o = document.createElement("option"); o.value=d.uid; o.textContent="⚡ "+d.name; grp.appendChild(o); });
      sel.appendChild(grp);
    }
    const genDevs = DEVICES.filter(d => d.type === "generator");
    if (genDevs.length) {
      const grp = document.createElement("optgroup"); grp.label = "Generators";
      genDevs.forEach(d => { const o = document.createElement("option"); o.value=d.uid; o.textContent="⚡ "+d.name; grp.appendChild(o); });
      sel.appendChild(grp);
    }
  }
}

async function saveInlineRule() {
  if (!inlineSelectedTier) {
    setStatus("error", "Please select a tier (Alert / Suggest / Autopilot).");
    return;
  }
  if (!inlineCurrentFeedKey) {
    setStatus("error", "No feed selected. Select a feed from the chart above first.");
    return;
  }
  const threshold = parseFloat(document.getElementById("inline-threshold")?.value);
  if (isNaN(threshold)) {
    setStatus("error", "Please enter a threshold value.");
    return;
  }
  const targetId = document.getElementById("inline-target")?.value;
  if (!targetId && inlineSelectedTier !== "alert") {
    setStatus("error", "Please select a target device or group.");
    return;
  }
  if (inlineSelectedTier === "autopilot" && currentUserRole !== "administrator") {
    setStatus("error", "Autopilot rules require Administrator role.");
    return;
  }

  const targetType = document.getElementById("inline-target-type")?.value;
  const targetName = targetType === "group"
    ? (groupNames[parseInt(targetId.replace("group_",""))] || targetId)
    : (DEVICES.find(d => d.uid === targetId)?.name || targetId);

  const def = FEED_DEFS[inlineCurrentFeedKey] || {};

  const record = {
    tier:          inlineSelectedTier,
    name:          document.getElementById("inline-rule-name")?.value?.trim() || `${def.label} ${document.getElementById("inline-operator")?.value} ${threshold} ${def.unit||""}`,
    feed_key:      inlineCurrentFeedKey,
    operator:      document.getElementById("inline-operator")?.value || "gt",
    threshold,
    target_type:   targetType || null,
    target_id:     targetId   || null,
    target_name:   targetName || null,
    relay_action:  "all_on",
    mode:          "dlc",
    strategy_val:  document.getElementById("inline-strategy")?.value || "9|15|30",
    duration_mins: parseInt(document.getElementById("inline-duration")?.value) || 60,
    max_per_day:   parseInt(document.getElementById("inline-max-per-day")?.value) || 3,
    min_rest_mins: parseInt(document.getElementById("inline-min-rest")?.value) || 120,
    grace_mins:    inlineSelectedTier === "autopilot" ? parseInt(document.getElementById("inline-grace")?.value) || 5 : null,
    enabled:       true,
    created_by:    currentUser?.email || null,
    created_at:    new Date().toISOString()
  };

  try {
    await supabasePost("monitor_rules", record);
    setStatus("ready", `Rule "${record.name}" saved.`);
    hideInlineRuleForm();
    // Reload rules list for this feed
    await loadFeedRules(inlineCurrentFeedKey);
    // Also refresh the rules lists on the Triggers sub-tab
    await loadRules();
    await loadRulesList("rules-list-m");
  } catch(e) {
    setStatus("error", "Failed to save rule: " + e.message);
    console.error("saveInlineRule:", e);
  }
}

// Load rules for the currently charted feed
async function loadFeedRules(feedKey) {
  const card    = document.getElementById("feed-rules-card");
  const list    = document.getElementById("feed-rules-list");
  if (!card || !list || !feedKey) return;

  card.style.display = "block";

  const def = FEED_DEFS[feedKey] || {};

  // Update card title
  const titleEl = card.querySelector(".sched-card-title");
  if (titleEl) titleEl.innerHTML = `&#9881;&#65039; Rules — <span style="font-family:monospace;color:var(--text-secondary);">${def.label || feedKey}</span>`;

  // Update inline feed label
  const labelEl = document.getElementById("inline-feed-label");
  const unitEl  = document.getElementById("inline-threshold-unit");
  const hintEl  = document.getElementById("inline-threshold-hint");
  if (labelEl) labelEl.textContent = def.label || feedKey;
  if (unitEl)  unitEl.textContent  = def.unit  || "";
  if (hintEl)  hintEl.textContent  = `Typical: ${def.typical||"—"} — Suggested trigger: ${def.typical_trigger||"?"} ${def.unit||""}`;

  try {
    const rows = await supabaseGet(
      `monitor_rules?feed_key=eq.${encodeURIComponent(feedKey)}&order=created_at.asc`
    );

    if (!Array.isArray(rows) || !rows.length) {
      list.innerHTML = `<div class="sched-empty">No rules for <strong>${def.label||feedKey}</strong> yet. Click + Quick Add Rule to create one.</div>`;
      return;
    }

    list.innerHTML = rows.map(r => {
      const op = {gt:">",gte:"≥",lt:"<",lte:"≤",eq:"="}[r.operator]||r.operator;
      return `<div class="rule-card" style="margin-bottom:8px;">
        <div class="rule-card-header">
          <div class="rule-status ${r.enabled?"enabled":"disabled"}"></div>
          <span class="rule-tier-badge ${r.tier}">${r.tier.toUpperCase()}</span>
          <div class="rule-condition" style="flex:1;">${r.name||`${def.label} ${op} ${r.threshold} ${def.unit||""}`}</div>
          <div style="display:flex;gap:5px;">
            <button onclick="toggleRuleEnabled(${r.id},${!r.enabled});setTimeout(()=>loadFeedRules('${feedKey}'),300);"
              style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">
              ${r.enabled?"Disable":"Enable"}
            </button>
            <button onclick="editRule(${r.id})"
              style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">Edit</button>
            <button onclick="deleteRule(${r.id});setTimeout(()=>loadFeedRules('${feedKey}'),300);"
              style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Delete</button>
          </div>
        </div>
        <div class="rule-card-body">
          <strong>Condition:</strong> ${def.label} ${op} ${r.threshold} ${def.unit||""}<br/>
          ${r.target_name ? `<strong>Action:</strong> ${r.relay_action||"all_on"} on ${r.target_name} &bull; Strategy ${(r.strategy_val||"").split("|")[0]} &bull; ${r.duration_mins} min<br/>` : ""}
          <strong>Guards:</strong> Max ${r.max_per_day}/day &bull; ${r.min_rest_mins} min rest${r.grace_mins?` &bull; ${r.grace_mins} min grace`:""}
        </div>
      </div>`;
    }).join("");
  } catch(e) {
    list.innerHTML = `<div class="sched-empty">Error loading rules: ${e.message}</div>`;
  }
}



// ── OpenADR mTLS & Auth ───────────────────────────────────────────────────────

function selectOADRAuthMode(mode, btn, silent = false) {
  // Update button styles
  document.querySelectorAll(".oadr-auth-btn").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface2)";
    b.style.color       = "var(--text-secondary)";
    b.classList.remove("active");
  });
  if (btn) {
    btn.style.borderColor = "var(--green)";
    btn.style.background  = "var(--green-bg)";
    btn.style.color       = "var(--green-dark)";
    btn.classList.add("active");
  } else {
    // Find by data-mode
    const target = document.querySelector(`.oadr-auth-btn[data-mode="${mode}"]`);
    if (target) {
      target.style.borderColor = "var(--green)";
      target.style.background  = "var(--green-bg)";
      target.style.color       = "var(--green-dark)";
      target.classList.add("active");
    }
  }

  // Show/hide auth panels
  const panels = { none: null, apikey: "oadr-auth-apikey", mtls: "oadr-auth-mtls" };
  Object.values(panels).filter(Boolean).forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = "none";
  });
  if (mode !== "none" && panels[mode]) {
    const el = document.getElementById(panels[mode]);
    if (el) el.style.display = "block";
  }
}

function updateMTLSStatus(certId) {
  const indicator = document.getElementById("oadr-mtls-indicator");
  const statusText = document.getElementById("oadr-mtls-status-text");
  if (!certId) {
    if (indicator) indicator.style.background = "var(--border-md)";
    if (statusText) statusText.textContent = "No certificate configured";
    return;
  }
  if (indicator) indicator.style.background = "var(--green-dark)";
  if (statusText) statusText.innerHTML = `&#10003; Certificate configured &bull; ID: <code style="font-family:monospace;font-size:10px;">${certId.substring(0,8)}...</code>`;
}

async function verifyMTLSCert() {
  const certId  = document.getElementById("oadr-mtls-cert-id")?.value?.trim();
  const statusEl = document.getElementById("oadr-mtls-cert-status");
  if (!certId) { if (statusEl) { statusEl.textContent = "Enter a Certificate ID first."; statusEl.style.color = "var(--red)"; } return; }
  if (statusEl) { statusEl.textContent = "Verifying via Worker..."; statusEl.style.color = "var(--text-hint)"; }

  try {
    // Ask the Worker to verify the cert ID is configured
    const res = await fetch(PROXY_URL + "openadr/mtls-status", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ cert_id: certId })
    });
    const data = await res.json();
    if (data.configured) {
      if (statusEl) { statusEl.textContent = "✅ Certificate binding active in Worker — mTLS ready."; statusEl.style.color = "var(--green-dark)"; }
      updateMTLSStatus(certId);
    } else {
      if (statusEl) { statusEl.innerHTML = "⚠️ Certificate ID saved but Worker binding not yet active.<br/>Add the mtls_certificates binding to wrangler.toml and redeploy (see instructions above)."; statusEl.style.color = "var(--amber)"; }
    }
  } catch(e) {
    // Worker might not have the route yet — still save the cert ID
    if (statusEl) { statusEl.innerHTML = `Certificate ID saved. Worker mTLS route not yet deployed — redeploy worker.js with the mtls_certificates binding to activate.<br/><span style="color:var(--text-hint);">Error: ${e.message}</span>`; statusEl.style.color = "var(--amber)"; }
    updateMTLSStatus(certId);
  }
}

async function testVTNConnection() {
  const vtnUrl   = document.getElementById("oadr-vtn-url")?.value?.trim();
  const venId    = document.getElementById("oadr-ven-id")?.value?.trim() || "E545300JH";
  const vtnId    = document.getElementById("oadr-vtn-id")?.value?.trim() || "";
  const statusEl = document.getElementById("oadr-config-status");

  if (!vtnUrl) {
    if (statusEl) { statusEl.textContent = "Enter a VTN URL first then click Save before testing."; statusEl.style.color = "var(--red)"; statusEl.style.display = "block"; }
    return;
  }
  if (statusEl) { statusEl.textContent = "Saving config then testing connection via mTLS Worker…"; statusEl.style.color = "var(--text-hint)"; statusEl.style.display = "block"; }

  // Always save first so the Worker has current values
  await saveVTNConfig();

  if (statusEl) { statusEl.textContent = "Testing connection via Worker (mTLS)…"; statusEl.style.color = "var(--text-hint)"; statusEl.style.display = "block"; }

  try {
    const res  = await fetch(PROXY_URL + "openadr/test", {
      method: "GET",
      headers: { "Content-Type": "application/json" }
    });
    const data = await res.json();
    if (data.success) {
      if (statusEl) { statusEl.textContent = `✅ Connected — HTTP ${data.http_status} · Cert: ${data.cert_used ? "mTLS ✓" : "no cert"} · VTN response: ${data.response_code||"ok"}`; statusEl.style.color = "var(--green-dark)"; }
    } else {
      if (statusEl) { statusEl.textContent = `⚠️ Connection failed: ${data.error || "HTTP "+data.http_status}`; statusEl.style.color = "var(--amber)"; }
    }
    console.log("VTN test result:", data);
  } catch(e) {
    if (statusEl) { statusEl.textContent = `Error: ${e.message}`; statusEl.style.color = "var(--red)"; }
  }
  setTimeout(() => { if (statusEl) statusEl.style.display = "none"; }, 8000);
}



// ── Summary Feed Values ───────────────────────────────────────────────────────

async function refreshSummaryFeeds() {
  const grid    = document.getElementById("summary-feeds-grid");
  const card    = document.getElementById("summary-feeds-card");
  const updated = document.getElementById("summary-feeds-updated");
  if (!grid) return;

  // Fetch latest reading per active feed from Supabase
  try {
    const feeds = await supabaseGet("monitor_feeds?enabled=eq.true&order=added_at.asc");
    if (!Array.isArray(feeds) || !feeds.length) {
      if (card) card.style.display = "none";
      return;
    }

    if (card) card.style.display = "block";

    const results = await Promise.all(feeds.map(async f => {
      const rows = await supabaseGet(
        `monitor_feed_readings?feed_key=eq.${encodeURIComponent(f.feed_key)}&order=recorded_at.desc&limit=1`
      ).catch(() => []);
      const latest = Array.isArray(rows) && rows.length ? rows[0] : null;
      return { feed: f, latest };
    }));

    // Also check live feedValues and scadaLiveData for any that are more recent
    results.forEach(r => {
      // Check scadaLiveData directly for SCADA feeds
      if (r.feed.feed_key.startsWith("scada_")) {
        const pointId = r.feed.feed_key.replace("scada_", "");
        const scadaLive = typeof scadaLiveData !== "undefined" ? scadaLiveData[pointId] : null;
        if (scadaLive && scadaLive.value != null) {
          r.latest = { value: scadaLive.value, unit: scadaLive.unit, recorded_at: scadaLive.timestamp };
        }
      }
      const live = feedValues[r.feed.feed_key];
      if (live && live.value != null) {
        const liveAge    = live.timestamp ? Date.now() - new Date(live.timestamp).getTime() : 9999999;
        const dbAge      = r.latest?.recorded_at ? Date.now() - new Date(r.latest.recorded_at).getTime() : 9999999;
        if (liveAge < dbAge) {
          r.latest = { value: live.value, unit: live.unit, recorded_at: live.timestamp };
        }
      }
    });

    const colorMap = {
      nws_temp:"#e67e22", nws_humidity:"#2980b9", nws_heat_index:"#c0392b",
      openmeteo_uv:"#8e44ad", openmeteo_temp_forecast:"#e67e22",
      spp_lmp:"#c0392b", ercot_lmp:"#c0392b", miso_lmp:"#c0392b",
      isone_lmp:"#c0392b", tou_peak:"#1a5f4a", tou_offpeak:"#2980b9"
    };

    grid.innerHTML = results.map(({ feed: f, latest }) => {
      const def   = FEED_DEFS[f.feed_key] || {};
      const val   = latest?.value != null ? latest.value : null;
      const unit  = f.unit || def.unit || "";
      const age   = latest?.recorded_at
        ? Math.round((Date.now() - new Date(latest.recorded_at).getTime()) / 60000)
        : null;
      const color = colorMap[f.feed_key] || "var(--text-primary)";
      const ageStr = age == null ? "No data" : age < 2 ? "Just now" : `${age}m ago`;
      const ageColor = age == null ? "var(--red)" : age > 30 ? "var(--amber)" : "var(--text-hint)";

      return `<div style="background:var(--surface2);border:0.5px solid var(--border-md);border-radius:var(--radius-sm);padding:12px;text-align:center;">
        <div style="font-size:16px;margin-bottom:4px;">${def.icon || "📡"}</div>
        <div style="font-size:11px;font-weight:600;color:var(--text-hint);margin-bottom:6px;font-family:monospace;text-transform:uppercase;letter-spacing:.04em;">${f.label}</div>
        <div style="font-size:${val != null ? "24px" : "18px"};font-weight:700;color:${val != null ? color : "var(--text-hint)"};line-height:1;">
          ${val != null ? val + (unit ? " <span style=\"font-size:12px;font-weight:400;\">" + unit + "</span>" : "") : "—"}
        </div>
        <div style="font-size:10px;color:${ageColor};margin-top:4px;">${ageStr}</div>
      </div>`;
    }).join("");

    if (updated) updated.textContent = `Updated: ${new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}`;

  } catch(e) {
    console.warn("refreshSummaryFeeds:", e.message);
  }
}

// ── Tier-Aware Rule Form ───────────────────────────────────────────────────────

function applyRuleTierVisibility(tier) {
  const actionSection  = document.getElementById("rule-action-section");
  const graceRow       = document.getElementById("rule-grace-row");
  const apWarn         = document.getElementById("autopilot-warning");
  const notifySection  = document.getElementById("rule-notify-section");
  const cancelRow      = document.getElementById("rule-notify-cancel-row");

  if (!tier) return;

  // Action section — hidden for Alert, shown for Suggest and Autopilot
  if (actionSection) actionSection.style.display = tier === "alert" ? "none" : "block";

  // Grace period — only for Autopilot
  if (graceRow) graceRow.style.display = tier === "autopilot" ? "block" : "none";

  // Autopilot warning
  if (apWarn) apWarn.style.display = tier === "autopilot" ? "block" : "none";

  // Notification section — always shown
  if (notifySection) notifySection.style.display = "block";

  // Cancel link option — only relevant for Suggest and Autopilot
  if (cancelRow) cancelRow.style.display = tier === "alert" ? "none" : "flex";
}

// selectRuleTier visibility wired directly into the original function below

// ── Email Notification System ─────────────────────────────────────────────────

// Fetch alert-enabled users from user_profiles
async function getAlertRecipients() {
  try {
    const rows = await supabaseGet("user_profiles?receive_alerts=eq.true&is_active=eq.true&select=email,full_name,role");
    return Array.isArray(rows) ? rows : [];
  } catch(e) {
    console.warn("getAlertRecipients:", e);
    return [];
  }
}

// Generate a cancellation token and store it
async function createCancelToken(ruleId, eventDesc, graceMins) {
  const token     = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + graceMins * 60 * 1000).toISOString();
  try {
    await supabasePost("pending_notifications", {
      token,
      rule_id:     ruleId,
      event_desc:  eventDesc,
      expires_at:  expiresAt,
      cancelled:   false,
      created_at:  new Date().toISOString()
    });
  } catch(e) { console.warn("createCancelToken:", e); }
  return token;
}

// Send notification email via Worker /notify endpoint
async function sendNotificationEmail({ recipients, rule, tier, feedValue, feedUnit, feedLabel, eventDesc, cancelToken, graceMins }) {
  if (!recipients || !recipients.length) return;

  const tierColors = { alert:"#1d5fa8", suggest:"#b45309", autopilot:"#c0392b" };
  const tierLabels = { alert:"⚠️ Alert", suggest:"💡 Suggestion", autopilot:"⚡ Autopilot" };
  const tierColor  = tierColors[tier] || "#1a1a1a";
  const tierLabel  = tierLabels[tier] || tier.toUpperCase();

  const cancelSection = cancelToken ? `
    <div style="margin-top:20px;text-align:center;">
      <p style="font-size:13px;color:#666;margin-bottom:12px;">
        This event will fire in <strong>${graceMins} minute${graceMins!==1?"s":""}</strong> unless cancelled.
      </p>
      <a href="${PROXY_URL}cancel?token=${cancelToken}"
        style="display:inline-block;padding:12px 28px;background:#c0392b;color:#fff;border-radius:6px;text-decoration:none;font-weight:700;font-size:14px;">
        &#10060; Cancel This Event
      </a>
      <p style="font-size:11px;color:#999;margin-top:8px;">This link expires in ${graceMins} minutes.</p>
    </div>` : "";

  const customMsg = rule.notify_message ? `<p style="font-size:13px;color:#444;font-style:italic;margin:8px 0;">${rule.notify_message}</p>` : "";

  const html = `
    <div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;background:#fff;border-radius:8px;overflow:hidden;border:1px solid #e0e0e0;">
      <div style="background:${tierColor};padding:20px 24px;">
        <div style="font-size:20px;font-weight:700;color:#fff;">${tierLabel}</div>
        <div style="font-size:13px;color:rgba(255,255,255,.75);margin-top:4px;">Load Control Platform — Monitor & Triggers</div>
      </div>
      <div style="padding:24px;">
        <p style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:4px;">${rule.name || feedLabel + " threshold crossed"}</p>
        ${customMsg}
        <table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:13px;">
          <tr style="background:#f5f5f3;">
            <td style="padding:8px 12px;font-weight:600;color:#666;border-bottom:1px solid #e8e8e8;">Feed</td>
            <td style="padding:8px 12px;border-bottom:1px solid #e8e8e8;">${feedLabel}</td>
          </tr>
          <tr>
            <td style="padding:8px 12px;font-weight:600;color:#666;border-bottom:1px solid #e8e8e8;">Current Value</td>
            <td style="padding:8px 12px;border-bottom:1px solid #e8e8e8;font-weight:700;color:${tierColor};">${feedValue} ${feedUnit}</td>
          </tr>
          <tr style="background:#f5f5f3;">
            <td style="padding:8px 12px;font-weight:600;color:#666;border-bottom:1px solid #e8e8e8;">Threshold</td>
            <td style="padding:8px 12px;border-bottom:1px solid #e8e8e8;">${{gt:">",gte:"≥",lt:"<",lte:"≤",eq:"="}[rule.operator]||rule.operator} ${rule.threshold} ${feedUnit}</td>
          </tr>
          <tr>
            <td style="padding:8px 12px;font-weight:600;color:#666;">Action</td>
            <td style="padding:8px 12px;">${eventDesc || "See dashboard"}</td>
          </tr>
        </table>
        ${cancelSection}
        <div style="margin-top:20px;padding-top:16px;border-top:1px solid #e8e8e8;font-size:11px;color:#999;">
          Sent by Load Control Platform &bull; ${new Date().toLocaleString()}
        </div>
      </div>
    </div>`;

  try {
    await fetch(PROXY_URL + "notify", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        recipients: recipients.map(r => ({ email: r.email, name: r.full_name || r.email })),
        subject:    `[LCP ${tier.toUpperCase()}] ${rule.name || feedLabel}`,
        html
      })
    });
  } catch(e) {
    console.warn("sendNotificationEmail:", e.message);
  }
}

// ── Cancellation Timer ─────────────────────────────────────────────────────────

let activeCancellationTimers = {}; // { ruleId: { timer, countdownEl, graceMs } }

function showCancellationBanner(rule, fv, tier, token) {
  const graceMins = rule.grace_mins || 5;
  const graceMs   = graceMins * 60 * 1000;
  let   remaining = graceMins * 60;

  hideCancellationBanner(rule.id);

  const bannerId  = `cancel-banner-${rule.id}`;
  const isAuto    = tier === "autopilot";
  const accentClr = isAuto ? "#DC2626" : "#D97706";
  const accentBg  = isAuto ? "#FEF2F2" : "#FFFBEB";

  const banner = document.createElement("div");
  banner.id = bannerId;
  banner.style.cssText = `
    position:fixed;
    top:72px;
    left:50%;
    transform:translateX(-50%);
    z-index:9999;
    width:min(520px, 94vw);
    background:#fff;
    color:#111;
    border-radius:14px;
    padding:20px 24px 18px;
    box-shadow:0 12px 48px rgba(0,0,0,.28), 0 0 0 3px ${accentClr};
    border-top:5px solid ${accentClr};
    animation:oadr3Pulse 1.4s ease-in-out infinite;
  `;

  banner.innerHTML = `
    <div style="display:flex;align-items:flex-start;gap:16px;">
      <div style="font-size:36px;flex-shrink:0;line-height:1;">${isAuto ? "⚡" : "💡"}</div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:15px;font-weight:800;color:#111;margin-bottom:4px;letter-spacing:-.01em;">
          ${isAuto ? "Autopilot Event Pending" : "Suggested Event Pending"}
        </div>
        <div style="font-size:13px;font-weight:600;color:#444;margin-bottom:8px;">
          ${rule.name || "Monitor trigger"}
        </div>
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;">
          <div style="font-size:12px;color:#666;">
            ${isAuto ? "Fires automatically in" : "Confirm or cancel within"}
          </div>
          <div style="
            font-size:26px;font-weight:800;font-variant-numeric:tabular-nums;
            color:${accentClr};
            background:${accentBg};
            padding:4px 14px;border-radius:8px;
            min-width:80px;text-align:center;
            border:1.5px solid ${accentClr}33;
            letter-spacing:.02em;
          " id="cancel-countdown-${rule.id}">${graceMins}:00</div>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;">
          <button onclick="cancelPendingEvent(${rule.id},'${token || ""}')"
            style="padding:8px 20px;border-radius:8px;border:none;background:${accentClr};color:#fff;
                   font-size:13px;font-weight:700;cursor:pointer;flex-shrink:0;">
            ✕ Cancel Event
          </button>
          ${!isAuto ? `<button onclick="confirmSuggestedEvent(${rule.id})"
            style="padding:8px 20px;border-radius:8px;border:none;background:#16A34A;color:#fff;
                   font-size:13px;font-weight:700;cursor:pointer;flex-shrink:0;">
            ✓ Confirm Now
          </button>` : ""}
          <button onclick="showPendingEventDetail(${rule.id})"
            style="padding:8px 18px;border-radius:8px;border:1.5px solid ${accentClr};background:#fff;
                   color:${accentClr};font-size:13px;font-weight:700;cursor:pointer;flex-shrink:0;">
            📋 Pending Actions
          </button>
          <button onclick="hideCancellationBanner(${rule.id})"
            style="padding:8px 14px;border-radius:8px;border:1.5px solid #ddd;background:#f9f9f9;
                   color:#666;font-size:13px;cursor:pointer;flex-shrink:0;">
            Dismiss
          </button>
        </div>
      </div>
    </div>
    <!-- Progress bar -->
    <div style="margin-top:16px;height:4px;background:#eee;border-radius:2px;overflow:hidden;">
      <div id="cancel-progress-${rule.id}" style="height:100%;background:${accentClr};width:100%;
           border-radius:2px;transition:width 1s linear;"></div>
    </div>
  `;

  // Add pulse keyframes if not already added
  if (!document.getElementById("cancel-banner-styles")) {
    const style = document.createElement("style");
    style.id = "cancel-banner-styles";
    style.textContent = `
      @keyframes oadr3Pulse {
        0%,100% { box-shadow:0 12px 48px rgba(0,0,0,.28), 0 0 0 3px ${accentClr}; }
        50%      { box-shadow:0 12px 48px rgba(0,0,0,.28), 0 0 0 6px ${accentClr}66, 0 0 24px ${accentClr}44; }
      }
    `;
    document.head.appendChild(style);
  }

  document.body.appendChild(banner);

  const countdownEl = document.getElementById(`cancel-countdown-${rule.id}`);
  const progressEl  = document.getElementById(`cancel-progress-${rule.id}`);
  const totalSecs   = graceMins * 60;

  const ticker = setInterval(() => {
    remaining--;
    if (remaining <= 0) {
      clearInterval(ticker);
      hideCancellationBanner(rule.id);
      return;
    }
    const m = Math.floor(remaining / 60);
    const s = remaining % 60;
    if (countdownEl) countdownEl.textContent = `${m}:${String(s).padStart(2,"0")}`;
    if (progressEl)  progressEl.style.width  = `${(remaining / totalSecs) * 100}%`;
    // Keep remaining in sync for showPendingEventDetail
    if (activeCancellationTimers[rule.id]) activeCancellationTimers[rule.id].remaining = remaining;
  }, 1000);

  activeCancellationTimers[rule.id] = { ticker, token, rule, fv, tier, remaining };
}

function showPendingEventDetail(ruleId) {
  const pending = activeCancellationTimers[ruleId];
  if (!pending) return;
  const rule = pending.rule;
  const evType = rule.event_type || "switch";
  const typeLabels = { switch:"⚡ Switch / Relay", bas_di:"🏢 BAS Mode", ev:"🔌 EV Charger",
    battery:"🔋 Battery Backup", generator:"⚙️ Generator", openadr:"📡 OpenADR", hybrid:"🔀 Hybrid" };

  // Build a synthetic queue-style item from the rule
  const item = {
    name:             rule.name || "Autopilot Event",
    event_type:       evType,
    target_name:      rule.target_name || rule.target_id,
    target_type:      rule.target_type,
    relay_action:     rule.relay_action || "all_on",
    lc_mode:          rule.mode || "dlc",
    lc_strategy:      rule.strategy_val ? parseInt(rule.strategy_val.split("|")[0]) : null,
    lc_reps:          null,
    duration_minutes: rule.duration_mins || 60,
    fire_at:          new Date(Date.now() + (activeCancellationTimers[ruleId]?.remaining || 0) * 1000).toISOString(),
    status:           "pending",
    fired_at:         null
  };

  showEventDetail({ type:"pending", item });
}

function hideCancellationBanner(ruleId) {
  const existing = document.getElementById(`cancel-banner-${ruleId}`);
  if (existing) existing.remove();
  if (activeCancellationTimers[ruleId]) {
    clearInterval(activeCancellationTimers[ruleId].ticker);
    delete activeCancellationTimers[ruleId];
  }
}

async function cancelPendingEvent(ruleId, token) {
  hideCancellationBanner(ruleId);

  // Cancel autopilot timer if pending
  if (pendingAutopilotEvents[ruleId]) {
    clearTimeout(pendingAutopilotEvents[ruleId].timer);
    clearInterval(pendingAutopilotEvents[ruleId].countdown);
    delete pendingAutopilotEvents[ruleId];
  }

  // Mark token as cancelled in Supabase
  if (token) {
    try {
      await fetch(`${SUPABASE_URL}/rest/v1/pending_notifications?token=eq.${token}`, {
        method: "PATCH",
        headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
          "Content-Type": "application/json", "Prefer": "return=minimal" },
        body: JSON.stringify({ cancelled: true, cancelled_at: new Date().toISOString(), cancelled_by: currentUser?.email })
      });
    } catch(e) {}
  }

  // Update trigger log
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/monitor_trigger_log?rule_id=eq.${ruleId}&outcome=eq.pending`, {
      method: "PATCH",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json", "Prefer": "return=minimal" },
      body: JSON.stringify({ outcome: "cancelled", cancelled_by: currentUser?.email })
    });
  } catch(e) {}

  setStatus("ready", `Event cancelled for rule ${ruleId}`);
  loadTriggerLog();
  loadTriggerLogM();
}

function confirmSuggestedEvent(ruleId) {
  hideCancellationBanner(ruleId);
  const pending = pendingAutopilotEvents[ruleId];
  if (pending) {
    clearTimeout(pending.timer);
    clearInterval(pending.countdown);
    fireAutopilotEvent(pending.rule, pending.fv);
    delete pendingAutopilotEvents[ruleId];
  }
}



