// Legacy alias for backward compatibility
const UTILITY_DB = EIA_UTILITIES;

// Legacy — kept for backward compatibility
const UTILITY_PRESETS = {};

let configuredUtilities = []; // loaded from Supabase utility_outage_config
let outagePoller = null;
let corrChartInstance = null;
const OUTAGE_CONFIG_KEY = "lcp_outage_utilities_v1";

// ── Init ──────────────────────────────────────────────────────────────────────
async function initOutageTracker() {
  await loadConfiguredUtilities();

  // If no utilities configured yet, show a helpful state detection message
  if (!configuredUtilities.length) {
    const state = detectSiteState();
    const list  = document.getElementById("outage-utility-list");
    if (list && state) {
      const utils = EIA_UTILITIES[state] || [];
      const iouCount  = utils.filter(u => u.type === "iou").length;
      const coopCount = utils.filter(u => u.type === "coop").length;
      const muniCount = utils.filter(u => u.type === "muni").length;
      const pudCount  = utils.filter(u => u.type === "pud").length;
      list.innerHTML = `<div style="font-size:12px;color:var(--text-hint);padding:10px 0;">
        &#128205; Detected state: <strong>${state}</strong> — <strong>${utils.length}</strong> utilities on record.
        ${iouCount  ? `<span style="margin-right:8px;">&#9679; ${iouCount} IOU${iouCount!==1?"s":""}</span>` : ""}
        ${coopCount ? `<span style="margin-right:8px;">&#9679; ${coopCount} Co-op${coopCount!==1?"s":""}</span>` : ""}
        ${muniCount ? `<span style="margin-right:8px;">&#9679; ${muniCount} Muni${muniCount!==1?"s":""}</span>` : ""}
        ${pudCount  ? `<span style="margin-right:8px;">&#9679; ${pudCount} PUD${pudCount!==1?"s":""}</span>` : ""}
        <br/>Click <strong>+ Add Utility</strong> to select one, or enter a utility not in the list manually.
      </div>`;
    }
  }

  await refreshOutageData();
  await loadCorrelationChart();
  if (!outagePoller) {
    outagePoller = setInterval(() => {
      refreshOutageData();
    }, 15 * 60 * 1000);
  }
}

// ── Utility Configuration ─────────────────────────────────────────────────────
function toggleAddUtility() {
  const form = document.getElementById("add-utility-form");
  if (!form) return;
  const isOpen = form.style.display !== "none";
  form.style.display = isOpen ? "none" : "block";
  if (!isOpen) {
    // Auto-detect state from weather location or intake data
    const detectedState = detectSiteState();
    const stateEl = document.getElementById("new-util-state");
    const presetEl = document.getElementById("new-util-preset");
    if (stateEl) {
      stateEl.value = detectedState || "";
      if (detectedState) populateUtilityByState(detectedState);
    }
    if (presetEl) presetEl.selectedIndex = 0;
    const nameEl   = document.getElementById("new-util-name");
    const countyEl = document.getElementById("new-util-county");
    const mapEl    = document.getElementById("new-util-map-url");
    const odinEl   = document.getElementById("new-util-odin-id");
    const typeEl   = document.getElementById("new-util-type");
    if (nameEl)   nameEl.value   = "";
    if (countyEl) countyEl.value = "";
    if (mapEl)    mapEl.value    = "";
    if (odinEl)   odinEl.value   = "";
    if (typeEl)   typeEl.selectedIndex = 0;
  }
}

function detectSiteState() {
  // Try intake data first
  if (intakeData?.site?.state) return intakeData.site.state.toUpperCase().slice(0,2);
  // Try NWS station discovery — nwsStationId starts with K for CONUS
  // Try weather location data — NWS points API gave us state in county field
  // Fall back to nothing — let operator select
  return "";
}

function populateUtilityByState(state) {
  const sel = document.getElementById("new-util-preset");
  if (!sel || !state) return;
  const utils = (EIA_UTILITIES[state.toUpperCase()] || [])
    .slice()
    .sort((a, b) => a.name.localeCompare(b.name));

  if (!utils.length) {
    sel.innerHTML = `<option value="">No utilities on record for ${state} — enter manually below</option>`;
    return;
  }

  const TYPE_LABELS = { iou:"IOU", muni:"Muni", coop:"Co-op", pud:"PUD", federal:"Federal", other:"Other" };

  // Group by type for optgroups
  const groups = {};
  const ORDER  = ["iou","muni","coop","pud","federal","other"];
  utils.forEach((u, i) => {
    const t = u.type || "other";
    if (!groups[t]) groups[t] = [];
    groups[t].push({ u, i: (EIA_UTILITIES[state.toUpperCase()] || []).indexOf(u) });
  });

  let html = `<option value="">-- Select utility (${utils.length} found) --</option>`;
  ORDER.forEach(t => {
    if (!groups[t]?.length) return;
    html += `<optgroup label="${TYPE_LABELS[t] || t} (${groups[t].length})">`;
    html += groups[t].map(({ u, i }) =>
      `<option value="${i}">${u.name}</option>`
    ).join("");
    html += `</optgroup>`;
  });
  sel.innerHTML = html;
}

function applyUtilityPreset() {
  const stateEl = document.getElementById("new-util-state");
  const selEl   = document.getElementById("new-util-preset");
  const state   = stateEl?.value?.toUpperCase();
  const idx     = parseInt(selEl?.value);
  if (!state || isNaN(idx)) return;

  const utils = UTILITY_DB[state] || [];
  const u     = utils[idx];
  if (!u) return;

  const nameEl = document.getElementById("new-util-name");
  const mapEl  = document.getElementById("new-util-map-url");
  const odinEl = document.getElementById("new-util-odin-id");
  if (nameEl) nameEl.value = u.name  || "";
  if (mapEl)  mapEl.value  = u.mapUrl|| "";
  if (odinEl) odinEl.value = u.odinId|| "";

  // Set type directly from EIA_UTILITIES data
  const typeEl = document.getElementById("new-util-type");
  if (typeEl && u.type) typeEl.value = u.type;
}

function editUtility(id) {
  const u = configuredUtilities.find(x => String(x.id) === String(id));
  if (!u) return;

  // Store edit ID
  const form = document.getElementById("add-utility-form");
  if (!form) { toggleAddUtility(); return; }

  // Show form if hidden
  if (form.style.display === "none" || !form.style.display) toggleAddUtility();

  // Populate fields
  const setVal = (elId, val) => { const el = document.getElementById(elId); if (el) el.value = val || ""; };
  setVal("new-util-name",    u.utility_name);
  setVal("new-util-state",   u.state);
  setVal("new-util-county",  u.county);
  setVal("new-util-map-url", u.map_url || "");
  setVal("new-util-odin-id", u.odin_id || "");
  setVal("new-util-type",    u.utility_type || "iou");

  // Set edit mode
  let editInput = document.getElementById("util-edit-id");
  if (!editInput) {
    editInput = document.createElement("input");
    editInput.type = "hidden";
    editInput.id   = "util-edit-id";
    form.appendChild(editInput);
  }
  editInput.value = String(id);

  // Update form title and button
  const title = document.querySelector("#add-utility-form .sched-card-title");
  if (title) title.textContent = "✏️ Edit Utility";
  const saveBtn = document.querySelector("#add-utility-form button[onclick*='saveUtilityConfig']");
  if (saveBtn) saveBtn.textContent = "Save Changes";

  form.scrollIntoView({ behavior:"smooth" });
}

async function saveUtilityConfig() {
  const stateEl  = document.getElementById("new-util-state");
  const selEl    = document.getElementById("new-util-preset");
  const state    = stateEl?.value?.trim().toUpperCase();
  const selIdx   = parseInt(selEl?.value);
  const nameEl   = document.getElementById("new-util-name");
  const county   = document.getElementById("new-util-county")?.value?.trim();
  const mapUrl   = document.getElementById("new-util-map-url")?.value?.trim();
  const odinId   = document.getElementById("new-util-odin-id")?.value?.trim();
  const utilType = document.getElementById("new-util-type")?.value || "iou";

  if (!state) { setStatus("error", "Please select a state."); return; }

  // Name: from the explicit name field (required), auto-filled by preset or manual entry
  const name = nameEl?.value?.trim();
  if (!name) {
    setStatus("error", "Utility name is required. Enter the utility name or select from the known list.");
    return;
  }

  // Supplement with DB entry if a preset was selected
  const utils      = UTILITY_DB[state] || [];
  const util       = !isNaN(selIdx) && utils[selIdx] ? utils[selIdx] : null;
  const finalMapUrl= mapUrl || util?.mapUrl || "";   // empty string = no map
  const finalOdinId= odinId || util?.odinId || "";

  const record = {
    utility_name: name,
    utility_type: utilType,
    county:       county || state,
    state,
    map_url:      finalMapUrl || null,   // null = no public outage map
    odin_id:      finalOdinId || null,
    enabled:      true,
    added_at:     new Date().toISOString()
  };

  // Check if editing
  const editId = document.getElementById("util-edit-id")?.value;
  const isEdit = !!editId;

  // Try Supabase first, fall back to localStorage
  let savedToDb = false;
  try {
    const url    = isEdit && !String(editId).startsWith("local_")
      ? `${SUPABASE_URL}/rest/v1/utility_outage_config?id=eq.${editId}`
      : `${SUPABASE_URL}/rest/v1/utility_outage_config`;
    const method = isEdit && !String(editId).startsWith("local_") ? "PATCH" : "POST";
    const res = await fetch(url, {
      method,
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify(record)
    });
    if (res.ok) {
      savedToDb = true;
    } else {
      const err = await res.text();
      console.warn("Supabase utility save failed:", res.status, err);
    }
  } catch(e) {
    console.warn("Supabase utility save error:", e.message);
  }

  if (!savedToDb) {
    try {
      const existing = JSON.parse(localStorage.getItem(OUTAGE_CONFIG_KEY) || "[]");
      if (isEdit) {
        const idx = existing.findIndex(r => String(r.id) === String(editId));
        if (idx >= 0) existing[idx] = { ...existing[idx], ...record };
        else existing.push({ ...record, id: `local_${Date.now()}` });
      } else {
        existing.push({ ...record, id: `local_${Date.now()}` });
      }
      localStorage.setItem(OUTAGE_CONFIG_KEY, JSON.stringify(existing));
    } catch(e) {
      setStatus("error", "Failed to save utility: " + e.message);
      return;
    }
  }

  // Reset edit mode
  const editInput = document.getElementById("util-edit-id");
  if (editInput) editInput.value = "";
  const title = document.querySelector("#add-utility-form .sched-card-title");
  if (title) title.textContent = "➕ Add Utility";
  const saveBtn = document.querySelector("#add-utility-form button[onclick*='saveUtilityConfig']");
  if (saveBtn) saveBtn.textContent = "Save Utility";

  setStatus("ready", `${name} ${isEdit ? "updated" : "added"} successfully.`);
  toggleAddUtility();
  await loadConfiguredUtilities();
  await refreshOutageData();
}

async function loadConfiguredUtilities() {
  let dbRows = [];
  let localRows = [];

  // Try Supabase
  try {
    const rows = await supabaseGet("utility_outage_config?enabled=eq.true&order=added_at.asc");
    if (Array.isArray(rows) && rows.length > 0) {
      dbRows = rows;
    }
  } catch(e) {
    console.warn("loadConfiguredUtilities Supabase:", e.message);
  }

  // Also check localStorage (for entries saved before SQL was run)
  try {
    const saved = localStorage.getItem(OUTAGE_CONFIG_KEY);
    if (saved) localRows = JSON.parse(saved);
  } catch(e) {}

  // Merge — prefer DB rows, supplement with local-only entries
  const dbNames = new Set(dbRows.map(r => r.utility_name));
  const localOnly = localRows.filter(r => !dbNames.has(r.utility_name));
  configuredUtilities = [...dbRows, ...localOnly];

  renderUtilityList();
}

function renderUtilityList() {
  const list = document.getElementById("outage-utility-list");
  if (!list) return;
  if (!configuredUtilities.length) {
    list.innerHTML = '<div class="sched-empty">No utilities configured. Click + Add Utility to begin.</div>';
    return;
  }

  const TYPE_LABELS = {
    iou:"IOU", muni:"Municipal", coop:"Co-op", pud:"PUD", federal:"Federal", other:"Other"
  };
  const TYPE_COLORS = {
    iou:"var(--blue-dark)", muni:"var(--green-dark)", coop:"#7b4f9e",
    pud:"var(--amber)", federal:"#c0392b", other:"var(--text-secondary)"
  };

  list.innerHTML = configuredUtilities.map(u => {
    const utilType  = u.utility_type || "iou";
    const typeLabel = TYPE_LABELS[utilType] || utilType;
    const typeColor = TYPE_COLORS[utilType] || "var(--text-secondary)";
    const hasMap    = !!u.map_url;
    const count   = u._outageCount;
    const total   = u._customersTotal;
    const pct     = u._pctOut;
    const age     = u._lastUpdated ? Math.round((Date.now() - new Date(u._lastUpdated).getTime()) / 60000) : null;
    const badgeClass = count == null ? "" : count === 0 ? "outage-count-none" : count < 100 ? "outage-count-low" : "outage-count-high";


    const badgeFinal = count != null
      ? `<span class="outage-count-badge ${badgeClass}">${count.toLocaleString()} out${pct ? ` (${pct}%)` : ""}</span>`
      : `<span class="outage-count-badge" style="background:var(--surface2);color:var(--text-hint);">—</span>`;

    return `<div class="outage-util-card${!u.map_url ? ' no-map-card' : ''}" onclick="${u.map_url ? `openOutageMap('${u.map_url}','${u.utility_name}')` : ''}">
      <div class="outage-util-icon">&#9889;</div>
      <div class="outage-util-info">
        <div class="outage-util-name">
          ${u.utility_name}
          <span style="font-size:10px;font-weight:700;padding:1px 7px;border-radius:8px;border:0.5px solid ${typeColor};color:${typeColor};background:${typeColor}18;margin-left:6px;">${typeLabel}</span>
        </div>
        <div class="outage-util-meta">${u.county || ""} &bull; ${u.state} ${age != null ? `&bull; Updated ${age < 2 ? "just now" : age + " min ago"}` : ""}</div>
        ${u.map_url
          ? `<div style="font-size:10px;color:var(--blue-dark);margin-top:2px;">&#128279; Click to open outage map</div>`
          : `<div style="font-size:10px;color:var(--text-hint);margin-top:2px;">&#128683; No public outage map — data tracking only</div>`
        }
      </div>
      ${badgeFinal}
      <div style="display:flex;flex-direction:column;gap:4px;flex-shrink:0;">
        <button onclick="event.stopPropagation();editUtility('${u.id}')" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--blue-dark);background:none;color:var(--blue-dark);font-size:10px;cursor:pointer;white-space:nowrap;">✏️ Edit</button>
        <button onclick="event.stopPropagation();removeUtility('${u.id}')" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;white-space:nowrap;">✕ Remove</button>
      </div>
    </div>`;
  }).join("");
}

function openOutageMap(url, name) {
  if (!url) return; // card is not clickable when no map URL
  window.open(url, "_blank", "noopener,noreferrer");
}

async function removeUtility(id) {
  if (!confirm("Remove this utility from outage tracking?")) return;

  // Remove from Supabase (numeric IDs)
  if (!String(id).startsWith("local_")) {
    try {
      await fetch(`${SUPABASE_URL}/rest/v1/utility_outage_config?id=eq.${id}`, {
        method: "DELETE",
        headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}` }
      });
    } catch(e) { console.warn("removeUtility Supabase:", e.message); }
  }

  // Always remove from localStorage (catches both local-only and belt-and-suspenders)
  try {
    const key    = OUTAGE_CONFIG_KEY;
    const stored = JSON.parse(localStorage.getItem(key) || "[]");
    const filtered = stored.filter(u => String(u.id) !== String(id));
    localStorage.setItem(key, JSON.stringify(filtered));
  } catch(e) { console.warn("removeUtility localStorage:", e.message); }

  await loadConfiguredUtilities();
}

// ── Outage Data Refresh ────────────────────────────────────────────────────────
async function refreshOutageData() {
  if (!configuredUtilities.length) return;
  await fetchODINData();
}

async function fetchODINData() {
  const odinList = document.getElementById("odin-county-list");
  const lastEl   = document.getElementById("outage-last-updated");
  if (odinList) odinList.innerHTML = '<div class="sched-empty">Fetching ODIN data…</div>';

  if (!configuredUtilities.length) {
    if (odinList) odinList.innerHTML = '<div class="sched-empty">Configure a utility above to load ODIN county data.</div>';
    return;
  }

  const allCounties = [];

  // Query per utility through worker (handles CORS + better name matching)
  for (const u of configuredUtilities) {
    try {
      const res  = await fetch(`${PROXY_URL}utility/odin`, {
        method:  "POST",
        headers: { "Content-Type": "application/json" },
        body:    JSON.stringify({ utility_name: u.utility_name, state: u.state, odin_id: u.odin_id || null })
      });
      const data = await res.json();
      if (data.ok) {
        u._outageCount    = data.total_out ?? 0;
        u._customersTotal = data.total_customers || null;
        u._pctOut         = data.pct_out != null ? data.pct_out : null;
        u._lastUpdated    = data.last_updated || new Date().toISOString();
        allCounties.push(...(data.counties || []).map(c => ({ ...c, _utility: u.utility_name })));
      } else {
        console.warn(`ODIN no data for ${u.utility_name}:`, data.error);
        u._outageCount = 0;
        u._lastUpdated = new Date().toISOString();
      }
    } catch(e) {
      console.warn(`ODIN fetch error for ${u.utility_name}:`, e.message);
      u._outageCount = 0;
    }
  }

  renderUtilityList();

  // Render ODIN county breakdown
  if (odinList) {
    if (!allCounties.length) {
      odinList.innerHTML = `<div class="sched-empty">
        No active outages found in ODIN for configured utilities.<br>
        <span style="font-size:10px;color:var(--text-hint);">
          ODIN only shows utilities actively pushing data to DOE/Oak Ridge National Lab.
          If a utility participates but shows no data, they may not have active outages
          or may not yet be transmitting live data.
        </span>
      </div>`;
    } else {
      const sorted = allCounties.sort((a,b) => b.out - a.out);
      odinList.innerHTML = `
        <table style="width:100%;border-collapse:collapse;font-size:11px;">
          <thead><tr>
            <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">County</th>
            <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Utility</th>
            <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Customers Out</th>
            <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">% Out</th>
            <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Updated</th>
          </tr></thead>
          <tbody>${sorted.map(r => {
            const pctColor = (r.pct||0) > 5 ? "var(--red)" : (r.pct||0) > 1 ? "var(--amber)" : "var(--text-primary)";
            return `<tr>
              <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-weight:600;">${r.county}, ${r.state}</td>
              <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);color:var(--text-secondary);">${r._utility || "—"}</td>
              <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;font-weight:700;color:var(--red);">${r.out.toLocaleString()}</td>
              <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-weight:600;color:${pctColor};">${r.pct != null ? r.pct+"%" : "—"}</td>
              <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;color:var(--text-hint);">${r.updated ? new Date(r.updated).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}) : "—"}</td>
            </tr>`;
          }).join("")}
          </tbody>
        </table>`;
    }
  }

  if (lastEl) lastEl.textContent = `ODIN updated: ${new Date().toLocaleTimeString()}`;
}


// ── Correlation Chart ──────────────────────────────────────────────────────────// ── Correlation Chart ──────────────────────────────────────────────────────────
async function loadCorrelationChart() {
  const rangeHrs = parseInt(document.getElementById("corr-range")?.value || "24");
  const since    = new Date(Date.now() - rangeHrs * 60 * 60 * 1000).toISOString();
  const statsEl  = document.getElementById("corr-stats");
  const eventsEl = document.getElementById("corr-events-list");
  const ctx      = document.getElementById("outage-corr-chart");
  if (!ctx) return;

  try {
    // Fetch outage readings
    const outageRows = await supabaseGet(
      `outage_readings?recorded_at=gte.${encodeURIComponent(since)}&order=recorded_at.asc&limit=2000`
    ).catch(() => []);

    // Fetch device health (offline events — no report in 2+ hours)
    const healthRows = await supabaseGet(
      `device_health?recorded_at=gte.${encodeURIComponent(since)}&order=recorded_at.asc&limit=2000`
    ).catch(() => []);

    if (!Array.isArray(outageRows) || !outageRows.length) {
      if (ctx.getContext) {
        const c = ctx.getContext("2d");
        c.clearRect(0, 0, ctx.width, ctx.height);
      }
      if (statsEl) statsEl.innerHTML = '<div class="sched-empty">No outage data recorded yet. Data is collected every 15 minutes when utilities are configured.</div>';
      if (eventsEl) eventsEl.innerHTML = "";
      return;
    }

    // Aggregate outage counts by hour
    const hourBuckets = {};
    outageRows.forEach(r => {
      const h = new Date(r.recorded_at);
      h.setMinutes(0, 0, 0);
      const key = h.toISOString();
      if (!hourBuckets[key]) hourBuckets[key] = 0;
      hourBuckets[key] = Math.max(hourBuckets[key], r.customers_out || 0);
    });

    // Count offline device events by hour
    const deviceOfflineByHour = {};
    if (Array.isArray(healthRows)) {
      healthRows.forEach(r => {
        const age = r.recorded_at ? (Date.now() - new Date(r.recorded_at).getTime()) / 3600000 : 99;
        if (age > 2) { // offline if no report in 2+ hours
          const h = new Date(r.recorded_at);
          h.setMinutes(0, 0, 0);
          const key = h.toISOString();
          if (!deviceOfflineByHour[key]) deviceOfflineByHour[key] = 0;
          deviceOfflineByHour[key]++;
        }
      });
    }

    const sortedKeys  = Object.keys(hourBuckets).sort();
    const labels      = sortedKeys.map(k => {
      const d = new Date(k);
      return rangeHrs <= 24
        ? d.toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})
        : d.toLocaleDateString([], {month:"short",day:"numeric",hour:"2-digit"});
    });
    const outageData  = sortedKeys.map(k => hourBuckets[k]);
    const deviceData  = sortedKeys.map(k => deviceOfflineByHour[k] || 0);

    // Peak stats
    const peakOut    = Math.max(...outageData);
    const totalObs   = outageRows.length;
    const correlated = sortedKeys.filter(k => hourBuckets[k] > 0 && deviceOfflineByHour[k] > 0).length;

    if (statsEl) {
      statsEl.innerHTML = `
        <span class="outage-stat-pill">&#9889; Peak: <strong style="margin-left:4px;">${peakOut.toLocaleString()} customers out</strong></span>
        <span class="outage-stat-pill">&#128202; ${totalObs} readings recorded</span>
        ${correlated > 0 ? `<span class="outage-stat-pill" style="background:var(--red-lt);border-color:var(--red);color:var(--red);">&#9888;&#65039; ${correlated} hour${correlated!==1?"s":""} with both outages + offline devices</span>` : '<span class="outage-stat-pill" style="background:var(--green-bg);border-color:var(--green);color:var(--green-dark);">&#10003; No correlated outage/device events</span>'}`;
    }

    if (corrChartInstance) { corrChartInstance.destroy(); corrChartInstance = null; }

    corrChartInstance = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [
          {
            label: "Customers Without Power",
            data: outageData,
            borderColor: "#c0392b",
            backgroundColor: "rgba(192,57,43,0.1)",
            borderWidth: 2,
            pointRadius: outageData.length > 50 ? 0 : 3,
            tension: 0.3,
            fill: true,
            yAxisID: "y"
          },
          {
            label: "Offline Devices",
            data: deviceData,
            borderColor: "#e67e22",
            backgroundColor: "rgba(230,126,34,0.15)",
            borderWidth: 2,
            pointRadius: deviceData.length > 50 ? 0 : 3,
            tension: 0.3,
            fill: true,
            yAxisID: "y1"
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: "index", intersect: false },
        plugins: {
          legend: { display: true, position: "top", labels: { font: { size: 11 } } },
          tooltip: {
            callbacks: {
              label: ctx => ctx.dataset.label + ": " + ctx.parsed.y.toLocaleString()
            }
          }
        },
        scales: {
          x:  { ticks: { maxTicksLimit: 10, font: { size: 10 }, color: "#888780" }, grid: { color: "rgba(0,0,0,0.05)" } },
          y:  { type: "linear", display: true, position: "left",  title: { display: true, text: "Customers Out", font: { size: 10 } }, ticks: { font: { size: 10 }, color: "#c0392b" }, grid: { color: "rgba(0,0,0,0.05)" } },
          y1: { type: "linear", display: true, position: "right", title: { display: true, text: "Offline Devices", font: { size: 10 } }, ticks: { font: { size: 10 }, color: "#e67e22" }, grid: { drawOnChartArea: false } }
        }
      }
    });
    if (chartInstances) chartInstances["outage-corr-chart"] = corrChartInstance;

    // Show correlated events
    if (eventsEl && correlated > 0) {
      const corrKeys = sortedKeys.filter(k => hourBuckets[k] > 0 && deviceOfflineByHour[k] > 0);
      eventsEl.innerHTML = `<div style="font-size:11px;font-weight:600;color:var(--text-hint);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;font-family:monospace;">Correlated Events</div>` +
        corrKeys.map(k => `<div style="font-size:12px;padding:6px 10px;background:var(--red-lt);border-radius:var(--radius-sm);margin-bottom:4px;display:flex;justify-content:space-between;">
          <span>&#9888;&#65039; ${new Date(k).toLocaleString([], {month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}</span>
          <span style="color:var(--red);font-weight:600;">${hourBuckets[k].toLocaleString()} out &bull; ${deviceOfflineByHour[k]} device${deviceOfflineByHour[k]!==1?"s":""} offline</span>
        </div>`).join("");
    } else if (eventsEl) {
      eventsEl.innerHTML = "";
    }

  } catch(e) {
    console.error("loadCorrelationChart:", e);
    if (statsEl) statsEl.innerHTML = `<span style="color:var(--red);font-size:12px;">Error: ${e.message}</span>`;
  }
}



// ── SCADA Data System ─────────────────────────────────────────────────────────

let scadaSources      = [];   // configured data sources
let scadaPoints       = [];   // configured data points
let scadaTerritories  = [];   // territory hierarchy
let scadaLiveData     = {};   // { pointId: { value, timestamp, quality, unit } }
let scadaPoller       = null;
let scadaTrendChart   = null;
let selectedSCADAProto = null;

// ── Init ──────────────────────────────────────────────────────────────────────
async function initSCADA() {
  // Update webhook URL with actual worker URL
  const whu = document.getElementById("scada-webhook-url");
  if (whu) whu.textContent = `POST ${PROXY_URL}scada/ingest`;

  await loadSCADATerritories();
  await loadSCADASources();
  await loadSCADAPointMap();
  await refreshSCADADisplay();
  await loadSCADAAlarms();

  if (!scadaPoller) {
    // Poll REST sources every 30 seconds for live display
    // Record to DB on 15-minute boundary
    scadaPoller = setInterval(async () => {
      await pollSCADAREST();
      await refreshSCADADisplay();
      const now = new Date();
      if (now.getMinutes() % 15 === 0 && now.getSeconds() < 35) {
        await recordSCADASnapshot();
      }
    }, 30000);
  }
}

// ── Protocol Selection ────────────────────────────────────────────────────────
function selectSCADAProto(proto, el) {
  selectedSCADAProto = proto;
  document.querySelectorAll(".scada-proto-opt").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface)";
  });
  if (el) { el.style.borderColor = "var(--green)"; el.style.background = "var(--green-bg)"; }

  // Show relevant config panel
  ["rest","webhook","mqtt_ws","opcua_rest","csv_upload","dnp3_gw","modbus_gw","iec61850_gw"].forEach(p => {
    const panel = document.getElementById(`scada-proto-${p}`);
    if (panel) panel.style.display = "none";
  });
  const active = document.getElementById(`scada-proto-${proto}`);
  if (active) active.style.display = "block";
}

function toggleSCADASourceForm() {
  const form = document.getElementById("scada-source-form");
  if (!form) return;
  const isOpen = form.style.display !== "none";
  form.style.display = isOpen ? "none" : "block";
  if (!isOpen) {
    populateSCADATerritorySelect();
    // Reset protocol selection visual state
    document.querySelectorAll(".scada-proto-opt").forEach(b => {
      b.style.borderColor = "var(--border-md)";
      b.style.background  = "var(--surface)";
    });
    document.getElementById("scada-src-name").value = "";
    ["scada-proto-rest","scada-proto-webhook","scada-proto-mqtt_ws","scada-proto-opcua_rest","scada-proto-csv_upload","scada-proto-dnp3_gw","scada-proto-modbus_gw","scada-proto-iec61850_gw"].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = "none";
    });
  }
}

function toggleSCADATerritoryForm() {
  const form = document.getElementById("scada-territory-form");
  if (!form) return;
  form.style.display = form.style.display === "none" ? "block" : "none";
}

// ── Territory ─────────────────────────────────────────────────────────────────
async function saveSCADATerritory() {
  const name         = document.getElementById("scada-terr-name")?.value?.trim();
  const utility      = document.getElementById("scada-terr-utility")?.value?.trim();
  const substations  = document.getElementById("scada-terr-substations")?.value?.trim();
  const transmission = document.getElementById("scada-terr-transmission")?.value?.trim();
  const distribution = document.getElementById("scada-terr-distribution")?.value?.trim();
  if (!name) { setStatus("error", "Territory name required."); return; }

  const record = {
    name, utility: utility||null,
    substations:  substations  ? substations.split(",").map(s=>s.trim())  : [],
    transmission: transmission ? transmission.split(",").map(s=>s.trim()) : [],
    distribution: distribution ? distribution.split(",").map(s=>s.trim()) : [],
    created_at: new Date().toISOString()
  };

  try {
    await supabasePost("scada_territories", record);
    setStatus("ready", `Territory "${name}" saved.`);
    toggleSCADATerritoryForm();
    await loadSCADATerritories();
  } catch(e) { setStatus("error", "Failed to save territory: " + e.message); }
}

async function loadSCADATerritories() {
  const list = document.getElementById("scada-territory-list");
  try {
    const rows = await supabaseGet("scada_territories?order=created_at.asc");
    scadaTerritories = Array.isArray(rows) ? rows : [];
  } catch(e) { scadaTerritories = []; }

  if (!list) return;
  if (!scadaTerritories.length) {
    list.innerHTML = '<div class="sched-empty">No territories defined. Define your service territory hierarchy to organize SCADA data points.</div>';
    return;
  }

  list.innerHTML = scadaTerritories.map(t => `
    <div style="padding:12px 14px;border:0.5px solid var(--border-md);border-radius:var(--radius-sm);margin-bottom:8px;background:var(--surface);">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
        <div>
          <span style="font-size:13px;font-weight:600;color:var(--text-primary);">&#127968; ${t.name}</span>
          ${t.utility ? `<span style="font-size:11px;color:var(--text-hint);margin-left:8px;">${t.utility}</span>` : ""}
        </div>
        <button onclick="deleteSCADATerritory(${t.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;">
        ${(t.substations||[]).map(s=>`<span class="scada-hier-node" title="Substation">🔌 ${s}</span>`).join("")}
        ${(t.transmission||[]).map(s=>`<span class="scada-hier-node" title="Transmission">⚡ ${s}</span>`).join("")}
        ${(t.distribution||[]).map(s=>`<span class="scada-hier-node" title="Distribution">🔆 ${s}</span>`).join("")}
      </div>
    </div>`).join("");
}

function populateSCADATerritorySelect() {
  const sel = document.getElementById("scada-src-territory");
  if (!sel) return;
  sel.innerHTML = '<option value="">-- None --</option>' +
    scadaTerritories.map(t => `<option value="${t.id}">${t.name}</option>`).join("");
}

async function deleteSCADATerritory(id) {
  if (!confirm("Remove this territory?")) return;
  await fetch(`${SUPABASE_URL}/rest/v1/scada_territories?id=eq.${id}`, {
    method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
  });
  await loadSCADATerritories();
}

// ── Sources ───────────────────────────────────────────────────────────────────
async function saveSCADASource() {
  if (!selectedSCADAProto) { setStatus("error", "Select a protocol/intake method."); return; }
  const name = document.getElementById("scada-src-name")?.value?.trim();
  if (!name) { setStatus("error", "Source name required."); return; }

  const protoConfig = {};
  if (selectedSCADAProto === "rest_poll") {
    protoConfig.url      = document.getElementById("scada-rest-url")?.value?.trim();
    protoConfig.auth     = document.getElementById("scada-rest-auth")?.value;
    protoConfig.interval = parseInt(document.getElementById("scada-rest-interval")?.value || "900");
    if (!protoConfig.url) { setStatus("error", "Endpoint URL required."); return; }
  }
  if (selectedSCADAProto === "mqtt_ws") {
    protoConfig.url   = document.getElementById("scada-mqtt-url")?.value?.trim();
    protoConfig.topic = document.getElementById("scada-mqtt-topic")?.value?.trim();
    if (!protoConfig.url) { setStatus("error", "Broker URL required."); return; }
  }
  if (selectedSCADAProto === "opcua_rest") {
    protoConfig.url   = document.getElementById("scada-opc-url")?.value?.trim();
    protoConfig.nodes = document.getElementById("scada-opc-nodes")?.value?.trim();
  }

  const recordTypes = Array.from(document.getElementById("scada-record-types")?.selectedOptions || []).map(o => o.value);

  const record = {
    name,
    protocol:        selectedSCADAProto,
    territory_id:    document.getElementById("scada-src-territory")?.value || null,
    config:          JSON.stringify(protoConfig),
    record_interval: parseInt(document.getElementById("scada-record-interval")?.value || "900"),
    retention_days:  parseInt(document.getElementById("scada-retention")?.value || "90"),
    record_types:    JSON.stringify(recordTypes),
    enabled:         true,
    status:          "configured",
    created_at:      new Date().toISOString()
  };

  // Try Supabase first, fall back to localStorage
  let savedToDb = false;
  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/scada_sources`, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type": "application/json",
        "Prefer": "return=representation"
      },
      body: JSON.stringify(record)
    });
    if (res.ok) {
      savedToDb = true;
    } else {
      const err = await res.text();
      console.warn("SCADA source save failed:", res.status, err);
    }
  } catch(e) {
    console.warn("SCADA source save error:", e.message);
  }

  if (!savedToDb) {
    // Fall back to localStorage
    try {
      const key = "lcp_scada_sources_v1";
      const existing = JSON.parse(localStorage.getItem(key) || "[]");
      existing.push({ ...record, id: Date.now(), record_types: recordTypes });
      localStorage.setItem(key, JSON.stringify(existing));
      console.log("SCADA source saved to localStorage (run SQL to create scada_sources table)");
    } catch(e2) {
      setStatus("error", "Failed to save source: " + e2.message);
      return;
    }
  }

  setStatus("ready", `SCADA source "${name}" saved.`);

  // Hide the form first, then reload
  const form = document.getElementById("scada-source-form");
  if (form) form.style.display = "none";
  selectedSCADAProto = null;

  // Reset protocol visual state
  document.querySelectorAll(".scada-proto-opt").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface)";
  });

  await loadSCADASources();
}

async function loadSCADASources() {
  const list = document.getElementById("scada-source-list");
  const filter = document.getElementById("scada-point-source-filter");

  let dbRows = [];
  let localRows = [];

  try {
    const rows = await supabaseGet("scada_sources?enabled=eq.true&order=created_at.asc");
    if (Array.isArray(rows) && rows.length) dbRows = rows;
  } catch(e) { console.warn("loadSCADASources:", e.message); }

  try {
    const saved = localStorage.getItem("lcp_scada_sources_v1");
    if (saved) localRows = JSON.parse(saved);
  } catch(e) {}

  // Merge — DB takes priority, supplement with local-only
  const dbNames = new Set(dbRows.map(r => r.name));
  const localOnly = localRows.filter(r => !dbNames.has(r.name));
  scadaSources = [...dbRows, ...localOnly];

  // Normalize record_types — may be string or array
  scadaSources = scadaSources.map(s => ({
    ...s,
    record_types: typeof s.record_types === "string"
      ? (() => { try { return JSON.parse(s.record_types); } catch(e) { return ["analog","alarm","status","derived"]; } })()
      : (s.record_types || ["analog","alarm","status","derived"])
  }));

  if (filter) {
    filter.innerHTML = '<option value="">All Sources</option>' +
      scadaSources.map(s => `<option value="${s.id}">${s.name}</option>`).join("");
  }

  const PROTO_LABELS = {
    rest_poll:"REST/JSON", webhook:"Webhook/POST", mqtt_ws:"MQTT/WS",
    opcua_rest:"OPC-UA REST", csv_upload:"CSV Upload",
    dnp3_gw:"DNP3 Gateway", modbus_gw:"Modbus Gateway", iec61850_gw:"IEC 61850"
  };

  // Build HTML regardless of whether element is currently visible
  const renderSources = () => {
    const el = document.getElementById("scada-source-list");
    if (!el) return;
    if (!scadaSources.length) {
      el.innerHTML = '<div class="sched-empty">No data sources configured. Click + Add Source to add one.</div>';
      return;
    }
    el.innerHTML = scadaSources.map(s => {
    const cfg = (() => { try { return JSON.parse(s.config||"{}"); } catch(e) { return {}; } })();
    const territory = scadaTerritories.find(t => t.id == s.territory_id);
    return `<div class="scada-source-card">
      <div class="scada-source-status ${s.status === "active" ? "active" : s.status === "error" ? "error" : "inactive"}"></div>
      <div style="flex:1;min-width:0;">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">
          <span style="font-size:13px;font-weight:600;color:var(--text-primary);">${s.name}</span>
          <span class="scada-proto-badge">${PROTO_LABELS[s.protocol]||s.protocol}</span>
          ${territory ? `<span style="font-size:10px;color:var(--text-hint);">&#127968; ${territory.name}</span>` : ""}
        </div>
        <div style="font-size:11px;color:var(--text-hint);">
          ${cfg.url ? `&#128279; ${cfg.url} &bull; ` : ""}
          Record every ${Math.round((s.record_interval||900)/60)} min &bull; Keep ${s.retention_days||90} days
        </div>
        ${s.protocol === "webhook" ? `<div style="font-size:10px;color:var(--text-hint);margin-top:3px;font-family:monospace;">POST ${PROXY_URL}scada/ingest</div>` : ""}
      </div>
      <div style="display:flex;gap:6px;flex-shrink:0;">
        <button onclick="testSCADASource(${s.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--border-md);background:var(--surface2);font-size:10px;cursor:pointer;">Test</button>
        <button onclick="removeSCADASource(${s.id})" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
      </div>
    </div>`;
    }).join("");
  }; // end renderSources

  renderSources();

  // Also update point source filter dropdown
  const filterEl = document.getElementById("scada-point-source-filter");
  if (filterEl) {
    filterEl.innerHTML = '<option value="">All Sources</option>' +
      scadaSources.map(s => `<option value="${s.id}">${s.name}</option>`).join("");
  }
}

async function testSCADASource(id) {
  const src = scadaSources.find(s => s.id === id);
  if (!src) return;
  setStatus("ready", `Testing connection to ${src.name}...`);
  try {
    const cfg = JSON.parse(src.config || "{}");
    if (src.protocol === "rest_poll" && cfg.url) {
      const res = await fetch(PROXY_URL + "scada/test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: cfg.url, auth: cfg.auth })
      });
      const data = await res.json();
      setStatus("ready", `${src.name}: ${data.ok ? "✅ Connected" : "⚠️ " + (data.error||data.status)}`);
    } else if (src.protocol === "webhook") {
      setStatus("ready", `${src.name}: Webhook — waiting for incoming POST to ${PROXY_URL}scada/ingest`);
    } else {
      setStatus("ready", `${src.name}: Test not available for ${src.protocol} sources`);
    }
  } catch(e) { setStatus("error", `Test failed: ${e.message}`); }
}

async function removeSCADASource(id) {
  if (!confirm("Remove this SCADA source? Associated data points will be orphaned.")) return;
  await fetch(`${SUPABASE_URL}/rest/v1/scada_sources?id=eq.${id}`, {
    method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
  });
  await loadSCADASources();
}

// ── Data Points ───────────────────────────────────────────────────────────────
function showAddPointModal() {
  // Simple inline prompt for now — full modal can be added if needed
  const srcId = document.getElementById("scada-point-source-filter")?.value;
  const id    = prompt("Point ID / Tag Name (e.g. SUB1_VOLT_AN):");
  if (!id) return;
  const name  = prompt("Display Name (e.g. Substation 1 Voltage A-N):");
  if (!name) return;
  const type  = prompt("Point Type: analog / status / count / alarm / derived", "analog");
  const unit  = prompt("Unit (e.g. kV, A, MW, %):", "");

  addSCADAPoint({ source_id: srcId||null, point_id: id, name, type: type||"analog", unit: unit||"", lo_limit: null, hi_limit: null, enabled: true });
}

async function addSCADAPoint(point) {
  try {
    await supabasePost("scada_points", { ...point, created_at: new Date().toISOString() });

    // Auto-register as a monitor feed so it appears in the rules engine
    const feedKey = `scada_${point.point_id}`;
    const existing = await supabaseGet(`monitor_feeds?feed_key=eq.${encodeURIComponent(feedKey)}&limit=1`).catch(() => []);
    if (!Array.isArray(existing) || !existing.length) {
      const src = scadaSources.find(s => s.id == point.source_id);
      await supabasePost("monitor_feeds", {
        feed_key:         feedKey,
        label:            point.name,
        unit:             point.unit || "",
        interval_minutes: 15,
        auth_required:    false,
        endpoint_url:     null,
        enabled:          true,
        added_at:         new Date().toISOString()
      }).catch(e => console.warn("SCADA feed registration:", e.message));
    }

    await loadSCADAPointMap();
    await populateSCADATrendSelector();
    setStatus("ready", `Point "${point.name}" added and registered as monitor feed.`);
  } catch(e) { setStatus("error", "Failed to add point: " + e.message); }
}

async function loadSCADAPointMap() {
  const list  = document.getElementById("scada-point-map-list");
  const srcId = document.getElementById("scada-point-source-filter")?.value;
  try {
    const q = srcId ? `scada_points?source_id=eq.${srcId}&order=type.asc,name.asc` : "scada_points?order=type.asc,name.asc";
    const rows = await supabaseGet(q);
    scadaPoints = Array.isArray(rows) ? rows : [];
  } catch(e) { scadaPoints = []; }

  if (!list) return;
  if (!scadaPoints.length) {
    list.innerHTML = '<div class="sched-empty">No data points configured. Click + Add Point to define a SCADA tag to monitor.</div>';
    return;
  }

  const typeColors = { analog:"var(--blue-dark)", status:"var(--green-dark)", count:"var(--amber)", alarm:"var(--red)", derived:"var(--ink-3)" };
  const typeIcons  = { analog:"〰", status:"⊙", count:"#", alarm:"🔔", derived:"∑" };

  list.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:11px;">
    <thead><tr>
      <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Type</th>
      <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Tag / Point ID</th>
      <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Display Name</th>
      <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Current Value</th>
      <th style="text-align:center;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Quality</th>
      <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);"></th>
    </tr></thead>
    <tbody>${scadaPoints.map(p => {
      const live = scadaLiveData[p.point_id];
      const val  = live?.value != null ? `${live.value} ${p.unit||""}` : "—";
      const qual = live?.quality || "—";
      const qualColor = qual === "good" ? "var(--green-dark)" : qual === "bad" ? "var(--red)" : "var(--text-hint)";
      return `<tr>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">
          <span style="font-size:11px;font-weight:700;color:${typeColors[p.type]||"var(--text-primary)"};">${typeIcons[p.type]||"?"} ${p.type}</span>
        </td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-family:monospace;font-size:10px;color:var(--text-secondary);">${p.point_id}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-weight:600;">${p.name}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;font-weight:700;">${val}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:center;color:${qualColor};font-size:10px;">${qual}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;">
          <button onclick="removeSCADAPoint(${p.id})" style="padding:2px 7px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">✕</button>
        </td>
      </tr>`;
    }).join("")}</tbody></table>`;

  await populateSCADATrendSelector();
}

async function removeSCADAPoint(id) {
  if (!confirm("Remove this data point?")) return;
  await fetch(`${SUPABASE_URL}/rest/v1/scada_points?id=eq.${id}`, {
    method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
  });
  await loadSCADAPointMap();
}

// ── Live Display ──────────────────────────────────────────────────────────────
async function refreshSCADADisplay() {
  const grid = document.getElementById("scada-points-grid");
  const updEl = document.getElementById("scada-last-updated");
  const badge = document.getElementById("scada-live-badge");

  if (!scadaPoints.length) return;

  // Get latest readings from DB for each point
  const since = new Date(Date.now() - 20 * 60 * 1000).toISOString(); // last 20 min
  try {
    const rows = await supabaseGet(
      `scada_readings?recorded_at=gte.${encodeURIComponent(since)}&order=recorded_at.desc&limit=500`
    );
    if (Array.isArray(rows)) {
      rows.forEach(r => {
        if (!scadaLiveData[r.point_id] || new Date(r.recorded_at) > new Date(scadaLiveData[r.point_id].timestamp)) {
          scadaLiveData[r.point_id] = { value:r.value, timestamp:r.recorded_at, quality:r.quality||"good", unit:r.unit||"" };
        }
      });
    }
  } catch(e) {}

  if (!grid) return;

  const activeType = document.querySelector(".scada-filter-btn.active")?.dataset?.type || "all";
  const filtered   = activeType === "all" ? scadaPoints : scadaPoints.filter(p => p.type === activeType);

  if (!filtered.length) {
    grid.innerHTML = `<div style="grid-column:1/-1;"><div class="sched-empty">No ${activeType} points configured.</div></div>`;
    return;
  }

  const typeColors = { analog:"#1d5fa8", status:"#1a5f4a", count:"#b45309", alarm:"#c0392b", derived:"#555" };

  grid.innerHTML = filtered.map(p => {
    const live  = scadaLiveData[p.point_id];
    const val   = live?.value != null ? live.value : null;
    const unit  = p.unit || live?.unit || "";
    const qual  = live?.quality || "unknown";
    const age   = live?.timestamp ? Math.round((Date.now() - new Date(live.timestamp).getTime()) / 60000) : null;
    const alarm = p.type === "alarm" && val === 1;
    const warn  = p.hi_limit && val > p.hi_limit;
    const tileClass = alarm ? "scada-point-tile alarm" : warn ? "scada-point-tile warn" : val != null ? "scada-point-tile normal" : "scada-point-tile";
    const color = typeColors[p.type] || "var(--text-primary)";

    return `<div class="${tileClass}">
      <div class="scada-point-label">${p.name}</div>
      <div class="scada-point-value" style="color:${val!=null?color:"var(--text-hint)"};">
        ${val != null ? val : "—"}${val != null && unit ? `<span class="scada-point-unit"> ${unit}</span>` : ""}
      </div>
      <div class="scada-point-age">${age == null ? "No data" : age < 2 ? "Just now" : `${age}m ago`}</div>
    </div>`;
  }).join("");

  if (badge) badge.style.display = Object.keys(scadaLiveData).length > 0 ? "inline-block" : "none";
  if (updEl) { updEl.textContent = `Last refreshed: ${new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}`; updEl.style.display = "block"; }
}

function filterSCADAPoints(type, btn) {
  document.querySelectorAll(".scada-filter-btn").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface2)";
    b.style.color       = "var(--text-secondary)";
  });
  if (btn) { btn.style.borderColor = "var(--green)"; btn.style.background = "var(--green-bg)"; btn.style.color = "var(--green-dark)"; }
  refreshSCADADisplay();
}

// ── Alarms ────────────────────────────────────────────────────────────────────
async function loadSCADAAlarms() {
  const list  = document.getElementById("scada-alarm-list");
  const count = document.getElementById("scada-alarm-count");
  if (!list) return;
  try {
    const rows = await supabaseGet(
      "scada_readings?type=eq.alarm&value=eq.1&order=recorded_at.desc&limit=50"
    );
    const alarms = Array.isArray(rows) ? rows : [];
    if (count) { count.textContent = alarms.length; count.style.display = alarms.length ? "inline" : "none"; }
    if (!alarms.length) { list.innerHTML = '<div class="sched-empty">&#10003; No active alarms.</div>'; return; }
    list.innerHTML = alarms.map(a => `
      <div class="scada-alarm-row">
        <div class="scada-alarm-sev critical"></div>
        <div style="flex:1;">
          <span style="font-weight:600;">${a.point_name||a.point_id}</span>
          <span style="font-size:10px;color:var(--text-hint);margin-left:8px;">${a.source_name||""}</span>
        </div>
        <div style="font-size:10px;color:var(--text-hint);font-family:monospace;">${new Date(a.recorded_at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</div>
      </div>`).join("");
  } catch(e) { list.innerHTML = '<div class="sched-empty">Error loading alarms.</div>'; }
}

// ── REST Polling ──────────────────────────────────────────────────────────────
async function pollSCADAREST() {
  const restSources = scadaSources.filter(s => s.protocol === "rest_poll" && s.enabled);
  for (const src of restSources) {
    try {
      const cfg = JSON.parse(src.config || "{}");
      if (!cfg.url) continue;
      const res = await fetch(PROXY_URL + "scada/poll", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: cfg.url, auth: cfg.auth, source_id: src.id, source_name: src.name })
      });
      if (!res.ok) continue;
      const data = await res.json();
      if (data.points) {
        data.points.forEach(p => {
          scadaLiveData[p.id] = { value:p.value, timestamp:p.timestamp||new Date().toISOString(), quality:p.quality||"good", unit:p.unit||"" };
        });
        // Update source status
        await fetch(`${SUPABASE_URL}/rest/v1/scada_sources?id=eq.${src.id}`, {
          method:"PATCH",
          headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`,"Content-Type":"application/json","Prefer":"return=minimal"},
          body:JSON.stringify({status:"active",last_poll:new Date().toISOString()})
        });
      }
    } catch(e) { console.warn(`SCADA REST poll ${src.name}:`, e.message); }
  }
}

// ── 15-minute Snapshot Recording ─────────────────────────────────────────────
async function recordSCADASnapshot() {
  const now = new Date().toISOString();
  const records = [];
  for (const p of scadaPoints) {
    const live = scadaLiveData[p.point_id];
    if (!live || live.value == null) continue;
    const src = scadaSources.find(s => s.id == p.source_id);
    if (!src) continue;
    const recordTypes = src.record_types || ["analog","alarm","status","derived"];
    if (!recordTypes.includes(p.type)) continue;

    records.push({
      source_id:   p.source_id,
      source_name: src.name,
      point_id:    p.point_id,
      point_name:  p.name,
      type:        p.type,
      value:       live.value,
      unit:        p.unit || live.unit || "",
      quality:     live.quality || "good",
      recorded_at: now
    });
  }
  if (!records.length) return;
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/scada_readings`, {
      method:"POST",
      headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`,"Content-Type":"application/json","Prefer":"return=minimal"},
      body:JSON.stringify(records)
    });
    console.log(`SCADA snapshot: recorded ${records.length} points at ${now}`);
  } catch(e) { console.warn("SCADA snapshot error:", e); }
}

// ── CSV Import ────────────────────────────────────────────────────────────────
async function importSCADACSV() {
  const file   = document.getElementById("scada-csv-file")?.files?.[0];
  const status = document.getElementById("scada-csv-status");
  if (!file) { if (status) status.textContent = "Select a CSV file first."; return; }
  if (status) status.textContent = "Reading file...";

  const text = await file.text();
  const lines = text.trim().split("\n");
  const headers = lines[0].split(",").map(h => h.trim().toLowerCase().replace(/"/g,""));
  const records = [];

  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(",").map(c => c.trim().replace(/^"|"$/g,""));
    const row = {};
    headers.forEach((h, idx) => { row[h] = cols[idx] || ""; });
    if (!row.timestamp || !row.value) continue;
    records.push({
      source_id:   null,
      source_name: "CSV Import",
      point_id:    row.point_id || row.tag || `csv_${i}`,
      point_name:  row.point_name || row.name || row.point_id || `Point ${i}`,
      type:        row.type || "analog",
      value:       parseFloat(row.value),
      unit:        row.unit || "",
      quality:     row.quality || "good",
      recorded_at: new Date(row.timestamp).toISOString()
    });
  }

  if (!records.length) { if (status) status.textContent = "No valid records found in CSV."; return; }
  if (status) status.textContent = `Importing ${records.length} records...`;

  try {
    // Batch in chunks of 500
    const chunks = [];
    for (let i = 0; i < records.length; i += 500) chunks.push(records.slice(i, i+500));
    for (const chunk of chunks) {
      await fetch(`${SUPABASE_URL}/rest/v1/scada_readings`, {
        method:"POST",
        headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`,"Content-Type":"application/json","Prefer":"return=minimal"},
        body:JSON.stringify(chunk)
      });
    }
    if (status) status.textContent = `✅ Imported ${records.length} records successfully.`;
    await refreshSCADADisplay();
  } catch(e) { if (status) status.textContent = `Error: ${e.message}`; }
}

// ── Trend Chart ───────────────────────────────────────────────────────────────
async function populateSCADATrendSelector() {
  const sel = document.getElementById("scada-trend-point");
  if (!sel) return;
  sel.innerHTML = '<option value="">-- Select Point --</option>' +
    scadaPoints.map(p => `<option value="${p.point_id}">${p.name} (${p.type})</option>`).join("");
}

async function loadSCADATrend() {
  const pointId  = document.getElementById("scada-trend-point")?.value;
  const rangeHrs = parseInt(document.getElementById("scada-trend-range")?.value || "24");
  const metaEl   = document.getElementById("scada-trend-meta");
  const ctx      = document.getElementById("scada-trend-chart");
  if (!ctx || !pointId) return;

  const since = new Date(Date.now() - rangeHrs * 60 * 60 * 1000).toISOString();
  if (metaEl) metaEl.textContent = "Loading...";

  try {
    const rows = await supabaseGet(
      `scada_readings?point_id=eq.${encodeURIComponent(pointId)}&recorded_at=gte.${encodeURIComponent(since)}&order=recorded_at.asc&limit=2000`
    );
    const point = scadaPoints.find(p => p.point_id === pointId);

    if (!Array.isArray(rows) || !rows.length) {
      if (metaEl) metaEl.textContent = "No recorded data for this point in the selected range.";
      if (scadaTrendChart) { scadaTrendChart.destroy(); scadaTrendChart = null; }
      return;
    }

    const labels = rows.map(r => {
      const d = new Date(r.recorded_at);
      return rangeHrs <= 24 ? d.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}) : d.toLocaleDateString([],{month:"short",day:"numeric",hour:"2-digit"});
    });
    const data = rows.map(r => r.value);
    const unit = point?.unit || rows[0]?.unit || "";
    const min  = Math.min(...data);
    const max  = Math.max(...data);
    const avg  = (data.reduce((a,b)=>a+b,0)/data.length).toFixed(2);

    if (metaEl) metaEl.innerHTML = `<strong>${point?.name||pointId}</strong> &bull; Latest: ${data[data.length-1]} ${unit} &bull; Min: ${min} &bull; Max: ${max} &bull; Avg: ${avg} &bull; ${rows.length} readings`;

    const typeColors = { analog:"#1d5fa8", status:"#1a5f4a", count:"#b45309", alarm:"#c0392b", derived:"#555" };
    const color = typeColors[point?.type] || "#1a5f4a";

    if (scadaTrendChart) { scadaTrendChart.destroy(); scadaTrendChart = null; }
    scadaTrendChart = new Chart(ctx, {
      type: point?.type === "status" || point?.type === "alarm" ? "bar" : "line",
      data: {
        labels,
        datasets: [{ label:`${point?.name||pointId} (${unit})`, data, borderColor:color, backgroundColor:color+"22", borderWidth:2, pointRadius:rows.length>100?0:3, tension:0.3, fill:true }]
      },
      options: {
        responsive:true, maintainAspectRatio:false,
        plugins:{ legend:{display:false}, tooltip:{ callbacks:{ label:c=>`${c.parsed.y} ${unit}` } } },
        scales:{
          x:{ ticks:{maxTicksLimit:10,font:{size:10},color:"#888780"},grid:{color:"rgba(0,0,0,0.05)"} },
          y:{ ticks:{font:{size:10},color:"#888780"},grid:{color:"rgba(0,0,0,0.05)"},title:{display:!!unit,text:unit,font:{size:10},color:"#888780"} }
        }
      }
    });
    if (chartInstances) chartInstances["scada-trend-chart"] = scadaTrendChart;

  } catch(e) {
    if (metaEl) metaEl.innerHTML = `<span style="color:var(--red);">Error: ${e.message}</span>`;
  }
}



// ── EV Charging CSMS ─────────────────────────────────────────────────────────

let evChargers     = [];   // enrolled chargers from Supabase
let evSessions     = {};   // live session data { stationId: { connectorId, status, power, energy, idTag } }
let evShedActive   = false;
let evRefreshTimer = null;
const EV_STORAGE_KEY = "lcp_ev_chargers_v1";

// ── Init ───────────────────────────────────────────────────────────────────────
async function initEVCharging() {
  // Show OCPP endpoint URLs
  const base = PROXY_URL.replace(/\/$/, "");
  const url16  = document.getElementById("ev-ocpp16-url");
  const url201 = document.getElementById("ev-ocpp201-url");
  if (url16)  url16.textContent  = `${base}/ocpp16/{stationId}`;
  if (url201) url201.textContent = `${base}/ocpp201/{stationId}`;

  await loadEVChargers();
  await refreshEVStatus();
  await loadEVSessionLog();
  await refreshEVLiveMonitor();

  if (!evRefreshTimer) {
    evRefreshTimer = setInterval(() => {
      refreshEVStatus();
      refreshEVLiveMonitor();
    }, 30000);
  }
}

// ── Charger Enrollment ────────────────────────────────────────────────────────
function toggleEnrollChargerForm() {
  const form = document.getElementById("ev-enroll-form");
  if (!form) return;
  form.style.display = form.style.display === "none" ? "block" : "none";
}

async function enrollCharger() {
  const stationId  = document.getElementById("ev-new-station-id")?.value?.trim().toUpperCase().replace(/\s+/g, "_");
  const name       = document.getElementById("ev-new-station-name")?.value?.trim();
  const protocol   = document.getElementById("ev-new-protocol")?.value || "ocpp201";
  const make       = document.getElementById("ev-new-make")?.value || "";
  const maxKw      = parseFloat(document.getElementById("ev-new-max-kw")?.value || "7.2");
  const connectors = parseInt(document.getElementById("ev-new-connectors")?.value || "1");
  const drEnrolled = document.getElementById("ev-new-dr-enrolled")?.value === "true";

  if (!stationId) { setStatus("error", "Station ID required."); return; }
  if (!name)      { setStatus("error", "Display name required."); return; }

  const shedLimits = {
    emergency: parseInt(document.getElementById("ev-shed-emergency")?.value || "0"),
    high:      parseInt(document.getElementById("ev-shed-high")?.value || "8"),
    medium:    parseInt(document.getElementById("ev-shed-medium")?.value || "16"),
    low:       parseInt(document.getElementById("ev-shed-low")?.value || "24")
  };

  const record = {
    station_id:  stationId,
    name,
    protocol,
    make:        make || null,
    max_kw:      maxKw,
    connectors,
    dr_enrolled: drEnrolled,
    shed_limits: JSON.stringify(shedLimits),
    status:      "offline",
    enabled:     true,
    enrolled_at: new Date().toISOString()
  };

  // Try Supabase, fall back to localStorage
  let saved = false;
  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/ev_chargers`, {
      method: "POST",
      headers: { "apikey":SUPABASE_KEY, "Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`, "Content-Type":"application/json", "Prefer":"return=representation" },
      body: JSON.stringify(record)
    });
    if (res.ok) saved = true;
    else console.warn("EV enroll Supabase:", res.status, await res.text());
  } catch(e) { console.warn("EV enroll:", e.message); }

  if (!saved) {
    const existing = JSON.parse(localStorage.getItem(EV_STORAGE_KEY) || "[]");
    existing.push({ ...record, id: Date.now(), shed_limits: shedLimits });
    localStorage.setItem(EV_STORAGE_KEY, JSON.stringify(existing));
  }

  // Register as a device so it can join groups and receive dispatches
  await registerAssetAsDevice(stationId, name, "ev", null);

  setStatus("ready", `${name} enrolled.`);
  const form = document.getElementById("ev-enroll-form");
  if (form) form.style.display = "none";
  await loadEVChargers();
  await refreshEVStatus();
}

async function loadEVChargers() {
  let dbRows = [], localRows = [];
  try {
    const rows = await supabaseGet("ev_chargers?enabled=eq.true&order=enrolled_at.asc");
    if (Array.isArray(rows) && rows.length) dbRows = rows;
  } catch(e) {}
  try {
    const saved = localStorage.getItem(EV_STORAGE_KEY);
    if (saved) localRows = JSON.parse(saved);
  } catch(e) {}

  const dbIds = new Set(dbRows.map(r => r.station_id));
  const localOnly = localRows.filter(r => !dbIds.has(r.station_id));
  evChargers = [...dbRows, ...localOnly].map(c => ({
    ...c,
    shed_limits: typeof c.shed_limits === "string"
      ? (() => { try { return JSON.parse(c.shed_limits); } catch(e) { return {emergency:0,high:8,medium:16,low:24}; } })()
      : (c.shed_limits || {emergency:0,high:8,medium:16,low:24})
  }));
}

// ── Live Status Refresh ────────────────────────────────────────────────────────
async function refreshEVStatus() {
  if (!evChargers.length) {
    const list = document.getElementById("ev-charger-list");
    if (list) list.innerHTML = '<div class="sched-empty">No chargers enrolled. Click + Enroll Charger to add a charging station.</div>';
    return;
  }

  // Fetch latest status from Supabase ev_sessions table
  try {
    const since = new Date(Date.now() - 60 * 60 * 1000).toISOString(); // last 1 hour
    const rows  = await supabaseGet(`ev_sessions?updated_at=gte.${encodeURIComponent(since)}&order=updated_at.desc&limit=200`);
    if (Array.isArray(rows)) {
      rows.forEach(r => {
        if (!evSessions[r.station_id] || new Date(r.updated_at) > new Date(evSessions[r.station_id].updated_at || 0)) {
          evSessions[r.station_id] = r;
        }
      });
    }
  } catch(e) {}

  renderEVChargerList();
  updateEVFleetStats();
}

function renderEVChargerList() {
  const list = document.getElementById("ev-charger-list");
  if (!list || !evChargers.length) return;

  const PROTO_LABELS = { ocpp201:"OCPP 2.0.1", ocpp16:"OCPP 1.6J", api:"API", relay:"Relay" };
  const STATUS_COLORS = { available:"available", charging:"charging", faulted:"faulted", offline:"offline", preparing:"preparing", unavailable:"faulted" };

  list.innerHTML = evChargers.map(c => {
    const sess       = evSessions[c.station_id];
    const status     = sess?.status || c.status || "offline";
    const dotClass   = STATUS_COLORS[status.toLowerCase()] || "offline";
    const powerKw    = sess?.power_kw != null ? parseFloat(sess.power_kw).toFixed(1) : "—";
    const energyKwh  = sess?.energy_kwh != null ? parseFloat(sess.energy_kwh).toFixed(2) : "—";
    const soc        = sess?.soc_pct || null;
    const shedActive = sess?.shed_active || false;
    const protoClass = c.protocol === "ocpp201" ? "ocpp201" : c.protocol === "ocpp16" ? "ocpp16" : "api";
    const base       = PROXY_URL.replace(/\/$/, "");

    return `<div class="ev-charger-card${shedActive ? " ev-shed-active" : ""}">
      <div class="ev-charger-header">
        <div class="ev-status-dot ${dotClass}"></div>
        <div style="flex:1;">
          <div style="font-size:13px;font-weight:600;color:var(--text-primary);">${c.name}</div>
          <div style="font-size:10px;color:var(--text-hint);font-family:monospace;">${c.station_id} &bull; ${c.make || "Unknown"} &bull; ${c.max_kw} kW max</div>
        </div>
        <span class="ev-proto-badge ${protoClass}">${PROTO_LABELS[c.protocol]||c.protocol}</span>
        ${c.dr_enrolled ? '<span style="font-size:10px;font-weight:600;color:var(--green-dark);background:var(--green-bg);padding:2px 8px;border-radius:10px;">DR</span>' : ""}
        ${shedActive ? '<span style="font-size:10px;font-weight:600;color:var(--red);background:var(--red-lt);padding:2px 8px;border-radius:10px;">SHED</span>' : ""}
      </div>

      <div class="ev-meter-grid">
        <div class="ev-meter-tile"><div class="ev-meter-val" style="color:${status==="charging"?"var(--blue-dark)":"var(--text-hint)"};">${status.charAt(0).toUpperCase()+status.slice(1)}</div><div class="ev-meter-lbl">Status</div></div>
        <div class="ev-meter-tile"><div class="ev-meter-val">${powerKw} <span style="font-size:11px;font-weight:400;">kW</span></div><div class="ev-meter-lbl">Power</div></div>
        <div class="ev-meter-tile"><div class="ev-meter-val">${energyKwh} <span style="font-size:11px;font-weight:400;">kWh</span></div><div class="ev-meter-lbl">Session</div></div>
        <div class="ev-meter-tile"><div class="ev-meter-val">${soc != null ? soc+"%" : "—"}</div><div class="ev-meter-lbl">SOC</div></div>
      </div>

      ${soc != null ? `<div class="ev-session-bar"><div class="ev-session-fill" style="width:${soc}%;"></div></div>` : ""}

      <div class="ev-connector-row" style="margin-top:8px;border-top:0.5px solid var(--border);">
        <div style="font-size:10px;color:var(--text-hint);font-family:monospace;flex:1;">
          OCPP: ${base}/${c.protocol === "ocpp201" ? "ocpp201" : "ocpp16"}/${c.station_id}
        </div>
        <div style="display:flex;gap:6px;">
          ${c.dr_enrolled && c.protocol !== "relay" ? `
          <button onclick="shedSingleCharger('${c.station_id}', 0.75)" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--amber);background:var(--amber-bg);color:var(--amber);font-size:10px;cursor:pointer;">Shed</button>
          <button onclick="restoreSingleCharger('${c.station_id}')" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:10px;cursor:pointer;">Restore</button>` : ""}
          <button onclick="removeEVCharger('${c.station_id}')" style="padding:3px 8px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
        </div>
      </div>
    </div>`;
  }).join("");
}

function updateEVFleetStats() {
  const total    = evChargers.length;
  const online   = evChargers.filter(c => evSessions[c.station_id]?.status && evSessions[c.station_id].status !== "offline").length;
  const charging = evChargers.filter(c => evSessions[c.station_id]?.status === "charging").length;
  const totalKw  = evChargers.reduce((sum, c) => sum + (parseFloat(evSessions[c.station_id]?.power_kw || 0)), 0);
  const shed     = evChargers.filter(c => evSessions[c.station_id]?.shed_active).length;

  document.getElementById("ev-stat-total").textContent   = total;
  document.getElementById("ev-stat-online").textContent  = online;
  document.getElementById("ev-stat-charging").textContent= charging;
  document.getElementById("ev-stat-kw").textContent      = totalKw.toFixed(1);
  document.getElementById("ev-stat-shed").textContent    = shed;

  const badge = document.getElementById("ev-csms-status");
  if (badge) {
    badge.textContent  = online > 0 ? `${online}/${total} online` : total > 0 ? "All offline" : "No chargers";
    badge.style.background = online > 0 ? "var(--green-bg)" : "var(--surface2)";
    badge.style.color      = online > 0 ? "var(--green-dark)" : "var(--text-hint)";
  }
}

async function removeEVCharger(stationId) {
  if (!confirm(`Remove ${stationId} from enrollment?`)) return;
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/ev_chargers?station_id=eq.${encodeURIComponent(stationId)}`, {
      method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
    });
  } catch(e) {}
  // Also remove from localStorage
  const local = JSON.parse(localStorage.getItem(EV_STORAGE_KEY) || "[]");
  localStorage.setItem(EV_STORAGE_KEY, JSON.stringify(local.filter(c => c.station_id !== stationId)));
  await unregisterAssetDevice(stationId, "ev");
  await loadEVChargers();
  renderEVChargerList();
}

// ── OCPP Smart Charging — SetChargingProfile ────────────────────────────────────
async function shedEVChargers(limitAmps, signalLevel) {
  const enrolled = evChargers.filter(c => c.dr_enrolled);
  if (!enrolled.length) { setStatus("error", "No DR-enrolled chargers."); return; }

  evShedActive = true;
  const shedBanner = document.getElementById("ev-shed-banner");
  if (shedBanner) shedBanner.style.display = "flex";

  const results = await Promise.all(enrolled.map(c => shedSingleCharger(c.station_id, signalLevel, limitAmps)));
  setStatus("ready", `EV DR shed sent to ${enrolled.length} charger${enrolled.length!==1?"s":""}.`);

  // Log to ev_sessions
  await logEVDREvent("shed", signalLevel, enrolled.map(c => c.station_id));
}

async function shedSingleCharger(stationId, signalLevel, limitAmps = null) {
  const charger = evChargers.find(c => c.station_id === stationId);
  if (!charger) return;

  // Determine amp limit from shed_limits if not specified
  const limits = charger.shed_limits || {emergency:0, high:8, medium:16, low:24};
  if (limitAmps === null) {
    if (signalLevel >= 1.0)       limitAmps = limits.emergency;
    else if (signalLevel >= 0.75) limitAmps = limits.high;
    else if (signalLevel >= 0.5)  limitAmps = limits.medium;
    else                          limitAmps = limits.low;
  }

  if (charger.protocol === "relay") {
    // Relay fallback — send LC hex via existing relay system
    const matchedDevice = DEVICES.find(d => d.uid === charger.relay_uid || d.name === charger.name);
    if (matchedDevice) await sendLCToDevice(matchedDevice.uid, buildLCHex("all_on","dlc",19,2,0));
    return;
  }

  // OCPP — send SetChargingProfile via Worker
  try {
    const profileId = Math.floor(Math.random() * 99999) + 1;
    const endpoint  = charger.protocol === "ocpp201" ? "ocpp201/send" : "ocpp16/send";
    const payload   = charger.protocol === "ocpp201"
      ? buildOCPP201ChargingProfile(stationId, profileId, limitAmps)
      : buildOCPP16ChargingProfile(stationId, profileId, limitAmps);

    await fetch(PROXY_URL + endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ station_id: stationId, action: "SetChargingProfile", payload })
    });
  } catch(e) { console.warn(`shedSingleCharger ${stationId}:`, e.message); }
}

async function restoreEVShed() {
  evShedActive = false;
  const shedBanner = document.getElementById("ev-shed-banner");
  if (shedBanner) shedBanner.style.display = "none";

  const enrolled = evChargers.filter(c => c.dr_enrolled);
  await Promise.all(enrolled.map(c => restoreSingleCharger(c.station_id)));
  setStatus("ready", "EV chargers restored to full power.");
  await logEVDREvent("restore", 0, enrolled.map(c => c.station_id));
}

async function restoreSingleCharger(stationId) {
  const charger = evChargers.find(c => c.station_id === stationId);
  if (!charger) return;
  if (charger.protocol === "relay") return;

  try {
    const profileId = Math.floor(Math.random() * 99999) + 1;
    const maxAmps   = Math.round((charger.max_kw * 1000) / 230); // approx
    const endpoint  = charger.protocol === "ocpp201" ? "ocpp201/send" : "ocpp16/send";
    const payload   = charger.protocol === "ocpp201"
      ? buildOCPP201ChargingProfile(stationId, profileId, maxAmps)
      : buildOCPP16ChargingProfile(stationId, profileId, maxAmps);

    await fetch(PROXY_URL + endpoint, {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({ station_id:stationId, action:"SetChargingProfile", payload })
    });
    // Also clear the DR profile
    await fetch(PROXY_URL + endpoint, {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({ station_id:stationId, action:"ClearChargingProfile", payload:{ id:profileId, connectorId:0 } })
    });
  } catch(e) { console.warn(`restoreSingleCharger ${stationId}:`, e.message); }
}

function toggleEVShedAll() {
  if (evShedActive) restoreEVShed();
  else shedEVChargers(null, 0.75);
}

// ── OCPP Message Builders ────────────────────────────────────────────────────
function buildOCPP16ChargingProfile(stationId, profileId, limitAmps) {
  // OCPP 1.6J — SetChargingProfile payload
  return {
    connectorId: 0,  // 0 = entire charge point
    csChargingProfiles: {
      chargingProfileId:      profileId,
      stackLevel:             9,          // high stack level to override defaults
      chargingProfilePurpose: "ChargePointMaxProfile",
      chargingProfileKind:    "Absolute",
      chargingSchedule: {
        chargingRateUnit: "A",
        chargingSchedulePeriod: [
          { startPeriod: 0, limit: parseFloat(limitAmps.toFixed(1)) }
        ]
      }
    }
  };
}

function buildOCPP201ChargingProfile(stationId, profileId, limitAmps) {
  // OCPP 2.0.1 — SetChargingProfile payload
  return {
    evseId: 0,  // 0 = entire charging station
    chargingProfile: {
      id:                     profileId,
      stackLevel:             9,
      chargingProfilePurpose: "ChargingStationExternalConstraints",
      chargingProfileKind:    "Absolute",
      chargingSchedule: [{
        id:               1,
        chargingRateUnit: "A",
        chargingSchedulePeriod: [
          { startPeriod: 0, limit: parseFloat(limitAmps.toFixed(1)) }
        ]
      }]
    }
  };
}

// ── DR Log ───────────────────────────────────────────────────────────────────
async function logEVDREvent(action, signalLevel, stationIds) {
  try {
    await supabasePost("ev_dr_log", {
      action,
      signal_level: signalLevel,
      station_ids:  JSON.stringify(stationIds),
      fired_at:     new Date().toISOString(),
      fired_by:     currentUser?.email || "manual"
    });
  } catch(e) {}
}

// ── Session Log ──────────────────────────────────────────────────────────────
async function loadEVSessionLog() {
  const list   = document.getElementById("ev-session-log");
  if (!list) return;
  const rangeHrs = parseInt(document.getElementById("ev-log-range")?.value || "24");
  const since  = new Date(Date.now() - rangeHrs * 60 * 60 * 1000).toISOString();
  try {
    const rows = await supabaseGet(`ev_sessions?updated_at=gte.${encodeURIComponent(since)}&order=updated_at.desc&limit=100`);
    if (!Array.isArray(rows) || !rows.length) {
      list.innerHTML = '<div class="sched-empty">No sessions in this period. Sessions are recorded as chargers connect and report via OCPP.</div>';
      return;
    }
    list.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:11px;">
      <thead><tr>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Station</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Status</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Power</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Energy</th>
        <th style="text-align:center;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Shed</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Updated</th>
      </tr></thead>
      <tbody>${rows.map(r => `<tr>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-weight:600;">${r.station_name||r.station_id}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">${r.status||"—"}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;">${r.power_kw!=null?r.power_kw+" kW":"—"}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;">${r.energy_kwh!=null?r.energy_kwh+" kWh":"—"}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:center;">${r.shed_active?"⚡ Yes":""}</td>
        <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;color:var(--text-hint);">${new Date(r.updated_at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</td>
      </tr>`).join("")}</tbody></table>`;
  } catch(e) {
    list.innerHTML = '<div class="sched-empty">Session data not yet available. Run the SQL to create ev_sessions table.</div>';
  }
}

// ── Wire OpenADR → EV Chargers ───────────────────────────────────────────────
// Called from fireAutopilotEvent and OpenADR dispatch — extends existing DR to EV chargers



// ── EV Charger Device Assets ───────────────────────────────────────────────────

let evDevAssets      = [];     // all enrolled EV assets
let evDevSelectedInteg = null; // currently selected integration type
const EV_DEV_KEY     = "lcp_ev_dev_assets_v1";

// ── Init ───────────────────────────────────────────────────────────────────────
async function initEVDevicesTab() {
  const base = PROXY_URL.replace(/\/$/, "");
  const url201 = document.getElementById("ev-dev-ocpp201-url");
  const url16  = document.getElementById("ev-dev-ocpp16-url");
  if (url201) url201.textContent = `${base}/ocpp201/{stationId}`;
  if (url16)  url16.textContent  = `${base}/ocpp16/{stationId}`;

  // Populate relay device dropdown
  const relayDev = document.getElementById("ev-relay-device");
  if (relayDev) {
    relayDev.innerHTML = '<option value="">-- Select relay device --</option>' +
      (DEVICES || []).filter(d => !d.uid.includes("PLACEHOLDER"))
        .map(d => `<option value="${d.uid}">${d.name}</option>`).join("");
  }

  await refreshEVDevAssets();
  await loadEVDevLog();
}

// ── Form UI ────────────────────────────────────────────────────────────────────
function toggleEVDevEnrollForm() {
  const form = document.getElementById("ev-dev-enroll-form");
  if (!form) return;
  const isOpen = form.style.display !== "none";
  form.style.display = isOpen ? "none" : "block";
  if (!isOpen) {
    // Reset
    evDevEditingId = null;
    evDevSelectedInteg = null;
    const titleEl = document.getElementById("ev-dev-form-title");
    if (titleEl) titleEl.textContent = "Add EV Charger Asset";
    const btnEl = document.getElementById("ev-dev-save-btn");
    if (btnEl) btnEl.textContent = "Save Asset";
    document.querySelectorAll(".ev-integ-opt").forEach(b => {
      b.style.borderColor = "var(--border-md)";
      b.style.background  = "var(--surface)";
    });
    document.querySelectorAll(".ev-integ-panel").forEach(p => p.style.display = "none");
    ["ev-dev-station-id","ev-dev-name","ev-dev-location",
     "ev-cp-api-key","ev-cp-api-pass","ev-cp-station-id",
     "ev-enelx-token","ev-enelx-device-token",
     "ev-blink-user","ev-blink-pass","ev-blink-charger-id"
    ].forEach(id => { const el = document.getElementById(id); if(el) el.value = ""; });
    document.getElementById("ev-dev-max-kw").value  = "7.2";
    document.getElementById("ev-dev-connectors").value = "1";
    document.getElementById("ev-dev-make").selectedIndex   = 0;
    document.getElementById("ev-dev-dr").selectedIndex     = 0;
  }
}

function selectEVInteg(integ, el) {
  evDevSelectedInteg = integ;
  document.querySelectorAll(".ev-integ-opt").forEach(b => {
    b.style.borderColor = "var(--border-md)";
    b.style.background  = "var(--surface)";
  });
  if (el) { el.style.borderColor = "var(--green)"; el.style.background = "var(--green-bg)"; }
  document.querySelectorAll(".ev-integ-panel").forEach(p => p.style.display = "none");
  const panel = document.getElementById(`ev-integ-${integ}`);
  if (panel) panel.style.display = "block";

  // Show/hide shed config (not relevant for relay which just cuts power)
  const shedCfg = document.getElementById("ev-dev-shed-config");
  if (shedCfg) shedCfg.style.display = integ === "relay" ? "none" : "block";
}

// ── Save Asset ─────────────────────────────────────────────────────────────────
function editEVDevAsset(stationId) {
  const asset = evDevAssets.find(a => a.station_id === stationId);
  if (!asset) return;
  evDevEditingId = stationId;

  // Open form
  const form = document.getElementById("ev-dev-enroll-form");
  if (form) form.style.display = "block";
  const title = document.getElementById("ev-dev-form-title");
  if (title) title.textContent = "Edit EV Charger Asset";
  const btn = document.getElementById("ev-dev-save-btn");
  if (btn) btn.textContent = "Update Asset";

  // Populate common fields
  const integ = asset.integ_config?.type || asset.integration || "ocpp201";
  document.getElementById("ev-dev-station-id").value = asset.station_id || "";
  document.getElementById("ev-dev-name").value        = asset.name || "";
  document.getElementById("ev-dev-location").value    = asset.location || "";
  document.getElementById("ev-dev-max-kw").value      = asset.max_kw || "7.2";
  document.getElementById("ev-dev-connectors").value  = asset.connectors || "1";
  document.getElementById("ev-dev-dr").value          = asset.dr_enrolled ? "true" : "false";
  const makeEl = document.getElementById("ev-dev-make");
  if (makeEl) makeEl.value = asset.make || "";

  // Select integration type
  const integEl = document.querySelector(`.ev-integ-opt[data-integ="${integ}"]`);
  selectEVInteg(integ, integEl);

  // Populate integration-specific fields
  const cfg = asset.integ_config || {};
  if (integ === "chargepoint") {
    document.getElementById("ev-cp-api-key").value    = cfg.api_key    || "";
    document.getElementById("ev-cp-api-pass").value   = cfg.api_pass   || "";
    document.getElementById("ev-cp-station-id").value = cfg.cp_station || "";
  } else if (integ === "enelx") {
    document.getElementById("ev-enelx-token").value        = cfg.api_token    || "";
    document.getElementById("ev-enelx-device-token").value = cfg.device_token || "";
  } else if (integ === "blink") {
    document.getElementById("ev-blink-user").value       = cfg.username   || "";
    document.getElementById("ev-blink-pass").value       = cfg.password   || "";
    document.getElementById("ev-blink-charger-id").value = cfg.charger_id || "";
  } else if (integ === "tesla") {
    document.getElementById("ev-tesla-client-id").value     = cfg.client_id     || "";
    document.getElementById("ev-tesla-client-secret").value = cfg.client_secret || "";
    document.getElementById("ev-tesla-refresh-token").value = cfg.refresh_token || "";
    document.getElementById("ev-tesla-region").value        = cfg.region        || "na";
    document.getElementById("ev-tesla-vin").value           = cfg.vin           || "";
    document.getElementById("ev-tesla-max-amps").value      = cfg.max_amps      || "48";
  } else if (integ === "relay") {
    document.getElementById("ev-relay-device").value = cfg.relay_uid || "";
    document.getElementById("ev-relay-num").value    = cfg.relay_num || "1";
  }

  // Populate shed limits
  const limits = asset.shed_limits || {};
  document.getElementById("ev-dev-shed-emergency").value = limits.emergency ?? 0;
  document.getElementById("ev-dev-shed-high").value      = limits.high      ?? 8;
  document.getElementById("ev-dev-shed-medium").value    = limits.medium    ?? 16;
  document.getElementById("ev-dev-shed-low").value       = limits.low       ?? 24;

  form.scrollIntoView({ behavior:"smooth", block:"start" });
}

async function saveEVDevAsset() {
  if (!evDevSelectedInteg) { setStatus("error", "Select an integration type."); return; }

  const stationId = document.getElementById("ev-dev-station-id")?.value?.trim().toUpperCase().replace(/\s+/g,"_");
  const name      = document.getElementById("ev-dev-name")?.value?.trim();
  if (!stationId) { setStatus("error", "Station ID / Asset Tag required."); return; }
  if (!name)      { setStatus("error", "Display name required."); return; }

  // Build integration config
  const integConfig = { type: evDevSelectedInteg };
  if (evDevSelectedInteg === "chargepoint") {
    integConfig.api_key    = document.getElementById("ev-cp-api-key")?.value?.trim();
    integConfig.api_pass   = document.getElementById("ev-cp-api-pass")?.value?.trim();
    integConfig.cp_station = document.getElementById("ev-cp-station-id")?.value?.trim();
    if (!integConfig.api_key || !integConfig.cp_station) {
      setStatus("error", "ChargePoint API key and station ID required."); return;
    }
  } else if (evDevSelectedInteg === "enelx") {
    integConfig.api_token    = document.getElementById("ev-enelx-token")?.value?.trim();
    integConfig.device_token = document.getElementById("ev-enelx-device-token")?.value?.trim();
    if (!integConfig.api_token) { setStatus("error", "JuiceNet API token required."); return; }
  } else if (evDevSelectedInteg === "blink") {
    integConfig.username   = document.getElementById("ev-blink-user")?.value?.trim();
    integConfig.password   = document.getElementById("ev-blink-pass")?.value?.trim();
    integConfig.charger_id = document.getElementById("ev-blink-charger-id")?.value?.trim();
    if (!integConfig.username || !integConfig.charger_id) {
      setStatus("error", "Blink username and charger ID required."); return;
    }
  } else if (evDevSelectedInteg === "tesla") {
    integConfig.client_id     = document.getElementById("ev-tesla-client-id")?.value?.trim();
    integConfig.client_secret = document.getElementById("ev-tesla-client-secret")?.value?.trim();
    integConfig.refresh_token = document.getElementById("ev-tesla-refresh-token")?.value?.trim();
    integConfig.region        = document.getElementById("ev-tesla-region")?.value || "na";
    integConfig.vin           = document.getElementById("ev-tesla-vin")?.value?.trim().toUpperCase();
    integConfig.max_amps      = parseInt(document.getElementById("ev-tesla-max-amps")?.value || "48");
    if (!integConfig.client_id || !integConfig.refresh_token || !integConfig.vin) {
      setStatus("error", "Tesla Client ID, refresh token, and VIN required."); return;
    }
  } else if (evDevSelectedInteg === "relay") {
    integConfig.relay_uid = document.getElementById("ev-relay-device")?.value;
    integConfig.relay_num = parseInt(document.getElementById("ev-relay-num")?.value || "1");
    if (!integConfig.relay_uid) { setStatus("error", "Select a relay device."); return; }
  }

  const shedLimits = {
    emergency: parseInt(document.getElementById("ev-dev-shed-emergency")?.value || "0"),
    high:      parseInt(document.getElementById("ev-dev-shed-high")?.value      || "8"),
    medium:    parseInt(document.getElementById("ev-dev-shed-medium")?.value    || "16"),
    low:       parseInt(document.getElementById("ev-dev-shed-low")?.value       || "24")
  };

  const record = {
    station_id:   stationId,
    name,
    protocol:     ["ocpp201","ocpp16"].includes(evDevSelectedInteg) ? evDevSelectedInteg : "api",
    integration:  evDevSelectedInteg,
    make:         document.getElementById("ev-dev-make")?.value || null,
    max_kw:       parseFloat(document.getElementById("ev-dev-max-kw")?.value || "7.2"),
    connectors:   parseInt(document.getElementById("ev-dev-connectors")?.value || "1"),
    dr_enrolled:  document.getElementById("ev-dev-dr")?.value === "true",
    location:     document.getElementById("ev-dev-location")?.value?.trim() || null,
    integ_config: JSON.stringify(integConfig),
    shed_limits:  JSON.stringify(shedLimits),
    status:       "offline",
    enabled:      true,
    enrolled_at:  new Date().toISOString()
  };

  // Try Supabase — PATCH if editing, POST if new
  let saved = false;
  try {
    const isEdit = !!evDevEditingId;
    const url    = isEdit
      ? `${SUPABASE_URL}/rest/v1/ev_chargers?station_id=eq.${encodeURIComponent(evDevEditingId)}`
      : `${SUPABASE_URL}/rest/v1/ev_chargers`;
    const res = await fetch(url, {
      method: isEdit ? "PATCH" : "POST",
      headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        "Content-Type":"application/json","Prefer":"return=representation"},
      body: JSON.stringify(record)
    });
    if (res.ok) saved = true;
    else console.warn("EV save Supabase:", res.status, await res.text());
  } catch(e) { console.warn("EV save:", e.message); }

  if (!saved) {
    const existing = JSON.parse(localStorage.getItem(EV_DEV_KEY) || "[]");
    const filtered = existing.filter(a => a.station_id !== stationId);
    filtered.push({ ...record, id: Date.now(),
      shed_limits: shedLimits, integ_config: integConfig });
    localStorage.setItem(EV_DEV_KEY, JSON.stringify(filtered));
  }

  setStatus("ready", `${name} ${evDevEditingId ? "updated" : "saved"}.`);
  evDevEditingId = null;
  const title = document.getElementById("ev-dev-form-title");
  if (title) title.textContent = "Add EV Charger Asset";
  const btn = document.getElementById("ev-dev-save-btn");
  if (btn) btn.textContent = "Save Asset";
  toggleEVDevEnrollForm();
  await refreshEVDevAssets();
}

// ── Load & Render Assets ───────────────────────────────────────────────────────
async function refreshEVDevAssets() {
  let dbRows = [], localRows = [];
  try {
    const rows = await supabaseGet("ev_chargers?enabled=eq.true&order=enrolled_at.asc");
    if (Array.isArray(rows) && rows.length) dbRows = rows;
  } catch(e) {}
  try {
    const saved = localStorage.getItem(EV_DEV_KEY);
    if (saved) localRows = JSON.parse(saved);
  } catch(e) {}

  const dbIds = new Set(dbRows.map(r => r.station_id));
  const localOnly = localRows.filter(r => !dbIds.has(r.station_id));
  evDevAssets = [...dbRows, ...localOnly].map(a => ({
    ...a,
    shed_limits:  typeof a.shed_limits  === "string" ? JSON.parse(a.shed_limits  || "{}") : (a.shed_limits  || {}),
    integ_config: typeof a.integ_config === "string" ? JSON.parse(a.integ_config || "{}") : (a.integ_config || {})
  }));

  renderEVDevAssets();
  updateEVDevFleetStats();
  // Keep DEVICES in sync so groups and scheduler see EV chargers
  injectEVIntoDevices();
  // Refresh selectors if groups tab is loaded
  if (typeof refreshGroupSelectors === "function") refreshGroupSelectors();
  if (typeof populateTargetSelector === "function") populateTargetSelector();
}

function renderEVDevAssets() {
  const list = document.getElementById("ev-dev-asset-list");
  if (!list) return;
  if (!evDevAssets.length) {
    list.innerHTML = '<div class="sched-empty">No EV charger assets registered. Click + Add Charger to begin.</div>';
    return;
  }

  const INTEG_LABELS = {
    ocpp201:"OCPP 2.0.1", ocpp16:"OCPP 1.6J",
    chargepoint:"ChargePoint API", enelx:"Enel X / JuiceNet",
    blink:"Blink Network", tesla:"Tesla Fleet API", relay:"Relay Fallback"
  };
  const INTEG_COLORS = {
    ocpp201:"var(--green-dark)", ocpp16:"var(--blue-dark)",
    chargepoint:"#e87722", enelx:"var(--amber)",
    blink:"#0057a8", tesla:"#cc0000", relay:"var(--text-secondary)"
  };
  const STATUS_DOT = { available:"live", charging:"live", faulted:"unavailable",
    offline:"unavailable", preparing:"registration", connected:"live" };

  list.innerHTML = evDevAssets.map(a => {
    const integ   = a.integ_config?.type || a.integration || "ocpp201";
    const sess    = evSessions?.[a.station_id] || {};
    const status  = sess.status || a.status || "offline";
    const dotCls  = STATUS_DOT[status.toLowerCase()] || "unavailable";
    const powerKw = sess.power_kw != null ? `${parseFloat(sess.power_kw).toFixed(1)} kW` : "—";
    const energyKwh = sess.energy_kwh != null ? `${parseFloat(sess.energy_kwh).toFixed(2)} kWh` : "—";

    return `<div class="scada-source-card${sess.shed_active ? " ev-shed-active" : ""}">
      <div class="feed-status-dot ${dotCls}" style="margin-top:4px;"></div>
      <div style="flex:1;min-width:0;">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap;">
          <span style="font-size:13px;font-weight:600;color:var(--text-primary);">&#128268; ${a.name}</span>
          <span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;font-family:monospace;border:0.5px solid ${INTEG_COLORS[integ]||"var(--border-md)"};color:${INTEG_COLORS[integ]||"var(--text-hint)"};background:${INTEG_COLORS[integ]||"var(--border-md)"}18;">${INTEG_LABELS[integ]||integ}</span>
          ${a.dr_enrolled ? '<span style="font-size:10px;font-weight:700;color:var(--green-dark);background:var(--green-bg);padding:2px 8px;border-radius:10px;">DR</span>' : ""}
          ${sess.shed_active ? '<span style="font-size:10px;font-weight:700;color:var(--red);background:var(--red-lt);padding:2px 8px;border-radius:10px;">SHED</span>' : ""}
        </div>
        <div style="font-size:11px;color:var(--text-hint);margin-bottom:4px;">
          ${a.station_id} &bull; ${a.make||"Generic"} &bull; ${a.max_kw} kW &bull; ${a.connectors} connector${a.connectors!==1?"s":""}
          ${a.location ? ` &bull; ${a.location}` : ""}
        </div>
        <div style="font-size:11px;color:var(--text-secondary);">
          Status: <strong>${status.charAt(0).toUpperCase()+status.slice(1)}</strong>
          &bull; Power: <strong>${powerKw}</strong>
          &bull; Session: <strong>${energyKwh}</strong>
          ${integ === "relay" ? ` &bull; Relay: Device ${a.integ_config?.relay_uid?.slice(-4)||"?"} / R${a.integ_config?.relay_num||1}` : ""}
        </div>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end;flex-shrink:0;">
        ${a.dr_enrolled && integ !== "relay" ? `
        <div style="display:flex;gap:4px;">
          <button onclick="dispatchEVDRSingle('${a.station_id}', 0.75)"
            style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--amber);background:var(--amber-bg);color:var(--amber);font-size:10px;font-weight:600;cursor:pointer;">Shed</button>
          <button onclick="restoreEVSingle('${a.station_id}')"
            style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:10px;font-weight:600;cursor:pointer;">Restore</button>
        </div>` : ""}
        <div style="display:flex;gap:4px;">
          <button onclick="editEVDevAsset('${a.station_id}')"
            style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--blue-dark);background:var(--blue-lt);color:var(--blue-dark);font-size:10px;cursor:pointer;">Edit</button>
          <button onclick="removeEVDevAsset('${a.station_id}')"
            style="padding:4px 10px;border-radius:4px;border:0.5px solid var(--red);background:none;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
        </div>
      </div>
    </div>`;
  }).join("");
}

function updateEVDevFleetStats() {
  const total    = evDevAssets.length;
  const online   = evDevAssets.filter(a => evSessions?.[a.station_id]?.status &&
                   evSessions[a.station_id].status !== "offline").length;
  const charging = evDevAssets.filter(a => evSessions?.[a.station_id]?.status === "charging").length;
  const totalKw  = evDevAssets.reduce((s,a) => s + (parseFloat(evSessions?.[a.station_id]?.power_kw||0)),0);
  const drCount  = evDevAssets.filter(a => a.dr_enrolled).length;
  const shed     = evDevAssets.filter(a => evSessions?.[a.station_id]?.shed_active).length;

  const set = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  set("ev-dev-total",    total);
  set("ev-dev-online",   online);
  set("ev-dev-charging", charging);
  set("ev-dev-kw",       totalKw.toFixed(1));
  set("ev-dev-dr",       drCount);
  set("ev-dev-shed",     shed);

  const statusEl = document.getElementById("ev-dev-status");
  if (statusEl) {
    statusEl.textContent  = online > 0 ? `${online}/${total} online` : total > 0 ? "All offline" : "No assets";
    statusEl.style.background = online > 0 ? "var(--green-bg)" : "var(--surface2)";
    statusEl.style.color      = online > 0 ? "var(--green-dark)" : "var(--text-hint)";
  }
}

async function removeEVDevAsset(stationId) {
  if (!confirm("Remove this EV charger asset?")) return;
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/ev_chargers?station_id=eq.${encodeURIComponent(stationId)}`, {
      method:"DELETE", headers:{"apikey":SUPABASE_KEY,"Authorization":`Bearer ${currentSession?.access_token || SUPABASE_KEY}`}
    });
  } catch(e) {}
  const local = JSON.parse(localStorage.getItem(EV_DEV_KEY) || "[]");
  localStorage.setItem(EV_DEV_KEY, JSON.stringify(local.filter(a => a.station_id !== stationId)));
  await refreshEVDevAssets();
}

// ── DR Dispatch — All Integration Types ──────────────────────────────────────
async function dispatchEVDR(signalLevel) {
  const enrolled = evDevAssets.filter(a => a.dr_enrolled);
  if (!enrolled.length) { setStatus("error", "No DR-enrolled EV chargers."); return; }

  const results = await Promise.all(enrolled.map(a => dispatchEVDRSingle(a.station_id, signalLevel)));
  const ok = results.filter(Boolean).length;

  const logEl = document.getElementById("ev-dev-dr-log");
  if (logEl) logEl.innerHTML = `<span style="color:var(--red);font-weight:600;">&#9889; DR Shed dispatched</span> — ${ok}/${enrolled.length} chargers responded &bull; Signal: ${Math.round(signalLevel*100)}% &bull; ${new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}`;

  await logEVDREvent("shed", signalLevel, enrolled.map(a => a.station_id));
  setStatus("ready", `EV DR shed sent to ${enrolled.length} charger${enrolled.length!==1?"s":""}.`);
}

async function dispatchEVDRSingle(stationId, signalLevel) {
  const asset = evDevAssets.find(a => a.station_id === stationId);
  if (!asset) return false;

  const integ  = asset.integ_config?.type || asset.integration || "ocpp201";
  const limits = asset.shed_limits || {emergency:0, high:8, medium:16, low:24};
  let limitAmps = signalLevel >= 1.0 ? limits.emergency
                : signalLevel >= 0.75 ? limits.high
                : signalLevel >= 0.5  ? limits.medium : limits.low;

  try {
    if (integ === "ocpp201" || integ === "ocpp16") {
      // OCPP — SetChargingProfile via Worker
      const profileId = Math.floor(Math.random() * 99999) + 1;
      const endpoint  = integ === "ocpp201" ? "ocpp201/send" : "ocpp16/send";
      const payload   = integ === "ocpp201"
        ? buildOCPP201ChargingProfile(stationId, profileId, limitAmps)
        : buildOCPP16ChargingProfile(stationId, profileId, limitAmps);
      await fetch(PROXY_URL + endpoint, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ station_id:stationId, action:"SetChargingProfile", payload })
      });
      return true;

    } else if (integ === "chargepoint") {
      // ChargePoint — shedLoad via Worker proxy
      const res = await fetch(PROXY_URL + "ev/chargepoint/shed", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          api_key:    asset.integ_config.api_key,
          api_pass:   asset.integ_config.api_pass,
          station_id: asset.integ_config.cp_station,
          allowed_load: Math.round(limitAmps * 230 / 1000 * 10) / 10  // A → kW approx
        })
      });
      return (await res.json()).ok;

    } else if (integ === "enelx") {
      // Enel X JuiceNet — set_charge_limit via Worker proxy
      const res = await fetch(PROXY_URL + "ev/enelx/shed", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          api_token:    asset.integ_config.api_token,
          device_token: asset.integ_config.device_token,
          limit_amps:   limitAmps
        })
      });
      return (await res.json()).ok;

    } else if (integ === "blink") {
      // Blink — remote session control via Worker proxy
      const res = await fetch(PROXY_URL + "ev/blink/shed", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          username:   asset.integ_config.username,
          password:   asset.integ_config.password,
          charger_id: asset.integ_config.charger_id,
          action:     limitAmps <= 0 ? "stop" : "limit",
          limit_amps: limitAmps
        })
      });
      return (await res.json()).ok;

    } else if (integ === "tesla") {
      // Tesla Fleet API — set_charging_amps or charge_stop via Worker proxy
      const res = await fetch(PROXY_URL + "ev/tesla/shed", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          client_id:     asset.integ_config.client_id,
          client_secret: asset.integ_config.client_secret,
          refresh_token: asset.integ_config.refresh_token,
          region:        asset.integ_config.region || "na",
          vin:           asset.integ_config.vin,
          limit_amps:    limitAmps,
          max_amps:      asset.integ_config.max_amps || 48
        })
      });
      return (await res.json()).ok;

    } else if (integ === "relay") {
      // Relay fallback — LC hex via Notehub
      const relayUid = asset.integ_config?.relay_uid;
      if (relayUid) {
        // Build LC hex: all relays off (shed) using strategy 19 (100% shed)
        const hex = buildLCHex("all_on", "dlc", 19, 2, Math.floor(Date.now()/1000));
        await sendLCToDevice(relayUid, hex);
      }
      return !!relayUid;
    }
  } catch(e) {
    console.warn(`dispatchEVDRSingle ${stationId} (${integ}):`, e.message);
    return false;
  }
  return false;
}

async function dispatchEVRestore() {
  const enrolled = evDevAssets.filter(a => a.dr_enrolled);
  if (!enrolled.length) return;
  await Promise.all(enrolled.map(a => restoreEVSingle(a.station_id)));

  const logEl = document.getElementById("ev-dev-dr-log");
  if (logEl) logEl.innerHTML = `<span style="color:var(--green-dark);font-weight:600;">&#9989; Restore dispatched</span> — ${enrolled.length} charger${enrolled.length!==1?"s":""} &bull; ${new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}`;

  await logEVDREvent("restore", 0, enrolled.map(a => a.station_id));
  setStatus("ready", "EV chargers restored to full power.");
}

async function restoreEVSingle(stationId) {
  const asset = evDevAssets.find(a => a.station_id === stationId);
  if (!asset) return;
  const integ   = asset.integ_config?.type || asset.integration || "ocpp201";
  const maxAmps = Math.round((asset.max_kw * 1000) / 230);

  try {
    if (integ === "ocpp201" || integ === "ocpp16") {
      const profileId = Math.floor(Math.random() * 99999) + 1;
      const endpoint  = integ === "ocpp201" ? "ocpp201/send" : "ocpp16/send";
      const payload   = integ === "ocpp201"
        ? buildOCPP201ChargingProfile(stationId, profileId, maxAmps)
        : buildOCPP16ChargingProfile(stationId, profileId, maxAmps);
      await fetch(PROXY_URL + endpoint, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ station_id:stationId, action:"ClearChargingProfile",
          payload:{ id:profileId, connectorId:0 } })
      });
    } else if (integ === "chargepoint") {
      await fetch(PROXY_URL + "ev/chargepoint/restore", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ api_key:asset.integ_config.api_key,
          api_pass:asset.integ_config.api_pass, station_id:asset.integ_config.cp_station })
      });
    } else if (integ === "enelx") {
      await fetch(PROXY_URL + "ev/enelx/restore", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ api_token:asset.integ_config.api_token,
          device_token:asset.integ_config.device_token, limit_amps:maxAmps })
      });
    } else if (integ === "blink") {
      await fetch(PROXY_URL + "ev/blink/restore", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ username:asset.integ_config.username,
          password:asset.integ_config.password, charger_id:asset.integ_config.charger_id })
      });
    } else if (integ === "tesla") {
      await fetch(PROXY_URL + "ev/tesla/restore", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          client_id:     asset.integ_config.client_id,
          client_secret: asset.integ_config.client_secret,
          refresh_token: asset.integ_config.refresh_token,
          region:        asset.integ_config.region || "na",
          vin:           asset.integ_config.vin,
          max_amps:      asset.integ_config.max_amps || 48
        })
      });
    } else if (integ === "relay") {
      // Restore relay — send all relays ON
      const relayUid = asset.integ_config?.relay_uid;
      if (relayUid) {
        const hex = buildLCHex("all_on","dlc",5,1,Math.floor(Date.now()/1000));
        await sendLCToDevice(relayUid, hex);
      }
    }
  } catch(e) { console.warn(`restoreEVSingle ${stationId}:`, e.message); }
}

// ── Session & DR Log ───────────────────────────────────────────────────────────
async function loadEVDevLog() {
  const list = document.getElementById("ev-dev-log-list");
  if (!list) return;
  try {
    const rows = await supabaseGet("ev_sessions?order=updated_at.desc&limit=100");
    if (!Array.isArray(rows) || !rows.length) {
      list.innerHTML = '<div class="sched-empty">No sessions recorded. Sessions populate as chargers connect via OCPP or API polling.</div>';
      return;
    }
    list.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:11px;">
      <thead><tr>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Station</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Integration</th>
        <th style="text-align:left;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Status</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Power</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Energy</th>
        <th style="text-align:center;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">DR</th>
        <th style="text-align:right;padding:7px 10px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Updated</th>
      </tr></thead>
      <tbody>${rows.map(r => {
        const asset = evDevAssets.find(a => a.station_id === r.station_id);
        const integ = asset?.integration || r.protocol || "ocpp";
        return `<tr>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-weight:600;">${r.station_name||r.station_id}</td>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);font-size:10px;font-family:monospace;">${integ}</td>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);">${r.status||"—"}</td>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;">${r.power_kw!=null?r.power_kw+" kW":"—"}</td>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;font-family:monospace;">${r.energy_kwh!=null?r.energy_kwh+" kWh":"—"}</td>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:center;">${r.shed_active?"<span style='color:var(--red);font-weight:600;'>SHED</span>":""}</td>
          <td style="padding:6px 10px;border-bottom:0.5px solid var(--border);text-align:right;color:var(--text-hint);">${new Date(r.updated_at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})}</td>
        </tr>`;
      }).join("")}</tbody></table>`;
  } catch(e) {
    list.innerHTML = '<div class="sched-empty">Run the SQL to create ev_sessions table to see logs.</div>';
  }
}

// ── Override dispatchEVChargersDR to use dev assets ───────────────────────────
// This overrides the earlier version from the Monitor tab
async function dispatchEVChargersDR(signalLevel) {
  if (evDevAssets.length > 0) {
    await dispatchEVDR(signalLevel);
  } else if (evChargers.length > 0) {
    // Fall back to Monitor tab chargers if dev assets not loaded
    await shedEVChargers(null, signalLevel);
  }
}



// ── Tesla Fleet API Helpers ───────────────────────────────────────────────────
async function testTeslaConnection() {
  const clientId     = document.getElementById("ev-tesla-client-id")?.value?.trim();
  const clientSecret = document.getElementById("ev-tesla-client-secret")?.value?.trim();
  const refreshToken = document.getElementById("ev-tesla-refresh-token")?.value?.trim();
  const region       = document.getElementById("ev-tesla-region")?.value || "na";
  const vin          = document.getElementById("ev-tesla-vin")?.value?.trim().toUpperCase();
  const resultEl     = document.getElementById("ev-tesla-test-result");

  if (!clientId || !refreshToken || !vin) {
    if (resultEl) { resultEl.textContent = "Client ID, refresh token, and VIN required."; resultEl.style.color = "var(--red)"; }
    return;
  }
  if (resultEl) { resultEl.textContent = "Testing..."; resultEl.style.color = "var(--text-hint)"; }
  try {
    const res  = await fetch(PROXY_URL + "ev/tesla/status", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({ client_id:clientId, client_secret:clientSecret, refresh_token:refreshToken, region, vin })
    });
    const data = await res.json();
    if (data.ok) {
      if (resultEl) { resultEl.textContent = `✅ ${data.display_name||vin} — ${data.state||"connected"} — ${data.battery_level!=null?data.battery_level+"%":""}`.trim(); resultEl.style.color = "var(--green-dark)"; }
    } else {
      if (resultEl) { resultEl.textContent = `⚠️ ${data.error||"Connection failed"}`; resultEl.style.color = "var(--amber)"; }
    }
  } catch(e) {
    if (resultEl) { resultEl.textContent = `Error: ${e.message}`; resultEl.style.color = "var(--red)"; }
  }
}


