// ── EV Live Device Monitor ─────────────────────────────────────────────────────
async function refreshEVLiveMonitor() {
  const table  = document.getElementById("ev-live-monitor-table");
  const lastEl = document.getElementById("ev-monitor-last-update");
  if (!table) return;

  if (!evChargers.length) {
    table.innerHTML = '<div class="sched-empty">No chargers enrolled.</div>';
    return;
  }

  // Pull fresh session data
  try {
    const since = new Date(Date.now() - 24 * 3600000).toISOString();
    const rows  = await supabaseGet(`ev_sessions?updated_at=gte.${encodeURIComponent(since)}&order=updated_at.desc&limit=500`);
    if (Array.isArray(rows)) {
      rows.forEach(r => {
        if (!evSessions[r.station_id] || new Date(r.updated_at) > new Date(evSessions[r.station_id]?.updated_at || 0))
          evSessions[r.station_id] = r;
      });
    }
  } catch(e) {}

  const STATUS_COLORS = {
    charging:    { bg:"#dbeafe", color:"#1d4ed8" },
    available:   { bg:"#dcfce7", color:"#166534" },
    faulted:     { bg:"#fee2e2", color:"#991b1b" },
    offline:     { bg:"#f1f5f9", color:"#64748b" },
    preparing:   { bg:"#fef9c3", color:"#854d0e" },
    unavailable: { bg:"#fee2e2", color:"#991b1b" },
  };

  table.innerHTML = `
    <div style="overflow-x:auto;">
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead>
        <tr style="background:var(--surface2);">
          <th style="text-align:left;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;white-space:nowrap;">Charger</th>
          <th style="text-align:center;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">Status</th>
          <th style="text-align:right;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">Power (kW)</th>
          <th style="text-align:right;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">Session (kWh)</th>
          <th style="text-align:right;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">SOC</th>
          <th style="text-align:right;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">Voltage (V)</th>
          <th style="text-align:right;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">Current (A)</th>
          <th style="text-align:center;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">DR Shed</th>
          <th style="text-align:right;padding:8px 10px;border-bottom:1.5px solid var(--border-md);color:var(--text-hint);font-size:10px;text-transform:uppercase;">Last Seen</th>
        </tr>
      </thead>
      <tbody>
        ${evChargers.map((c, i) => {
          const sess     = evSessions[c.station_id];
          const status   = (sess?.status || c.status || "offline").toLowerCase();
          const sc       = STATUS_COLORS[status] || STATUS_COLORS.offline;
          const powerKw  = sess?.power_kw  != null ? parseFloat(sess.power_kw).toFixed(2)  : "—";
          const energyKwh= sess?.energy_kwh!= null ? parseFloat(sess.energy_kwh).toFixed(3) : "—";
          const soc      = sess?.soc_pct   != null ? sess.soc_pct + "%" : "—";
          const voltage  = sess?.voltage   != null ? parseFloat(sess.voltage).toFixed(1)   : "—";
          const current  = sess?.current_a != null ? parseFloat(sess.current_a).toFixed(2) : "—";
          const shed     = sess?.shed_active ? `<span style="color:var(--red);font-weight:700;">YES</span>` : `<span style="color:var(--text-hint);">—</span>`;
          const lastSeen = sess?.updated_at
            ? (() => { const ago = Math.round((Date.now() - new Date(sess.updated_at).getTime())/1000); return ago < 60 ? `${ago}s ago` : ago < 3600 ? `${Math.round(ago/60)}m ago` : `${Math.round(ago/3600)}h ago`; })()
            : "—";

          // SOC bar
          const socPct   = sess?.soc_pct;
          const socBar   = socPct != null
            ? `<div style="width:100%;height:3px;background:var(--border-md);border-radius:2px;margin-top:3px;"><div style="height:3px;width:${socPct}%;background:${socPct>50?"#16a34a":socPct>20?"#d97706":"#dc2626"};border-radius:2px;"></div></div>` : "";

          return `<tr style="${i%2?"background:var(--surface2)20;":""}border-bottom:0.5px solid var(--border);">
            <td style="padding:8px 10px;">
              <div style="font-weight:600;color:var(--text-primary);">${c.name}</div>
              <div style="font-size:10px;color:var(--text-hint);font-family:monospace;">${c.station_id}</div>
            </td>
            <td style="padding:8px 10px;text-align:center;">
              <span style="font-size:11px;font-weight:700;padding:3px 10px;border-radius:10px;background:${sc.bg};color:${sc.color};">
                ${status.charAt(0).toUpperCase()+status.slice(1)}
              </span>
            </td>
            <td style="padding:8px 10px;text-align:right;font-family:monospace;font-weight:700;color:${status==="charging"?"var(--blue-dark)":"var(--text-hint)"};">${powerKw}</td>
            <td style="padding:8px 10px;text-align:right;font-family:monospace;">${energyKwh}</td>
            <td style="padding:8px 10px;text-align:right;">
              <div style="font-family:monospace;">${soc}</div>
              ${socBar}
            </td>
            <td style="padding:8px 10px;text-align:right;font-family:monospace;">${voltage}</td>
            <td style="padding:8px 10px;text-align:right;font-family:monospace;">${current}</td>
            <td style="padding:8px 10px;text-align:center;">${shed}</td>
            <td style="padding:8px 10px;text-align:right;font-size:10px;color:var(--text-hint);white-space:nowrap;">${lastSeen}</td>
          </tr>`;
        }).join("")}
      </tbody>
    </table>
    </div>`;

  if (lastEl) lastEl.textContent = `Updated: ${new Date().toLocaleTimeString()}`;
}
// ── End EV Live Monitor ────────────────────────────────────────────────────────

// ── OpenADR 3.0 Signal Mapping & DR Config ────────────────────────────────────
function renderOadr3Mappings() {
  // Mirror the 2.0b mapping table but use SIMPLE signal levels 0-3
  const tbody = document.getElementById("oadr-mapping-table-3");
  if (!tbody) return;

  // Load saved mappings from same store as 2.0b (shared config)
  const saved = (() => {
    try { return JSON.parse(localStorage.getItem("lcp_oadr_mappings") || "{}"); } catch(e) { return {}; }
  })();

  const LEVELS = [
    { level:0, label:"0 — Normal",          desc:"Restore all load"              },
    { level:1, label:"1 — Low",             desc:"Low shed / 25% duty cycle"     },
    { level:2, label:"2 — Medium",          desc:"Medium shed / 50% duty cycle"  },
    { level:3, label:"3 — High/Emergency",  desc:"Full shed / 100% duty cycle"   },
  ];

  const STRATEGIES = [
    { val:"",        label:"— Restore —" },
    { val:"5",       label:"5 — 25% shed" },
    { val:"9",       label:"9 — 50% shed" },
    { val:"13",      label:"13 — 75% shed" },
    { val:"19",      label:"19 — 100% shed" },
  ];

  tbody.innerHTML = LEVELS.map(lv => {
    const m = saved[`oadr3_${lv.level}`] || saved[lv.level] || {};
    const strat = m.strategy || (lv.level === 0 ? "" : lv.level === 1 ? "5" : lv.level === 2 ? "9" : "19");
    const mode  = m.mode || "dlc";
    const pct   = strat === "5" ? "25%" : strat === "9" ? "50%" : strat === "13" ? "75%" : strat === "19" ? "100%" : "—";

    return `<tr style="border-bottom:0.5px solid var(--border);">
      <td style="padding:8px;font-weight:700;color:var(--blue-dark);">${lv.label}</td>
      <td style="padding:8px;color:var(--text-secondary);">${lv.desc}</td>
      <td style="padding:8px;">
        <select id="oadr3-map-strat-${lv.level}" style="padding:5px 8px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
          ${STRATEGIES.map(s => `<option value="${s.val}" ${s.val===strat?"selected":""}>${s.label}</option>`).join("")}
        </select>
      </td>
      <td style="padding:8px;">
        <select id="oadr3-map-mode-${lv.level}" style="padding:5px 8px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
          <option value="dlc" ${mode==="dlc"?"selected":""}>DLC</option>
          <option value="di"  ${mode==="di" ?"selected":""}>BAS</option>
        </select>
      </td>
      <td style="padding:8px;font-weight:600;color:var(--text-primary);">${pct}</td>
    </tr>`;
  }).join("");
}

function saveOadr3Mappings() {
  const saved = (() => {
    try { return JSON.parse(localStorage.getItem("lcp_oadr_mappings") || "{}"); } catch(e) { return {}; }
  })();
  [0,1,2,3].forEach(lv => {
    const strat = document.getElementById(`oadr3-map-strat-${lv}`)?.value || "";
    const mode  = document.getElementById(`oadr3-map-mode-${lv}`)?.value  || "dlc";
    saved[`oadr3_${lv}`] = { strategy:strat, mode };
  });
  localStorage.setItem("lcp_oadr_mappings", JSON.stringify(saved));
  const statusEl = document.getElementById("oadr3-mapping-status");
  if (statusEl) { statusEl.textContent = "✅ Mappings saved."; statusEl.style.display="block"; statusEl.style.color="var(--green-dark)"; setTimeout(()=>statusEl.style.display="none",2500); }
}

function renderOadr3DrConfig() {
  // Point to the shared dr-device-config-list-3 div, reuse same loadDRConfig data
  const list3 = document.getElementById("dr-device-config-list-3");
  const list2 = document.getElementById("dr-device-config-list");
  if (list3 && list2) {
    list3.innerHTML = list2.innerHTML || '<div class="sched-empty">Loading device DR configuration…</div>';
  }
}

async function simulateOadr3Event() {
  const statusEl = document.getElementById("oadr3-test-status");
  const level    = parseInt(document.getElementById("oadr3-test-signal")?.value ?? 2);
  const progId   = document.getElementById("oadr3-test-program")?.value;
  const durMins  = parseInt(document.getElementById("oadr3-test-duration")?.value || 30);

  if (!progId) {
    if (statusEl) { statusEl.textContent = "Please select a program."; statusEl.style.display="block"; statusEl.style.color="var(--red)"; }
    return;
  }

  const prog = oadr3Programs.find(p => p.id === progId);
  const vtn  = oadr3VTNs.find(v => v.id === prog?.vtn_id);
  if (!prog || !vtn) {
    if (statusEl) { statusEl.textContent = "Program or VTN not found."; statusEl.style.display="block"; statusEl.style.color="var(--red)"; }
    return;
  }

  if (statusEl) { statusEl.textContent = "⏳ Simulating event…"; statusEl.style.display="block"; statusEl.style.color="var(--text-secondary)"; }

  const now   = new Date();
  const start = new Date(now.getTime() + 60000); // 1 min from now
  const end   = new Date(start.getTime() + durMins * 60000);

  // Build synthetic OpenADR 3.0 event
  const syntheticEvent = {
    id:          `test-${Date.now()}`,
    eventName:   `Test Event — Level ${level}`,
    programID:   prog.program_id,
    intervalPeriod: {
      start:    start.toISOString(),
      duration: `PT${durMins}M`
    },
    intervals: [{
      id: 0,
      payloads: [{ type:"SIMPLE", values:[level] }]
    }]
  };

  try {
    await oadr3ExecuteEvent(vtn, prog, syntheticEvent, level);
    if (statusEl) { statusEl.textContent = `✅ Test event (Level ${level}) dispatched to ${prog.target_name || prog.target_id}. Check device status.`; statusEl.style.color="var(--green-dark)"; }
    await loadOadr3Events();
  } catch(e) {
    if (statusEl) { statusEl.textContent = `❌ Error: ${e.message}`; statusEl.style.color="var(--red)"; }
  }
}

// Populate test program dropdown when tab loads
function populateOadr3TestDropdown() {
  const sel = document.getElementById("oadr3-test-program");
  if (!sel) return;
  sel.innerHTML = '<option value="">— Select Program —</option>' +
    oadr3Programs.map(p => {
      const vtn = oadr3VTNs.find(v => v.id === p.vtn_id);
      return `<option value="${p.id}">${p.program_name || p.program_id} (${vtn?.name||"?"})</option>`;
    }).join("");
}
