// Relay Correlation Timeline
// ═══════════════════════════════════════════════════════════════════════════════
let _timelineData = null; // cached { readings, events, range }

async function loadRelayTimeline() {
  const deviceFilter = document.getElementById("timeline-device-select")?.value;
  const hours        = parseInt(document.getElementById("timeline-range")?.value || 24);
  const since        = new Date(Date.now() - hours * 3600000);
  const now          = new Date();
  const emptyEl      = document.getElementById("relay-timeline-empty");
  const canvas       = document.getElementById("relay-timeline-canvas");
  const wrap         = document.getElementById("relay-timeline-wrap");
  if (!canvas) return;

  if (emptyEl) emptyEl.textContent = "Loading timeline…";
  canvas.style.display = "none";

  // ── Fetch data in parallel ────────────────────────────────────────────────
  let readQuery = `device_readings?order=recorded_at.asc&recorded_at=gte.${since.toISOString()}&limit=2000`;
  if (deviceFilter) readQuery += `&device_uid=eq.${encodeURIComponent(deviceFilter)}`;

  let evQuery = `schedule_queue?order=fire_at.asc&fire_at=gte.${since.toISOString()}&limit=500`;
  if (deviceFilter) evQuery += `&target_id=eq.${encodeURIComponent(deviceFilter)}`;

  const [readings, events] = await Promise.all([
    supabaseGet(readQuery).catch(() => []),
    supabaseGet(evQuery).catch(() => [])
  ]);

  if (!Array.isArray(readings) || !readings.length) {
    if (emptyEl) { emptyEl.style.display = "block"; emptyEl.textContent = "No device readings found for selected range."; }
    return;
  }
  if (emptyEl) emptyEl.style.display = "none";

  // Group readings by device
  const byDevice = {};
  readings.forEach(r => {
    if (!byDevice[r.device_uid]) byDevice[r.device_uid] = [];
    byDevice[r.device_uid].push(r);
  });

  _timelineData = { byDevice, events: Array.isArray(events) ? events : [], since, now, hours };

  renderRelayTimeline();
}

function renderRelayTimeline() {
  if (!_timelineData) return;
  const { byDevice, events, since, now } = _timelineData;
  const canvas = document.getElementById("relay-timeline-canvas");
  const wrap   = document.getElementById("relay-timeline-wrap");
  if (!canvas || !wrap) return;

  const devices      = Object.keys(byDevice);
  const RELAYS       = ["relay_status_r1","relay_status_r2","relay_status_r3","relay_status_r4"];
  const RELAY_LABELS = ["R1","R2","R3","R4"];
  const ROW_H   = 32;
  const LABEL_W = 110;
  const HEADER_H= 40;
  const DEV_GAP = 16;
  const PAD_R   = 16;
  const DPR     = window.devicePixelRatio || 1;

  const cssW  = wrap.clientWidth || 900;
  const totalRows = devices.length * 4;
  const cssH  = HEADER_H + totalRows * ROW_H + Math.max(0, devices.length - 1) * DEV_GAP + 16;

  // Set canvas physical vs CSS size for sharp rendering
  canvas.width  = cssW  * DPR;
  canvas.height = cssH  * DPR;
  canvas.style.width  = cssW  + "px";
  canvas.style.height = cssH  + "px";
  canvas.style.display = "block";

  const ctx = canvas.getContext("2d");
  ctx.scale(DPR, DPR);   // all drawing now in CSS pixels

  const W      = cssW;
  const chartW = W - LABEL_W - PAD_R;
  const tStart = since.getTime();
  const tEnd   = now.getTime();
  const tRange = tEnd - tStart || 1;

  // Position helpers
  const tx  = t  => LABEL_W + Math.max(0, Math.min(1, (t - tStart) / tRange)) * chartW;
  const txC = ts => tx(new Date(ts).getTime());

  // Colors from CSS vars
  const cs = getComputedStyle(document.documentElement);
  const surface2 = cs.getPropertyValue("--surface2").trim() || "#f4f4f5";
  const borderMd = cs.getPropertyValue("--border-md").trim() || "#e2e2e7";
  const textHint = cs.getPropertyValue("--text-hint").trim() || "#8b8b99";
  const textPrim = cs.getPropertyValue("--text-primary").trim() || "#111";

  // Clear
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, W, cssH);

  // ── Time axis header ──────────────────────────────────────────────────────
  ctx.fillStyle = surface2;
  ctx.fillRect(0, 0, W, HEADER_H);

  ctx.strokeStyle = borderMd;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(LABEL_W, HEADER_H); ctx.lineTo(W - PAD_R, HEADER_H); ctx.stroke();

  const hours = _timelineData.hours;
  const tickN = hours <= 6 ? 6 : hours <= 24 ? 8 : hours <= 48 ? 8 : 7;
  ctx.fillStyle = textHint;
  ctx.font = `${10 * Math.min(1, cssW / 600)}px system-ui,sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";

  for (let i = 0; i <= tickN; i++) {
    const t  = tStart + (i / tickN) * tRange;
    const x  = tx(t);
    const d  = new Date(t);
    const lbl = hours <= 48
      ? d.toLocaleTimeString("en-US", { hour:"2-digit", minute:"2-digit" })
      : d.toLocaleDateString("en-US", { month:"short", day:"numeric" });

    ctx.fillStyle = textHint;
    ctx.fillText(lbl, x, HEADER_H / 2);

    // Tick line through whole chart
    ctx.strokeStyle = borderMd + "80";
    ctx.lineWidth = 0.5;
    ctx.setLineDash([2, 3]);
    ctx.beginPath(); ctx.moveTo(x, HEADER_H); ctx.lineTo(x, cssH); ctx.stroke();
    ctx.setLineDash([]);
  }

  // ── Relay rows ────────────────────────────────────────────────────────────
  let rowY = HEADER_H;
  const rowMap = {}; // uid -> { y, rows: [...] }

  devices.forEach((uid, di) => {
    const devName = DEVICES.find(d => d.uid === uid)?.name || uid.slice(-8);
    const rrows   = byDevice[uid];
    rowMap[uid]   = { y: rowY };

    RELAYS.forEach((rKey, ri) => {
      const y   = rowY + ri * ROW_H;
      const mid = y + ROW_H / 2;

      // Row bg
      ctx.fillStyle = ri % 2 === 0 ? "#ffffff" : surface2;
      ctx.fillRect(LABEL_W, y, chartW, ROW_H);

      // Device name above first relay row
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      if (ri === 0) {
        ctx.fillStyle = textPrim;
        ctx.font = `bold 11px system-ui,sans-serif`;
        ctx.fillText(devName, LABEL_W - 6, mid - 8);
      }
      ctx.fillStyle = textHint;
      ctx.font = `bold 10px system-ui,sans-serif`;
      ctx.fillText(RELAY_LABELS[ri], LABEL_W - 6, ri === 0 ? mid + 6 : mid);

      // ── Green ON bars ───────────────────────────────────────────────────
      const isOn = r => r[rKey] === true || r[rKey] === 1 || r[rKey] === "1" || r[rKey] === "true";

      let segStart = null;
      rrows.forEach((r, idx) => {
        const t = new Date(r.recorded_at).getTime();
        if (isOn(r)) {
          if (segStart === null) segStart = t;
        } else {
          if (segStart !== null) {
            // Draw segment segStart → t
            const x1 = tx(segStart), x2 = tx(t);
            if (x2 > x1 + 1) {
              ctx.fillStyle = "#dcfce7";
              ctx.fillRect(x1, y + 5, x2 - x1, ROW_H - 10);
              ctx.fillStyle = "#16a34a";
              ctx.fillRect(x1, y + 5, 3, ROW_H - 10);
              ctx.fillRect(x2 - 3, y + 5, 3, ROW_H - 10);
            }
            segStart = null;
          }
        }
        // Last reading still ON → extend to now
        if (idx === rrows.length - 1 && isOn(r) && segStart !== null) {
          const x1 = tx(segStart), x2 = tx(tEnd);
          if (x2 > x1 + 1) {
            ctx.fillStyle = "#dcfce7";
            ctx.fillRect(x1, y + 5, x2 - x1, ROW_H - 10);
            ctx.fillStyle = "#16a34a";
            ctx.fillRect(x1, y + 5, 3, ROW_H - 10);
            // Pulsing right edge (open-ended)
            ctx.fillStyle = "#16a34a88";
            ctx.fillRect(x2 - 3, y + 5, 3, ROW_H - 10);
          }
        }
      });

      // Row divider
      ctx.strokeStyle = borderMd;
      ctx.lineWidth = 0.5;
      ctx.beginPath(); ctx.moveTo(LABEL_W, y + ROW_H); ctx.lineTo(W - PAD_R, y + ROW_H); ctx.stroke();
    });

    // Device separator line
    if (di < devices.length - 1) {
      const sepY = rowY + 4 * ROW_H + DEV_GAP / 2;
      ctx.strokeStyle = borderMd;
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(0, sepY); ctx.lineTo(W, sepY); ctx.stroke();
    }

    rowY += 4 * ROW_H + DEV_GAP;
  });

  // Label border
  ctx.strokeStyle = borderMd;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(LABEL_W, HEADER_H); ctx.lineTo(LABEL_W, cssH); ctx.stroke();

  // ── Event markers ─────────────────────────────────────────────────────────
  const EVENT_COLORS = {
    autopilot:"#DC2626", fired:"#DC2626",
    openadr:"#D97706",   openADR:"#D97706",
    switch:"#378ADD",    bas_di:"#378ADD",
    sent:"#378ADD",      pending:"#378ADD",
    hybrid:"#7C3AED",    battery:"#16a34a",
    generator:"#D97706", ev:"#0ea5e9",
    manual:"#7C3AED"
  };

  // Color resolution: tier > AUTO: name prefix > fired status > event_type > status
  const getEvColor = (ev) => {
    if (ev.tier === "autopilot")                    return EVENT_COLORS.autopilot;
    if (ev.status === "fired")                      return EVENT_COLORS.fired;
    if ((ev.name || "").startsWith("AUTO:"))        return EVENT_COLORS.autopilot;
    return EVENT_COLORS[ev.event_type] || EVENT_COLORS[ev.status] || "#378ADD";
  };

  _timelineData.markers = [];

  console.log(`Timeline: ${events.length} events to draw`);

  events.forEach(ev => {
    const fireAt = ev.fire_at ? new Date(ev.fire_at).getTime() : null;
    if (!fireAt) return;
    if (fireAt < tStart - 60000 || fireAt > tEnd + 60000) {
      console.log(`Event outside range: ${ev.name} at ${new Date(fireAt).toISOString()}`);
      return;
    }

    const color  = getEvColor(ev);
    const x      = tx(fireAt);
    const durMs  = (ev.duration_minutes || 0) * 60000;
    const endX   = durMs ? tx(Math.min(fireAt + durMs, tEnd)) : null;

    // Duration band
    if (endX && endX > x + 2) {
      ctx.fillStyle = color + "14";
      ctx.fillRect(x, HEADER_H, endX - x, cssH - HEADER_H);
    }

    // Vertical dashed line
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 4]);
    ctx.beginPath(); ctx.moveTo(x, HEADER_H + 18); ctx.lineTo(x, cssH); ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();

    // Diamond at top
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x,     HEADER_H + 2);
    ctx.lineTo(x + 7, HEADER_H + 10);
    ctx.lineTo(x,     HEADER_H + 18);
    ctx.lineTo(x - 7, HEADER_H + 10);
    ctx.closePath();
    ctx.fill();

    // White label background + event name
    const label = (ev.name || ev.event_type || "Event").slice(0, 18);
    ctx.font = "bold 9px system-ui,sans-serif";
    const lw = ctx.measureText(label).width;
    const lx = Math.min(x + 4, W - PAD_R - lw - 4);
    ctx.fillStyle = "rgba(255,255,255,0.85)";
    ctx.fillRect(lx - 2, HEADER_H + 20, lw + 4, 13);
    ctx.fillStyle = color;
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(label, lx, HEADER_H + 21);

    _timelineData.markers.push({ x, cssX: x, ev, color, fireAt, durMs, endX });
  });

  console.log(`Timeline rendered: ${_timelineData.markers.length} markers, ${Object.keys(byDevice).length} devices`);

  // ── Legend ────────────────────────────────────────────────────────────────
  const legEl = document.getElementById("relay-timeline-legend");
  if (legEl) {
    legEl.style.display = "block";
    const readCount = Object.values(byDevice).reduce((s,a) => s + a.length, 0);
    legEl.textContent = `${readCount} readings · ${events.length} events · ${since.toLocaleString([], {dateStyle:"short",timeStyle:"short"})} → ${now.toLocaleTimeString([], {timeStyle:"short"})}`;
  }

  // ── Mouse events ──────────────────────────────────────────────────────────
  // Recalculate marker X from timestamp at event time (not stored cssX)
  // so it's always correct regardless of scroll/resize/DPR
  const liveX = (fireAt) => {
    const rect   = canvas.getBoundingClientRect();
    const cssW2  = rect.width;
    const chartW2 = cssW2 - LABEL_W - PAD_R;
    return LABEL_W + Math.max(0, Math.min(1, (fireAt - tStart) / tRange)) * chartW2;
  };

  const getCanvasX = (e) => {
    const rect = canvas.getBoundingClientRect();
    return e.clientX - rect.left;
  };

  canvas.onmousemove = (e) => {
    const mx      = getCanvasX(e);
    const tooltip = document.getElementById("relay-timeline-tooltip");
    if (!tooltip) return;

    let nearest = null, minDist = 14;
    (_timelineData?.markers || []).forEach(m => {
      const lx = liveX(m.fireAt);
      const d  = Math.abs(lx - mx);
      if (d < minDist) { minDist = d; nearest = m; }
    });

    if (nearest) {
      const ev = nearest.ev;
      const typeMap = { switch:"⚡ Switch/Relay", bas_di:"🏢 BAS Mode", ev:"🔌 EV Charger",
        battery:"🔋 Battery", generator:"⚙️ Generator", openadr:"📡 OpenADR",
        hybrid:"🔀 Hybrid", openADR:"📡 OpenADR" };
      tooltip.style.display  = "block";
      tooltip.style.left     = (e.clientX + 14) + "px";
      tooltip.style.top      = (e.clientY - 14) + "px";
      tooltip.style.borderColor = nearest.color;
      tooltip.innerHTML = `
        <div style="font-weight:700;color:${nearest.color};margin-bottom:4px;font-size:12px;">${ev.name || "Event"}</div>
        <div style="color:#555;margin-bottom:2px;">${typeMap[ev.event_type] || ev.event_type || "—"}</div>
        <div style="color:#777;margin-bottom:2px;">🎯 ${ev.target_name || ev.target_id || "—"}</div>
        <div style="color:#777;margin-bottom:2px;">📅 ${new Date(nearest.fireAt).toLocaleString()}</div>
        ${ev.duration_minutes ? `<div style="color:#777;">⏱ ${ev.duration_minutes} min</div>` : ""}
        <div style="margin-top:5px;padding-top:5px;border-top:1px solid #eee;">
          <span style="font-size:10px;padding:1px 7px;border-radius:8px;background:${nearest.color}22;color:${nearest.color};font-weight:700;">${ev.status||"—"}</span>
          <span style="font-size:10px;color:#aaa;margin-left:6px;">Click to view details</span>
        </div>`;
      canvas.style.cursor = "pointer";
    } else {
      tooltip.style.display = "none";
      canvas.style.cursor   = "default";
    }
  };

  canvas.onmouseleave = () => {
    const t = document.getElementById("relay-timeline-tooltip");
    if (t) t.style.display = "none";
    canvas.style.cursor = "default";
  };

  canvas.onclick = (e) => {
    const mx = getCanvasX(e);
    let nearest = null, minDist = 16;
    (_timelineData?.markers || []).forEach(m => {
      const lx = liveX(m.fireAt);
      const d  = Math.abs(lx - mx);
      if (d < minDist) { minDist = d; nearest = m; }
    });
    if (nearest) showEventDetail({ type:"queue", item: nearest.ev });
  };
}

// Redraw on resize
window.addEventListener("resize", () => {
  if (_timelineData) renderRelayTimeline();
});

// Wire device selector
function initTimelineDeviceSelect() {
  const sel = document.getElementById("timeline-device-select");
  if (!sel) return;
  const relays = DEVICES.filter(d => (!d.type || d.type === "relay") && !d.uid.includes("PLACEHOLDER"));
  sel.innerHTML = '<option value="">All Devices</option>' +
    relays.map(d => `<option value="${d.uid}">${d.name}</option>`).join("");
}
// ═══════════════════════════════════════════════════════════════════════════════
// End Relay Correlation Timeline
// ═══════════════════════════════════════════════════════════════════════════════

// ── Chart tab selector ────────────────────────────────────────────────────────
function selectChart(which, btn) {
  document.querySelectorAll(".chart-tab-btn").forEach(b => b.classList.remove("active"));
  document.querySelectorAll(".chart-panel").forEach(p => p.style.display = "none");
  if (btn) btn.classList.add("active");
  const panel = document.getElementById(`chart-panel-${which}`);
  if (panel) {
    panel.style.display = "block";
    // Must resize AFTER display:block so Chart.js can read actual container dimensions
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        const instance = chartInstances[`chart-${which}`];
        if (instance) instance.resize();
      });
    });
  }
}
// ── End Chart Tab ─────────────────────────────────────────────────────────────

// ── Outage URL Float Helper ───────────────────────────────────────────────────
let _outageFloatTargetField = "new-util-map-url";

function showOutageFloat(utilName, homepageUrl, targetFieldId) {
  _outageFloatTargetField = targetFieldId || "new-util-map-url";
  const panel   = document.getElementById("outage-url-float");
  const nameEl  = document.getElementById("outage-float-util-name");
  const reopenEl= document.getElementById("outage-float-reopen");
  const input   = document.getElementById("outage-float-input");
  const hint    = document.getElementById("outage-float-hint");
  if (!panel) return;
  if (nameEl)   nameEl.textContent = utilName || "the utility";
  if (reopenEl) { reopenEl.href = homepageUrl || "#"; reopenEl.textContent = `↗ Re-open ${utilName || "utility website"}`; }
  if (input)    input.value = "";
  if (hint)     hint.textContent = "";
  panel.style.display = "block";
  // Animate in
  panel.style.transform = "translateY(20px)";
  panel.style.opacity   = "0";
  panel.style.transition = "transform 0.2s ease, opacity 0.2s ease";
  requestAnimationFrame(() => {
    panel.style.transform = "translateY(0)";
    panel.style.opacity   = "1";
  });
  if (input) setTimeout(() => input.focus(), 250);
}

function closeOutageFloat() {
  const panel = document.getElementById("outage-url-float");
  if (!panel) return;
  panel.style.transform = "translateY(20px)";
  panel.style.opacity   = "0";
  setTimeout(() => { panel.style.display = "none"; }, 200);
}

function outageFloatValidate() {
  const input  = document.getElementById("outage-float-input");
  const btn    = document.getElementById("outage-float-set-btn");
  const hint   = document.getElementById("outage-float-hint");
  const val    = input?.value?.trim() || "";
  const isUrl  = val.startsWith("http://") || val.startsWith("https://");
  if (btn)  btn.disabled = !isUrl;
  if (btn)  btn.style.opacity = isUrl ? "1" : "0.5";
  if (hint) hint.textContent = val && !isUrl ? "Must be a full URL starting with https://" : "";
}

function outageFloatSet() {
  const input  = document.getElementById("outage-float-input");
  const val    = input?.value?.trim() || "";
  if (!val.startsWith("http")) return;
  // Set the target field
  const targetEl = document.getElementById(_outageFloatTargetField);
  if (targetEl) {
    targetEl.value = val;
    targetEl.style.background = "var(--green-lt)";
    setTimeout(() => { targetEl.style.background = ""; }, 1500);
  }
  // Update result area
  const resultEl = document.getElementById("outage-search-result");
  if (resultEl) {
    resultEl.innerHTML = `<span style="color:var(--green-dark);">✓ Outage map URL set: <a href="${val}" target="_blank" style="color:var(--blue-dark);">${val}</a></span>`;
  }
  closeOutageFloat();
}

// Make float draggable
(function() {
  let dragging = false, ox = 0, oy = 0;
  document.addEventListener("DOMContentLoaded", () => {
    const panel  = document.getElementById("outage-url-float");
    const header = panel?.querySelector("div[style*='background:var(--blue-dark)']");
    if (!header || !panel) return;
    header.style.cursor = "move";
    header.addEventListener("mousedown", e => {
      dragging = true;
      const rect = panel.getBoundingClientRect();
      ox = e.clientX - rect.left;
      oy = e.clientY - rect.top;
      e.preventDefault();
    });
    document.addEventListener("mousemove", e => {
      if (!dragging) return;
      const x = e.clientX - ox;
      const y = e.clientY - oy;
      panel.style.left   = `${Math.max(0, Math.min(window.innerWidth  - panel.offsetWidth,  x))}px`;
      panel.style.top    = `${Math.max(0, Math.min(window.innerHeight - panel.offsetHeight, y))}px`;
      panel.style.right  = "auto";
      panel.style.bottom = "auto";
    });
    document.addEventListener("mouseup", () => { dragging = false; });
  });
})();
// ── End Outage Float ──────────────────────────────────────────────────────────

// ── Rule Form — Event Type & Hybrid ──────────────────────────────────────────
let selectedRuleEventType = "switch";

function selectRuleEventType(type) {
  selectedRuleEventType = type;
  document.querySelectorAll("#rule-event-type-tiles .rule-event-tile").forEach(el => {
    el.classList.toggle("selected", el.dataset.type === type);
  });
  // Show/hide panels
  ["switch","bas_di","ev","battery","generator","openADR"].forEach(t => {
    const el = document.getElementById(`rule-panel-${t}`);
    if (el) el.style.display = t === type ? "block" : "none";
  });
  // Reset switch mode to uniform when switching away
  if (type !== "switch") {
    const modeEl = document.getElementById("rule-switch-mode");
    if (modeEl) modeEl.value = "uniform";
    onRuleSwitchModeChange();
  }
}

function onRuleSwitchModeChange() {
  const mode       = document.getElementById("rule-switch-mode")?.value;
  const hybridEl   = document.getElementById("rule-hybrid-section");
  const relayCol   = document.getElementById("rule-relay-action-col");
  const modeCol    = document.getElementById("rule-mode-col");
  const stratCol   = document.getElementById("rule-strategy-col");
  const isHybrid   = mode === "hybrid";
  if (hybridEl) hybridEl.style.display = isHybrid ? "block" : "none";
  if (relayCol) { relayCol.style.display = isHybrid ? "none" : "block"; }
  if (modeCol)  { modeCol.style.display  = isHybrid ? "none" : "block"; }
  if (stratCol) { stratCol.style.display = isHybrid ? "none" : "block"; }
  if (isHybrid) renderRuleHybridRows();
}

function renderRuleHybridRows() {
  const container = document.getElementById("rule-hybrid-rows");
  if (!container) return;
  container.innerHTML = [1,2,3,4].map(r => `
    <div style="display:grid;grid-template-columns:32px 80px 120px 1fr;gap:0;padding:8px 12px;border-bottom:0.5px solid var(--border);align-items:center;" id="rule-relay-row-${r}">
      <input type="checkbox" id="rule-relay-${r}-active" checked onchange="onRuleRelayActiveChange(${r})"
        style="width:15px;height:15px;accent-color:var(--blue-dark);cursor:pointer;" />
      <span style="font-size:13px;font-weight:700;color:var(--text-primary);">Relay ${r}</span>
      <div id="rule-relay-${r}-mode-col">
        <label style="display:flex;align-items:center;gap:5px;cursor:pointer;margin-bottom:3px;">
          <input type="radio" name="rule-relay-${r}-mode" value="dlc" checked onchange="onRuleRelayModeChange(${r})" style="accent-color:var(--blue-dark);" />
          <span style="font-size:11px;font-weight:600;color:var(--blue-dark);">DLC</span>
        </label>
        <label style="display:flex;align-items:center;gap:5px;cursor:pointer;">
          <input type="radio" name="rule-relay-${r}-mode" value="bas" onchange="onRuleRelayModeChange(${r})" style="accent-color:var(--green-dark);" />
          <span style="font-size:11px;font-weight:600;color:var(--green-dark);">BAS</span>
        </label>
      </div>
      <div id="rule-relay-${r}-setting">
        <select class="sched-select" id="rule-relay-${r}-dlc" style="font-size:11px;">
          <option value="19|30|30">100% — Full Shed</option>
          <option value="17|27|30">90% — High</option>
          <option value="13|21|30">75% — High-Med</option>
          <option value="9|15|30" selected>50% — Medium</option>
          <option value="6|10|30">33% — Low-Med</option>
          <option value="5|7.5|30">25% — Low</option>
        </select>
      </div>
    </div>
  `).join("");
}

function onRuleRelayActiveChange(r) {
  const active  = document.getElementById(`rule-relay-${r}-active`)?.checked;
  const modeCol = document.getElementById(`rule-relay-${r}-mode-col`);
  const setting = document.getElementById(`rule-relay-${r}-setting`);
  const label   = document.querySelector(`#rule-relay-row-${r} span`);
  const opacity = active ? "1" : "0.35";
  const pointer = active ? "auto" : "none";
  if (modeCol) { modeCol.style.opacity = opacity; modeCol.style.pointerEvents = pointer; }
  if (setting) { setting.style.opacity = opacity; setting.style.pointerEvents = pointer; }
  if (label)   label.style.color = active ? "var(--text-primary)" : "var(--text-hint)";
}

function onRuleRelayModeChange(r) {
  const mode    = document.querySelector(`input[name="rule-relay-${r}-mode"]:checked`)?.value;
  const setting = document.getElementById(`rule-relay-${r}-setting`);
  if (!setting) return;
  if (mode === "bas") {
    setting.innerHTML = `<select class="sched-select" id="rule-relay-${r}-bas" style="font-size:11px;">
      <option value="19|30|30">Emergency — Relay ON</option>
      <option value="17|27|30">High — Relay ON</option>
      <option value="5|7.5|30">Low — Relay ON</option>
      <option value="61|30|30">Restore — Relay ON</option>
    </select>`;
  } else {
    setting.innerHTML = `<select class="sched-select" id="rule-relay-${r}-dlc" style="font-size:11px;">
      <option value="19|30|30">100% — Full Shed</option>
      <option value="17|27|30">90% — High</option>
      <option value="13|21|30">75% — High-Med</option>
      <option value="9|15|30" selected>50% — Medium</option>
      <option value="6|10|30">33% — Low-Med</option>
      <option value="5|7.5|30">25% — Low</option>
    </select>`;
  }
}

function getRuleHybridConfig() {
  const dlcRelays = [], basRelays = [];
  [1,2,3,4].forEach(r => {
    if (!document.getElementById(`rule-relay-${r}-active`)?.checked) return;
    const mode     = document.querySelector(`input[name="rule-relay-${r}-mode"]:checked`)?.value || "dlc";
    const stratVal = mode === "bas"
      ? document.getElementById(`rule-relay-${r}-bas`)?.value
      : document.getElementById(`rule-relay-${r}-dlc`)?.value;
    const action = `relay${r}_on`;
    if (mode === "bas") basRelays.push({ num:r, action, stratVal });
    else               dlcRelays.push({ num:r, action, stratVal });
  });
  return { dlcRelays, basRelays };
}

function applyRuleHybridConfig(cfg) {
  // Restore saved hybrid config into the relay grid
  const allRelays = [...(cfg.dlcRelays||[]), ...(cfg.basRelays||[])];
  const activeNums = new Set(allRelays.map(r => r.num));
  [1,2,3,4].forEach(r => {
    const activeEl = document.getElementById(`rule-relay-${r}-active`);
    if (activeEl) { activeEl.checked = activeNums.has(r); onRuleRelayActiveChange(r); }
    const relCfg = allRelays.find(x => x.num === r);
    if (!relCfg) return;
    const mode = cfg.basRelays?.some(x=>x.num===r) ? "bas" : "dlc";
    const radio = document.querySelector(`input[name="rule-relay-${r}-mode"][value="${mode}"]`);
    if (radio) { radio.checked = true; onRuleRelayModeChange(r); }
    setTimeout(() => {
      const sel = document.getElementById(`rule-relay-${r}-${mode}`);
      if (sel && relCfg.stratVal) sel.value = relCfg.stratVal;
    }, 50);
  });
}

// ── End Rule Form Helpers ─────────────────────────────────────────────────────
// ── EV / Battery / Generator Target Type selectors ───────────────────────────
function populateAssetTarget(typeId, targetId, assetType) {
  const type   = document.getElementById(typeId)?.value;
  const target = document.getElementById(targetId);
  if (!target) return;
  target.innerHTML = '<option value="" disabled selected>— Choose One —</option>';

  if (type === "group") {
    // Show groups that contain at least one asset of this type
    const groupNums = new Set();
    DEVICES.filter(d => d.type === assetType).forEach(d => {
      (groupAssignments[d.uid] || []).forEach(g => groupNums.add(g));
    });
    // Also show all groups if none specifically tagged (fallback)
    if (!groupNums.size) {
      Object.values(groupAssignments).flat().forEach(g => groupNums.add(g));
    }
    [...groupNums].sort((a,b)=>a-b).forEach(g => {
      const name = groupNames[g] || `Group ${g}`;
      const opt = document.createElement("option");
      opt.value = `group_${g}`;
      opt.textContent = name;
      target.appendChild(opt);
    });
  } else if (type === "device") {
    DEVICES.filter(d => d.type === assetType).forEach(d => {
      const opt = document.createElement("option");
      opt.value = d.uid;
      opt.textContent = d.name;
      target.appendChild(opt);
    });
  }
}

function onEvTargetTypeChange()   { populateAssetTarget("sf-ev-target-type",   "sf-ev-target",   "ev");        }
function onBattTargetTypeChange() { populateAssetTarget("sf-batt-target-type", "sf-batt-target", "battery");   }
function onGenTargetTypeChange()  { populateAssetTarget("sf-gen-target-type",  "sf-gen-target",  "generator"); }
function onThermTargetTypeChange(){ populateAssetTarget("sf-therm-target-type","sf-therm-target","thermostat"); }
// ── End Asset Target Selectors ────────────────────────────────────────────────



const BAS_LEVELS = [
  { value: "19|30|30", label: "Emergency", sub: "Relay ON — highest priority" },
  { value: "17|27|30", label: "High",      sub: "Relay ON — high priority"    },
  { value: "5|7.5|30", label: "Low",       sub: "Relay ON — low priority"     },
  { value: "61|30|30", label: "Restore",   sub: "Relay ON — restore normal"   },
];

function onSwitchModeChange() {
  const mode = document.getElementById("sf-switch-mode")?.value;
  const uniformEl = document.getElementById("sf-uniform-section");
  const hybridEl  = document.getElementById("sf-hybrid-section");
  if (!uniformEl || !hybridEl) return;

  if (mode === "hybrid") {
    uniformEl.style.display = "none";
    hybridEl.style.display  = "block";
    renderHybridRows();
  } else {
    uniformEl.style.display = "block";
    hybridEl.style.display  = "none";
  }
}

function onSwitchTargetChange() {
  const typeEl = document.getElementById("sf-target-type");
  const modeEl = document.getElementById("sf-switch-mode");
  // Hybrid only makes sense for individual devices — hide option for groups
  if (!modeEl) return;
  const isGroup = typeEl?.value === "group";
  const hybridOpt = modeEl.querySelector('option[value="hybrid"]');
  if (hybridOpt) hybridOpt.disabled = isGroup;
  if (isGroup && modeEl.value === "hybrid") {
    modeEl.value = "uniform";
    onSwitchModeChange();
  }
}

function renderHybridRows() {
  const container = document.getElementById("sf-hybrid-rows");
  if (!container) return;

  container.innerHTML = [1,2,3,4].map(r => `
    <div style="display:grid;grid-template-columns:32px 80px 120px 1fr;gap:0;padding:10px 12px;border-bottom:0.5px solid var(--border);align-items:center;" id="sf-relay-row-${r}">
      <div>
        <input type="checkbox" id="sf-relay-${r}-active" checked
          onchange="onRelayActiveChange(${r})"
          style="width:15px;height:15px;accent-color:var(--blue-dark);cursor:pointer;" />
      </div>
      <span style="font-size:13px;font-weight:700;color:var(--text-primary);">Relay ${r}</span>
      <div id="sf-relay-${r}-mode-col">
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer;margin-bottom:4px;">
          <input type="radio" name="sf-relay-${r}-mode" value="dlc" checked
            onchange="onRelayModeChange(${r})" style="accent-color:var(--blue-dark);" />
          <span style="font-size:12px;font-weight:600;color:var(--blue-dark);">DLC</span>
        </label>
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer;">
          <input type="radio" name="sf-relay-${r}-mode" value="bas"
            onchange="onRelayModeChange(${r})" style="accent-color:var(--green-dark);" />
          <span style="font-size:12px;font-weight:600;color:var(--green-dark);">BAS</span>
        </label>
      </div>
      <div id="sf-relay-${r}-setting">
        <select class="sched-select" id="sf-relay-${r}-dlc" style="font-size:11px;">
          <option value="19|30|30">100% — Full Shed</option>
          <option value="17|27|30">90% — High</option>
          <option value="13|21|30">75% — High-Med</option>
          <option value="9|15|30" selected>50% — Medium</option>
          <option value="6|10|30">33% — Low-Med</option>
          <option value="5|7.5|30">25% — Low</option>
        </select>
      </div>
    </div>
  `).join("");
}

function onRelayActiveChange(relayNum) {
  const active   = document.getElementById(`sf-relay-${relayNum}-active`)?.checked;
  const modeCol  = document.getElementById(`sf-relay-${relayNum}-mode-col`);
  const setting  = document.getElementById(`sf-relay-${relayNum}-setting`);
  const label    = document.querySelector(`#sf-relay-row-${relayNum} span`);
  const opacity  = active ? "1" : "0.35";
  const pointer  = active ? "auto" : "none";
  if (modeCol) { modeCol.style.opacity = opacity; modeCol.style.pointerEvents = pointer; }
  if (setting) { setting.style.opacity = opacity; setting.style.pointerEvents = pointer; }
  if (label)   { label.style.color = active ? "var(--text-primary)" : "var(--text-hint)"; }
}

function onRelayModeChange(relayNum) {
  const mode    = document.querySelector(`input[name="sf-relay-${relayNum}-mode"]:checked`)?.value;
  const setting = document.getElementById(`sf-relay-${relayNum}-setting`);
  if (!setting) return;

  if (mode === "bas") {
    setting.innerHTML = `<select class="sched-select" id="sf-relay-${relayNum}-bas" style="font-size:11px;">
      ${BAS_LEVELS.map(l => `<option value="${l.value}">${l.label} — ${l.sub}</option>`).join("")}
    </select>`;
  } else {
    setting.innerHTML = `<select class="sched-select" id="sf-relay-${relayNum}-dlc" style="font-size:11px;">
      <option value="19|30|30">100% — Full Shed</option>
      <option value="17|27|30">90% — High</option>
      <option value="13|21|30">75% — High-Med</option>
      <option value="9|15|30" selected>50% — Medium</option>
      <option value="6|10|30">33% — Low-Med</option>
      <option value="5|7.5|30">25% — Low</option>
    </select>`;
  }
}

function getHybridConfig() {
  // Returns { dlcRelays: [{num, action, strategy}], basRelays: [{num, action, strategy}] }
  // Only includes relays where the participation checkbox is checked
  const dlcRelays = [], basRelays = [];
  [1,2,3,4].forEach(r => {
    const active   = document.getElementById(`sf-relay-${r}-active`)?.checked;
    if (!active) return; // skip unchecked relays
    const mode     = document.querySelector(`input[name="sf-relay-${r}-mode"]:checked`)?.value || "dlc";
    const stratVal = mode === "bas"
      ? document.getElementById(`sf-relay-${r}-bas`)?.value
      : document.getElementById(`sf-relay-${r}-dlc`)?.value;
    const action = `relay${r}_on`;
    if (mode === "bas") basRelays.push({ num:r, action, stratVal });
    else               dlcRelays.push({ num:r, action, stratVal });
  });
  return { dlcRelays, basRelays };
}


