const THEMES = {
  default:  { bg:"#f5f5f3", surface:"#ffffff", surface2:"#f0efeb", textPrimary:"#1a1a18", textSecondary:"#5f5e5a", textHint:"#888780", border:"rgba(0,0,0,0.10)", borderMd:"rgba(0,0,0,0.18)" },
  white:    { bg:"#ffffff", surface:"#f8f8f8", surface2:"#f0f0f0", textPrimary:"#1a1a18", textSecondary:"#5f5e5a", textHint:"#888780", border:"rgba(0,0,0,0.10)", borderMd:"rgba(0,0,0,0.18)" },
  slate:    { bg:"#e8eaed", surface:"#ffffff", surface2:"#f0f1f3", textPrimary:"#1a1a18", textSecondary:"#5f5e5a", textHint:"#888780", border:"rgba(0,0,0,0.10)", borderMd:"rgba(0,0,0,0.18)" },
  warm:     { bg:"#fdf6ec", surface:"#ffffff", surface2:"#f7efe0", textPrimary:"#1a1208", textSecondary:"#5f4e3a", textHint:"#8f7a60", border:"rgba(0,0,0,0.10)", borderMd:"rgba(0,0,0,0.18)" },
  cool:     { bg:"#eef2f7", surface:"#ffffff", surface2:"#e4ebf4", textPrimary:"#0e1c2f", textSecondary:"#3a5270", textHint:"#7090b0", border:"rgba(0,0,0,0.10)", borderMd:"rgba(0,0,0,0.18)" },
  sage:     { bg:"#eef4f0", surface:"#ffffff", surface2:"#e2ede5", textPrimary:"#0e1f14", textSecondary:"#3a5940", textHint:"#6b8f72", border:"rgba(0,0,0,0.10)", borderMd:"rgba(0,0,0,0.18)" },
  charcoal: { bg:"#2b2b2b", surface:"#363636", surface2:"#404040", textPrimary:"#f0eeea", textSecondary:"#b8b4ae", textHint:"#888480", border:"rgba(255,255,255,0.10)", borderMd:"rgba(255,255,255,0.18)" },
  navy:     { bg:"#1c2a3a", surface:"#243344", surface2:"#2c3d50", textPrimary:"#e8eef5", textSecondary:"#9ab0c8", textHint:"#6a8aa8", border:"rgba(255,255,255,0.10)", borderMd:"rgba(255,255,255,0.18)" },
  forest:   { bg:"#1a2e22", surface:"#213829", surface2:"#294230", textPrimary:"#e2ede5", textSecondary:"#8ab89a", textHint:"#5a8868", border:"rgba(255,255,255,0.10)", borderMd:"rgba(255,255,255,0.18)" },
};

function applyTheme(name) {
  const t = THEMES[name] || THEMES.default;
  const root = document.documentElement.style;
  root.setProperty("--bg",             t.bg);
  root.setProperty("--surface",        t.surface);
  root.setProperty("--surface2",       t.surface2);
  root.setProperty("--text-primary",   t.textPrimary);
  root.setProperty("--text-secondary", t.textSecondary);
  root.setProperty("--text-hint",      t.textHint);
  root.setProperty("--border",         t.border);
  root.setProperty("--border-md",      t.borderMd);

  // Update sticky header background
  const hdr = document.querySelector(".sticky-header");
  if (hdr) hdr.style.background = t.bg;

  // Update all swatch instances (admin card + prefs modal)
  document.querySelectorAll(".theme-swatch").forEach(s => {
    s.classList.toggle("active", s.dataset.theme === name);
  });

  // Persist
  try { localStorage.setItem("lcp_theme", name); } catch(e) {}
}


function applyFontSize(size) {
  // Map label to zoom factor
  const ZOOM_MAP = { "12px": 0.85, "14px": 1.0, "16px": 1.14, "18px": 1.28, "20px": 1.42 };
  const zoom = ZOOM_MAP[size] || 1.0;
  document.body.style.zoom = zoom;

  // Update all font size button instances (admin card + prefs modal)
  document.querySelectorAll(".font-size-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.size === size);
  });

  try { localStorage.setItem("lcp_font_size", size); } catch(e) {}
}

function initFontSize() {
  let saved = "14px";
  try { saved = localStorage.getItem("lcp_font_size") || "14px"; } catch(e) {}
  applyFontSize(saved);

  document.querySelectorAll(".font-size-btn").forEach(btn => {
    btn.addEventListener("click", () => applyFontSize(btn.dataset.size));
  });
}

function initTheme() {
  let saved = "default";
  try { saved = localStorage.getItem("lcp_theme") || "default"; } catch(e) {}
  applyTheme(saved);

  // Wire up all swatch instances
  document.querySelectorAll(".theme-swatch").forEach(swatch => {
    swatch.addEventListener("click", () => applyTheme(swatch.dataset.theme));
  });
}

