// ── Settings ──────────────────────────────────────────────────────────────────

async function amiLoadSettings() {
  try {
    const rows = await supabaseGet("program_settings?setting_key=in.(ami_utilityapi_key,ami_interval_length)");
    if (Array.isArray(rows)) {
      rows.forEach(r => {
        if (r.setting_key === 'ami_utilityapi_key') {
          const el = document.getElementById('ami-setting-uapi-key');
          if (el) el.value = r.setting_value || '';
        }
        if (r.setting_key === 'ami_interval_length') {
          const el = document.getElementById('ami-setting-interval');
          if (el) el.value = r.setting_value || '60';
        }
      });
    }
  } catch(e) { console.warn('amiLoadSettings:', e.message); }
  // Show webhook URL
  const wh = document.getElementById('ami-webhook-url');
  if (wh) wh.textContent = `${PROXY_URL}ami/ingest`;
}

async function amiSaveSettings() {
  const pairs = [
    ['ami_utilityapi_key',   document.getElementById('ami-setting-uapi-key')?.value?.trim()  || ''],
    ['ami_interval_length',  document.getElementById('ami-setting-interval')?.value           || '60'],
  ];
  for (const [key, val] of pairs) {
    await fetch(`${SUPABASE_URL}/rest/v1/program_settings?on_conflict=setting_key`, {
      method: 'POST',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates,return=minimal'
      },
      body: JSON.stringify({ setting_key: key, setting_value: val })
    });
  }
  const saved = document.getElementById('ami-settings-saved');
  if (saved) { saved.style.display = 'inline-block'; setTimeout(() => saved.style.display = 'none', 2500); }
}

// ── AMI Meters Tab ────────────────────────────────────────────────────────────

async function amiLoadMeters() {
  const tableEl  = document.getElementById('ami-meters-table');
  const countEl  = document.getElementById('ami-meters-count');
  if (!tableEl) return;
  tableEl.innerHTML = '<div class="sched-empty">Loading…</div>';

  try {
    const meters = await supabaseGet('ami_meters?order=created_at.desc');
    if (!Array.isArray(meters) || !meters.length) {
      tableEl.innerHTML = '<div class="sched-empty">No meters registered yet. Import data in the Ingest tab to add meters automatically.</div>';
      if (countEl) countEl.textContent = '';
      return;
    }

    if (countEl) countEl.textContent = `${meters.length} meter${meters.length !== 1 ? 's' : ''}`;

    // Also load reading counts per meter
    const counts = {};
    try {
      const readingCounts = await supabaseGet('ami_readings?select=meter_uid&order=meter_uid');
      if (Array.isArray(readingCounts)) {
        readingCounts.forEach(r => { counts[r.meter_uid] = (counts[r.meter_uid] || 0) + 1; });
      }
    } catch(e) {}

    const srcBadge = s => ({
      utilityapi:  '<span style="font-size:10px;padding:2px 6px;border-radius:8px;background:var(--blue-bg);color:var(--blue-dark);">UtilityAPI</span>',
      greenbutton: '<span style="font-size:10px;padding:2px 6px;border-radius:8px;background:var(--green-bg);color:var(--green-dark);">Green Button</span>',
      csv:         '<span style="font-size:10px;padding:2px 6px;border-radius:8px;background:var(--surface2);color:var(--text-hint);">CSV</span>'
    }[s] || `<span style="font-size:10px;padding:2px 6px;border-radius:8px;background:var(--surface2);">${s||'—'}</span>`);

    tableEl.innerHTML = `
      <div style="overflow-x:auto;">
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr>
          <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Meter UID</th>
          <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Utility</th>
          <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Source</th>
          <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Address</th>
          <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Tariff</th>
          <th style="text-align:center;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Intervals</th>
          <th style="text-align:center;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Interval (min)</th>
          <th style="text-align:left;padding:7px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Added</th>
        </tr></thead>
        <tbody>
          ${meters.map(m => `<tr>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);font-family:monospace;font-size:11px;">${m.meter_uid}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);">${m.utility_name || '—'}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);">${srcBadge(m.source_type)}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);font-size:11px;color:var(--text-hint);">${m.service_address || '—'}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);font-size:11px;color:var(--text-hint);">${m.tariff || '—'}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${counts[m.meter_uid] || 0}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${m.interval_length || '—'}</td>
            <td style="padding:7px 8px;border-bottom:0.5px solid var(--border);font-size:11px;color:var(--text-hint);">${m.created_at ? new Date(m.created_at).toLocaleDateString() : '—'}</td>
          </tr>`).join('')}
        </tbody>
      </table></div>`;

    // Populate correlation meter select
    await amiLoadCorrelations();
    const mSel = document.getElementById('ami-corr-meter');
    if (mSel) {
      mSel.innerHTML = '<option value="">— Select Meter —</option>' +
        meters.map(m => `<option value="${m.meter_uid}">${m.utility_name || m.source_type || ''} — ${m.meter_uid}</option>`).join('');
    }

  } catch(e) {
    if (tableEl) tableEl.innerHTML = `<div class="sched-empty" style="color:var(--red);">Error: ${e.message}</div>`;
    console.error('amiLoadMeters:', e);
  }
}

function amiShowCorrelationForm() {
  const form = document.getElementById('ami-corr-form');
  if (!form) return;
  form.style.display = form.style.display === 'none' ? '' : 'none';
  // Populate device select
  const dSel = document.getElementById('ami-corr-device');
  if (dSel) {
    dSel.innerHTML = '<option value="">— Select Device —</option>' +
      (DEVICES || []).map(d => `<option value="${d.uid}">${d.name || d.uid}</option>`).join('');
  }
}

async function amiSaveCorrelation() {
  const meterUid  = document.getElementById('ami-corr-meter')?.value;
  const deviceUid = document.getElementById('ami-corr-device')?.value;
  const corrType  = document.getElementById('ami-corr-type')?.value || 'one_to_one';
  const notes     = document.getElementById('ami-corr-notes')?.value?.trim() || null;
  const statusEl  = document.getElementById('ami-corr-status');

  if (!meterUid || !deviceUid) {
    if (statusEl) statusEl.textContent = '⚠ Select both a meter and a device.';
    return;
  }
  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/ami_meter_devices?on_conflict=meter_uid,device_uid`, {
      method: 'POST',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${currentSession?.access_token || SUPABASE_KEY}`,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates,return=minimal'
      },
      body: JSON.stringify({ meter_uid: meterUid, device_uid: deviceUid, corr_type: corrType, notes })
    });
    if (!res.ok) throw new Error(await res.text());
    if (statusEl) statusEl.textContent = '✅ Correlation saved';
    setTimeout(() => { if (statusEl) statusEl.textContent = ''; }, 2000);
    document.getElementById('ami-corr-form').style.display = 'none';
    await amiLoadCorrelations();
  } catch(e) {
    if (statusEl) statusEl.textContent = `❌ ${e.message}`;
  }
}

async function amiLoadCorrelations() {
  const tableEl = document.getElementById('ami-correlations-table');
  if (!tableEl) return;
  try {
    const rows = await supabaseGet('ami_meter_devices?order=created_at.desc');
    if (!Array.isArray(rows) || !rows.length) {
      tableEl.innerHTML = '<div class="sched-empty">No device correlations configured yet.</div>';
      return;
    }
    tableEl.innerHTML = `
      <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:4px;">
        <thead><tr>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Meter UID</th>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Device</th>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Type</th>
          <th style="text-align:left;padding:6px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);">Notes</th>
          <th style="padding:6px 8px;border-bottom:0.5px solid var(--border-md);"></th>
        </tr></thead>
        <tbody>
          ${rows.map(r => {
            const dev = (DEVICES||[]).find(d => d.uid === r.device_uid);
            return `<tr>
              <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);font-family:monospace;font-size:11px;">${r.meter_uid}</td>
              <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);">${dev?.name || r.device_uid}</td>
              <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);font-size:11px;color:var(--text-hint);">${r.corr_type?.replace('_',' ') || '—'}</td>
              <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);font-size:11px;color:var(--text-hint);">${r.notes || '—'}</td>
              <td style="padding:6px 8px;border-bottom:0.5px solid var(--border);text-align:right;">
                <button onclick="amiDeleteCorrelation(${r.id})" style="padding:3px 8px;border-radius:var(--radius-sm);border:0.5px solid var(--red);background:transparent;color:var(--red);font-size:10px;cursor:pointer;">Remove</button>
              </td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>`;
  } catch(e) { console.error('amiLoadCorrelations:', e); }
}

async function amiDeleteCorrelation(id) {
  if (!confirm('Remove this correlation?')) return;
  await supabaseDelete('ami_meter_devices', `id=eq.${id}`);
  await amiLoadCorrelations();
}

// ── AMI Interval Data Chart ───────────────────────────────────────────────────

let _amiIntervalChart = null;
let _amiChartData     = null;

async function amiInitIntervalTab() {
  // Set default date range (last 30 days)
  const to   = new Date();
  const from = new Date(to.getTime() - 30 * 86400000);
  const fmt  = d => d.toISOString().split('T')[0];
  const fromEl = document.getElementById('ami-chart-from');
  const toEl   = document.getElementById('ami-chart-to');
  if (fromEl && !fromEl.value) fromEl.value = fmt(from);
  if (toEl   && !toEl.value)   toEl.value   = fmt(to);

  // Populate meter select
  try {
    const meters = await supabaseGet('ami_meters?order=created_at.desc&enabled=eq.true');
    const sel = document.getElementById('ami-chart-meter');
    if (sel && Array.isArray(meters)) {
      sel.innerHTML = '<option value="">— Select Meter —</option>' +
        meters.map(m => `<option value="${m.meter_uid}">${m.utility_name||m.source_type||''} — ${m.meter_uid}</option>`).join('');
    }
  } catch(e) {}
}

function amiChartPopulateDevices() {
  const meterUid = document.getElementById('ami-chart-meter')?.value;
  const sel = document.getElementById('ami-chart-device');
  if (!sel) return;
  sel.innerHTML = '<option value="">— None —</option>' +
    (DEVICES||[]).map(d => `<option value="${d.uid}">${d.name || d.uid}</option>`).join('');
}

async function amiLoadIntervalChart() {
  const meterUid = document.getElementById('ami-chart-meter')?.value;
  const deviceUid = document.getElementById('ami-chart-device')?.value;
  const fromDate  = document.getElementById('ami-chart-from')?.value;
  const toDate    = document.getElementById('ami-chart-to')?.value;
  const statusEl  = document.getElementById('ami-chart-status');
  const emptyEl   = document.getElementById('ami-chart-empty');

  if (!meterUid) { if (statusEl) statusEl.textContent = '⚠ Select a meter first.'; return; }
  if (!fromDate || !toDate) { if (statusEl) statusEl.textContent = '⚠ Set a date range.'; return; }

  if (statusEl) statusEl.textContent = 'Loading…';
  if (emptyEl)  emptyEl.style.display = 'none';

  try {
    // Fetch AMI readings — use paged fetch to bypass Supabase 1000-row default cap
    const readings = await supabaseGetPaged(
      `ami_readings?meter_uid=eq.${encodeURIComponent(meterUid)}&interval_start=gte.${fromDate}T00:00:00Z&interval_start=lte.${toDate}T23:59:59Z&order=interval_start.asc`,
      10000
    );

    if (!Array.isArray(readings) || !readings.length) {
      if (statusEl) statusEl.textContent = '⚠ No interval data in this date range.';
      if (emptyEl)  emptyEl.style.display = '';
      emptyEl.textContent = 'No interval data found for selected meter and date range.';
      return;
    }

    // Fetch device relay readings if a device is selected
    let relayReadings = [];
    if (deviceUid) {
      relayReadings = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(deviceUid)}&recorded_at=gte.${fromDate}T00:00:00Z&recorded_at=lte.${toDate}T23:59:59Z&order=recorded_at.asc&limit=2000`
      ).catch(() => []);
    }

    _amiChartData = { readings, relayReadings, meterUid, deviceUid };

    // Downsample for chart rendering if too many points (keep every Nth point)
    const MAX_CHART_POINTS = 1500;
    const step = readings.length > MAX_CHART_POINTS ? Math.ceil(readings.length / MAX_CHART_POINTS) : 1;
    const chartReadings = step > 1 ? readings.filter((_,i) => i % step === 0) : readings;

    // Build chart datasets
    const labels  = chartReadings.map(r => new Date(r.interval_start).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}));
    const kwhData = chartReadings.map(r => r.kwh);
    const kwData  = chartReadings.map(r => r.kw);

    // Map relay state to interval timestamps
    const relayMap = {};
    relayReadings.forEach(r => {
      const key = new Date(r.recorded_at).toISOString().slice(0,16);
      relayMap[key] = (r.relay_status_r1 > 0 || r.relay_status_r2 > 0 || r.relay_active_r1 || r.relay_active_r2) ? 1 : 0;
    });
    const relayData = chartReadings.map(r => {
      const key = new Date(r.interval_start).toISOString().slice(0,16);
      return relayMap[key] ?? null;
    });

    // Destroy existing chart
    if (_amiIntervalChart) { _amiIntervalChart.destroy(); _amiIntervalChart = null; }

    const ctx = document.getElementById('ami-interval-chart')?.getContext('2d');
    if (!ctx) return;

    _amiIntervalChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [
          {
            label: 'kWh',
            data: kwhData,
            borderColor: 'var(--blue-dark)',
            backgroundColor: 'rgba(56,127,214,0.08)',
            borderWidth: 1.5,
            pointRadius: readings.length > 200 ? 0 : 2,
            fill: true,
            yAxisID: 'y',
            hidden: false
          },
          {
            label: 'kW',
            data: kwData,
            borderColor: 'var(--green-dark)',
            backgroundColor: 'transparent',
            borderWidth: 1.5,
            pointRadius: 0,
            fill: false,
            yAxisID: 'y',
            hidden: false
          },
          ...(deviceUid ? [{
            label: 'Relay Active',
            data: relayData,
            borderColor: 'var(--red)',
            backgroundColor: 'rgba(226,75,74,0.15)',
            borderWidth: 1,
            pointRadius: 0,
            fill: true,
            stepped: true,
            yAxisID: 'y2',
            hidden: false
          }] : [])
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: { position: 'top', labels: { font: { size: 11 } } },
          tooltip: { callbacks: {
            label: ctx => {
              if (ctx.dataset.label === 'Relay Active') return ctx.parsed.y === 1 ? 'Relay: ON' : ctx.parsed.y === 0 ? 'Relay: OFF' : '';
              return `${ctx.dataset.label}: ${ctx.parsed.y?.toFixed(3)}`;
            }
          }}
        },
        scales: {
          x: { ticks: { font: { size: 10 }, maxTicksLimit: 12 } },
          y: { title: { display: true, text: 'kWh / kW', font: { size: 11 } }, beginAtZero: true },
          ...(deviceUid ? { y2: { position: 'right', min: 0, max: 1.5, ticks: { display: false }, grid: { display: false } } } : {})
        }
      }
    });

    // Stats
    const totalKwh = readings.reduce((s,r) => s + (r.kwh||0), 0);
    const validKw  = readings.filter(r => r.kw != null).map(r => r.kw);
    const avgKw    = validKw.length ? validKw.reduce((s,v) => s+v,0) / validKw.length : 0;
    const peakKw   = validKw.length ? Math.max(...validKw) : 0;
    const totalCost = readings.reduce((s,r) => s + (r.cost||0), 0);

    document.getElementById('ami-stat-total-kwh').textContent = totalKwh.toFixed(1) + ' kWh';
    document.getElementById('ami-stat-avg-kw').textContent    = avgKw.toFixed(2) + ' kW';
    document.getElementById('ami-stat-peak-kw').textContent   = peakKw.toFixed(2) + ' kW';
    document.getElementById('ami-stat-intervals').textContent = readings.length;
    document.getElementById('ami-stat-cost').textContent      = totalCost > 0 ? '$' + totalCost.toFixed(2) : '—';
    document.getElementById('ami-chart-stats').style.display  = '';

    if (statusEl) statusEl.textContent = `${readings.length} intervals loaded`;

  } catch(e) {
    if (statusEl) statusEl.textContent = `Error: ${e.message}`;
    console.error('amiLoadIntervalChart:', e);
  }
}

function amiUpdateChartVisibility() {
  if (!_amiIntervalChart) return;
  const showKwh   = document.getElementById('ami-show-kwh')?.checked;
  const showKw    = document.getElementById('ami-show-kw')?.checked;
  const showRelay = document.getElementById('ami-show-relay')?.checked;
  _amiIntervalChart.data.datasets.forEach(ds => {
    if (ds.label === 'kWh')          ds.hidden = !showKwh;
    if (ds.label === 'kW')           ds.hidden = !showKw;
    if (ds.label === 'Relay Active') ds.hidden = !showRelay;
  });
  _amiIntervalChart.update();
}

// ── AMI M&V Reports ───────────────────────────────────────────────────────────

let _amiMVData = null;
let _amiMVChart = null;

async function amiInitMVTab() {
  // Populate event select
  try {
    const events = await supabaseGet('schedule_queue?order=fire_at.desc&limit=50&select=name,fire_at,duration_minutes');
    const sel = document.getElementById('ami-mv-event');
    if (sel && Array.isArray(events)) {
      const seen = new Set();
      sel.innerHTML = '<option value="">— Select Event —</option>' +
        events.filter(e => e.name && !seen.has(e.name) && seen.add(e.name))
          .map(e => `<option value="${JSON.stringify({name:e.name,fire_at:e.fire_at,duration_minutes:e.duration_minutes}).replace(/"/g,'&quot;')}">${e.name} (${new Date(e.fire_at).toLocaleDateString()})</option>`)
          .join('');
    }
  } catch(e) {}

  // Populate meter select
  try {
    const meters = await supabaseGet('ami_meters?order=created_at.desc');
    const sel = document.getElementById('ami-mv-meter');
    if (sel && Array.isArray(meters)) {
      sel.innerHTML = '<option value="">— Select Meter —</option>' +
        meters.map(m => `<option value="${m.meter_uid}">${m.utility_name||''} — ${m.meter_uid}</option>`).join('');
    }
  } catch(e) {}
}

async function amiRunMV() {
  const eventRaw   = document.getElementById('ami-mv-event')?.value;
  const meterUid   = document.getElementById('ami-mv-meter')?.value;
  const method     = document.getElementById('ami-mv-baseline-method')?.value || '10of10';
  const resultsEl  = document.getElementById('ami-mv-results');
  const emptyEl    = document.getElementById('ami-mv-empty');

  if (!eventRaw || !meterUid) { alert('Select an event and meter first.'); return; }

  let eventData;
  try { eventData = JSON.parse(eventRaw.replace(/&quot;/g,'"')); } catch(e) { alert('Invalid event data'); return; }

  const fireAt   = new Date(eventData.fire_at);
  const duration = eventData.duration_minutes || 60;
  const endAt    = new Date(fireAt.getTime() + duration * 60000);

  if (emptyEl) emptyEl.style.display = 'none';

  try {
    // 1. Fetch event interval readings
    const eventReadings = await supabaseGet(
      `ami_readings?meter_uid=eq.${encodeURIComponent(meterUid)}&interval_start=gte.${fireAt.toISOString()}&interval_start=lte.${endAt.toISOString()}&order=interval_start.asc`
    );

    // 2. Fetch baseline readings (30 days prior, same hours)
    const baselineFrom = new Date(fireAt.getTime() - 30 * 86400000).toISOString();
    const baselineAll  = await supabaseGetPaged(
      `ami_readings?meter_uid=eq.${encodeURIComponent(meterUid)}&interval_start=gte.${baselineFrom}&interval_start=lt.${fireAt.toISOString()}&order=interval_start.asc`,
      10000
    );

    // 3. Fetch device relay readings during event
    let relayReadings = [];
    const corrs = await supabaseGet(`ami_meter_devices?meter_uid=eq.${encodeURIComponent(meterUid)}&limit=1`).catch(()=>[]);
    if (Array.isArray(corrs) && corrs[0]?.device_uid) {
      relayReadings = await supabaseGet(
        `device_readings?device_uid=eq.${encodeURIComponent(corrs[0].device_uid)}&recorded_at=gte.${fireAt.toISOString()}&recorded_at=lte.${endAt.toISOString()}&order=recorded_at.asc`
      ).catch(()=>[]);
    }

    // 4. Calculate baseline per interval using same hour-of-day from prior days
    const baselineMap = {};
    if (Array.isArray(baselineAll)) {
      const byHour = {};
      baselineAll.forEach(r => {
        const h = new Date(r.interval_start).getHours();
        if (!byHour[h]) byHour[h] = [];
        if (r.kw != null) byHour[h].push(r.kw);
      });
      // Average per hour
      Object.entries(byHour).forEach(([h, vals]) => {
        const sorted = [...vals].sort((a,b) => a-b);
        const top = method === '10of10' ? sorted.slice(-10) : sorted.slice(-7);
        baselineMap[parseInt(h)] = top.length ? top.reduce((s,v)=>s+v,0)/top.length : null;
      });
    }

    // 5. Build per-interval comparison
    const relayMap = {};
    relayReadings.forEach(r => {
      const key = new Date(r.recorded_at).toISOString().slice(0,16);
      relayMap[key] = r.relay_status_r1 > 0 || r.relay_status_r2 > 0 || r.relay_active_r1 || r.relay_active_r2;
    });

    const intervals = (Array.isArray(eventReadings) ? eventReadings : []).map(r => {
      const h          = new Date(r.interval_start).getHours();
      const baselineKw = baselineMap[h] ?? null;
      const actualKw   = r.kw ?? (r.kwh != null ? r.kwh : null);
      const reductionKw = baselineKw != null && actualKw != null ? Math.max(0, baselineKw - actualKw) : null;
      const reductionPct = baselineKw != null && baselineKw > 0 && reductionKw != null ? (reductionKw / baselineKw * 100) : null;
      const relayKey   = new Date(r.interval_start).toISOString().slice(0,16);
      return { r, baselineKw, actualKw, reductionKw, reductionPct, relayOn: relayMap[relayKey] ?? null };
    });

    // 6. Aggregate stats
    const validBaselines = intervals.filter(i => i.baselineKw != null);
    const validActuals   = intervals.filter(i => i.actualKw != null);
    const validReductions = intervals.filter(i => i.reductionKw != null);

    const avgBaseline  = validBaselines.length ? validBaselines.reduce((s,i)=>s+i.baselineKw,0)/validBaselines.length : 0;
    const avgActual    = validActuals.length   ? validActuals.reduce((s,i)=>s+i.actualKw,0)/validActuals.length : 0;
    const avgReduction = validReductions.length ? validReductions.reduce((s,i)=>s+i.reductionKw,0)/validReductions.length : 0;
    const reductionPct = avgBaseline > 0 ? (avgReduction / avgBaseline * 100) : 0;
    const durHrs       = duration / 60;
    const energySaved  = avgReduction * durHrs;

    _amiMVData = { eventData, meterUid, intervals, avgBaseline, avgActual, avgReduction, reductionPct, energySaved, method };

    // 7. Update KPI cards
    document.getElementById('ami-mv-baseline-kw').textContent   = avgBaseline.toFixed(2) + ' kW';
    document.getElementById('ami-mv-actual-kw').textContent     = avgActual.toFixed(2) + ' kW';
    document.getElementById('ami-mv-reduction-kw').textContent  = avgReduction.toFixed(2) + ' kW';
    document.getElementById('ami-mv-reduction-pct').textContent = reductionPct.toFixed(1) + '% of baseline';
    document.getElementById('ami-mv-energy-saved').textContent  = energySaved.toFixed(3) + ' kWh';
    document.getElementById('ami-mv-event-info').textContent    = `${eventData.name} | ${fireAt.toLocaleString()} — ${endAt.toLocaleString()} | ${duration} min`;

    // 8. Render chart
    if (_amiMVChart) { _amiMVChart.destroy(); _amiMVChart = null; }
    const ctx = document.getElementById('ami-mv-chart')?.getContext('2d');
    if (ctx && intervals.length) {
      const labels = intervals.map(i => new Date(i.r.interval_start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}));
      _amiMVChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels,
          datasets: [
            { label: 'Baseline kW', data: intervals.map(i=>i.baselineKw), backgroundColor: 'rgba(56,127,214,0.3)', borderColor:'var(--blue-dark)', borderWidth:1 },
            { label: 'Actual kW',   data: intervals.map(i=>i.actualKw),   backgroundColor: 'rgba(15,110,86,0.5)',  borderColor:'var(--green-dark)', borderWidth:1 },
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { legend: { position:'top', labels:{ font:{size:11} } } },
          scales: {
            x: { ticks: { font:{size:10} } },
            y: { title: { display:true, text:'kW', font:{size:11} }, beginAtZero:true }
          }
        }
      });
    }

    // 9. Render table
    const tbody = document.getElementById('ami-mv-table-body');
    if (tbody) {
      tbody.innerHTML = intervals.map(i => `<tr>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);font-size:11px;">${new Date(i.r.interval_start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);text-align:right;">${i.baselineKw?.toFixed(3) ?? '—'}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);text-align:right;">${i.actualKw?.toFixed(3) ?? '—'}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);text-align:right;color:${(i.reductionKw||0)>0?'var(--green-dark)':'var(--text-hint)'};">${i.reductionKw?.toFixed(3) ?? '—'}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);text-align:right;color:${(i.reductionPct||0)>0?'var(--green-dark)':'var(--text-hint)'};">${i.reductionPct?.toFixed(1) ?? '—'}%</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);">${i.relayOn===true?'<span style="color:var(--green-dark);">● ON</span>':i.relayOn===false?'<span style="color:var(--text-hint);">○ OFF</span>':'—'}</td>
      </tr>`).join('');
    }

    if (resultsEl) resultsEl.style.display = '';

  } catch(e) {
    alert('M&V Error: ' + e.message);
    console.error('amiRunMV:', e);
  }
}

function amiExportMVReport() {
  const d = _amiMVData;
  if (!d) { alert('Run M&V first.'); return; }

  const { eventData, meterUid, intervals, avgBaseline, avgActual, avgReduction, reductionPct, energySaved, method } = d;
  const fireAt   = new Date(eventData.fire_at);
  const duration = eventData.duration_minutes || 60;
  const endAt    = new Date(fireAt.getTime() + duration * 60000);
  const reportDate = new Date().toLocaleString();

  const methodLabels = {
    '10of10': 'CAISO 10-of-10', '5of10': 'Mid 5-of-10',
    '7day': '7-Day Same-Hour Avg', '30day': '30-Day Same-Hour Avg'
  };
  const methodLabel = methodLabels[method] || method;

  const kpiCard = (value, label, unit, color, bg) =>
    `<div style="text-align:center;padding:20px 16px;border-radius:12px;background:${bg};border-left:4px solid ${color};">
      <div style="font-size:32px;font-weight:800;color:${color};line-height:1;">${value}</div>
      <div style="font-size:11px;color:#64748B;margin-top:4px;font-weight:600;">${unit}</div>
      <div style="font-size:11px;color:#94A3B8;margin-top:4px;text-transform:uppercase;letter-spacing:.05em;">${label}</div>
    </div>`;

  // Build sparkline-style bar chart SVG for baseline vs actual per interval
  const maxKw = Math.max(...intervals.map(i => Math.max(i.baselineKw||0, i.actualKw||0)), 1);
  const barW  = Math.max(4, Math.floor(560 / Math.max(intervals.length, 1) / 2));
  const gap   = Math.max(2, Math.floor(560 / Math.max(intervals.length, 1)) - barW * 2);
  const chartH = 120;

  const bars = intervals.map((iv, i) => {
    const x      = i * (barW * 2 + gap);
    const blH    = iv.baselineKw ? Math.round((iv.baselineKw / maxKw) * chartH) : 0;
    const acH    = iv.actualKw   ? Math.round((iv.actualKw   / maxKw) * chartH) : 0;
    return `<rect x="${x}" y="${chartH - blH}" width="${barW}" height="${blH}" fill="#3B82F6" opacity="0.7" rx="1"/>
            <rect x="${x+barW}" y="${chartH - acH}" width="${barW}" height="${acH}" fill="${acH < blH ? '#16A34A' : '#DC2626'}" opacity="0.85" rx="1"/>`;
  }).join('');

  const totalWidth = intervals.length * (barW * 2 + gap);
  const chartSVG = intervals.length ? `
    <svg width="100%" viewBox="0 0 ${totalWidth} ${chartH + 20}" preserveAspectRatio="none" style="display:block;border-radius:4px;">
      <rect width="${totalWidth}" height="${chartH + 20}" fill="#F8FAFC" rx="4"/>
      ${bars}
      <line x1="0" y1="${chartH}" x2="${totalWidth}" y2="${chartH}" stroke="#E2E8F0" stroke-width="1"/>
    </svg>` : '';

  const tableRows = intervals.map(i => {
    const reduction = i.reductionKw ?? 0;
    const pct       = i.reductionPct ?? 0;
    const rowBg     = reduction > 0 ? '#F0FDF4' : '#FFF';
    return `<tr style="background:${rowBg};">
      <td style="padding:9px 14px;border-bottom:1px solid #F1F5F9;font-weight:600;white-space:nowrap;">${new Date(i.r.interval_start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</td>
      <td style="padding:9px 14px;border-bottom:1px solid #F1F5F9;text-align:right;color:#3B82F6;font-weight:600;">${i.baselineKw?.toFixed(3)??'—'}</td>
      <td style="padding:9px 14px;border-bottom:1px solid #F1F5F9;text-align:right;font-weight:600;">${i.actualKw?.toFixed(3)??'—'}</td>
      <td style="padding:9px 14px;border-bottom:1px solid #F1F5F9;text-align:right;color:${reduction>0?'#16A34A':'#DC2626'};font-weight:700;">${reduction.toFixed(3)}</td>
      <td style="padding:9px 14px;border-bottom:1px solid #F1F5F9;text-align:right;">
        <span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;background:${pct>0?'#DCFCE7':'#FEE2E2'};color:${pct>0?'#166534':'#991B1B'};">${pct.toFixed(1)}%</span>
      </td>
      <td style="padding:9px 14px;border-bottom:1px solid #F1F5F9;text-align:center;">
        ${i.relayOn===true
          ? '<span style="display:inline-block;padding:2px 8px;border-radius:10px;background:#DCFCE7;color:#166534;font-size:11px;font-weight:700;">● ON</span>'
          : i.relayOn===false
            ? '<span style="display:inline-block;padding:2px 8px;border-radius:10px;background:#F1F5F9;color:#64748B;font-size:11px;">○ OFF</span>'
            : '<span style="color:#94A3B8;">—</span>'}
      </td>
    </tr>`;
  }).join('');

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>M&V Report — ${eventData.name}</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #F8FAFC; color: #0F172A; font-size: 14px; }
  @media print { body { background: #fff; } .no-print { display: none; } }
</style>
</head>
<body>
<div style="max-width:920px;margin:0 auto;padding:32px 24px;">

  <!-- Header -->
  <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:32px;padding-bottom:24px;border-bottom:2px solid #E2E8F0;">
    <div>
      <div style="font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.1em;margin-bottom:6px;">AMI Measurement & Verification</div>
      <div style="font-size:28px;font-weight:800;color:#0F172A;line-height:1.2;">Demand Reduction Report</div>
      <div style="font-size:15px;color:#64748B;margin-top:6px;">${eventData.name}</div>
    </div>
    <div style="text-align:right;">
      <div style="font-size:11px;color:#94A3B8;">Generated</div>
      <div style="font-size:13px;font-weight:600;color:#475569;">${reportDate}</div>
      <button class="no-print" onclick="window.print()" style="margin-top:10px;padding:8px 16px;border-radius:6px;border:none;background:#0F172A;color:#fff;font-size:12px;font-weight:600;cursor:pointer;">🖨 Print / Save PDF</button>
    </div>
  </div>

  <!-- Event + Meter Info -->
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px;">
    <div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;">
      <div style="font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.08em;margin-bottom:14px;">Event Details</div>
      <div style="display:flex;flex-direction:column;gap:8px;">
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">Event</span><span style="font-weight:700;font-size:13px;">${eventData.name}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">Start</span><span style="font-weight:600;font-size:13px;">${fireAt.toLocaleString([],{dateStyle:"medium",timeStyle:"short"})}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">End</span><span style="font-weight:600;font-size:13px;">${endAt.toLocaleString([],{dateStyle:"medium",timeStyle:"short"})}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">Duration</span><span style="font-weight:600;font-size:13px;">${duration} minutes</span></div>
      </div>
    </div>
    <div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;">
      <div style="font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.08em;margin-bottom:14px;">M&V Parameters</div>
      <div style="display:flex;flex-direction:column;gap:8px;">
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">Meter</span><span style="font-weight:700;font-size:12px;font-family:monospace;">${meterUid}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">Baseline Method</span><span style="font-weight:600;font-size:13px;">${methodLabel}</span></div>
        <div style="display:flex;justify-content:space-between;"><span style="color:#94A3B8;font-size:12px;">Intervals Analyzed</span><span style="font-weight:600;font-size:13px;">${intervals.length}</span></div>
      </div>
    </div>
  </div>

  <!-- KPI Cards -->
  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:24px;">
    ${kpiCard(avgBaseline.toFixed(2), 'Baseline Demand', 'kW avg', '#3B82F6', '#EFF6FF')}
    ${kpiCard(avgActual.toFixed(2),   'Actual Demand',   'kW avg', '#64748B', '#F8FAFC')}
    ${kpiCard(avgReduction.toFixed(2),'Demand Reduction','kW avg', '#16A34A', '#F0FDF4')}
    ${kpiCard(reductionPct.toFixed(1)+'%','Reduction Rate','of baseline','#7C3AED','#F5F3FF')}
  </div>

  <!-- Energy Saved Banner -->
  <div style="background:linear-gradient(135deg,#0F172A 0%,#1E3A5F 100%);border-radius:12px;padding:24px 28px;margin-bottom:24px;display:flex;align-items:center;justify-content:space-between;">
    <div>
      <div style="font-size:12px;font-weight:700;color:#94A3B8;text-transform:uppercase;letter-spacing:.1em;margin-bottom:6px;">Estimated Energy Savings</div>
      <div style="font-size:36px;font-weight:800;color:#fff;line-height:1;">${energySaved.toFixed(3)} <span style="font-size:20px;font-weight:400;color:#94A3B8;">kWh</span></div>
    </div>
    <div style="text-align:right;">
      <div style="font-size:12px;color:#94A3B8;margin-bottom:4px;">Over ${duration}-minute event</div>
      <div style="font-size:13px;color:#64748B;">${avgReduction.toFixed(2)} kW avg reduction × ${(duration/60).toFixed(2)} hrs</div>
    </div>
  </div>

  <!-- Narrative -->
  <div style="background:#EFF6FF;border-radius:12px;padding:20px 24px;margin-bottom:24px;border-left:4px solid #3B82F6;">
    <div style="font-size:12px;font-weight:700;color:#1D4ED8;text-transform:uppercase;letter-spacing:.08em;margin-bottom:10px;">Analysis Summary</div>
    <p style="color:#1E3A5F;line-height:1.8;font-size:13px;">
      This M&V analysis used the <strong>${methodLabel}</strong> baseline methodology to estimate the Customer Baseline Load (CBL) for meter <strong style="font-family:monospace;">${meterUid}</strong> during the event window of <strong>${fireAt.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} – ${endAt.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</strong>.
      The baseline average demand was <strong style="color:#3B82F6;">${avgBaseline.toFixed(3)} kW</strong>, while the actual measured demand during the event was <strong>${avgActual.toFixed(3)} kW</strong>.
      This represents a verified demand reduction of <strong style="color:#16A34A;">${avgReduction.toFixed(3)} kW (${reductionPct.toFixed(1)}%)</strong> against the established baseline,
      resulting in estimated energy savings of <strong style="color:#7C3AED;">${energySaved.toFixed(3)} kWh</strong> over the ${duration}-minute event duration.
    </p>
  </div>

  <!-- Bar Chart -->
  ${chartSVG ? `<div style="background:#fff;border-radius:12px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;margin-bottom:24px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">
      <div style="font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.08em;">Baseline vs Actual — Per Interval</div>
      <div style="display:flex;gap:16px;font-size:11px;">
        <span><span style="display:inline-block;width:10px;height:10px;background:#3B82F6;border-radius:2px;margin-right:4px;"></span>Baseline</span>
        <span><span style="display:inline-block;width:10px;height:10px;background:#16A34A;border-radius:2px;margin-right:4px;"></span>Actual (below baseline)</span>
      </div>
    </div>
    ${chartSVG}
  </div>` : ''}

  <!-- Detail Table -->
  <div style="background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.08);border:1px solid #E2E8F0;margin-bottom:24px;">
    <div style="padding:16px 20px;border-bottom:1px solid #F1F5F9;font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.08em;">Interval Detail</div>
    <div style="overflow-x:auto;">
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead>
        <tr style="background:#F8FAFC;">
          <th style="text-align:left;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;border-bottom:1px solid #E2E8F0;">Time</th>
          <th style="text-align:right;padding:10px 14px;font-size:11px;font-weight:700;color:#3B82F6;text-transform:uppercase;border-bottom:1px solid #E2E8F0;">Baseline kW</th>
          <th style="text-align:right;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;border-bottom:1px solid #E2E8F0;">Actual kW</th>
          <th style="text-align:right;padding:10px 14px;font-size:11px;font-weight:700;color:#16A34A;text-transform:uppercase;border-bottom:1px solid #E2E8F0;">Reduction kW</th>
          <th style="text-align:right;padding:10px 14px;font-size:11px;font-weight:700;color:#7C3AED;text-transform:uppercase;border-bottom:1px solid #E2E8F0;">Reduction %</th>
          <th style="text-align:center;padding:10px 14px;font-size:11px;font-weight:700;color:#64748B;text-transform:uppercase;border-bottom:1px solid #E2E8F0;">Relay</th>
        </tr>
      </thead>
      <tbody>${tableRows}</tbody>
    </table>
    </div>
  </div>

  <!-- Footer -->
  <div style="text-align:center;padding-top:24px;border-top:1px solid #E2E8F0;color:#94A3B8;font-size:11px;">
    Load Control Dashboard &nbsp;·&nbsp; M&V Report &nbsp;·&nbsp; ${eventData.name} &nbsp;·&nbsp; ${reportDate}
  </div>

</div>
</body>
</html>`;

  const blob = new Blob([html], { type: 'text/html' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `MV_Report_${eventData.name.replace(/\s+/g,'_')}_${fireAt.toISOString().split('T')[0]}.html`;
  a.click();
  URL.revokeObjectURL(a.href);
}

// ── AMI Baseline Calculator (Enhanced) ────────────────────────────────────────

let _amiBaselineChart  = null;
let _amiBaselineData   = null;
let _blCustomBaselines = [];   // { id, name, config }
let _blResults         = {};   // { methodKey: [{time, kw}] }
let _blActual          = [];   // [{time, kw}]

// ── Standard method definitions ──────────────────────────────────────────────

const BL_STANDARD_METHODS = [
  { key:'caiso_10of10',  label:'CAISO 10-of-10',     iso:'CAISO',   color:'#3B82F6', desc:'Avg of 10 highest-energy non-event weekdays, ±20% LPA adjustment' },
  { key:'pjm_4of5',      label:'PJM High 4-of-5',    iso:'PJM',     color:'#10B981', desc:'Highest 4 of last 5 similar weekdays by daily energy' },
  { key:'nyiso_10of10',  label:'NYISO 10-of-10',      iso:'NYISO',   color:'#F59E0B', desc:'10 highest-energy days from last 10 non-event days, weekdays only' },
  { key:'bl_5of10',      label:'Mid 5-of-10',         iso:'Generic', color:'#8B5CF6', desc:'Middle 5 of 10 days (excludes highest 3 and lowest 2)' },
  { key:'bl_3of10',      label:'High 3-of-10',        iso:'Generic', color:'#EC4899', desc:'Average of 3 highest-energy days from last 10 similar days' },
  { key:'isone_ema',     label:'ISO-NE EMA',          iso:'ISO-NE',  color:'#EF4444', desc:'Exponential moving avg: 90% prior CBL + 10% current day' },
  { key:'bl_7day',       label:'7-Day Same-Hour Avg', iso:'Generic', color:'#14B8A6', desc:'Simple average of same hour across last 7 days' },
  { key:'bl_30day',      label:'30-Day Same-Hour Avg',iso:'Generic', color:'#F97316', desc:'Simple average of same hour across lookback window' },
  { key:'aemo_4of5',     label:'AEMO 4-of-5',         iso:'AEMO',    color:'#6366F1', desc:'4 highest-consumption days of last 5 weekdays (Australia)' },
  { key:'krec_max4of5',  label:'KREC Max 4-of-5',     iso:'KREC',    color:'#0EA5E9', desc:'Highest 4 of prior 5 weekdays (Korea Electric Power)' },
];

// US Federal Holidays (approximate — year-agnostic matching by month/day)
const US_HOLIDAYS = [
  [1,1],[1,15],[2,19],[5,27],[6,19],[7,4],[9,2],[10,14],[11,11],[11,28],[12,25]
];

function isHoliday(date) {
  return US_HOLIDAYS.some(([m,d]) => date.getMonth()+1 === m && date.getDate() === d);
}
function isWeekend(date) { return date.getDay() === 0 || date.getDay() === 6; }

// ── Init ──────────────────────────────────────────────────────────────────────

async function amiInitBaselineTab() {
  // Populate meter select
  try {
    const meters = await supabaseGet('ami_meters?order=created_at.desc&enabled=eq.true');
    const sel = document.getElementById('bl-meter');
    if (sel && Array.isArray(meters)) {
      sel.innerHTML = '<option value="">— Select Meter —</option>' +
        meters.map(m => `<option value="${m.meter_uid}">${m.utility_name||m.source_type||''} — ${m.meter_uid}</option>`).join('');
    }
  } catch(e) {}

  // Populate DR event dropdown from schedule_queue
  try {
    const events = await supabaseGet('schedule_queue?order=fire_at.desc&limit=50&select=name,fire_at,duration_minutes');
    const sel = document.getElementById('bl-dr-event');
    if (sel && Array.isArray(events)) {
      const seen = new Set();
      sel.innerHTML = '<option value="">— Select Event or enter manually —</option>' +
        events.filter(e => e.name && !seen.has(e.name) && seen.add(e.name))
          .map(e => `<option value="${JSON.stringify({fire_at:e.fire_at,duration_minutes:e.duration_minutes}).replace(/"/g,'&quot;')}">${e.name} (${new Date(e.fire_at).toLocaleDateString()})</option>`)
          .join('');
    }
  } catch(e) {}

  // Default event window — use most recent AMI data range rather than yesterday
  try {
    const latest = await supabaseGet('ami_readings?order=interval_start.desc&limit=1&select=interval_start');
    const earliest = await supabaseGet('ami_readings?order=interval_start.asc&limit=1&select=interval_start');
    if (latest?.[0]?.interval_start) {
      const latestDt  = new Date(latest[0].interval_start);
      const defEnd    = new Date(latestDt);
      const defStart  = new Date(latestDt.getTime() - 3 * 3600000); // 3 hours before latest
      const fmt = d => d.toISOString().slice(0,16);
      const startEl = document.getElementById('bl-event-start');
      const endEl   = document.getElementById('bl-event-end');
      if (startEl && !startEl.value) startEl.value = fmt(defStart);
      if (endEl   && !endEl.value)   endEl.value   = fmt(defEnd);
    }
  } catch(e) {
    // Fallback to yesterday
    const now = new Date();
    const yesterday = new Date(now); yesterday.setDate(yesterday.getDate()-1);
    const fmt = d => d.toISOString().slice(0,16);
    const defStart = new Date(yesterday); defStart.setHours(14,0,0,0);
    const defEnd   = new Date(yesterday); defEnd.setHours(17,0,0,0);
    const startEl = document.getElementById('bl-event-start');
    const endEl   = document.getElementById('bl-event-end');
    if (startEl && !startEl.value) startEl.value = fmt(defStart);
    if (endEl   && !endEl.value)   endEl.value   = fmt(defEnd);
  }

  // Render standard method checkboxes
  blRenderStandardMethods();
  blLoadSavedBaselines();
}

function blApplyDREvent(val) {
  if (!val) return;
  try {
    const ev = JSON.parse(val.replace(/&quot;/g,'"'));
    const fireAt   = new Date(ev.fire_at);
    const duration = ev.duration_minutes || 60;
    const endAt    = new Date(fireAt.getTime() + duration * 60000);
    const fmt = d => d.toISOString().slice(0,16);
    const startEl = document.getElementById('bl-event-start');
    const endEl   = document.getElementById('bl-event-end');
    if (startEl) startEl.value = fmt(fireAt);
    if (endEl)   endEl.value   = fmt(endAt);
  } catch(e) { console.warn('blApplyDREvent:', e.message); }
}

function blRenderStandardMethods() {
  const el = document.getElementById('bl-standard-methods');
  if (!el) return;
  el.innerHTML = BL_STANDARD_METHODS.map(m => `
    <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:4px 0;">
      <input type="checkbox" id="bl-std-${m.key}" checked style="accent-color:${m.color};">
      <span style="width:10px;height:10px;border-radius:50%;background:${m.color};display:inline-block;flex-shrink:0;"></span>
      <span style="font-size:11px;flex:1;">${m.label}</span>
      <span style="font-size:9px;padding:1px 5px;border-radius:6px;background:var(--surface2);color:var(--text-hint);">${m.iso}</span>
    </label>`).join('');
}

function blToggleAllStandard() {
  const checkboxes = BL_STANDARD_METHODS.map(m => document.getElementById(`bl-std-${m.key}`)).filter(Boolean);
  const allChecked = checkboxes.every(cb => cb.checked);
  checkboxes.forEach(cb => cb.checked = !allChecked);
}

// ── Custom Baseline Builder ───────────────────────────────────────────────────

function blAddCustomBaseline() {
  const id = `custom_${Date.now()}`;
  const colors = ['#A855F7','#06B6D4','#D97706','#DC2626','#059669','#7C3AED'];
  const color  = colors[_blCustomBaselines.length % colors.length];

  _blCustomBaselines.push({
    id, color,
    name:          `Custom ${_blCustomBaselines.length+1}`,
    method:        'high_x_of_y',
    x:             5,
    y:             10,
    lookback:      30,
    excludeWeekends:  true,
    excludeHolidays:  true,
    trimHigh:      0,
    trimLow:       0,
    dayTypes:      'weekday',
    lpa:           false,
    lpaHours:      2
  });
  blRenderCustomList();
}

function blRenderCustomList() {
  const el = document.getElementById('bl-custom-list');
  if (!el) return;
  if (!_blCustomBaselines.length) {
    el.innerHTML = '<div style="font-size:11px;color:var(--text-hint);">Click + Add to build a custom baseline method.</div>';
    return;
  }
  el.innerHTML = _blCustomBaselines.map(bl => `
    <div style="border:0.5px solid var(--border-md);border-radius:var(--radius-sm);padding:10px;background:var(--surface);">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;">
        <span style="width:10px;height:10px;border-radius:50%;background:${bl.color};display:inline-block;flex-shrink:0;"></span>
        <input type="text" value="${bl.name}" onchange="blUpdateCustom('${bl.id}','name',this.value)"
          style="flex:1;padding:4px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:12px;font-weight:600;">
        <button onclick="blRemoveCustom('${bl.id}')" style="padding:3px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--red);background:transparent;color:var(--red);font-size:10px;cursor:pointer;">✕</button>
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:11px;">
        <div>
          <label style="color:var(--text-hint);display:block;margin-bottom:2px;">Method</label>
          <select onchange="blUpdateCustom('${bl.id}','method',this.value)"
            style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
            <option value="high_x_of_y" ${bl.method==='high_x_of_y'?'selected':''}>High X-of-Y</option>
            <option value="mid_x_of_y"  ${bl.method==='mid_x_of_y'?'selected':''}>Mid X-of-Y</option>
            <option value="low_x_of_y"  ${bl.method==='low_x_of_y'?'selected':''}>Low X-of-Y</option>
            <option value="avg_all"      ${bl.method==='avg_all'?'selected':''}>Average All Days</option>
            <option value="ema"          ${bl.method==='ema'?'selected':''}>Exponential Moving Avg</option>
          </select>
        </div>
        <div style="display:flex;gap:4px;">
          <div style="flex:1;">
            <label style="color:var(--text-hint);display:block;margin-bottom:2px;">X (select)</label>
            <input type="number" min="1" max="30" value="${bl.x}" onchange="blUpdateCustom('${bl.id}','x',+this.value)"
              style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
          </div>
          <div style="flex:1;">
            <label style="color:var(--text-hint);display:block;margin-bottom:2px;">Y (pool)</label>
            <input type="number" min="1" max="60" value="${bl.y}" onchange="blUpdateCustom('${bl.id}','y',+this.value)"
              style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
          </div>
        </div>

        <div>
          <label style="color:var(--text-hint);display:block;margin-bottom:2px;">Trim High Days</label>
          <input type="number" min="0" max="5" value="${bl.trimHigh}" onchange="blUpdateCustom('${bl.id}','trimHigh',+this.value)"
            style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;"
            title="Remove this many highest-kWh days from pool before averaging">
        </div>
        <div>
          <label style="color:var(--text-hint);display:block;margin-bottom:2px;">Trim Low Days</label>
          <input type="number" min="0" max="5" value="${bl.trimLow}" onchange="blUpdateCustom('${bl.id}','trimLow',+this.value)"
            style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;"
            title="Remove this many lowest-kWh days from pool before averaging">
        </div>

        <div>
          <label style="color:var(--text-hint);display:block;margin-bottom:2px;">Day Types</label>
          <select onchange="blUpdateCustom('${bl.id}','dayTypes',this.value)"
            style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
            <option value="weekday"  ${bl.dayTypes==='weekday'?'selected':''}>Weekdays only</option>
            <option value="weekend"  ${bl.dayTypes==='weekend'?'selected':''}>Weekends only</option>
            <option value="all"      ${bl.dayTypes==='all'?'selected':''}>All days</option>
            <option value="match"    ${bl.dayTypes==='match'?'selected':''}>Match event day type</option>
          </select>
        </div>
        <div>
          <label style="color:var(--text-hint);display:block;margin-bottom:2px;">Lookback</label>
          <select onchange="blUpdateCustom('${bl.id}','lookback',+this.value)"
            style="width:100%;padding:5px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
            <option value="30"  ${bl.lookback===30?'selected':''}>30 days</option>
            <option value="45"  ${bl.lookback===45?'selected':''}>45 days</option>
            <option value="60"  ${bl.lookback===60?'selected':''}>60 days</option>
            <option value="90"  ${bl.lookback===90?'selected':''}>90 days</option>
          </select>
        </div>
      </div>

      <div style="display:flex;gap:12px;margin-top:8px;flex-wrap:wrap;">
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" ${bl.excludeWeekends?'checked':''} onchange="blUpdateCustom('${bl.id}','excludeWeekends',this.checked)">
          Exclude weekends
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" ${bl.excludeHolidays?'checked':''} onchange="blUpdateCustom('${bl.id}','excludeHolidays',this.checked)">
          Exclude holidays
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" ${bl.lpa?'checked':''} onchange="blUpdateCustom('${bl.id}','lpa',this.checked)">
          LPA adjustment
        </label>
      </div>
      ${bl.lpa ? `<div style="margin-top:6px;font-size:11px;display:flex;align-items:center;gap:6px;">
        <label style="color:var(--text-hint);">LPA pre-event hours:</label>
        <input type="number" min="1" max="4" value="${bl.lpaHours}" onchange="blUpdateCustom('${bl.id}','lpaHours',+this.value)"
          style="width:50px;padding:3px 6px;border-radius:var(--radius-sm);border:0.5px solid var(--border-md);background:var(--surface2);font-size:11px;">
      </div>` : ''}
      <div style="display:flex;gap:6px;margin-top:8px;">
        <button onclick="blSaveCustomBaseline('${bl.id}')"
          style="flex:1;padding:4px;border-radius:var(--radius-sm);border:0.5px solid var(--green);background:var(--green-bg);color:var(--green-dark);font-size:10px;font-weight:600;cursor:pointer;">
          💾 Save
        </button>
      </div>
    </div>`).join('');
}

function blUpdateCustom(id, field, value) {
  const bl = _blCustomBaselines.find(b => b.id === id);
  if (bl) { bl[field] = value; blRenderCustomList(); }
}

function blRemoveCustom(id) {
  _blCustomBaselines = _blCustomBaselines.filter(b => b.id !== id);
  blRenderCustomList();
}

// ── Save / Load named baselines ───────────────────────────────────────────────

function blSaveCustomBaseline(id) {
  const bl = _blCustomBaselines.find(b => b.id === id);
  if (!bl) return;
  const saved = JSON.parse(localStorage.getItem('ami_saved_baselines') || '[]');
  const existing = saved.findIndex(s => s.name === bl.name);
  if (existing >= 0) saved[existing] = bl; else saved.push(bl);
  localStorage.setItem('ami_saved_baselines', JSON.stringify(saved));
  setStatus('success', `Baseline "${bl.name}" saved`);
  blLoadSavedBaselines();
}

function blSaveCurrentAsBaseline() {
  const name = prompt('Name for this baseline configuration:', `Baseline ${new Date().toLocaleDateString()}`);
  if (!name) return;
  const saved = JSON.parse(localStorage.getItem('ami_saved_baselines') || '[]');
  const config = {
    id: `saved_${Date.now()}`, name, color: '#6B7280',
    activeStandard: BL_STANDARD_METHODS.filter(m => document.getElementById(`bl-std-${m.key}`)?.checked).map(m=>m.key),
    customBaselines: _blCustomBaselines,
    savedAt: new Date().toISOString()
  };
  saved.push(config);
  localStorage.setItem('ami_saved_baselines', JSON.stringify(saved));
  setStatus('success', `"${name}" saved`);
  blLoadSavedBaselines();
}

function blLoadSavedBaselines() {
  const el = document.getElementById('bl-saved-list');
  if (!el) return;
  const saved = JSON.parse(localStorage.getItem('ami_saved_baselines') || '[]');
  if (!saved.length) { el.innerHTML = '<div style="font-size:11px;color:var(--text-hint);">No saved baselines yet.</div>'; return; }
  el.innerHTML = saved.map(s => `
    <div style="display:flex;align-items:center;gap:6px;padding:5px 0;border-bottom:0.5px solid var(--border);">
      <span style="font-size:11px;flex:1;color:var(--text-primary);">${s.name}</span>
      <span style="font-size:10px;color:var(--text-hint);">${s.savedAt ? new Date(s.savedAt).toLocaleDateString() : ''}</span>
      <button onclick="blApplySaved(${JSON.stringify(s).replace(/"/g,'&quot;')})" style="padding:2px 7px;border-radius:var(--radius-sm);border:0.5px solid var(--blue-dark);background:var(--blue-bg);color:var(--blue-dark);font-size:10px;cursor:pointer;">Load</button>
      <button onclick="blDeleteSaved('${s.name}')" style="padding:2px 6px;border-radius:var(--radius-sm);border:0.5px solid var(--red);background:transparent;color:var(--red);font-size:10px;cursor:pointer;">✕</button>
    </div>`).join('');
}

function blApplySaved(config) {
  if (config.customBaselines) _blCustomBaselines = config.customBaselines;
  if (config.activeStandard) {
    BL_STANDARD_METHODS.forEach(m => {
      const cb = document.getElementById(`bl-std-${m.key}`);
      if (cb) cb.checked = config.activeStandard.includes(m.key);
    });
  }
  blRenderCustomList();
  setStatus('success', `Loaded "${config.name}"`);
}

function blDeleteSaved(name) {
  if (!confirm(`Delete saved baseline "${name}"?`)) return;
  const saved = JSON.parse(localStorage.getItem('ami_saved_baselines') || '[]').filter(s => s.name !== name);
  localStorage.setItem('ami_saved_baselines', JSON.stringify(saved));
  blLoadSavedBaselines();
}

// ── Core Calculation Engine ───────────────────────────────────────────────────

async function amiRunBaseline() {
  const meterUid  = document.getElementById('bl-meter')?.value;
  const startStr  = document.getElementById('bl-event-start')?.value;
  const endStr    = document.getElementById('bl-event-end')?.value;
  const lookback  = parseInt(document.getElementById('bl-lookback')?.value || '30');
  const statusEl  = document.getElementById('bl-status');
  const emptyEl   = document.getElementById('bl-chart-empty');

  if (!meterUid) { if (statusEl) statusEl.textContent = '⚠ Select a meter first.'; return; }
  if (!startStr || !endStr) { if (statusEl) statusEl.textContent = '⚠ Set event window.'; return; }

  const eventStart = new Date(startStr);
  const eventEnd   = new Date(endStr);
  if (eventEnd <= eventStart) { if (statusEl) statusEl.textContent = '⚠ End must be after start.'; return; }

  if (statusEl) statusEl.textContent = 'Loading interval data…';
  if (emptyEl)  emptyEl.style.display = 'none';

  try {
    // Fetch actual event-window readings
    const eventReadings = await supabaseGetPaged(
      `ami_readings?meter_uid=eq.${encodeURIComponent(meterUid)}&interval_start=gte.${eventStart.toISOString()}&interval_start=lt.${eventEnd.toISOString()}&order=interval_start.asc`,
      2000
    );

    if (!Array.isArray(eventReadings) || !eventReadings.length) {
      if (statusEl) statusEl.textContent = '⚠ No readings in event window.';
      if (emptyEl)  { emptyEl.style.display=''; emptyEl.textContent='No data found in selected event window.'; }
      return;
    }

    // Fetch maximum lookback (90 days) all at once
    const maxLookback = Math.max(lookback, ...(_blCustomBaselines.map(b=>b.lookback||30)), 90);
    const lookbackFrom = new Date(eventStart.getTime() - maxLookback * 86400000);
    if (statusEl) statusEl.textContent = `Fetching ${maxLookback} days of history…`;

    const histReadings = await supabaseGetPaged(
      `ami_readings?meter_uid=eq.${encodeURIComponent(meterUid)}&interval_start=gte.${lookbackFrom.toISOString()}&interval_start=lt.${eventStart.toISOString()}&order=interval_start.asc`,
      20000
    );

    if (statusEl) statusEl.textContent = `Computing baselines from ${histReadings.length} historical readings…`;

    // Build lookup: date string → { timeKey → kw }
    // Also build daily energy map for X-of-Y day selection
    const dailyEnergy = {};   // 'YYYY-MM-DD' → total kWh
    const byTimeKey   = {};   // 'HH:MM' → [{date, kw, dayStr}]

    histReadings.forEach(r => {
      const d      = new Date(r.interval_start);
      const dayStr = d.toISOString().slice(0,10);
      const tKey   = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
      if (!dailyEnergy[dayStr]) dailyEnergy[dayStr] = 0;
      dailyEnergy[dayStr] += r.kwh || 0;
      if (!byTimeKey[tKey]) byTimeKey[tKey] = [];
      if (r.kw != null) byTimeKey[tKey].push({ date: d, dayStr, kw: r.kw });
    });

    const isEventWeekend = isWeekend(eventStart);

    // Helper: filter days by type and exclusion rules
    function filterDays(entries, cfg) {
      return entries.filter(e => {
        if (cfg.excludeWeekends && isWeekend(e.date)) return false;
        if (cfg.excludeHolidays && isHoliday(e.date)) return false;
        if (cfg.dayTypes === 'weekday'  && isWeekend(e.date)) return false;
        if (cfg.dayTypes === 'weekend'  && !isWeekend(e.date)) return false;
        if (cfg.dayTypes === 'match') {
          if (isEventWeekend !== isWeekend(e.date)) return false;
        }
        // Lookback filter
        const lb = cfg.lookback || lookback;
        const cutoff = new Date(eventStart.getTime() - lb * 86400000);
        if (e.date < cutoff) return false;
        return true;
      });
    }

    // Helper: select X-of-Y days by energy ranking
    function selectDays(filteredEntries, method, x, y, trimHigh, trimLow) {
      // Get unique day strings sorted by energy
      const uniqueDays = [...new Set(filteredEntries.map(e => e.dayStr))];
      let ranked = uniqueDays
        .map(d => ({ dayStr: d, energy: dailyEnergy[d] || 0 }))
        .sort((a,b) => b.energy - a.energy);

      // Apply trim
      if (trimHigh > 0) ranked = ranked.slice(trimHigh);
      if (trimLow  > 0) ranked = ranked.slice(0, ranked.length - trimLow);

      // Take pool of Y days
      const pool = ranked.slice(0, y).map(r => r.dayStr);

      // Select X from pool based on method
      let selected;
      if (method === 'high_x_of_y' || method === undefined) {
        selected = pool.slice(0, x);
      } else if (method === 'low_x_of_y') {
        selected = pool.slice(-x);
      } else if (method === 'mid_x_of_y') {
        const start = Math.floor((pool.length - x) / 2);
        selected = pool.slice(start, start + x);
      } else {
        selected = pool.slice(0, x);
      }

      return new Set(selected);
    }

    // Compute LPA adjustment factor for a config
    function computeLPA(cfg, timeKey) {
      if (!cfg.lpa) return 1.0;
      const lpaHours = cfg.lpaHours || 2;
      const preEventEnd   = new Date(eventStart);
      const preEventStart = new Date(eventStart.getTime() - lpaHours * 3600000);
      // Get actual pre-event kW
      const actualPre = histReadings.filter(r => {
        const d = new Date(r.interval_start);
        return d >= preEventStart && d < preEventEnd;
      }).map(r => r.kw).filter(v => v != null);
      const actualPreAvg = actualPre.length ? actualPre.reduce((s,v)=>s+v,0)/actualPre.length : null;
      if (!actualPreAvg) return 1.0;
      // Get baseline pre-event kW using same timeKey logic
      const preKeys = [];
      let cur = new Date(preEventStart);
      while (cur < preEventEnd) {
        preKeys.push(`${String(cur.getHours()).padStart(2,'0')}:${String(cur.getMinutes()).padStart(2,'0')}`);
        cur = new Date(cur.getTime() + 15*60000);
      }
      // ... simplified: use overall average of pre-event intervals in history
      const histPreAvg = preKeys.flatMap(k => (byTimeKey[k]||[]).map(e=>e.kw))
        .filter(v=>v!=null);
      const histAvg = histPreAvg.length ? histPreAvg.reduce((s,v)=>s+v,0)/histPreAvg.length : null;
      if (!histAvg || histAvg === 0) return 1.0;
      // Cap at ±20% per CAISO rules
      return Math.min(1.2, Math.max(0.8, actualPreAvg / histAvg));
    }

    // ── Calculate each standard method ──────────────────────────────────────

    function calcStandardMethod(methodKey) {
      const cfg = { excludeWeekends: true, excludeHolidays: true, dayTypes: 'weekday', lookback, lpa: false };
      return eventReadings.map(r => {
        const d    = new Date(r.interval_start);
        const tKey = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
        const pool = filterDays(byTimeKey[tKey] || [], cfg);
        const vals = pool.map(e => e.kw).filter(v => v != null).sort((a,b) => b-a);
        const actualKw = r.kw ?? null;

        let blKw = null;
        if (methodKey === 'caiso_10of10') {
          const top10Days = selectDays(pool, 'high_x_of_y', 10, 10, 0, 0);
          const sel = pool.filter(e => top10Days.has(e.dayStr)).map(e => e.kw).filter(v=>v!=null);
          blKw = sel.length ? sel.reduce((s,v)=>s+v,0)/sel.length : null;
          if (blKw) blKw *= computeLPA({...cfg, lpa:true, lpaHours:2}, tKey);
        } else if (methodKey === 'pjm_4of5' || methodKey === 'aemo_4of5' || methodKey === 'krec_max4of5') {
          const top4Days = selectDays(pool, 'high_x_of_y', 4, 5, 0, 0);
          const sel = pool.filter(e => top4Days.has(e.dayStr)).map(e => e.kw).filter(v=>v!=null);
          blKw = sel.length ? sel.reduce((s,v)=>s+v,0)/sel.length : null;
        } else if (methodKey === 'nyiso_10of10') {
          const top10Days = selectDays(pool, 'high_x_of_y', 10, 10, 0, 0);
          const sel = pool.filter(e => top10Days.has(e.dayStr)).map(e => e.kw).filter(v=>v!=null);
          blKw = sel.length ? sel.reduce((s,v)=>s+v,0)/sel.length : null;
        } else if (methodKey === 'bl_5of10') {
          // Mid 5-of-10: drop top 3 and bottom 2
          const allDays = selectDays(pool, 'high_x_of_y', 10, 10, 3, 2);
          const sel = pool.filter(e => allDays.has(e.dayStr)).map(e => e.kw).filter(v=>v!=null);
          blKw = sel.length ? sel.reduce((s,v)=>s+v,0)/sel.length : null;
        } else if (methodKey === 'bl_3of10') {
          const top3Days = selectDays(pool, 'high_x_of_y', 3, 10, 0, 0);
          const sel = pool.filter(e => top3Days.has(e.dayStr)).map(e => e.kw).filter(v=>v!=null);
          blKw = sel.length ? sel.reduce((s,v)=>s+v,0)/sel.length : null;
        } else if (methodKey === 'isone_ema') {
          // Exponential: 90% prior day + 10% current (simplified to weighted recent avg)
          const sorted = pool.sort((a,b) => b.date - a.date);
          let ema = null;
          sorted.forEach(e => { ema = ema === null ? e.kw : 0.9*ema + 0.1*e.kw; });
          blKw = ema;
        } else if (methodKey === 'bl_7day') {
          const sevenDaysAgo = new Date(eventStart.getTime() - 7*86400000);
          const recent = pool.filter(e => e.date >= sevenDaysAgo).map(e => e.kw).filter(v=>v!=null);
          blKw = recent.length ? recent.reduce((s,v)=>s+v,0)/recent.length : null;
        } else if (methodKey === 'bl_30day') {
          blKw = vals.length ? vals.reduce((s,v)=>s+v,0)/vals.length : null;
        }

        return { time: d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}), blKw, actualKw };
      });
    }

    // ── Calculate custom baselines ───────────────────────────────────────────

    function calcCustomBaseline(bl) {
      return eventReadings.map(r => {
        const d    = new Date(r.interval_start);
        const tKey = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
        const pool = filterDays(byTimeKey[tKey] || [], bl);
        const actualKw = r.kw ?? null;

        let blKw = null;
        if (bl.method === 'avg_all') {
          const vals = pool.map(e=>e.kw).filter(v=>v!=null);
          blKw = vals.length ? vals.reduce((s,v)=>s+v,0)/vals.length : null;
        } else if (bl.method === 'ema') {
          const sorted = pool.sort((a,b)=>b.date-a.date);
          let ema = null;
          sorted.forEach(e => { ema = ema===null ? e.kw : 0.9*ema + 0.1*e.kw; });
          blKw = ema;
        } else {
          const selectedDays = selectDays(pool, bl.method, bl.x, bl.y, bl.trimHigh, bl.trimLow);
          const sel = pool.filter(e=>selectedDays.has(e.dayStr)).map(e=>e.kw).filter(v=>v!=null);
          blKw = sel.length ? sel.reduce((s,v)=>s+v,0)/sel.length : null;
        }

        if (blKw && bl.lpa) blKw *= computeLPA(bl, tKey);

        return { time: d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}), blKw, actualKw };
      });
    }

    // ── Run all enabled methods ──────────────────────────────────────────────

    _blResults = {};
    _blActual  = eventReadings.map(r => ({
      time:     new Date(r.interval_start).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),
      fullTime: new Date(r.interval_start),
      kw:       r.kw ?? null
    }));

    const enabledStandard = BL_STANDARD_METHODS.filter(m => document.getElementById(`bl-std-${m.key}`)?.checked);
    enabledStandard.forEach(m => { _blResults[m.key] = calcStandardMethod(m.key); });
    _blCustomBaselines.forEach(bl => { _blResults[bl.id] = calcCustomBaseline(bl); });

    _amiBaselineData = { meterUid, eventStart, eventEnd, lookback };

    // ── Render ───────────────────────────────────────────────────────────────
    const rangeDays = document.getElementById('bl-chart-range')?.value || 'all';
    blRenderChart(enabledStandard, rangeDays);
    blRenderKPIs(enabledStandard);
    blRenderTable(enabledStandard);

    const totalMethods = enabledStandard.length + _blCustomBaselines.length;
    if (statusEl) statusEl.textContent = `${eventReadings.length} intervals | ${histReadings.length} hist readings | ${totalMethods} methods`;

  } catch(e) {
    if (statusEl) statusEl.textContent = `Error: ${e.message}`;
    console.error('amiRunBaseline:', e);
  }
}

// ── Render Chart ──────────────────────────────────────────────────────────────

function blRenderChart(enabledStandard, rangeDays) {
  if (_amiBaselineChart) { _amiBaselineChart.destroy(); _amiBaselineChart = null; }
  const ctx = document.getElementById('bl-chart')?.getContext('2d');
  if (!ctx) return;

  // Filter indices by display range
  let indices = _blActual.map((_,i)=>i);
  if (rangeDays && rangeDays !== 'all') {
    const cutoff = new Date(_blActual[_blActual.length-1]?.fullTime || new Date());
    cutoff.setDate(cutoff.getDate() - parseInt(rangeDays));
    indices = _blActual.map((r,i)=>({r,i})).filter(({r})=>r.fullTime>=cutoff).map(({i})=>i);
  }

  const labels = indices.map(i => _blActual[i].time);
  const sliceActual = i => _blActual[i]?.kw?.toFixed(3);
  const sliceResult = (key, i) => (_blResults[key]||[])[i]?.blKw?.toFixed(3);

  const datasets = [
    {
      label: 'Actual (event)',
      data:  indices.map(sliceActual),
      borderColor: '#6B7280', backgroundColor: 'rgba(107,114,128,0.1)',
      borderWidth: 2.5, pointRadius: indices.length > 200 ? 0 : 2, fill: true, tension: 0.2,
      order: 0
    },
    ...enabledStandard.map((m,i) => ({
      label: m.label,
      data:  indices.map(idx => sliceResult(m.key, idx)),
      borderColor: m.color, backgroundColor: m.color + '10',
      borderWidth: 2, pointRadius: 0, fill: false, tension: 0.3,
      borderDash: i > 4 ? [4,3] : undefined,
      order: i+1
    })),
    ..._blCustomBaselines.map((bl,i) => ({
      label: bl.name,
      data:  indices.map(idx => sliceResult(bl.id, idx)),
      borderColor: bl.color, backgroundColor: bl.color + '15',
      borderWidth: 2, pointRadius: 0, fill: false, tension: 0.3,
      borderDash: [6,2],
      order: enabledStandard.length + i + 1
    }))
  ];

  _amiBaselineChart = new Chart(ctx, {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: { callbacks: { label: ctx => `${ctx.dataset.label}: ${ctx.parsed.y!=null?Number(ctx.parsed.y).toFixed(3)+' kW':'—'}` } }
      },
      scales: {
        x: { ticks: { font:{size:10}, maxTicksLimit:16 } },
        y: { title: { display:true, text:'kW', font:{size:11} }, beginAtZero: true }
      }
    }
  });

  blRenderLegendToggles(datasets);
}

function blUpdateChartRange() {
  if (!_amiBaselineData || !Object.keys(_blResults).length) return;
  const rangeDays = document.getElementById('bl-chart-range')?.value || 'all';
  const enabledStandard = BL_STANDARD_METHODS.filter(m => _blResults[m.key]);
  blRenderChart(enabledStandard, rangeDays);
}

function blRenderLegendToggles(datasets) {
  const el = document.getElementById('bl-legend-toggles');
  if (!el) return;
  el.innerHTML = datasets.map((ds,i) => `
    <button onclick="blToggleDataset(${i})" id="bl-toggle-${i}"
      style="display:flex;align-items:center;gap:5px;padding:3px 8px;border-radius:8px;border:1.5px solid ${ds.borderColor};background:${ds.borderColor}18;cursor:pointer;font-size:10px;color:${ds.borderColor};font-weight:600;">
      <span style="width:8px;height:8px;border-radius:50%;background:${ds.borderColor};"></span>
      ${ds.label}
    </button>`).join('');
}

function blToggleDataset(index) {
  if (!_amiBaselineChart) return;
  const meta = _amiBaselineChart.getDatasetMeta(index);
  meta.hidden = !meta.hidden;
  _amiBaselineChart.update();
  const btn = document.getElementById(`bl-toggle-${index}`);
  if (btn) btn.style.opacity = meta.hidden ? '0.35' : '1';
}

function amiUpdateBaselineChart() { /* kept for compat — now using toggle buttons */ }

// ── Render KPIs ───────────────────────────────────────────────────────────────

function blRenderKPIs(enabledStandard) {
  const el = document.getElementById('bl-kpi-grid');
  if (!el) return;
  const avgKw = arr => { const v=arr.filter(r=>r.kw!=null||r.blKw!=null); return v.length ? v.reduce((s,r)=>s+(r.kw??r.blKw??0),0)/v.length : null; };
  const actualAvg = _blActual.reduce((s,r,_,a)=>s+(r.kw??0)/a.length,0);

  const allMethods = [
    ...enabledStandard.map(m => ({ label: m.label, color: m.color, key: m.key })),
    ..._blCustomBaselines.map(b => ({ label: b.name, color: b.color, key: b.id }))
  ];

  el.innerHTML = allMethods.map(m => {
    const results  = _blResults[m.key] || [];
    const blAvg    = results.reduce((s,r,_,a)=>s+(r.blKw??0)/a.length,0);
    const reduction = Math.max(0, blAvg - actualAvg);
    const pct       = blAvg > 0 ? (reduction/blAvg*100) : 0;
    return `<div class="sched-card" style="padding:10px;border-left:3px solid ${m.color};">
      <div style="font-size:10px;color:var(--text-hint);margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${m.label}">${m.label}</div>
      <div style="font-size:18px;font-weight:700;color:${m.color};">${blAvg.toFixed(2)} kW</div>
      <div style="font-size:10px;color:var(--text-hint);margin-top:3px;">
        ${reduction>0 ? `<span style="color:var(--green-dark);font-weight:600;">${reduction.toFixed(2)} kW saved (${pct.toFixed(1)}%)</span>` : 'No reduction'}
      </div>
    </div>`;
  }).join('');
}

// ── Render Table ──────────────────────────────────────────────────────────────

function blRenderTable(enabledStandard) {
  const thead = document.getElementById('bl-table-head');
  const tbody = document.getElementById('bl-table-body');
  const card  = document.getElementById('bl-table-card');
  if (!thead || !tbody) return;

  const allMethods = [
    ...enabledStandard.map(m => ({ label: m.label, color: m.color, key: m.key })),
    ..._blCustomBaselines.map(b => ({ label: b.name, color: b.color, key: b.id }))
  ];

  thead.innerHTML = `<tr>
    <th style="text-align:left;padding:5px 8px;border-bottom:0.5px solid var(--border-md);color:var(--text-hint);position:sticky;top:0;background:var(--surface);">Time</th>
    <th style="text-align:right;padding:5px 8px;border-bottom:0.5px solid var(--border-md);color:#6B7280;position:sticky;top:0;background:var(--surface);">Actual kW</th>
    ${allMethods.map(m=>`<th style="text-align:right;padding:5px 8px;border-bottom:0.5px solid var(--border-md);color:${m.color};position:sticky;top:0;background:var(--surface);white-space:nowrap;">${m.label}</th>`).join('')}
    <th style="text-align:right;padding:5px 8px;border-bottom:0.5px solid var(--border-md);color:var(--green-dark);position:sticky;top:0;background:var(--surface);">Best Reduction</th>
  </tr>`;

  const intervals = _blActual.length;
  tbody.innerHTML = Array.from({length: intervals}, (_,i) => {
    const actual = _blActual[i]?.kw;
    const blVals = allMethods.map(m => (_blResults[m.key]||[])[i]?.blKw);
    const reductions = blVals.map(b => b!=null && actual!=null ? Math.max(0,b-actual) : null);
    const best = reductions.filter(r=>r!=null).length ? Math.max(...reductions.filter(r=>r!=null)) : null;
    const bestLabel = best!=null ? best.toFixed(3)+' kW' : '—';
    return `<tr>
      <td style="padding:4px 8px;border-bottom:0.5px solid var(--border);font-size:11px;">${_blActual[i]?.time||'—'}</td>
      <td style="padding:4px 8px;border-bottom:0.5px solid var(--border);text-align:right;font-size:11px;color:#6B7280;font-weight:600;">${actual?.toFixed(3)??'—'}</td>
      ${blVals.map((b,j)=>`<td style="padding:4px 8px;border-bottom:0.5px solid var(--border);text-align:right;font-size:11px;color:${allMethods[j].color};">${b?.toFixed(3)??'—'}</td>`).join('')}
      <td style="padding:4px 8px;border-bottom:0.5px solid var(--border);text-align:right;font-size:11px;color:var(--green-dark);">${bestLabel}</td>
    </tr>`;
  }).join('');

  if (card) card.style.display = '';
}

// ── Export ────────────────────────────────────────────────────────────────────

function amiExportBaselineReport() {
  if (!_amiBaselineData || !Object.keys(_blResults).length) { alert('Run calculation first.'); return; }
  const { meterUid, eventStart, eventEnd, lookback } = _amiBaselineData;

  const allMethods = [
    ...BL_STANDARD_METHODS.filter(m => _blResults[m.key]).map(m=>({label:m.label, key:m.key, iso:m.iso})),
    ..._blCustomBaselines.map(b=>({label:b.name, key:b.id, iso:'Custom'}))
  ];

  const fmt = v => v!=null ? v.toFixed(3).padStart(8) : '       —';
  const avgKw = key => {
    const v = (_blResults[key]||[]).filter(r=>r.blKw!=null);
    return v.length ? v.reduce((s,r)=>s+r.blKw,0)/v.length : null;
  };
  const actualAvg = _blActual.filter(r=>r.kw!=null).reduce((s,r,_,a)=>s+r.kw/a.length,0);

  const lines = [
    'AMI BASELINE CALCULATOR REPORT',
    `Generated: ${new Date().toLocaleString()}`,
    '='.repeat(80),
    '',
    'PARAMETERS',
    '-'.repeat(40),
    `Meter:           ${meterUid}`,
    `Event Window:    ${eventStart.toLocaleString()} — ${eventEnd.toLocaleString()}`,
    `Lookback:        ${lookback} days`,
    `Intervals:       ${_blActual.length}`,
    '',
    'METHOD SUMMARY',
    '-'.repeat(60),
    `${'Method'.padEnd(25)} ${'ISO/Source'.padEnd(10)} ${'Avg kW'.padEnd(10)} ${'Reduction'.padEnd(10)} ${'Pct'}`,
    '-'.repeat(60),
    ...allMethods.map(m => {
      const avg = avgKw(m.key);
      const red = avg!=null ? Math.max(0,avg-actualAvg) : null;
      const pct = avg!=null && avg>0 ? (red/avg*100) : null;
      return `${m.label.padEnd(25)} ${(m.iso||'').padEnd(10)} ${avg!=null?avg.toFixed(3).padEnd(10):'—'.padEnd(10)} ${red!=null?red.toFixed(3).padEnd(10):'—'.padEnd(10)} ${pct!=null?pct.toFixed(1)+'%':'—'}`;
    }),
    `${'Actual (event)'.padEnd(25)} ${''.padEnd(10)} ${actualAvg.toFixed(3)}`,
    '',
    'INTERVAL DETAIL',
    '-'.repeat(80),
    `Time     | Actual   | ${allMethods.map(m=>m.label.slice(0,10).padEnd(10)).join(' | ')}`,
    '-'.repeat(80),
    ...Array.from({length:_blActual.length},(_,i)=>
      `${(_blActual[i]?.time||'—').padEnd(8)} | ${fmt(_blActual[i]?.kw)} | ${allMethods.map(m=>fmt((_blResults[m.key]||[])[i]?.blKw)).join(' | ')}`
    ),
    '',
    '='.repeat(80),
    `Load Control Dashboard — Baseline Calculator | Meter: ${meterUid}`,
  ].join('\n');

  const blob = new Blob([lines],{type:'text/plain'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `Baseline_Report_${meterUid}_${eventStart.toISOString().split('T')[0]}.txt`;
  a.click();
  URL.revokeObjectURL(a.href);
}
